content:
`timescale 1ns / 1ps
module testbench;

// Inputs
reg clk;
reg rst_n, ctrl_en;
reg [9:0] tfr_cmd;
reg start_done, stop_done, restart_done;
reg mst_tx_shift_done, mst_rx_shift_done, mst_rx_shift_check_hold;
reg ack_det, bus_idle, arb_lost;
reg txfifo_empty, txfifo_empty_nodly;
reg pre_loaded_restart_bit, flush_txfifo;

// Outputs
wire load_tx_shifter, mst_tx_en, mst_rx_en;
wire start_en, restart_en, stop_en;
wire mstfsm_emptyfifo_hold_en, mstfsm_b2b_rxshift;
wire tx_byte_state, gen_7bit_addr_state, mstfsm_idle_state;
wire pop_tx_fifo_state, pop_tx_fifo_state_dly;
wire mst_rx_ack_nack, abrt_txdata_noack, abrt_7b_addr_noack;
wire gen_stop_state;

integer i, j;

altera_avalon_i2c_mstfsm uut (
    .clk(clk),
    .rst_n(rst_n),
    .ctrl_en(ctrl_en),
    .tfr_cmd(tfr_cmd),
    .start_done(start_done),
    .stop_done(stop_done),
    .restart_done(restart_done),
    .mst_tx_shift_done(mst_tx_shift_done),
    .mst_rx_shift_done(mst_rx_shift_done),
    .mst_rx_shift_check_hold(mst_rx_shift_check_hold),
    .ack_det(ack_det),
    .bus_idle(bus_idle),
    .arb_lost(arb_lost),
    .txfifo_empty(txfifo_empty),
    .txfifo_empty_nodly(txfifo_empty_nodly),
    .pre_loaded_restart_bit(pre_loaded_restart_bit),
    .flush_txfifo(flush_txfifo),
    .load_tx_shifter(load_tx_shifter),
    .mst_tx_en(mst_tx_en),
    .mst_rx_en(mst_rx_en),
    .start_en(start_en),
    .restart_en(restart_en),
    .stop_en(stop_en),
    .mstfsm_emptyfifo_hold_en(mstfsm_emptyfifo_hold_en),
    .mstfsm_b2b_rxshift(mstfsm_b2b_rxshift),
    .tx_byte_state(tx_byte_state),
    .gen_7bit_addr_state(gen_7bit_addr_state),
    .mstfsm_idle_state(mstfsm_idle_state),
    .pop_tx_fifo_state(pop_tx_fifo_state),
    .pop_tx_fifo_state_dly(pop_tx_fifo_state_dly),
    .mst_rx_ack_nack(mst_rx_ack_nack),
    .abrt_txdata_noack(abrt_txdata_noack),
    .abrt_7b_addr_noack(abrt_7b_addr_noack),
    .gen_stop_state(gen_stop_state)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [8*64-1:0] label;
    begin
        // One format literal: no C-style adjacent string concatenation.
        $display(
            "%0t %0s i=%0d j=%0d rst_n=%b ctrl_en=%b cmd=%h empty=%b empty_nodly=%b preload=%b load_tx_shifter=%b mst_tx_en=%b mst_rx_en=%b start_en=%b restart_en=%b stop_en=%b mstfsm_emptyfifo_hold_en=%b mstfsm_b2b_rxshift=%b tx_byte_state=%b gen_7bit_addr_state=%b mstfsm_idle_state=%b pop_tx_fifo_state=%b pop_tx_fifo_state_dly=%b mst_rx_ack_nack=%b abrt_txdata_noack=%b abrt_7b_addr_noack=%b gen_stop_state=%b",
            $time, label, i, j, rst_n, ctrl_en, tfr_cmd,
            txfifo_empty, txfifo_empty_nodly,
            pre_loaded_restart_bit, load_tx_shifter,
            mst_tx_en, mst_rx_en, start_en, restart_en, stop_en,
            mstfsm_emptyfifo_hold_en, mstfsm_b2b_rxshift,
            tx_byte_state, gen_7bit_addr_state, mstfsm_idle_state,
            pop_tx_fifo_state, pop_tx_fifo_state_dly,
            mst_rx_ack_nack, abrt_txdata_noack,
            abrt_7b_addr_noack, gen_stop_state
        );
    end
endtask

// Observe settled combinational response, then registered response.
task step;
    input [8*64-1:0] label;
    begin
        #1;
        observe(label);
        @(posedge clk);
        #1;
        observe(label);
    end
endtask

task defaults;
    begin
        ctrl_en = 0;
        tfr_cmd = 0;
        start_done = 0;
        stop_done = 0;
        restart_done = 0;
        mst_tx_shift_done = 0;
        mst_rx_shift_done = 0;
        mst_rx_shift_check_hold = 0;
        ack_det = 1;
        bus_idle = 1;
        arb_lost = 0;
        txfifo_empty = 1;
        txfifo_empty_nodly = 1;
        pre_loaded_restart_bit = 0;
        flush_txfifo = 0;
    end
endtask

task reset_dut;
    begin
        @(negedge clk);
        defaults;
        rst_n = 0;
        #1;
        observe("asynchronous reset");
        repeat (2) @(posedge clk);
        #1;
        rst_n = 1;
        step("reset released; disabled idle");
    end
endtask

// Return in the initial address phase with completion inputs low.
task address_phase;
    input direction;
    begin
        reset_dut;
        ctrl_en = 1;
        txfifo_empty = 0;
        tfr_cmd = {9'b0, direction};
        step("enable edge");
        step("start entry");
        step("start waiting");
        start_done = 1;
        step("start complete / FIFO pop");
        start_done = 0;
        step("initial address");
        step("address waiting");
    end
endtask

// Change command bit 0 after address completion to expose captured direction.
task data_phase;
    input direction;
    begin
        address_phase(direction);
        mst_tx_shift_done = 1;
        step("address ACK / FIFO pop");
        mst_tx_shift_done = 0;
        tfr_cmd = {2'b00, 7'b1010010, ~direction};
        step("data uses captured direction");
        step("data waiting");
    end
endtask

task command_sweep;
    input [8*64-1:0] label;
    integer k;
    begin
        for (k = 0; k < 16; k = k + 1) begin
            {pre_loaded_restart_bit, txfifo_empty,
             tfr_cmd[9], tfr_cmd[8]} = k;
            #1;
            observe(label);
            #1;
        end
        pre_loaded_restart_bit = 0;
        txfifo_empty = 0;
        tfr_cmd[9:8] = 0;
    end
endtask

task hold_qualification;
    integer k;
    begin
        txfifo_empty = 1;
        for (k = 0; k < 4; k = k + 1) begin
            {ack_det, tfr_cmd[8]} = k;
            #1;
            step("empty-FIFO hold qualification");
        end
        ack_det = 1;
        tfr_cmd[8] = 0;
    end
endtask

// Enter each missing reset-source phase using only top-level stimulus.
// Each path returns one time unit after a rising edge. The caller then
// asserts asynchronous reset at the following falling edge, before the
// next rising edge can advance a transient POP_TX_FIFO phase.
task reset_source_phase;
    input integer scenario;
    begin
        case (scenario)
            0: begin
                reset_dut;
                ctrl_en = 1;
                txfifo_empty = 1;
                step("reset target: PRE_START entry");
                step("reset target: PRE_START blocked");
            end

            1: begin
                address_phase(0);
                mst_tx_shift_done = 1;
                step("reset target: address ACK / POP_TX_FIFO");
                mst_tx_shift_done = 0;
                // No further rising edge before reset.
            end

            2: begin
                address_phase(0);
                mst_tx_shift_done = 1;
                step("reset setup: address ACK / FIFO pop");
                mst_tx_shift_done = 0;
                tfr_cmd[9] = 1;
                step("reset target: GEN_RESTART_7BIT entry");
                step("reset target: GEN_RESTART_7BIT waiting");
            end

            3: begin
                data_phase(0);
                txfifo_empty = 1;
                mst_tx_shift_done = 1;
                step("reset target: transmit BUS_HOLD entry");
                mst_tx_shift_done = 0;
                step("reset target: transmit BUS_HOLD waiting");
            end

            4: begin
                data_phase(1);
                txfifo_empty = 1;
                mst_rx_shift_check_hold = 1;
                mst_rx_shift_done = 1;
                step("reset target: receive BUS_HOLD entry");
                mst_rx_shift_check_hold = 0;
                mst_rx_shift_done = 0;
                step("reset target: receive BUS_HOLD waiting");
            end
        endcase
    end
endtask

initial begin
    rst_n = 0;
    i = 0;
    j = 0;
    defaults;

    #100;
    observe("initial reset");

    // Reset-visible combinational response and enable already high.
    command_sweep("ACK/NACK while reset asserted");
    ctrl_en = 1;
    txfifo_empty = 1;
    rst_n = 1;
    step("enable high at reset release");
    step("PRE_START blocked by empty FIFO");
    txfifo_empty = 0;
    bus_idle = 0;
    step("PRE_START blocked by busy bus");
    bus_idle = 1;
    flush_txfifo = 1;
    step("PRE_START blocked by flush");
    flush_txfifo = 0;
    step("PRE_START admitted");
    step("start waits for completion");
    reset_dut;
    command_sweep("ACK/NACK without receive hold");

    // Address hold in both directions, then repeated start and direction change.
    for (i = 0; i < 2; i = i + 1) begin
        #1;
        address_phase(i[0]);
        hold_qualification;
        mst_tx_shift_done = 1;
        step("address ACK with empty FIFO");
        mst_tx_shift_done = 0;
        step("address-origin bus hold");
        tfr_cmd[9] = 1;
        txfifo_empty = 0;
        step("release address hold / FIFO pop");
        step("restart command routing");
        step("repeated start waiting");
        tfr_cmd = {9'b0, ~i[0]};
        restart_done = 1;
        step("restart complete / new address");
        restart_done = 0;
        mst_tx_shift_done = 1;
        step("repeated address ACK");
        mst_tx_shift_done = 0;
        tfr_cmd[0] = i[0];
        step("new captured direction");
    end

    // Address NACK, including a simultaneous stop command.
    for (i = 0; i < 2; i = i + 1) begin
        #1;
        address_phase(i[0]);
        tfr_cmd[8] = i[0];
        ack_det = 0;
        step("address NACK before completion");
        mst_tx_shift_done = 1;
        step("address NACK abort pulse");
        mst_tx_shift_done = 0;
        step("address NACK stop waiting");
        stop_done = 1;
        step("address NACK stop complete");
    end

    // Write continuation, transmit hold, requested stop and NACK stop.
    for (i = 0; i < 2; i = i + 1) begin
        #1;
        data_phase(0);
        hold_qualification;
        txfifo_empty = 0;
        mst_tx_shift_done = 1;
        step("TX ACK continuation / FIFO pop");
        mst_tx_shift_done = 0;
        step("next TX byte");
        txfifo_empty = 1;
        mst_tx_shift_done = 1;
        step("TX ACK enters bus hold");
        mst_tx_shift_done = 0;
        step("TX bus hold waiting");
        txfifo_empty = 0;
        step("TX hold release / FIFO pop");
        step("TX resumes");
        ack_det = i[0];
        tfr_cmd[8] = i[0];
        step("TX stop condition before completion");
        mst_tx_shift_done = 1;
        step("TX NACK or acknowledged requested stop");
        mst_tx_shift_done = 0;
        step("stop waiting");
        txfifo_empty_nodly = i[0];
        stop_done = 1;
        step("stop complete / queued or empty");
        stop_done = 0;
        step("post-stop routing");
    end

    // Receive continuation, no-hold empty completion, and stop priority.
    data_phase(1);
    hold_qualification;
    mst_rx_shift_done = 1;
    step("RX done with empty FIFO and no hold request");
    mst_rx_shift_done = 0;
    txfifo_empty = 0;
    step("RX still waiting");
    mst_rx_shift_done = 1;
    step("RX continuation / FIFO pop");
    mst_rx_shift_done = 0;
    step("next RX byte");
    tfr_cmd[8] = 1;
    mst_rx_shift_check_hold = 1;
    step("RX stop suppresses hold request before done");
    mst_rx_shift_done = 1;
    step("RX requested stop");
    mst_rx_shift_done = 0;
    mst_rx_shift_check_hold = 0;
    step("RX stop waiting");
    stop_done = 1;
    step("RX stop complete / PRE_IDLE");
    stop_done = 0;
    step("enabled PRE_IDLE waiting");
    ctrl_en = 0;
    txfifo_empty_nodly = 0;
    txfifo_empty = 1;
    step("queued work takes priority over disable");
    step("queued PRE_START waits for immediate FIFO");
    txfifo_empty = 0;
    step("queued transaction start");

    // Stored receive hold: all restart/stop combinations.
    for (i = 0; i < 4; i = i + 1) begin
        #1;
        data_phase(1);
        txfifo_empty = 1;
        mst_rx_shift_check_hold = 1;
        mst_rx_shift_done = 1;
        step("RX hold setting takes priority over clearing");
        mst_rx_shift_check_hold = 0;
        mst_rx_shift_done = 0;
        step("receive-oriented bus hold");
        txfifo_empty = 0;
        tfr_cmd[9:8] = i[1:0];
        step("receive hold release / FIFO pop");
        step("stored hold routes to RX");
        step("delayed back-to-back RX indication");
        command_sweep("ACK/NACK with stored receive hold");
        tfr_cmd[9:8] = i[1:0];
        mst_rx_shift_done = 1;
        step("held RX completion / clear hold or restart");
        mst_rx_shift_done = 0;
        step("after held completion");
        mst_rx_shift_done = 1;
        step("RX completion after hold cleared");
        mst_rx_shift_done = 0;
        restart_done = 1;
        step("complete repeated start if selected");
        restart_done = 0;
    end

    // Completion can clear the hold flag while still in BUS_HOLD.
    data_phase(1);
    txfifo_empty = 1;
    mst_rx_shift_check_hold = 1;
    step("RX enters hold");
    mst_rx_shift_check_hold = 0;
    mst_rx_shift_done = 1;
    step("clear receive hold while FIFO remains empty");
    mst_rx_shift_done = 0;
    step("hold enables after flag clearing");
    txfifo_empty = 0;
    step("release cleared hold");
    step("captured read direction resumes");

    // Arbitration priority in address, TX and RX; flush and enable routing.
    for (i = 0; i < 3; i = i + 1) begin
        #1;
        case (i)
            0: address_phase(0);
            1: data_phase(0);
            2: data_phase(1);
        endcase
        arb_lost = 1;
        ack_det = 0;
        tfr_cmd[9:8] = 2'b11;
        mst_tx_shift_done = 1;
        mst_rx_shift_done = 1;
        mst_rx_shift_check_hold = 1;
        txfifo_empty = 1;
        step("arbitration overrides competing completion");
        arb_lost = 0;
        mst_tx_shift_done = 0;
        mst_rx_shift_done = 0;
        mst_rx_shift_check_hold = 0;
        step("arbitration PRE_IDLE waiting");
        txfifo_empty_nodly = 0;
        flush_txfifo = 1;
        step("flush blocks queued PRE_IDLE work");
        ctrl_en = 0;
        step("disabled with flushed work returns IDLE");
        flush_txfifo = 0;
        txfifo_empty = 0;
        step("queued work alone does not launch IDLE");
        ctrl_en = 1;
        step("fresh enable edge launches");
        step("start after fresh enable edge");
    end

    // Flush also blocks admission following a queued stop completion.
    data_phase(0);
    tfr_cmd[8] = 1;
    mst_tx_shift_done = 1;
    step("stop before queued flushed work");
    mst_tx_shift_done = 0;
    txfifo_empty_nodly = 0;
    flush_txfifo = 1;
    stop_done = 1;
    step("queued stop completion");
    stop_done = 0;
    step("post-stop PRE_START blocked by flush");
    flush_txfifo = 0;
    step("post-stop flush released");

    // Asynchronous recovery with receive hold and history flags active.
    data_phase(1);
    txfifo_empty = 1;
    mst_rx_shift_check_hold = 1;
    step("receive hold before asynchronous reset");
    mst_rx_shift_check_hold = 0;
    txfifo_empty = 0;
    step("release hold before reset");
    step("held receive before reset");
    step("back-to-back history before reset");
    reset_dut;
    ctrl_en = 1;
    txfifo_empty = 0;
    step("launch after active reset");
    step("start after active reset");
    start_done = 1;
    step("FIFO pop after active reset");
    start_done = 0;
    step("initial address restored after active reset");

    // Supplement the existing suite with the missing reset transitions.
    // j=0: PRE_START -> IDLE
    // j=1: POP_TX_FIFO -> IDLE
    // j=2: GEN_RESTART_7BIT -> IDLE
    // j=3: transmit-oriented BUS_HOLD -> IDLE
    // j=4: receive-oriented BUS_HOLD -> IDLE
    for (j = 0; j < 5; j = j + 1) begin
        #1;
        reset_source_phase(j);
        observe("target phase immediately before reset");
        reset_dut;
        step("disabled IDLE after targeted reset");

        // Exercise ordinary launch again after clearing phase/history flags.
        ctrl_en = 1;
        txfifo_empty = 0;
        step("targeted reset recovery: enable edge");
        step("targeted reset recovery: start entry");
        start_done = 1;
        step("targeted reset recovery: FIFO pop");
        start_done = 0;
        step("targeted reset recovery: initial address");
    end

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

// Inputs
reg clk;
reg rst_n;
reg mst_tx_scl_high_cnt_complete;
reg mst_tx_scl_low_cnt_complete;
reg mst_tx_en;
reg scl_int;
reg mstfsm_emptyfifo_hold_en;
reg load_tx_shifter;
reg [9:0] tx_fifo_data_in;
reg tx_byte_state;
reg gen_7bit_addr_state;

// Outputs
wire mst_tx_scl_high_cnt_en;
wire mst_tx_scl_low_cnt_en;
wire mst_tx_chk_ack;
wire mst_tx_shift_done;
wire mst_tx_scl_out;
wire mst_tx_sda_out;
wire load_mst_tx_scl_high_cnt;
wire load_mst_tx_scl_low_cnt;
wire [9:0] tx_shifter;
wire mst_txdata_phase;

integer test_id, i, j, action, stage;

altera_avalon_i2c_txshifter uut (
    .clk(clk),
    .rst_n(rst_n),
    .mst_tx_scl_high_cnt_complete(mst_tx_scl_high_cnt_complete),
    .mst_tx_scl_low_cnt_complete(mst_tx_scl_low_cnt_complete),
    .mst_tx_en(mst_tx_en),
    .scl_int(scl_int),
    .mstfsm_emptyfifo_hold_en(mstfsm_emptyfifo_hold_en),
    .load_tx_shifter(load_tx_shifter),
    .tx_fifo_data_in(tx_fifo_data_in),
    .tx_byte_state(tx_byte_state),
    .gen_7bit_addr_state(gen_7bit_addr_state),
    .mst_tx_scl_high_cnt_en(mst_tx_scl_high_cnt_en),
    .mst_tx_scl_low_cnt_en(mst_tx_scl_low_cnt_en),
    .mst_tx_chk_ack(mst_tx_chk_ack),
    .mst_tx_shift_done(mst_tx_shift_done),
    .mst_tx_scl_out(mst_tx_scl_out),
    .mst_tx_sda_out(mst_tx_sda_out),
    .load_mst_tx_scl_high_cnt(load_mst_tx_scl_high_cnt),
    .load_mst_tx_scl_low_cnt(load_mst_tx_scl_low_cnt),
    .tx_shifter(tx_shifter),
    .mst_txdata_phase(mst_txdata_phase)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
begin
    $display("case=%0d t=%0t rst_n=%b en=%b sel=%b%b high_en=%b low_en=%b ack=%b done=%b scl=%b sda=%b load_high=%b load_low=%b shifter=%03h data_phase=%b",
        test_id, $time, rst_n, mst_tx_en,
        tx_byte_state, gen_7bit_addr_state,
        mst_tx_scl_high_cnt_en, mst_tx_scl_low_cnt_en,
        mst_tx_chk_ack, mst_tx_shift_done,
        mst_tx_scl_out, mst_tx_sda_out,
        load_mst_tx_scl_high_cnt, load_mst_tx_scl_low_cnt,
        tx_shifter, mst_txdata_phase);
end
endtask

task clocks;
    input integer count;
    integer n;
begin
    for (n = 0; n < count; n = n + 1) begin
        @(posedge clk);
        #1;
        observe;
    end
end
endtask

task initialize_inputs;
begin
    mst_tx_scl_high_cnt_complete = 0;
    mst_tx_scl_low_cnt_complete = 0;
    mst_tx_en = 0;
    scl_int = 1;
    mstfsm_emptyfifo_hold_en = 0;
    load_tx_shifter = 0;
    tx_fifo_data_in = 0;
    tx_byte_state = 0;
    gen_7bit_addr_state = 0;
end
endtask

task reset_case;
begin
    initialize_inputs;
    #2;
    rst_n = 0;
    #1;
    observe;
    clocks(2);
    rst_n = 1;
    clocks(1);
end
endtask

task load_word;
    input [9:0] value;
begin
    tx_fifo_data_in = value;
    load_tx_shifter = 1;
    clocks(1);
    load_tx_shifter = 0;
    clocks(1);
end
endtask

// Each invocation begins in the load phase. Nine periods include ACK.
task periods;
    input integer count;
    input integer direct_high;
    input integer falling_scl;
    integer n;
begin
    for (n = 0; n < count; n = n + 1) begin
        #1;
        scl_int = 0;
        if (direct_high == 0) begin
            clocks(2);
            mst_tx_scl_low_cnt_complete = 1;
            clocks(1);
        end
        clocks(3);
        scl_int = 1;
        clocks(2);
        mst_tx_scl_low_cnt_complete = direct_high;
        if (falling_scl != 0)
            scl_int = 0;
        else
            mst_tx_scl_high_cnt_complete = 1;
        clocks(1);
        mst_tx_scl_high_cnt_complete = 0;
    end
end
endtask

task start_transfer;
    input integer direct_high;
begin
    mst_tx_scl_low_cnt_complete = direct_high;
    mst_tx_scl_high_cnt_complete = 0;
    scl_int = 0;
    mst_tx_en = 1;
    clocks(1);
end
endtask

// Fixed stimulus schedules establish interruption points without polling.
task prepare_interruption;
    input integer location;
begin
    reset_case;
    tx_byte_state = 1;
    load_word(10'h2a5);
    if (location != 0) begin
        start_transfer(0);
        case (location)
            1: clocks(0);
            2: clocks(2);
            3: begin
                clocks(2);
                mst_tx_scl_low_cnt_complete = 1;
                clocks(3);
                scl_int = 1;
                clocks(2);
            end
            4, 5: begin
                mstfsm_emptyfifo_hold_en = (location == 5);
                periods(9, 0, 0);
                clocks(2);
            end
            6: begin
                periods(8, 0, 0);
                clocks(2);
            end
        endcase
    end
end
endtask

initial begin
    rst_n = 1;
    test_id = 0;
    initialize_inputs;

    // Wait 100 ns for global reset to finish.
    #100;

    // Reset, consecutive loading, retention, and active source changes.
    reset_case;
    load_word(10'h000);
    load_tx_shifter = 1;
    tx_fifo_data_in = 10'h3ff;
    clocks(1);
    tx_fifo_data_in = 10'h1a5;
    clocks(1);
    load_tx_shifter = 0;
    tx_fifo_data_in = 10'h000;
    clocks(2);
    tx_byte_state = 1;
    start_transfer(0);
    clocks(2);
    load_tx_shifter = 1;
    tx_fifo_data_in = 10'h25a;
    clocks(1);
    tx_fifo_data_in = 10'h3ff;
    clocks(1);
    load_tx_shifter = 0;
    tx_fifo_data_in = 0;
    clocks(2);
    tx_byte_state = 0;
    clocks(1);
    gen_7bit_addr_state = 1;
    clocks(1);
    tx_byte_state = 1;
    clocks(1);

    // Four source selections, two alternating patterns, both timing paths.
    for (i = 0; i < 4; i = i + 1) begin
        #1;
        for (j = 0; j < 2; j = j + 1) begin
            #1;
            test_id = 10 + 2*i + j;
            reset_case;
            tx_byte_state = i % 2;
            gen_7bit_addr_state = i / 2;
            load_word((i << 8) | (j == 0 ? 8'ha5 : 8'h5a));
            mstfsm_emptyfifo_hold_en = j;
            start_transfer(j);
            periods(9, j, i / 2);
            clocks(3);
            mstfsm_emptyfifo_hold_en = 0;
            clocks(2);
            mst_tx_en = 0;
            clocks(2);

            // Restart from idle without resetting the retained word.
            start_transfer(0);
            periods(9, 0, 0);
            clocks(2);
            mst_tx_en = 0;
            clocks(2);
        end
    end

    // Boundary byte values and upper-bit independence in byte mode.
    for (i = 0; i < 6; i = i + 1) begin
        #1;
        test_id = 30 + i;
        reset_case;
        tx_byte_state = 1;
        case (i)
            0: load_word(10'h000);
            1: load_word(10'h3ff);
            default: load_word(((i - 2) << 8) | 8'ha5);
        endcase
        start_transfer(0);
        periods(9, 0, 0);
        clocks(3);
        mst_tx_en = 0;
        clocks(2);
    end

    // Disable/reset in idle, load, low, high, done, hold, and ACK-low.
    for (action = 0; action < 2; action = action + 1) begin
        #1;
        for (stage = 0; stage < 7; stage = stage + 1) begin
            #1;
            test_id = 50 + 10*action + stage;
            prepare_interruption(stage);
            if (action == 0) begin
                mst_tx_en = 0;
                clocks(3);
            end
            else begin
                load_tx_shifter = 1;
                tx_fifo_data_in = 10'h3ff;
                #2;
                rst_n = 0;
                #1;
                observe;
                clocks(2);
                initialize_inputs;
                rst_n = 1;
                clocks(3);
            end
        end
    end

    $display("===========End===========");
    $finish;
end

endmodule

