begin
    $display("time=%0t ack_OUT_req=%b ack_ic_req=%b ack_dc_req=%b ack_mem_req=%b select=%03b",
             $time, ack_OUT_req, ack_ic_req, ack_dc_req, ack_mem_req, select);
end
endtask

initial begin
    reset_dut;

    // Test Case 1: idle, not ready, and no requests
    OUT_req_rdy = 1'b0;
    #1 observe;
    OUT_req_rdy = 1'b1;
    #1 observe;

    // Test Case 2: requests present while output is stalled
    v_ic_req  = 1'b1;
    v_dc_req  = 1'b1;
    v_mem_req = 1'b1;
    OUT_req_rdy = 1'b0;
    #1 observe;

    // Test Case 3: synchronous reset while an active transfer is present
    reset_dut;
    OUT_req_rdy = 1'b1;
    v_dc_req = 1'b1;
    dc_req_ctrl = 2'b00;
    #1 observe;
    @(posedge clk);
    #1 observe;
    rst = 1'b1;
    #1 observe;
    @(posedge clk);
    #1 observe;
    rst = 1'b0;

    // Test Case 4: instruction-cache priority and active ownership
    reset_dut;
    OUT_req_rdy = 1'b1;
    v_ic_req  = 1'b1;
    v_dc_req  = 1'b1;
    v_mem_req = 1'b1;
    ic_req_ctrl = 2'b00;
    #1 observe;
    @(posedge clk);
    #1 observe;

    v_ic_req = 1'b1;
    v_dc_req = 1'b0;
    v_mem_req = 1'b1;
    OUT_req_rdy = 1'b0;
    ic_req_ctrl = 2'b11;
    #1 observe;
    @(posedge clk);
    #1 observe;

    OUT_req_rdy = 1'b1;
    #1 observe;
    @(posedge clk);
    v_ic_req = 1'b0;
    v_dc_req = 1'b0;
    v_mem_req = 1'b0;
    #1 observe;

    // Test Case 5: sole data-cache request, non-terminal and terminal beats
    reset_dut;
    OUT_req_rdy = 1'b1;
    v_dc_req = 1'b1;
    dc_req_ctrl = 2'b00;
    #1 observe;
    @(posedge clk);
    #1 observe;
    dc_req_ctrl = 2'b11;
    #1 observe;
    @(posedge clk);
    v_dc_req = 1'b0;
    #1 observe;

    // Test Case 6: sole memory request, non-terminal and terminal beats
    reset_dut;
    OUT_req_rdy = 1'b1;
    v_mem_req = 1'b1;
    mem_req_ctrl = 2'b00;
    #1 observe;
    @(posedge clk);
    #1 observe;
    mem_req_ctrl = 2'b11;
    #1 observe;
    @(posedge clk);
    v_mem_req = 1'b0;
    #1 observe;

    // Test Case 7: data-cache/memory tie alternation, initial grant is memory
    reset_dut;
    OUT_req_rdy = 1'b1;
    v_dc_req  = 1'b1;
    v_mem_req = 1'b1;
    mem_req_ctrl = 2'b11;
    #1 observe;
    @(posedge clk);
    #1 observe;
    @(posedge clk);
    #1 observe;

    dc_req_ctrl = 2'b11;
    mem_req_ctrl = 2'b00;
    #1 observe;
    @(posedge clk);
    #1 observe;

    // Test Case 8: uncontested and instruction-cache grants do not update tie preference
    reset_dut;
    OUT_req_rdy = 1'b1;
    v_dc_req = 1'b1;
    dc_req_ctrl = 2'b11;
    #1 observe;
    @(posedge clk);
    #1 observe;
    @(posedge clk);
    #1 observe;

    v_ic_req  = 1'b1;
    v_dc_req  = 1'b1;
    v_mem_req = 1'b1;
    ic_req_ctrl = 2'b11;
    #1 observe;
    @(posedge clk);
    #1 observe;
    @(posedge clk);
    #1 observe;

    v_ic_req = 1'b0;
    v_dc_req = 1'b1;
    v_mem_req = 1'b1;
    mem_req_ctrl = 2'b11;
    #1 observe;
    @(posedge clk);
    #1 observe;

    // Test Case 9: active ownership lock, stalled terminal beat, then completion
    reset_dut;
    OUT_req_rdy = 1'b1;
    v_dc_req = 1'b1;
    dc_req_ctrl = 2'b00;
    #1 observe;
    @(posedge clk);
    #1 observe;

