    v_dc_req = 1'b0;
    v_ic_req = 1'b1;
    v_mem_req = 1'b1;
    dc_req_ctrl = 2'b11;
    #1 observe;
    @(posedge clk);
    #1 observe;

    OUT_req_rdy = 1'b1;
    #1 observe;
    @(posedge clk);
    v_ic_req = 1'b0;
    v_mem_req = 1'b0;
    #1 observe;

    $display("===========End===========");
    $finish;
end

