`timescale 1ns / 1ps
module testbench;

// Inputs
reg clk;
reg [31:0] i_in;
reg i_carry_in;
reg [7:0] i_shift_amount;
reg i_shift_imm_zero;
reg [1:0] i_function;

// Outputs
wire [31:0] o_out;
wire o_carry_out;

integer vector_index;
integer amount_index;
reg [31:0] data_word;
reg [7:0] amount;

a25_shifter_quick uut (
    .i_in(i_in),
    .i_carry_in(i_carry_in),
    .i_shift_amount(i_shift_amount),
    .i_shift_imm_zero(i_shift_imm_zero),
    .i_function(i_function),
    .o_out(o_out),
    .o_carry_out(o_carry_out)
);

initial clk = 0;
always #5 clk = ~clk;

task apply_and_observe;
    input [31:0] data_value;
    input carry_value;
    input [7:0] amount_value;
    input imm_zero_value;
    input [1:0] function_value;
    begin
        i_in = data_value;
        i_carry_in = carry_value;
        i_shift_amount = amount_value;
        i_shift_imm_zero = imm_zero_value;
        i_function = function_value;
        #1;
        $display("fn=%0d imm_zero=%b amount=%0d in=%h carry_in=%b o_out=%h o_carry_out=%b",
                 i_function, i_shift_imm_zero, i_shift_amount,
                 i_in, i_carry_in, o_out, o_carry_out);
    end
endtask

initial begin
    i_in = 32'b0;
    i_carry_in = 1'b0;
    i_shift_amount = 8'b0;
    i_shift_imm_zero = 1'b0;
    i_function = 2'b0;

    // Wait 100 ns for global reset to finish.
    #100;
    $display("initial: o_out=%h o_carry_out=%b", o_out, o_carry_out);

    // Four data patterns x two carries x four functions.
    for (vector_index = 0; vector_index < 32;
         vector_index = vector_index + 1) begin
        case (vector_index / 8)
            0: data_word = 32'h00000000;
            1: data_word = 32'hffffffff;
            2: data_word = 32'ha5c396a5;
            3: data_word = 32'h5a3c695a;
        endcase
        #1;

        // Amounts 0–7, 32–35, and 252–255.
        for (amount_index = 0; amount_index < 16;
             amount_index = amount_index + 1) begin
            if (amount_index < 8)
                amount = amount_index;
            else if (amount_index < 12)
                amount = 32 + (amount_index - 8);
            else
                amount = 252 + (amount_index - 12);

            apply_and_observe(data_word, (vector_index / 4) % 2,
                              amount, 1'b0, vector_index % 4);
            apply_and_observe(data_word, (vector_index / 4) % 2,
                              amount, 1'b1, vector_index % 4);
            #1;
        end
    end

    $display("===========End===========");
    $finish;
end

endmodule

