wire [LA:0] out_cmd_bank_is_open, out_cmd_row_is_open;
wire [LA:0] out_cmd_can_write, out_cmd_can_read;
wire [LA:0] out_cmd_can_activate, out_cmd_can_precharge;
wire [LA:0] out_cmd_info_valid;

integer i, j, sequence_id, case_id, step_id;
reg [1:0] control;

alt_ddrx_cache #(
    .MEM_IF_CS_WIDTH(CS),
    .CTL_LOOK_AHEAD_DEPTH(LA),
    .CTL_CMD_QUEUE_DEPTH(QD)
) uut (
    .ctl_clk(clk),
    .ctl_reset_n(ctl_reset_n),
    .fetch(fetch),
    .ecc_fetch_error_addr(ecc_fetch_error_addr),
    .cmd_is_valid(cmd_is_valid),
    .in_cs_all_banks_closed(in_cs_all_banks_closed),
    .in_cs_can_precharge_all(in_cs_can_precharge_all),
    .in_cs_can_refresh(in_cs_can_refresh),
    .in_cs_can_self_refresh(in_cs_can_self_refresh),
    .in_cs_can_power_down(in_cs_can_power_down),
    .in_cs_can_exit_power_saving_mode(in_cs_can_exit_power_saving_mode),
    .in_cs_zq_cal_req(in_cs_zq_cal_req),
    .in_cs_power_down_req(in_cs_power_down_req),
    .in_cs_refresh_req(in_cs_refresh_req),
    .in_cmd_bank_is_open(in_cmd_bank_is_open),
    .in_cmd_row_is_open(in_cmd_row_is_open),
    .in_cmd_can_write(in_cmd_can_write),
    .in_cmd_can_read(in_cmd_can_read),
    .in_cmd_can_activate(in_cmd_can_activate),
    .in_cmd_can_precharge(in_cmd_can_precharge),
    .out_cs_all_banks_closed(out_cs_all_banks_closed),
    .out_cs_can_precharge_all(out_cs_can_precharge_all),
    .out_cs_can_refresh(out_cs_can_refresh),
    .out_cs_can_self_refresh(out_cs_can_self_refresh),
    .out_cs_can_power_down(out_cs_can_power_down),
    .out_cs_can_exit_power_saving_mode(out_cs_can_exit_power_saving_mode),
    .out_cs_zq_cal_req(out_cs_zq_cal_req),
    .out_cs_power_down_req(out_cs_power_down_req),
    .out_cs_refresh_req(out_cs_refresh_req),
    .out_cmd_bank_is_open(out_cmd_bank_is_open),
    .out_cmd_row_is_open(out_cmd_row_is_open),
    .out_cmd_can_write(out_cmd_can_write),
    .out_cmd_can_read(out_cmd_can_read),
    .out_cmd_can_activate(out_cmd_can_activate),
    .out_cmd_can_precharge(out_cmd_can_precharge),
    .out_cmd_info_valid(out_cmd_info_valid)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [8*24-1:0] phase;
    begin
        $display(
            "t=%0t case=%0d step=%0d phase=%0s reset_n=%b fetch=%b ecc=%b cmd_is_valid=%b",
            $time, case_id, step_id, phase, ctl_reset_n,
            fetch, ecc_fetch_error_addr, cmd_is_valid
        );
        $display(
            "out_cs_all_banks_closed=%b out_cs_can_precharge_all=%b out_cs_can_refresh=%b out_cs_can_self_refresh=%b out_cs_can_power_down=%b out_cs_can_exit_power_saving_mode=%b out_cs_zq_cal_req=%b out_cs_power_down_req=%b out_cs_refresh_req=%b",
            out_cs_all_banks_closed, out_cs_can_precharge_all,
            out_cs_can_refresh, out_cs_can_self_refresh,
            out_cs_can_power_down, out_cs_can_exit_power_saving_mode,
            out_cs_zq_cal_req, out_cs_power_down_req, out_cs_refresh_req
        );
        $display(
            "out_cmd_bank_is_open=%b out_cmd_row_is_open=%b out_cmd_can_write=%b out_cmd_can_read=%b out_cmd_can_activate=%b out_cmd_can_precharge=%b out_cmd_info_valid=%b",
            out_cmd_bank_is_open, out_cmd_row_is_open,
            out_cmd_can_write, out_cmd_can_read,
            out_cmd_can_activate, out_cmd_can_precharge,
            out_cmd_info_valid
        );
    end
endtask

task set_cs;
    input [9*CS-1:0] value;
    begin
        {in_cs_all_banks_closed, in_cs_can_precharge_all,
         in_cs_can_refresh, in_cs_can_self_refresh,
         in_cs_can_power_down, in_cs_can_exit_power_saving_mode,
         in_cs_zq_cal_req, in_cs_power_down_req,
         in_cs_refresh_req} = value;
    end
endtask

task set_commands;
    input [LA:0] value;
    begin
        in_cmd_bank_is_open = value;
        in_cmd_row_is_open = value;
        in_cmd_can_write = value;
        in_cmd_can_read = value;
        in_cmd_can_activate = value;
        in_cmd_can_precharge = value;
    end
endtask

task mixed_data;
    begin
        set_cs(36'h123456789);
        cmd_is_valid = 9'b101010110;
        in_cmd_bank_is_open = 5'b10001;
        in_cmd_row_is_open = 5'b10110;
        in_cmd_can_write = 5'b01010;
        in_cmd_can_read = 5'b00101;
        in_cmd_can_activate = 5'b11000;
        in_cmd_can_precharge = 5'b01111;
    end
endtask

task reset_dut;
    begin
        @(negedge clk);
        #2 ctl_reset_n = 0;
        #1 observe("async_reset");
        repeat (2) @(posedge clk);
        #1 observe("reset_held");
        @(negedge clk);
        fetch = 0;
        ecc_fetch_error_addr = 0;
        ctl_reset_n = 1;
        #1 observe("reset_released");
    end
endtask

task cycle;
    input f, e;
    begin
        @(negedge clk);
        fetch = f;
        ecc_fetch_error_addr = e;
        #1 observe("before_rising_edge");
        @(posedge clk);
        #1 observe("after_rising_edge");
    end
endtask

initial begin
    ctl_reset_n = 0;
    fetch = 0;
    ecc_fetch_error_addr = 0;
    cmd_is_valid = 0;
    set_cs(0);
    set_commands(0);
    case_id = 0;
    step_id = 0;
    control = 0;

    // Wait 100 ns for global reset to finish.
    #100;
    observe("initial_reset");
    reset_dut();

    // Case 1: status pass-through, including active controls.
    case_id = 1;
    mixed_data();
    reset_dut();
    for (i = 0; i < 2; i = i + 1) begin
        @(negedge clk);
        set_cs({36{i[0]}});
        #1 observe("status_uniform");
    end
    for (i = 0; i < 9*CS; i = i + 1) begin
        @(negedge clk);
        step_id = i;
        set_cs(36'b1 << i);
        fetch = i[0];
        ecc_fetch_error_addr = i[1];
        #1 observe("status_walking_one");
        @(posedge clk);
        #1 observe("status_clocked");
    end

    // Case 2: uniform and walking-bit command windows.
    case_id = 2;
    for (i = 0; i < LA+3; i = i + 1) begin
        #1;
        step_id = i;
        mixed_data();
        reset_dut();
        @(negedge clk);
        case (i)
            0: begin
                set_commands(0);
                cmd_is_valid = 0;
            end
            1: begin
                set_commands({(LA+1){1'b1}});
                cmd_is_valid = {(QD+1){1'b1}};
            end
            default: begin
                set_commands(5'b1 << (i-2));
                cmd_is_valid = 9'b1 << (i-2);
            end
        endcase
        #1 observe("command_direct");
        cycle(1, 0);
        cycle(0, 0);
        cycle(0, 0);
    end

    // Case 3: each queue-validity bit, including unused bits.
    case_id = 3;
    for (i = 0; i <= QD; i = i + 1) begin
        #1;
        step_id = i;
        mixed_data();
        reset_dut();
        @(negedge clk);
        cmd_is_valid = 9'b1 << i;
        #1 observe("validity_direct");
        cycle(1, 0);
        cycle(0, 0);
        cycle(0, 0);
    end

    // Cases 100..163: every three-cycle fetch/ECC sequence.
    for (sequence_id = 0; sequence_id < 64;
         sequence_id = sequence_id + 1) begin
        #1;
        case_id = 100 + sequence_id;
        step_id = 0;
        mixed_data();
        reset_dut();
        for (j = 0; j < 3; j = j + 1) begin
            #1;
            step_id = j;
            control = sequence_id >> (2*j);
            cycle(control[1], control[0]);
        end
        step_id = 3;
        cycle(0, 0);
        step_id = 4;
        cycle(0, 0);
    end

    // Cases 200..203: reset retained validity and active histories.
    for (i = 0; i < 4; i = i + 1) begin
        #1;
        case_id = 200 + i;
        step_id = 0;
        mixed_data();
        reset_dut();
        cycle(1, 0);
        cycle(0, 0);
        cycle(0, 0);
        control = i;
        cycle(control[1], control[0]);
        reset_dut();
        cycle(0, 0);
        cycle(0, 0);
    end

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam OBS_CYCLES = 2*8 + 4;

// Inputs
reg clk;
reg [63:0] B, R;
reg [2:0] X, Y;
reg player, RST;

// Outputs
wire [63:0] MB, MR;

integer p;

board_move uut (
    .clk(clk), .B(B), .R(R), .X(X), .Y(Y),
    .player(player), .MB(MB), .MR(MR), .RST(RST)
);

initial clk = 0;
always #5 clk = ~clk;

task show;
    input integer id;
    input [159:0] phase;
    input integer cycle;
    begin
        $display("case=%0d phase=%0s cycle=%0d t=%0t RST=%b player=%b X=%0d Y=%0d MB=%016h MR=%016h",
                 id, phase, cycle, $time, RST, player, X, Y, MB, MR);
    end
endtask

task observe;
    input integer id;
    input integer cycles;
    integer k;
    begin
        for (k = 1; k <= cycles; k = k + 1) begin
            @(posedge clk);
            #1;
            show(id, "observe", k);
        end
    end
endtask

// Board arguments describe stimulus in current/opponent roles.
task start_case;
    input integer id;
    input side;
    input [2:0] x, y;
    input [63:0] current_board, opponent_board;
    begin
        @(negedge clk);
        RST = 1;
        player = side;
        X = x;
        Y = y;
        B = side ? opponent_board : current_board;
        R = side ? current_board : opponent_board;
        #1;
        show(id, "reset_asserted", 0);
        repeat (2) begin
            @(posedge clk);
            #1;
            show(id, "reset_held", 0);
        end
        @(negedge clk);
        RST = 0;
    end
endtask

task row_case;
    input integer id;
    input side;
    input [2:0] x, y;
    input [7:0] current_row, opponent_row;
    begin
        start_case(id, side, x, y,
                   {56'b0, current_row} << (8*y),
                   {56'b0, opponent_row} << (8*y));
        observe(id, OBS_CYCLES);
    end
endtask

initial begin
    B = 0;
    R = 0;
    X = 0;
    Y = 0;
    player = 0;
    RST = 1;

    // Wait 100 ns for global reset to finish.
    #100;
    show(0, "startup", 0);

    for (p = 0; p < 2; p = p + 1) begin
        #1;

        // Eligibility and immediate termination.
        row_case(100*p+1, p, 3, 3, 8'h00, 8'h00);
        row_case(100*p+2, p, 3, 3, 8'h14, 8'h00);
        row_case(100*p+3, p, 3, 3, 8'h08, 8'h14);
        row_case(100*p+4, p, 3, 3, 8'h14, 8'h08);

        // Right-only: bounded single/run, gap, and edge.
        row_case(100*p+5, p, 3, 3, 8'h20, 8'h10);
        row_case(100*p+6, p, 3, 3, 8'h80, 8'h70);
        row_case(100*p+7, p, 3, 3, 8'h00, 8'h30);
        row_case(100*p+8, p, 3, 3, 8'h00, 8'hf0);

        // Left-only: bounded single, gap, and consecutive opponents.
        row_case(100*p+9,  p, 3, 3, 8'h02, 8'h04);
        row_case(100*p+10, p, 3, 3, 8'h00, 8'h04);
        row_case(100*p+11, p, 3, 3, 8'h01, 8'h06);

        // Concurrent scanners with differing termination paths.
        row_case(100*p+12, p, 3, 3, 8'h22, 8'h14);
        row_case(100*p+13, p, 3, 3, 8'h82, 8'h74);
        row_case(100*p+14, p, 3, 3, 8'h20, 8'h14);
        row_case(100*p+15, p, 3, 3, 8'h21, 8'h16);
        row_case(100*p+16, p, 3, 3, 8'h00, 8'h14);
        row_case(100*p+17, p, 3, 3, 8'h00, 8'h34);

        // Board edges, longest right run, and left zero boundary.
        row_case(100*p+18, p, 0, 0, 8'h80, 8'h7e);
        row_case(100*p+19, p, 1, 7, 8'h08, 8'h05);
        row_case(100*p+20, p, 6, 7, 8'h10, 8'ha0);
        row_case(100*p+21, p, 7, 7, 8'h10, 8'h60);

        // Previous-row adjacency plus unrelated occupied squares.
        start_case(100*p+22, p, 0, 3,
                   (64'b1 << 63) | 64'b1,
                   (64'b1 << 23) | (64'b1 << 25));
        observe(100*p+22, OBS_CYCLES);

        // Restart after two scan clocks, then after rollback entry.
        start_case(100*p+23, p, 3, 3,
                   64'h82 << 24, 64'h74 << 24);
        observe(100*p+23, 2);
        start_case(100*p+24, p, 3, 3,
                   64'b0, 64'h14 << 24);
        observe(100*p+24, 2);
        row_case(100*p+25, !p, 6, 0, 8'h10, 8'ha0);
    end

    // Completed scan followed by input changes without reset.
    row_case(201, 0, 3, 0, 8'h22, 8'h14);
    @(negedge clk);
    B = 64'h81 << 56;
    R = 64'h42 << 56;
    X = 7;
    Y = 7;
    player = 1;
    observe(202, 3);

    // Reset pulse entirely between rising edges.
    @(negedge clk);
    #1 RST = 1;
    #1;
    show(203, "short_reset_high", 0);
    #1 RST = 0;
    #1;
    show(203, "short_reset_low", 0);
    observe(203, 2);

    // Clocked reset, then reload different inputs while reset stays high.
    @(negedge clk);
    RST = 1;
    #1;
    show(204, "reset_asserted", 0);
    @(posedge clk);
    #1;
    show(204, "reset_loaded", 1);

    @(negedge clk);
    B = 64'h22 << 24;
    R = 64'h14 << 24;
    X = 3;
    Y = 3;
    player = 0;
    #1;
    show(204, "reload_before_clock", 0);
    repeat (2) begin
        @(posedge clk);
        #1;
        show(204, "reload_reset_held", 0);
    end
    @(negedge clk);
    RST = 0;
    observe(204, OBS_CYCLES);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps

module testbench;

// Inputs
reg        clk_i;
reg        rst_i;
reg        istek_i;
reg        sign_i;
reg [31:0] bolunen_i;
reg [31:0] bolen_i;

// Outputs
wire [31:0] bolum_o;
wire [31:0] kalan_o;
wire        result_ready_o;

// Instantiate the Unit Under Test (UUT)
bolme uut (
    .clk_i          (clk_i),
    .rst_i          (rst_i),
    .istek_i        (istek_i),
    .sign_i         (sign_i),
    .bolunen_i      (bolunen_i),
    .bolen_i        (bolen_i),
    .bolum_o        (bolum_o),
    .kalan_o        (kalan_o),
    .result_ready_o (result_ready_o)
);

// Clock generation
initial clk_i = 1'b0;
always #5 clk_i = ~clk_i;

task reset_dut;
begin
    rst_i      = 1'b0;
    istek_i    = 1'b0;
    sign_i     = 1'b0;
    bolunen_i  = 32'd0;
    bolen_i    = 32'd0;

    repeat (2) @(posedge clk_i);
    #1;
    rst_i = 1'b1;
end
endtask

task run_case;
    input        case_sign;
    input [31:0] case_dividend;
    input [31:0] case_divisor;
    input integer response_cycles;
begin
    reset_dut();

    sign_i    = case_sign;
    bolunen_i = case_dividend;
    bolen_i   = case_divisor;
    istek_i   = 1'b1;

    @(posedge clk_i);
    #1;
    istek_i = 1'b0;

    repeat (response_cycles) @(posedge clk_i);
    #1;

    $display("[%0t] sign=%b dividend=%h divisor=%h : bolum_o=%h kalan_o=%h result_ready_o=%b",
             $time, case_sign, case_dividend, case_divisor,
             bolum_o, kalan_o, result_ready_o);
end
endtask

// Apply reset after the request has reached a selected active state.
// cycles_to_state:
//   0 -> ISLEM
//   8 -> TAMAMLANDI
//   9 -> SIGNED_SONUC
task reset_from_state;
    input        case_sign;
    input [31:0] case_dividend;
    input [31:0] case_divisor;
    input integer cycles_to_state;
begin
    reset_dut();

    sign_i    = case_sign;
    bolunen_i = case_dividend;
    bolen_i   = case_divisor;
    istek_i   = 1'b1;

    @(posedge clk_i);
    #1;
    istek_i = 1'b0;

    repeat (cycles_to_state) @(posedge clk_i);
    #1;

    rst_i = 1'b0;
    @(posedge clk_i);
    #1;

    $display("[%0t] reset-in-state sign=%b dividend=%h divisor=%h : bolum_o=%h kalan_o=%h result_ready_o=%b",
             $time, case_sign, case_dividend, case_divisor,
             bolum_o, kalan_o, result_ready_o);

    rst_i = 1'b1;
end
endtask

initial begin
    // Initialize inputs
    clk_i     = 1'b0;
    rst_i     = 1'b0;
    istek_i   = 1'b0;
    sign_i    = 1'b0;
    bolunen_i = 32'd0;
    bolen_i   = 32'd0;

    // Initial synchronous reset
    repeat (2) @(posedge clk_i);
    #1;
    $display("[%0t] reset: bolum_o=%h kalan_o=%h result_ready_o=%b",
             $time, bolum_o, kalan_o, result_ready_o);
    rst_i = 1'b1;

    // Test Case 1: unsigned divide by zero
    run_case(1'b0, 32'h12345678, 32'h00000000, 0);

    // Test Case 2: signed divide by zero
    run_case(1'b1, 32'h87654321, 32'h00000000, 0);

    // Test Case 3: unsigned divisor greater than dividend
    run_case(1'b0, 32'h00000005, 32'h00000007, 0);

    // Test Case 4: signed overflow
    run_case(1'b1, 32'h80000000, 32'hFFFFFFFF, 0);

    // Test Case 5: ordinary unsigned iterative division
    run_case(1'b0, 32'h00000064, 32'h00000007, 9);

    // Test Case 6: signed positive / positive, nonzero remainder
    run_case(1'b1, 32'h00000064, 32'h00000007, 10);

    // Test Case 7: signed negative dividend / positive divisor
    run_case(1'b1, 32'hFFFFFF9C, 32'h00000007, 10);

    // Test Case 8: signed positive dividend / negative divisor
    run_case(1'b1, 32'h00000064, 32'hFFFFFFF9, 10);

    // Test Case 9: signed negative dividend / negative divisor
    run_case(1'b1, 32'hFFFFFF9C, 32'hFFFFFFF9, 10);

    // Test Case 10: signed zero remainder with negative divisor
    run_case(1'b1, 32'h00000064, 32'hFFFFFFF6, 10);

    // Test Case 11: request presented while a normal operation is busy
    reset_dut();

    sign_i    = 1'b0;
    bolunen_i = 32'h00000064;
    bolen_i   = 32'h00000007;
    istek_i   = 1'b1;

    @(posedge clk_i);
    #1;
    istek_i = 1'b0;

    sign_i    = 1'b0;
    bolunen_i = 32'h00000003;
    bolen_i   = 32'h00000002;
    istek_i   = 1'b1;

    @(posedge clk_i);
    #1;
    istek_i = 1'b0;

    repeat (8) @(posedge clk_i);
    #1;

    $display("[%0t] busy-request test: bolum_o=%h kalan_o=%h result_ready_o=%b",
             $time, bolum_o, kalan_o, result_ready_o);

    // Test Case 12: unsigned overflow-condition alternatives
    run_case(1'b0, 32'h80000000, 32'hFFFFFFFF, 0);

    // Test Case 13: signed divisor matches -1, dividend does not match INT_MIN
    run_case(1'b1, 32'h00000001, 32'hFFFFFFFF, 10);

    // Test Case 14: signed dividend matches INT_MIN, divisor does not match -1
    run_case(1'b1, 32'h80000000, 32'h00000001, 10);

    // Test Case 15: unsigned iterative path with both operand MSBs set
    run_case(1'b0, 32'hF0000000, 32'h80000001, 9);

    // Test Case 16: additional unsigned cases to exercise final restoration
    run_case(1'b0, 32'h00000009, 32'h00000002, 9);
    run_case(1'b0, 32'h0000000A, 32'h00000003, 9);
    run_case(1'b0, 32'h00000011, 32'h00000005, 9);
    run_case(1'b0, 32'h0000007F, 32'h00000008, 9);
    run_case(1'b0, 32'h00000100, 32'h0000000F, 9);

    // Test Case 17: signed negative / positive with zero remainder
    run_case(1'b1, 32'hFFFFFF9C, 32'h0000000A, 10);

    // Test Case 18: signed positive / negative with zero remainder
    run_case(1'b1, 32'h00000064, 32'hFFFFFFF6, 10);

    // Test Case 19: signed negative / negative with zero remainder
    run_case(1'b1, 32'hFFFFFF9C, 32'hFFFFFFF6, 10);

    // Test Case 20: signed nonzero remainder with both operands negative
    run_case(1'b1, 32'hFFFFFF9B, 32'hFFFFFFF6, 10);

    // Test Case 21: additional signed cases for final positive and negative partial remainders
    run_case(1'b1, 32'h00000009, 32'h00000002, 10);
    run_case(1'b1, 32'h0000000A, 32'h00000003, 10);
    run_case(1'b1, 32'hFFFFFFF7, 32'h00000003, 10);
    run_case(1'b1, 32'hFFFFFFF0, 32'hFFFFFFF9, 10);

    // Test Case 22: synchronous reset while in ISLEM
    reset_from_state(1'b0, 32'h00000064, 32'h00000007, 0);

    // Test Case 23: synchronous reset while in TAMAMLANDI
    reset_from_state(1'b0, 32'h00000064, 32'h00000007, 8);

    // Test Case 24: synchronous reset while in SIGNED_SONUC
    reset_from_state(1'b1, 32'h00000064, 32'h00000007, 9);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam [127:0] A = {
    32'h33333333, 32'h22222222, 32'h11111111, 32'h00000000
};
localparam [127:0] B = {
    32'hfedcba98, 32'h76543210, 32'hffffffff, 32'h89abcdef
};
localparam [127:0] C = {
    32'h80000000, 32'h00000001, 32'haaaaaaaa, 32'h55555555
};
localparam [127:0] D = {
    32'h01234567, 32'h89abcdef, 32'h13579bdf, 32'h2468ace0
};

// Inputs
reg clk;
reg proc_reset, proc_read, proc_write;
reg [29:0] proc_addr;
reg [31:0] proc_wdata;
reg [127:0] mem_rdata;
reg mem_ready;

// Outputs
wire proc_stall;
wire [31:0] proc_rdata;
wire mem_read, mem_write;
wire [27:0] mem_addr;
wire [127:0] mem_wdata;

integer tc, variant;
integer i, k, mode, round;

// Instantiate only the top-level DUT.
cache uut (
    .clk(clk),
    .proc_reset(proc_reset),
    .proc_read(proc_read),
    .proc_write(proc_write),
    .proc_addr(proc_addr),
    .proc_wdata(proc_wdata),
    .proc_stall(proc_stall),
    .proc_rdata(proc_rdata),
    .mem_read(mem_read),
    .mem_write(mem_write),
    .mem_addr(mem_addr),
    .mem_rdata(mem_rdata),
    .mem_wdata(mem_wdata),
    .mem_ready(mem_ready)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [8*32-1:0] point;
    begin
        $display("t=%0t case=%0d variant=%0d %0s reset=%b req=%b%b paddr=%08h pwdata=%08h ready=%b | proc_stall=%b proc_rdata=%08h mem_read=%b mem_write=%b mem_addr=%07h mem_wdata=%032h",
                 $time, tc, variant, point, proc_reset,
                 proc_read, proc_write, proc_addr, proc_wdata,
                 mem_ready, proc_stall, proc_rdata,
                 mem_read, mem_write, mem_addr, mem_wdata);
    end
endtask

task cycles;
    input integer n;
    input [8*32-1:0] point;
    begin
        repeat(n) @(posedge clk);
        #1;
        observe(point);
    end
endtask

task reset_dut;
    begin
        @(negedge clk);
        proc_read = 0;
        proc_write = 0;
        proc_addr = 0;
        proc_wdata = 0;
        mem_ready = 0;
        mem_rdata = 0;
        #2;
        proc_reset = 1;
        #1;
        observe("asynchronous reset");
        cycles(2, "reset held");
        @(negedge clk);
        proc_reset = 0;
        cycles(1, "reset released");
    end
endtask

task request;
    input rd, wr;
    input [29:0] address;
    input [31:0] data;
    begin
        @(negedge clk);
        proc_addr = address;
        proc_wdata = data;
        proc_read = rd;
        proc_write = wr;
        #1;
        observe("request applied");
        cycles(2, "request held");
    end
endtask

task release_request;
    begin
        @(negedge clk);
        proc_read = 0;
        proc_write = 0;
        #1;
        observe("processor released");
    end
endtask

// One fixed completion pulse; subsequent settling leaves writeback pending.
task complete_memory;
    input [127:0] data;
    begin
        @(negedge clk);
        mem_rdata = data;
        mem_ready = 1;
        cycles(1, "memory completion");
        @(negedge clk);
        mem_ready = 0;
        mem_rdata = ~data;
        cycles(2, "completion settled");
    end
endtask

task hit_access;
    input rd, wr;
    input [29:0] address;
    input [31:0] data;
    begin
        request(rd, wr, address, data);
        release_request;
    end
endtask

task miss_access;
    input rd, wr;
    input [29:0] address;
    input [31:0] data;
    input [127:0] block_data;
    begin
        request(rd, wr, address, data);
        cycles(3, "memory response delayed");
        complete_memory(block_data);
        release_request;
    end
endtask

task read_words;
    input [29:0] base;
    integer word_index;
    begin
        for (word_index = 0; word_index < 4;
             word_index = word_index + 1) begin
            #1;
            hit_access(1, 0, base + word_index, 0);
        end
    end
endtask

initial begin
    // Initialize inputs and wait 100 ns.
    proc_reset = 1;
    proc_read = 0;
    proc_write = 0;
    proc_addr = 0;
    proc_wdata = 0;
    mem_rdata = 0;
    mem_ready = 0;
    tc = 1;
    variant = 0;
    #100;
    observe("initial reset held");
    @(negedge clk);
    proc_reset = 0;
    cycles(2, "initial idle");
    complete_memory(A);
    cycles(2, "idle after ready pulse");

    // Case 2: all indices, all words, maximum address, reset invalidation.
    tc = 2;
    for (round = 0; round < 2; round = round + 1) begin
        #1;
        variant = round;
        reset_dut;
        for (i = 0; i < 8; i = i + 1) begin
            #1;
            variant = round * 8 + i;
            miss_access(1, 0,
                        {25'h1ffffff, i[2:0], i[1:0]}, 0,
                        {32'h30000000 + i, 32'h20000000 + i,
                         32'h10000000 + i, 32'h00000000 + i});
        end
        for (i = 0; i < 8; i = i + 1) begin
            #1;
            variant = round * 8 + i;
            read_words({25'h1ffffff, i[2:0], 2'b00});
        end
    end

    // Case 3: all offsets through allocation, hits, and replacement.
    tc = 3;
    for (k = 0; k < 4; k = k + 1) begin
        #1;
        variant = k;
        reset_dut;
        miss_access(0, 1, k, 32'hffffffff, A);
        read_words(0);
        hit_access(0, 1, k, 32'h00000000);
        read_words(0);

        miss_access(1, 0, 32 + k, 0, B);
        read_words(32);
        cycles(3, "dirty read writeback held");
        complete_memory(0);

        miss_access(1, 0, k, 0, C);
        read_words(0);
        miss_access(0, 1, 64 + k, 32'ha5a5a5a5, D);
        read_words(64);

        miss_access(0, 1, 96 + k, 32'h5a5a5a5a, A);
        read_words(96);
        cycles(3, "dirty write writeback held");
        complete_memory(0);

        miss_access(1, 0, 128 + k, 0, B);
        complete_memory(0);
        read_words(128);
    end

    // Case 4: read priority on invalid, clean, dirty misses and hits.
    tc = 4;
    for (mode = 0; mode < 3; mode = mode + 1) begin
        #1;
        variant = mode;
        reset_dut;
        if (mode > 0)
            miss_access(1, 0, 0, 0, A);
        if (mode == 2)
            hit_access(0, 1, 0, 32'hdeadbeef);

        miss_access(1, 1, 32 + mode, 32'hcafef00d, B);
        read_words(32);
        if (mode == 2)
            complete_memory(0);

        hit_access(1, 1, 32 + mode, 32'h12345678);
        read_words(32);
        miss_access(1, 0, 64 + mode, 0, C);
        read_words(64);
        cycles(3, "after priority replacement");
    end

    // Case 5: busy-buffer hits and six waiting-miss branches.
    // mode/2 selects invalid, clean, dirty; mode%2 selects read/write.
    tc = 5;
    for (mode = 0; mode < 6; mode = mode + 1) begin
        #1;
        variant = mode;
        reset_dut;
        if (mode / 2 > 0)
            miss_access(1, 0, 4, 0, C);
        if (mode / 2 == 2)
            hit_access(0, 1, 6, 32'hface1234);

        miss_access(0, 1, 0, 32'hdeadbeef, A);
        miss_access(1, 0, 32, 0, B);
        hit_access(1, 0, 32, 0);
        hit_access(0, 1, 33, 32'h87654321);
        read_words(32);

        request((mode % 2) == 0, (mode % 2) == 1,
                39, 32'h10203040);
        cycles(4, "miss waiting for writeback");
        complete_memory(0);
        cycles(3, "queued block read held");
        complete_memory(D);
        release_request;
        read_words(36);
        if (mode / 2 == 2) begin
            cycles(3, "second writeback held");
            complete_memory(0);
        end
        read_words(32);
    end

    // Case 6: reset allocation, dirty replacement, and writeback.
    tc = 6;
    for (mode = 0; mode < 6; mode = mode + 1) begin
        #1;
        variant = mode;
        reset_dut;
        if (mode >= 2)
            miss_access(0, 1, 0, 32'habcdef01, A);

        request((mode % 2) == 0, (mode % 2) == 1,
                35, 32'h11223344);
        cycles(3, "transaction before reset");
        if (mode >= 4) begin
            complete_memory(B);
            release_request;
            cycles(3, "writeback before reset");
        end

        reset_dut;
        miss_access(1, 0, 35, 0, C);
        read_words(32);
        miss_access(1, 0, 0, 0, D);
        read_words(0);
        cycles(2, "recovery idle");
    end

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

reg clk;

reg         hresetn;
reg  [11:0] addr;
reg         read_en;
reg         write_en;
reg  [3:0]  byte_strobe;
reg  [31:0] wdata;
reg  [3:0]  ecorevnum;

wire [31:0] rdata;

cmsdk_ahb_eg_slave_reg #(
    .ADDRWIDTH(12)
) uut (
    .hclk        (clk),
    .hresetn     (hresetn),
    .addr        (addr),
    .read_en     (read_en),
    .write_en    (write_en),
    .byte_strobe (byte_strobe),
    .wdata       (wdata),
    .ecorevnum   (ecorevnum),
    .rdata       (rdata)
);

initial clk = 1'b0;
always #5 clk = ~clk;

task sample_read;
    input [11:0] sample_addr;
    input        sample_enable;
    begin
        @(negedge clk);
        addr    = sample_addr;
        read_en = sample_enable;
        #1;
        $display("READ addr=%03h read_en=%b ecorevnum=%h rdata=%08h",
                 addr, read_en, ecorevnum, rdata);
    end
endtask

task write_and_read;
    input [11:0] write_addr;
    input [31:0] write_data;
    input [3:0]  write_strobe;
    begin
        @(negedge clk);
        addr        = write_addr;
        wdata       = write_data;
        byte_strobe = write_strobe;
        write_en    = 1'b1;
        @(posedge clk);
        #1;
        write_en    = 1'b0;
        sample_read(write_addr, 1'b1);
    end
endtask

task reset_dut;
    begin
        hresetn     = 1'b0;
        read_en     = 1'b0;
        write_en    = 1'b0;
        byte_strobe = 4'b0000;
        wdata       = 32'h00000000;
        addr        = 12'h000;
        #1;
        repeat (2) @(posedge clk);
        @(negedge clk);
        hresetn = 1'b1;
    end
endtask

integer i;

initial begin
    hresetn     = 1'b0;
    addr        = 12'h000;
    read_en     = 1'b0;
    write_en    = 1'b0;
    byte_strobe = 4'b0000;
    wdata       = 32'h00000000;
    ecorevnum   = 4'hA;

    // Test Case 1: asynchronous reset and cleared writable registers
    reset_dut;
    sample_read(12'h000, 1'b1);
    sample_read(12'h004, 1'b1);
    sample_read(12'h008, 1'b1);
    sample_read(12'h00C, 1'b1);

    // Test Case 2: full-word writes to all writable registers
    write_and_read(12'h000, 32'hA1B2C3D4, 4'b1111);
    write_and_read(12'h004, 32'h11223344, 4'b1111);
    write_and_read(12'h008, 32'h55667788, 4'b1111);
    write_and_read(12'h00C, 32'h99AABBCC, 4'b1111);

    // Test Case 3: extend the original byte-lane sequence to every register.
    // A selected register must see low strobes to exercise its retention paths.
    for (i = 0; i < 4; i = i + 1) begin
        #1;
        write_and_read(i * 4, 32'h00000011, 4'b0001);
        write_and_read(i * 4, 32'h00002200, 4'b0010);
        write_and_read(i * 4, 32'h00330000, 4'b0100);
        write_and_read(i * 4, 32'h44000000, 4'b1000);
        write_and_read(i * 4, 32'hFFFFFFFF, 4'b0000);
        write_and_read(i * 4, 32'hA5B6C7D8, 4'b0101);
        write_and_read(i * 4, 32'h192A3B4C, 4'b1010);
    end

    // Test Case 4: write gating and invalid write address
    @(negedge clk);
    addr        = 12'h004;
    wdata       = 32'hDEADBEEF;
    byte_strobe = 4'b1111;
    write_en    = 1'b0;
    @(posedge clk);
    #1;
    sample_read(12'h004, 1'b1);

    write_and_read(12'h100, 32'hCAFEBABE, 4'b1111);
    sample_read(12'h004, 1'b1);

    // Test Case 5: aligned and all low-bit-alias reads.
    // Includes the original 001, 005, 009, and 00D reads.
    for (i = 0; i < 16; i = i + 1) begin
        #1;
        sample_read(i, 1'b1);
    end
    sample_read(12'h010, 1'b1);

    // Test Case 6: read enable disabled, unknown, and high impedance
    sample_read(12'h000, 1'b0);
    sample_read(12'hFD0, 1'bx);
    sample_read(12'hFD0, 1'bz);

    // Test Case 7: entire identification window
    for (i = 0; i < 16; i = i + 1) begin
        #1;
        sample_read(12'hFC0 + (i * 4), 1'b1);
    end

    // Test Case 8: address outside implemented windows
    sample_read(12'h100, 1'b1);
    sample_read(12'h800, 1'b1);

    // Test Case 9: explicitly reach both read-decoder case defaults.
    // Keep writes disabled and window-selection bits fully known.
    @(negedge clk);
    write_en    = 1'b0;
    byte_strobe = 4'b0000;

    // addr[11:4] == 0; addr[3:2] contains X or Z.
    sample_read({8'h00, 2'bx0, 2'b00}, 1'b1);
    sample_read({8'h00, 2'b0z, 2'b00}, 1'b1);

    // addr[11:6] == 6'h3F; addr[5:2] contains X or Z.
    sample_read({6'h3F, 4'b0x00, 2'b00}, 1'b1);
    sample_read({6'h3F, 4'b00z0, 2'b00}, 1'b1);

    // Disabled reads with unknown selection bits.
    sample_read({8'h00, 2'bx0, 2'b00}, 1'b0);
    sample_read({6'h3F, 4'b0x00, 2'b00}, 1'b0);

    // Restore a known address and observe ordinary decoding again.
    sample_read(12'h000, 1'b1);

    // Test Case 10: revision changes with address/read enable held fixed.
    sample_read(12'hFEC, 1'b1);
    for (i = 0; i < 16; i = i + 1) begin
        @(negedge clk);
        ecorevnum = i;
        #1;
        $display("READ addr=%03h read_en=%b ecorevnum=%h rdata=%08h",
                 addr, read_en, ecorevnum, rdata);
    end

    $display("===========End===========");
    $finish;
end

endmodule

