initial clk = 1'b0;
always #5 clk = ~clk;

task observe;
    input integer case_id;
    begin
        #1;
        $display(
        "CASE %0d: DIV_start=%b DIVU_start=%b PC_ena=%b IM_ena=%b IM_w=%b IR_ena=%b DM_ena=%b DM_w=%b data_type=%b RF_w=%b RF_waddr=%b Z_ena=%b aluc=%b HI_ena=%b LO_ena=%b M_PC=%b M_RF=%b M_ALU=%b M_HI=%b M_LO=%b EXT16_sign=%b EXT1_n_c=%b CBW_sign=%b CHW_sign=%b mfc0=%b mtc0=%b exception=%b eret=%b cause=%b finish=%b",
        case_id, DIV_start, DIVU_start, PC_ena, IM_ena, IM_w,
        IR_ena, DM_ena, DM_w, data_type, RF_w, RF_waddr, Z_ena,
        aluc, HI_ena, LO_ena, M_PC, M_RF, M_ALU, M_HI, M_LO,
        EXT16_sign, EXT1_n_c, CBW_sign, CHW_sign, mfc0, mtc0,
        exception, eret, cause, finish);
    end
endtask

task reset_dut;
    begin
        rst = 1'b1;
        #2;
        observe(0);
        rst = 1'b0;
        repeat (1) @(posedge clk);
        #1;
    end
endtask

task run_instruction;
    input [5:0] instruction;
    input condition_zero;
    input condition_negative;
    input integer case_id;
    begin
        reset_dut;
        inst = instruction;
        zero = condition_zero;
        negative = condition_negative;
        DIV_busy = 1'b0;
        DIVU_busy = 1'b0;
        repeat (7) @(posedge clk);
        observe(case_id);
    end
endtask

task run_divide_wait;
    input [5:0] instruction;
    input integer unsigned_divide;
    input integer case_id;
    begin
        reset_dut;
        inst = instruction;
        zero = 1'b0;
        negative = 1'b0;
        DIV_busy = 1'b1;
        DIVU_busy = 1'b1;

        // Reach SEXE_DIV and keep the selected divider busy there.
        repeat (4) @(posedge clk);

        if (unsigned_divide)
            DIVU_busy = 1'b0;
        else
            DIV_busy = 1'b0;

        repeat (2) @(posedge clk);
        observe(case_id);
    end
endtask

task exercise_default_paths;
    begin
        // SID default -> SEXE_ALU default -> SWB_REG default.
        reset_dut;
        inst = 6'd0;
        repeat (4) @(posedge clk);
        observe(101);

        // Reach SEXE_ALU with ADD, then retarget to BEQ.
        // This specifically covers the BEQ item in the SEXE_ALU case.
        reset_dut;
        inst = ADD;
        repeat (2) @(posedge clk);
        #1;
        inst = BEQ;
        @(posedge clk);
        #1;
        inst = 6'd0;
        @(posedge clk);
        observe(102);

        // Reach SEXE_J, then retarget inst to an unsupported selector.
        reset_dut;
        inst = J;
        repeat (2) @(posedge clk);
        #1;
        inst = 6'd0;
        @(posedge clk);
        observe(103);

        // Reach SMEM_LS, then retarget inst to an unsupported selector.
        reset_dut;
        inst = LW;
        repeat (3) @(posedge clk);
        #1;
        inst = 6'd0;
        @(posedge clk);
        observe(104);

        // Reach SEXE_M, then retarget inst to an unsupported selector.
        reset_dut;
        inst = MFHI;
        repeat (2) @(posedge clk);
        #1;
        inst = 6'd0;
        @(posedge clk);
        observe(105);

        // Reach SEXE_DIV, then retarget inst to an unsupported selector.
        reset_dut;
        inst = DIV_I;
        DIV_busy = 1'b0;
        DIVU_busy = 1'b0;
        repeat (2) @(posedge clk);
        #1;
        inst = 6'd0;
        @(posedge clk);
        observe(106);

        // Reach SEXE_MULT, then retarget inst to an unsupported selector.
        reset_dut;
        inst = MULT;
        repeat (2) @(posedge clk);
        #1;
        inst = 6'd0;
        @(posedge clk);
        observe(107);
    end
endtask

task exercise_taken_teq_transition;
    begin
        // BEQ first selects SEXE_B2. Retargeting to TEQ before the
        // SEXE_B2 decision covers SEXE_B2 -> SEXE_BREAK.
        reset_dut;
        zero = 1'b1;
        negative = 1'b0;
        inst = BEQ;

        repeat (2) @(posedge clk);
        @(posedge clk);
        #1;
        inst = TEQ;
        @(posedge clk);
        observe(108);
    end
endtask

