    run_instruction(ADD,     1'b0, 1'b0, 1);
    run_instruction(ADDU,    1'b0, 1'b0, 2);
    run_instruction(SUB,     1'b0, 1'b0, 3);
    run_instruction(SUBU,    1'b0, 1'b0, 4);
    run_instruction(AND_I,   1'b0, 1'b0, 5);
    run_instruction(OR_I,    1'b0, 1'b0, 6);
    run_instruction(XOR_I,   1'b0, 1'b0, 7);
    run_instruction(NOR_I,   1'b0, 1'b0, 8);
    run_instruction(SLT,     1'b0, 1'b0, 9);
    run_instruction(SLTU,    1'b0, 1'b0, 10);
    run_instruction(SLL,     1'b0, 1'b0, 11);
    run_instruction(SRL,     1'b0, 1'b0, 12);
    run_instruction(SRA,     1'b0, 1'b0, 13);
    run_instruction(SLLV,    1'b0, 1'b0, 14);
    run_instruction(SRLV,    1'b0, 1'b0, 15);
    run_instruction(SRAV,    1'b0, 1'b0, 16);

    run_instruction(ADDI,    1'b0, 1'b0, 17);
    run_instruction(ADDIU,   1'b0, 1'b0, 18);
    run_instruction(ANDI,    1'b0, 1'b0, 19);
    run_instruction(ORI,     1'b0, 1'b0, 20);
    run_instruction(XORI,    1'b0, 1'b0, 21);
    run_instruction(SLTI,    1'b0, 1'b0, 22);
    run_instruction(SLTIU,   1'b0, 1'b0, 23);
    run_instruction(LUI,     1'b0, 1'b0, 24);
    run_instruction(CLZ,     1'b0, 1'b0, 25);

    run_instruction(LW,      1'b0, 1'b0, 26);
    run_instruction(LH,      1'b0, 1'b0, 27);
    run_instruction(LHU,     1'b0, 1'b0, 28);
    run_instruction(LB,      1'b0, 1'b0, 29);
    run_instruction(LBU,     1'b0, 1'b0, 30);
    run_instruction(SW,      1'b0, 1'b0, 31);
    run_instruction(SH,      1'b0, 1'b0, 32);
    run_instruction(SB,      1'b0, 1'b0, 33);

    run_instruction(BEQ,     1'b0, 1'b0, 34);
    run_instruction(BEQ,     1'b1, 1'b0, 35);
    run_instruction(BNE,     1'b1, 1'b0, 36);
    run_instruction(BNE,     1'b0, 1'b0, 37);
