`timescale 1ns / 1ps
module testbench;

reg clk;
reg rst;
reg [2:0] ins;

wire write_r;
wire read_r;
wire PC_en;
wire [1:0] fetch;
wire ac_ena;
wire ram_ena;
wire rom_ena;
wire ram_write;
wire ram_read;
wire rom_read;
wire ad_sel;

controller_purify uut (
    .ins(ins),
    .clk(clk),
    .rst(rst),
    .write_r(write_r),
    .read_r(read_r),
    .PC_en(PC_en),
    .fetch(fetch),
    .ac_ena(ac_ena),
    .ram_ena(ram_ena),
    .rom_ena(rom_ena),
    .ram_write(ram_write),
    .ram_read(ram_read),
    .rom_read(rom_read),
    .ad_sel(ad_sel)
);

initial clk = 0;

always #5 clk = ~clk;

task observe_outputs;
    input integer point;
    input integer sample;
    begin
        $display("TP=%0d SAMPLE=%0d ins=%b write_r=%b read_r=%b PC_en=%b fetch=%b ac_ena=%b ram_ena=%b rom_ena=%b ram_write=%b ram_read=%b rom_read=%b ad_sel=%b",
                 point, sample, ins, write_r, read_r, PC_en, fetch, ac_ena,
                 ram_ena, rom_ena, ram_write, ram_read, rom_read, ad_sel);
    end
endtask

task run_instruction;
    input [2:0] opcode;
    input integer point;
    integer sample;
    begin
        ins = opcode;
        rst = 1'b0;
        #2;
        observe_outputs(point, 0);

        rst = 1'b1;

        for (sample = 1; sample <= 8; sample = sample + 1) begin
            @(posedge clk);
            #1;
            observe_outputs(point, sample);
        end
    end
endtask

task reset_from_state;
    input [2:0] opcode;
    input integer cycles_to_target;
    input integer point;
    begin
        ins = opcode;

        rst = 1'b0;
        #1;
        rst = 1'b1;

        repeat (cycles_to_target) @(posedge clk);
        #1;

        rst = 1'b0;
        #1;
        observe_outputs(point, 0);

        rst = 1'b1;
    end
endtask

initial begin
    ins = 3'b000;
    rst = 1'b0;

    #2;
    observe_outputs(0, 0);
    rst = 1'b1;

    run_instruction(3'b000, 1);
    run_instruction(3'b001, 2);
    run_instruction(3'b010, 3);
    run_instruction(3'b011, 4);
    run_instruction(3'b100, 5);
    run_instruction(3'b101, 6);
    run_instruction(3'b110, 7);
    run_instruction(3'b111, 8);

    reset_from_state(3'b000, 1, 10);
    reset_from_state(3'b001, 3, 11);
    reset_from_state(3'b001, 4, 12);
    reset_from_state(3'b001, 5, 13);
    reset_from_state(3'b001, 6, 14);
    reset_from_state(3'b011, 5, 15);
    reset_from_state(3'b011, 6, 16);
    reset_from_state(3'b100, 3, 17);
    reset_from_state(3'b100, 4, 18);
    reset_from_state(3'b110, 3, 19);
    reset_from_state(3'b110, 4, 20);

    rst = 1'b0;
    #1;
    observe_outputs(21, 0);

    rst = 1'b1;

    repeat (2) begin
        @(posedge clk);
        #1;
        observe_outputs(21, 1);
    end

    $display("===========End===========");

    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam PAL_WADR = 3'd0, PAL_DAT = 3'd1, PIX_MSK = 3'd2,
           PAL_RADR = 3'd3, IDX_ADRLO = 3'd4, IDX_ADRHI = 3'd5,
