    .cursor2cpu(cursor2cpu),
    .lblu_comp(lblu_comp), .lgrn_comp(lgrn_comp), .lred_comp(lred_comp),
    .blu_comp(blu_comp), .grn_comp(grn_comp), .red_comp(red_comp),
    .misr_done(misr_done), .pal2cpu(pal2cpu), .paladr(paladr),
    .act_curxlow(act_curxlow), .act_curxhi(act_curxhi),
    .act_curylow(act_curylow), .act_curyhi(act_curyhi),
    .misr_red(misr_red), .misr_grn(misr_grn), .misr_blu(misr_blu),
    .ext_fs(ext_fs),
    .rd_mode(rd_mode), .idx_inc(idx_inc), .idx_raw(idx_raw),
