    .pixclksel(pixclksel), .hsyn_pos(hsyn_pos), .dac_op(dac_op),
    .syscctl(syscctl), .pix_sel(pix_sel), .vsyn_cntl(vsyn_cntl),
    .hsyn_cntl(hsyn_cntl), .int_fs(int_fs),
    .cur1red(cur1red), .cur1grn(cur1grn), .cur1blu(cur1blu),
    .cur2red(cur2red), .cur2grn(cur2grn), .cur2blu(cur2blu),
    .cur3red(cur3red), .cur3grn(cur3grn), .cur3blu(cur3blu),
    .pal_wradr(pal_wradr), .pal_data1(pal_data1),
