    .b32dcol(b32dcol), .wr_mode(wr_mode), .sixbitlin(sixbitlin),
    .vga_mode(vga_mode), .csyn_invt(csyn_invt), .vsyn_invt(vsyn_invt),
    .hsyn_invt(hsyn_invt), .adcurctl(adcurctl), .prog_mode(prog_mode),
    .spll_enab(spll_enab), .misr_cntl(misr_cntl), .sens_disb(sens_disb),
    .sens_sel(sens_sel), .xor_sync(xor_sync), .padr_rfmt(padr_rfmt),
    .sclk_inv(sclk_inv), .ppll_enab(ppll_enab)
);

initial clk = 0; //clk is initialized as 0
always #5 clk = ~clk;

// Enumerate the 45 writable indexed addresses.
function [10:0] config_address;
    input integer n;
    begin
        if      (n < 7)  config_address = 11'h002 + n;
        else if (n < 10) config_address = 11'h00a + (n - 7);
        else if (n < 11) config_address = 11'h00e;
        else if (n < 13) config_address = 11'h010 + (n - 11);
        else if (n < 17) config_address = 11'h015 + (n - 13);
        else if (n < 25) config_address = 11'h020 + (n - 17);
        else if (n < 34) config_address = 11'h030 + (n - 25);
        else if (n < 43) config_address = 11'h040 + (n - 34);
        else             config_address = 11'h070 + (n - 43);
    end
endfunction

function [7:0] pattern;
    input integer n;
    begin
        case (n)
            0: pattern = 8'h00;
            1: pattern = 8'hff;
            2: pattern = 8'h55;
            3: pattern = 8'haa;
            default: pattern = 8'h00;
        endcase
    end
endfunction

task observe;
    input [8*24-1:0] phase;
    begin
        $display("t=%0t tc=%0d %0s rs=%h wrn=%b rdn=%b din=%h | cp_addr=%h cpu_dout=%h cpu2cursor=%h idx_inc=%h idx_raw=%h",
                 $time, tc, phase, rs, wrn, rdn, cpu_din,
                 cp_addr, cpu_dout, cpu2cursor, idx_inc, idx_raw);
        $display("rd_mode=%b wr_mode=%b pal_wradr=%h pal_data1=%h pal_data2=%h pal_data3=%h pix_mask=%h",
                 rd_mode, wr_mode, pal_wradr, pal_data1,
                 pal_data2, pal_data3, pix_mask);
        $display("pixformat=%h pixclksel=%h hsyn_pos=%h dac_op=%h syscctl=%h pix_sel=%h vsyn_cntl=%h hsyn_cntl=%h int_fs=%h",
                 pixformat, pixclksel, hsyn_pos, dac_op, syscctl,
                 pix_sel, vsyn_cntl, hsyn_cntl, int_fs);
        $display("curctl=%h curxlow=%h curxhi=%h curylow=%h curyhi=%h curhotx=%h curhoty=%h adcurctl=%b adcuratt=%h",
                 curctl, curxlow, curxhi, curylow, curyhi,
                 curhotx, curhoty, adcurctl, adcuratt);
        $display("cur1red=%h cur1grn=%h cur1blu=%h cur2red=%h cur2grn=%h cur2blu=%h cur3red=%h cur3grn=%h cur3blu=%h",
                 cur1red, cur1grn, cur1blu, cur2red, cur2grn,
                 cur2blu, cur3red, cur3grn, cur3blu);
        $display("sysnctl=%h sysmctl=%h syspctl=%h pixreg20=%h pixreg21=%h pixreg22=%h pixreg23=%h pixreg24=%h pixreg25=%h pixreg26=%h pixreg27=%h",
                 sysnctl, sysmctl, syspctl, pixreg20, pixreg21,
                 pixreg22, pixreg23, pixreg24, pixreg25, pixreg26, pixreg27);
        $display("sclk_pwr=%b sync_pwr=%b iclk_pwr=%b dac_pwr=%b blank_cntl=%b colres=%b fsf=%b ziblin=%b b8dcol=%b b16dcol=%b b32dcol=%b",
                 sclk_pwr, sync_pwr, iclk_pwr, dac_pwr, blank_cntl,
                 colres, fsf, ziblin, b8dcol, b16dcol, b32dcol);
        $display("sixbitlin=%b vga_mode=%b csyn_invt=%b vsyn_invt=%b hsyn_invt=%b prog_mode=%b spll_enab=%b sclk_inv=%b ppll_enab=%b",
                 sixbitlin, vga_mode, csyn_invt, vsyn_invt,
                 hsyn_invt, prog_mode, spll_enab, sclk_inv, ppll_enab);
        $display("misr_cntl=%b sens_disb=%b sens_sel=%b xor_sync=%b padr_rfmt=%b",
                 misr_cntl, sens_disb, sens_sel, xor_sync, padr_rfmt);
    end
endtask

task reset_dut;
    begin
        @(negedge clk);
        #2;
        hresetn = 0;
        wrn = 1;
        rdn = 1;
        rs = PAL_WADR;
        cpu_din = 0;
        #1;
        observe("async reset");
        repeat (2) @(posedge clk);
        #1;
        observe("reset held");
        @(negedge clk);
        hresetn = 1;
        @(posedge clk);
        #1;
        observe("reset released");
    end
endtask

// Each active clock is one access; selector setup uses an idle clock.
task access_bus;
    input [2:0] selector;
    input [7:0] value;
    input write_access;
    input integer cycles;
    integer beat;
    begin
        @(negedge clk);
        wrn = 1;
        rdn = 1;
        rs = selector;
        cpu_din = value;
        @(posedge clk);
        #1;
        observe("selected idle");
        @(negedge clk);
        wrn = !write_access;
        rdn = write_access;
        for (beat = 0; beat < cycles; beat = beat + 1) begin
            @(posedge clk);
            #1;
            observe("active response");
        end
        @(negedge clk);
        wrn = 1;
        rdn = 1;
    end
endtask

task write_primary;
    input [2:0] selector;
    input [7:0] value;
    begin
        access_bus(selector, value, 1'b1, 1);
    end
endtask

task read_primary;
    input [2:0] selector;
    begin
        access_bus(selector, 8'h00, 1'b0, 1);
    end
endtask

task set_index;
    input [10:0] value;
    begin
        write_primary(IDX_ADRLO, value[7:0]);
        write_primary(IDX_ADRHI, {5'b0, value[10:8]});
    end
endtask

task write_indexed;
    input [10:0] index_value;
    input [7:0] value;
    begin
        set_index(index_value);
        write_primary(IDX_DAT, value);
    end
endtask

task read_indexed;
    input [10:0] index_value;
    begin
        set_index(index_value);
        read_primary(IDX_DAT);
    end
endtask

initial begin
    // Initialize inputs; wait 100 ns before reset testing.
    hresetn = 1;
    wrn = 1;
    rdn = 1;
    rs = 0;
    cpu_din = 0;
    mreg = 0;
    nreg = 0;
    preg = 0;
    creg = 0;
    cursor2cpu = 8'h96;
    {lblu_comp, lgrn_comp, lred_comp, blu_comp, grn_comp, red_comp} = 0;
    misr_done = 0;
    pal2cpu = 8'h3c;
    paladr = 8'ha5;
    act_curxlow = 8'h12;
    act_curxhi = 8'h78;
    act_curylow = 8'he4;
    act_curyhi = 8'h87;
    misr_red = 0;
    misr_grn = 0;
    misr_blu = 0;
    ext_fs = 0;
    tc = 1;
    #100;

    // 1: Reset defaults, including indexed readback.
    reset_dut;
    for (i = 0; i < 45; i = i + 1) begin
        #1;
        read_indexed(config_address(i));
    end

    // 2: Primary registers, palette formats, pipeline, selector timing.
    tc = 2;
    reset_dut;
    write_primary(PAL_WADR, 8'h00);
    for (i = 0; i < 4; i = i + 1) begin
        #1;
        write_primary(PAL_DAT, pattern(i));
        read_primary(PAL_DAT);
        write_primary(PIX_MSK, pattern(i));
        read_primary(PIX_MSK);
    end
    for (i = 0; i < 2; i = i + 1) begin
        #1;
        write_indexed(11'h070, i << 5);
        write_primary(PAL_WADR, 8'hff);
        read_primary(PAL_RADR);
        write_primary(PAL_RADR, 8'h00);
        read_primary(PAL_RADR);
        write_primary(PAL_WADR, 8'h00);
        read_primary(PAL_RADR);
        write_primary(PAL_RADR, 8'hff);
        read_primary(PAL_RADR);
    end
    for (i = 0; i < 8; i = i + 1) begin
        #1;
        read_primary(i);
    end
    read_primary(PAL_WADR);
    #2;
    paladr = 8'h5a;
    #1;
    observe("live palette address");
    read_primary(PAL_DAT);
    #2;
    pal2cpu = 8'hc3;
    #1;
    observe("live palette data");
    @(negedge clk);
    rs = PIX_MSK;
    cpu_din = 8'h69;
    #1;
    observe("before selector clock");
    @(posedge clk);
    #1;
    observe("after selector clock");
    repeat (2) @(posedge clk);
    #1;
    observe("idle retention");

    // 3: Independent configuration-address cases and data patterns.
    tc = 3;
    for (i = 0; i < 45; i = i + 1) begin
        #1;
        reset_dut;
        write_primary(PAL_WADR, 8'h00);
        address = config_address(i);
        set_index(address);
        for (j = 0; j < 4; j = j + 1) begin
            #1;
            write_primary(IDX_DAT, pattern(j));
            read_primary(IDX_DAT);
        end
    end

    // 4: Index control masking, no increment, snapshots, carry and wrap.
    tc = 4;
    reset_dut;
    write_primary(IDX_ADRLO, 8'hff);
    write_primary(IDX_ADRHI, 8'hf8);
    read_primary(IDX_ADRHI);
    read_primary(IDX_ADRLO);
    write_primary(IDX_ADRHI, 8'hff);
    read_primary(IDX_ADRHI);
    write_primary(IDX_CTL, 8'hfe);
    read_primary(IDX_CTL);
    access_bus(IDX_DAT, 8'h5a, 1'b1, 3);
    repeat (2) @(posedge clk);
    #1;
    observe("write snapshot idle");
    access_bus(IDX_DAT, 8'h00, 1'b0, 3);
    repeat (2) @(posedge clk);
    #1;
    observe("read snapshot idle");
    read_primary(IDX_ADRLO);
    read_primary(IDX_ADRHI);

    for (i = 0; i < 3; i = i + 1) begin
        #1;
        reset_dut;
        case (i)
            0: address = 11'h020;
            1: address = 11'h0fe;
            2: address = 11'h7fe;
        endcase
        write_primary(IDX_CTL, 8'hff);
        read_primary(IDX_CTL);
        set_index(address);
        access_bus(IDX_DAT, 8'ha6, 1'b1, 3);
        repeat (2) @(posedge clk);
        #1;
        observe("increment write idle");
        read_primary(IDX_ADRLO);
        read_primary(IDX_ADRHI);
        set_index(address);
        access_bus(IDX_DAT, 8'h00, 1'b0, 3);
        repeat (2) @(posedge clk);
        #1;
        observe("increment read idle");
        read_primary(IDX_ADRLO);
        read_primary(IDX_ADRHI);
        write_primary(IDX_CTL, 8'h00);
        read_primary(IDX_CTL);
    end

    // 5: Cursor source/width selection and sign boundaries.
    tc = 5;
    reset_dut;
    write_indexed(11'h031, 8'h3c);
    write_indexed(11'h032, 8'h7f);
    write_indexed(11'h033, 8'hc3);
    write_indexed(11'h034, 8'h80);
    write_indexed(11'h035, 8'h3f);
    write_indexed(11'h036, 8'h20);
    for (i = 0; i < 4; i = i + 1) begin
        #1;
        write_indexed(11'h030, ((i & 1) << 4) | ((i & 2) << 1));
        for (j = 0; j < 2; j = j + 1) begin
            #1;
            act_curxlow = 8'h12 ^ (8'hff * j);
            act_curylow = 8'he4 ^ (8'hff * j);
            act_curxhi = 8'h78 ^ (8'hff * j);
            act_curyhi = 8'h87 ^ (8'hff * j);
            for (k = 0; k < 6; k = k + 1) begin
                #1;
                read_indexed(11'h031 + k);
            end
        end
    end
    read_indexed(11'h032);
    #2;
    act_curxhi = 8'h80;
    #1;
    observe("live cursor idle");
    write_indexed(11'h030, 8'h00);
    write_indexed(11'h032, 8'h80);
    write_indexed(11'h034, 8'h7f);
    read_indexed(11'h032);
    read_indexed(11'h034);

    // 6: Identification, diagnostics, aliases and fallback behavior.
    tc = 6;
    reset_dut;
    for (i = 0; i < 3; i = i + 1) begin
        #1;
        case (i)
            0: begin
                mreg = 0; nreg = 0; preg = 0; creg = 0;
                misr_done = 0;
                misr_red = 0; misr_grn = 0; misr_blu = 0;
                cursor2cpu = 0;
            end
            1: begin
                mreg = 7'h7f; nreg = 6'h3f; preg = 7; creg = 3;
                misr_done = 1;
                misr_red = 8'hff; misr_grn = 8'hff; misr_blu = 8'hff;
                cursor2cpu = 8'hff;
            end
            2: begin
                mreg = 7'h53; nreg = 6'h2a; preg = 5; creg = 2;
                misr_done = 0;
                misr_red = 8'h12; misr_grn = 8'h69; misr_blu = 8'hc7;
                cursor2cpu = 8'h96;
            end
        endcase
        read_indexed(11'h000);
        read_indexed(11'h001);
        for (j = 0; j < 16; j = j + 1) begin
            #1;
            read_indexed(11'h082 + j);
        end
    end
    set_index(11'h082);
    read_primary(IDX_DAT);
    for (i = 0; i < 8; i = i + 1) begin
        #2;
        {lblu_comp, lgrn_comp, lred_comp} = i;
        {blu_comp, grn_comp, red_comp} = 7 - i;
        #1;
        observe("live comparators idle");
        read_primary(IDX_DAT);
    end
    read_indexed(11'h08e);
    #2;
    mreg = 7'h2c;
    #1;
    observe("live divider idle");
    read_indexed(11'h084);
    #2;
    misr_red = 8'he1;
    #1;
    observe("live MISR idle");

    for (i = 0; i < 5; i = i + 1) begin
        #1;
        case (i)
            0: address = 11'h000;
            1: address = 11'h082;
            2: address = 11'h009;
            3: address = 11'h170;
            4: address = 11'h7ff;
        endcase
        write_indexed(address, 8'h5a);
        read_primary(IDX_DAT);
    end
    #2;
    cursor2cpu = 8'h69;
    #1;
    observe("fallback live idle");
    #2;
    ext_fs = 1;
    #1;
    observe("external frame sync high");
    #2;
    ext_fs = 0;
    #1;
    observe("external frame sync low");

    // 7: Asynchronous reset after populating persistent state.
    tc = 7;
    reset_dut;
    for (i = 0; i < 45; i = i + 1) begin
        #1;
        write_indexed(config_address(i), 8'hff);
    end
    write_primary(PIX_MSK, 8'ha5);
    for (i = 0; i < 4; i = i + 1) begin
        #1;
        write_primary(PAL_DAT, pattern(i));
    end
    write_primary(PAL_RADR, 8'hff);
    write_primary(IDX_CTL, 8'h01);
    set_index(11'h7fe);
    write_primary(IDX_DAT, 8'hc3);
    reset_dut;
    for (i = 0; i < 45; i = i + 1) begin
        #1;
        read_indexed(config_address(i));
    end
    write_primary(PAL_WADR, 8'h5a);
    write_indexed(11'h070, 8'h20);
    read_primary(PAL_RADR);
    reset_dut;
    read_primary(IDX_CTL);
    read_primary(IDX_ADRLO);
    read_primary(IDX_ADRHI);
    write_primary(PAL_RADR, 8'ha5);
    read_primary(PAL_RADR);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam TOTAL_WEIGHT = 4;
localparam TOTAL_SHIFT  = 6;
localparam ACK_IDLE        = 2'd0;
localparam ACK_PRELOAD_FIN = 2'd1;
localparam ACK_SHIFT_FIN   = 2'd2;
localparam ACK_LOAD_FIN    = 2'd3;

// Inputs
reg clk;
reg rst_n;
reg enable;
reg [1:0] input_interface_ack;

// Outputs
wire [1:0] input_interface_cmd;
wire [2:0] current_state;

integer case_id;
integer sequence_id;
integer stage_id;
integer ack_id;
integer mode;
integer variant;
integer extension;
integer n;

conv_layer_controller #(
    .TOTAL_WEIGHT(TOTAL_WEIGHT),
    .TOTAL_SHIFT(TOTAL_SHIFT)
) uut (
    .clk(clk),
    .rst_n(rst_n),
    .enable(enable),
    .input_interface_ack(input_interface_ack),
    .input_interface_cmd(input_interface_cmd),
    .current_state(current_state)
);

initial clk = 0;

always #5 clk = ~clk;

task observe;
    begin
        $display("t=%0t case=%0d rst_n=%b enable=%b ack=%0d cmd=%0d state=%0d",
                 $time, case_id, rst_n, enable, input_interface_ack,
                 input_interface_cmd, current_state);
    end
endtask

// Drive away from the active edge; sample after registered updates.
task tick;
    input en;
    input [1:0] ack;
    begin
        @(negedge clk);
        enable = en;
        input_interface_ack = ack;
        @(posedge clk);
        #1;
        observe;
    end
endtask

task reset_dut;
    begin
        @(negedge clk);
        #2;
        rst_n = 0;
        enable = 0;
        input_interface_ack = ACK_SHIFT_FIN;
        #1;
        observe;
        @(posedge clk);
        #1;
        observe;
        @(negedge clk);
        rst_n = 1;
        input_interface_ack = ACK_IDLE;
        #1;
        observe;
    end
endtask

task pulse_ack;
    input [1:0] ack;
    begin
        tick(1'b1, ack);
        tick(1'b1, ACK_IDLE);
    end
endtask

// Reach stages 0/1/2/3 using only legal top-level transactions.
task prepare_stage;
    input integer stage_number;
    integer w;
    begin
        reset_dut;
        if (stage_number >= 1)
            tick(1'b1, ACK_IDLE);
        if (stage_number >= 2)
            pulse_ack(ACK_PRELOAD_FIN);
        if (stage_number >= 3) begin
            for (w = 0; w < TOTAL_WEIGHT; w = w + 1) begin
                pulse_ack(ACK_SHIFT_FIN);
            end
        end
    end
endtask

task sequence_body;
    integer g;
    integer w;
    begin
        for (g = 0; g < TOTAL_SHIFT; g = g + 1) begin
            for (w = 0; w < TOTAL_WEIGHT; w = w + 1) begin
                pulse_ack(ACK_SHIFT_FIN);
            end
            if (g < TOTAL_SHIFT - 1)
                pulse_ack(ACK_LOAD_FIN);
        end
    end
endtask

initial begin
    rst_n = 1;
    enable = 0;
    input_interface_ack = ACK_IDLE;
    case_id = 0;

    // Allow the first rising edge before reset. In four-state RTL
    // simulation the uninitialized state reaches the command default.
    // No DUT internals are driven or referenced.
    #6;
    observe;

    // Assert reset between edges, preserving a 100 ns startup interval.
    rst_n = 0;
    #1;
    observe;
    #93;

    // Case 1: two normal sequences, including final-group restart.
    case_id = 1;
    prepare_stage(1);
    tick(1'b1, ACK_IDLE);
    for (sequence_id = 0; sequence_id < 2;
         sequence_id = sequence_id + 1) begin
        pulse_ack(ACK_PRELOAD_FIN);
        sequence_body;
        tick(1'b1, ACK_IDLE);
    end

    // Cases 100+: every stage/ack combination, enabled and disabled.
    for (mode = 0; mode < 2; mode = mode + 1) begin
        for (stage_id = 0; stage_id < 4; stage_id = stage_id + 1) begin
            for (ack_id = 0; ack_id < 4; ack_id = ack_id + 1) begin
                case_id = 100 + mode * 16 + stage_id * 4 + ack_id;
                prepare_stage(stage_id);
                tick(mode, ack_id);
                tick(mode, ack_id);
                tick(1'b1, ACK_IDLE);

                // Fixed follow-up traffic makes counter side effects visible.
                pulse_ack(ACK_PRELOAD_FIN);
                pulse_ack(ACK_LOAD_FIN);
                sequence_body;
                reset_dut;
            end
        end
    end

    // Cases 200+: hold shift acknowledgements across group boundaries.
    for (variant = 0; variant < 4; variant = variant + 1) begin
        case_id = 200 + variant;
        prepare_stage(2);
        case (variant)
            0: extension = 0;
            1: extension = 1;
            2: extension = TOTAL_WEIGHT;
            3: extension = 2 * TOTAL_WEIGHT;
        endcase

        for (n = 0; n < TOTAL_WEIGHT * TOTAL_SHIFT + extension;
             n = n + 1) begin
            tick(1'b0, ACK_SHIFT_FIN);
        end

        tick(1'b0, ACK_IDLE);
        tick(1'b1, ACK_IDLE);
        sequence_body;
        reset_dut;
    end

    // Cases 300+: reset directly from SHIFT at each partial-weight count.
    // Fewer than TOTAL_WEIGHT transfers keep the stage in SHIFT.
    // Exercise reset with enable both high and low before assertion.
    for (mode = 0; mode < 2; mode = mode + 1) begin
        for (variant = 0; variant < TOTAL_WEIGHT;
             variant = variant + 1) begin
            case_id = 300 + mode * TOTAL_WEIGHT + variant;
            prepare_stage(2);
            tick(mode, ACK_IDLE);

            for (n = 0; n < variant; n = n + 1) begin
                tick(mode, ACK_SHIFT_FIN);
                tick(mode, ACK_IDLE);
            end

            // No intervening transaction can leave SHIFT before reset.
            reset_dut;

            // Observe held INIT commands and normal restart after reset.
            tick(1'b0, ACK_IDLE);
            tick(1'b1, ACK_IDLE);
            pulse_ack(ACK_PRELOAD_FIN);
        end
    end

    $display("===========End===========");
    $finish;
end

endmodule

