module testbench;

reg ap_clk;
reg ap_rst;
reg ap_start;
reg ap_ce;
reg [7:0] CurHuffReadBuf_q0;
reg [31:0] tmp_7;
reg [31:0] off_i;

wire ap_done;
wire ap_idle;
wire ap_ready;
wire [12:0] CurHuffReadBuf_address0;
wire CurHuffReadBuf_ce0;
wire [31:0] off_o;
wire off_o_ap_vld;
wire [7:0] ap_return;

decode_start_pgetc uut (
    .ap_clk(ap_clk),
    .ap_rst(ap_rst),
    .ap_start(ap_start),
    .ap_done(ap_done),
    .ap_idle(ap_idle),
    .ap_ready(ap_ready),
    .ap_ce(ap_ce),
    .CurHuffReadBuf_address0(CurHuffReadBuf_address0),
    .CurHuffReadBuf_ce0(CurHuffReadBuf_ce0),
    .CurHuffReadBuf_q0(CurHuffReadBuf_q0),
    .tmp_7(tmp_7),
    .off_i(off_i),
    .off_o(off_o),
    .off_o_ap_vld(off_o_ap_vld),
    .ap_return(ap_return)
);

initial ap_clk = 0;
always #5 ap_clk = ~ap_clk;

task observe;
    input integer test_id;
    input integer phase;
    begin
        #1;
        $display("case=%0d phase=%0d done=%b idle=%b ready=%b address=%h ce0=%b off_o=%h off_vld=%b return=%h",
                 test_id, phase, ap_done, ap_idle, ap_ready,
                 CurHuffReadBuf_address0, CurHuffReadBuf_ce0,
                 off_o, off_o_ap_vld, ap_return);
    end
endtask

task reset_case;
    input integer test_id;
    begin
        @(negedge ap_clk);
        ap_rst = 1;
        ap_start = 0;
        ap_ce = 1;
        CurHuffReadBuf_q0 = 0;
        tmp_7 = 0;
        off_i = 0;
        @(posedge ap_clk);
        observe(test_id, 0);
        @(negedge ap_clk);
        ap_rst = 0;
        observe(test_id, 1);
    end
endtask

task fetch;
    input integer test_id;
    input [31:0] base;
    input [31:0] offset;
    input [7:0] first_byte;
    input [7:0] following_byte;
    input integer stall_stage0;
    input integer stall_stage1;
    begin
        reset_case(test_id);
        @(negedge ap_clk);
        tmp_7 = base;
        off_i = offset;
        CurHuffReadBuf_q0 = first_byte;
        ap_start = 1;
        ap_ce = !stall_stage0;
        observe(test_id, 2); // First address and one-byte offset update.

        if (stall_stage0) begin
            repeat (2) @(posedge ap_clk);
            observe(test_id, 3);
            @(negedge ap_clk);
            ap_ce = 1;
            observe(test_id, 4);
        end

        @(posedge ap_clk);
        observe(test_id, 5); // Following-byte address; first byte is presented.
        if (stall_stage1) begin
            @(negedge ap_clk);
            ap_ce = 0;
            observe(test_id, 6);
            repeat (2) @(posedge ap_clk);
            observe(test_id, 7);
            @(negedge ap_clk);
            ap_ce = 1;
            observe(test_id, 8);
        end

        @(posedge ap_clk);
        observe(test_id, 9);
        @(negedge ap_clk);
        ap_start = 0;
        CurHuffReadBuf_q0 = following_byte;
        observe(test_id, 10); // Completed result with following byte available.
        @(posedge ap_clk);
        observe(test_id, 11); // Drain to idle.
    end
endtask

initial begin
    ap_rst = 0;
    ap_start = 0;
    ap_ce = 1;
    CurHuffReadBuf_q0 = 0;
    tmp_7 = 0;
    off_i = 0;

    #100;

    fetch(1, 32'h00000020, 32'h00000003, 8'h00, 8'hA5, 0, 0);
    fetch(2, 32'h00001FFF, 32'h00000001, 8'h7E, 8'h00, 0, 0);
    fetch(3, 32'h00000040, 32'h00000005, 8'hFF, 8'h00, 0, 0);
    fetch(4, 32'h00001FFE, 32'h00000001, 8'hFF, 8'h7B, 0, 0);
    fetch(5, 32'h00000010, 32'hFFFFFFFF, 8'hFF, 8'hFF, 0, 0);
    fetch(6, 32'h00000002, 32'hFFFFFFFF, 8'h35, 8'h00, 0, 0);
    fetch(7, 32'h00000030, 32'h00000002, 8'h52, 8'h00, 1, 0);
    fetch(8, 32'h00000030, 32'h00000002, 8'hFF, 8'h6C, 0, 1);

    // Two consecutive requests while start remains asserted.
    reset_case(9);
    @(negedge ap_clk);
    ap_start = 1;
    tmp_7 = 32'h00000100;
    off_i = 32'h00000001;
    CurHuffReadBuf_q0 = 8'h41;
    observe(9, 2);
    @(posedge ap_clk);
    observe(9, 3);
    @(posedge ap_clk);
    observe(9, 4);
    @(negedge ap_clk);
    off_i = 32'h00000002;
    CurHuffReadBuf_q0 = 8'h42;
    observe(9, 5);
    @(posedge ap_clk);
    observe(9, 6);
    @(negedge ap_clk);
    ap_start = 0;
    observe(9, 7);
    @(posedge ap_clk);
    observe(9, 8);
    @(posedge ap_clk);
    observe(9, 9);

    // Reset an active request before stage 1 can complete it.
    reset_case(10);
    @(negedge ap_clk);
    ap_start = 1;
    tmp_7 = 32'h00000080;
    off_i = 32'h00000004;
    CurHuffReadBuf_q0 = 8'hFF;
    observe(10, 2);
    @(posedge ap_clk);
    observe(10, 3);
    @(negedge ap_clk);
    ap_rst = 1;
    ap_start = 0;
    @(posedge ap_clk);
    observe(10, 4);
    @(negedge ap_clk);
    ap_rst = 0;
    observe(10, 5);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam SIZE = 20;
localparam PRE_CYCLES = 80;
localparam BYTE_CYCLES = 8;
localparam POST_CYCLES = 16;

// Inputs
reg clk;
reg reset_n;
reg [7:0] din;
reg din_valid;

// Outputs
wire [7:0] dout;
wire indicator;

integer test_id;
integer k;
integer length;

fifo #(.SIZE(SIZE), .INDEX_WIDTH(8)) uut (
    .dout(dout),
    .indicator(indicator),
    .din(din),
    .din_valid(din_valid),
    .clk(clk),
    .reset_n(reset_n)
);

initial clk = 0; //clk is initialized as 0
always #5 clk = ~clk;

task observe;
    input [159:0] label;
    input integer step;
    begin
        $display("t=%0t case=%0d phase=%0s step=%0d dout=%02h indicator=%b",
                 $time, test_id, label, step, dout, indicator);
    end
endtask

task sample_cycles;
    input integer cycles;
    input [159:0] label;
    integer j;
    begin
        for (j = 0; j < cycles; j = j + 1) begin
            @(posedge clk);
            #1;
            observe(label, j);
        end
    end
endtask

task reset_dut;
    begin
        @(negedge clk);
        #2;
        reset_n = 0;
        #1;
        observe("async_reset", 0);
        din_valid = 0;
        din = 0;
        sample_cycles(2, "reset_held");
        @(negedge clk);
        reset_n = 1;
        sample_cycles(1, "reset_released");
    end
endtask

task capture;
    input integer bytes;
    integer j;
    begin
        for (j = 0; j < bytes; j = j + 1) begin
            @(negedge clk);
            din_valid = 1;
            case (j)
                0: din = 8'hA5;
                1: din = 8'h00;
                2: din = 8'hFF;
                3: din = 8'h80;
                4: din = 8'h01;
                5: din = 8'hAA;
                6: din = 8'h55;
                default: din = j;
            endcase
            @(posedge clk);
            #1;
            observe("capture", j);
        end
    end
endtask

task end_capture;
    begin
        @(negedge clk);
        din_valid = 0;
        din = 8'h3C;
        #1;
        observe("qualifier_fell", 0);
        sample_cycles(1, "padding_entry");
    end
endtask

task complete_burst;
    input integer bytes;
    begin
        capture(bytes);
        end_capture;
        sample_cycles(PRE_CYCLES, "pre_padding");
        sample_cycles(BYTE_CYCLES * bytes, "transfer");
        sample_cycles(POST_CYCLES, "post_padding");
    end
endtask

initial begin
    // Initialize inputs; wait 100 ns for global reset to finish.
    test_id = 0;
    din = 0;
    din_valid = 0;
    reset_n = 0;
    #100;
    observe("startup_reset", 0);

    // Idle, minimum burst, intermediate burst, and full capacity.
    for (k = 0; k < 3; k = k + 1) begin
        @(negedge clk);
        test_id = k + 1;
        reset_dut;
        @(negedge clk);
        din = 8'hFF;
        sample_cycles(2, "idle");
        @(negedge clk);
        din = 8'h00;
        sample_cycles(2, "idle");
        case (k)
            0: length = 1;
            1: length = 3;
            2: length = SIZE;
        endcase
        complete_burst(length);
    end

    // Reuse immediately after the full-capacity burst.
    test_id = 4;
    complete_burst(1);

    // Reset in idle, reception, pre-padding, transfer, and post-padding.
    for (k = 0; k < 5; k = k + 1) begin
        @(negedge clk);
        test_id = 10 + k;
        reset_dut;
        case (k)
            0: sample_cycles(2, "idle_before_reset");
            1: capture(3);
            2: begin
                capture(3);
                end_capture;
                sample_cycles(10, "pre_before_reset");
            end
            3: begin
                capture(3);
                end_capture;
                sample_cycles(PRE_CYCLES + 3, "transfer_before_reset");
            end
            4: begin
                capture(3);
                end_capture;
                sample_cycles(PRE_CYCLES + BYTE_CYCLES * 3 + 3,
                              "post_before_reset");
            end
        endcase
        reset_dut;
        complete_burst(1);
    end

    $display("===========End===========");
    $finish;
end

endmodule

