begin
    @(negedge clk);
    reg_wdata = data;
    reg_wr    = 2'b01;
    @(posedge clk);
    @(negedge clk);
    reg_wr    = 2'b00;
    repeat (1) @(posedge clk);
    #1;
    $display("STATUS WRITE data=%02h: rdata=%02h scale=%b scan_h=%b scan_v=%b prom=%h",
             data, reg_rdata, cfg_scale_2x_on, cfg_scan_line_h,
             cfg_scan_line_v, cfg_prom_wren);
    read_mask(6'b100000);
end
endtask

task cfg_key;
input [7:0] data;
begin
    @(negedge clk);
    reg_wdata = data;
    reg_wr    = 2'b10;
    @(posedge clk);
    // Sample after nonblocking assignments have taken effect.
    #1;
    $display("CONFIG BYTE data=%02h: rdata=%02h scale=%b scan_h=%b scan_v=%b prom=%h",
             data, reg_rdata, cfg_scale_2x_on, cfg_scan_line_h,
             cfg_scan_line_v, cfg_prom_wren);
end
endtask

task cfg_command;
input [7:0] command;
begin
    cfg_key(8'h19);
    cfg_key(8'h43);
    cfg_key(8'hFD);
    cfg_key(command);
    @(negedge clk);
    reg_wr = 2'b00;
    #1;
    $display("CONFIG command=%02h: rdata=%02h scale=%b scan_h=%b scan_v=%b prom=%h",
             command, reg_rdata, cfg_scale_2x_on, cfg_scan_line_h,
             cfg_scan_line_v, cfg_prom_wren);
end
endtask

// Present a byte without a write strobe for a fixed interval.
task cfg_pause;
input [7:0] data;
begin
    @(negedge clk);
    reg_wr    = 2'b00;
    reg_wdata = data;
    repeat (2) @(posedge clk);
    #1;
    $display("CONFIG PAUSE data=%02h: rdata=%02h scale=%b scan_h=%b scan_v=%b prom=%h",
             data, reg_rdata, cfg_scale_2x_on, cfg_scan_line_h,
             cfg_scan_line_v, cfg_prom_wren);
end
endtask

// Reset between edges and observe asynchronous configuration outputs.
// Also hold reset across clocks to exercise the clocked read mux.
task reset_partial_sequence;
input integer stage;
begin
    @(negedge clk);
    reg_wr    = 2'b00;
    reg_wdata = 8'h00;
    reg_rd    = 6'b000001;
    #2;
    bus_rst = 1'b1;
    #1;
    $display("ASYNC RESET after key %0d: rdata=%02h scale=%b scan_h=%b scan_v=%b prom=%h",
             stage, reg_rdata, cfg_scale_2x_on, cfg_scan_line_h,
             cfg_scan_line_v, cfg_prom_wren);

    repeat (2) @(posedge clk);
    #1;
    $display("RESET HELD after key %0d: rdata=%02h scale=%b scan_h=%b scan_v=%b prom=%h",
             stage, reg_rdata, cfg_scale_2x_on, cfg_scan_line_h,
             cfg_scan_line_v, cfg_prom_wren);

    read_mask(6'b000010);
    read_mask(6'b000100);
    read_mask(6'b100000);

    @(negedge clk);
    #2;
    bus_rst = 1'b0;
    repeat (2) @(posedge clk);
    #1;
    $display("RESET RELEASE after key %0d: rdata=%02h scale=%b scan_h=%b scan_v=%b prom=%h",
             stage, reg_rdata, cfg_scale_2x_on, cfg_scan_line_h,
             cfg_scan_line_v, cfg_prom_wren);
end
endtask

initial begin
    bus_rst   = 1'b0;
    bus_eof   = 1'b0;
    reg_rd    = 6'b0;
    reg_wr    = 2'b0;
    reg_wdata = 8'b0;
    start_n   = 2'b11;
    coin_n    = 2'b11;
    joy1_n    = 6'b111111;
    joy2_n    = 6'b111111;
    dip_sw_A  = 8'h00;
    dip_sw_B  = 8'h00;

    reset_dut;

    // Mixed input capture and individual/multiple reads.
    @(negedge clk);
    start_n  = 2'b01;
    coin_n   = 2'b10;
    bus_eof  = 1'b1;
    joy1_n   = 6'b010101;
    joy2_n   = 6'b101010;
    dip_sw_A = 8'hA5;
    dip_sw_B = 8'h3C;
    repeat (1) @(posedge clk);
    read_mask(6'b000001);
    read_mask(6'b000010);
    read_mask(6'b000100);
    read_mask(6'b001000);
    read_mask(6'b010000);
    read_mask(6'b100000);
    read_mask(6'b000000);
    read_mask(6'b111111);

    // Extend read-mask traversal while mixed input values remain stable.
    for (i = 0; i < 64; i = i + 1) begin
        @(posedge clk);
        read_mask(i[5:0]);
    end

    // Boundary input capture.
    @(negedge clk);
    start_n  = 2'b00;
    coin_n   = 2'b00;
    bus_eof  = 1'b0;
    joy1_n   = 6'b000000;
    joy2_n   = 6'b000000;
    dip_sw_A = 8'hFF;
    dip_sw_B = 8'hFF;
    repeat (1) @(posedge clk);
    read_mask(6'b000001);
    read_mask(6'b000010);
    read_mask(6'b000100);
    read_mask(6'b001000);
    read_mask(6'b010000);
    read_mask(6'b111111);

    // Writable and derived status: retain original cases.
    write_status(8'h00);
    write_status(8'hFF);
    write_status(8'hA5);

    // Exhaustive eight-bit source traversal, using existing timing.
    for (i = 0; i < 256; i = i + 1) begin
        @(posedge clk);
        write_status(i[7:0]);
    end

    // Preserve the original unlocked PROM command and state-1 mismatch.
    reset_dut;
    cfg_command(8'h00);
    cfg_key(8'h19);
    cfg_key(8'h00);
    cfg_key(8'h43);
    cfg_key(8'hFD);
    cfg_key(8'h80);
    @(negedge clk);
    reg_wr = 2'b00;
    #1;
    $display("CONFIG mismatch recovery: rdata=%02h scale=%b scan_h=%b scan_v=%b prom=%h",
             reg_rdata, cfg_scale_2x_on, cfg_scan_line_h,
             cfg_scan_line_v, cfg_prom_wren);

    // Preserve original valid configuration writes.
    reset_dut;
    cfg_command(8'hC0);
    cfg_command(8'hC1);
    cfg_command(8'h82);
    cfg_command(8'hC3);
    cfg_command(8'h00);
    cfg_command(8'h0F);

    // Directly target the uncovered idle mismatch branch.
    // Unlike cfg_command, cfg_key does not prepend unlock keys.
    reset_dut;
    cfg_key(8'h00);
    cfg_key(8'h43);
    cfg_key(8'hFD);
    cfg_key(8'hC0);
    cfg_pause(8'h19);

    // Exercise holds in every key state and mismatches in states 1 and 2.
    cfg_key(8'h19);
    cfg_pause(8'h43);
    cfg_key(8'h00);
    cfg_key(8'h19);
    cfg_key(8'h43);
    cfg_pause(8'hFD);

    // State 2 requires 0xFD: all following bytes are mismatches.
    cfg_key(8'h00);
    cfg_key(8'h19);
    cfg_key(8'h43);
    cfg_key(8'hFC);
    cfg_key(8'hFD);

    // A disabled command must leave the final command state pending.
    cfg_pause(8'hC1);
    cfg_key(8'hC1);
    cfg_pause(8'h00);

    // The completed transaction returned to idle; reject an unkeyed command.
    cfg_key(8'hC0);
    cfg_pause(8'h00);

    // Reset after each key. The first two iterations target the missing
    // FSM transitions 1->0 and 2->0. All stimulus uses top-level ports.
    for (reset_stage = 1; reset_stage <= 3;
         reset_stage = reset_stage + 1) begin
        @(posedge clk);
        cfg_command(8'hC0);
        cfg_command(8'h0F);

        cfg_key(8'h19);
        if (reset_stage >= 2)
            cfg_key(8'h43);
        if (reset_stage >= 3)
            cfg_key(8'hFD);

        reset_partial_sequence(reset_stage);

        // Old trailing keys/command cannot complete the aborted sequence.
        cfg_key(8'h43);
        cfg_key(8'hFD);
        cfg_key(8'hC1);
        cfg_pause(8'h00);

        // Demonstrate recovery with a complete fresh sequence.
        cfg_command(8'hC1);
    end

    // Set and clear every flag address, including the unexported bit 3.
    for (i = 0; i < 4; i = i + 1) begin
        @(posedge clk);
        cfg_command(8'hC0 | i[7:0]);
        cfg_command(8'h80 | i[7:0]);
    end

    // Traverse all PROM write-enable values.
    for (i = 0; i < 16; i = i + 1) begin
        @(posedge clk);
        cfg_command(i[7:0]);
    end

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

reg reset;
reg SCK;
reg SDI;
reg CSB;
reg [7:0] idata;

wire SDO;
wire sdoenb;
wire [7:0] odata;
wire [7:0] oaddr;
wire rdstb;
wire wrstb;
wire pass_thru;
wire pass_thru_delay;
wire pass_thru_reset;

housekeeping_spi uut (
    .reset(reset),
    .SCK(SCK),
    .SDI(SDI),
    .CSB(CSB),
    .SDO(SDO),
    .sdoenb(sdoenb),
    .idata(idata),
    .odata(odata),
    .oaddr(oaddr),
    .rdstb(rdstb),
    .wrstb(wrstb),
    .pass_thru(pass_thru),
    .pass_thru_delay(pass_thru_delay),
    .pass_thru_reset(pass_thru_reset)
);

initial SCK = 1'b0;
always #5 SCK = ~SCK;

task observe;
    input [127:0] tag;
    begin
        $display("%s SDO=%b sdoenb=%b odata=%02h oaddr=%02h rdstb=%b wrstb=%b pass_thru=%b pass_thru_delay=%b pass_thru_reset=%b",
                 tag, SDO, sdoenb, odata, oaddr, rdstb, wrstb,
                 pass_thru, pass_thru_delay, pass_thru_reset);
    end
endtask

task reset_dut;
    begin
        CSB = 1'b1;
        reset = 1'b1;
        SDI = 1'b0;
        idata = 8'h00;
        #2;
        reset = 1'b0;
        repeat (1) @(posedge SCK);
        CSB = 1'b0;
        #1;
        observe("reset released");
    end
endtask

task send_bit;
    input bit_value;
    input [127:0] tag;
    begin
        SDI = bit_value;
        @(posedge SCK);
        @(negedge SCK);
        observe(tag);
    end
endtask

task send_byte;
    input [7:0] value;
    input [127:0] tag;
    integer i;
    begin
        for (i = 7; i >= 0; i = i - 1)
            send_bit(value[i], tag);
    end
endtask

task send_command;
    input [7:0] command;
    begin
        send_byte(command, "command");
    end
endtask

task send_address;
    input [7:0] address;
    begin
        send_byte(address, "address");
    end
endtask

task send_data;
    input [7:0] data_byte;
    begin
        send_byte(data_byte, "data");
    end
endtask

initial begin
    reset = 1'b1;
    SDI = 1'b0;
    CSB = 1'b1;
    idata = 8'h00;
    #2;
    reset = 1'b0;

    // Test Case 1: fixed-length write of one byte.
    reset_dut;
    send_command(8'b10001000);
    send_address(8'h2A);
    send_data(8'h3C);
    #1;
    observe("fixed write complete");
    CSB = 1'b1;
    #1;
    observe("fixed write framed");

    // Test Case 2: fixed-length read of two bytes.
    reset_dut;
    idata = 8'hA6;
    send_command(8'b01010000);
    send_address(8'h40);
    send_data(8'h00);
    idata = 8'h5D;
    send_data(8'h00);
    #1;
    observe("fixed read complete");
    CSB = 1'b1;
    #1;
    observe("fixed read framed");

    // Test Case 3: simultaneous read/write modes and continuous transfer.
    reset_dut;
    idata = 8'h96;
    send_command(8'b11000000);
    send_address(8'h7E);
    send_data(8'h81);
    idata = 8'h3A;
    send_data(8'h24);
    #1;
    observe("continuous transfer active");
    CSB = 1'b1;
    #1;
    observe("continuous transfer framed");

    // Test Case 4: asynchronous reset in the middle of command capture.
    reset_dut;
    send_bit(1'b1, "partial command");
    send_bit(1'b1, "partial command");
    reset = 1'b1;
    #1;
    observe("reset during transaction");
    reset = 1'b0;
    CSB = 1'b0;
    send_command(8'b10001000);
    send_address(8'h11);
    send_data(8'hE7);
    CSB = 1'b1;
    #1;
    observe("post-reset transaction");

    // Test Case 5: correctly selected pass-through command.
    // Bit 2 is the pass-through command bit.
    reset_dut;
    send_command(8'b00000100);
    #1;
    observe("pass-through command captured");
    send_bit(1'b0, "pass-through active");
    send_bit(1'b1, "pass-through data");
    send_bit(1'b0, "pass-through data");
    CSB = 1'b1;
    #1;
    observe("pass-through framed");

    // Test Case 6: continuous write-only transfer over multiple bytes.
    // Zero transfer length selects continuous mode.
    reset_dut;
    send_command(8'b10000000);
    send_address(8'h20);
    send_data(8'h12);
    send_data(8'h34);
    send_data(8'h56);
    #1;
    observe("continuous write sequence active");
    CSB = 1'b1;
    #1;
    observe("continuous write sequence framed");

    // Test Case 7: fixed-length simultaneous read/write transfer of three bytes.
    // Length field is 011, so the nonzero decrement path is exercised.
    reset_dut;
    idata = 8'hC3;
    send_command(8'b11011000);
    send_address(8'h55);
    send_data(8'hA1);
    idata = 8'h5A;
    send_data(8'hB2);
    idata = 8'hE7;
    send_data(8'hC3);
    #1;
    observe("fixed three-byte transfer complete");
    CSB = 1'b1;
    #1;
    observe("fixed three-byte transfer framed");

    // Test Case 8: read-only fixed-length transfer of three bytes.
    reset_dut;
    idata = 8'h81;
    send_command(8'b01011000);
    send_address(8'h68);
    send_data(8'h00);
    idata = 8'h2D;
    send_data(8'h00);
    idata = 8'hF0;
    send_data(8'h00);
    #1;
    observe("read-only multi-byte transfer complete");
    CSB = 1'b1;
    #1;
    observe("read-only multi-byte transfer framed");

    // Test Case 9: chip-select interruption during active continuous data.
    reset_dut;
    send_command(8'b10000000);
    send_address(8'h91);
    send_bit(1'b1, "interrupted write data");
    send_bit(1'b0, "interrupted write data");
    CSB = 1'b1;
    #1;
    observe("chip-select reset during data");
    CSB = 1'b0;
    send_command(8'b10001000);
    send_address(8'h09);
    send_data(8'h5E);
    CSB = 1'b1;
    #1;
    observe("transaction after chip-select reset");

    // Test Case 10: reset assertion during an active read transfer.
    reset_dut;
    idata = 8'h3C;
    send_command(8'b01000000);
    send_address(8'hA4);
    send_bit(1'b0, "active read data");
    send_bit(1'b0, "active read data");
    reset = 1'b1;
    #1;
    observe("reset during active read");
    reset = 1'b0;
    CSB = 1'b0;
    send_command(8'b10001000);
    send_address(8'h17);
    send_data(8'hD9);
    CSB = 1'b1;
    #1;
    observe("post-read-reset transaction");

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

parameter WIDTH_MODULUS = 4;
parameter ORDER = 3;

localparam [WIDTH_MODULUS-1:0] MAX_INPUT =
    {WIDTH_MODULUS{1'b1}};
localparam [WIDTH_MODULUS-1:0] HALF_INPUT =
    MAX_INPUT ^ (MAX_INPUT >> 1);
localparam integer WINDOW = 16 * ORDER + 16;

// Inputs
reg clk;
reg rst;
reg [WIDTH_MODULUS-1:0] data_in;

// Outputs
wire [ORDER-1:0] data_out;

integer i, k;
integer seed;
reg [WIDTH_MODULUS-1:0] level;

// Instantiate the Unit Under Test (UUT)
mash_mod #(
    .WIDTH_MODULUS(WIDTH_MODULUS),
    .ORDER(ORDER)
) uut (
    .clk(clk),
    .rst(rst),
    .data_in(data_in),
    .data_out(data_out)
);

// clk toggle generate
initial clk = 0;
always #5 clk = ~clk;

task observe;
    input integer test_id;
    begin
        $display("t=%0t test=%0d rst=%b data_in=%0d data_out=%b unsigned=%0d signed=%0d",
                 $time, test_id, rst, data_in, data_out,
                 data_out, $signed(data_out));
    end
endtask

task sample;
    input [WIDTH_MODULUS-1:0] value;
    input integer test_id;
    begin
        @(negedge clk);
        data_in = value;
        @(posedge clk);
        #1;
        observe(test_id);
    end
endtask

task hold_input;
    input [WIDTH_MODULUS-1:0] value;
    input integer count;
    input integer test_id;
    integer n;
    begin
        for (n = 0; n < count; n = n + 1)
            sample(value, test_id);
    end
endtask

task reset_dut;
    input integer test_id;
    begin
        @(negedge clk);
        #2;
        rst = 1;
        data_in = MAX_INPUT;
        #1;
        observe(test_id);
        repeat (2) @(posedge clk);
        #1;
        observe(test_id);
        @(negedge clk);
        rst = 0;
        data_in = 0;
    end
endtask

initial begin
    // Initialize Inputs
    rst = 1;
    data_in = 0;
    seed = 32'h13579bdf;
    #1;
    observe(0);

    // Wait 100 ns for global reset to finish
    #100;
    observe(0);
    @(negedge clk);
    rst = 0;

    // Test 1: zero-input startup
    hold_input(0, WINDOW, 1);

    // Tests 10-16: independent constant-input boundaries
    for (k = 0; k < 7; k = k + 1) begin
        reset_dut(10 + k);
        case (k)
            0: level = 0;
            1: level = 1;
            2: level = HALF_INPUT - 1'b1;
            3: level = HALF_INPUT;
            4: level = HALF_INPUT | 1'b1;
            5: level = MAX_INPUT - 1'b1;
            6: level = MAX_INPUT;
        endcase
        hold_input(level, WINDOW, 10 + k);
    end

    // Test 20: impulse and subsequent cascade activity
    reset_dut(20);
    sample(MAX_INPUT, 20);
    hold_input(0, WINDOW, 20);

    // Test 21: maximum-rate input transitions
    reset_dut(21);
    for (i = 0; i < WINDOW; i = i + 1) begin
        sample(0, 21);
        sample(MAX_INPUT, 21);
    end
    hold_input(0, WINDOW, 21);

    // Test 22: ramp through the upper boundary and wrap to zero
    reset_dut(22);
    level = MAX_INPUT - 3;
    for (i = 0; i < WINDOW; i = i + 1) begin
        sample(level, 22);
        level = level + 1'b1;
    end
    hold_input(0, WINDOW, 22);

    // Test 23: reproducible mixed input history
    reset_dut(23);
    for (i = 0; i < 2 * WINDOW; i = i + 1)
        sample($random(seed), 23);
    hold_input(0, WINDOW, 23);

    // Test 24: reset during startup and after sustained activity
    reset_dut(24);
    hold_input(MAX_INPUT, 2, 24);
    reset_dut(24);
    hold_input(MAX_INPUT, WINDOW, 24);
    reset_dut(24);
    hold_input(0, WINDOW, 24);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

// Inputs
reg clk;
reg wren;
reg [8:0] wrad;
reg [51:0] data;
reg rden;
reg [8:0] rdad;

// Outputs
wire [51:0] q;

integer i;
integer j;
reg [51:0] pattern;

mcp3_ram512x052 uut (
    .clk(clk),
    .wren(wren),
    .wrad(wrad),
    .data(data),
    .rden(rden),
    .rdad(rdad),
    .q(q)
);

initial clk = 0;
always #5 clk = ~clk;

// Each call applies one cycle and prints the only output before/after its edge.
task access;
    input [255:0] label;
    input we;
    input [8:0] wa;
    input [51:0] wd;
    input re;
    input [8:0] ra;
    begin
        @(negedge clk);
        wren = we;
        wrad = wa;
        data = wd;
        rden = re;
        rdad = ra;
        #1;
        $display("%0s pre t=%0t we=%b wa=%0d data=%013h re=%b ra=%0d q=%013h",
                 label, $time, wren, wrad, data, rden, rdad, q);
        @(posedge clk);
        #1;
        $display("%0s post t=%0t we=%b wa=%0d data=%013h re=%b ra=%0d q=%013h",
                 label, $time, wren, wrad, data, rden, rdad, q);
    end
endtask

initial begin
    wren = 0;
    wrad = 0;
    data = 0;
    rden = 0;
    rdad = 0;
    pattern = 0;

    // No reset interface; wait 100 ns before starting stimulus.
    #100;

    // Startup and full-memory initialization.
    $display("startup t=%0t q=%013h", $time, q);
    access("unwritten read", 0, 9'd511, 52'd0, 1, 9'd511);
    for (i = 0; i < 512; i = i + 1) begin
        #1;
        access("initialize", 1, i[8:0], {43'd0, i[8:0]}, 0, 9'd0);
    end
    for (i = 0; i < 512; i = i + 1) begin
        #1;
        access("address sweep", 0, i[8:0], 52'd0, 1, i[8:0]);
    end

    // Disabled writes, with equal read/write addresses and reading enabled.
    for (i = 0; i < 512; i = i + 1) begin
        #1;
        access("disabled write", 0, i[8:0],
               ~{43'd0, i[8:0]}, 1, i[8:0]);
    end
    for (i = 0; i < 512; i = i + 1) begin
        #1;
        access("reread after inhibited writes", 0, 9'd0, 52'd0, 1, i[8:0]);
    end

    // Repeated overwrite and full-width data patterns.
    for (i = 0; i < 4; i = i + 1) begin
        #1;
        case (i)
            0: pattern = 52'h0000000000000;
            1: pattern = 52'hfffffffffffff;
            2: pattern = 52'haaaaaaaaaaaaa;
            3: pattern = 52'h5555555555555;
        endcase
        access("fixed pattern write", 1, 9'd256, pattern, 0, 9'd256);
        access("fixed pattern read", 0, 9'd256, 52'd0, 1, 9'd256);
    end
    for (i = 0; i < 52; i = i + 1) begin
        #1;
        pattern = 52'd1 << i;
        access("walking one write", 1, 9'd256, pattern, 0, 9'd256);
        access("walking one read", 0, 9'd256, 52'd0, 1, 9'd256);
        access("walking zero write", 1, 9'd256, ~pattern, 0, 9'd256);
        access("walking zero read", 0, 9'd256, 52'd0, 1, 9'd256);
    end

    // Output retention with both enables low or only writing enabled.
    access("hold setup write", 1, 9'd0, 52'haaaaaaaaaaaaa, 0, 9'd0);
    access("hold setup read", 0, 9'd0, 52'd0, 1, 9'd0);
    access("idle equal addresses", 0, 9'd0, 52'hfffffffffffff, 0, 9'd0);
    access("idle changed addresses", 0, 9'd511, 52'd0, 0, 9'd511);
    access("write only equal addresses", 1, 9'd0, 52'h5555555555555, 0, 9'd0);
    access("write only different addresses", 1, 9'd511,
           52'hfffffffffffff, 0, 9'd0);
    access("resume read", 0, 9'd0, 52'd0, 1, 9'd0);
    access("read other written word", 0, 9'd511, 52'd0, 1, 9'd511);

    // Independent simultaneous accesses in both address directions.
    access("parallel setup low", 1, 9'd0, 52'd0, 0, 9'd0);
    access("parallel setup high", 1, 9'd511, 52'hfffffffffffff, 0, 9'd0);
    access("parallel setup read", 0, 9'd0, 52'd0, 1, 9'd0);
    access("write low read high", 1, 9'd0, 52'haaaaaaaaaaaaa, 1, 9'd511);
    access("write high read low", 1, 9'd511, 52'h5555555555555, 1, 9'd0);
    access("parallel readback low", 0, 9'd0, 52'd0, 1, 9'd0);
    access("parallel readback high", 0, 9'd511, 52'd0, 1, 9'd511);

    // Boundary collisions, unknown retention, and read recovery.
    for (i = 0; i < 2; i = i + 1) begin
        #1;
        j = i * 511;
        access("collision setup write", 1, j[8:0], 52'd0, 0, j[8:0]);
        access("collision setup read", 0, j[8:0], 52'd0, 1, j[8:0]);
        access("same address collision", 1, j[8:0],
               52'hfffffffffffff, 1, j[8:0]);
        access("hold collision output", 0, j[8:0], 52'd0, 0, j[8:0]);
        access("collision write readback", 0, j[8:0], 52'd0, 1, j[8:0]);
    end

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

reg clk;
reg resetn;
reg [7:0] i2c_baud_clk_l;
reg [7:0] i2c_baud_clk_h;
reg i2c_tx_on;
reg i2c_stop;
reg i2c_start;
reg i2c_rx_on;
reg [7:0] i2c_tx_reg;
reg sda_external;

wire i2c_sda;
wire i2c_scl;
wire i2c_ack;
wire i2c_busy;
wire [7:0] i2c_rx_reg;

assign i2c_sda = sda_external;

i2c_master uut (
    .clk            (clk),
    .resetn         (resetn),
    .i2c_baud_clk_l (i2c_baud_clk_l),
    .i2c_baud_clk_h (i2c_baud_clk_h),
    .i2c_sda        (i2c_sda),
    .i2c_scl        (i2c_scl),
    .i2c_tx_on      (i2c_tx_on),
    .i2c_stop       (i2c_stop),
    .i2c_start      (i2c_start),
    .i2c_rx_on      (i2c_rx_on),
    .i2c_ack        (i2c_ack),
    .i2c_busy       (i2c_busy),
    .i2c_tx_reg     (i2c_tx_reg),
    .i2c_rx_reg     (i2c_rx_reg)
);

initial clk = 1'b0;
always #5 clk = ~clk;

task reset_dut;
begin
    resetn = 1'b0;
    i2c_tx_on = 1'b0;
    i2c_rx_on = 1'b0;
    i2c_start = 1'b0;
    i2c_stop = 1'b0;
    i2c_tx_reg = 8'h00;
    i2c_baud_clk_l = 8'h01;
    i2c_baud_clk_h = 8'h00;
    sda_external = 1'bz;
    #2;
    resetn = 1'b1;
    repeat (2) @(posedge clk);
end
endtask

task observe;
input [8*48-1:0] tag;
begin
    #1 $display("%s: sda=%b scl=%b rx_reg=%h busy=%b ack=%b",
               tag, i2c_sda, i2c_scl, i2c_rx_reg, i2c_busy, i2c_ack);
end
endtask

task transmit_case;
input [7:0] data;
input hold_sda_low;
begin
    reset_dut;
    i2c_tx_reg = data;
    sda_external = hold_sda_low ? 1'b0 : 1'bz;
    i2c_tx_on = 1'b1;
    @(posedge clk);
    repeat (20) @(posedge clk);
    observe("Transmit");
    i2c_tx_on = 1'b0;
    sda_external = 1'bz;
    repeat (2) @(posedge clk);
end
endtask

task receive_case;
reg [7:0] pattern;
integer i;
begin
    reset_dut;
    pattern = 8'b10100110;
    sda_external = pattern[0];
    i2c_rx_on = 1'b1;
    @(posedge clk);

    for (i = 1; i < 8; i = i + 1) begin
        @(posedge clk);
        sda_external = pattern[i];
        @(posedge clk);
    end

    repeat (4) @(posedge clk);
    observe("Receive");
    i2c_rx_on = 1'b0;
    sda_external = 1'bz;
    repeat (2) @(posedge clk);
end
endtask

task transmit_non_tick_start;
input [7:0] data;
input hold_sda_low;
begin
    reset_dut;
    i2c_baud_clk_l = 8'h02;
    i2c_baud_clk_h = 8'h00;
    i2c_tx_reg = data;
    sda_external = hold_sda_low ? 1'b0 : 1'bz;
    i2c_tx_on = 1'b1;

    @(posedge clk);
    repeat (22) @(posedge clk);
    observe("Transmit non-tick qualification");

    i2c_tx_on = 1'b0;
    sda_external = 1'bz;
    repeat (2) @(posedge clk);
end
endtask

task receive_non_tick_start;
reg [7:0] pattern;
integer i;
begin
    reset_dut;
    i2c_baud_clk_l = 8'h02;
    i2c_baud_clk_h = 8'h00;
    pattern = 8'b01011001;
    sda_external = pattern[0];
    i2c_rx_on = 1'b1;

    @(posedge clk);

    for (i = 1; i < 8; i = i + 1) begin
        @(posedge clk);
        sda_external = pattern[i];
        @(posedge clk);
    end

    repeat (8) @(posedge clk);
    observe("Receive non-tick qualification");

    i2c_rx_on = 1'b0;
    sda_external = 1'bz;
    repeat (2) @(posedge clk);
end
endtask

// The request is asserted immediately after reset while the divider is
// configured to three.  The first two clocks are non-tick cycles.
task directed_tx_non_tick;
begin
    reset_dut;
    i2c_baud_clk_l = 8'h03;
    i2c_baud_clk_h = 8'h00;
    i2c_tx_reg = 8'hC3;
    sda_external = 1'bz;
    i2c_tx_on = 1'b1;

    @(posedge clk);
    @(posedge clk);
    repeat (20) @(posedge clk);
    observe("Directed TX idle non-tick");

    i2c_tx_on = 1'b0;
    sda_external = 1'bz;
    repeat (2) @(posedge clk);
end
endtask

task directed_rx_non_tick;
begin
    reset_dut;
    i2c_baud_clk_l = 8'h03;
    i2c_baud_clk_h = 8'h00;
    sda_external = 1'b1;
    i2c_rx_on = 1'b1;

    @(posedge clk);
    @(posedge clk);
    repeat (20) @(posedge clk);
    observe("Directed RX idle non-tick");

    i2c_rx_on = 1'b0;
    sda_external = 1'bz;
    repeat (2) @(posedge clk);
end
endtask

// An unknown enable value prevents the outer busy-termination condition
// from being selected, while the nested if/else tests treat the enable
// as false.  This reaches the defensive no-enable branch paths.
task ambiguous_tx_active;
begin
    reset_dut;
    i2c_tx_reg = 8'hA5;
    sda_external = 1'bz;
    i2c_tx_on = 1'b1;

    // Divider value one accepts the transmit request on the next clock.
    @(posedge clk);
    i2c_tx_on = 1'bx;
    repeat (20) @(posedge clk);
    observe("Unknown TX enable active");

    i2c_tx_on = 1'b0;
    sda_external = 1'bz;
    repeat (2) @(posedge clk);
end
endtask

task ambiguous_rx_active;
begin
    reset_dut;
    sda_external = 1'b0;
    i2c_rx_on = 1'b1;

    @(posedge clk);
    i2c_rx_on = 1'bx;
    repeat (20) @(posedge clk);
    observe("Unknown RX enable active");

    i2c_rx_on = 1'b0;
    sda_external = 1'bz;
    repeat (2) @(posedge clk);
end
endtask

initial begin
    reset_dut;
    observe("Reset");

    reset_dut;
    i2c_baud_clk_l = 8'h02;
    i2c_start = 1'b1;
    repeat (3) @(posedge clk);
    i2c_start = 1'b0;
    observe("Divider and start active");
    repeat (3) @(posedge clk);
    observe("Divider and start complete");

    reset_dut;
    i2c_baud_clk_l = 8'h02;
    i2c_start = 1'b1;
    repeat (3) @(posedge clk);
    observe("Held start active");
    repeat (2) @(posedge clk);
    observe("Held start completion");
    i2c_start = 1'b0;
    repeat (2) @(posedge clk);

    reset_dut;
    i2c_stop = 1'b1;
    @(posedge clk);
    i2c_stop = 1'b0;
    observe("Stop active");
    repeat (2) @(posedge clk);
    observe("Stop complete");

    reset_dut;
    i2c_baud_clk_l = 8'h02;
    i2c_stop = 1'b1;
    @(posedge clk);
    observe("Stop non-tick qualification");
    repeat (2) @(posedge clk);
    i2c_stop = 1'b0;
    observe("Stop after qualified tick");
    repeat (2) @(posedge clk);

    reset_dut;
    i2c_start = 1'b1;
    i2c_stop = 1'b1;
    @(posedge clk);
    i2c_start = 1'b0;
    i2c_stop = 1'b0;
    observe("Simultaneous start and stop");
    repeat (2) @(posedge clk);
    observe("Simultaneous control completion");

    transmit_case(8'hA5, 1'b0);
    transmit_case(8'h3C, 1'b1);
    transmit_case(8'h00, 1'b0);
    transmit_case(8'hFF, 1'b1);

    reset_dut;
    i2c_tx_reg = 8'h96;
    i2c_tx_on = 1'b1;
    i2c_rx_on = 1'b1;
    sda_external = 1'b0;
    @(posedge clk);
    repeat (20) @(posedge clk);
    observe("Transmit priority over receive");
    i2c_tx_on = 1'b0;
    i2c_rx_on = 1'b0;
    sda_external = 1'bz;
    repeat (2) @(posedge clk);

    transmit_non_tick_start(8'h81, 1'b0);
    transmit_non_tick_start(8'h7E, 1'b1);

    receive_case;
    receive_non_tick_start;

    reset_dut;
    i2c_tx_reg = 8'h5A;
    i2c_tx_on = 1'b1;
    @(posedge clk);
    repeat (3) @(posedge clk);
    i2c_tx_on = 1'b0;
    repeat (3) @(posedge clk);
    observe("Transfer enable removed while busy");
    repeat (2) @(posedge clk);

    reset_dut;
    i2c_rx_on = 1'b1;
    sda_external = 1'b1;
    @(posedge clk);
    repeat (3) @(posedge clk);
    i2c_rx_on = 1'b0;
    repeat (3) @(posedge clk);
    observe("Receive enable removed while busy");
    sda_external = 1'bz;
    repeat (2) @(posedge clk);

    directed_tx_non_tick;
    directed_rx_non_tick;

    ambiguous_tx_active;
    ambiguous_rx_active;

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam MUL    = 3'b001;
localparam MULH   = 3'b010;
localparam MULHU  = 3'b011;
localparam MULHSU = 3'b100;
localparam MULW   = 3'b101;
localparam NV = 22;

// Inputs
reg clk;
reg rstn;
reg ctrl_mdu_fake_gen_flag;
reg gpr_mdu_mul_data_vld;
reg [63:0] gpr_mdu_mul_reg1_data;
reg [63:0] gpr_mdu_mul_reg2_data;
reg [2:0] de_mdu_mul_type;

// Outputs
wire mdu_wb_mul_vld;
wire [63:0] mdu_wb_mul_wdata;
wire mdu_wb_mul_fake_vld;

reg [63:0] operand_a [0:NV-1];
reg [63:0] operand_b [0:NV-1];
integer op_index, i, depth, j;
integer test_id;

// Instantiate the Unit Under Test (UUT)
mul uut (
    .clk(clk),
    .rstn(rstn),
    .ctrl_mdu_fake_gen_flag(ctrl_mdu_fake_gen_flag),
    .gpr_mdu_mul_data_vld(gpr_mdu_mul_data_vld),
    .gpr_mdu_mul_reg1_data(gpr_mdu_mul_reg1_data),
    .gpr_mdu_mul_reg2_data(gpr_mdu_mul_reg2_data),
    .de_mdu_mul_type(de_mdu_mul_type),
    .mdu_wb_mul_vld(mdu_wb_mul_vld),
    .mdu_wb_mul_wdata(mdu_wb_mul_wdata),
    .mdu_wb_mul_fake_vld(mdu_wb_mul_fake_vld)
);

// clk toggle generate
initial clk = 0; //clk is initialized as 0
always #5 clk = ~clk;

task observe;
begin
    $display("t=%0t test=%0d rstn=%b in_valid=%b fake=%b op=%b a=%h b=%h | mdu_wb_mul_vld=%b mdu_wb_mul_wdata=%h mdu_wb_mul_fake_vld=%b",
             $time, test_id, rstn, gpr_mdu_mul_data_vld,
             ctrl_mdu_fake_gen_flag, de_mdu_mul_type,
             gpr_mdu_mul_reg1_data, gpr_mdu_mul_reg2_data,
             mdu_wb_mul_vld, mdu_wb_mul_wdata,
             mdu_wb_mul_fake_vld);
end
endtask

task cycle;
    input valid_in;
    input fake_in;
    input [2:0] operation;
    input [63:0] a_in;
    input [63:0] b_in;
begin
    @(negedge clk);
    gpr_mdu_mul_data_vld = valid_in;
    ctrl_mdu_fake_gen_flag = fake_in;
    de_mdu_mul_type = operation;
    gpr_mdu_mul_reg1_data = a_in;
    gpr_mdu_mul_reg2_data = b_in;
    @(posedge clk);
    #1;
    observe;
end
endtask

task drain;
    integer k;
begin
    for (k = 0; k < 4; k = k + 1) begin
        cycle(1'b0, 1'b0, k, 64'h123456789abcdef0,
              64'hfedcba9876543210);
        #1;
    end
end
endtask

task reset_dut;
begin
    @(negedge clk);
    rstn = 0;
    gpr_mdu_mul_data_vld = 0;
    ctrl_mdu_fake_gen_flag = 0;
    de_mdu_mul_type = MUL;
    gpr_mdu_mul_reg1_data = 0;
    gpr_mdu_mul_reg2_data = 0;
    #1;
    observe;
    repeat (2) @(posedge clk);
    #1;
    observe;
    @(negedge clk);
    rstn = 1;
end
endtask

initial begin
    // Initialize Inputs
    rstn = 0;
    ctrl_mdu_fake_gen_flag = 0;
    gpr_mdu_mul_data_vld = 0;
    gpr_mdu_mul_reg1_data = 0;
    gpr_mdu_mul_reg2_data = 0;
    de_mdu_mul_type = MUL;
    test_id = 0;

    operand_a[0]  = 64'd0;                 operand_b[0]  = 64'hffffffffffffffff;
    operand_a[1]  = 64'h8000000000000000;   operand_b[1]  = 64'd0;
    operand_a[2]  = 64'd1;                 operand_b[2]  = 64'd1;
    operand_a[3]  = 64'd3;                 operand_b[3]  = 64'd7;
    operand_a[4]  = -64'd3;                operand_b[4]  = 64'd7;
    operand_a[5]  = 64'd3;                 operand_b[5]  = -64'd7;
    operand_a[6]  = -64'd3;                operand_b[6]  = -64'd7;
    operand_a[7]  = 64'h8000000000000000;   operand_b[7]  = 64'd1;
    operand_a[8]  = 64'h8000000000000000;   operand_b[8]  = 64'hffffffffffffffff;
    operand_a[9]  = 64'h8000000000000000;   operand_b[9]  = 64'h8000000000000000;
    operand_a[10] = 64'h7fffffffffffffff;   operand_b[10] = 64'h7fffffffffffffff;
    operand_a[11] = 64'hffffffffffffffff;   operand_b[11] = 64'hffffffffffffffff;
    operand_a[12] = 64'd1;                 operand_b[12] = 64'hffffffffffffffff;
    operand_a[13] = 64'h000000007fffffff;   operand_b[13] = 64'd1;
    operand_a[14] = 64'h0000000080000000;   operand_b[14] = 64'd1;
    operand_a[15] = 64'h00000000ffffffff;   operand_b[15] = 64'd1;
    operand_a[16] = 64'h0000000100000000;   operand_b[16] = 64'h0000000100000000;
    operand_a[17] = 64'h0000000040000000;   operand_b[17] = 64'd2;
    operand_a[18] = 64'h1234567880000001;   operand_b[18] = 64'habcdef0100000003;
    operand_a[19] = 64'h0123456789abcdef;   operand_b[19] = 64'hfedcba9876543210;
    operand_a[20] = 64'hfedcba9876543210;   operand_b[20] = 64'h0123456789abcdef;
    operand_a[21] = 64'haaaaaaaaaaaaaaaa;   operand_b[21] = 64'h5555555555555555;

    // Wait 100 ns for global reset to finish
    #1;
    observe;
    #99;

    // Test Case 1: isolated latency, then arithmetic stream for every opcode.
    for (op_index = 0; op_index < 8; op_index = op_index + 1) begin
        test_id = 100 + op_index;
        reset_dut;
        cycle(1'b1, 1'b0, op_index, -64'd3, 64'd7);
        drain;
        for (i = 0; i < NV; i = i + 1) begin
            cycle(1'b1, 1'b0, op_index, operand_a[i], operand_b[i]);
            #1;
        end
        drain;
        #1;
    end

    // Test Case 2: back-to-back operation changes and bubbles.
    test_id = 200;
    reset_dut;
    for (i = 0; i < NV; i = i + 1) begin
        cycle(1'b1, 1'b0, i % 8, operand_a[i], operand_b[i]);
        #1;
    end
    drain;
    for (i = 0; i < 8; i = i + 1) begin
        cycle(1'b1, 1'b0, i, operand_a[i + 4], operand_b[i + 4]);
        cycle(1'b0, 1'b0, 7 - i, operand_b[i + 4], operand_a[i + 4]);
        #1;
    end
    drain;

    // Test Case 3: fake bursts, invalid fake inputs, and overlapping outputs.
    test_id = 300;
    reset_dut;
    for (i = 0; i < 4; i = i + 1) begin
        cycle(1'b1, 1'b1, i + 1, operand_a[i + 4], operand_b[i + 4]);
        #1;
    end
    cycle(1'b0, 1'b1, MULHU, 64'hffffffffffffffff, 64'd9);
    drain;
    for (i = 0; i < 4; i = i + 1) begin
        cycle(1'b1, 1'b0, i + 1, operand_a[i + 8], operand_b[i + 8]);
        #1;
    end
    cycle(1'b1, 1'b1, MULW, -64'd11, 64'd13);
    cycle(1'b1, 1'b0, MULHSU, -64'd17, 64'hffffffffffffffff);
    cycle(1'b1, 1'b1, MULH, 64'd19, -64'd23);
    cycle(1'b0, 1'b1, MULHU, 64'd29, 64'd31);
    cycle(1'b0, 1'b0, MUL, 64'd37, 64'd41);
    drain;

    // Test Case 4: asynchronous reset at different pipeline occupancies.
    for (depth = 1; depth <= 4; depth = depth + 1) begin
        test_id = 400 + depth;
        reset_dut;
        for (j = 0; j < depth; j = j + 1) begin
            cycle(1'b1, 1'b0, j + 1, operand_a[j + 8], operand_b[j + 8]);
            #1;
        end
        #1;
        rstn = 0;
        gpr_mdu_mul_data_vld = 0;
        #1;
        observe;
        cycle(1'b1, 1'b0, MUL, 64'd43, 64'd47);
        cycle(1'b1, 1'b1, MULW, -64'd53, 64'd59);
        @(negedge clk);
        gpr_mdu_mul_data_vld = 0;
        ctrl_mdu_fake_gen_flag = 0;
        rstn = 1;
        drain;
        cycle(1'b1, 1'b0, MULW, -64'd61, 64'd67);
        drain;
        #1;
    end

    // Test Case 5: reset while normal-result and fake-valid are active.
    test_id = 500;
    reset_dut;
    for (i = 0; i < 4; i = i + 1) begin
        cycle(1'b1, 1'b0, i + 1, operand_a[i + 18], operand_b[i + 18]);
        #1;
    end
    cycle(1'b1, 1'b1, MULW, 64'd71, -64'd73);
    #1;
    rstn = 0;
    gpr_mdu_mul_data_vld = 0;
    ctrl_mdu_fake_gen_flag = 0;
    #1;
    observe;
    repeat (2) @(posedge clk);
    #1;
    observe;
    @(negedge clk);
    rstn = 1;
    drain;
    cycle(1'b1, 1'b1, MUL, 64'd79, 64'd83);
    cycle(1'b1, 1'b0, MULH, -64'd89, 64'd97);
    drain;

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

reg clk;
reg rst_n_i;

reg signed [7:0]  data0_i;
reg               valid0_i;
reg               last0_i;
wire              ready0_o;

reg signed [23:0] data1_w_i;
reg signed [47:0] data1_b_i;
reg               valid1_i;
reg               last1_i;
wire              ready1_o;

wire signed [71:0] data_o;
wire               valid_o;
wire               last_o;
reg                ready_i;

mac uut (
