    .data1_w_i (data1_w_i),
    .data1_b_i (data1_b_i),
    .valid1_i  (valid1_i),
    .last1_i   (last1_i),
    .ready1_o  (ready1_o),
    .data_o    (data_o),
    .valid_o   (valid_o),
    .last_o    (last_o),
    .ready_i   (ready_i)
);

initial clk = 0;

always #5 clk = ~clk;

task reset_dut;
begin
    rst_n_i   = 0;
    data0_i   = 0;
    valid0_i  = 0;
    last0_i   = 0;
    data1_w_i = 0;
    data1_b_i = 0;
    valid1_i  = 0;
    last1_i   = 0;
    ready_i   = 0;
    repeat (2) @(posedge clk);
    #1;
    rst_n_i   = 1;
    @(posedge clk);
    #1;
end
endtask

task send_sample;
    input signed [7:0]  scalar;
    input signed [7:0]  w0;
    input signed [7:0]  w1;
    input signed [7:0]  w2;
    input signed [15:0] b0;
    input signed [15:0] b1;
    input signed [15:0] b2;
    input               v0;
    input               v1;
    input               l0;
    input               l1;
begin
    @(negedge clk);
    data0_i   = scalar;
    data1_w_i = {w2, w1, w0};
    data1_b_i = {b2, b1, b0};
    valid0_i  = v0;
    valid1_i  = v1;
    last0_i   = l0;
    last1_i   = l1;
    @(posedge clk);
end
endtask

task observe_outputs;
    input integer test_id;
begin
    repeat (2) @(posedge clk);
    #1;
    $display("TC%0d data_o=%h valid_o=%b last_o=%b ready0_o=%b ready1_o=%b",
             test_id, data_o, valid_o, last_o, ready0_o, ready1_o);
end
endtask

integer k;

initial begin
    reset_dut;
    $display("TC1_RESET data_o=%h valid_o=%b last_o=%b ready0_o=%b ready1_o=%b",
             data_o, valid_o, last_o, ready0_o, ready1_o);

    @(negedge clk);
    ready_i = 1;
    @(posedge clk);
    #1;
    $display("TC1_READY_HIGH data_o=%h valid_o=%b last_o=%b ready0_o=%b ready1_o=%b",
             data_o, valid_o, last_o, ready0_o, ready1_o);

    @(negedge clk);
    ready_i = 0;
    @(posedge clk);
    #1;
    $display("TC1_READY_LOW data_o=%h valid_o=%b last_o=%b ready0_o=%b ready1_o=%b",
             data_o, valid_o, last_o, ready0_o, ready1_o);

    reset_dut;
    send_sample(-8'sd128, 8'sd127, -8'sd128, 8'sd1,
                16'sh7fff, -16'sh8000, 16'sd0,
                1, 1, 1, 1);
    observe_outputs(2);

    reset_dut;
    send_sample(8'sd2,  8'sd3,  -8'sd2,  8'sd1,
                16'sd10, 16'sd20, -16'sd30,
                1, 1, 1, 0);
    send_sample(-8'sd4, 8'sd5, 8'sd6, -8'sd7,
                16'sd10, 16'sd20, -16'sd30,
                1, 1, 1, 0);
    send_sample(8'sd8,  -8'sd9, 8'sd10, 8'sd11,
                16'sd10, 16'sd20, -16'sd30,
                1, 1, 1, 1);
    observe_outputs(3);

    reset_dut;
    send_sample(8'sd12, 8'sd2, 8'sd3, 8'sd4,
                16'sd1, 16'sd2, 16'sd3,
                1, 0, 0, 0);
    send_sample(8'sd13, 8'sd2, 8'sd3, 8'sd4,
                16'sd1, 16'sd2, 16'sd3,
                0, 1, 0, 0);
    send_sample(8'sd14, 8'sd2, 8'sd3, 8'sd4,
                16'sd1, 16'sd2, 16'sd3,
                1, 1, 0, 1);
    observe_outputs(4);

    reset_dut;
    send_sample(8'sd5, 8'sd1, 8'sd1, 8'sd1,
                16'sd0, 16'sd0, 16'sd0,
                0, 0, 0, 1);
    observe_outputs(5);

    reset_dut;
    send_sample(8'sd7, 8'sd4, -8'sd5, 8'sd6,
                16'sd100, -16'sd200, 16'sd300,
                1, 1, 0, 0);

    for (k = 0; k < 9; k = k + 1) begin
        send_sample(8'sd0, 8'sd0, 8'sd0, 8'sd0,
                    16'sd0, 16'sd0, 16'sd0,
                    0, 0, 0, 0);
    end

    send_sample(-8'sd8, -8'sd7, 8'sd6, -8'sd5,
                -16'sd11, 16'sd22, -16'sd33,
                1, 1, 0, 1);
    observe_outputs(6);

    $display("===========End===========");

    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam WD = 256;
localparam DB = 8;
localparam HALF = DB + 12;

// Six adjacent timings span the verification/use window after
// send_packet_bits returns. Timing is derived from the fixed bus
// half-period and watchdog interval, not from DUT internal signals.
localparam RESET_WINDOW_FIRST = WD - HALF - 4;
localparam RESET_WINDOW_COUNT = 6;

// Inputs
reg clk;
reg reset, read;
reg mouse_clk_low, mouse_data_low;

// Outputs or inout
tri1 ps2_clk, ps2_data;
wire left_button, right_button;
wire [8:0] x_increment, y_increment;
wire data_ready, error_no_ack;

integer test_id, i, j, integer_bit;
reg bounce;
reg [7:0] status_byte, x_byte, y_byte;
reg [32:0] frame;

assign ps2_clk  = mouse_clk_low  ? 1'b0 : 1'bz;
assign ps2_data = mouse_data_low ? 1'b0 : 1'bz;

// Instantiate only the top-level golden module.
ps2_mouse_interface #(
    .WATCHDOG_TIMER_VALUE_PP(WD),
    .WATCHDOG_TIMER_BITS_PP(9),
    .DEBOUNCE_TIMER_VALUE_PP(DB),
    .DEBOUNCE_TIMER_BITS_PP(5)
) uut (
    .clk(clk),
    .reset(reset),
    .ps2_clk(ps2_clk),
    .ps2_data(ps2_data),
    .left_button(left_button),
    .right_button(right_button),
    .x_increment(x_increment),
    .y_increment(y_increment),
    .data_ready(data_ready),
    .read(read),
    .error_no_ack(error_no_ack)
);

// Independent, continuously running system clock.
initial clk = 0;
always #5 clk = ~clk;

task cycles;
    input integer n;
    begin
        repeat (n) @(posedge clk);
        #1;
    end
endtask

task observe;
    input [8*40-1:0] label;
    begin
        $display("t=%0t case=%0d %0s reset=%b read=%b ps2_clk=%b ps2_data=%b left_button=%b right_button=%b x_increment=%h y_increment=%h data_ready=%b error_no_ack=%b",
                 $time, test_id, label, reset, read, ps2_clk, ps2_data,
                 left_button, right_button, x_increment, y_increment,
                 data_ready, error_no_ack);
    end
endtask

task reset_dut;
    begin
        reset = 1;
        read = 0;
        mouse_clk_low = 0;
        mouse_data_low = 0;
        bounce = 0;
        cycles(3);
        observe("reset asserted");
        reset = 0;
        cycles(3);
        observe("reset released / clock inhibit");
        cycles(WD + 16);
        observe("host request");
    end
endtask

// Optional excursions occur inside the debounce interval.
task send_bit;
    input value;
    begin
        mouse_data_low = ~value;
        cycles(2);
        mouse_clk_low = 1;
        cycles(3);
        if (bounce) mouse_clk_low = 0;
        cycles(1);
        mouse_clk_low = 1;
        cycles(HALF - 4);
        mouse_clk_low = 0;
        cycles(3);
        if (bounce) mouse_clk_low = 1;
        cycles(1);
        mouse_clk_low = 0;
        cycles(HALF - 4);
    end
endtask

task send_byte;
    input [7:0] value;
    reg [10:0] serial;
    integer b;
    begin
        serial = {1'b1, ~^value, value, 1'b0};
        for (b = 0; b < 11; b = b + 1) begin
            send_bit(serial[b]);
            #1;
        end
        mouse_data_low = 0;
    end
endtask

// Send a fixed-length prefix of the host-command clock sequence.
// Clocks 1..10 release device data; clock 11 supplies acknowledgment.
// No DUT outputs or internal state control stimulus timing.
task command_clocks;
    input integer count;
    input ack_level;
    integer b;
    begin
        for (b = 0; b < count; b = b + 1) begin
            if (b == 10)
                send_bit(ack_level);
            else
                send_bit(1'b1);
            #1;
            observe("command clock");
        end
    end
endtask

task command;
    input ack_level;
    begin
        command_clocks(10, 1'b1);
        send_bit(ack_level);
        mouse_data_low = 0;
        cycles(2);
        observe("device acknowledgment");
        if (!ack_level) begin
            send_byte(8'hfa);
            observe("command response complete");
            cycles(WD + 16);
            observe("response idle complete");
        end
    end
endtask

task initialize_mouse;
    begin
        reset_dut;
        command(1'b0);
    end
endtask

// Transmit a packet without waiting for watchdog verification.
// fault 0..8: start/parity/stop in each byte; 9: even total parity.
task send_packet_bits;
    input [7:0] buttons;
    input [7:0] dx;
    input [7:0] dy;
    input integer fault;
    reg [32:0] serial;
    integer b, position;
    begin
        serial = {1'b1, ~^dy, dy, 1'b0,
                  1'b1, ~^dx, dx, 1'b0,
                  1'b1, ~^buttons, buttons, 1'b0};
        if (fault >= 0 && fault < 9) begin
            case (fault % 3)
                0: position = 11 * (fault / 3);
                1: position = 11 * (fault / 3) + 9;
                2: position = 11 * (fault / 3) + 10;
            endcase
            serial[position] = ~serial[position];
        end
        if (fault == 9) begin
            serial[9]  = ~serial[9];
            serial[20] = ~serial[20];
            serial[31] = ~serial[31];
        end
        for (b = 0; b < 33; b = b + 1) begin
            send_bit(serial[b]);
            #1;
        end
        mouse_data_low = 0;
        cycles(4);
        observe("33 bits received / before timeout");
    end
endtask

// Preserve the original packet task's interface and idle behavior.
task send_packet;
    input [7:0] buttons;
    input [7:0] dx;
    input [7:0] dy;
    input integer fault;
    begin
        send_packet_bits(buttons, dx, dy, fault);
        cycles(WD + 16);
        observe("packet observation");
    end
endtask

task host_read;
    begin
        read = 1;
        cycles(3);
        observe("read asserted");
        read = 0;
        cycles(3);
        observe("read released");
    end
endtask

initial begin
    // Initialize inputs.
    reset = 1;
    read = 0;
    mouse_clk_low = 0;
    mouse_data_low = 0;
    bounce = 0;
    test_id = 0;

    // Wait 100 ns for global reset to finish.
    #100;
    cycles(1);
    observe("initial reset");

    // Valid data boundaries and handshake.
    for (i = 0; i < 5; i = i + 1) begin
        #1;
        test_id = 10 + i;
        initialize_mouse;
        case (i)
            0: begin
                status_byte = 8'h08;
                x_byte = 8'h00;
                y_byte = 8'h00;
            end
            1: begin
                status_byte = 8'h19;
                x_byte = 8'hff;
                y_byte = 8'h7f;
            end
            2: begin
                status_byte = 8'h2a;
                x_byte = 8'h7f;
                y_byte = 8'h80;
            end
            3: begin
                status_byte = 8'h3b;
                x_byte = 8'h80;
                y_byte = 8'hff;
            end
            4: begin
                status_byte = 8'hfc;
                x_byte = 8'h55;
                y_byte = 8'haa;
            end
        endcase
        send_packet(status_byte, x_byte, y_byte, -1);
        cycles(WD + 16);
        observe("unread data retained");
        host_read;
        host_read;
    end

    // Independent framing/parity faults with unread data and recovery.
    for (i = 0; i < 10; i = i + 1) begin
        #1;
        test_id = 20 + i;
        initialize_mouse;
        send_packet(8'h09, 8'h12, 8'h34, -1);
        send_packet(8'h3a, 8'hfe, 8'h81, i);
        observe("after malformed packet");
        host_read;
        send_packet(8'h0b, 8'h55, 8'haa, -1);
        host_read;
    end

    // New packet while earlier data remains unread; reset pending data.
    test_id = 30;
    initialize_mouse;
    send_packet(8'h09, 8'h01, 8'h02, -1);
    send_packet(8'h3a, 8'hff, 8'h80, -1);
    observe("second unread packet");
    reset_dut;
    command(1'b0);

    // Short excursions within both debounce phases.
    test_id = 31;
    initialize_mouse;
    bounce = 1;
    send_packet(8'h2b, 8'haa, 8'h55, -1);
    bounce = 0;
    host_read;

    // Partial packet watchdog paths and command recovery.
    frame = {1'b1, ~^8'h34, 8'h34, 1'b0,
             1'b1, ~^8'h12, 8'h12, 1'b0,
             1'b1, ~^8'h09, 8'h09, 1'b0};
    for (i = 0; i < 3; i = i + 1) begin
        #1;
        test_id = 40 + i;
        initialize_mouse;
        case (i)
            0: j = 1;
            1: j = 16;
            2: j = 32;
        endcase
        for (integer_bit = 0;
             integer_bit < j;
             integer_bit = integer_bit + 1) begin
            send_bit(frame[integer_bit]);
            #1;
        end
        mouse_data_low = 0;
        observe("partial packet");
        cycles(WD + 8);
        observe("partial packet timeout");
        cycles(WD + 16);
        observe("renewed host request");
        command(1'b0);
        send_packet(8'h0b, 8'h01, 8'hff, -1);
        host_read;
    end

    // Reset during reception, host command, and clock inhibition.
    test_id = 50;
    initialize_mouse;
    send_byte(8'h09);
    observe("reception before reset");
    reset_dut;
    for (i = 0; i < 3; i = i + 1) begin
        send_bit(1'b1);
        #1;
    end
    observe("command before reset");
    reset_dut;
    reset = 1;
    cycles(3);
    observe("reset before clock inhibition");
    reset = 0;
    cycles(3);
    observe("clock inhibition before reset");
    reset_dut;
    command(1'b0);
    send_packet(8'h08, 8'h00, 8'h00, -1);

    // Missing acknowledgment, sticky behavior, and reset recovery.
    test_id = 60;
    reset_dut;
    command(1'b1);
    cycles(2 * WD + 16);
    observe("missing acknowledgment retained");
    host_read;
    send_byte(8'hfa);
    cycles(WD + 16);
    observe("error after further bus activity");
    initialize_mouse;
    send_packet(8'h0b, 8'h7f, 8'h01, -1);
    host_read;

    // Additional directed coverage:
    // Reset from the three uncovered clock-cleaner source states.
    // All transitions are created through the top-level clock/reset ports.
    for (i = 0; i < 3; i = i + 1) begin
        #1;
        test_id = 70 + i;
        initialize_mouse;
        mouse_data_low = 0;
        mouse_clk_low = 1;

        case (i)
            0: begin
                // First sampled low: falling-edge state.
                cycles(1);
                observe("reset at falling-edge phase");
            end
            1: begin
                // Remain low beyond the debounce interval.
                cycles(HALF);
                observe("reset at stable-low phase");
            end
            2: begin
                // Debounce low, then sample the released-high line once.
                cycles(HALF);
                mouse_clk_low = 0;
                cycles(1);
                observe("reset at rising-edge phase");
            end
        endcase

        // Assert reset immediately, before another system-clock edge.
        reset_dut;
        command(1'b0);
        send_packet(8'h2b, 8'h81, 8'h7e, -1);
        host_read;
    end

    // Reset from uncovered command/response states.
    // Completed clock counts:
    // 4 -> low_2, 5 -> high_2, 9 -> low_3,
    // 10 -> high_3, 11 with low ACK -> await_response.
    for (i = 0; i < 5; i = i + 1) begin
        #1;
        test_id = 80 + i;
        reset_dut;

        case (i)
            0: j = 4;
            1: j = 5;
            2: j = 9;
            3: j = 10;
            4: j = 11;
        endcase

        command_clocks(j, 1'b0);
        mouse_data_low = 0;
        observe("command prefix before reset");

        // Do not transmit FA in the 11-clock case: reset while
        // awaiting the response instead of completing that phase.
        reset_dut;
        command(1'b0);
        send_packet(8'h19, 8'hfe, 8'h01, -1);
        host_read;
    end

    // Reset around the watchdog-driven verify/use window.
    // A bounded cycle sweep catches both one-cycle states without
    // hierarchical access, output polling, or DUT-state replication.
    for (i = 0; i < RESET_WINDOW_COUNT; i = i + 1) begin
        #1;
        test_id = 90 + i;
        initialize_mouse;
        send_packet_bits(8'h3b, 8'ha5, 8'h5a, -1);
        cycles(RESET_WINDOW_FIRST + i);
        observe("verification-window reset");

        reset_dut;
        command(1'b0);
        send_packet(8'h08, 8'h00, 8'h00, -1);
        host_read;
    end

    // Overlength packet reception and bit-counter wraparound.
    // Appended counts 1, 30, 31, 32 produce total lengths
    // 34, 63, 64, 65 without an intervening watchdog timeout.
    for (i = 0; i < 4; i = i + 1) begin
        #1;
        test_id = 100 + i;
        initialize_mouse;

        // Keep valid data pending while malformed-length traffic arrives.
        send_packet(8'h09, 8'h12, 8'h34, -1);
        send_packet_bits(8'h3a, 8'hfe, 8'h81, -1);

        case (i)
            0: j = 1;
            1: j = 30;
            2: j = 31;
            3: j = 32;
        endcase

        for (integer_bit = 0;
             integer_bit < j;
             integer_bit = integer_bit + 1) begin
            send_bit(integer_bit % 2);
            #1;
        end

        mouse_data_low = 0;
        observe("overlength stream before timeout");
        cycles(WD + 8);
        observe("overlength watchdog observation");
        cycles(WD + 16);
        observe("overlength renewed host request");

        command(1'b0);
        host_read;
        send_packet(8'h0b, 8'h55, 8'haa, -1);
        host_read;
    end

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

reg clk;
reg [8:0] address_i;
wire [4:0] q_o;

integer addr;

rom_clip uut (
    .address_i(address_i),
    .q_o(q_o)
);

initial clk = 0;
always #5 clk = ~clk;

initial begin
    address_i = 9'd0;

    // No reset is present; allow initial combinational settling.
    #100;

    // Test Case 1: exhaustive address-space sweep
    $display("address_i=%h q_o=%d", address_i, q_o);
    for (addr = 1; addr < 512; addr = addr + 1) begin
        address_i = addr;
        #1;
        $display("address_i=%h q_o=%d", address_i, q_o);
    end

    // Test Case 2: unknown and high-impedance addresses
    address_i = 9'bxxxxxxxxx;
    #1;
    $display("address_i=%b q_o=%d", address_i, q_o);

    address_i = 9'bzzzzzzzzz;
    #1;
    $display("address_i=%b q_o=%d", address_i, q_o);

    address_i = 9'bxxxzzzzzz;
    #1;
    $display("address_i=%b q_o=%d", address_i, q_o);

    $display("===========End===========");

    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam SCAN_WORDS = 107;
localparam FRAME_SEGMENTS = 240;

// Inputs
reg clk;
reg addr_ready, data_ready, want_read, wantDir, wantwriteback;
reg fbnextscanline, fbpage, wantshadedata, wanttexel, globalreset;
reg [17:0] addrin, writebackaddr, texeladdr;
reg [15:0] triID;
reg [63:0] datain, writebackdata, tm3_sram_data_in;

// Outputs
wire want_addr, want_data, read_ready, dirReady, writebackack;
wire fbdatavalid, shadedataready, texelready, tm3_sram_adsp;
wire [63:0] dataout, fbdata, shadedata, texel, tm3_sram_data_out;
wire [47:0] sramdatal;
wire [14:0] addr;
wire [18:0] tm3_sram_addr;
wire [7:0] tm3_sram_we;
wire [1:0] tm3_sram_oe;

integer test_id, i, j;

// Instantiate the Unit Under Test (UUT)
rgsramcontroller uut (
    .want_addr(want_addr), .addr_ready(addr_ready), .addrin(addrin),
    .want_data(want_data), .data_ready(data_ready), .datain(datain),
    .want_read(want_read), .read_ready(read_ready), .dataout(dataout),
    .dirReady(dirReady), .wantDir(wantDir), .sramdatal(sramdatal),
    .addr(addr), .wantwriteback(wantwriteback),
    .writebackack(writebackack), .writebackdata(writebackdata),
    .writebackaddr(writebackaddr), .fbdata(fbdata),
    .fbnextscanline(fbnextscanline), .fbdatavalid(fbdatavalid),
    .fbpage(fbpage), .shadedata(shadedata), .triID(triID),
    .wantshadedata(wantshadedata), .shadedataready(shadedataready),
    .texeladdr(texeladdr), .texel(texel), .wanttexel(wanttexel),
    .texelready(texelready), .tm3_sram_data_in(tm3_sram_data_in),
    .tm3_sram_data_out(tm3_sram_data_out),
    .tm3_sram_addr(tm3_sram_addr), .tm3_sram_we(tm3_sram_we),
    .tm3_sram_oe(tm3_sram_oe), .tm3_sram_adsp(tm3_sram_adsp),
    .globalreset(globalreset), .clk(clk)
);

// clk toggle generate
initial clk = 0; //clk is initialized as 0
always #5 clk = ~clk;

task observe;
begin
    $display(
        "t=%0t case=%0d reset=%b req=%b nextscan=%b page=%b rin=%h want_addr=%b want_data=%b read_ready=%b dataout=%h dirReady=%b sramdatal=%h addr=%h writebackack=%b fbdata=%h fbdatavalid=%b shadedata=%h shadedataready=%b texel=%h texelready=%b tm3_sram_data_out=%h tm3_sram_addr=%h tm3_sram_we=%h tm3_sram_oe=%b tm3_sram_adsp=%b",
        $time, test_id, globalreset,
        {addr_ready, want_read, data_ready, wantDir,
         wantwriteback, wantshadedata, wanttexel},
        fbnextscanline, fbpage, tm3_sram_data_in,
        want_addr, want_data, read_ready, dataout, dirReady,
        sramdatal, addr, writebackack, fbdata, fbdatavalid,
        shadedata, shadedataready, texel, texelready,
        tm3_sram_data_out, tm3_sram_addr, tm3_sram_we,
        tm3_sram_oe, tm3_sram_adsp
    );
end
endtask

task sample_cycles;
input integer count;
integer k;
begin
    for (k = 0; k < count; k = k + 1) begin
        @(posedge clk);
        #1;
        observe;
    end
end
endtask

// Request order: address, read, data, direction, writeback, shader, texel.
task requests;
input [6:0] value;
begin
    @(negedge clk);
    {addr_ready, want_read, data_ready, wantDir,
     wantwriteback, wantshadedata, wanttexel} = value;
end
endtask

task reset_dut;
begin
    @(negedge clk);
    globalreset = 1;
    #1;
    observe;
    sample_cycles(1);
    @(negedge clk);
    {addr_ready, want_read, data_ready, wantDir,
     wantwriteback, wantshadedata, wanttexel} = 0;
    fbnextscanline = 0;
    fbpage = 0;
    addrin = 0;
    datain = 64'h0123456789abcdef;
    writebackaddr = 0;
    writebackdata = 64'hfedcba9876543210;
    triID = 0;
    texeladdr = 0;
    tm3_sram_data_in = 64'h123456789abcdef0;
    sample_cycles(1);
    @(negedge clk);
    globalreset = 0;
end
endtask

task capture_address;
input [17:0] value;
begin
    @(negedge clk);
    addrin = value;
    addr_ready = 1;
    sample_cycles(3);
    requests(0);
    sample_cycles(1);
end
endtask

// Establish a bounded, quiet arbitration interval through legal requests.
task quiet_idle;
begin
    reset_dut;
    capture_address(18'h12345);
    requests(7'b0100000);
    sample_cycles(3);
    @(negedge clk);
    want_read = 0;
    fbnextscanline = 1;
    sample_cycles(4);
    @(negedge clk);
    fbnextscanline = 0;
    repeat (SCAN_WORDS + 8) @(posedge clk);
    #1;
    observe;
end
endtask

task scan_segment;
begin
    @(negedge clk);
    fbnextscanline = 1;
    sample_cycles(3);
    @(negedge clk);
    fbnextscanline = 0;
    sample_cycles(2);
    repeat (SCAN_WORDS - 6) @(posedge clk);
    #1;
    observe;
    sample_cycles(6);
end
endtask

initial begin
    // Initialize Inputs
    test_id = 0;
    globalreset = 1;
    addr_ready = 0;
    data_ready = 0;
    want_read = 0;
    wantDir = 0;
    wantwriteback = 0;
    wantshadedata = 0;
    wanttexel = 0;
    fbnextscanline = 0;
    fbpage = 0;
    addrin = 0;
    writebackaddr = 0;
    texeladdr = 0;
    triID = 0;
    datain = 0;
    writebackdata = 0;
    tm3_sram_data_in = 64'hffffffffffffffff;

    // Wait 100 ns for global reset to finish
    #100;
    observe;
    @(negedge clk);
    globalreset = 0;
    sample_cycles(5);

    // Returned-data aliases and registered views.
    test_id = 10;
    reset_dut;
    requests(7'b1000000);
    sample_cycles(2);
    for (i = 0; i < 6; i = i + 1) begin
        @(negedge clk);
        case (i)
            0: tm3_sram_data_in = 64'h0000000000000000;
            1: tm3_sram_data_in = 64'hffffffffffffffff;
            2: tm3_sram_data_in = 64'h8000000000000000;
            3: tm3_sram_data_in = 64'h7fff000000000000;
            4: tm3_sram_data_in = 64'ha55aa55aa55aa55a;
            5: tm3_sram_data_in = 64'h5aa55aa55aa55aa5;
        endcase
        #1;
        observe;
        sample_cycles(1);
    end

    // Sequential read, write, and direction at both address boundaries.
    for (i = 0; i < 2; i = i + 1) begin
        for (j = 0; j < 3; j = j + 1) begin
            #1;
            test_id = 20 + 3*i + j;
            reset_dut;
            capture_address(i ? 18'h3ffff : 18'h00000);
            datain = i ? 64'hffffffffffffffff : 64'h0000000000000000;
            case (j)
                0: requests(7'b0100000);
                1: requests(7'b0010000);
                2: requests(7'b0001000);
            endcase
            sample_cycles(4);
            requests(0);
            sample_cycles(1);
            requests(7'b0100000);
            sample_cycles(3);
            requests(0);
            sample_cycles(2);
        end
    end

    // Full priority chain, including sustained lower-priority requests.
    test_id = 30;
    reset_dut;
    addrin = 18'h2aaaa;
    requests(7'b1111111);
    sample_cycles(3);
    for (i = 0; i < 7; i = i + 1) begin
        #1;
        requests(7'h7f >> (i + 1));
        sample_cycles(4);
    end

    // Isolated and repeated writeback, shader, and texel transactions.
    for (i = 0; i < 2; i = i + 1) begin
        for (j = 0; j < 3; j = j + 1) begin
            #1;
            test_id = 40 + 3*i + j;
            quiet_idle;
            writebackaddr = i ? 18'h3ffff : 18'h00000;
            texeladdr = i ? 18'h3ffff : 18'h00000;
            triID = i ? 16'hffff : 16'h0000;
            writebackdata = i ? 64'ha55aa55aa55aa55a
                              : 64'h5aa55aa55aa55aa5;
            requests(7'b0000100 >> j);
            sample_cycles(1);
            requests(0);
            sample_cycles(3);
            requests(7'b0000100 >> j);
            sample_cycles(6);
            requests(0);
            sample_cycles(3);
        end
    end

    // Each foreground preemption source interrupts background reading.
    for (i = 0; i < 5; i = i + 1) begin
        #1;
        test_id = 50 + i;
        quiet_idle;
        @(negedge clk);
        fbpage = i % 2;
        fbnextscanline = 1;
        sample_cycles(5);
        @(negedge clk);
        fbnextscanline = 0;
        addrin = 18'h15555;
        requests(7'b1000000 >> i);
        sample_cycles(5);
        requests(0);
        sample_cycles(5);
        repeat (SCAN_WORDS + 8) @(posedge clk);
        #1;
        observe;
        sample_cycles(3);
    end

    // Shader and texel stay pending through a background burst.
    test_id = 60;
    quiet_idle;
    @(negedge clk);
    fbnextscanline = 1;
    sample_cycles(5);
    @(negedge clk);
    fbnextscanline = 0;
    wantshadedata = 1;
    wanttexel = 1;
    sample_cycles(4);
    repeat (SCAN_WORDS - 12) @(posedge clk);
    #1;
    observe;
    sample_cycles(12);
    requests(7'b0000001);
    sample_cycles(6);
    requests(0);
    sample_cycles(3);

    // Reload, page selection, completion, and the nominal frame boundary.
    test_id = 70;
    quiet_idle;
    for (i = 0; i < FRAME_SEGMENTS + 1; i = i + 1) begin
        @(negedge clk);
        test_id = 1000 + i;
        fbpage = i % 2;
        scan_segment;
    end
    sample_cycles(4);

    // Reset during every foreground operation, including data hold.
    for (i = 0; i < 8; i = i + 1) begin
        #1;
        test_id = 80 + i;
        quiet_idle;
        requests(i == 7 ? 7'b0010000 : (7'b1000000 >> i));
        sample_cycles(i == 7 ? 2 : 1);
        reset_dut;
        sample_cycles(3);
    end

    // Reset with framebuffer activity and valid pipeline in flight.
    test_id = 90;
    quiet_idle;
    @(negedge clk);
    fbnextscanline = 1;
    sample_cycles(6);
    reset_dut;
    sample_cycles(5);

    $display("===========End===========");
    $finish;
end

endmodule

