module testbench;

// Inputs
reg clk;
reg enable;
reg [13:0] addr;

// Outputs
wire [15:0] data;

integer i;

rom08 uut (
    .clk(clk),
    .enable(enable),
    .addr(addr),
    .data(data)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [255:0] label;
    begin
        $display("%0s t=%0t enable=%b addr=%h data=%h",
                 label, $time, enable, addr, data);
    end
endtask

// Call at a falling edge; observe both sides of the sampling edge.
task read_word;
    input [13:0] address;
    begin
        enable = 1'b1;
        addr = address;
        #1;
        observe("read_before_edge");
        @(posedge clk);
        #1;
        observe("read_after_edge");
    end
endtask

task gate_case;
    input [13:0] address;
    begin
        @(negedge clk);
        read_word(14'h0000);

        // A complete gate pulse without a rising clock edge.
        @(negedge clk);
        enable = 1'b0;
        #1;
        observe("gate_pulse_low");
        enable = 1'b1;
        #1;
        observe("gate_pulse_high");

        // Two lookups while disabled.
        @(negedge clk);
        enable = 1'b0;
        addr = 14'h0002;
        #1;
        observe("disabled_before_edge");
        @(posedge clk);
        #1;
        observe("disabled_first_lookup");

        @(negedge clk);
        addr = address;
        @(posedge clk);
        #1;
        observe("disabled_latest_lookup");

        // Change address and reopen the gate before another rising edge.
        addr = 14'h0000;
        #1;
        enable = 1'b1;
        #1;
        observe("reenabled_between_edges");
        @(posedge clk);
        #1;
        observe("reenabled_next_lookup");
    end
endtask

initial begin
    enable = 1'b0;
    addr = 14'h0000;

    // Case 1: startup observations before the first rising edge.
    #1;
    observe("startup_disabled");
    enable = 1'b1;
    #1;
    observe("startup_enabled");
    enable = 1'b0;

    // Complete the template's 100 ns startup interval; no reset exists.
    #98;

    // Case 2: every valid word, synchronous timing, and held address.
    @(negedge clk);
    read_word(14'h0000);
    for (i = 0; i < 250; i = i + 1) begin
        @(negedge clk);
        read_word(i);
    end
    repeat (2) begin
        @(negedge clk);
        read_word(14'h00F9);
    end

    // Case 3: invalid boundaries and upper address bits.
    @(negedge clk);
    read_word(14'h0000);
    @(negedge clk);
    read_word(14'h00FA);
    @(negedge clk);
    read_word(14'h00F9);
    @(negedge clk);
    read_word(14'h00FF);

    for (i = 8; i < 14; i = i + 1) begin
        @(negedge clk);
        read_word(14'h0000);
        @(negedge clk);
        read_word(14'h0001 << i);
    end

    @(negedge clk);
    read_word(14'h3FFF);
    @(negedge clk);
    read_word(14'h0000);

    // Case 4: combinational gating and continued disabled lookups.
    gate_case(14'h0001);
    gate_case(14'h00F9);
    gate_case(14'h00FA);
    gate_case(14'h3FFF);

    $display("===========End=========== data=%h", data);
    $finish;
end

endmodule

