initial begin
    reset_n = 0;
    addr = 0;

    // Wait 100 ns for global reset to finish.
    #100;
    observe("startup reset");

    // Complete address map and registered timing.
    @(negedge clk);
    reset_n = 1;
    #1;
    observe("startup reset released");
    @(posedge clk);
    #1;
    observe("first capture after reset");

    for (i = 0; i < 64; i = i + 1) begin
        read_address(i);
    end
    read_address(0);
    read_address(0);

    // Reset from each distinct stored control combination.
    for (i = 0; i < 5; i = i + 1) begin
        @(negedge clk);
        reset_n = 0;
        addr = 0;
        @(posedge clk);
        #1;
        observe("case initialization");

        @(negedge clk);
        case (i)
            0: addr = 0;
            1: addr = 2;
            2: addr = 3;
            3: addr = 4;
            4: addr = 50;
        endcase
        reset_n = 1;
        @(posedge clk);
        #1;
        observe("control word before reset");

        @(negedge clk);
        #1;
        reset_n = 0;
        #1;
        observe("asynchronous reset asserted");
        addr = 63;
        #1;
        observe("address changed during reset");
        @(posedge clk);
        #1;
        observe("reset held across rising edge");

        @(negedge clk);
        #1;
        reset_n = 1;
        #1;
        observe("reset released before rising edge");
        @(posedge clk);
        #1;
        observe("capture after reset release");
    end

    $display("===========End===========");
    $finish;
end

