module testbench;

// Inputs
reg clk;
reg [39:0] i_flit;
reg i_slave_rx_ready;

// Outputs
wire o_slave_rx_ren;
wire o_address_valid, o_data_valid;
wire [31:0] o_data, o_address;
wire [2:0] o_cmd;
wire o_cmd_valid;
wire [5:0] o_feature0, o_feature1;
wire o_feature0_valid, o_feature1_valid;
wire [2:0] o_length;
wire o_length_valid;

integer n, test_id;
integer fmt, cmd, len, ready_seed;
reg [39:0] header;

strawman_rx_fsm uut (
    .clk(clk),
    .i_flit(i_flit),
    .i_slave_rx_ready(i_slave_rx_ready),
    .o_slave_rx_ren(o_slave_rx_ren),
    .o_address_valid(o_address_valid),
    .o_data_valid(o_data_valid),
    .o_data(o_data),
    .o_address(o_address),
    .o_cmd(o_cmd),
    .o_cmd_valid(o_cmd_valid),
    .o_feature0(o_feature0),
    .o_feature0_valid(o_feature0_valid),
    .o_feature1(o_feature1),
    .o_feature1_valid(o_feature1_valid),
    .o_length(o_length),
    .o_length_valid(o_length_valid)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input integer phase;
    input integer cycle;
    begin
        $display("t=%0t case=%0d phase=%0d cycle=%0d flit=%010h ready=%b ren=%b address_valid=%b address=%08h data_valid=%b data=%08h cmd_valid=%b cmd=%h feature0_valid=%b feature0=%h feature1_valid=%b feature1=%h length_valid=%b length=%h",
                 $time, test_id, phase, cycle, i_flit,
                 i_slave_rx_ready, o_slave_rx_ren,
                 o_address_valid, o_address, o_data_valid, o_data,
                 o_cmd_valid, o_cmd, o_feature0_valid, o_feature0,
                 o_feature1_valid, o_feature1,
                 o_length_valid, o_length);
    end
endtask

task step;
    input [39:0] flit;
    input ready;
    input integer phase;
    input integer cycle;
    begin
        @(negedge clk);
        i_flit = flit;
        i_slave_rx_ready = ready;
        @(posedge clk);
        #1;
        observe(phase, cycle);
    end
endtask

task packet;
    input [39:0] h;
    input integer command;
    input integer length_code;
    input integer seed;
    integer j, window;
    reg [31:0] word;
    begin
        // Fixed observation budgets, including idle margin.
        if (command == 0)
            window = 3;
        else if ((command == 2) &&
                 ((length_code == 0) || (length_code >= 6)))
            window = 258;
        else if (length_code >= 6)
            window = 3;
        else
            window = (1 << length_code) + 2;

        step(40'b0, seed[0], 0, 0);
        step(40'b0, seed[0], 0, 1);

        // Phase 1: captured header; phase 2: current following word.
        step(h, seed[0], 1, 0);
        i_flit = {8'hD3, (32'h89ABCDEC ^ (length_code << 8))};
        #1;
        observe(2, 0);

        for (j = 0; j < window; j = j + 1) begin
            @(negedge clk);
            // Bit 1 stays clear so trailing words cannot start packets.
            case (j % 4)
                0: word = 32'h00000000;
                1: word = 32'hFFFFFFFD;
                2: word = 32'hAAAAAAAA;
                3: word = 32'h55555555;
            endcase
            word = (word ^ (j << 8)) & 32'hFFFFFFFD;
            i_flit = {8'h5A, word};
            i_slave_rx_ready = seed[0] ^ j[0];
            @(posedge clk);
            #1;
            observe(3, j);
        end

        step(40'b0, 1'b0, 4, 0);
        step(40'b0, 1'b1, 4, 1);
    end
endtask

initial begin
    // Initialize inputs; wait 100 ns for global initialization.
    i_flit = 40'b0;
    i_slave_rx_ready = 1'b0;
    test_id = 0;
    #100;
    observe(0, 0);
    step(40'b0, 1'b1, 0, 1);

    // Invalid headers: all commands and both formats.
    for (n = 0; n < 16; n = n + 1) begin
        #1;
        test_id = 100 + n;
        header = {32'hA55A3CC3, 8'h00};
        header[7:5] = 3'd7;
        header[4:2] = n / 2;
        header[1] = 1'b0;
        header[0] = n % 2;
        step(header, n[0], 5, 0);
        step(40'b0, ~n[0], 5, 1);
    end

    // Valid headers with unsupported commands 3 through 7.
    for (n = 0; n < 10; n = n + 1) begin
        #1;
        test_id = 200 + n;
        header = {32'h5AA5C33C, 8'h00};
        header[7:5] = 3'd7;
        header[4:2] = 3 + n / 2;
        header[1] = 1'b1;
        header[0] = n % 2;
        step(header, n[0], 6, 0);
        step(40'b0, ~n[0], 6, 1);
    end

    // Two ready patterns x two formats x three commands x eight lengths.
    for (n = 0; n < 96; n = n + 1) begin
        #1;
        test_id = 300 + n;
        ready_seed = n / 48;
        fmt = (n / 24) % 2;
        cmd = (n / 8) % 3;
        len = n % 8;

        case (len % 4)
            0: header = {32'h00000000, 8'h00};
            1: header = {32'hFFFFFFFF, 8'h00};
            2: header = {32'hAAAAAAAA, 8'h00};
            3: header = {32'h55555555, 8'h00};
        endcase
        header[7:5] = len;
        header[4:2] = cmd;
        header[1] = 1'b1;
        header[0] = fmt;
        packet(header, cmd, len, ready_seed);
    end

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps

module testbench;

// Inputs
reg clk;
reg rstn_i;
reg en_i;
reg cpol_i;
reg cpha_i;
reg [26:0] clkdiv_i;
reg [7:0] mosi_data_i;
reg miso_i;

// Outputs
wire [7:0] miso_data_o;
wire data_ready_o;
wire cs_o;
wire sclk_o;
wire mosi_o;

integer mode;
integer rate;
integer boundary;
integer case_id;
integer pattern;
integer request_position;

reg [26:0] divider;
reg [7:0] walking_tx;

spi_master uut (
    .clk_i(clk),
    .rstn_i(rstn_i),
    .en_i(en_i),
    .cpol_i(cpol_i),
    .cpha_i(cpha_i),
    .clkdiv_i(clkdiv_i),
    .mosi_data_i(mosi_data_i),
    .miso_i(miso_i),
    .miso_data_o(miso_data_o),
    .data_ready_o(data_ready_o),
    .cs_o(cs_o),
    .sclk_o(sclk_o),
    .mosi_o(mosi_o)
);

// Independent, continuously running controller clock.
initial clk = 1'b0;
always #5 clk = ~clk;

task observe;
begin
    $display("case=%0d t=%0t rstn=%b en=%b mode=%b%b div=%0d tx=%h miso=%b | miso_data_o=%h data_ready_o=%b cs_o=%b sclk_o=%b mosi_o=%b",
             case_id, $time, rstn_i, en_i, cpol_i, cpha_i,
             clkdiv_i, mosi_data_i, miso_i,
             miso_data_o, data_ready_o, cs_o, sclk_o, mosi_o);
end
endtask

task sample_cycles;
    input integer count;
    integer cycle;
begin
    for (cycle = 0; cycle < count; cycle = cycle + 1) begin
        @(posedge clk);
        #1;
        observe;
    end
end
endtask

task reset_case;
    input polarity;
    input phase;
    input [26:0] divisor;
begin
    @(negedge clk);
    rstn_i = 1'b0;
    en_i = 1'b0;
    cpol_i = polarity;
    cpha_i = phase;
    clkdiv_i = divisor;
    mosi_data_i = 8'h00;
    miso_i = 1'b0;
    #1;
    observe;

    sample_cycles(2);

    @(negedge clk);
    rstn_i = 1'b1;
    sample_cycles(3);
end
endtask

task start_transfer;
    input [7:0] tx;
    input rx_level;
begin
    @(negedge clk);
    mosi_data_i = tx;
    miso_i = rx_level;
    en_i = 1'b1;
    sample_cycles(2);
end
endtask

task single_byte;
    input [7:0] tx;
    input [7:0] rx;
    integer bit_index;
begin
    start_transfer(tx, rx[7]);

    for (bit_index = 7; bit_index >= 0;
         bit_index = bit_index - 1) begin
        @(negedge clk);
        en_i = 1'b0;
        mosi_data_i = ~tx;
        miso_i = rx[bit_index];
        #1;
        sample_cycles(2 * clkdiv_i);
    end

    sample_cycles(4 * clkdiv_i + 8);
end
endtask

// Pulse enable for exactly one controller cycle near the first
// continuation decision.
//
// Let the transfer-acceptance rising edge be cycle zero.
// The first continuation decision occurs at:
//   CPHA=0: cycle 16*N + 1
//   CPHA=1: cycle 17*N + 1
//
// start_transfer returns after cycle one. No DUT state or output
// is consulted to schedule the request.
task boundary_request;
    input polarity;
    input phase;
    input [26:0] divisor;
    input integer relative_cycle;
    integer decision_cycle;
    integer delay_cycles;
begin
    reset_case(polarity, phase, divisor);
    start_transfer(8'h96, 1'b0);

    @(negedge clk);
    en_i = 1'b0;
    mosi_data_i = 8'h3C;

    decision_cycle = (16 + phase) * divisor + 1;
    delay_cycles = decision_cycle + relative_cycle - 2;
    sample_cycles(delay_cycles);

    @(negedge clk);
    en_i = 1'b1;
    mosi_data_i = 8'h69;
    miso_i = 1'b1;
    sample_cycles(1);

    @(negedge clk);
    en_i = 1'b0;
    mosi_data_i = 8'hC3;

    // Sufficient for a continued or newly accepted byte to finish.
    sample_cycles(20 * divisor + 8);
end
endtask

// OUT-OF-CONTRACT DIAGNOSTIC:
// Change CPHA only after a phase-zero terminal transmit event.
// This accesses the otherwise unreachable phase-one count-nine
// handling through ports, without forcing any DUT internals.
//
// With acceptance at cycle zero, phase zero's terminal transmit
// event is processed at cycle 16*N+1. start_transfer has already
// sampled cycles zero and one, so another 16*N cycles reach it.
// A divisor greater than one also leaves controller cycles without
// a sample event, exercising the no-event path before termination.
task termination_phase_probe;
    input polarity;
    input [26:0] divisor;
begin
    reset_case(polarity, 1'b0, divisor);
    start_transfer(8'hA6, 1'b1);

    @(negedge clk);
    en_i = 1'b0;
    mosi_data_i = 8'h59;
    sample_cycles(16 * divisor);

    @(negedge clk);
    cpha_i = 1'b1;
    sample_cycles(4 * divisor + 8);

    // Restore supported settings through a fresh reset.
    reset_case(polarity, 1'b0, divisor);
end
endtask

// OUT-OF-CONTRACT FOUR-STATE DIAGNOSTIC:
// Exercise unmatched mode decoding while reset prevents transfers.
// Restore valid mode values before releasing reset.
task unknown_mode_probe;
    input polarity;
begin
    reset_case(polarity, 1'b0, 27'd2);

    @(negedge clk);
    rstn_i = 1'b0;
    en_i = 1'b0;
    cpha_i = 1'bx;
    #1;
    observe;
    sample_cycles(2);

    @(negedge clk);
    cpha_i = 1'bz;
    #1;
    observe;
    sample_cycles(2);

    @(negedge clk);
    cpha_i = 1'b0;
    sample_cycles(2);

    @(negedge clk);
    rstn_i = 1'b1;
    sample_cycles(3);

    // Observe an ordinary transaction after restoring valid inputs.
    single_byte(8'h5A, 8'hC3);
end
endtask

initial begin
    rstn_i = 1'b0;
    en_i = 1'b0;
    cpol_i = 1'b0;
    cpha_i = 1'b0;
    clkdiv_i = 27'd1;
    mosi_data_i = 8'h00;
    miso_i = 1'b0;
    case_id = 0;
    walking_tx = 8'h00;

    // Initial reset hold.
    #100;
    observe;

    for (mode = 0; mode < 4; mode = mode + 1) begin
        #1;

        // Preserve the original three rates and add more even/odd rates.
        for (rate = 0; rate < 6; rate = rate + 1) begin
            #1;
            case (rate)
                0: divider = 27'd1;
                1: divider = 27'd2;
                2: divider = 27'd5;
                3: divider = 27'd3;
                4: divider = 27'd4;
                5: divider = 27'd7;
                default: divider = 27'd1;
            endcase

            case_id = case_id + 1;
            reset_case(mode[1], mode[0], divider);

            case (rate)
                0: single_byte(8'h96, 8'hA5);
                1: single_byte(8'h00, 8'hFF);
                2: single_byte(8'hFF, 8'h00);
                3: single_byte(8'h81, 8'h7E);
                4: single_byte(8'h55, 8'hAA);
                5: single_byte(8'h3C, 8'hC3);
                default: single_byte(8'h00, 8'h00);
            endcase
        end

        // Original chaining, reloading, and eventual termination.
        case_id = case_id + 1;
        reset_case(mode[1], mode[0], 27'd2);
        start_transfer(8'hAA, 1'b0);
        sample_cycles(20 * clkdiv_i + 8);

        @(negedge clk);
        mosi_data_i = 8'h55;
        miso_i = 1'b1;
        sample_cycles(20 * clkdiv_i + 8);

        @(negedge clk);
        en_i = 1'b0;
        mosi_data_i = 8'h3C;
        sample_cycles(20 * clkdiv_i + 8);

        // Original asynchronous abort and enabled restart.
        case_id = case_id + 1;
        reset_case(mode[1], mode[0], 27'd3);
        start_transfer(8'h81, 1'b1);
        sample_cycles(4 * clkdiv_i);

        @(negedge clk);
        #2;
        rstn_i = 1'b0;
        #1;
        observe;
        sample_cycles(2);

        @(negedge clk);
        rstn_i = 1'b1;
        sample_cycles(2);

        @(negedge clk);
        en_i = 1'b0;
        mosi_data_i = 8'h7E;
        miso_i = 1'b0;
        sample_cycles(20 * clkdiv_i + 8);

        // Walking patterns, with no reset between individual bytes.
        case_id = case_id + 1;
        reset_case(mode[1], mode[0], 27'd2);

        for (pattern = 0; pattern < 8; pattern = pattern + 1) begin
            #1;
            case_id = case_id + 1;
            walking_tx = 8'h01 << pattern;
            single_byte(walking_tx, ~walking_tx);
        end

        // One-cycle request before, at, and after the decision edge.
        // Include the minimum divider and a divider with quiet cycles.
        for (rate = 0; rate < 2; rate = rate + 1) begin
            #1;
            case (rate)
                0: divider = 27'd1;
                1: divider = 27'd3;
                default: divider = 27'd1;
            endcase

            for (request_position = 0; request_position < 3;
                 request_position = request_position + 1) begin
                #1;
                case_id = case_id + 1;
                boundary_request(mode[1], mode[0], divider,
                                 request_position - 1);
            end
        end
    end

    // Original bounded zero/max-divider observations.
    // Do not wait for full transfers at these settings.
    for (boundary = 0; boundary < 2; boundary = boundary + 1) begin
        #1;
        case_id = case_id + 1;

        case (boundary)
            0: divider = 27'd0;
            1: divider = 27'h7FFFFFF;
            default: divider = 27'd1;
        endcase

        reset_case(1'b0, 1'b0, divider);
        start_transfer(8'hF0, 1'b1);
        sample_cycles(32);

        @(negedge clk);
        en_i = 1'b0;
        sample_cycles(4);

        reset_case(1'b0, 1'b0, 27'd1);
    end

    // Isolated out-of-contract diagnostics, after normal regression.
    // Only top-level input ports are driven.
    for (mode = 0; mode < 2; mode = mode + 1) begin
        #1;
        case_id = case_id + 1;
        termination_phase_probe(mode[0], 27'd4);

        case_id = case_id + 1;
        unknown_mode_probe(mode[0]);
    end

    // Finish in a known, supported idle configuration.
    case_id = case_id + 1;
    reset_case(1'b0, 1'b0, 27'd1);
    sample_cycles(4);

    $display("===========End=========== miso_data_o=%h data_ready_o=%b cs_o=%b sclk_o=%b mosi_o=%b",
             miso_data_o, data_ready_o, cs_o, sclk_o, mosi_o);
    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam [511:0] IV = {
    64'h6a09e667f3bcc908, 64'hbb67ae8584caa73b,
    64'h3c6ef372fe94f82b, 64'ha54ff53a5f1d36f1,
    64'h510e527fade682d1, 64'h9b05688c2b3e6c1f,
    64'h1f83d9abfb41bd6b, 64'h5be0cd19137e2179
};
localparam [1023:0] EMPTY_BLOCK = {8'h80, 1016'b0};
localparam [1023:0] ABC_BLOCK = {32'h61626380, 928'b0, 64'd24};
localparam [1023:0] ORDER_BLOCK = {
    64'd0, 64'd1, 64'd2, 64'd3,
    64'd4, 64'd5, 64'd6, 64'd7,
    64'd8, 64'd9, 64'd10, 64'd11,
    64'd12, 64'd13, 64'd14, 64'd15
};
localparam [511:0] ORDER_VIN = {
    64'h0123456789abcdef, 64'hfedcba9876543210,
    64'h8000000000000000, 64'h0000000000000001,
    64'haaaaaaaaaaaaaaaa, 64'h5555555555555555,
    64'hffffffffffffffff, 64'h0000000000000000
};

reg clk;
reg i_rst;
reg i_start;
reg [1023:0] i_data;
reg [511:0] i_vin;

wire [511:0] o_vout;
wire o_done;

integer case_id;
integer vector_id;
integer reset_id;
integer abort_cycles;
reg [1023:0] block_value;
reg [511:0] vin_value;

sha512_core uut (
    .i_clk   (clk),
    .i_rst   (i_rst),
    .i_start (i_start),
    .i_data  (i_data),
    .i_vin   (i_vin),
    .o_vout  (o_vout),
    .o_done  (o_done)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [8*48-1:0] label_text;
    begin
        $display("case=%0d time=%0t %0s o_done=%b o_vout=%h",
                 case_id, $time, label_text, o_done, o_vout);
    end
endtask

task sample_after;
    input integer cycles;
    input [8*48-1:0] label_text;
    begin
        repeat (cycles) @(posedge clk);
        #1;
        observe(label_text);
    end
endtask

task reset_core;
    begin
        @(negedge clk);
        i_start = 1'b1;
        #2;
        i_rst = 1'b1;
        #1;
        observe("asynchronous reset, start high");
        sample_after(1, "reset held across rising edge");
        @(negedge clk);
        i_start = 1'b0;
        i_rst = 1'b0;
        sample_after(2, "idle after reset");
    end
endtask

task launch;
    input [1023:0] message_block;
    input [511:0] chaining_value;
    begin
        @(negedge clk);
        i_data = message_block;
        i_vin = chaining_value;
        i_start = 1'b1;
        sample_after(1, "request acceptance");
    end
endtask

// Called after acceptance, before the first processing edge.
task observe_rounds;
    begin
        sample_after(1,  "after round 0");
        sample_after(15, "after round 15");
        sample_after(1,  "after round 16");
        sample_after(62, "after round 78");
        sample_after(1,  "after round 79");
    end
endtask

task finish_and_idle;
    begin
        sample_after(1, "feed-forward completion");
        sample_after(1, "first idle edge");
        sample_after(2, "idle result retention");
    end
endtask

task run_block;
    input [1023:0] message_block;
    input [511:0] chaining_value;
    begin
        launch(message_block, chaining_value);
        @(negedge clk);
        i_start = 1'b0;
        observe_rounds;
        finish_and_idle;
    end
endtask

initial begin
    // Case 0: permit a clock before the first reset.
    // In four-state RTL simulation, uninitialized r_state selects
    // the default recovery branch. No DUT internals are accessed.
    i_rst = 1'b0;
    i_start = 1'b0;
    i_data = 1024'b0;
    i_vin = 512'b0;
    block_value = 1024'b0;
    vin_value = 512'b0;
    case_id = 0;

    #1;
    observe("power-up before reset or first clock");
    sample_after(1, "first clock before reset");
    sample_after(1, "second clock before reset");

    // Establish the original reset-based test precondition.
    // Assert away from a clock edge and retain the 100 ns reset hold.
    @(negedge clk);
    #2;
    i_rst = 1'b1;
    #100;
    observe("initial reset");

    // Cases 1-8: data patterns and round boundaries.
    for (vector_id = 0; vector_id < 8; vector_id = vector_id + 1) begin
        #1;
        case_id = vector_id + 1;
        reset_core;
        case (vector_id)
            0: begin
                block_value = 1024'b0;
                vin_value = 512'b0;
            end
            1: begin
                block_value = {1024{1'b1}};
                vin_value = {512{1'b1}};
            end
            2: begin
                block_value = {16{64'haaaaaaaaaaaaaaaa}};
                vin_value = {4{128'haaaaaaaaaaaaaaaa5555555555555555}};
            end
            3: begin
                block_value = ORDER_BLOCK;
                vin_value = ORDER_VIN;
            end
            4: begin
                block_value = {1'b1, 1023'b0};
                vin_value = ORDER_VIN;
            end
            5: begin
                block_value = {{1023{1'b0}}, 1'b1};
                vin_value = ORDER_VIN;
            end
            6: begin
                block_value = EMPTY_BLOCK;
                vin_value = IV;
            end
            7: begin
                block_value = ABC_BLOCK;
                vin_value = IV;
            end
        endcase
        run_block(block_value, vin_value);
    end

    // Case 9: captured message; busy/finalization requests ignored.
    case_id = 9;
    reset_core;
    launch(ORDER_BLOCK, ORDER_VIN);
    @(negedge clk);
    i_start = 1'b0;
    i_data = ~ORDER_BLOCK;
    sample_after(1, "round 0 after message input change");
    @(negedge clk);
    i_start = 1'b1;
    sample_after(15, "busy start held, after round 15");
    sample_after(1, "busy start held, after round 16");
    sample_after(62, "busy start held, after round 78");
    sample_after(1, "busy start held, after round 79");
    sample_after(1, "start high at finalization");
    @(negedge clk);
    i_start = 1'b0;
    sample_after(1, "idle after ignored requests");
    sample_after(82, "idle with no queued request");

    // Case 10: start held through completion and next acceptance.
    case_id = 10;
    reset_core;
    launch(EMPTY_BLOCK, IV);
    observe_rounds;
    sample_after(1, "first completion, start still high");
    @(negedge clk);
    i_data = ABC_BLOCK;
    i_vin = ORDER_VIN;
    sample_after(1, "immediate next request acceptance");
    @(negedge clk);
    i_start = 1'b0;
    observe_rounds;
    finish_and_idle;

    // Case 11: deliberate live feed-forward input characterization.
    case_id = 11;
    reset_core;
    launch(ORDER_BLOCK, ORDER_VIN);
    @(negedge clk);
    i_start = 1'b0;
    observe_rounds;
    @(negedge clk);
    i_vin = ~ORDER_VIN;
    finish_and_idle;

    // Cases 12-16: interruption at selected boundaries, then recovery.
    for (reset_id = 0; reset_id < 5; reset_id = reset_id + 1) begin
        #1;
        case_id = 12 + reset_id;
        reset_core;
        case (reset_id)
            0: abort_cycles = 0;
            1: abort_cycles = 1;
            2: abort_cycles = 17;
            3: abort_cycles = 80;
            4: abort_cycles = 81;
        endcase
        launch(ABC_BLOCK, IV);
        @(negedge clk);
        i_start = 1'b0;
        sample_after(abort_cycles, "before reset interruption");
        reset_core;
        run_block(EMPTY_BLOCK, IV);
    end

    $display("===========End===========");
    $finish;
end

endmodule

