`timescale 1ns / 1ps
module testbench;

// Inputs
reg clk;
reg reset;
reg [15:0] frets;
reg e, a, d, g;

// Outputs
wire speaker;

integer ch, note, phase, mode, mask, stage;
integer t, short_t, long_t, old_t, new_t, elapsed;
integer case_id;

tuner uut (
    .clk(clk), .reset(reset), .frets(frets),
    .e(e), .a(a), .d(d), .g(g), .speaker(speaker)
);

initial clk = 0;
always #5 clk = ~clk;

// Published terminal counts, used only for stimulus timing.
function integer terminal;
    input integer channel;
    input integer selection;
    reg [79:0] row;
    begin
        case (selection)
             1: row = {20'd572672,20'd429037,20'd321419,20'd240790};
             2: row = {20'd540541,20'd404957,20'd303380,20'd227273};
             3: row = {20'd510204,20'd382234,20'd286352,20'd214519};
             4: row = {20'd481556,20'd360776,20'd270270,20'd202478};
             5: row = {20'd454545,20'd340530,20'd255102,20'd191110};
             6: row = {20'd429037,20'd321419,20'd240790,20'd180388};
             7: row = {20'd404957,20'd303380,20'd227273,20'd170265};
             8: row = {20'd382234,20'd286352,20'd214519,20'd160705};
             9: row = {20'd360776,20'd270270,20'd202478,20'd151685};
            10: row = {20'd340530,20'd255102,20'd191110,20'd143172};
            11: row = {20'd321419,20'd240790,20'd180388,20'd135139};
            12: row = {20'd303380,20'd227273,20'd170265,20'd127551};
            13: row = {20'd286352,20'd214519,20'd160705,20'd120395};
            14: row = {20'd270270,20'd202478,20'd151685,20'd113636};
            15: row = {20'd255102,20'd191110,20'd143172,20'd107259};
            16: row = {20'd240790,20'd180388,20'd135139,20'd101239};
            default:
                row = {20'd606722,20'd454545,20'd340530,20'd255102};
        endcase
        terminal = row[(3-channel)*20 +: 20];
    end
endfunction

function [15:0] fret_pattern;
    input integer selection;
    begin
        case (selection)
             0: fret_pattern = 16'h0000;
            17: fret_pattern = 16'h0003;
            18: fret_pattern = 16'h8001;
            19: fret_pattern = 16'hffff;
            default: fret_pattern = 16'h0001 << (selection-1);
        endcase
    end
endfunction

task observe;
    input [8*40-1:0] label;
    begin
        $display("case=%0d time=%0t %0s reset=%b frets=%h eadg=%b speaker=%b",
                 case_id, $time, label, reset, frets, {e,a,d,g}, speaker);
    end
endtask

task cycles;
    input integer count;
    input [8*40-1:0] label;
    begin
        repeat (count) @(posedge clk);
        #1;
        observe(label);
    end
endtask

task initialize_case;
    input [15:0] selection;
    input [3:0] enables;
    begin
        @(negedge clk);
        case_id = case_id + 1;
        reset = 1;
        frets = selection;
        {e,a,d,g} = enables;
        cycles(2, "case reset");
        @(negedge clk);
        reset = 0;
    end
endtask

task observe_period;
    input integer count;
    begin
        cycles(count,   "before first transition");
        cycles(1,       "first transition boundary");
        cycles(1,       "after first transition");
        cycles(count-1, "before second transition");
        cycles(1,       "second transition boundary");
        cycles(1,       "after second transition");
    end
endtask

initial begin
    reset = 1;
    frets = 0;
    {e,a,d,g} = 0;
    case_id = 0;

    // Wait 100 ns for global reset to finish.
    #100;
    observe("startup reset");

    // All selections, isolated channels, and disabled operation.
    for (ch = 0; ch < 4; ch = ch + 1) begin
        #1;
        for (note = 0; note < 20; note = note + 1) begin
            #1;
            t = terminal(ch, note);
            initialize_case(fret_pattern(note), 4'b0000);
            cycles(2, "all channels disabled");
            @(negedge clk);
            {e,a,d,g} = 4'b1000 >> ch;
            observe_period(t);
        end
    end

    // Disable and resume during each phase interval.
    for (ch = 0; ch < 4; ch = ch + 1) begin
        #1;
        t = terminal(ch, 16);
        for (phase = 0; phase < 2; phase = phase + 1) begin
            #1;
            initialize_case(16'h8000, 4'b1000 >> ch);
            cycles(phase*(t+1) + t/2, "partial interval before disable");
            @(negedge clk);
            {e,a,d,g} = 0;
            #1;
            observe("disable before rising edge");
            cycles(1, "disable sampled");
            cycles(t+2, "extended disabled interval");
            @(negedge clk);
            {e,a,d,g} = 4'b1000 >> ch;
            cycles(t-t/2, "resumed terminal boundary");
            cycles(1, "resumed transition boundary");
            cycles(t, "before next resumed transition");
            cycles(1, "next resumed transition");
        end
    end

    // Threshold increase; decrease below, at, and above new threshold.
    for (ch = 0; ch < 4; ch = ch + 1) begin
        #1;
        short_t = terminal(ch, 16);
        long_t = terminal(ch, 0);
        for (mode = 0; mode < 4; mode = mode + 1) begin
            #1;
            old_t = (mode == 0) ? short_t : long_t;
            new_t = (mode == 0) ? long_t : short_t;
            case (mode)
                0, 1: elapsed = short_t/2;
                2:    elapsed = short_t;
                3:    elapsed = short_t+1;
            endcase
            for (phase = 0; phase < 2; phase = phase + 1) begin
                #1;
                initialize_case((mode == 0) ? 16'h8000 : 16'h0000,
                                4'b1000 >> ch);
                cycles(phase*(old_t+1) + elapsed, "before fret change");
                @(negedge clk);
                frets = (mode == 0) ? 16'h0000 : 16'h8000;
                #1;
                observe("fret change before rising edge");
                if (mode < 2)
                    cycles(new_t-elapsed, "before changed terminal");
                cycles(1, "changed terminal response");
                cycles(new_t, "before following transition");
                cycles(1, "following transition boundary");
            end
        end
    end

    // Between-edge reset pulse, synchronous reset, and restart timing.
    for (ch = 0; ch < 4; ch = ch + 1) begin
        #1;
        t = terminal(ch, 16);
        initialize_case(16'h8000, 4'b1000 >> ch);
        cycles(t+1+t/2, "active tone before reset pulse");

        @(negedge clk);
        reset = 1;
        #1;
        observe("between-edge reset asserted");
        #1;
        reset = 0;
        #1;
        observe("between-edge reset released");
        cycles(1, "after between-edge reset pulse");

        @(negedge clk);
        reset = 1;
        #1;
        observe("reset before rising edge");
        cycles(1, "synchronous reset sampled");
        cycles(2, "reset held with channel enabled");
        @(negedge clk);
        reset = 0;
        observe_period(t);
    end

    // All enable masks; align first transitions using terminal differences.
    for (mask = 0; mask < 16; mask = mask + 1) begin
        #1;
        initialize_case(16'h8000, 4'b0000);
        for (stage = 0; stage < 4; stage = stage + 1) begin
            @(negedge clk);
            {e,a,d,g} = mask & (4'b1111 << (3-stage));
            #1;
            if (stage < 3)
                cycles(terminal(stage,16)-terminal(stage+1,16),
                       "staggered activation");
            else
                cycles(terminal(3,16), "before aligned transitions");
        end
        cycles(1, "aligned transition boundary");
        cycles(1, "after aligned transitions");

        for (stage = 0; stage < 4; stage = stage + 1) begin
            @(negedge clk);
            {e,a,d,g} = {e,a,d,g} & ~(4'b1000 >> stage);
            #1;
            observe("remove channel before rising edge");
            cycles(1, "channel removal sampled");
        end
    end

    $display("===========End=========== speaker=%b", speaker);
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam TLBNUM = 32;

// Inputs
reg clk;
reg [TLBNUM*20-1:0] all_pfn0, all_pfn1;
reg [TLBNUM*6-1:0] all_ps;
reg [TLBNUM*2-1:0] all_mat0, all_mat1, all_plv0, all_plv1;
reg [TLBNUM-1:0] all_d0, all_d1, all_v0, all_v1;
reg [TLBNUM-1:0] found0, found1;
reg odd0_bit_12, odd0_bit_21, odd1_bit_12, odd1_bit_21;

// Outputs
wire found_v0, found_d0, found_v1, found_d1;
wire [1:0] found_mat0, found_plv0, found_mat1, found_plv1;
wire [19:0] found_pfn0, found_pfn1;
wire [5:0] found_ps0, found_ps1;

integer i, p, s, m;
reg [5:0] page_size;

// Instantiate the Unit Under Test (UUT)
TLB_found_signal #(.TLBNUM(TLBNUM)) uut (
    .all_pfn0(all_pfn0), .all_ps(all_ps),
    .all_mat0(all_mat0), .all_plv0(all_plv0),
    .all_d0(all_d0), .all_v0(all_v0), .found0(found0),
    .odd0_bit_12(odd0_bit_12), .odd0_bit_21(odd0_bit_21),
    .all_pfn1(all_pfn1),
    .all_mat1(all_mat1), .all_plv1(all_plv1),
    .all_d1(all_d1), .all_v1(all_v1), .found1(found1),
    .odd1_bit_12(odd1_bit_12), .odd1_bit_21(odd1_bit_21),
    .found_v0(found_v0), .found_d0(found_d0),
    .found_mat0(found_mat0), .found_plv0(found_plv0),
    .found_pfn0(found_pfn0), .found_ps0(found_ps0),
    .found_v1(found_v1), .found_d1(found_d1),
    .found_mat1(found_mat1), .found_plv1(found_plv1),
    .found_pfn1(found_pfn1), .found_ps1(found_ps1)
);

// clk toggle generate
initial clk = 0;
always #5 clk = ~clk;

task clear_inputs;
begin
    all_pfn0 = 0; all_pfn1 = 0; all_ps = 0;
    all_mat0 = 0; all_mat1 = 0;
    all_plv0 = 0; all_plv1 = 0;
    all_d0 = 0; all_d1 = 0; all_v0 = 0; all_v1 = 0;
    found0 = 0; found1 = 0;
    {odd0_bit_12, odd0_bit_21, odd1_bit_12, odd1_bit_21} = 0;
end
endtask

task load_table;
    integer e;
begin
    clear_inputs;
    for (e = 0; e < TLBNUM; e = e + 1) begin
        all_ps[e*6 +: 6] = e[0] ? 6'd21 : 6'd12;
        all_pfn0[e*20 +: 20] = 20'h54320 + e;
        all_pfn1[e*20 +: 20] = ~(20'h54320 + e);
        all_mat0[e*2 +: 2] = e[1:0];
        all_mat1[e*2 +: 2] = ~e[1:0];
        all_plv0[e*2 +: 2] = e[1:0] + 2'd1;
        all_plv1[e*2 +: 2] = e[1:0] + 2'd2;
        all_v0[e] = e[0];  all_v1[e] = ~e[0];
        all_d0[e] = e[1];  all_d1[e] = ~e[1];
        #1;
    end
end
endtask

task observe;
    input integer tc;
    input integer step;
begin
    $display("tc=%0d step=%0d t=%0t found0=%h found1=%h odd0=%b%b odd1=%b%b found_v0=%b found_d0=%b found_mat0=%h found_plv0=%h found_pfn0=%h found_ps0=%h found_v1=%b found_d1=%b found_mat1=%h found_plv1=%h found_pfn1=%h found_ps1=%h",
        tc, step, $time, found0, found1,
        odd0_bit_12, odd0_bit_21, odd1_bit_12, odd1_bit_21,
        found_v0, found_d0, found_mat0, found_plv0,
        found_pfn0, found_ps0,
        found_v1, found_d1, found_mat1, found_plv1,
        found_pfn1, found_ps1);
end
endtask

task sweep_selectors;
    input integer tc;
    integer sel;
begin
    for (sel = 0; sel < 16; sel = sel + 1) begin
        {odd0_bit_12, odd0_bit_21,
         odd1_bit_12, odd1_bit_21} = sel[3:0];
        #1;
        observe(tc, sel);
    end
end
endtask

initial begin
    // Initialize Inputs; retain the template's 100 ns startup interval.
    clear_inputs;
    #100;

    // Test Case 1: Initialization and no matches.
    observe(1, 0);
    load_table;
    sweep_selectors(1);

    // Test Case 2: Every entry, both page-size branches and subpages.
    for (p = 0; p < 2; p = p + 1) begin
        load_table;
        page_size = p[0] ? 6'd21 : 6'd12;
        all_ps = {TLBNUM{page_size}};
        #1;
        for (i = 0; i < TLBNUM; i = i + 1) begin
            found0 = 32'h00000001 << i;
            found1 = 32'h00000001 << (31-i);
            #1;
            for (s = 0; s < 4; s = s + 1) begin
                {odd0_bit_12, odd0_bit_21} = s[1:0];
                {odd1_bit_12, odd1_bit_21} = ~s[1:0];
                #1;
                observe(2, p*128 + i*4 + s);
            end
        end
    end

    // Test Case 3: Page-size boundaries and independent selectors.
    for (p = 0; p < 6; p = p + 1) begin
        load_table;
        case (p)
            0: page_size = 6'd0;
            1: page_size = 6'd11;
            2: page_size = 6'd12;
            3: page_size = 6'd13;
            4: page_size = 6'd21;
            5: page_size = 6'd63;
        endcase
        all_ps[0 +: 6] = page_size;
        found0 = 32'h00000001;
        found1 = 32'h00000001;
        #1;
        sweep_selectors(30+p);
    end

    load_table;
    found0 = 32'h00000001;
    found1 = 0;
    #1;
    sweep_selectors(36);
    found0 = 0;
    found1 = 32'h80000000;
    #1;
    sweep_selectors(37);

    // Test Case 4: Sparse, alternating and full match reductions.
    for (m = 0; m < 4; m = m + 1) begin
        load_table;
        all_pfn0[0 +: 20] = 20'h0000f;
        all_pfn0[31*20 +: 20] = 20'hf0000;
        all_pfn1[0 +: 20] = 20'h00f00;
        all_pfn1[31*20 +: 20] = 20'h0f000;
        case (m)
            0: begin
                found0 = 32'h80000001;
                found1 = 32'h80000001;
            end
            1: begin
                found0 = 32'h55555555;
                found1 = 32'haaaaaaaa;
            end
            2: begin
                found0 = 32'haaaaaaaa;
                found1 = 32'h55555555;
            end
            3: begin
                found0 = 32'hffffffff;
                found1 = 32'hffffffff;
            end
        endcase
        #1;
        sweep_selectors(40+m);
    end

    // Test Case 5: Zero/max fields and removal of active matches.
    for (p = 0; p < 2; p = p + 1) begin
        clear_inputs;
        page_size = p[0] ? 6'd21 : 6'd12;
        all_ps = {TLBNUM{page_size}};
        all_pfn1 = {TLBNUM{20'hfffff}};
        all_mat1 = {TLBNUM{2'b11}};
        all_plv1 = {TLBNUM{2'b11}};
        all_d1 = {TLBNUM{1'b1}};
        all_v1 = {TLBNUM{1'b1}};
        found0 = 32'h00000001;
        found1 = 32'h80000000;
        #1;
        sweep_selectors(50+p);
        found0 = 0;
        found1 = 0;
        #1;
        observe(52, p);
    end

    clear_inputs;
    #1;
    observe(53, 0);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

// Timeout observation bound includes gap entry, expiration, and cleanup.
localparam GAP_BOUND = (1 << 3) + 4;

// Inputs
reg clk;
reg reset;
reg out_ep_grant, out_ep_data_avail, out_ep_setup, out_ep_acked;
reg [7:0] out_ep_data;
reg in_ep_grant, in_ep_data_free, in_ep_acked;
reg [7:0] uart_in_data;
reg uart_in_valid, uart_out_ready;

// Outputs
wire out_ep_req, out_ep_data_get, out_ep_stall;
wire in_ep_req, in_ep_data_put, in_ep_data_done, in_ep_stall;
wire [7:0] in_ep_data;
wire uart_in_ready, uart_out_valid;
wire [7:0] uart_out_data;
wire [3:0] debug;

integer test_id, i, mode, gap_index, gap_cycles;

usb_uart_bridge_ep uut (
    .clk(clk),
    .reset(reset),
    .out_ep_req(out_ep_req),
    .out_ep_grant(out_ep_grant),
    .out_ep_data_avail(out_ep_data_avail),
    .out_ep_setup(out_ep_setup),
    .out_ep_data_get(out_ep_data_get),
    .out_ep_data(out_ep_data),
    .out_ep_stall(out_ep_stall),
    .out_ep_acked(out_ep_acked),
    .in_ep_req(in_ep_req),
    .in_ep_grant(in_ep_grant),
    .in_ep_data_free(in_ep_data_free),
    .in_ep_data_put(in_ep_data_put),
    .in_ep_data(in_ep_data),
    .in_ep_data_done(in_ep_data_done),
    .in_ep_stall(in_ep_stall),
    .in_ep_acked(in_ep_acked),
    .uart_in_data(uart_in_data),
    .uart_in_valid(uart_in_valid),
    .uart_in_ready(uart_in_ready),
    .uart_out_data(uart_out_data),
    .uart_out_valid(uart_out_valid),
    .uart_out_ready(uart_out_ready),
    .debug(debug)
);

initial clk = 0; //clk is initialized as 0
always #5 clk = ~clk;

task observe;
begin
    $display("T=%0t case=%0d reset=%b out_ep_req=%b out_ep_data_get=%b out_ep_stall=%b in_ep_req=%b in_ep_data_put=%b in_ep_data=%02h in_ep_data_done=%b in_ep_stall=%b uart_in_ready=%b uart_out_data=%02h uart_out_valid=%b debug=%b",
             $time, test_id, reset,
             out_ep_req, out_ep_data_get, out_ep_stall,
             in_ep_req, in_ep_data_put, in_ep_data,
             in_ep_data_done, in_ep_stall,
             uart_in_ready, uart_out_data, uart_out_valid, debug);
end
endtask

// Sample settled outputs each cycle; return at a safe driving edge.
task cycles;
input integer count;
integer n;
begin
    for (n = 0; n < count; n = n + 1) begin
        @(posedge clk);
        #1;
        observe;
        @(negedge clk);
    end
end
endtask

task clear_inputs;
begin
    out_ep_grant = 0;
    out_ep_data_avail = 0;
    out_ep_setup = 0;
    out_ep_acked = 0;
    out_ep_data = 0;
    in_ep_grant = 0;
    in_ep_data_free = 0;
    in_ep_acked = 0;
    uart_in_data = 0;
    uart_in_valid = 0;
    uart_out_ready = 0;
end
endtask

// Preserve traffic inputs initially to expose synchronous reset behavior.
task reset_dut;
begin
    @(negedge clk);
    reset = 1;
    #1;
    observe;
    cycles(2);
    clear_inputs;
    cycles(1);
    reset = 0;
    cycles(1);
end
endtask

task start_in;
input [7:0] data_byte;
begin
    in_ep_grant = 1;
    in_ep_data_free = 1;
    uart_in_valid = 1;
    uart_in_data = data_byte;
    cycles(2);
end
endtask

initial begin
    // Initialize inputs and wait 100 ns for global reset to finish.
    test_id = 0;
    reset = 1;
    clear_inputs;
    #100;
    reset_dut;
    cycles(2);

    // Case 1: OUT delayed grant, continuous bytes, and normal drain.
    test_id = 1;
    reset_dut;
    uart_out_ready = 1;
    out_ep_data_avail = 1;
    cycles(3);
    out_ep_grant = 1;
    cycles(2);
    for (i = 0; i < 4; i = i + 1) begin
        #1;
        case (i)
            0: out_ep_data = 8'h00;
            1: out_ep_data = 8'hff;
            2: out_ep_data = 8'h55;
            3: out_ep_data = 8'haa;
        endcase
        out_ep_setup = i % 2;
        out_ep_acked = i % 2;
        cycles(1);
    end
    out_ep_data = 8'h81;
    out_ep_data_avail = 0;
    cycles(4);
    out_ep_grant = 0;
    cycles(1);

    // Cases 2-3: deferred byte, with continuing data or packet end.
    for (mode = 0; mode < 2; mode = mode + 1) begin
        #1;
        test_id = 2 + mode;
        reset_dut;
        out_ep_grant = 1;
        out_ep_data_avail = 1;
        out_ep_data = 8'h12;
        uart_out_ready = 1;
        cycles(3);
        uart_out_ready = 0;
        out_ep_data = 8'h34;
        out_ep_data_avail = mode;
        cycles(4);
        uart_out_ready = 1;
        cycles(1);
        if (mode) begin
            out_ep_data = 8'h56;
            cycles(1);
            out_ep_data = 8'h78;
            out_ep_data_avail = 0;
            cycles(1);
        end
        uart_out_ready = 0;
        cycles(3);
        uart_out_ready = 1;
        cycles(3);
    end

    // Case 4: IN qualification, delayed grant, byte stream, abort/restart.
    test_id = 4;
    reset_dut;
    in_ep_grant = 1;
    in_ep_data_free = 1;
    uart_in_data = 8'ha5;
    cycles(2);
    uart_in_valid = 1;
    in_ep_data_free = 0;
    cycles(2);
    in_ep_grant = 0;
    in_ep_data_free = 1;
    cycles(3);
    in_ep_grant = 1;
    cycles(2);
    for (i = 0; i < 4; i = i + 1) begin
        #1;
        case (i)
            0: uart_in_data = 8'h00;
            1: uart_in_data = 8'hff;
            2: uart_in_data = 8'h55;
            3: uart_in_data = 8'haa;
        endcase
        in_ep_acked = i % 2;
        cycles(1);
    end
    uart_in_data = 8'h69;
    in_ep_data_free = 0;
    cycles(3);
    in_ep_data_free = 1;
    cycles(3);
    uart_in_valid = 0;
    cycles(GAP_BOUND);

    // Cases 10-14: short gap and both sides of timeout expiration.
    for (gap_index = 0; gap_index < 5; gap_index = gap_index + 1) begin
        #1;
        test_id = 10 + gap_index;
        reset_dut;
        case (gap_index)
            0: gap_cycles = 1;
            1: gap_cycles = (1 << 3);
            2: gap_cycles = (1 << 3) + 1;
            3: gap_cycles = (1 << 3) + 2;
            4: gap_cycles = GAP_BOUND;
        endcase
        start_in(8'h31);
        uart_in_valid = 0;
        cycles(gap_cycles);
        uart_in_data = 8'hc7;
        uart_in_valid = 1;
        cycles(4);
        uart_in_valid = 0;
        cycles(GAP_BOUND);
    end

    // Cases 20-21: no endpoint space during a gap, with/without return.
    for (mode = 0; mode < 2; mode = mode + 1) begin
        #1;
        test_id = 20 + mode;
        reset_dut;
        start_in(8'h42);
        uart_in_valid = 0;
        in_ep_data_free = 0;
        cycles(3);
        if (mode) begin
            uart_in_data = 8'h24;
            uart_in_valid = 1;
        end
        cycles(GAP_BOUND);
        in_ep_data_free = 1;
        uart_in_data = 8'h24;
        uart_in_valid = 1;
        cycles(4);
        uart_in_valid = 0;
        cycles(GAP_BOUND);
    end

    // Case 30: simultaneous streams, reset while both are active.
    test_id = 30;
    reset_dut;
    out_ep_grant = 1;
    out_ep_data_avail = 1;
    uart_out_ready = 1;
    in_ep_grant = 1;
    in_ep_data_free = 1;
    uart_in_valid = 1;
    out_ep_data = 8'h96;
    uart_in_data = 8'h69;
    cycles(3);
    for (i = 0; i < 4; i = i + 1) begin
        #1;
        out_ep_data = 8'h10 + i;
        uart_in_data = 8'h80 + i;
        out_ep_setup = i % 2;
        out_ep_acked = (i + 1) % 2;
        in_ep_acked = i % 2;
        cycles(1);
    end
    reset_dut;

    // Case 31: reset with OUT buffering and an IN inter-byte gap.
    test_id = 31;
    out_ep_grant = 1;
    out_ep_data_avail = 1;
    uart_out_ready = 1;
    out_ep_data = 8'hde;
    start_in(8'hbc);
    cycles(1);
    uart_out_ready = 0;
    out_ep_data = 8'had;
    uart_in_valid = 0;
    cycles(3);
    reset_dut;

    // Case 32: reset during final OUT drain and IN completion.
    test_id = 32;
    out_ep_grant = 1;
    out_ep_data_avail = 1;
    uart_out_ready = 1;
    out_ep_data = 8'h5a;
    start_in(8'ha5);
    cycles(1);
    out_ep_data_avail = 0;
    out_ep_data = 8'hc3;
    cycles(1);
    uart_out_ready = 0;
    uart_in_valid = 0;
    cycles((1 << 3) + 2);
    reset_dut;
    start_in(8'h7e);
    uart_in_valid = 0;
    cycles(GAP_BOUND);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

parameter depth = 4;
parameter width = 8;

// Inputs
reg clk;
reg arstn;
reg m_axis_tready;
reg [width-1:0] s_axis_tdata;
reg s_axis_tvalid;

// Outputs
wire [width-1:0] m_axis_tdata;
wire m_axis_tvalid;
wire s_axis_tready;

integer i;

util_axis_tiny_fifo #(
    .depth(depth),
    .width(width)
) uut (
    .aclk(clk),
    .arstn(arstn),
    .m_axis_tready(m_axis_tready),
    .s_axis_tdata(s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .m_axis_tdata(m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .s_axis_tready(s_axis_tready)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [8*32-1:0] label;
    begin
        $display("%0t %0s rstn=%b in_valid=%b in_data=%h out_ready=%b | m_axis_tdata=%h m_axis_tvalid=%b s_axis_tready=%b",
                 $time, label, arstn, s_axis_tvalid, s_axis_tdata,
                 m_axis_tready, m_axis_tdata, m_axis_tvalid,
                 s_axis_tready);
    end
endtask

task cycle;
    input [8*32-1:0] label;
    input reset_n;
    input valid_in;
    input ready_out;
    input [width-1:0] data_in;
    begin
        @(negedge clk);
        arstn = reset_n;
        s_axis_tvalid = valid_in;
        m_axis_tready = ready_out;
        s_axis_tdata = data_in;
        @(posedge clk);
        #1;
        observe(label);
    end
endtask

task reset_queue;
    begin
        cycle("reset", 0, 0, 0, 0);
        cycle("reset held", 0, 0, 0, 0);
        cycle("reset released", 1, 0, 0, 0);
    end
endtask

// Each loop iteration advances through cycle() and prints after the edge.
task idle_cycles;
    input [8*32-1:0] label;
    input integer count;
    input ready_out;
    integer n;
    begin
        for (n = 0; n < count; n = n + 1) begin
            cycle(label, 1, 0, ready_out, 0);
        end
    end
endtask

initial begin
    arstn = 0;
    m_axis_tready = 0;
    s_axis_tdata = 0;
    s_axis_tvalid = 0;

    // Wait 100 ns for global reset to finish.
    #100;
    observe("startup reset");

    // Empty and isolated-word operation.
    reset_queue;
    idle_cycles("empty stalled", 2, 0);
    idle_cycles("empty ready", 2, 1);
    cycle("isolated zero input", 1, 1, 0, {width{1'b0}});
    idle_cycles("single word held", depth + 2, 0);
    idle_cycles("consume and empty reads", depth + 2, 1);
    cycle("isolated ones ready", 1, 1, 1, {width{1'b1}});
    idle_cycles("isolated word drain", depth + 2, 1);

    // Fill, block an extra word, and replenish while draining.
    reset_queue;
    for (i = 0; i < depth; i = i + 1) begin
        cycle("fill to capacity", 1, 1, 0, i + 1);
    end
    for (i = 0; i < 3; i = i + 1) begin
        cycle("full blocked input", 1, 1, 0, {width{1'b1}});
    end
    cycle("release blocked input", 1, 1, 1, {width{1'b1}});
    for (i = 0; i < 2 * depth; i = i + 1) begin
        cycle("simultaneous transfers", 1, 1, 1, i + 16);
    end
    idle_cycles("full queue drain", depth + 2, 1);

    // Gapped input and changing output backpressure.
    reset_queue;
    for (i = 0; i < depth; i = i + 1) begin
        cycle("gapped input A", 1, 1, 0, 'h55);
        cycle("input gap stalled", 1, 0, 0, 'hAA);
        cycle("gapped input B", 1, 1, 1, 'hAA);
        cycle("input gap ready", 1, 0, 1, {width{1'b1}});
    end
    idle_cycles("partial queue settle", depth + 1, 0);
    idle_cycles("partial queue drain", depth + 2, 1);

    // Reset a full queue despite asserted transfer requests.
    reset_queue;
    for (i = 0; i < depth; i = i + 1) begin
        cycle("fill before reset", 1, 1, 0, i + 32);
    end
    cycle("reset during requests", 0, 1, 1, {width{1'b1}});
    cycle("reset held stalled", 0, 1, 0, 'h55);
    cycle("reset release empty", 1, 0, 1, 0);
    idle_cycles("empty after reset", depth + 1, 1);
    cycle("fresh post-reset input", 1, 1, 0, 'hAA);
    idle_cycles("post-reset hold", depth + 1, 0);
    idle_cycles("post-reset drain", depth + 2, 1);

    $display("===========End=========== m_axis_tdata=%h m_axis_tvalid=%b s_axis_tready=%b",
             m_axis_tdata, m_axis_tvalid, s_axis_tready);
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

// Inputs
reg clk;
reg [31:0] rs1, rs2, arg_0, padd_result;
reg [5:0] count;
reg [63:0] acc;
reg carryless, pw_32, pw_16, pw_8, pw_4, pw_2;
reg lhs_sign, rhs_sign;
reg [32:0] padd_cout;

// Outputs
wire [31:0] padd_lhs, padd_rhs, n_arg_0;
wire padd_sub, padd_cin, padd_cen, ready;
wire [63:0] n_acc;

integer i, j;

xc_malu_mul uut (
    .rs1(rs1), .rs2(rs2), .count(count), .acc(acc),
    .arg_0(arg_0), .carryless(carryless),
    .pw_32(pw_32), .pw_16(pw_16), .pw_8(pw_8),
    .pw_4(pw_4), .pw_2(pw_2),
    .lhs_sign(lhs_sign), .rhs_sign(rhs_sign),
    .padd_lhs(padd_lhs), .padd_rhs(padd_rhs),
    .padd_sub(padd_sub), .padd_cin(padd_cin),
    .padd_cen(padd_cen), .padd_cout(padd_cout),
    .padd_result(padd_result), .n_acc(n_acc),
    .n_arg_0(n_arg_0), .ready(ready)
);

initial clk = 0;
always #5 clk = ~clk;

task initialize_inputs;
begin
    rs1 = 0;
    rs2 = 0;
    count = 0;
    acc = 0;
    arg_0 = 0;
    carryless = 0;
    {pw_32, pw_16, pw_8, pw_4, pw_2} = 0;
    lhs_sign = 0;
    rhs_sign = 0;
    padd_cout = 0;
    padd_result = 0;
end
endtask

task observe;
    input [159:0] label;
    input integer index;
begin
    $display("%0s[%0d] padd_lhs=%08h padd_rhs=%08h padd_sub=%b padd_cin=%b padd_cen=%b n_acc=%016h n_arg_0=%08h ready=%b",
             label, index, padd_lhs, padd_rhs, padd_sub,
             padd_cin, padd_cen, n_acc, n_arg_0, ready);
end
endtask

initial begin
    initialize_inputs;

    // Initialization: no DUT reset port.
    #100;
    observe("initial", 0);

    // All width encodings and adjacent counts.
    initialize_inputs;
    for (i = 0; i < 32; i = i + 1) begin
        {pw_32, pw_16, pw_8, pw_4, pw_2} = i;
        count = 2*i - 1;
        #1;
        observe("threshold_before", i);
        count = 2*i;
        #1;
        observe("threshold_at", i);
        count = 2*i + 1;
        #1;
        observe("threshold_after", i);
    end

    // All combinations affecting the generated upper bit.
    initialize_inputs;
    pw_32 = 1;
    count = 31;
    rs2 = 32'h80000000;
    padd_result = 32'h96a53cc3;
    for (i = 0; i < 128; i = i + 1) begin
        carryless = i[6];
        lhs_sign = i[5];
        acc = {i[4], 31'h12345678, 32'h89abcdef};
        rs1 = {i[3], 31'h00000001};
        arg_0 = {31'h456789ab, i[2]};
        rhs_sign = i[1];
        padd_cout = 0;
        padd_cout[31] = i[0];
        #1;
        observe("upper_bit_controls", i);
    end

    // Each signed-correction condition and neighboring counts.
    initialize_inputs;
    pw_32 = 1;
    arg_0 = 32'hffffffff;
    for (j = 0; j < 3; j = j + 1) begin
        count = 30 + j;
        #1;
        for (i = 0; i < 8; i = i + 1) begin
            rs2 = {i[2], 31'b0};
            rhs_sign = i[1];
            rs1 = {31'b0, i[0]};
            #1;
            observe("signed_correction", 8*j + i);
        end
    end

    // Every multiplicand bit can make the operand nonzero.
    initialize_inputs;
    count = 31;
    rs2 = 32'h80000000;
    rhs_sign = 1;
    for (i = 0; i < 32; i = i + 1) begin
        rs1 = 32'h00000001 << i;
        arg_0 = 0;
        #1;
        observe("nonzero_disabled", i);
        arg_0 = 32'hffffffff;
        #1;
        observe("nonzero_enabled", i);
    end

    // Walking and complementary data patterns.
    initialize_inputs;
    for (i = 0; i < 128; i = i + 1) begin
        acc = 64'h0000000000000001 << (i % 64);
        rs1 = 32'h00000001 << (i % 32);
        arg_0 = 32'h00000001 << (i % 32);
        padd_result = 32'h00000001 << (i % 32);
        if (i[6]) begin
            acc = ~acc;
            rs1 = ~rs1;
            arg_0 = ~arg_0;
            padd_result = ~padd_result;
        end
        #1;
        observe("data_patterns", i);
    end

    // Returned carry positions, with and without carry propagation.
    initialize_inputs;
    for (i = 0; i < 33; i = i + 1) begin
        padd_cout = 33'h000000001 << i;
        carryless = 0;
        #1;
        observe("carry_arithmetic", i);
        carryless = 1;
        #1;
        observe("carry_carryless", i);
    end

    // All-one and all-zero data boundaries.
    initialize_inputs;
    rs1 = 32'hffffffff;
    rs2 = 32'hffffffff;
    acc = 64'hffffffffffffffff;
    arg_0 = 32'hffffffff;
    padd_result = 32'hffffffff;
    padd_cout = 33'h1ffffffff;
    lhs_sign = 1;
    rhs_sign = 1;
    count = 31;
    pw_32 = 1;
    #1;
    observe("all_ones", 0);
    carryless = 1;
    #1;
    observe("all_ones_carryless", 0);

    initialize_inputs;
    #1;
    observe("all_zero_return", 0);

    $display("===========End===========");
    $finish;
end

endmodule

