`timescale 1ns / 1ps
module testbench;

reg clk;

reg iReset_n;
reg iStart;
reg iRead_data_valid;
reg iWait_request;
reg iFF_almost_full;
reg HC_ff0_wait_request;
reg R2Y_waitrequest;
reg [31:0] iStart_read_address;
reg [31:0] iLength;
reg [31:0] iRead_data;

wire oRead;
wire [31:0] oRead_address;
wire oFF_write_request;
wire [7:0] oBurst_length;
wire [31:0] oWrite_data;

ic_master_read_burst uut (
    .iClk                 (clk),
    .iReset_n             (iReset_n),
    .iStart               (iStart),
    .iRead_data_valid     (iRead_data_valid),
    .iWait_request        (iWait_request),
    .iFF_almost_full      (iFF_almost_full),
    .HC_ff0_wait_request  (HC_ff0_wait_request),
    .R2Y_waitrequest      (R2Y_waitrequest),
    .iStart_read_address  (iStart_read_address),
    .iLength              (iLength),
    .iRead_data           (iRead_data),
    .oRead                (oRead),
    .oRead_address        (oRead_address),
    .oFF_write_request    (oFF_write_request),
    .oBurst_length        (oBurst_length),
    .oWrite_data          (oWrite_data)
);

initial clk = 1'b0;
always #5 clk = ~clk;

task show_outputs;
    input integer tag;
    begin
        $display("OBS%d: oRead=%b oRead_address=%h oFF_write_request=%b oBurst_length=%h oWrite_data=%h",
                 tag, oRead, oRead_address, oFF_write_request,
                 oBurst_length, oWrite_data);
    end
endtask

task reset_dut;
    begin
        iReset_n = 1'b0;
        iStart = 1'b0;
        iRead_data_valid = 1'b0;
        iWait_request = 1'b0;
        iFF_almost_full = 1'b0;
        HC_ff0_wait_request = 1'b0;
        R2Y_waitrequest = 1'b0;
        iStart_read_address = 32'h0;
        iLength = 32'h0;
        iRead_data = 32'h0;

        repeat (2) @(posedge clk);
        #1 show_outputs(0);

        iReset_n = 1'b1;
        repeat (1) @(posedge clk);
        #1;
    end
endtask

task start_sequence;
    input [31:0] start_address;
    input [31:0] length_bytes;
    begin
        iStart_read_address = start_address;
        iLength = length_bytes;
        iStart = 1'b1;
        @(posedge clk);
        #1 show_outputs(1);
        iStart = 1'b0;
    end
endtask

task accept_command;
    begin
        iWait_request = 1'b0;
        @(posedge clk);
        #1 show_outputs(2);
    end
endtask

task send_burst_data;
    input [31:0] data_seed;
    integer k;
    begin
        iRead_data_valid = 1'b1;
        for (k = 0; k < 64; k = k + 1) begin
            iRead_data = data_seed + k;
            @(posedge clk);
            #1 show_outputs(3);
        end

        iRead_data_valid = 1'b0;
        iRead_data = 32'h0;
        @(posedge clk);
        #1 show_outputs(4);
    end
endtask

initial begin
    iReset_n = 1'b0;
    iStart = 1'b0;
    iRead_data_valid = 1'b0;
    iWait_request = 1'b0;
    iFF_almost_full = 1'b0;
    HC_ff0_wait_request = 1'b0;
    R2Y_waitrequest = 1'b0;
    iStart_read_address = 32'h0;
    iLength = 32'h0;
    iRead_data = 32'h0;

    // Test Case 1: reset and one normal burst.
    reset_dut;
    start_sequence(32'h00001000, 32'd256);
    accept_command;
    send_burst_data(32'h10000000);
    repeat (2) @(posedge clk);
    #1 show_outputs(5);
    repeat (1) @(posedge clk);
    #1 show_outputs(6);

    // Test Case 2: command backpressure on the first burst.
    reset_dut;
    start_sequence(32'h00002000, 32'd256);
    iWait_request = 1'b1;
    repeat (2) @(posedge clk);
    #1 show_outputs(7);
    accept_command;
    send_burst_data(32'h20000000);
    repeat (2) @(posedge clk);
    #1 show_outputs(8);
    repeat (1) @(posedge clk);
    #1 show_outputs(9);

    // Test Case 3: two bursts with inter-burst downstream backpressure.
    reset_dut;
    start_sequence(32'h00003000, 32'd512);
    accept_command;
    send_burst_data(32'h30000000);

    // Cover iFF_almost_full asserted while both other waits are clear.
    iFF_almost_full = 1'b1;
    HC_ff0_wait_request = 1'b0;
    R2Y_waitrequest = 1'b0;
    repeat (2) @(posedge clk);
    #1 show_outputs(10);

    // Keep FIFO almost full asserted while another downstream wait is active.
    HC_ff0_wait_request = 1'b1;
    repeat (2) @(posedge clk);
    #1 show_outputs(11);

    // Release FIFO pressure, but hold the HC wait request.
    iFF_almost_full = 1'b0;
    HC_ff0_wait_request = 1'b0;
    R2Y_waitrequest = 1'b1;
    repeat (2) @(posedge clk);
    #1 show_outputs(12);

    // Release all downstream backpressure.
    R2Y_waitrequest = 1'b0;
    @(posedge clk);
    #1 show_outputs(13);

    accept_command;
    send_burst_data(32'h30000100);
    repeat (2) @(posedge clk);
    #1 show_outputs(14);
    repeat (1) @(posedge clk);
    #1 show_outputs(15);

    // Test Case 4: zero-length boundary and suppressed forwarding.
    reset_dut;
    start_sequence(32'hfffffff0, 32'd0);
    accept_command;
    send_burst_data(32'h40000000);
    repeat (2) @(posedge clk);
    #1 show_outputs(16);
    repeat (1) @(posedge clk);
    #1 show_outputs(17);

    // Test Case 5: synchronous reset while the active burst state is running.
    reset_dut;
    start_sequence(32'h00005000, 32'd256);
    iRead_data = 32'h50000000;
    iRead_data_valid = 1'b1;
    @(posedge clk);
    #1 show_outputs(18);

    iRead_data_valid = 1'b0;
    iReset_n = 1'b0;
    @(posedge clk);
    #1 show_outputs(19);

    iReset_n = 1'b1;
    repeat (2) @(posedge clk);
    #1 show_outputs(20);

    // Test Case 6: synchronous reset after the controller has
    // progressed beyond the inter-burst admission state.
    reset_dut;
    start_sequence(32'h00006000, 32'd256);
    accept_command;
    send_burst_data(32'h60000000);

    // The extra clock places the controller in the inter-burst state,
    // then allows it to proceed toward cleanup.
    @(posedge clk);
    #1 show_outputs(21);

    iReset_n = 1'b0;
    @(posedge clk);
    #1 show_outputs(22);

    iReset_n = 1'b1;
    repeat (2) @(posedge clk);
    #1 show_outputs(23);

    // Test Case 7: apply reset immediately while the controller is
    // in the inter-burst admission state.  The 512-byte request keeps
    // the advanced address within the requested range, so state 2'h2
    // is entered and remains active until the reset edge.
    reset_dut;
    start_sequence(32'h00007000, 32'd512);
    accept_command;
    send_burst_data(32'h70000000);

    // send_burst_data leaves the DUT in state 2'h2 after its final
    // cleanup/command-observation clock.  Assert synchronous reset
    // without allowing an additional admission-state clock.
    iReset_n = 1'b0;
    @(posedge clk);
    #1 show_outputs(24);

    iReset_n = 1'b1;
    repeat (2) @(posedge clk);
    #1 show_outputs(25);

    $display("===========End===========");

    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

// Inputs
reg clk;
reg [15:0] current_address, jmp_address_pm;
reg [5:0] op;
reg [1:0] flag_ex;
reg interrupt, reset;

// Outputs
wire [15:0] jmp_loc;
wire pc_mux_sel;

integer code_index, flag_index, address_index;
reg [15:0] pulse_address;

JC_block uut (
    .jmp_loc(jmp_loc),
    .pc_mux_sel(pc_mux_sel),
    .current_address(current_address),
    .jmp_address_pm(jmp_address_pm),
    .op(op),
    .flag_ex(flag_ex),
    .interrupt(interrupt),
    .clk(clk),
    .reset(reset)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [8*40-1:0] label;
    begin
        #1;
        $display("%0s t=%0t reset=%b interrupt=%b op=%h flags=%b current=%h pm=%h jmp_loc=%h pc_mux_sel=%b",
                 label, $time, reset, interrupt, op, flag_ex,
                 current_address, jmp_address_pm, jmp_loc, pc_mux_sel);
    end
endtask

task sample_edge;
    input [8*40-1:0] label;
    begin
        @(posedge clk);
        observe(label);
    end
endtask

task initialize_case;
    begin
        @(negedge clk);
        reset = 0;
        interrupt = 0;
        current_address = 0;
        jmp_address_pm = 16'hA55A;
        op = 6'h10;
        flag_ex = 0;
        sample_edge("case initialization");
        @(negedge clk);
        reset = 1;
        op = 0;
    end
endtask

initial begin
    current_address = 0;
    jmp_address_pm = 0;
    op = 0;
    flag_ex = 0;
    interrupt = 0;
    reset = 0;

    // Wait 100 ns for global reset to finish.
    #100;
    observe("initial reset");

    // All opcodes, flag combinations, and ordinary target patterns.
    for (code_index = 0; code_index < 64; code_index = code_index + 1) begin
        @(negedge clk);
        initialize_case();
        for (flag_index = 0; flag_index < 4; flag_index = flag_index + 1) begin
            @(negedge clk);
            op = code_index;
            flag_ex = flag_index;
            case (flag_index)
                0: jmp_address_pm = 16'h0000;
                1: jmp_address_pm = 16'hFFFF;
                2: jmp_address_pm = 16'hA55A;
                3: jmp_address_pm = 16'h5AA5;
            endcase
            observe("instruction decode");
        end
    end

    // Independent one-cycle interrupts at address boundaries.
    for (address_index = 0; address_index < 4;
         address_index = address_index + 1) begin
        @(negedge clk);
        initialize_case();
        case (address_index)
            0: pulse_address = 16'h0000;
            1: pulse_address = 16'h7FFF;
            2: pulse_address = 16'hFFFE;
            3: pulse_address = 16'hFFFF;
        endcase

        @(negedge clk);
        current_address = pulse_address;
        flag_ex = address_index;
        interrupt = 1;
        observe("pulse before capture");
        sample_edge("pulse vector");

        op = 6'h10;
        observe("return during vector");

        @(negedge clk);
        interrupt = 0;
        current_address = 16'h2468;
        flag_ex = ~flag_ex;
        sample_edge("pulse return after release");

        @(negedge clk);
        op = 6'h00;
        flag_ex = address_index;
        sample_edge("pulse delayed context");

        @(negedge clk);
        op = 6'h10;
        current_address = 16'h1357;
        flag_ex = ~flag_ex;
        repeat (3) @(posedge clk);
        observe("pulse retained return");
    end

    // Sustained request: all opcode priorities and repeated address refresh.
    initialize_case();
    for (code_index = 0; code_index < 64; code_index = code_index + 1) begin
        @(negedge clk);
        interrupt = 1;
        op = code_index;
        flag_ex = code_index;
        current_address = 16'h4000 + code_index;
        jmp_address_pm = 16'h5AA5;
        sample_edge("held interrupt opcode");

        op = 6'h10;
        observe("held interrupt saved address");
    end

    @(negedge clk);
    interrupt = 0;
    op = 6'h00;
    current_address = 16'hAAAA;
    sample_edge("held interrupt release");
    repeat (3) @(posedge clk);
    observe("held interrupt drained");

    @(negedge clk);
    op = 6'h10;
    observe("held interrupt retained return");

    @(negedge clk);
    interrupt = 1;
    current_address = 16'hBEEF;
    flag_ex = 2'b11;
    op = 6'h18;
    sample_edge("second interrupt vector");

    @(negedge clk);
    interrupt = 0;
    op = 6'h10;
    sample_edge("second interrupt return");
    repeat (3) @(posedge clk);
    observe("second interrupt retained return");

    // Synchronous reset with active interrupt history and saved context.
    initialize_case();
    @(negedge clk);
    interrupt = 1;
    current_address = 16'h1234;
    flag_ex = 2'b11;
    repeat (3) @(posedge clk);
    observe("context before reset");

    @(negedge clk);
    reset = 0;
    observe("reset before clock vector");
    op = 6'h10;
    observe("reset before clock return");
    sample_edge("reset clears saved return");

    @(negedge clk);
    op = 6'h00;
    sample_edge("reset suppresses interrupt");

    @(negedge clk);
    op = 6'h18;
    observe("jump while reset low");

    @(negedge clk);
    op = 6'h1E;
    flag_ex = 2'b10;
    observe("conditional while reset low");

    @(negedge clk);
    reset = 1;
    op = 6'h00;
    current_address = 16'hFFFF;
    sample_edge("interrupt after reset release");

    @(negedge clk);
    interrupt = 0;
    op = 6'h10;
    sample_edge("return after reset release");
    repeat (3) @(posedge clk);
    observe("final retained return");

    $display("===========End===========");
    $finish;
end

endmodule

