        repeat (2) @(posedge clk);
        #1;
        observe;
        @(negedge clk);
        gmii_dv_i = 0;
        gmii_data_i = 0;
        gmii_er_i = 0;
        local_time = 0;
        rst_n = 1;
        @(posedge clk);
        #1;
        observe;
    end
endtask

task header;
    input [15:0] timestamp;
    integer h;
    begin
        send_byte(1, 8'h55, 0, timestamp);
        send_byte(1, 8'hd5, 1, ~timestamp);
        for (h = 0; h < 6; h = h + 1)
            send_byte(1, h, h % 2, ~timestamp);
    end
endtask

task payload;
    input dv;
    input [15:0] timestamp;
    integer p;
    begin
        for (p = 0; p < 10; p = p + 1)
            send_byte(dv, 8'h80 + p, p % 2, timestamp);
    end
endtask

task packet;
    input [7:0] type_byte;
    input [15:0] timestamp;
    begin
        header(timestamp);
        send_byte(1, type_byte, 1, ~timestamp);
        payload(1, ~timestamp);
        send_byte(0, 8'h00, 1, ~timestamp);
    end
endtask

initial begin
    rst_n = 0;
    gmii_dv_i = 0;
    gmii_data_i = 0;
    gmii_er_i = 0;
    local_time = 0;
    case_id = 0;

    // Wait 100 ns for global reset to finish.
    #100;
    observe;

    // Reset and idle pass-through.
    case_id = 1;
    reset_dut;
    send_byte(0, 8'h00, 0, 16'h0000);
    send_byte(0, 8'hff, 1, 16'hffff);
    send_byte(0, 8'hd5, 0, 16'h1234);

    // All type values and timestamp boundaries.
    for (i = 0; i < 8; i = i + 1) begin
        case_id = 10 + i;
        reset_dut;
        case (i)
            0, 1: stamp = 16'h12e7;
            4:    stamp = 16'h0000;
            5:    stamp = 16'hffff;
            default: stamp = 16'ha53c;
        endcase
        packet((i % 2 ? 8'hf8 : 8'ha0) | i, stamp);
    end

    // A D5 on the start edge is followed by a delayed delimiter.
    case_id = 20;
    reset_dut;
    send_byte(1, 8'hd5, 0, 16'h2468);
    send_byte(1, 8'h55, 1, 16'hffff);
    send_byte(1, 8'h00, 0, 16'h0000);
    send_byte(1, 8'hd5, 0, 16'hffff);
    for (j = 0; j < 6; j = j + 1)
        send_byte(1, j, j % 2, 16'hffff);
    send_byte(1, 8'ha0, 0, 16'hffff);
    payload(1, 16'hffff);
    send_byte(0, 0, 0, 0);

    // Reject each header position; do not end the frame before retrying.
    for (i = 0; i < 6; i = i + 1) begin
        case_id = 30 + i;
        reset_dut;
        send_byte(1, 8'h55, 0, 16'h369c);
        send_byte(1, 8'hd5, 0, 16'h369c);
        for (j = 0; j < 6; j = j + 1)
            send_byte(1, (j == i) ? 8'hff : j,
                      j % 2, 16'h369c);
        send_byte(1, 8'ha0, 1, 16'h369c);
        packet(8'ha1, 16'h1234);
        packet(8'ha0, 16'h5678);
    end

    // Missing delimiter, then parsing and insertion while invalid.
    for (i = 0; i < 2; i = i + 1) begin
        case_id = 40 + i;
        reset_dut;
        send_byte(1, 8'h55, 0, 16'h3ac5);
        send_byte(0, 8'h00, 1, 16'hffff);
        send_byte(0, 8'h55, 0, 16'hffff);
        send_byte(0, 8'hd5, 1, 16'hffff);
        for (j = 0; j < 6; j = j + 1)
            send_byte(0, j, j % 2, 16'hffff);
        send_byte(0, 8'ha0 + i, 1, 16'hffff);
        payload(0, 16'hffff);
        packet(8'ha0, 16'h9876);
    end

    // Consecutive packets with one invalid cycle between frames.
    case_id = 50;
    reset_dut;
    for (i = 0; i < 3; i = i + 1)
        packet(8'ha0 + i, 16'h1234 + i);

    // Interrupt each reachable processing phase with asynchronous reset.
    for (k = 0; k < 7; k = k + 1) begin
        case_id = 60 + k;
        reset_dut;
        if (k > 0)
            send_byte(1, 8'h55, 1, 16'hc35a);
        if (k > 1)
            send_byte(1, 8'hd5, 0, 16'h0000);
        if (k == 2)
            send_byte(1, 8'h00, 0, 16'h0000);
        if (k >= 3) begin
            for (j = 0; j < 6; j = j + 1)
                send_byte(1, j, j % 2, 16'h0000);
        end
        if (k >= 4) begin
            case (k)
                4: send_byte(1, 8'ha0, 1, 16'h0000);
                5: send_byte(1, 8'ha1, 1, 16'h0000);
                6: send_byte(1, 8'ha2, 1, 16'h0000);
            endcase
        end
        if (k == 4 || k == 5) begin
            // Interrupt between the two timestamp bytes.
            for (j = 0; j < ((k == 4) ? 2 : 6); j = j + 1)
                send_byte(1, 8'h70 + j, j % 2, 16'h0000);
        end
        reset_dut;
        packet(8'ha1, 16'h5ac3);
    end

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

parameter DOUT_W = 8;
parameter DIN_W  = 4;

// Inputs
reg clk;
reg rst_n;
reg [DIN_W-1:0] din;
reg din_vld;

// Outputs
wire [DOUT_W-1:0] dout;
wire dout_vld;

integer test_id;
integer i;
integer stage;

// Instantiate the Unit Under Test (UUT)
opcode_dect #(
    .DOUT_W(DOUT_W),
    .DIN_W(DIN_W)
) uut (
    .clk(clk),
    .rst_n(rst_n),
    .din(din),
    .din_vld(din_vld),
    .dout(dout),
    .dout_vld(dout_vld)
);

// clk toggle generate
initial clk = 0;
always #5 clk = ~clk;

task observe;
begin
    $display("test=%0d time=%0t rst_n=%b din=%h din_vld=%b dout=%h dout_vld=%b",
             test_id, $time, rst_n, din, din_vld, dout, dout_vld);
end
endtask

task cycle;
    input [DIN_W-1:0] value;
    input valid;
begin
    @(negedge clk);
    din = value;
    din_vld = valid;
    @(posedge clk);
    #1;
    observe;
end
endtask

// Packed sequences are sent most significant used nibble first.
task send;
    input [127:0] values;
    input integer count;
    integer n;
begin
    for (n = count - 1; n >= 0; n = n - 1) begin
        #1;
        cycle(values >> (4*n), 1'b1);
    end
end
endtask

task reset_dut;
begin
    @(negedge clk);
    din = 0;
    din_vld = 0;
    #2;
    rst_n = 0;
    #1;
    observe;
    repeat (2) @(posedge clk);
    #1;
    observe;
    @(negedge clk);
    rst_n = 1;
end
endtask

initial begin
    // Initialize inputs; hold reset for the initial 100 ns.
    test_id = 0;
    rst_n = 0;
    din = 0;
    din_vld = 0;
    #100;
    observe;

    // Test 1: held reset and recovery.
    test_id = 1;
    send(16'h55D5, 4);
    @(negedge clk);
    rst_n = 1;
    send(32'h55D501EF, 8);
    cycle(4'h0, 1'b0);

    // Test 2: search, near misses, and overlapping prefixes.
    test_id = 2;
    reset_dut;
    send(64'h0123456789ABCDEF, 16);
    send(48'h55D455C554D5, 12);
    send(40'h555D51234F, 9);
    cycle(4'hA, 1'b0);

    // Test 3: back-to-back frames and unframed trailing data.
    test_id = 3;
    reset_dut;
    send(64'h55D5012355D5CDEF, 16);
    send(32'h678955D5, 8);
    send(16'hA05F, 4);
    cycle(4'h0, 1'b0);
    cycle(4'hF, 1'b0);

    // Test 4: invalid cycles throughout search and collection.
    test_id = 4;
    reset_dut;
    cycle(4'h5, 1'b1);
    cycle(4'hA, 1'b0);
    cycle(4'h5, 1'b1);
    cycle(4'h0, 1'b0);
    cycle(4'hD, 1'b1);
    cycle(4'h5, 1'b0);
    cycle(4'hF, 1'b0);
    cycle(4'h5, 1'b1);
    for (i = 0; i < 4; i = i + 1) begin
        #1;
        cycle(4'hF, 1'b0);
        cycle(4'h0, 1'b0);
        cycle(i, 1'b1);
    end
    cycle(4'hA, 1'b0);
    cycle(4'h5, 1'b0);
    send(32'h55D589AB, 8);
    cycle(4'h0, 1'b0);

    // Test 5: marker in payload and detection across boundaries.
    test_id = 5;
    reset_dut;
    send(48'h55D555D51234, 12);
    send(32'h55D56789, 8);
    cycle(4'h0, 1'b0);

    test_id = 6;
    reset_dut;
    send(60'h55D512345D5ABCD, 15);
    cycle(4'h0, 1'b0);

    // Test 7: reset discards an incomplete marker.
    test_id = 7;
    reset_dut;
    send(12'h55D, 3);
    reset_dut;
    send(20'h51234, 5);
    send(32'h55D5ABCD, 8);
    cycle(4'h0, 1'b0);

    // Tests 8-12: reset after 0 through 4 collected nibbles.
    for (stage = 0; stage <= 4; stage = stage + 1) begin
        #1;
        test_id = 8 + stage;
        reset_dut;
        send(16'h55D5, 4);
        send(16'h1234, stage);
        reset_dut;
        send(16'h6789, 4);
        send(32'h55D5A0F1, 8);
        cycle(4'h0, 1'b0);
    end

    $display("===========End===========");
    $finish;
end

endmodule

