`timescale 1ns / 1ps
module testbench;

parameter DEPTH = 16;
localparam SETTLE_CYCLES = 32;

// Inputs
reg clk;
reg clk_out;
reg rst_in;
reg [68:0] rcn_in;
reg push;
reg pop;

// Outputs
wire full;
wire [68:0] rcn_out;
wire empty;

integer i;
integer round_id;

rcn_fifo_async #(.DEPTH(DEPTH)) uut (
    .rst_in(rst_in),
    .clk_in(clk),
    .clk_out(clk_out),
    .rcn_in(rcn_in),
    .push(push),
    .full(full),
    .rcn_out(rcn_out),
    .pop(pop),
    .empty(empty)
);

initial clk = 0;
always #5 clk = ~clk;

initial clk_out = 0;
always #7 clk_out = ~clk_out;

task observe;
    input [255:0] label;
    begin
        $display("%0t %0s full=%b empty=%b rcn_out=%h",
                 $time, label, full, empty, rcn_out);
    end
endtask

// 320 ns spans many complete exchanges of the two clock domains.
task settle;
    begin
        repeat (SETTLE_CYCLES) @(posedge clk);
        #1;
        observe("pointer exchange settled");
    end
endtask

task reset_fifo;
    begin
        @(negedge clk);
        push = 0;
        pop = 0;
        #2 rst_in = 1;
        #1;
        observe("asynchronous reset");
        // Wait 100 ns for global reset to finish.
        #100;
        @(negedge clk);
        rst_in = 0;
        settle;
    end
endtask

// Target the uncovered exchange-phase 3 -> 0 reset transition.
// This task drives only ports and uses fixed clock-edge timing.
task reset_from_phase_three;
    begin
        @(negedge clk);
        push = 0;
        pop = 0;
        #2 rst_in = 1;
        #1;
        observe("directed reset preparation");

        // Hold reset across many edges of both clocks so the
        // unreset write-domain phase sampler also samples zero.
        #100;
        @(negedge clk_out);
        rst_in = 0;

        // With the 10 ns write clock and 14 ns read clock:
        // first read edge advances the exchange from 00 to 01;
        // second read edge advances the exchange from 01 to 11.
        repeat (2) @(posedge clk_out);

        // Move beyond the second read edge's NBA updates, then
        // let the write domain sample 11. The following assertion
        // still precedes the next read-clock rising edge.
        #1;
        @(posedge clk);
        #1;
        observe("before phase-three reset");
        rst_in = 1;
        #1;
        observe("phase-three asynchronous reset");

        // Keep reset asserted so the write-domain phase sampler
        // also makes its transition from 11 to 00.
        #100;
        @(negedge clk);
        rst_in = 0;
        settle;
    end
endtask

task write_word;
    input [68:0] word;
    begin
        @(negedge clk);
        rcn_in = word;
        push = 1;
        @(posedge clk);
        #1;
        observe("write");
        @(negedge clk);
        push = 0;
    end
endtask

task read_word;
    begin
        @(negedge clk_out);
        observe("before pop");
        pop = 1;
        @(posedge clk_out);
        #1;
        observe("after pop");
        @(negedge clk_out);
        pop = 0;
    end
endtask

initial begin
    rst_in = 0;
    rcn_in = 0;
    push = 0;
    pop = 0;

    // Test 1: startup reset and idle.
    reset_fifo;
    settle;

    // Test 2: single entries, input MSB exclusion, payload patterns.
    reset_fifo;
    for (i = 0; i < 6; i = i + 1) begin
        case (i)
            0: write_word({1'b0, 68'h00000000000000000});
            1: write_word({1'b1, 68'h00000000000000000});
            2: write_word({1'b0, 68'hfffffffffffffffff});
            3: write_word({1'b1, 68'hfffffffffffffffff});
            4: write_word({1'b0, 68'haaaaaaaaaaaaaaaaa});
            5: write_word({1'b1, 68'h55555555555555555});
        endcase
        settle;
        read_word;
        settle;
        #1;
    end

    // Test 3: capacity, full release, refill, drain, and both wraps.
    reset_fifo;
    for (round_id = 0; round_id < 2; round_id = round_id + 1) begin
        for (i = 0; i < DEPTH - 1; i = i + 1) begin
            write_word(69'h10000000000000000 + round_id * DEPTH + i);
            #1;
        end
        settle;
        observe("filled to usable capacity");
        read_word;
        settle;
        write_word(69'h0f000000000000000 + round_id);
        settle;
        observe("refilled after one pop");
        for (i = 0; i < DEPTH - 1; i = i + 1) begin
            read_word;
            #1;
        end
        settle;
        observe("drained");
        #1;
    end

    // Test 4: interleaved domain activity with one established entry.
    // DEPTH=2 has no spare slot, so its legal transfers are covered above.
    reset_fifo;
    if (DEPTH > 2) begin
        write_word(69'h0123456789abcdef0);
        settle;
        for (i = 0; i < DEPTH; i = i + 1) begin
            write_word(69'h08000000000000000 + i);
            read_word;
            settle;
            #1;
        end
        read_word;
        settle;
    end

    // Test 5: reset with queued data, then reuse the FIFO.
    reset_fifo;
    for (i = 0; i < DEPTH / 2; i = i + 1) begin
        write_word(69'h05555555500000000 + i);
        #1;
    end
    settle;
    observe("queued data before reset");
    reset_fifo;
    observe("reset with retained memory");
    write_word(69'h1abcdef0123456789);
    settle;
    read_word;
    settle;

    // Test 6: directed reset from exchange phase 11 and recovery.
    reset_from_phase_three;
    observe("directed reset recovery");
    write_word({1'b1, 68'hfedcba9876543210f});
    settle;
    read_word;
    settle;

    $display("===========End===========");
    $finish;
end

endmodule

