module testbench;

// Inputs
reg clk;
reg rst;
reg signed [15:0] x_n;
reg signed [15:0] x_n_1;

// Outputs
wire signed [15:0] y_n;

reg signed [15:0] samples [0:8];
integer i, mode;

IIR_Filter uut (
    .clk(clk),
    .rst(rst),
    .x_n(x_n),
    .x_n_1(x_n_1),
    .y_n(y_n)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [191:0] label;
    begin
        $display("%0t %0s mode=%0d index=%0d rst=%b x_n=%0d x_n_1=%0d y_n=%0d (0x%04h)",
                 $time, label, mode, i, rst, x_n, x_n_1, y_n, y_n);
    end
endtask

task reset_dut;
    begin
        @(negedge clk);
        #1 rst = 1;
        #1 observe("asynchronous reset");
        repeat (2) begin
            @(posedge clk);
            #1 observe("reset held");
        end
        @(negedge clk);
        rst = 0;
    end
endtask

task apply_sample;
    input signed [15:0] current_sample;
    input signed [15:0] previous_sample;
    input [191:0] label;
    begin
        @(negedge clk);
        x_n   = current_sample;
        x_n_1 = previous_sample;
        @(posedge clk);
        #1 observe(label);
    end
endtask

task drain_history;
    begin
        repeat (4) begin
            @(negedge clk);
            x_n   = 0;
            x_n_1 = 0;
            @(posedge clk);
            #1 observe("zero-input feedback");
        end
    end
endtask

initial begin
    rst   = 0;
    x_n   = 0;
    x_n_1 = 0;
    i     = 0;
    mode  = 0;

    samples[0] = 16'h0000;
    samples[1] = 16'h0001;
    samples[2] = 16'hffff;
    samples[3] = 16'h0002;
    samples[4] = 16'hfffe;
    samples[5] = 16'h7fff;
    samples[6] = 16'h8000;
    samples[7] = 16'h4000;
    samples[8] = 16'hc000;

    // Wait 100 ns for global reset to finish.
    #100;

    // Reset with active inputs, then observe recovery.
    x_n   = 16'h7fff;
    x_n_1 = 16'h8000;
    reset_dut;
    drain_history;

    // Independent ports, equal pairs, and opposite pairs.
    for (mode = 0; mode < 4; mode = mode + 1) begin
        @(negedge clk);
        for (i = 0; i < 9; i = i + 1) begin
            @(negedge clk);
            x_n   = 0;
            x_n_1 = 0;
            reset_dut;
            case (mode)
                0: apply_sample(samples[i], 16'sd0, "current input only");
                1: apply_sample(16'sd0, samples[i], "prior input only");
                2: apply_sample(samples[i], samples[i], "equal input pair");
                3: apply_sample(samples[i], -samples[i], "opposite input pair");
            endcase
            drain_history;
        end
    end

    // Sustained input and reset after history has accumulated.
    mode  = 4;
    x_n   = 0;
    x_n_1 = 0;
    reset_dut;
    repeat (6) begin
        @(negedge clk);
        x_n   = -16'sd1;
        x_n_1 = 0;
        @(posedge clk);
        #1 observe("sustained input");
    end
    reset_dut;
    drain_history;

    // Consecutive samples with externally supplied input history.
    mode = 5;
    reset_dut;
    for (i = 0; i < 9; i = i + 1) begin
        @(negedge clk);
        x_n_1 = x_n;
        x_n   = samples[i];
        @(posedge clk);
        #1 observe("continuous sequence");
    end
    apply_sample(16'sd0, x_n, "final prior sample");
    drain_history;

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps

module testbench;

reg clk;
reg rst_n;
reg data;

wire match;
wire not_match;

integer position;
integer prefix_length;
integer sequence_number;

localparam [5:0] TARGET = 6'b011100;

RefModule uut (
    .clk      (clk),
    .rst_n    (rst_n),
    .data     (data),
    .match    (match),
    .not_match(not_match)
);

// Independent, continuously running clock.
initial clk = 1'b0;
always #5 clk = ~clk;

// Assert reset between clock edges and hold it across a rising edge.
// Release after the rising edge so the next send task can safely
// establish its first data bit at the following falling edge.
task reset_dut;
begin
    @(negedge clk);
    #2;
    rst_n = 1'b0;
    data  = 1'b0;

    #1;
    $display("t=%0t RESET asserted asynchronously: match=%b not_match=%b",
             $time, match, not_match);

    repeat (1) @(posedge clk);
    #1;
    $display("t=%0t RESET held across clock: match=%b not_match=%b",
             $time, match, not_match);

    rst_n = 1'b1;
    #1;
    $display("t=%0t RESET released: match=%b not_match=%b",
             $time, match, not_match);
end
endtask

// Consume the requested number of MSB-first samples.
// This task supports both complete windows and interrupted prefixes.
task send_prefix;
    input [5:0] seq;
    input integer count;
    integer i;
begin
    for (i = 0; i < count; i = i + 1) begin
        @(negedge clk);
        data = seq[5-i];

        // Observe outputs after data changes but before it is sampled.
        #1;
        $display("t=%0t Before sample %0d: data=%b match=%b not_match=%b",
                 $time, i + 1, data, match, not_match);

        @(posedge clk);
        #1;
        $display("t=%0t After sample %0d: data=%b match=%b not_match=%b",
                 $time, i + 1, data, match, not_match);
    end
end
endtask

task send_sequence;
    input [5:0] seq;
begin
    send_prefix(seq, 6);
    $display("t=%0t Sequence %b complete: match=%b not_match=%b",
             $time, seq, match, not_match);
end
endtask

initial begin
    rst_n = 1'b0;
    data  = 1'b0;

    #1;
    $display("t=%0t Initial reset: match=%b not_match=%b",
             $time, match, not_match);

    // Test Case 1: asynchronous reset and exact target.
    reset_dut;
    send_sequence(TARGET);

    // Test Case 2: retain mismatch at each target position.
    // Generates 111100, 001100, 010100, 011000, 011110, 011101.
    for (position = 0; position < 6; position = position + 1) begin
        #1;
        reset_dut;
        send_sequence(TARGET ^ (6'b100000 >> position));
    end

    // Test Case 3: retain consecutive non-overlapping sequences.
    reset_dut;
    send_sequence(TARGET);
    send_sequence(6'b111100);

    // Test Case 4: retain reset during an in-progress sequence,
    // after the first two target bits.
    reset_dut;
    send_prefix(TARGET, 2);
    reset_dut;
    send_sequence(TARGET);

    // Test Case 5: all terminal restart choices without reset.
    // TARGET -> TARGET:   s6  -> s1
    // TARGET -> 111111:   s6  -> sf1
    // 111111 -> 111111:   sf6 -> sf1
    // 111111 -> TARGET:   sf6 -> s1
    reset_dut;
    send_sequence(TARGET);
    send_sequence(TARGET);
    send_sequence(6'b111111);
    send_sequence(6'b111111);
    send_sequence(TARGET);

    // Consume one further bit to observe the final match clearing.
    send_prefix(TARGET, 1);

    // Test Case 6: reset from every matching progress state and
    // the matching terminal state, followed by target recovery.
    for (prefix_length = 1;
         prefix_length <= 6;
         prefix_length = prefix_length + 1) begin
        #1;
        reset_dut;
        send_prefix(TARGET, prefix_length);
        reset_dut;
        send_sequence(TARGET);
    end

    // Test Case 7: reset from every mismatch progress state and
    // the mismatch terminal state, followed by target recovery.
    for (prefix_length = 1;
         prefix_length <= 6;
         prefix_length = prefix_length + 1) begin
        #1;
        reset_dut;
        send_prefix(6'b111111, prefix_length);
        reset_dut;
        send_sequence(TARGET);
    end

    // Test Case 8: all 64 six-bit values in contiguous windows.
    reset_dut;
    for (sequence_number = 0;
         sequence_number < 64;
         sequence_number = sequence_number + 1) begin
        #1;
        send_sequence(sequence_number[5:0]);
    end

    // Observe restart after the final mismatch, then finish with
    // asynchronous reset from an active terminal indication.
    send_sequence(TARGET);
    reset_dut;

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam DEPTH = 5;
localparam DATA_WIDTH = 32;
localparam ENTRIES = 2**DEPTH;
localparam [DATA_WIDTH-1:0] ONE = 1;

// Inputs
reg clk;
reg WE3;
reg [DEPTH-1:0] A1, A2, A3;
reg [DATA_WIDTH-1:0] WD3;

// Outputs
wire [DATA_WIDTH-1:0] RD1, RD2;

integer i;
integer case_id;

Register_File #(
    .DEPTH(DEPTH),
    .DATA_WIDTH(DATA_WIDTH)
) uut (
    .WE3(WE3),
    .clk(clk),
    .A1(A1),
    .A2(A2),
    .A3(A3),
    .WD3(WD3),
    .RD1(RD1),
    .RD2(RD2)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [8*32-1:0] label;
    begin
        $display("case=%0d %0s t=%0t clk=%b WE3=%b A1=%0d A2=%0d A3=%0d WD3=%h RD1=%h RD2=%h",
                 case_id, label, $time, clk, WE3,
                 A1, A2, A3, WD3, RD1, RD2);
    end
endtask

// Initialize exclusively through the synchronous write port.
task initialize_file;
    integer address;
    begin
        for (address = 0; address < ENTRIES; address = address + 1) begin
            @(negedge clk);
            WE3 = 1;
            A3 = address;
            WD3 = address + 1;
            A1 = address;
            A2 = address;
            @(posedge clk);
            #1;
            observe("initialize/write");
        end
        @(negedge clk);
        WE3 = 0;
    end
endtask

task read_all;
    integer address;
    begin
        for (address = 0; address < ENTRIES; address = address + 1) begin
            @(negedge clk);
            A1 = address;
            A2 = ENTRIES - 1 - address;
            #1;
            observe("readback");
        end
    end
endtask

initial begin
    WE3 = 0;
    A1 = 0;
    A2 = 0;
    A3 = 0;
    WD3 = 0;
    case_id = 0;

    // Startup interval; the DUT has no reset.
    #100;

    // Case 1: consecutive writes and independent asynchronous reads.
    case_id = 1;
    initialize_file;
    read_all;
    for (i = 0; i < ENTRIES; i = i + 1) begin
        @(negedge clk);
        A1 = i;
        #1;
        observe("change A1 only");
        A2 = ENTRIES - 1 - i;
        #1;
        observe("change A2 only");
        A2 = A1;
        #1;
        observe("same-address reads");
    end

    // Case 2: disabled writes and complete retention readback.
    case_id = 2;
    initialize_file;
    for (i = 0; i < ENTRIES; i = i + 1) begin
        @(negedge clk);
        WE3 = 0;
        A3 = i;
        WD3 = ~(i + ONE);
        A1 = i;
        A2 = i;
        @(posedge clk);
        #1;
        observe("disabled write");
    end
    read_all;

    // Case 3: overwrite, data patterns, and read/write collisions.
    case_id = 3;
    initialize_file;
    for (i = 0; i < 2*DATA_WIDTH + 2; i = i + 1) begin
        @(negedge clk);
        WE3 = 1;
        A3 = i % ENTRIES;
        A1 = A3;
        A2 = (i + 1) % ENTRIES;
        if (i == 0)
            WD3 = {DATA_WIDTH{1'b0}};
        else if (i == 1)
            WD3 = {DATA_WIDTH{1'b1}};
        else if (i < DATA_WIDTH + 2)
            WD3 = ONE << (i - 2);
        else
            WD3 = ~(ONE << (i - DATA_WIDTH - 2));
        #1;
        observe("before rising edge");
        @(posedge clk);
        #1;
        observe("written/unselected entries");
        A2 = A3;
        #1;
        observe("both ports after write");
    end
    @(negedge clk);
    WE3 = 0;
    read_all;

    // Case 4: enable pulse spans only a falling edge.
    case_id = 4;
    initialize_file;
    for (i = 0; i < 2; i = i + 1) begin
        @(posedge clk);
        #1;
        A3 = i * (ENTRIES - 1);
        A1 = A3;
        A2 = A3;
        WD3 = {DATA_WIDTH{1'b1}};
        WE3 = 1;
        #1;
        observe("enable between rising edges");
        @(negedge clk);
        #1;
        observe("after falling edge");
        WD3 = {DATA_WIDTH{1'b0}};
        #1;
        observe("data change while enabled");
        WE3 = 0;
        @(posedge clk);
        #1;
        observe("after disabled rising edge");
    end
    read_all;

    $display("===========End===========");
    $finish;
end

endmodule

