module testbench;

// Inputs
reg clk;
reg [7:0] data;
reg ena;
reg rst;

// Outputs
wire [15:0] opc_iraddr;

// Instantiate the Unit Under Test (UUT)
register uut (
    .opc_iraddr(opc_iraddr),
    .data(data),
    .ena(ena),
    .clk1(clk),
    .rst(rst)
);

// clk toggle generate
initial clk = 0;
always #5 clk = ~clk;

task transfer;
    input integer test_id;
    input reset_value;
    input enable_value;
    input [7:0] byte_value;
    begin
        @(negedge clk);
        rst = reset_value;
        ena = enable_value;
        data = byte_value;
        #1;
        $display("case=%0d before-edge t=%0t rst=%b ena=%b data=%h opc_iraddr=%h",
                 test_id, $time, rst, ena, data, opc_iraddr);
        @(posedge clk);
        #1;
        $display("case=%0d after-edge  t=%0t rst=%b ena=%b data=%h opc_iraddr=%h",
                 test_id, $time, rst, ena, data, opc_iraddr);
    end
endtask

initial begin
    // Initialize inputs; intentionally exercise the uninitialized boundary.
    data = 8'hA5;
    ena = 1'b1;
    rst = 1'b0;

    // Wait 100 ns before the remaining stimulus.
    #100;
    $display("case=1 startup t=%0t rst=%b ena=%b data=%h opc_iraddr=%h",
             $time, rst, ena, data, opc_iraddr);

    // Case 1: recover the uninitialized phase through top-level inputs.
    transfer(1, 0, 0, 8'h00);
    transfer(1, 0, 1, 8'hA5);
    transfer(1, 0, 1, 8'h5A);

    // Case 2: reset and uninterrupted byte alternation.
    transfer(2, 1, 0, 8'hFF);
    transfer(2, 0, 1, 8'h00);
    transfer(2, 0, 1, 8'hFF);
    transfer(2, 0, 1, 8'hFF);
    transfer(2, 0, 1, 8'h00);
    transfer(2, 0, 1, 8'hAA);
    transfer(2, 0, 1, 8'h55);

    // Case 3: disabled hold and restart from either transfer phase.
    transfer(3, 1, 0, 8'h00);
    transfer(3, 0, 0, 8'hFF);
    transfer(3, 0, 1, 8'h12);
    transfer(3, 0, 1, 8'h34);
    transfer(3, 0, 1, 8'h56);
    transfer(3, 0, 0, 8'hFF);
    transfer(3, 0, 0, 8'h00);
    transfer(3, 0, 1, 8'h78);
    transfer(3, 0, 1, 8'h9A);
    transfer(3, 0, 0, 8'h11);
    transfer(3, 0, 1, 8'hBC);
    transfer(3, 0, 1, 8'hDE);

    // Case 4: reset partial/full addresses, priority, and held reset.
    transfer(4, 1, 0, 8'h00);
    transfer(4, 0, 1, 8'hAB);
    transfer(4, 1, 1, 8'hFF);
    transfer(4, 1, 1, 8'h55);
    transfer(4, 0, 1, 8'h12);
    transfer(4, 0, 1, 8'h34);
    transfer(4, 1, 0, 8'hAA);
    transfer(4, 0, 1, 8'h56);
    transfer(4, 0, 1, 8'h78);

    $display("===========End===========");
    $finish;
end

endmodule

