module testbench;

reg clk;
reg aresetn;
reg [31:0] cfg_data;
reg [31:0] s_axis_tdata;
reg s_axis_tvalid;
reg m_axis_tready;

wire s_axis_tready;
wire [31:0] m_axis_tdata;
wire m_axis_tvalid;

axis_interpolator uut (
    .aclk          (clk),
    .aresetn       (aresetn),
    .cfg_data      (cfg_data),
    .s_axis_tdata  (s_axis_tdata),
    .s_axis_tvalid (s_axis_tvalid),
    .m_axis_tready (m_axis_tready),
    .s_axis_tready (s_axis_tready),
    .m_axis_tdata  (m_axis_tdata),
    .m_axis_tvalid (m_axis_tvalid)
);

initial clk = 1'b0;
always #5 clk = ~clk;

task reset_dut;
begin
    aresetn       = 1'b0;
    cfg_data      = 32'd0;
    s_axis_tdata  = 32'd0;
    s_axis_tvalid = 1'b0;
    m_axis_tready = 1'b0;
    repeat (2) @(posedge clk);
    $display("RESET: s_axis_tready=%b m_axis_tvalid=%b m_axis_tdata=%h",
             s_axis_tready, m_axis_tvalid, m_axis_tdata);
    aresetn = 1'b1;
    repeat (1) @(posedge clk);
end
endtask

initial begin
    aresetn       = 1'b0;
    cfg_data      = 32'd0;
    s_axis_tdata  = 32'd0;
    s_axis_tvalid = 1'b0;
    m_axis_tready = 1'b0;

    // Capture input and remove registered ready indication.
    reset_dut;
    cfg_data      = 32'd2;
    s_axis_tdata  = 32'h0000_00A1;
    s_axis_tvalid = 1'b1;
    repeat (1) @(posedge clk);
    $display("CAPTURE: s_axis_tready=%b m_axis_tvalid=%b m_axis_tdata=%h",
             s_axis_tready, m_axis_tvalid, m_axis_tdata);
    repeat (1) @(posedge clk);
    $display("READY_CLEAR: s_axis_tready=%b m_axis_tvalid=%b m_axis_tdata=%h",
             s_axis_tready, m_axis_tvalid, m_axis_tdata);

    // Hold output while downstream is not ready.
    reset_dut;
    cfg_data      = 32'd1;
    s_axis_tdata  = 32'h0000_00B2;
    s_axis_tvalid = 1'b1;
    repeat (1) @(posedge clk);
    s_axis_tvalid = 1'b0;
    repeat (2) @(posedge clk);
    $display("OUTPUT_HOLD: s_axis_tready=%b m_axis_tvalid=%b m_axis_tdata=%h",
             s_axis_tready, m_axis_tvalid, m_axis_tdata);

    // Transfers below threshold followed by valid-word replacement.
    reset_dut;
    cfg_data      = 32'd2;
    s_axis_tdata  = 32'h1111_1111;
    s_axis_tvalid = 1'b1;
    repeat (1) @(posedge clk);
    s_axis_tdata  = 32'h2222_2222;
    s_axis_tvalid = 1'b1;
    m_axis_tready = 1'b1;
    repeat (1) @(posedge clk);
    $display("TRANSFER_COUNT_1: s_axis_tready=%b m_axis_tvalid=%b m_axis_tdata=%h",
             s_axis_tready, m_axis_tvalid, m_axis_tdata);
    repeat (1) @(posedge clk);
    $display("TRANSFER_COUNT_2: s_axis_tready=%b m_axis_tvalid=%b m_axis_tdata=%h",
             s_axis_tready, m_axis_tvalid, m_axis_tdata);
    repeat (1) @(posedge clk);
