    s_axis_tvalid = 1'b1;
    repeat (1) @(posedge clk);
    s_axis_tdata  = 32'h4444_4444;
    s_axis_tvalid = 1'b1;
    m_axis_tready = 1'b1;
    repeat (1) @(posedge clk);
    $display("ZERO_THRESHOLD_VALID: s_axis_tready=%b m_axis_tvalid=%b m_axis_tdata=%h",
             s_axis_tready, m_axis_tvalid, m_axis_tdata);

    s_axis_tdata  = 32'h5555_5555;
    s_axis_tvalid = 1'b1;
    m_axis_tready = 1'b0;
    repeat (1) @(posedge clk);
    $display("VALID_OUTPUT_NO_TRANSFER: s_axis_tready=%b m_axis_tvalid=%b m_axis_tdata=%h",
             s_axis_tready, m_axis_tvalid, m_axis_tdata);

    s_axis_tvalid = 1'b0;
