`timescale 1ns / 1ps
module testbench;

// Inputs
reg clk;
reg rst_n;
reg req_compl_i;
reg compl_done_i;
reg cfg_to_turnoff;

// Outputs
wire cfg_turnoff_ok;

integer test_id;
integer combination;
integer cycle;

PIO_TO_CTRL uut (
    .clk(clk),
    .rst_n(rst_n),
    .req_compl_i(req_compl_i),
    .compl_done_i(compl_done_i),
    .cfg_to_turnoff(cfg_to_turnoff),
    .cfg_turnoff_ok(cfg_turnoff_ok)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [159:0] phase;
    begin
        $display("t=%0t case=%0d phase=%0s rst_n=%b req=%b done=%b turnoff=%b cfg_turnoff_ok=%b",
                 $time, test_id, phase, rst_n, req_compl_i,
                 compl_done_i, cfg_to_turnoff, cfg_turnoff_ok);
    end
endtask

task reset_dut;
    begin
        @(negedge clk);
        req_compl_i = 0;
        compl_done_i = 0;
        cfg_to_turnoff = 0;
        #2 rst_n = 0;
        #1 observe("async reset");
        repeat (2) @(posedge clk);
        #1 observe("reset held");
        @(negedge clk);
        rst_n = 1;
    end
endtask

task drive_cycle;
    input request_value;
    input done_value;
    input turnoff_value;
    begin
        @(negedge clk);
        req_compl_i = request_value;
        compl_done_i = done_value;
        cfg_to_turnoff = turnoff_value;
        #1 observe("before rising edge");
        @(posedge clk);
        #1 observe("after rising edge");
    end
endtask

initial begin
    rst_n = 0;
    req_compl_i = 0;
    compl_done_i = 0;
    cfg_to_turnoff = 0;
    test_id = 0;

    // Wait 100 ns for global reset to finish.
    #100;
    observe("startup reset");

    // Cases 1-16: all inputs from idle and pending states.
    // combination[3] selects the setup request; [2:0] are req/done/turnoff.
    for (combination = 0; combination < 16;
         combination = combination + 1) begin
        @(negedge clk);
        test_id = combination + 1;
        reset_dut;
        drive_cycle(combination[3], 1'b0, 1'b0);
        drive_cycle(combination[2], combination[1], combination[0]);
        drive_cycle(1'b0, 1'b0, 1'b1);
    end

    // Case 17: reset while approval is asserted.
    test_id = 17;
    reset_dut;
    drive_cycle(1'b0, 1'b0, 1'b1);
    reset_dut;
    drive_cycle(1'b0, 1'b0, 1'b1);
    drive_cycle(1'b0, 1'b0, 1'b0);

    // Case 18: reset with an outstanding request.
    test_id = 18;
    reset_dut;
    drive_cycle(1'b1, 1'b0, 1'b1);
    drive_cycle(1'b0, 1'b0, 1'b1);
    reset_dut;
    drive_cycle(1'b0, 1'b0, 1'b1);

    // Case 19: sustained simultaneous request and completion.
    test_id = 19;
    reset_dut;
    for (cycle = 0; cycle < 4; cycle = cycle + 1) begin
        @(negedge clk);
        req_compl_i = 1;
        compl_done_i = 1;
        cfg_to_turnoff = 1;
        @(posedge clk);
        #1 observe("sustained controls");
    end
    drive_cycle(1'b0, 1'b0, 1'b1);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam SUBNORMAL_CYCLES = 23 + 3;

// Inputs
reg clk;
reg rst;
reg [31:0] input_a;
reg input_a_stb;
reg output_z_ack;

// Outputs
wire [63:0] output_z;
wire output_z_stb;
wire input_a_ack;

integer i, sign_index, phase;

float_to_double uut (
    .input_a(input_a),
    .input_a_stb(input_a_stb),
    .output_z_ack(output_z_ack),
    .clk(clk),
    .rst(rst),
    .output_z(output_z),
    .output_z_stb(output_z_stb),
    .input_a_ack(input_a_ack)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [255:0] label;
    begin
        $display("%0t %0s rst=%b a=%h a_stb=%b z_ack=%b z=%h z_stb=%b a_ack=%b",
                 $time, label, rst, input_a, input_a_stb,
                 output_z_ack, output_z, output_z_stb, input_a_ack);
    end
endtask

task advance;
    input integer cycles;
    input [255:0] label;
    begin
        repeat (cycles) @(posedge clk);
        #1;
        observe(label);
    end
endtask

task reset_dut;
    begin
        @(negedge clk);
        rst = 1;
        input_a = 0;
        input_a_stb = 0;
        output_z_ack = 0;
        advance(1, "reset asserted");
        @(negedge clk);
        rst = 0;
        advance(1, "reset released / ready");
    end
endtask

task launch;
    input [31:0] value;
    begin
        @(negedge clk);
        input_a = value;
        input_a_stb = 1;
        advance(1, "input acceptance");
        @(negedge clk);
        input_a_stb = 0;
    end
endtask

task acknowledge;
    begin
        @(negedge clk);
        output_z_ack = 1;
        advance(1, "output acknowledged");
        @(negedge clk);
        output_z_ack = 0;
        advance(1, "input readiness restored");
    end
endtask

task conversion;
    input [31:0] value;
    input integer cycles;
    begin
        reset_dut;
        launch(value);
        advance(cycles, "conversion result");
        advance(2, "output held");
        acknowledge;
    end
endtask

function [31:0] direct_vector;
    input integer index;
    begin
        case (index)
             0: direct_vector = 32'h00000000; // Zero
             1: direct_vector = 32'h00800000; // Minimum normal
             2: direct_vector = 32'h00800001;
             3: direct_vector = 32'h00ffffff;
             4: direct_vector = 32'h3f000000;
             5: direct_vector = 32'h3f7fffff;
             6: direct_vector = 32'h3f800000;
             7: direct_vector = 32'h3f800001;
             8: direct_vector = 32'h3faaaaaa;
             9: direct_vector = 32'h40555555;
            10: direct_vector = 32'h7f000000;
            11: direct_vector = 32'h7f7fffff; // Maximum finite
            12: direct_vector = 32'h7f800000; // Infinity
            13: direct_vector = 32'h7f800001; // Signaling NaN
            14: direct_vector = 32'h7fbfffff;
            15: direct_vector = 32'h7fc00000; // Quiet NaN
            16: direct_vector = 32'h7fc12345;
            17: direct_vector = 32'h7fffffff;
            default: direct_vector = 32'h00000000;
        endcase
    end
endfunction

initial begin
    // Initialize inputs and allow 100 ns for startup reset.
    rst = 1;
    input_a = 0;
    input_a_stb = 0;
    output_z_ack = 0;
    #100;
    observe("startup reset");

    // Idle operation: input changes and output ack without requests.
    reset_dut;
    @(negedge clk);
    input_a = 32'h3f800000;
    output_z_ack = 1;
    advance(3, "idle without input strobe");
    reset_dut;

    // Direct conversions, with both signs.
    for (sign_index = 0; sign_index < 2; sign_index = sign_index + 1) begin
        #1;
        for (i = 0; i < 18; i = i + 1) begin
            #1;
            conversion(direct_vector(i) |
                       (sign_index << 31), 2);
        end
    end

    // Every subnormal leading-one position, with both signs.
    for (sign_index = 0; sign_index < 2; sign_index = sign_index + 1) begin
        #1;
        for (i = 0; i < 23; i = i + 1) begin
            #1;
            conversion((32'h00000001 << i) |
                       (sign_index << 31), SUBNORMAL_CYCLES);
        end
        conversion(32'h00000003 | (sign_index << 31),
                   SUBNORMAL_CYCLES);
        conversion(32'h00555555 | (sign_index << 31),
                   SUBNORMAL_CYCLES);
        conversion(32'h007fffff | (sign_index << 31),
                   SUBNORMAL_CYCLES);
    end

    // Busy input request, output backpressure, then consecutive transfer.
    reset_dut;
    launch(32'h3f800001);
    input_a = 32'hc0200000;
    input_a_stb = 1;
    advance(1, "normal conversion first edge");
    advance(1, "normal conversion second edge");
    advance(4, "busy request / output held");
    @(negedge clk);
    output_z_ack = 1;
    advance(1, "first output acknowledged");
    @(negedge clk);
    output_z_ack = 0;
    advance(1, "held request / ready");
    advance(1, "held request accepted");
    @(negedge clk);
    input_a_stb = 0;
    advance(2, "second conversion result");
    acknowledge;

    // Ack already high: observe every edge through two transfers.
    reset_dut;
    @(negedge clk);
    input_a = 32'h40400000;
    input_a_stb = 1;
    output_z_ack = 1;
    for (i = 0; i < 10; i = i + 1) begin
        @(posedge clk);
        #1;
        observe("continuous request / early ack");
    end
    @(negedge clk);
    input_a_stb = 0;
    output_z_ack = 0;
    advance(2, "continuous requests stopped");

    // Preserve the original four interruption cases and add a reset
    // asserted early enough to target convert_0 -> get_a.
    for (phase = 0; phase < 5; phase = phase + 1) begin
        #1;
        reset_dut;
        case (phase)
            0: begin
                launch(32'h3f800000);
            end
            1: begin
                launch(32'hbf800000);
                advance(1, "reset before output presentation");
            end
            2: begin
                launch(32'h00000001);
                advance(8, "reset during normalization");
            end
            3: begin
                launch(32'h807fffff);
                advance(SUBNORMAL_CYCLES, "reset during held output");
            end
            4: begin
                launch(32'h3f800000);

                // launch returns at the falling edge immediately after
                // input acceptance. Assert reset here so that the next
                // rising edge resets the controller from convert_0.
                // An additional falling-edge wait would miss that state.
                rst = 1;
                advance(1, "reset at primary conversion");
            end
        endcase

        // In phase 4 this extends the already asserted reset.
        // All phases then exercise the same release and recovery sequence.
        reset_dut;
        advance(SUBNORMAL_CYCLES, "idle after interrupted operation");
        launch(32'h41200000);
        advance(2, "fresh conversion after reset");
        acknowledge;
    end

    $display("===========End===========");
    $finish;
end

endmodule

