    drive_and_show(8, 2'b10, 6'b100101);
    drive_and_show(9, 2'b10, 6'b101010);

    // Test unsupported fully known combinations and output retention.
    drive_and_show(10, 2'b10, 6'b101010);
    drive_and_show(11, 2'b10, 6'b100001);
    drive_and_show(12, 2'b11, 6'b000000);

