`timescale 1ns / 1ps
module testbench;

localparam integer DEBOUNCE = 1000000;

// Inputs
reg clk;
reg Rst_n;
reg key_in;

// Outputs
wire key_flag;
wire key_state;

integer test_id;
integer direction;
integer offset;
integer phase;
integer width;

keyscan uut (
    .Clk(clk),
    .Rst_n(Rst_n),
    .key_in(key_in),
    .key_flag(key_flag),
    .key_state(key_state)
);

initial clk = 0; //clk is initialized as 0
always #5 clk = ~clk;

task show_outputs;
begin
    $display("test=%0d time=%0t rst_n=%b key_in=%b key_flag=%b key_state=%b",
             test_id, $time, Rst_n, key_in, key_flag, key_state);
end
endtask

task sample_cycles;
    input integer count;
    integer i;
begin
    for (i = 0; i < count; i = i + 1) begin
        @(posedge clk);
        #1;
        show_outputs;
    end
end
endtask

task observe_later;
    input integer count;
begin
    repeat (count) @(posedge clk);
    #1;
    show_outputs;
end
endtask

task drive_key;
    input level;
begin
    @(negedge clk);
    key_in = level;
end
endtask

task reset_dut;
    input startup_level;
begin
    #2;
    Rst_n = 0;
    key_in = startup_level;
    #1;
    show_outputs;
    repeat (2) @(posedge clk);
    @(negedge clk);
    Rst_n = 1;
    sample_cycles(8);
end
endtask

// Sample every clock across the completion and pulse-clear window.
task valid_transition;
    input level;
begin
    drive_key(level);
    repeat (DEBOUNCE - 8) @(posedge clk);
    sample_cycles(18);
end
endtask

task short_bounce;
    input candidate_level;
    input integer duration;
begin
    drive_key(candidate_level);
    repeat (duration) @(posedge clk);
    drive_key(~candidate_level);
    sample_cycles(8);
end
endtask

// Reverse after DEBOUNCE, DEBOUNCE+1, or DEBOUNCE+2 clocks.
// The middle timing aligns the synchronized bounce with completion.
task boundary_transition;
    input candidate_level;
    input integer timing_offset;
begin
    drive_key(candidate_level);
    repeat (DEBOUNCE - 8) @(posedge clk);
    sample_cycles(8 + timing_offset);
    drive_key(~candidate_level);
    sample_cycles(12);
    observe_later(DEBOUNCE + 12);
end
endtask

initial begin
    // Initialize Inputs
    Rst_n = 0;
    key_in = 1;
    test_id = 0;

    // Wait 100 ns for global reset to finish
    #100;
    show_outputs;

    // Released startup; press, held press, release, held release, repress.
    test_id = 1;
    reset_dut(1);
    observe_later(DEBOUNCE + 12);
    valid_transition(0);
    observe_later(DEBOUNCE + 12);
    valid_transition(1);
    observe_later(DEBOUNCE + 12);
    valid_transition(0);

    // Low startup, followed by a fresh falling edge.
    test_id = 2;
    reset_dut(0);
    observe_later(DEBOUNCE + 12);
    drive_key(1);
    sample_cycles(8);
    valid_transition(0);
    valid_transition(1);

    // Short candidate presses and releases, each followed by recovery.
    for (direction = 0; direction < 2; direction = direction + 1) begin
        for (width = 1; width <= 8; width = width + 7) begin
            #1;
            test_id = 10 + direction * 10 + width;
            reset_dut(1);
            case (direction)
                1: valid_transition(0);
            endcase
            short_bounce(direction, width);
            observe_later(DEBOUNCE + 12);
            valid_transition(direction);
            valid_transition(!direction);
        end
    end

    // Adjacent boundary timings for press and release.
    for (direction = 0; direction < 2; direction = direction + 1) begin
        for (offset = 0; offset < 3; offset = offset + 1) begin
            #1;
            test_id = 30 + direction * 3 + offset;
            reset_dut(1);
            case (direction)
                1: valid_transition(0);
            endcase
            boundary_transition(direction, offset);
        end
    end

    // Reset in idle, FILTER0, DOWN, FILTER1, and the press pulse.
    for (phase = 0; phase < 5; phase = phase + 1) begin
        #1;
        test_id = 40 + phase;
        reset_dut(1);
        case (phase)
            0: sample_cycles(2);
            1: begin
                drive_key(0);
                sample_cycles(16);
            end
            2: valid_transition(0);
            3: begin
                valid_transition(0);
                drive_key(1);
                sample_cycles(16);
            end
            4: begin
                drive_key(0);
                repeat (DEBOUNCE + 4) @(posedge clk);
                sample_cycles(1);
            end
        endcase
        reset_dut(1);
        valid_transition(0);
        valid_transition(1);
    end

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

// Inputs
reg clk;
reg reset;
reg wait_for_incoming_data;
reg start_receiving_data;
reg ps2_clk_posedge;
reg ps2_clk_negedge;
reg ps2_data;

// Outputs
wire [7:0] received_data;
wire received_data_en;

integer test_id;
integer sample_id;
integer pattern;
integer mode;
integer phase;
reg [7:0] payload;

PS2_Mouse_Data_In uut (
    .clk(clk),
    .reset(reset),
    .wait_for_incoming_data(wait_for_incoming_data),
    .start_receiving_data(start_receiving_data),
    .ps2_clk_posedge(ps2_clk_posedge),
    .ps2_clk_negedge(ps2_clk_negedge),
    .ps2_data(ps2_data),
    .received_data(received_data),
    .received_data_en(received_data_en)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    begin
        $display("test=%0d sample=%0d time=%0t reset=%b wait=%b start=%b pos=%b neg=%b serial=%b received_data=%02h received_data_en=%b",
                 test_id, sample_id, $time, reset,
                 wait_for_incoming_data, start_receiving_data,
                 ps2_clk_posedge, ps2_clk_negedge, ps2_data,
                 received_data, received_data_en);
        sample_id = sample_id + 1;
    end
endtask

task cycle;
    input r, w, s, p, n, d;
    begin
        @(negedge clk);
        reset = r;
        wait_for_incoming_data = w;
        start_receiving_data = s;
        ps2_clk_posedge = p;
        ps2_clk_negedge = n;
        ps2_data = d;
        @(posedge clk);
        #1;
        observe;
    end
endtask

task reset_receiver;
    begin
        @(negedge clk);
        reset = 1;
        wait_for_incoming_data = 1;
        start_receiving_data = 1;
        ps2_clk_posedge = 1;
        ps2_clk_negedge = 1;
        ps2_data = 0;
        #1;
        observe; // Before the synchronous reset edge.
        @(posedge clk);
        #1;
        observe;
        cycle(0, 0, 0, 0, 0, 1);
    end
endtask

task begin_direct;
    begin
        cycle(0, 0, 1, 0, 0, 1);
    end
endtask

task send_bits;
    input [7:0] value;
    input integer count;
    integer bit_index;
    begin
        for (bit_index = 0; bit_index < count; bit_index = bit_index + 1) begin
            #1;
            cycle(0, 1, 1, 0, 1, ~value[bit_index]);
            cycle(0, 0, 0, 1, 0, value[bit_index]);
        end
    end
endtask

task end_frame;
    input parity_value;
    input stop_value;
    begin
        cycle(0, 1, 1, 0, 1, ~parity_value);
        cycle(0, 0, 0, 1, 1, parity_value);
        cycle(0, 1, 1, 0, 1, ~stop_value);
        cycle(0, 0, 0, 0, 0, stop_value);
        cycle(0, 0, 0, 1, 0, stop_value);
    end
endtask

initial begin
    reset = 1;
    wait_for_incoming_data = 0;
    start_receiving_data = 0;
    ps2_clk_posedge = 0;
    ps2_clk_negedge = 0;
    ps2_data = 1;
    test_id = 0;
    sample_id = 0;

    // Wait 100 ns for global reset to finish.
    #100;
    observe;

    // 1: Idle activity, wait priority, cancellation, and direct recovery.
    test_id = 1;
    reset_receiver;
    cycle(0, 0, 0, 1, 0, 0);
    cycle(0, 0, 0, 0, 1, 1);
    cycle(0, 1, 1, 0, 0, 1);
    cycle(0, 1, 1, 1, 0, 1);
    cycle(0, 1, 1, 0, 0, 0);
    cycle(0, 1, 1, 0, 1, 0);
    cycle(0, 0, 0, 0, 0, 0);
    cycle(0, 0, 0, 1, 0, 0);
    begin_direct;
    send_bits(8'h96, 8);
    end_frame(1, 1);
    cycle(0, 0, 0, 0, 0, 1);
    cycle(0, 0, 0, 1, 1, 0);
    cycle(0, 0, 0, 0, 0, 1);

    // 2-3: Detected start, with wait withdrawn or retained at that edge.
    for (mode = 0; mode < 2; mode = mode + 1) begin
        #1;
        test_id = 2 + mode;
        reset_receiver;
        cycle(0, 1, 1, 0, 0, 1);
        cycle(0, 1, 1, 1, 0, 1);
        cycle(0, 1, 1, 0, 1, 0);
        cycle(0, mode[0], 1, 1, 0, 0);
        send_bits(8'h69, 8);
        end_frame(0, 1);
        cycle(0, 0, 0, 0, 0, 1);
    end

    // 4-7: Data patterns and all parity/stop value combinations.
    for (pattern = 0; pattern < 4; pattern = pattern + 1) begin
        #1;
        test_id = 4 + pattern;
        case (pattern)
            0: payload = 8'h00;
            1: payload = 8'hFF;
            2: payload = 8'h96;
            3: payload = 8'h3D;
        endcase
        reset_receiver;
        begin_direct;
        send_bits(payload, 8);
        end_frame(pattern[1], pattern[0]);
        cycle(0, 0, 0, 0, 0, 1);
        cycle(0, 0, 0, 0, 1, 0);
    end

    // 8: Hold direct request through completion and restart without reset.
    test_id = 8;
    reset_receiver;
    begin_direct;
    send_bits(8'hC7, 8);
    cycle(0, 0, 0, 0, 0, 1);
    cycle(0, 0, 0, 1, 0, 1); // Parity.
    cycle(0, 0, 1, 0, 0, 1);
    cycle(0, 0, 1, 1, 0, 1); // Stop.
    cycle(0, 0, 1, 0, 0, 1); // Request during active completion pulse.
    cycle(0, 0, 1, 1, 0, 0); // Direct entry with coincident edge.
    send_bits(8'h28, 8);
    end_frame(1, 1);
    cycle(0, 0, 0, 0, 0, 1);

    // 9-14: Reset from each reception phase, then receive a fresh byte.
    for (phase = 0; phase < 6; phase = phase + 1) begin
        #1;
        test_id = 9 + phase;
        reset_receiver;
        case (phase)
            0: cycle(0, 0, 0, 0, 1, 0);
            1: cycle(0, 1, 0, 0, 0, 1);
            default: begin
                begin_direct;
                case (phase)
                    2: send_bits(8'hD6, 3);
                    default: send_bits(8'hD6, 8);
                endcase
                case (phase)
                    4, 5: begin
                        cycle(0, 0, 0, 0, 0, 1);
                        cycle(0, 0, 0, 1, 0, 1);
                        cycle(0, 0, 0, 0, 0, 1);
                        case (phase)
                            5: cycle(0, 0, 0, 1, 0, 1);
                            default: begin end
                        endcase
                    end
                    default: begin end
                endcase
            end
        endcase
        reset_receiver;
        begin_direct;
        send_bits(8'h29, 8);
        end_frame(0, 1);
        cycle(0, 0, 0, 0, 0, 1);
    end

    $display("===========End=========== received_data=%02h received_data_en=%b",
             received_data, received_data_en);
    $finish;
end

endmodule

