`timescale 1ns / 1ps
module testbench;

// Timer order: soak_low, soak_high, wash_low, wash_high, spin, rinse, drain.
localparam [6:0] T_SL = 7'b1000000,
                 T_SH = 7'b0100000,
                 T_WL = 7'b0010000,
                 T_WH = 7'b0001000,
                 T_D  = 7'b0000001,
                 T_DR = 7'b0000011,
                 T_DS = 7'b0000101;

// Inputs
reg clk;
reg rst, start, select, stop;
reg [6:0] timers;

// Outputs
wire idle, soak_low, soak_high, wash_low, wash_high;
wire rinse, spin, drain;

integer path, phase, bit_index, mode;

// Instantiate the Unit Under Test (UUT)
washing_machine uut (
    .clk(clk), .rst(rst), .start(start), .select(select), .stop(stop),
    .timer_soak_low(timers[6]), .timer_soak_high(timers[5]),
    .timer_wash_low(timers[4]), .timer_wash_high(timers[3]),
    .timer_spin(timers[2]), .timer_rinse(timers[1]),
    .timer_drain(timers[0]),
    .idle(idle), .soak_low(soak_low), .soak_high(soak_high),
    .wash_low(wash_low), .wash_high(wash_high),
    .rinse(rinse), .spin(spin), .drain(drain)
);

// clk toggle generate
initial clk = 0;
always #5 clk = ~clk;

// Stimulus patterns only; phase 0..5 denotes idle through spin.
function [6:0] transition_timers;
    input integer p;
    input integer s;
    begin
        case (s)
            0: transition_timers = p ? T_SH : T_SL;
            1: transition_timers = p ? T_WH : T_WL;
            2: transition_timers = T_D;
            3: transition_timers = T_DR;
            4: transition_timers = T_DS;
            5: transition_timers = 7'b0;
            default: transition_timers = 7'b0;
        endcase
    end
endfunction

task observe;
    input [8*48-1:0] label;
    begin
        $display(
            "%0t %0s path=%0d phase=%0d bit=%0d mode=%0d rst=%b start=%b select=%b stop=%b timers=%b idle=%b soak_low=%b soak_high=%b wash_low=%b wash_high=%b rinse=%b spin=%b drain=%b",
            $time, label, path, phase, bit_index, mode,
            rst, start, select, stop, timers,
            idle, soak_low, soak_high, wash_low, wash_high,
            rinse, spin, drain
        );
    end
endtask

task reset_clean;
    begin
        @(negedge clk);
        rst = 1;
        start = 0;
        select = 0;
        stop = 0;
        timers = 0;
        @(posedge clk);
        #1;
        observe("initialize: reset clock");
        @(negedge clk);
        rst = 0;
        #1;
        observe("initialize: reset release");
    end
endtask

// Toggle start to ensure select is evaluated with a sensitive input event.
task apply_step;
    input [8*48-1:0] label;
    input req_start, req_select, req_stop;
    input [6:0] req_timers;
    begin
        @(negedge clk);
        start = 0;
        select = req_select;
        stop = req_stop;
        timers = req_timers;
        #1;
        start = req_start;
        #1;
        observe(label);
        @(posedge clk);
        #1;
        observe("after state-update clock");
    end
endtask

task reach_phase;
    input integer p;
    input integer target;
    integer step;
    begin
        reset_clean;
        for (step = 0; step < target; step = step + 1) begin
            #1;
            apply_step("setup: legal progression",
                       1'b1, p, 1'b0, transition_timers(p, step));
        end
    end
endtask

initial begin
    // Initialize Inputs
    rst = 1;
    start = 0;
    select = 0;
    stop = 0;
    timers = 0;
    path = 0;
    phase = 0;
    bit_index = -1;
    mode = 0;

    // Wait 100 ns for global reset to finish
    #100;
    observe("startup");

    // Exact qualification, holds, and both complete normal sequences.
    for (path = 0; path < 2; path = path + 1) begin
        #1;
        reset_clean;
        for (phase = 0; phase < 6; phase = phase + 1) begin
            #1;
            apply_step("hold: start inactive",
                       1'b0, path, 1'b0, transition_timers(path, phase));
            for (bit_index = 0; bit_index < 7;
                 bit_index = bit_index + 1) begin
                #1;
                apply_step("hold: one timer bit inverted",
                           1'b1, path, 1'b0,
                           transition_timers(path, phase) ^
                           (7'b0000001 << bit_index));
            end
            bit_index = -1;
            if (phase < 3)
                apply_step("hold: opposite selection",
                           1'b1, !path, 1'b0,
                           transition_timers(path, phase));
            apply_step("normal forward transition",
                       1'b1, path, 1'b0, transition_timers(path, phase));
        end
    end

    // Shared phases also advance with selection opposite the entry path.
    for (path = 0; path < 2; path = path + 1) begin
        #1;
        reach_phase(path, 3);
        for (phase = 3; phase < 6; phase = phase + 1) begin
            #1;
            apply_step("shared phase: opposite selection",
                       1'b1, !path, 1'b0, transition_timers(path, phase));
        end
    end

    // Stop from every reachable phase, with and without forward requests.
    for (path = 0; path < 2; path = path + 1) begin
        #1;
        for (phase = 0; phase < 6; phase = phase + 1) begin
            #1;
            for (mode = 0; mode < 2; mode = mode + 1) begin
                #1;
                reach_phase(path, phase);
                apply_step("stop request", mode, path, 1'b1,
                           mode ? transition_timers(path, phase) : 7'b0);
                apply_step("stop released", 1'b0, path, 1'b0, 7'b0);
            end
        end
    end

    // Raising reset without a clock, followed by synchronous reset.
    for (path = 0; path < 2; path = path + 1) begin
        #1;
        for (phase = 0; phase < 6; phase = phase + 1) begin
            #1;
            reach_phase(path, phase);
            @(negedge clk);
            rst = 1;
            #1;
            observe("reset raised before clock");
            @(posedge clk);
            #1;
            observe("reset sampled high");
            @(negedge clk);
            rst = 0;
            #1;
            observe("reset falling after idle reset");
        end
    end

    // Falling reset captures a pending transition between clock edges.
    for (path = 0; path < 2; path = path + 1) begin
        #1;
        for (phase = 0; phase < 6; phase = phase + 1) begin
            #1;
            reach_phase(path, phase);
            @(negedge clk);
            rst = 1;
            start = 0;
            select = path;
            timers = transition_timers(path, phase);
            #1;
            start = 1;
            #1;
            observe("pending transition with reset high");
            rst = 0;
            #1;
            observe("falling reset before next clock");
            start = 0;
            #1;
            observe("hold after falling reset capture");
            @(posedge clk);
            #1;
            observe("clock after falling reset capture");
        end
    end

    // Reset while already idle with a decoded start request.
    for (path = 0; path < 2; path = path + 1) begin
        #1;
        phase = 0;
        reset_clean;
        @(negedge clk);
        rst = 1;
        select = path;
        timers = transition_timers(path, 0);
        start = 1;
        #1;
        observe("idle start decode with reset high");
        @(posedge clk);
        #1;
        observe("reset clock while already idle");
        @(negedge clk);
        rst = 0;
        #1;
        observe("release with pending start");
        start = 0;
        timers = 0;
        #1;
        observe("hold after release");
    end

    // Select-only changes, from matching to mismatching and vice versa.
    for (path = 0; path < 2; path = path + 1) begin
        #1;
        for (phase = 0; phase < 3; phase = phase + 1) begin
            #1;
            for (mode = 0; mode < 2; mode = mode + 1) begin
                #1;
                reach_phase(path, phase);
                @(negedge clk);
                start = 0;
                select = path ^ mode;
                timers = transition_timers(path, phase);
                #1;
                start = 1;
                #1;
                observe("selection baseline");
                select = !select;
                #1;
                observe("select changed alone");
                @(posedge clk);
                #1;
                observe("clock after select-only change");
                apply_step("decode retriggered through start",
                           1'b1, select, 1'b0,
                           transition_timers(path, phase));
            end
        end
    end

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam integer CYCLES_PER_TU   = 25;
localparam integer TUS_PER_LINE    = 80;
localparam integer CYCLES_PER_LINE = CYCLES_PER_TU * TUS_PER_LINE;
localparam integer VISIBLE_LINES   = 1080;
localparam integer TOTAL_LINES     = 1125;

// Inputs
reg clk;

// Outputs
wire [23:0] M_value, N_value;
