module testbench;

// Inputs
reg clk;
reg rst;
reg [7:0] wr;
reg rd_r0_mux, rd_r1_mux;
reg [7:0] ds1_sel, ds2_sel;
reg [7:0] rd_data;
reg [15:0] cr_data;

// Outputs
wire [7:0] ds1_data, ds2_data;
wire [15:0] r6_r7_data;

integer i, j;

gpr uut (
    .clk(clk),
    .rst(rst),
    .r0_write(wr[0]), .r1_write(wr[1]),
    .r2_write(wr[2]), .r3_write(wr[3]),
    .r4_write(wr[4]), .r5_write(wr[5]),
    .r6_write(wr[6]), .r7_write(wr[7]),
    .rd_r0_mux(rd_r0_mux),
    .rd_r1_mux(rd_r1_mux),
    .ds1_r0(ds1_sel[0]), .ds1_r1(ds1_sel[1]),
    .ds1_r2(ds1_sel[2]), .ds1_r3(ds1_sel[3]),
    .ds1_r4(ds1_sel[4]), .ds1_r5(ds1_sel[5]),
    .ds1_r6(ds1_sel[6]), .ds1_r7(ds1_sel[7]),
    .ds2_r0(ds2_sel[0]), .ds2_r1(ds2_sel[1]),
    .ds2_r2(ds2_sel[2]), .ds2_r3(ds2_sel[3]),
    .ds2_r4(ds2_sel[4]), .ds2_r5(ds2_sel[5]),
    .ds2_r6(ds2_sel[6]), .ds2_r7(ds2_sel[7]),
    .rd_data(rd_data),
    .cr_data(cr_data),
    .ds1_data(ds1_data),
    .ds2_data(ds2_data),
    .r6_r7_data(r6_r7_data)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [8*32-1:0] tag;
    begin
        $display("%0t %0s rst=%b wr=%h mux0=%b mux1=%b rd=%h cr=%h sel1=%h sel2=%h ds1_data=%h ds2_data=%h r6_r7_data=%h",
                 $time, tag, rst, wr, rd_r0_mux, rd_r1_mux,
                 rd_data, cr_data, ds1_sel, ds2_sel,
                 ds1_data, ds2_data, r6_r7_data);
    end
endtask

task reset_case;
    begin
        @(negedge clk);
        rst = 1;
        wr = 8'hFF;
        rd_data = 8'hFF;
        cr_data = 16'hA53C;
        rd_r0_mux = 1;
        rd_r1_mux = 1;
        ds1_sel = 8'hFF;
        ds2_sel = 8'hFF;
        #1;
        observe("reset-before-edge");
        @(posedge clk);
        #1;
        observe("reset-after-edge");
        @(negedge clk);
        rst = 0;
        wr = 0;
        rd_r0_mux = 0;
        rd_r1_mux = 0;
        rd_data = 0;
        cr_data = 0;
        #1;
        observe("reset-released");
    end
endtask

task write_cycle;
    input [7:0] enables;
    input [7:0] normal_data;
    input [15:0] control_data;
    input mux0, mux1;
    begin
        @(negedge clk);
        wr = enables;
        rd_data = normal_data;
        cr_data = control_data;
        rd_r0_mux = mux0;
        rd_r1_mux = mux1;
        #1;
        observe("write-before-edge");
        @(posedge clk);
        #1;
        observe("write-after-edge");
    end
endtask

task read_pair;
    input [7:0] select1, select2;
    begin
        @(negedge clk);
        wr = 0;
        ds1_sel = select1;
        ds2_sel = select2;
        #1;
        observe("combinational-read");
    end
endtask

task scan_registers;
    integer k;
    begin
        wr = 0;
        for (k = 0; k < 8; k = k + 1) begin
            @(negedge clk);
            ds1_sel = 8'h01 << k;
            ds2_sel = 8'h80 >> k;
            #1;
            observe("register-scan");
        end
    end
endtask

initial begin
    rst = 1;
    wr = 0;
    rd_r0_mux = 0;
    rd_r1_mux = 0;
    ds1_sel = 0;
    ds2_sel = 0;
    rd_data = 0;
    cr_data = 0;

    // Wait 100 ns for global reset to finish.
    #100;

    // Initial reset, synchronous pulse, and reset/write priority.
    reset_case;
    scan_registers;
    write_cycle(8'hFF, 8'hFF, 16'h0000, 0, 0);
    read_pair(8'hFF, 8'hFF);
    @(negedge clk);
    rst = 1;
    #1;
    observe("reset-pulse-asserted");
    #1;
    rst = 0;
    #1;
    observe("reset-pulse-released");
    @(posedge clk);
    #1;
    observe("after-reset-pulse");
    reset_case;
    scan_registers;

    // Individual writes, preservation of other registers, and paired view.
    reset_case;
    for (i = 0; i < 8; i = i + 1) begin
        @(negedge clk);
        ds1_sel = 8'h01 << i;
        ds2_sel = 8'h80 >> i;
        write_cycle(8'h01 << i, 8'h01 << i, 16'hFFFF, 0, 0);
        scan_registers;
    end

    // Read combinations on the independently populated register bank.
    for (i = 0; i < 8; i = i + 1) begin
        @(negedge clk);
        ds1_sel = 8'h01 << i;
        ds2_sel = 8'h01 << i;
        #1;
        observe("same-register-both-ports");
    end
    read_pair(8'h00, 8'h00);
    read_pair(8'h00, 8'hFF);
    read_pair(8'hFF, 8'h00);
    read_pair(8'h55, 8'hAA);
    read_pair(8'hAA, 8'h55);
    read_pair(8'h81, 8'h18);
    read_pair(8'h18, 8'h81);
    read_pair(8'hFF, 8'hFF);

    // All mux combinations; separate and simultaneous r0/r1 writes.
    for (i = 0; i < 4; i = i + 1) begin
        @(negedge clk);
        reset_case;
        write_cycle(8'hFF, 8'h5A, 16'h0000, 0, 0);
        read_pair(8'h01, 8'h02);
        for (j = 1; j <= 3; j = j + 1) begin
            @(negedge clk);
            ds1_sel = 8'h01;
            ds2_sel = 8'h02;
            write_cycle(j, 8'hC0 + j,
                        16'h3CA0 + j * 16'h0101, i[0], i[1]);
            scan_registers;
        end
        write_cycle(8'hFF, 8'h81, 16'h7E24, i[0], i[1]);
        scan_registers;
        write_cycle(8'h00, 8'h18, 16'hE742, ~i[0], ~i[1]);
        scan_registers;
    end

    // Both data boundaries, overwrites, and disabled-write retention.
    for (i = 0; i < 2; i = i + 1) begin
        @(negedge clk);
        reset_case;
        write_cycle(8'hFF, i ? 8'h00 : 8'hFF, 16'hA53C, 0, 0);
        scan_registers;
        write_cycle(8'hFF, i ? 8'hFF : 8'h00, 16'h3CA5, 0, 1);
        scan_registers;
        write_cycle(8'h00, i ? 8'h00 : 8'hFF, 16'h9696, 1, 0);
        scan_registers;
    end

    $display("===========End===========");
    $finish;
end

endmodule

