task step;
    input [8*24-1:0] label;
    input integer index;
    input [2:0] controls; // {rst, flushE, stallE}
    input [W-1:0] data;
    begin
        @(negedge clk);
        {rst, flushE, stallE} = controls;
        bundleD = data;
        #1;
        observe(label, index, "pre");
        @(posedge clk);
        #1;
        observe(label, index, "post");
    end
endtask

