    observe("startup_reset", 0, "settled");

    // Test Case 1: enabled transfer and bit independence
    initialize_case;
    step("transfer_zero", 0, 3'b000, {W{1'b0}});
    step("transfer_ones", 0, 3'b000, {W{1'b1}});
    step("transfer_alternating", 0, 3'b000, {(W/2){2'b10}});
    step("transfer_alternating", 1, 3'b000, {(W/2){2'b01}});
    for (i = 0; i < W; i = i + 1) begin
        #1;
        pattern = {W{1'b0}};
        pattern[i] = 1'b1;
        step("transfer_walking_one", i, 3'b000, pattern);
    end
    step("transfer_zero", 1, 3'b000, {W{1'b0}});

    // Test Case 2: multi-cycle stall and release
    initialize_case;
    step("stall_preload", 0, 3'b000, {(W/2){2'b10}});
    for (i = 0; i < 4; i = i + 1) begin
        #1;
        pattern = {W{1'b1}} << i;
        step("stall_hold", i, 3'b001, pattern);
    end
    step("stall_release", 0, 3'b000, {(W/2){2'b01}});

    // Test Case 3: every clearing-control combination
    for (c = 2; c < 8; c = c + 1) begin
        #1;
        initialize_case;
        step("clear_preload", c, 3'b000, {W{1'b1}});
        step("clear_assert", c, c[2:0], {(W/2){2'b10}});
        step("clear_held", c, c[2:0], {(W/2){2'b01}});
        step("bubble_stalled", c, 3'b001, {W{1'b1}});
        step("clear_recovery", c, 3'b000, {(W/2){2'b10}});
    end

    $display("===========End===========");
    $finish;
end

