    begin
        $display(
            "t=%0t tc=%0d %0s reset=%b addr=%h din=%h we=%b busy=%b gpio_in=%h | RegData_o=%h Run=%b Mode=%h CarrierCycle=%h CarrierDuty=%h MemStart=%h MemStop=%h MemAddr=%h LEDPolarity=%b LED=%b GpioPort=%h GpioDir=%h Interrupt=%b",
            $time, tc, label, reset, addr, data_in, wr_en, busy,
            gpio_in, data_out, run, mode, carrier_cycle, carrier_duty,
            mem_start, mem_stop, mem_addr, led_polarity, led,
            gpio_out, gpio_dir, interrupt_out
        );
    end
endtask

// Each step exposes one pipeline clock, including write-edge read data.
task step;
    input [7:0] next_addr;
    input [7:0] next_data;
    input next_we;
    begin
        @(negedge clk);
        addr = next_addr;
        data_in = next_data;
        wr_en = next_we;
        @(posedge clk);
        #1;
        observe("clock");
    end
endtask

task read_reg;
    input [7:0] reg_addr;
    begin
        step(reg_addr, 8'h00, 1'b0);
        step(reg_addr, 8'h00, 1'b0);
    end
endtask

task write_reg;
    input [7:0] reg_addr;
    input [7:0] value;
    begin
        step(reg_addr, 8'h00, 1'b0);
        step(reg_addr, value, 1'b1);
        step(reg_addr, 8'h00, 1'b0);
    end
endtask

task reset_dut;
    begin
        @(negedge clk);
        #2;
        reset = 1'b1;
        #1;
        observe("asynchronous reset");
        repeat (2) @(posedge clk);
        #1;
        observe("reset held");
        @(negedge clk);
        reset = 1'b0;
        busy = 1'b0;
        gpio_in = 8'h00;
        addr = 8'h00;
        data_in = 8'h00;
        wr_en = 1'b0;
        @(posedge clk);
        #1;
        observe("reset released");
    end
endtask

initial begin
    // Initialize Inputs; wait 100 ns for global reset to finish.
    tc = 0;
    reset = 1'b1;
    busy = 1'b0;
    gpio_in = 8'h00;
    addr = 8'h00;
    data_in = 8'h00;
    wr_en = 1'b0;
    pattern = 8'h00;
    #1;
    observe("startup reset");
    #99;
    @(negedge clk);
    reset = 1'b0;

    // 1: Reset map, identification, reserved and unmapped locations.
    tc = 1;
    for (i = 0; i < 20; i = i + 1) begin
        read_reg(i);
        #1;
    end
    for (i = 0; i < 4; i = i + 1) begin
        write_reg(i, 8'hff);
        write_reg(i, 8'h00);
        #1;
    end
    write_reg(8'h0f, 8'hff);
    write_reg(8'h11, 8'hff);
    write_reg(8'h13, 8'hff);
    write_reg(8'h14, 8'hff);
    write_reg(8'h80, 8'hff);
    write_reg(8'hff, 8'hff);

    // 2: Storage patterns, byte independence, truncation and write gating.
    tc = 2;
    reset_dut;
    gpio_in = 8'h3c;
    for (p = 0; p < 4; p = p + 1) begin
        case (p)
            0: pattern = 8'hff;
            1: pattern = 8'ha5;
            2: pattern = 8'h5a;
            3: pattern = 8'h00;
        endcase
        for (i = 6; i < 20; i = i + 1) begin
            write_reg(i, pattern);
            #1;
        end
        #1;
    end
    for (i = 4; i < 20; i = i + 1) begin
        step(i, 8'hff, 1'b0);
        step(i, 8'hff, 1'b0);
        #1;
    end

    // 3: Consecutive pipeline reads and writes with changing addresses.
    tc = 3;
    reset_dut;
    for (i = 0; i < 6; i = i + 1) begin
        step(i, 8'h00, 1'b0);
        #1;
    end
    step(8'h06, 8'h00, 1'b0);
    step(8'h07, 8'ha5, 1'b1);
    step(8'h08, 8'h5a, 1'b1);
    step(8'h09, 8'h3c, 1'b1);
    step(8'hff, 8'hc3, 1'b1);
    step(8'h06, 8'hff, 1'b1);
    step(8'h07, 8'h00, 1'b0);
    step(8'h08, 8'h00, 1'b0);
    step(8'h09, 8'h00, 1'b0);
    step(8'hff, 8'h00, 1'b0);

    // 4: Live GPIO input is independent of output latch and direction.
    tc = 4;
    reset_dut;
    write_reg(8'h10, 8'ha5);
    write_reg(8'h12, 8'h5a);
    gpio_in = 8'h00;
    read_reg(8'h10);
    gpio_in = 8'hff;
    step(8'h10, 8'h00, 1'b0);
    gpio_in = 8'h3c;
    step(8'h10, 8'h00, 1'b0);
    write_reg(8'h10, 8'h5a);
    read_reg(8'h12);

    // 5: Command pulses, repeated writes, masked bits and live busy.
    tc = 5;
    reset_dut;
    write_reg(8'h04, 8'h01);
    step(8'h04, 8'h00, 1'b0);
    step(8'h04, 8'h01, 1'b1);
    step(8'h04, 8'hff, 1'b1);
    step(8'h04, 8'hfe, 1'b1);
    step(8'h04, 8'h00, 1'b1);
    step(8'h04, 8'h00, 1'b0);
    busy = 1'b1;
    write_reg(8'h04, 8'h01);
    busy = 1'b0;
    read_reg(8'h04);

    // 6: All modes, individual control bits and ignored upper bits.
    tc = 6;
    reset_dut;
    for (i = 0; i < 4; i = i + 1) begin
        write_reg(8'h05, i);
        #1;
    end
    for (i = 0; i < 6; i = i + 1) begin
        write_reg(8'h05, 8'h01 << i);
        #1;
    end
    write_reg(8'h05, 8'hff);
    write_reg(8'h05, 8'hc0);
    write_reg(8'h05, 8'h00);

    // 7: Completion, pending retention, enable gating and acknowledgement.
    tc = 7;
    for (p = 0; p < 2; p = p + 1) begin
        reset_dut;
        write_reg(8'h05, p << 5);
        busy = 1'b1;
        read_reg(8'h04);
        read_reg(8'h05);
        busy = 1'b0;
        read_reg(8'h05);
        step(8'h05, 8'h00, 1'b0);
        busy = 1'b1;
        read_reg(8'h05);
        busy = 1'b0;
        read_reg(8'h05);
        write_reg(8'h05, 8'h30);
        write_reg(8'h05, 8'h10);
        write_reg(8'h05, 8'h30);
        write_reg(8'h05, 8'h20);
        read_reg(8'h05);
        busy = 1'b1;
        read_reg(8'h04);
        busy = 1'b0;
        read_reg(8'h05);
        #1;
    end

    // 8: Control-write priority on the exact busy falling-edge clock.
    tc = 8;
    for (p = 0; p < 2; p = p + 1) begin
        reset_dut;
        write_reg(8'h05, 8'h20);
        busy = 1'b1;
        step(8'h05, 8'h00, 1'b0);
        busy = 1'b0;
        step(8'h05, 8'h20 | (p << 4), 1'b1);
        read_reg(8'h05);
        #1;
    end
    reset_dut;
    write_reg(8'h05, 8'h20);
    busy = 1'b1;
    step(8'h06, 8'h00, 1'b0);
    busy = 1'b0;
    step(8'h07, 8'hff, 1'b1);
    read_reg(8'h05);

    // 9: Asynchronous reset of populated state with active run/interrupt.
    tc = 9;
    reset_dut;
    for (i = 6; i < 20; i = i + 1) begin
        write_reg(i, 8'hff);
        #1;
    end
    write_reg(8'h05, 8'h37);
    gpio_in = 8'ha5;
    busy = 1'b1;
    step(8'h04, 8'h00, 1'b0);
    step(8'h04, 8'h01, 1'b1);
    reset_dut;
    for (i = 0; i < 20; i = i + 1) begin
        read_reg(i);
        #1;
    end
    write_reg(8'h05, 8'h20);
    read_reg(8'h05);
    write_reg(8'h06, 8'h5a);
    write_reg(8'h04, 8'h01);
    busy = 1'b1;
    read_reg(8'h04);
    busy = 1'b0;
    read_reg(8'h05);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

// Inputs
reg [31:0] ReadData2;
reg [31:0] Sign_Extnd_out;
reg        ALUSrc;

// Outputs
wire [31:0] ALUIn2;

// Unused clock included for the required testbench structure
reg clk;

// Instantiate the Unit Under Test (UUT)
ALU_mux uut (
    .ReadData2(ReadData2),
    .Sign_Extnd_out(Sign_Extnd_out),
    .ALUSrc(ALUSrc),
    .ALUIn2(ALUIn2)
);

// clk toggle generate
initial clk = 0;

always #5 clk = ~clk;

initial begin
    // Initialize inputs
    ReadData2     = 32'h00000000;
    Sign_Extnd_out = 32'h00000000;
    ALUSrc        = 1'b0;
    #1;
    $display("TC1 ALUSrc=0, ReadData2=0x%08h, Sign_Extnd_out=0x%08h, ALUIn2=0x%08h",
             ReadData2, Sign_Extnd_out, ALUIn2);

    // Test selected ReadData2 boundary and unselected immediate value
    ReadData2      = 32'hFFFFFFFF;
    Sign_Extnd_out = 32'h80000000;
    ALUSrc         = 1'b0;
    #1;
    $display("TC2 ALUSrc=0, ReadData2=0x%08h, Sign_Extnd_out=0x%08h, ALUIn2=0x%08h",
             ReadData2, Sign_Extnd_out, ALUIn2);

    // Test selected Sign_Extnd_out boundary
    ALUSrc = 1'b1;
    #1;
    $display("TC3 ALUSrc=1, ReadData2=0x%08h, Sign_Extnd_out=0x%08h, ALUIn2=0x%08h",
             ReadData2, Sign_Extnd_out, ALUIn2);

    // Change selected immediate and unselected register data
    Sign_Extnd_out = 32'h7FFFFFFF;
    ReadData2      = 32'h12345678;
    #1;
    $display("TC4 ALUSrc=1, ReadData2=0x%08h, Sign_Extnd_out=0x%08h, ALUIn2=0x%08h",
             ReadData2, Sign_Extnd_out, ALUIn2);

    // Switch back to the register-data source
    ALUSrc = 1'b0;
    #1;
    $display("TC5 ALUSrc=0, ReadData2=0x%08h, Sign_Extnd_out=0x%08h, ALUIn2=0x%08h",
             ReadData2, Sign_Extnd_out, ALUIn2);

    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

parameter PROFILE = 0;
parameter TCQ = 1;

localparam DQS_WIDTH  = (PROFILE == 7) ? 1 : 8;
localparam RANK_WIDTH = (PROFILE == 7) ? 2 : 1;
localparam VWIDTH = 5 * DQS_WIDTH;

localparam DRAM_TYPE =
    ((PROFILE == 4) || (PROFILE == 5)) ? "DDR2" :
    (PROFILE == 6) ? "OTHER" : "DDR3";
localparam NCWL =
    (PROFILE == 4) ? 3 : (PROFILE == 5) ? 4 :
    ((PROFILE == 1) || (PROFILE == 2)) ? 6 :
    (PROFILE == 3) ? 7 : 5;
localparam REG_CTRL =
    ((PROFILE == 1) || (PROFILE == 3)) ? "ON" : "OFF";
localparam PHASE_DETECT =
    ((PROFILE == 2) || (PROFILE == 5)) ? "OFF" : "ON";
localparam DEBUG_PORT =
    ((PROFILE == 0) || (PROFILE == 5)) ? "OFF" : "ON";

localparam C0 = (PROFILE == 0) ? 4 :
                ((PROFILE == 2) || (PROFILE == 7)) ? 1 : 2;
localparam C1 = (PROFILE == 0) ? 4 : (PROFILE == 7) ? 0 : 2;
localparam C2 = ((PROFILE == 0) || (PROFILE == 7)) ? 0 :
                (PROFILE == 2) ? 3 : 2;
localparam C3 = ((PROFILE == 0) || (PROFILE == 7)) ? 0 :
                (PROFILE == 2) ? 1 : 2;

localparam L0 = (PROFILE == 0) ? 32'h03020100 :
                (PROFILE == 7) ? 32'h00000000 :
                (PROFILE == 2) ? 32'h00000006 : 32'h00000106;
localparam L1 = (PROFILE == 0) ? 32'h07060504 : 32'h00000502;
localparam L2 = (PROFILE == 2) ? 32'h00010300 : 32'h00000007;
localparam L3 = (PROFILE == 2) ? 32'h00000004 : 32'h00000403;

// Two central updates, three receiving stages, and one lane update.
localparam SETTLE = (6*TCQ + 2*10 + 4*26 + 9)/10 + 2;

// Inputs
reg clk;
reg [3:0] clk_rsync;
reg rst;
reg [3:0] rst_rsync;
reg wrlvl_done;
reg [1:0] rdlvl_done;
reg pd_cal_done;
reg mc_data_sel;
reg [RANK_WIDTH:0] mc_ioconfig;
reg mc_ioconfig_en;
reg [0:0] phy_ioconfig;
reg phy_ioconfig_en;
reg dqs_oe;
reg [VWIDTH-1:0] dlyval_wrlvl_dqs, dlyval_wrlvl_dq;
reg [DQS_WIDTH-1:0] dlyce_rdlvl_cpt;
reg dlyinc_rdlvl_cpt;
reg [3:0] dlyce_rdlvl_rsync;
reg dlyinc_rdlvl_rsync;
reg [VWIDTH-1:0] dlyval_rdlvl_dq, dlyval_rdlvl_dqs;
reg [DQS_WIDTH-1:0] dlyce_pd_cpt, dlyinc_pd_cpt;
reg [VWIDTH-1:0] dlyval_pd_dqs;
reg dbg_pd_off;

// Outputs
wire [VWIDTH-1:0] dlyval_dqs, dlyval_dq;
wire dlyrst_cpt, dlyrst_rsync;
wire [DQS_WIDTH-1:0] dlyce_cpt, dlyinc_cpt;
wire [3:0] dlyce_rsync, dlyinc_rsync;

integer source, state, debug_sel, boundary, lane;

phy_dly_ctrl #(
    .TCQ(TCQ),
    .DQ_WIDTH((PROFILE == 7) ? 8 : 64),
    .DQS_CNT_WIDTH((PROFILE == 7) ? 1 : 3),
    .DQS_WIDTH(DQS_WIDTH), .RANK_WIDTH(RANK_WIDTH),
    .nCWL(NCWL), .REG_CTRL(REG_CTRL),
    .WRLVL((PROFILE == 7) ? "OFF" : "ON"),
    .PHASE_DETECT(PHASE_DETECT), .DRAM_TYPE(DRAM_TYPE),
    .nDQS_COL0(C0), .nDQS_COL1(C1),
    .nDQS_COL2(C2), .nDQS_COL3(C3),
    .DQS_LOC_COL0(L0), .DQS_LOC_COL1(L1),
    .DQS_LOC_COL2(L2), .DQS_LOC_COL3(L3),
    .DEBUG_PORT(DEBUG_PORT)
) uut (
    .clk(clk), .rst(rst),
    .clk_rsync(clk_rsync), .rst_rsync(rst_rsync),
    .wrlvl_done(wrlvl_done), .rdlvl_done(rdlvl_done),
    .pd_cal_done(pd_cal_done),
    .mc_data_sel(mc_data_sel), .mc_ioconfig(mc_ioconfig),
    .mc_ioconfig_en(mc_ioconfig_en),
    .phy_ioconfig(phy_ioconfig), .phy_ioconfig_en(phy_ioconfig_en),
    .dqs_oe(dqs_oe),
    .dlyval_wrlvl_dqs(dlyval_wrlvl_dqs),
    .dlyval_wrlvl_dq(dlyval_wrlvl_dq),
    .dlyce_rdlvl_cpt(dlyce_rdlvl_cpt),
    .dlyinc_rdlvl_cpt(dlyinc_rdlvl_cpt),
    .dlyce_rdlvl_rsync(dlyce_rdlvl_rsync),
    .dlyinc_rdlvl_rsync(dlyinc_rdlvl_rsync),
    .dlyval_rdlvl_dq(dlyval_rdlvl_dq),
    .dlyval_rdlvl_dqs(dlyval_rdlvl_dqs),
    .dlyce_pd_cpt(dlyce_pd_cpt), .dlyinc_pd_cpt(dlyinc_pd_cpt),
    .dlyval_pd_dqs(dlyval_pd_dqs), .dbg_pd_off(dbg_pd_off),
    .dlyval_dqs(dlyval_dqs), .dlyval_dq(dlyval_dq),
    .dlyrst_cpt(dlyrst_cpt), .dlyce_cpt(dlyce_cpt),
    .dlyinc_cpt(dlyinc_cpt), .dlyrst_rsync(dlyrst_rsync),
    .dlyce_rsync(dlyce_rsync), .dlyinc_rsync(dlyinc_rsync)
);

initial clk = 0;
always #5 clk = ~clk;

initial clk_rsync = 0;
always #7  clk_rsync[0] = ~clk_rsync[0];
always #9  clk_rsync[1] = ~clk_rsync[1];
always #11 clk_rsync[2] = ~clk_rsync[2];
always #13 clk_rsync[3] = ~clk_rsync[3];

task observe;
    input [8*40-1:0] tag;
    input integer sample;
    begin
        $display(
            {"P=%0d t=%0t case=%0s sample=%0d src=%b ",
             "rd_done=%b dbg=%b pd_done=%b wl_done=%b ",
             "dlyval_dqs=%h dlyval_dq=%h ",
             "dlyrst_cpt=%b dlyce_cpt=%b dlyinc_cpt=%b ",
             "dlyrst_rsync=%b dlyce_rsync=%b dlyinc_rsync=%b"},
            PROFILE, $time, tag, sample, mc_data_sel,
            rdlvl_done, dbg_pd_off, pd_cal_done, wrlvl_done,
            dlyval_dqs, dlyval_dq,
            dlyrst_cpt, dlyce_cpt, dlyinc_cpt,
            dlyrst_rsync, dlyce_rsync, dlyinc_rsync);
    end
endtask

task settle;
    input [8*40-1:0] tag;
    begin
        repeat (SETTLE) @(posedge clk);
        #2.1;
        observe(tag, 0);
    end
endtask

task trace_mode;
    input [8*40-1:0] tag;
    integer k;
    begin
        for (k = 0; k < SETTLE; k = k + 1) begin
            @(posedge clk);
            #2.1;
            observe(tag, k);
        end
    end
endtask

task defaults;
    begin
        rst = 1;
        rst_rsync = 4'b1111;
        wrlvl_done = 0;
        rdlvl_done = 0;
        pd_cal_done = 0;
        mc_data_sel = 0;
        mc_ioconfig = 0;
        mc_ioconfig_en = 0;
        phy_ioconfig = 0;
        phy_ioconfig_en = 1;
        dqs_oe = 0;
        dbg_pd_off = 0;
        dlyval_wrlvl_dqs = {DQS_WIDTH{5'd0}};
        dlyval_wrlvl_dq = {DQS_WIDTH{5'd31}};
        dlyval_rdlvl_dqs = {DQS_WIDTH{5'd8}};
        dlyval_rdlvl_dq = {DQS_WIDTH{5'd23}};
        dlyval_pd_dqs = {DQS_WIDTH{5'd16}};
        dlyce_rdlvl_cpt = 8'h55;
        dlyinc_rdlvl_cpt = 0;
        dlyce_rdlvl_rsync = 4'b1010;
        dlyinc_rdlvl_rsync = 1;
        dlyce_pd_cpt = 8'hAA;
        dlyinc_pd_cpt = 8'h96;
    end
endtask

task initialize_case;
    integer n;
    begin
        @(negedge clk);
        defaults;
        for (n = 0; n < DQS_WIDTH; n = n + 1) begin
            @(negedge clk);
            dlyval_wrlvl_dqs[5*n +: 5] = n;
            dlyval_wrlvl_dq[5*n +: 5] = 31-n;
            dlyval_rdlvl_dqs[5*n +: 5] = 8+n;
            dlyval_rdlvl_dq[5*n +: 5] = 23-n;
            dlyval_pd_dqs[5*n +: 5] = 16+n;
            #1;
        end
        settle("initialize_reset_held");
        @(negedge clk);
        rst = 0;
        rst_rsync = 0;
        settle("initialize_reset_released");
    end
endtask

task configure;
    input src, mode, enable;
    begin
        @(negedge clk);
        mc_data_sel = src;
        mc_ioconfig = 0;
        mc_ioconfig[RANK_WIDTH] = src ? mode : ~mode;
        phy_ioconfig = src ? ~mode : mode;
        mc_ioconfig_en = src ? enable : ~enable;
        phy_ioconfig_en = src ? ~enable : enable;
    end
endtask

initial begin
    defaults;

    // Wait 100 ns for global reset to finish.
    #100;
    observe("startup_reset", 0);

    // Mode sources, history, write leveling, and DDR3 forcing.
    for (source = 0; source < 2; source = source + 1) begin
        initialize_case;
        configure(source, 0, 1);
        settle("selected_read");

        configure(source, 1, 0);
        trace_mode("current_write_enable_low");
        configure(source, 0, 0);
        trace_mode("current_read_enable_low");

        configure(source, 1, 1);
        settle("capture_write_history");
        @(negedge clk);
        wrlvl_done = 1;
        settle("write_leveling_done_toggle");

        configure(source, 0, 0);
        trace_mode("read_with_retained_write");
        @(negedge clk);
        rst = 1;
        rst_rsync = 4'b1111;
        #0.1;
        observe("history_reset_assert", 0);
        settle("history_reset_held");
        @(negedge clk);
        rst = 0;
        rst_rsync = 0;
        #0.1;
        observe("history_reset_release", 0);
        settle("history_after_reset");

        configure(1-source, 0, 0);
        trace_mode("switch_source_keep_history");
        configure(source, 0, 1);
        trace_mode("clear_write_history");

        configure(source, 0, 0);
        dqs_oe = 1;
        trace_mode("dqs_oe_assert");
        @(negedge clk);
        dqs_oe = 0;
        trace_mode("dqs_oe_release");
        #1;
    end

    // Calibration status, phase detection, and debug override.
    initialize_case;
    for (state = 0; state < 4; state = state + 1) begin
        @(negedge clk);
        rdlvl_done = state;
        for (debug_sel = 0; debug_sel < 2; debug_sel = debug_sel + 1) begin
            @(negedge clk);
            dbg_pd_off = debug_sel;
            pd_cal_done = 0;
            settle("calibration_pd_done_low");
            @(negedge clk);
            pd_cal_done = 1;
            settle("calibration_pd_done_high");
            #1;
        end
        #1;
    end

    // Walking capture/column controls and increment directions.
    initialize_case;
    for (lane = 0; lane < DQS_WIDTH; lane = lane + 1) begin
        @(negedge clk);
        rdlvl_done = 0;
        dlyce_rdlvl_cpt = 1 << lane;
        dlyce_rdlvl_rsync = 4'b0001 << (lane % 4);
        dlyinc_rdlvl_cpt = lane[0];
        dlyinc_rdlvl_rsync = ~lane[0];
        dlyce_pd_cpt = ~dlyce_rdlvl_cpt;
        dlyinc_pd_cpt = dlyce_rdlvl_cpt;
        settle("walking_read_controls");
        @(negedge clk);
        rdlvl_done = 2;
        settle("walking_phase_controls");
        #1;
    end

    // Minimum/maximum delay values and zero/all-one controls.
    initialize_case;
    for (boundary = 0; boundary < 2; boundary = boundary + 1) begin
        @(negedge clk);
        dlyval_wrlvl_dqs = {DQS_WIDTH{boundary ? 5'd31 : 5'd0}};
        dlyval_wrlvl_dq = {DQS_WIDTH{boundary ? 5'd0 : 5'd31}};
        dlyval_rdlvl_dqs = {DQS_WIDTH{boundary ? 5'd0 : 5'd31}};
        dlyval_rdlvl_dq = {DQS_WIDTH{boundary ? 5'd31 : 5'd0}};
        dlyval_pd_dqs = {DQS_WIDTH{boundary ? 5'd31 : 5'd0}};
        dlyce_rdlvl_cpt = {DQS_WIDTH{boundary[0]}};
        dlyce_rdlvl_rsync = {4{boundary[0]}};
        dlyinc_rdlvl_cpt = boundary[0];
        dlyinc_rdlvl_rsync = ~boundary[0];
        dlyce_pd_cpt = ~dlyce_rdlvl_cpt;
        dlyinc_pd_cpt = ~dlyce_rdlvl_cpt;
        rdlvl_done = 0;
        configure(0, 0, 1);
        settle("boundary_read_leveling");
        @(negedge clk);
        rdlvl_done = 2;
        settle("boundary_phase_detection");
        configure(0, 1, 1);
        settle("boundary_write_leveling");
        #1;
    end

    // Reset forwarding, TCQ observations, and updates during reset.
    initialize_case;
    @(negedge clk);
    rst = 1;
    rst_rsync = 4'b1111;
    dlyce_rdlvl_cpt = ~dlyce_rdlvl_cpt;
    dlyinc_rdlvl_cpt = 1;
    dlyce_rdlvl_rsync = ~dlyce_rdlvl_rsync;
    dlyval_rdlvl_dqs = ~dlyval_rdlvl_dqs;
    dlyval_rdlvl_dq = ~dlyval_rdlvl_dq;
    #0.1;
    observe("reset_immediate_assert", 0);
    @(posedge clk);
    #0.1;
    observe("control_before_TCQ", 0);
    #(TCQ + 0.1);
    observe("control_after_TCQ", 0);
    settle("updates_while_reset_high");

    @(negedge clk);
    rst = 0;
    #0.1;
    observe("reset_immediate_release", 0);
    settle("rst_low_rsync_reset_high");
    @(negedge clk);
    rst_rsync = 4'b0101;
    dlyval_rdlvl_dqs = ~dlyval_rdlvl_dqs;
    settle("rsync_reset_alternating");
    @(negedge clk);
    rst_rsync = 4'b1010;
    dlyval_rdlvl_dq = ~dlyval_rdlvl_dq;
    settle("rsync_reset_complement");

    // Only the upper memory-controller configuration bit selects mode.
    initialize_case;
    configure(1, 0, 1);
    settle("mc_lower_bits_zero");
    @(negedge clk);
    mc_ioconfig[RANK_WIDTH-1:0] = {RANK_WIDTH{1'b1}};
    settle("mc_lower_bits_one");

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam DATA_BITS = 8;

// Inputs
reg clk;
reg rst_n;
reg sample_tick;
reg rx;

// Outputs
wire done_1, done_8, done_16;
wire [DATA_BITS-1:0] data_1, data_8, data_16;
integer test_id, pattern_id, reset_phase;
reg [7:0] payload;

// Instantiate the Unit Under Test (UUT)
uart_rx #(.DATA_BITS(DATA_BITS), .STOP_TICK(1)) uut_1 (
    .clk_i(clk), .rst_ni(rst_n), .sample_tick_i(sample_tick),
    .rx_i(rx), .rx_done_tick_o(done_1), .rx_data_o(data_1)
);

uart_rx #(.DATA_BITS(DATA_BITS), .STOP_TICK(8)) uut_8 (
    .clk_i(clk), .rst_ni(rst_n), .sample_tick_i(sample_tick),
    .rx_i(rx), .rx_done_tick_o(done_8), .rx_data_o(data_8)
);

uart_rx #(.DATA_BITS(DATA_BITS), .STOP_TICK(16)) uut_16 (
    .clk_i(clk), .rst_ni(rst_n), .sample_tick_i(sample_tick),
    .rx_i(rx), .rx_done_tick_o(done_16), .rx_data_o(data_16)
);

// clk toggle generate
initial clk = 0; //clk is initialized as 0
always #5 clk = ~clk;

task observe;
    input [8*32-1:0] label;
    begin
        $display("t=%0t case=%0d %0s rst_n=%b tick=%b rx=%b "
                 , $time, test_id, label, rst_n, sample_tick, rx);
        $display("  STOP=1 done=%b data=%02h | STOP=8 done=%b data=%02h | STOP=16 done=%b data=%02h",
                 done_1, data_1, done_8, data_8, done_16, data_16);
    end
endtask

task reset_receiver;
    begin
        @(negedge clk);
        #2;
        rst_n = 0;
        sample_tick = 0;
        rx = 1;
        #1;
        observe("asynchronous reset");
        repeat (2) @(posedge clk);
        @(negedge clk);
        rst_n = 1;
        repeat (3) @(posedge clk);
        #1;
        observe("reset released");
    end
endtask

task pause_ticks;
    input integer cycles;
    begin
        @(negedge clk);
        sample_tick = 0;
        repeat (cycles) @(posedge clk);
        #1;
        observe("sample ticks paused");
    end
endtask

// Each enable lasts one clock period; observe the last event in the group.
task ticks;
    input integer count;
    input [8*32-1:0] label;
    integer tick_id;
    begin
        for (tick_id = 0; tick_id < count; tick_id = tick_id + 1) begin
            @(negedge clk);
            sample_tick = 1;
            #1;
            if (tick_id == count - 1)
                observe(label);
            @(posedge clk);
            #1;
            @(negedge clk);
            sample_tick = 0;
            #1;
            if (tick_id == count - 1)
                observe("after tick, enable low");
        end
    end
endtask

task begin_start;
    begin
        @(negedge clk);
        rx = 0;
        sample_tick = 0;
        repeat (3) @(posedge clk);
        #1;
        observe("start detected, no ticks");
    end
endtask

task valid_start;
    begin
        begin_start;
        ticks(7, "start tick 7");
        pause_ticks(3);
        ticks(1, "start qualification tick 8");
    end
endtask

task receive_bits;
    input [7:0] value;
    input integer bit_count;
    integer bit_id;
    begin
        for (bit_id = 0; bit_id < bit_count; bit_id = bit_id + 1) begin
            @(negedge clk);
            rx = value[bit_id];
            repeat (2) @(posedge clk);
            ticks(15, "data tick 15");
            pause_ticks(3);
            ticks(1, "data capture tick 16");
        end
    end
endtask

task stop_interval;
    input stop_level;
    integer stop_id;
    begin
        @(negedge clk);
        rx = stop_level;
        repeat (2) @(posedge clk);
        for (stop_id = 0; stop_id < 16; stop_id = stop_id + 1) begin
            @(negedge clk);
            pause_ticks(3);
            ticks(1, "stop sample event");
        end
        @(negedge clk);
        rx = 1;
        repeat (3) @(posedge clk);
        #1;
        observe("after stop interval");
    end
endtask

task receive_frame;
    input [7:0] value;
    input stop_level;
    begin
        valid_start;
        receive_bits(value, 8);
        stop_interval(stop_level);
    end
endtask

initial begin
    // Initialize Inputs
    rst_n = 0;
    sample_tick = 0;
    rx = 1;
    test_id = 0;
    payload = 0;

    // Wait 100 ns for global reset to finish
    #100;
    observe("initial reset");

    // Test Case 1: reset and idle
    test_id = 1;
    reset_receiver;
    pause_ticks(4);
    ticks(20, "idle with sample ticks");

    // Test Case 2: rejected start, then recovery without reset
    test_id = 2;
    reset_receiver;
    begin_start;
    ticks(7, "false start tick 7");
    @(negedge clk);
    rx = 1;
    repeat (2) @(posedge clk);
    pause_ticks(3);
    ticks(1, "reject at start tick 8");
    ticks(20, "idle after rejected start");
    receive_frame(8'h96, 1'b1);

    // Test Cases 3-6: data patterns and retained data
    for (pattern_id = 0; pattern_id < 4; pattern_id = pattern_id + 1) begin
        @(negedge clk);
        test_id = 3 + pattern_id;
        case (pattern_id)
            0: payload = 8'h00;
            1: payload = 8'hFF;
            2: payload = 8'hA5;
            3: payload = 8'h81;
        endcase
        reset_receiver;
        receive_frame(payload, 1'b1);
        pause_ticks(4);
        ticks(20, "completed data retained");
    end

    // Test Case 7: consecutive characters without reset
    test_id = 7;
    reset_receiver;
    receive_frame(8'h3C, 1'b1);
    receive_frame(8'hC3, 1'b1);

    // Test Case 8: low stop level
    test_id = 8;
    reset_receiver;
    receive_frame(8'h5A, 1'b0);

    // Test Cases 9-11: reset during start, data, and stop
    for (reset_phase = 0; reset_phase < 3; reset_phase = reset_phase + 1) begin
        @(negedge clk);
        test_id = 9 + reset_phase;
        reset_receiver;
        case (reset_phase)
            0: begin
                begin_start;
                ticks(7, "reset target: start");
            end
            1: begin
                valid_start;
                receive_bits(8'hAD, 3);
                ticks(5, "reset target: partial data");
            end
            2: begin
                valid_start;
                receive_bits(8'h69, 8);
                @(negedge clk);
                rx = 1;
                pause_ticks(3);
            end
        endcase
        reset_receiver;
        receive_frame(8'hD2, 1'b1);
    end

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

// Inputs
reg clk;
reg rst;
reg [2:0] product_code;
reg online_payment;
reg start;
reg cancel;
reg [6:0] total_coin_value;

// Outputs
wire [3:0] state;
wire dispense_product;
wire [6:0] return_change;
wire [6:0] product_price;

// Instantiate the Unit Under Test
VendingMachine uut (
    .clk              (clk),
    .rst              (rst),
    .product_code     (product_code),
    .online_payment   (online_payment),
    .start            (start),
    .cancel           (cancel),
    .total_coin_value (total_coin_value),
    .state             (state),
    .dispense_product  (dispense_product),
    .return_change     (return_change),
    .product_price     (product_price)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input integer test_id;
    begin
        $display("TEST %0d: state=%b dispense_product=%b return_change=%0d product_price=%0d",
                 test_id, state, dispense_product, return_change, product_price);
    end
endtask

task reset_dut;
    input integer test_id;
    begin
        rst = 1;
        #2;
        observe(test_id);
        rst = 0;
        repeat (1) @(posedge clk);
        #1;
        observe(test_id);
    end
endtask

task cash_transaction;
    input [2:0] code;
    input [6:0] cash_value;
    input integer test_id;
    begin
        reset_dut(test_id);

        product_code = 3'b000;
        start = 1;
        repeat (1) @(posedge clk);
        #1;
        observe(test_id);

        start = 0;
        product_code = code;
        repeat (1) @(posedge clk);
        #1;
        observe(test_id);

        total_coin_value = 7'd0;
        online_payment = 0;
        repeat (1) @(posedge clk);
        #1;
        observe(test_id);

        total_coin_value = cash_value;
        repeat (1) @(posedge clk);
        #1;
        observe(test_id);

        repeat (1) @(posedge clk);
        #1;
        observe(test_id);
    end
endtask

// Exercise cancellation from each product-selection state.
task cancel_transaction;
    input [2:0] code;
    input [6:0] cash_value;
    input integer test_id;
    begin
        reset_dut(test_id);

        start = 1;
        repeat (1) @(posedge clk);
        #1;
        observe(test_id);

        start = 0;
        product_code = code;
        repeat (1) @(posedge clk);
        #1;
        observe(test_id);

        total_coin_value = cash_value;
        cancel = 1;
        repeat (1) @(posedge clk);
        #1;
        observe(test_id);

        cancel = 0;
        repeat (1) @(posedge clk);
        #1;
        observe(test_id);
    end
endtask

// Enter DISPENSE_AND_RETURN_STATE using online payment with insufficient
// cash, then remove online authorization and retain insufficient cash while
// the DUT is in the dispense state.
task online_payment_deasserted_during_dispense;
    input integer test_id;
    begin
        reset_dut(test_id);

        start = 1;
        repeat (1) @(posedge clk);
        #1;
        observe(test_id);

        start = 0;
        product_code = 3'b001;
        repeat (1) @(posedge clk);
        #1;
        observe(test_id);

        total_coin_value = 7'd0;
        online_payment = 1;
        repeat (1) @(posedge clk);
        #1;
        observe(test_id);

        online_payment = 0;
        total_coin_value = 7'd0;
        repeat (1) @(posedge clk);
        #1;
        observe(test_id);

        repeat (1) @(posedge clk);
        #1;
        observe(test_id);
    end
endtask

integer i;

initial begin
    rst = 0;
    product_code = 3'b000;
    online_payment = 0;
    start = 0;
    cancel = 0;
    total_coin_value = 7'd0;

    // Reset and idle cancel behavior
    reset_dut(1);
    cancel = 1;
    repeat (1) @(posedge clk);
    #1;
    observe(2);
    cancel = 0;

    // Start and unsupported product codes
    reset_dut(3);
    start = 1;
    repeat (1) @(posedge clk);
    #1;
    observe(3);
    start = 0;

    for (i = 5; i <= 7; i = i + 1) begin
        product_code = i;
        repeat (1) @(posedge clk);
        #1;
        observe(3);
        rst = 1;
        #1;
        observe(3);
        rst = 0;
        repeat (1) @(posedge clk);
        #1;
    end

    // All supported products, insufficient cash, and overpayment
    for (i = 0; i <= 4; i = i + 1)
        cash_transaction(i, 7'd60, 10 + i);

    // Exact payment boundary: Coke price
    reset_dut(20);
    start = 1;
    repeat (1) @(posedge clk);
    start = 0;
    product_code = 3'b010;
    repeat (1) @(posedge clk);
    total_coin_value = 7'd30;
    repeat (1) @(posedge clk);
    #1;
    observe(20);
    repeat (1) @(posedge clk);
    #1;
    observe(20);

    // Online payment with insufficient cash
    reset_dut(21);
    start = 1;
    repeat (1) @(posedge clk);
    start = 0;
    product_code = 3'b001;
    repeat (1) @(posedge clk);
    total_coin_value = 7'd0;
    online_payment = 1;
    repeat (1) @(posedge clk);
    #1;
    observe(21);
    repeat (1) @(posedge clk);
    #1;
    observe(21);
    online_payment = 0;

    // Cancellation with inserted cash
    reset_dut(22);
    start = 1;
    repeat (1) @(posedge clk);
    start = 0;
    product_code = 3'b000;
    repeat (1) @(posedge clk);
    total_coin_value = 7'd25;
    cancel = 1;
    repeat (1) @(posedge clk);
    #1;
    observe(22);
    cancel = 0;

    // Asynchronous reset during an active selected-product transaction
    reset_dut(23);
    start = 1;
    repeat (1) @(posedge clk);
    start = 0;
    product_code = 3'b011;
    repeat (1) @(posedge clk);
    #1;
    observe(23);
    rst = 1;
    #1;
    observe(23);
    rst = 0;
    repeat (1) @(posedge clk);
    #1;
    observe(23);

    // Additional cancellation coverage for notebook, Coke, and water.
    // These specifically target the previously uncovered FSM transitions
    // from the respective selection states back to IDLE.
    cancel_transaction(3'b001, 7'd12, 24);
    cancel_transaction(3'b010, 7'd18, 25);
    cancel_transaction(3'b100, 7'd9,  26);

    // Additional cancellation coverage for the already-covered paths,
    // preserving coverage of all product cancellation behaviors.
    cancel_transaction(3'b000, 7'd16, 27);
    cancel_transaction(3'b011, 7'd22, 28);

    // Target the missing else branch in DISPENSE_AND_RETURN_STATE:
    // online payment authorizes entry into dispense, then is removed while
    // cash remains insufficient.
    online_payment_deasserted_during_dispense(29);

    $display("===========End===========");

    $finish;
end

endmodule

