module testbench;

localparam [7:0]
    CMD_NOP           = 8'h00,
    CMD_TEST          = 8'h01,
    CMD_BAUD          = 8'h02,
    CMD_SPI_SPEED     = 8'h03,
    CMD_SPI_MODE      = 8'h04,
    CMD_SPI_CHIPSEL   = 8'h05,
    CMD_SPI_TRANSFER  = 8'h06,
    CMD_I2C_SPEED     = 8'h07,
    CMD_I2C_START     = 8'h08,
    CMD_I2C_STOP      = 8'h09,
    CMD_I2C_WRITE     = 8'h0A,
    CMD_I2C_READ      = 8'h0B,
    CMD_I2C_HOST_ACK  = 8'h0C,
    CMD_I2C_AGENT_ACK = 8'h0D;

// Inputs
reg clk, rst;
reg spi_transfer_ready, spi_transfer_done;
reg [7:0] spi_from_agent;
reg i2c_ready, i2c_agent_ack;
reg [7:0] i2c_from_agent;
reg [7:0] uart_rx_data;
