wire [7:0] spi_clk_div, spi_to_agent;
wire [15:0] i2c_clk_div;
wire i2c_start_req, i2c_stop_req, i2c_write_req, i2c_read_req;
wire i2c_host_ack;
wire [7:0] i2c_to_agent;
wire [15:0] uart_clk_div;
wire uart_tx_req;
wire [7:0] uart_tx_data, cmd_count, last_tx, last_rx;

integer tc, i, j;
reg [15:0] divider;
reg [7:0] operand;

dragonbridge_fsm uut (
    .clk(clk), .rst(rst),
    .spi_cs_n(spi_cs_n), .spi_clk_div(spi_clk_div),
    .spi_cpol(spi_cpol), .spi_cpha(spi_cpha),
    .spi_transfer_req(spi_transfer_req),
    .spi_transfer_ready(spi_transfer_ready),
    .spi_transfer_done(spi_transfer_done),
    .spi_to_agent(spi_to_agent), .spi_from_agent(spi_from_agent),
    .i2c_clk_div(i2c_clk_div),
    .i2c_start_req(i2c_start_req), .i2c_stop_req(i2c_stop_req),
    .i2c_write_req(i2c_write_req), .i2c_read_req(i2c_read_req),
    .i2c_ready(i2c_ready), .i2c_host_ack(i2c_host_ack),
    .i2c_agent_ack(i2c_agent_ack),
    .i2c_to_agent(i2c_to_agent), .i2c_from_agent(i2c_from_agent),
    .uart_clk_div(uart_clk_div), .uart_tx_req(uart_tx_req),
    .uart_tx_data(uart_tx_data), .uart_rx_data(uart_rx_data),
    .uart_tx_ready(uart_tx_ready), .uart_rx_ready(uart_rx_ready),
    .cmd_count(cmd_count), .last_tx(last_tx), .last_rx(last_rx)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [255:0] label;
    begin
        $display({
            "t=%0t case=%0d i=%0d j=%0d %0s ",
            "spi_cs_n=%b spi_clk_div=%02h spi_cpol=%b spi_cpha=%b ",
            "spi_transfer_req=%b spi_to_agent=%02h ",
            "i2c_clk_div=%04h i2c_start_req=%b i2c_stop_req=%b ",
            "i2c_write_req=%b i2c_read_req=%b i2c_host_ack=%b ",
            "i2c_to_agent=%02h uart_clk_div=%04h uart_tx_req=%b ",
            "uart_tx_data=%02h cmd_count=%02h last_tx=%02h last_rx=%02h"},
            $time, tc, i, j, label,
            spi_cs_n, spi_clk_div, spi_cpol, spi_cpha,
            spi_transfer_req, spi_to_agent,
            i2c_clk_div, i2c_start_req, i2c_stop_req,
            i2c_write_req, i2c_read_req, i2c_host_ack,
            i2c_to_agent, uart_clk_div, uart_tx_req,
            uart_tx_data, cmd_count, last_tx, last_rx);
    end
endtask

task cycles;
    input integer count;
    input [255:0] label;
    begin
        repeat (count) @(posedge clk);
        #1;
        observe(label);
    end
endtask

// Common reset sequence with no leading clock wait.
// Call at a falling edge so reset is asserted before the next rising edge.
task reset_dut_now;
    begin
        uart_rx_ready = 0;
        uart_rx_data = 0;
        uart_tx_ready = 0;
        spi_transfer_ready = 0;
        spi_transfer_done = 0;
        spi_from_agent = 0;
        i2c_ready = 0;
        i2c_agent_ack = 0;
        i2c_from_agent = 0;
        #2 rst = 1;
        #1 observe("asynchronous reset");
        cycles(2, "reset held");
        @(negedge clk);
        rst = 0;
        cycles(1, "reset released");
    end
endtask

// Preserve the timing of every original reset_dut invocation.
task reset_dut;
    begin
        @(negedge clk);
        reset_dut_now;
    end
endtask

task send_byte;
    input [7:0] data;
    begin
        @(negedge clk);
        uart_rx_data = data;
        uart_rx_ready = 1;
        cycles(1, "UART input sampled");
        @(negedge clk);
        uart_rx_ready = 0;
    end
endtask

task config_byte;
    input [7:0] command, data;
    begin
        send_byte(command);
        cycles(2, "waiting for operand");
        send_byte(data);
        cycles(1, "configuration retained");
    end
endtask

task config_word;
    input [7:0] command;
    input [15:0] data;
    begin
        send_byte(command);
        cycles(2, "waiting for high byte");
        send_byte(data[15:8]);
        cycles(2, "waiting for low byte");
        send_byte(data[7:0]);
        cycles(1, "divider retained");
    end
endtask

task finish_uart;
    begin
        cycles(2, "UART response interval");
        @(negedge clk);
        uart_tx_ready = 1;
        cycles(1, "UART ready sampled");
        @(negedge clk);
        uart_tx_ready = 0;
        cycles(1, "post UART completion");
    end
endtask

task echo_byte;
    input fast;
    input [7:0] data;
    begin
        @(negedge clk);
        uart_tx_ready = fast;
        send_byte(CMD_TEST);
        cycles(2, "echo operand wait");
        send_byte(data);
        if (!fast) begin
            send_byte(CMD_SPI_MODE);
            cycles(2, "echo stalled busy input");
        end
        finish_uart;
    end
endtask

task spi_byte;
    input fast;
    input [7:0] tx_byte, rx_byte;
    begin
        @(negedge clk);
        spi_transfer_ready = fast;
        spi_transfer_done = 0;
        spi_from_agent = ~rx_byte;
        uart_tx_ready = fast;
        send_byte(CMD_SPI_TRANSFER);
        cycles(2, "SPI operand wait");
        send_byte(tx_byte);
        if (!fast) begin
            cycles(2, "SPI acceptance stalled");
            send_byte(CMD_SPI_MODE);
        end
        @(negedge clk);
        spi_transfer_ready = 1;
        cycles(1, "SPI accepted");
        @(negedge clk);
        spi_transfer_ready = 0;
        if (!fast) begin
            cycles(2, "SPI completion stalled");
            send_byte(CMD_TEST);
            @(negedge clk);
        end
        spi_from_agent = rx_byte;
        spi_transfer_done = 1;
        cycles(1, "SPI completion sampled");
        @(negedge clk);
        spi_transfer_done = 0;
        spi_from_agent = ~rx_byte;
        finish_uart;
    end
endtask

task i2c_operation;
    input [7:0] command;
    input fast;
    input [7:0] tx_byte, rx_byte;
    begin
        @(negedge clk);
        i2c_ready = fast;
        i2c_from_agent = rx_byte;
        uart_tx_ready = fast;
        send_byte(command);
        if (command == CMD_I2C_WRITE) begin
            cycles(2, "I2C write operand wait");
            send_byte(tx_byte);
        end else begin
            cycles(1, "I2C first request edge");
        end
        if (!fast) begin
            cycles(2, "I2C request stalled");
            send_byte(CMD_SPI_MODE);
            @(negedge clk);
            i2c_ready = 1;
        end
        cycles(1, "I2C ready sampled");
        @(negedge clk);
        i2c_ready = 0;
        i2c_from_agent = ~rx_byte;
        if (command == CMD_I2C_READ)
            finish_uart;
        else
            cycles(2, "I2C operation finished");
    end
endtask

task agent_ack_response;
    input fast, ack_value;
    begin
        @(negedge clk);
        uart_tx_ready = fast;
        i2c_agent_ack = ack_value;
        send_byte(CMD_I2C_AGENT_ACK);
        cycles(1, "agent ACK first edge");
        if (!fast) begin
            cycles(2, "agent ACK stalled");
            @(negedge clk);
            i2c_agent_ack = ~ack_value;
            cycles(1, "agent ACK changed");
            @(negedge clk);
            i2c_agent_ack = ack_value;
            cycles(1, "agent ACK restored");
        end
        finish_uart;
    end
endtask

initial begin
    rst = 0;
    uart_rx_ready = 0;
    uart_rx_data = 0;
    uart_tx_ready = 0;
    spi_transfer_ready = 0;
    spi_transfer_done = 0;
    spi_from_agent = 0;
    i2c_ready = 0;
    i2c_agent_ack = 0;
    i2c_from_agent = 0;
    tc = 0;
    i = 0;
    j = 0;

    // Wait 100 ns for global reset to finish.
    #100;

    // 1: Reset, idle qualification, NOP and unsupported commands.
    tc = 1;
    reset_dut;
    @(negedge clk);
    uart_rx_data = CMD_TEST;
    uart_tx_ready = 1;
    spi_transfer_ready = 1;
    spi_transfer_done = 1;
    i2c_ready = 1;
    cycles(3, "idle without RX qualifier");
    send_byte(CMD_NOP);
    send_byte(8'h0E);
    send_byte(8'h7F);
    send_byte(8'hFF);
    cycles(2, "unsupported command idle");

    // 2: Sustained idle qualification and counter boundaries.
    tc = 2;
    reset_dut;
    @(negedge clk);
    uart_rx_data = CMD_NOP;
    uart_rx_ready = 1;
    cycles(254, "254 qualified idle edges");
    cycles(1, "255 qualified idle edges");
    cycles(1, "256 qualified idle edges");
    cycles(1, "257 qualified idle edges");
    @(negedge clk);
    uart_rx_ready = 0;
    cycles(2, "counter idle hold");

    // 3: Configuration boundaries, partial updates and persistence.
    tc = 3;
    reset_dut;
    for (i = 0; i < 4; i = i + 1) begin
        @(negedge clk);
        case (i)
            0: divider = 16'h0000;
            1: divider = 16'hFFFF;
            2: divider = 16'h12A5;
            3: divider = 16'hA512;
        endcase
        config_word(CMD_BAUD, divider);
        config_word(CMD_I2C_SPEED, divider);
        config_byte(CMD_SPI_SPEED, divider[7:0]);
        config_byte(CMD_SPI_MODE, i[7:0]);
        config_byte(CMD_SPI_MODE, 8'hFC | i[7:0]);
        case (i)
            0: operand = 8'h00;
            1: operand = 8'h01;
            2: operand = 8'hFE;
            3: operand = 8'hFF;
        endcase
        config_byte(CMD_SPI_CHIPSEL, operand);
        config_byte(CMD_I2C_HOST_ACK, operand);
    end
    send_byte(CMD_NOP);
    send_byte(8'hFF);
    cycles(3, "configuration idle persistence");

    // 4: Echo data boundaries and UART readiness.
    tc = 4;
    for (i = 0; i < 3; i = i + 1) begin
        @(negedge clk);
        reset_dut;
        case (i)
            0: operand = 8'h00;
            1: operand = 8'hFF;
            2: operand = 8'hA5;
        endcase
        echo_byte(i[0], operand);
        send_byte(CMD_NOP);
    end

    // 5: SPI acceptance, completion and UART response.
    tc = 5;
    for (i = 0; i < 2; i = i + 1) begin
        @(negedge clk);
        reset_dut;
        spi_byte(i[0], i[0] ? 8'hFF : 8'h00,
                       i[0] ? 8'h5A : 8'hA5);
        send_byte(CMD_NOP);
    end

    // 6: I2C start, stop, write and read readiness variants.
    tc = 6;
    for (i = 0; i < 4; i = i + 1) begin
        @(negedge clk);
        for (j = 0; j < 2; j = j + 1) begin
            @(negedge clk);
            reset_dut;
            i2c_operation(CMD_I2C_START + i, j[0],
                          j[0] ? 8'hFF : 8'h00,
                          j[0] ? 8'hFF : 8'h00);
            send_byte(CMD_NOP);
        end
    end

    // 7: Both agent ACK values, stalled and immediately ready.
    tc = 7;
    for (i = 0; i < 2; i = i + 1) begin
        @(negedge clk);
        for (j = 0; j < 2; j = j + 1) begin
            @(negedge clk);
            reset_dut;
            agent_ack_response(j[0], i[0]);
            send_byte(CMD_NOP);
        end
    end

    // 8: Mixed operations intentionally share persistent state.
    tc = 8;
    reset_dut;
    config_word(CMD_BAUD, 16'h2468);
    config_word(CMD_I2C_SPEED, 16'h1357);
    config_byte(CMD_SPI_SPEED, 8'h96);
    config_byte(CMD_SPI_MODE, 8'h03);
    config_byte(CMD_SPI_CHIPSEL, 8'h01);
    config_byte(CMD_I2C_HOST_ACK, 8'h01);
    spi_byte(0, 8'h3C, 8'hC3);
    i2c_operation(CMD_I2C_WRITE, 0, 8'hA6, 8'h00);
    i2c_operation(CMD_I2C_READ, 0, 8'h00, 8'h69);
    echo_byte(0, 8'h5A);
    agent_ack_response(0, 1);
    i2c_operation(CMD_I2C_START, 1, 8'h00, 8'h00);
    i2c_operation(CMD_I2C_STOP, 1, 8'h00, 8'h00);
    send_byte(CMD_NOP);
    send_byte(8'hFF);
    cycles(3, "mixed operation persistence");
    reset_dut;

    // 9: Abort pending operations asynchronously, then recover.
    // Preserve original cases 0..11 and add seven uncovered reset exits.
    tc = 9;
    for (i = 0; i < 19; i = i + 1) begin
        @(negedge clk);
        reset_dut;
        case (i)
            0, 1: begin
                if (i == 0)
                    send_byte(CMD_BAUD);
                else
                    send_byte(CMD_I2C_SPEED);
                send_byte(8'hD3);
            end

            2, 3, 4: begin
                send_byte(CMD_SPI_TRANSFER);
                send_byte(8'h96);
                if (i >= 3) begin
                    @(negedge clk);
                    spi_transfer_ready = 1;
                    cycles(1, "abort setup SPI acceptance");
                    @(negedge clk);
                    spi_transfer_ready = 0;
                end
                if (i == 4) begin
                    spi_from_agent = 8'h69;
                    spi_transfer_done = 1;
                    cycles(1, "abort setup SPI result");
                    @(negedge clk);
                    spi_transfer_done = 0;
                end
            end

            5, 6: begin
                if (i == 5)
                    send_byte(CMD_I2C_START);
                else
                    send_byte(CMD_I2C_STOP);
                cycles(1, "abort setup I2C condition");
            end

            7: begin
                send_byte(CMD_I2C_WRITE);
                send_byte(8'hC3);
            end

            8, 10: begin
                send_byte(CMD_I2C_READ);
                cycles(1, "abort setup I2C read");
                if (i == 10) begin
                    @(negedge clk);
                    i2c_from_agent = 8'hB6;
                    i2c_ready = 1;
                    cycles(1, "abort setup I2C result");
                    @(negedge clk);
                    i2c_ready = 0;
                end
            end

            9: begin
                send_byte(CMD_TEST);
                send_byte(8'h5A);
            end

            11: begin
                @(negedge clk);
                i2c_agent_ack = 1;
                send_byte(CMD_I2C_AGENT_ACK);
                cycles(1, "abort setup ACK response");
            end

            // New command-only aborts: do not send an operand or
            // allow another rising edge before asserting reset.
            12: send_byte(CMD_TEST);         // S_TEST -> S_IDLE
            13: send_byte(CMD_BAUD);         // S_BAUD_H -> S_IDLE
            14: send_byte(CMD_SPI_TRANSFER); // S_SPI_TRANSFER_GET -> S_IDLE
            15: send_byte(CMD_I2C_SPEED);    // S_I2C_SPEED_H -> S_IDLE
            16: send_byte(CMD_I2C_START);    // S_I2C_START_R -> S_IDLE
            17: send_byte(CMD_I2C_STOP);     // S_I2C_STOP_R -> S_IDLE
            18: send_byte(CMD_I2C_WRITE);    // S_I2C_WRITE_GET -> S_IDLE
        endcase

        if (i < 12) begin
            // Original abort timing is unchanged.
            cycles(2, "pending operation before reset");
            reset_dut;
        end else begin
            // send_byte has just returned at a falling edge.
            // reset_dut would wait one more falling edge, allowing
            // START_R/STOP_R to advance to their wait states.
            // Instead assert reset at falling edge + 2 ns and sample
            // at +3 ns, before the next rising edge at +5 ns.
            observe("command-only before reset");
            reset_dut_now;
        end

        // Preserve the original recovery transaction after every abort.
        echo_byte(1, 8'hA5);
        send_byte(CMD_NOP);
    end

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam CLOCK_FACTOR = 8;
localparam COUNT_WIDTH = 8;
localparam MAX_TRAIN_UNITS = (1 << (COUNT_WIDTH-1)) - 1;
localparam OBS_CYCLES = 3 * (1 << COUNT_WIDTH);

// Fixed timing for the existing reset-interruption training sequence.
localparam RESET_TRAIN_UNITS = 8;
localparam RESET_CELL_CYCLES =
    CLOCK_FACTOR * (RESET_TRAIN_UNITS + 1);
localparam DECISION_LAST_BIT_CYCLES =
    RESET_CELL_CYCLES / 2 + 2;

// Inputs
reg clk;
reg reset;
reg serial_dat;

// Outputs
wire auto_baud_locked;
wire baud_clk;

integer case_id;
integer bit_index;
integer stage;
integer timing_case;
integer train_units;
reg [7:0] interrupt_character;

auto_baud_with_tracking #(
    .CLOCK_FACTOR_PP(CLOCK_FACTOR),
    .LOG2_MAX_COUNT_PP(COUNT_WIDTH)
) uut (
    .clk_i(clk),
    .reset_i(reset),
    .serial_dat_i(serial_dat),
    .auto_baud_locked_o(auto_baud_locked),
    .baud_clk_o(baud_clk)
);

initial clk = 0;
always #5 clk = ~clk;

task show_outputs;
begin
    $display("t=%0t case=%0d reset=%b serial=%b auto_baud_locked_o=%b baud_clk_o=%b",
             $time, case_id, reset, serial_dat,
             auto_baud_locked, baud_clk);
end
endtask

task hold_cycles;
    input integer cycles;
begin
    repeat (cycles) @(posedge clk);
    #1;
    show_outputs;
end
endtask

task drive_level;
    input level;
    input integer cycles;
begin
    @(negedge clk);
    serial_dat = level;
    hold_cycles(cycles);
end
endtask

task reset_case;
begin
    @(negedge clk);
    serial_dat = 1'b1;
    #2 reset = 1'b1;
    #1;
    show_outputs;
    hold_cycles(2);
    @(negedge clk);
    reset = 1'b0;
    hold_cycles(2);
end
endtask

task observe_cycles;
    input integer cycles;
    integer sample_index;
begin
    for (sample_index = 0; sample_index < cycles;
         sample_index = sample_index + 1) begin
        @(posedge clk);
        #1;
        show_outputs;
    end
end
endtask

// Training spans use phase-sized units; verification cells include
// the interval counter's terminal-count clock.
task send_character;
    input integer units;
    input [7:0] character;
    integer k;
    integer cell_cycles;
begin
    cell_cycles = CLOCK_FACTOR * (units + 1);
    drive_level(1'b0, CLOCK_FACTOR * units);
    drive_level(1'b1, CLOCK_FACTOR * units);
    for (k = 0; k < 8; k = k + 1) begin
        @(negedge clk);
        serial_dat = character[k];
        hold_cycles(cell_cycles);
    end
    drive_level(1'b1, 2 * cell_cycles);
end
endtask

initial begin
    // Initialize inputs and allow 100 ns for global reset.
    reset = 1'b1;
    serial_dat = 1'b1;
    interrupt_character = 8'h86;
    case_id = 0;
    #100;
    show_outputs;
    @(negedge clk);
    reset = 1'b0;
    hold_cycles(20);

    // Preserve the original three interruption cases and add:
    // stage 3: reset in measurement capture;
    // stage 4: reset in the successful verification decision;
    // stage 5: reset in the mismatching verification decision.
    for (stage = 0; stage < 6; stage = stage + 1) begin
        @(negedge clk);
        case_id = 10 + stage;
        reset_case;

        drive_level(1'b0, RESET_TRAIN_UNITS * CLOCK_FACTOR);
        if (stage >= 1)
            drive_level(1'b1, RESET_TRAIN_UNITS * CLOCK_FACTOR);

        if (stage == 2)
            drive_level(1'b0, CLOCK_FACTOR * 9);

        if (stage == 3) begin
            // The first falling-input sampling edge enters
            // m1_measure_4. reset_case asserts asynchronous reset
            // before the next rising edge can enter verification.
            drive_level(1'b0, 1);
        end

        if (stage >= 4) begin
            // Keep bit 0 low so the falling training transition
            // occurs at the same point in both decision cases.
            // Stage 5 changes only the terminal verification bit.
            if (stage == 4)
                interrupt_character = 8'h86;
            else
                interrupt_character = 8'h06;

            for (bit_index = 0; bit_index < 8;
                 bit_index = bit_index + 1) begin
                @(negedge clk);
                serial_dat = interrupt_character[bit_index];

                if (bit_index < 7)
                    hold_cycles(RESET_CELL_CYCLES);
                else
                    // Two entry clocks plus half a verification
                    // cell place the final sample in m1_verify_1.
                    // Reset follows before its next rising edge.
                    hold_cycles(DECISION_LAST_BIT_CYCLES);
            end
        end

        reset_case;
        send_character(8, 8'h86);
        observe_cycles(32);
    end

    // Initial-low qualification failure.
    case_id = 20;
    reset_case;
    drive_level(1'b0, 1);
    drive_level(1'b1, 3 * CLOCK_FACTOR);
    observe_cycles(16);

    // High qualification failure before its midpoint.
    case_id = 21;
    reset_case;
    drive_level(1'b0, CLOCK_FACTOR);
    drive_level(1'b1, 1);
    drive_level(1'b0, CLOCK_FACTOR);
    drive_level(1'b1, 3 * CLOCK_FACTOR);
    observe_cycles(16);

    // Minimum, representative, and near-limit valid measurements.
    for (timing_case = 0; timing_case < 3;
         timing_case = timing_case + 1) begin
        @(negedge clk);
        case_id = 30 + timing_case;
        case (timing_case)
            0: train_units = 1;
            1: train_units = 8;
            2: train_units = MAX_TRAIN_UNITS;
        endcase
        reset_case;
        send_character(train_units, 8'h86);
        observe_cycles(OBS_CYCLES);
    end

    // Every template position, including the terminal bit, mismatches.
    for (bit_index = 0; bit_index < 8;
         bit_index = bit_index + 1) begin
        @(negedge clk);
        case_id = 40 + bit_index;
        reset_case;
        send_character(8, 8'h86 ^ (8'h01 << bit_index));
        observe_cycles(32);
        send_character(8, 8'h86);
        observe_cycles(32);
    end

    // Lock acquisition, slower tracking, invalid update, faster tracking.
    case_id = 60;
    reset_case;
    send_character(8, 8'h86);
    observe_cycles(OBS_CYCLES);

    case_id = 61;
    send_character(16, 8'h86);
    observe_cycles(OBS_CYCLES);

    case_id = 62;
    send_character(4, 8'h87);
    observe_cycles(OBS_CYCLES);

    case_id = 63;
    send_character(4, 8'h86);
    observe_cycles(OBS_CYCLES);

    // Reset an established lock, then acquire a new interval.
    case_id = 70;
    reset_case;
    observe_cycles(32);
    send_character(2, 8'h86);
    observe_cycles(32);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps

module testbench;

reg host_clk;
reg host_rst;
reg host_en;
reg host_rnw;
reg [31:0] host_addr;
reg [31:0] host_datai;
reg [3:0]  host_be;

reg qdr_clk;
reg qdr_rst;
reg qdr_ack;
reg [35:0] qdr_q;

wire [31:0] host_datao;
wire        host_ack;
wire        qdr_req;
wire [31:0] qdr_addr;
wire        qdr_r;
wire        qdr_w;
wire [35:0] qdr_d;
wire [3:0]  qdr_be;

async_qdr_interface #(
    .QDR_LATENCY(10)
) uut (
    .host_clk   (host_clk),
    .host_rst   (host_rst),
    .host_en    (host_en),
    .host_rnw   (host_rnw),
    .host_addr  (host_addr),
    .host_datai (host_datai),
    .host_be    (host_be),
    .host_datao (host_datao),
    .host_ack    (host_ack),
    .qdr_clk    (qdr_clk),
    .qdr_rst    (qdr_rst),
    .qdr_ack    (qdr_ack),
    .qdr_q      (qdr_q),
    .qdr_req    (qdr_req),
    .qdr_r      (qdr_r),
    .qdr_w      (qdr_w),
    .qdr_d      (qdr_d),
    .qdr_be     (qdr_be)
);

initial host_clk = 1'b0;
always #5 host_clk = ~host_clk;

initial qdr_clk = 1'b0;
always #7 qdr_clk = ~qdr_clk;

task reset_dut;
begin
    host_en    = 1'b0;
    host_rnw   = 1'b0;
    host_addr  = 32'b0;
    host_datai = 32'b0;
    host_be    = 4'b0;
    qdr_ack    = 1'b0;
    qdr_q      = 36'b0;

    host_rst   = 1'b1;
    qdr_rst    = 1'b1;

    repeat (4) @(posedge host_clk);
    repeat (4) @(posedge qdr_clk);

    host_rst   = 1'b0;
    qdr_rst    = 1'b0;

    repeat (3) @(posedge host_clk);
    repeat (3) @(posedge qdr_clk);
end
endtask

task observe_outputs;
    input [127:0] tag;
    integer k;
begin
    repeat (20) begin
        @(posedge host_clk);
        $display("%s host_datao=%h host_ack=%b qdr_req=%b qdr_addr=%h qdr_r=%b qdr_w=%b qdr_d=%h qdr_be=%h",
                 tag, host_datao, host_ack, qdr_req, qdr_addr,
                 qdr_r, qdr_w, qdr_d, qdr_be);
    end
end
endtask

task observe_qdr_outputs;
    input [127:0] tag;
    integer k;
begin
    repeat (14) begin
        @(posedge qdr_clk);
        $display("%s host_datao=%h host_ack=%b qdr_req=%b qdr_addr=%h qdr_r=%b qdr_w=%b qdr_d=%h qdr_be=%h",
                 tag, host_datao, host_ack, qdr_req, qdr_addr,
                 qdr_r, qdr_w, qdr_d, qdr_be);
    end
end
endtask

task launch_host_transaction;
    input        rnw;
    input [31:0] addr;
    input [31:0] data;
    input [3:0]  be;
begin
    host_rnw   = rnw;
    host_addr  = addr;
    host_datai = data;
    host_be    = be;
    host_en    = 1'b1;

    @(posedge host_clk);
    host_en    = 1'b0;
end
endtask

task do_write;
    input [31:0] addr;
    input [31:0] data;
    input [3:0]  be;
    input [127:0] tag;
begin
    launch_host_transaction(1'b0, addr, data, be);

    // Allow the request synchronizer and QDR responder to reach WAIT.
    repeat (5) @(posedge qdr_clk);

    // Explicitly exercise WAIT with qdr_ack low.
    repeat (2) @(posedge qdr_clk);

    qdr_ack = 1'b1;
    @(posedge qdr_clk);
    qdr_ack = 1'b0;

    // Observe the acknowledgement release and response handshake.
    observe_qdr_outputs(tag);
    observe_outputs(tag);
end
endtask

task do_read;
    input [31:0] addr;
    input [127:0] tag;
    input second_word;
begin
    launch_host_transaction(
        1'b1,
        addr,
        32'b0,
        4'b1111
    );

    // Keep the first QDR word valid before request acceptance and
    // throughout the configured read latency.
    if (second_word) begin
        qdr_q = {1'b0,8'h11,1'b0,8'h22,1'b0,8'h33,1'b0,8'h44};
    end else begin
        qdr_q = {1'b0,8'h00,1'b0,8'hFF,1'b0,8'h5A,1'b0,8'hA5};
    end

    // Allow the request to enter WAIT and explicitly exercise qdr_ack=0.
    repeat (5) @(posedge qdr_clk);
    repeat (2) @(posedge qdr_clk);

    qdr_ack = 1'b1;
    @(posedge qdr_clk);
    qdr_ack = 1'b0;

    if (second_word) begin
        // The first word is used to enter FINAL. Change the QDR data
        // before the following capture cycle for the second word.
        repeat (9) @(posedge qdr_clk);
        qdr_q = {1'b0,8'hAA,1'b0,8'hBB,1'b0,8'hCC,1'b0,8'hDD};
        repeat (4) @(posedge qdr_clk);
    end else begin
        // Hold the first word through the complete validity delay.
        repeat (13) @(posedge qdr_clk);
    end

    observe_qdr_outputs(tag);
    observe_outputs(tag);
end
endtask

task do_mid_wait_qdr_reset;
    input [31:0] addr;
    input [31:0] data;
    input [3:0]  be;
    input [127:0] tag;
begin
    launch_host_transaction(1'b0, addr, data, be);

    // The request has crossed into the QDR domain and the response
    // engine is in WAIT. Keep qdr_ack low before applying reset.
    repeat (5) @(posedge qdr_clk);
    repeat (2) @(posedge qdr_clk);

    // Synchronously reset the QDR side while WAIT is active.
    // This exercises the legal WAIT -> IDLE reset transition.
    qdr_rst = 1'b1;
    repeat (2) @(posedge qdr_clk);
    qdr_rst = 1'b0;

    // The host request remains asserted by the four-phase handshake.
    // Allow the QDR-side synchronizer and responder to accept it again.
    repeat (5) @(posedge qdr_clk);
    repeat (2) @(posedge qdr_clk);

    qdr_ack = 1'b1;
    @(posedge qdr_clk);
    qdr_ack = 1'b0;

    observe_qdr_outputs(tag);
    observe_outputs(tag);
end
endtask

initial begin
    host_rst   = 1'b0;
    qdr_rst    = 1'b0;
    host_en    = 1'b0;
    host_rnw   = 1'b0;
    host_addr  = 32'b0;
    host_datai = 32'b0;
    host_be    = 4'b0;
    qdr_ack    = 1'b0;
    qdr_q      = 36'b0;

    reset_dut();

    $display("RESET      host_datao=%h host_ack=%b qdr_req=%b qdr_addr=%h qdr_r=%b qdr_w=%b qdr_d=%h qdr_be=%h",
             host_datao, host_ack, qdr_req, qdr_addr,
             qdr_r, qdr_w, qdr_d, qdr_be);

    // Existing first-word write case.
    reset_dut();
    do_write(32'h0000_1000,
             32'h0000_0000,
             4'b1111,
             "WRITE_FIRST ");

    // Existing second-word write case.
    reset_dut();
    do_write(32'h0000_1004,
             32'hFFFF_FFFF,
             4'b0101,
             "WRITE_SECOND");

    // Additional first-word write with mixed data and byte enables.
    reset_dut();
    do_write(32'h1234_5000,
             32'hA5C3_7E19,
             4'b1010,
             "WRITE_MIXED ");

    // Additional second-word write with all byte enables disabled.
    reset_dut();
    do_write(32'h1234_5004,
             32'h1357_9BDF,
             4'b0000,
             "WRITE_SECOND0");

    // Directed mid-transaction QDR reset while the response engine is
    // waiting for qdr_ack. The request is then re-accepted and completed.
    reset_dut();
    do_mid_wait_qdr_reset(32'h2468_A000,
                          32'hDEAD_BEEF,
                          4'b1100,
                          "WRITE_QRESET");

    // Existing first-word read case.
    reset_dut();
    do_read(32'h0000_2000,
            "READ_FIRST  ",
            1'b0);

    // Existing second-word read case.
    reset_dut();
    do_read(32'h0000_2004,
            "READ_SECOND ",
            1'b1);

    // Additional first-word read with a different pair address.
    reset_dut();
    do_read(32'h89AB_C100,
            "READ_FIRST2 ",
            1'b0);

    // Additional second-word read with a different pair address.
    reset_dut();
    do_read(32'h89AB_C104,
            "READ_SECOND2",
            1'b1);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

// Parameters
localparam integer DRAIN = 11;

// Inputs
reg clk;
reg rst;
reg i_vl;
reg [7:0] i_x, i_px;
reg i_s, i_q;
reg [3:0] i_cn;

// Outputs
wire o_vl;
wire [4:0] o_zc;
wire [8:0] o_bv;
wire [3:0] o_bc;

// Instantiate the Unit Under Test (UUT)
run uut (
    .rst(rst), .clk(clk),
    .i_vl(i_vl), .i_x(i_x), .i_px(i_px),
    .i_s(i_s), .i_q(i_q), .i_cn(i_cn),
    .o_vl(o_vl), .o_zc(o_zc), .o_bv(o_bv), .o_bc(o_bc)
);

integer test_id, cycle;
integer q, s, n, c, x, mode, depth;
integer difference [0:14];

// clk toggle generate
initial clk = 0;
always #5 clk = ~clk;

// Drive away from the sampling edge; observe after register updates.
task tick;
    input reset_value, valid_value;
    input [7:0] sample_value, prediction_value;
    input direction_value, context_value;
    input [3:0] limit_value;
    begin
        @(negedge clk);
        rst  = reset_value;
        i_vl = valid_value;
        i_x  = sample_value;
        i_px = prediction_value;
        i_s  = direction_value;
        i_q  = context_value;
        i_cn = limit_value;
        @(posedge clk);
        #1;
        cycle = cycle + 1;
        $display("test=%0d cycle=%0d rst=%b i_vl=%b x=%0d px=%0d s=%b q=%b cn=%0d | o_vl=%b o_zc=%0d o_bv=%0d o_bc=%0d",
                 test_id, cycle, rst, i_vl, i_x, i_px, i_s, i_q,
                 i_cn, o_vl, o_zc, o_bv, o_bc);
    end
endtask

task idle;
    input integer clocks;
    integer j;
    begin
        for (j = 0; j < clocks; j = j + 1) begin
            tick(0, 0, 0, 0, 0, 0, 0);
            #1;
        end
    end
endtask

task reset_dut;
    begin
        tick(1, 0, 0, 0, 0, 0, 0);
        tick(1, 0, 0, 0, 0, 0, 0);
        tick(0, 0, 0, 0, 0, 0, 0);
    end
endtask

// Construct input operands only; no output values are calculated.
task send_difference;
    input integer delta;
    input direction_value, context_value;
    input [3:0] limit_value;
    begin
        if (delta < 0)
            tick(0, 1, 0, -delta, direction_value,
                 context_value, limit_value);
        else
            tick(0, 1, delta, 0, direction_value,
                 context_value, limit_value);
    end
endtask

initial begin
    // Initialize Inputs
    rst = 1;
    i_vl = 0;
    i_x = 0;
    i_px = 0;
    i_s = 0;
    i_q = 0;
    i_cn = 0;
    test_id = 0;
    cycle = 0;

    difference[0]  = -255; difference[1]  = -254;
    difference[2]  = -129; difference[3]  = -128;
    difference[4]  = -127; difference[5]  = -126;
    difference[6]  = -1;   difference[7]  = 0;
    difference[8]  = 1;    difference[9]  = 126;
    difference[10] = 127;  difference[11] = 128;
    difference[12] = 129;  difference[13] = 254;
    difference[14] = 255;

    // Wait 100 ns for global reset to finish
    #100;

    // Test 1: startup reset and valid input during reset.
    test_id = 1;
    tick(1, 1, 255, 0, 0, 1, 15);
    tick(1, 1, 0, 255, 1, 0, 0);
    idle(DRAIN);

    // Test 2: independent normalization and mapping boundaries.
    test_id = 2;
    for (q = 0; q < 2; q = q + 1) begin
        #1;
        for (s = 0; s < 2; s = s + 1) begin
            #1;
            for (n = 0; n < 15; n = n + 1) begin
                reset_dut;
                send_difference(difference[n], s, q, 0);
                idle(DRAIN);
                #1;
            end
        end
    end

    // Test 3: all limits, with independent ordinary/escape sweeps.
    test_id = 3;
    for (q = 0; q < 2; q = q + 1) begin
        #1;
        for (c = 0; c < 16; c = c + 1) begin
            #1;
            for (x = 0; x < 50; x = x + 1) begin
                reset_dut;
                tick(0, 1, x, 0, 0, q, c);
                idle(DRAIN);
                #1;
            end
        end
    end

    // Test 4: small-k training, sign balance, and repeated rescaling.
    test_id = 4;
    for (q = 0; q < 2; q = q + 1) begin
        reset_dut;
        #1;
        for (n = 0; n < 16; n = n + 1) begin
            tick(0, 1, q, 0, 0, q, 0);
            idle(DRAIN);
            #1;
        end
        for (n = 0; n < 96; n = n + 1) begin
            tick(0, 1, 0, 1, 0, q, 15);
            idle(DRAIN);
            #1;
        end
        for (n = 0; n < 96; n = n + 1) begin
            tick(0, 1, 1, 0, 0, q, 0);
            idle(DRAIN);
            #1;
        end
        tick(0, 1, 128, 128, 0, q, 15);
        idle(DRAIN);
    end

    // Test 5: large-error adaptation and context-one zero mapping.
    test_id = 5;
    for (mode = 0; mode < 3; mode = mode + 1) begin
        reset_dut;
        #1;
        for (n = 0; n < 96; n = n + 1) begin
            if (mode == 2)
                tick(0, 1, 0, 0, 0, 1, n % 16);
            else
                tick(0, 1, 128, 0, n % 2, mode, n % 16);
            idle(DRAIN);
            #1;
        end
    end

    // Test 6: back-to-back traffic, interleaving, and valid bubbles.
    test_id = 6;
    for (mode = 0; mode < 3; mode = mode + 1) begin
        reset_dut;
        #1;
        for (n = 0; n < 160; n = n + 1) begin
            if (mode == 2)
                q = n % 2;
            else
                q = mode;
            send_difference(difference[n % 15], n % 2,
                            q, n % 16);
            #1;
        end
        idle(DRAIN);
        for (n = 0; n < 32; n = n + 1) begin
            tick(0, (n % 3 != 1), n * 7, 255 - n * 3,
                 n % 2, n % 2, n % 16);
            #1;
        end
        idle(DRAIN);
    end

    // Test 7: cancel transactions at every pipeline position.
    test_id = 7;
    for (depth = 0; depth < 11; depth = depth + 1) begin
        reset_dut;
        tick(0, 1, 255, 0, 0, 0, 15);
        idle(depth);
        tick(1, 1, 0, 255, 1, 1, 0);
        idle(DRAIN);
        tick(0, 1, 1, 0, 0, 0, 0);
        idle(DRAIN);
        tick(0, 1, 0, 0, 0, 1, 15);
        idle(DRAIN);
        #1;
    end

    $display("===========End=========== o_vl=%b o_zc=%0d o_bv=%0d o_bc=%0d",
             o_vl, o_zc, o_bv, o_bc);
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

reg        clk;
reg        WE;
reg [31:0] ADDR;
reg [31:0] DIN;
reg        FOUND;
reg        RREQ;
reg        RST;
reg        MRDY;
reg [31:0] CDOUT;
reg [2:0]  LIM;
reg        SIGNED;

wire [31:0] MADDR;
wire        MWE;
wire [35:0] CDIN;
wire        CWE;
wire [31:0] DOUT;
wire        RDY;
wire [7:0]  MD;

reg        md_drive_en;
reg [7:0]  md_drive;

assign MD = md_drive_en ? md_drive : 8'bz;

CacheController uut (
    .WE     (WE),
    .ADDR   (ADDR),
    .DIN    (DIN),
    .FOUND  (FOUND),
    .MD     (MD),
    .RREQ   (RREQ),
    .RST    (RST),
    .CLK    (clk),
    .MADDR  (MADDR),
    .MWE    (MWE),
    .MRDY   (MRDY),
    .CDOUT  (CDOUT),
    .CDIN   (CDIN),
    .CWE    (CWE),
    .DOUT   (DOUT),
    .RDY    (RDY),
    .LIM    (LIM),
    .SIGNED (SIGNED)
);

initial clk = 1'b0;
always #5 clk = ~clk;

task reset_dut;
begin
    WE          = 1'b0;
    ADDR        = 32'b0;
    DIN         = 32'b0;
    FOUND       = 1'b0;
    RREQ        = 1'b0;
    MRDY        = 1'b0;
    CDOUT       = 32'b0;
    LIM         = 3'b0;
    SIGNED      = 1'b0;
    md_drive_en = 1'b0;
    md_drive    = 8'b0;

    RST = 1'b1;
    #1;
    @(posedge clk);
    #1;
    RST = 1'b0;

    // Execute START and enter WAIT.
    @(posedge clk);
    #1;
end
endtask

task observe;
    input integer case_id;
begin
    #1;
    $display("CASE %0d: MADDR=%h MWE=%b CDIN=%h CWE=%b DOUT=%h RDY=%b MD=%h",
             case_id, MADDR, MWE, CDIN, CWE, DOUT, RDY, MD);
end
endtask

task idle_wait_case;
    input integer case_id;
begin
    reset_dut;

    WE   = 1'b0;
    RREQ = 1'b0;
    MRDY = 1'b0;

    #1;
    @(posedge clk);
    #1;

    observe(case_id);
end
endtask

task write_case;
    input integer case_id;
    input [31:0] address;
    input [31:0] data;
    input [2:0]  length;
    input integer byte_count;
    integer i;
begin
    reset_dut;

    ADDR = address;
    DIN  = data;
    LIM  = length;
    WE   = 1'b1;
    RREQ = 1'b1;

    #1;
    @(posedge clk);
    #1;

    // WE has priority over RREQ.
    WE   = 1'b0;
    RREQ = 1'b0;

    // Exercise the wait path in WAIT_MWRITE.
    MRDY = 1'b0;
    #1;
    @(posedge clk);
    #1;

    for (i = 0; i < byte_count; i = i + 1) begin
        MRDY = 1'b1;
        #1;
        @(posedge clk);
        #1;
        MRDY = 1'b0;
    end

    repeat (2) @(posedge clk);
    observe(case_id);
end
endtask

task read_hit_case;
    input integer case_id;
    input [31:0] address;
    input [31:0] cache_data;
    input [2:0]  length;
    input        sg;
begin
    reset_dut;

    ADDR   = address;
    CDOUT  = cache_data;
    LIM    = length;
    SIGNED = sg;
    FOUND  = 1'b1;
    RREQ   = 1'b1;

    #1;
    @(posedge clk);
    #1;

    // Keep FOUND asserted through CHECK_CACHE.
    RREQ = 1'b0;
    @(posedge clk);
    #1;
    FOUND = 1'b0;

    repeat (2) @(posedge clk);
    observe(case_id);
end
endtask

task read_miss_case;
    input integer case_id;
    input [31:0] address;
    input [2:0]  length;
    input        sg;
    input [7:0]  byte0;
    input [7:0]  byte1;
    input [7:0]  byte2;
    input [7:0]  byte3;
    input integer byte_count;
    integer i;
begin
    reset_dut;

    ADDR   = address;
    LIM    = length;
    SIGNED = sg;
    FOUND  = 1'b0;
    RREQ   = 1'b1;

    #1;
    @(posedge clk);
    #1;
    RREQ = 1'b0;

    // CHECK_CACHE -> WAIT_MREAD, followed by one MRDY-low cycle.
    MRDY = 1'b0;
    repeat (2) @(posedge clk);

    for (i = 0; i < byte_count; i = i + 1) begin
        case (i)
            0: md_drive = byte0;
            1: md_drive = byte1;
            2: md_drive = byte2;
            3: md_drive = byte3;
            default: md_drive = 8'h00;
        endcase

        md_drive_en = 1'b1;
        MRDY        = 1'b1;

        // WAIT_MREAD observes MRDY and enters MREAD_BUF.
        #1;
        @(posedge clk);
        #1;

        MRDY = 1'b0;

        // MREAD_BUF samples MD on the following edge.
        @(posedge clk);
        #1;
    end

    md_drive_en = 1'b0;
    MRDY        = 1'b0;

    repeat (2) @(posedge clk);
    observe(case_id);
end
endtask

// Assert reset while the controller is in WAIT_MREAD.
// This targets the synchronous reset transition WAIT_MREAD -> START.
task reset_during_wait_mread_case;
    input integer case_id;
begin
    reset_dut;

    ADDR  = 32'h0000_4000;
    LIM   = 3'd3;
    RREQ  = 1'b1;
    FOUND = 1'b0;

    #1;
    @(posedge clk);
    #1;
    RREQ = 1'b0;

    // CHECK_CACHE -> WAIT_MREAD.
    MRDY = 1'b0;
    @(posedge clk);
    #1;

    // Remain in WAIT_MREAD with MRDY low.
    @(posedge clk);
    #1;

    // Synchronous reset from WAIT_MREAD.
    RST = 1'b1;
    @(posedge clk);
    #1;
    RST = 1'b0;

    // Execute START after reset.
    @(posedge clk);
    #1;

    observe(case_id);
end
endtask

// Assert reset after WAIT_MREAD has advanced into MREAD_BUF.
// This targets the synchronous reset transition MREAD_BUF -> START.
task reset_during_mread_buf_case;
    input integer case_id;
begin
    reset_dut;

    ADDR  = 32'h0000_4100;
    LIM   = 3'd3;
    RREQ  = 1'b1;
    FOUND = 1'b0;

    #1;
    @(posedge clk);
    #1;
    RREQ = 1'b0;

    // CHECK_CACHE -> WAIT_MREAD.
    MRDY = 1'b0;
    @(posedge clk);
    #1;

    // WAIT_MREAD -> MREAD_BUF.
    md_drive    = 8'hA5;
    md_drive_en = 1'b1;
    MRDY        = 1'b1;
    @(posedge clk);
    #1;

    // Reset while in MREAD_BUF, before the capture edge.
    MRDY = 1'b0;
    RST  = 1'b1;
    @(posedge clk);
    #1;
    RST = 1'b0;
    md_drive_en = 1'b0;

    // Execute START after reset.
    @(posedge clk);
    #1;

    observe(case_id);
end
endtask

initial begin
    reset_dut;
    observe(0);

    idle_wait_case(1);

    // Invalid I/O address; simultaneous write/read also checks WE priority.
    reset_dut;
    ADDR = 32'h8000_0100;
    DIN  = 32'h1122_3344;
    LIM  = 3;
    WE   = 1'b1;
    RREQ = 1'b1;

    #1;
    @(posedge clk);
    #1;

    WE   = 1'b0;
    RREQ = 1'b0;
    repeat (2) @(posedge clk);
    observe(2);

    // One-, two-, and four-byte writes.
    write_case(3, 32'h0000_1000, 32'hA1B2C3D4, 0, 1);
    write_case(4, 32'h0000_1100, 32'hA1B2C3D4, 1, 2);
    write_case(5, 32'h0000_1200, 32'hA1B2C3D4, 3, 4);

    // Exercise the default LIM mask and a three-byte transfer.
    write_case(12, 32'h0000_1300, 32'h10203040, 2, 3);

    // Cache hit.
    read_hit_case(6, 32'h0000_2000, 32'h55667788, 3, 0);

    // Byte read miss: unsigned and signed.
    read_miss_case(7, 32'h0000_3000, 0, 0,
                   8'h7E, 8'h00, 8'h00, 8'h00, 1);

    read_miss_case(8, 32'h0000_3010, 0, 1,
                   8'h80, 8'h00, 8'h00, 8'h00, 1);

    // Halfword read miss: unsigned and signed.
    read_miss_case(9, 32'h0000_3100, 1, 0,
                   8'h34, 8'h12, 8'h00, 8'h00, 2);

    read_miss_case(10, 32'h0000_3110, 1, 1,
                   8'h00, 8'h80, 8'h00, 8'h00, 2);

    // Word read miss.
    read_miss_case(11, 32'h0000_3200, 3, 0,
                   8'h44, 8'h33, 8'h22, 8'h11, 4);

    // Reset-abort coverage for the two previously uncovered FSM transitions.
    reset_during_wait_mread_case(13);
    reset_during_mread_buf_case(14);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

// Inputs
reg clk;
reg [31:0] instruction;
reg branch_taken;

// Outputs
wire [3:0] alu_control;
wire [2:0] store_select, data_mem_select, imm_select, branch_select;
wire reg_write_ctrl, data_mem_write_ctrl;
wire [2:0] write_data_source;
wire A_source_select, B_source_select;
wire [1:0] pc_source_select;
wire [4:0] destination_reg, source_reg_1, source_reg_2;
wire halt_signal;

integer op, fields;

control_unit uut (
    .instruction(instruction),
    .branch_taken(branch_taken),
    .alu_control(alu_control),
    .store_select(store_select),
    .data_mem_select(data_mem_select),
    .imm_select(imm_select),
    .branch_select(branch_select),
    .reg_write_ctrl(reg_write_ctrl),
    .data_mem_write_ctrl(data_mem_write_ctrl),
    .write_data_source(write_data_source),
    .A_source_select(A_source_select),
    .B_source_select(B_source_select),
    .pc_source_select(pc_source_select),
    .destination_reg(destination_reg),
    .source_reg_1(source_reg_1),
    .source_reg_2(source_reg_2),
    .halt_signal(halt_signal)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [8*12-1:0] test_name;
    begin
        $display(
            "%0s instruction=%08h branch_taken=%b alu_control=%b store_select=%b data_mem_select=%b imm_select=%b branch_select=%b reg_write_ctrl=%b data_mem_write_ctrl=%b write_data_source=%b A_source_select=%b B_source_select=%b pc_source_select=%b destination_reg=%b source_reg_1=%b source_reg_2=%b halt_signal=%b",
            test_name, instruction, branch_taken,
            alu_control, store_select, data_mem_select,
            imm_select, branch_select, reg_write_ctrl,
            data_mem_write_ctrl, write_data_source,
            A_source_select, B_source_select, pc_source_select,
            destination_reg, source_reg_1, source_reg_2, halt_signal
        );
    end
endtask

task sweep_opcode;
    input [6:0] opcode_value;
    integer f;
    begin
        for (f = 0; f < 16; f = f + 1) begin
            // f[3] drives bit 30; f[2:0] drives funct3.
            instruction = {
                1'b0, f[3], 5'b00000,
                5'd26, 5'd17, f[2:0], 5'd5, opcode_value
            };
            branch_taken = 0;
            #1;
            observe("decode");

            branch_taken = 1;
            #1;
            observe("decode");
        end
    end
endtask

initial begin
    instruction = 32'b0;
    branch_taken = 0;

    // Initial settling interval; DUT has no reset port.
    #100;
    observe("initialize");

    // Test Case 1: All opcodes, function selections, and PC conditions.
    for (op = 0; op < 128; op = op + 1) begin
        #1;
        sweep_opcode(op[6:0]);
    end

    // Test Case 2: Register addresses and all funct7 patterns.
    for (fields = 0; fields < 128; fields = fields + 1) begin
        instruction = {
            fields[6:0], fields[6:2], fields[5:1],
            3'b101, fields[4:0], 7'b0110011
        };
        branch_taken = 0;
        #1;
        observe("fields");
    end

    // Test Case 3: Return to inactive decoding after active instructions.
    instruction = 32'b0;
    branch_taken = 0;
    #1;
    observe("inactive");

    $display("===========End===========");
    $finish;
end

endmodule

