module testbench;

// Inputs
reg clk;
reg rst;
reg adclrc;
reg adcdat;

// Outputs
wire [15:0] data;
wire data_en;

integer test_id;
integer p;
integer r;
reg [15:0] pattern;

i2s_read uut (
    .clk_p(clk),
    .rst(rst),
    .adclrc(adclrc),
    .adcdat(adcdat),
    .data(data),
    .data_en(data_en)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [255:0] label;
    begin
        $display("t=%0t case=%0d %0s rst=%b adclrc=%b adcdat=%b data=%h data_en=%b",
                 $time, test_id, label, rst, adclrc, adcdat,
                 data, data_en);
    end
endtask

task step;
    input marker;
    input serial_bit;
    input [255:0] label;
    begin
        @(negedge clk);
        adclrc = marker;
        adcdat = serial_bit;
        @(posedge clk);
        #1;
        observe(label);
    end
endtask

task reset_dut;
    begin
        @(negedge clk);
        #2;
        rst = 0;
        #1;
        observe("asynchronous reset");
        repeat (2) @(posedge clk);
        #1;
        observe("reset held");
        @(negedge clk);
        adclrc = 1;
        adcdat = 0;
        rst = 1;
    end
endtask

task align_capture;
    begin
        step(0, 1, "initial low");
        step(0, 0, "low wait");
        step(1, 1, "qualifying high");
        step(1, 0, "high wait");
        step(0, 1, "capture entry");
    end
endtask

task send_bits;
    input [15:0] word;
    input integer count;
    input disturb_marker;
    integer b;
    begin
        for (b = 0; b < count; b = b + 1) begin
            @(negedge clk);
            adclrc = disturb_marker ? (b % 2) : 0;
            adcdat = word[15-b];
            @(posedge clk);
            #1;
            $display("t=%0t case=%0d bit=%0d rst=%b adclrc=%b adcdat=%b data=%h data_en=%b",
                     $time, test_id, b + 1, rst, adclrc, adcdat,
                     data, data_en);
        end
    end
endtask

initial begin
    // Initialize inputs and allow 100 ns for global reset.
    rst = 0;
    adclrc = 1;
    adcdat = 0;
    test_id = 0;
    pattern = 0;
    #1;
    observe("initial reset");
    #99;

    // Data patterns, synchronization, and consecutive reception.
    for (p = 0; p < 5; p = p + 1) begin
        test_id = p + 1;
        reset_dut;
        case (p)
            0: pattern = 16'h0000;
            1: pattern = 16'hffff;
            2: pattern = 16'haaaa;
            3: pattern = 16'h5555;
            4: pattern = 16'h93c6;
        endcase

        step(1, 1, "idle high");
        step(1, 0, "idle high hold");
        align_capture;
        send_bits(pattern, 16, p == 4);
        step(0, 1, "next edge after completion");
        step(0, 0, "completed buffer held");

        if (p == 4) begin
            step(1, 1, "next word high");
            step(1, 0, "next word high wait");
            step(0, 1, "next word capture entry");
            send_bits(16'h8001, 16, 0);

            step(1, 0, "immediate high after completion");
            step(0, 1, "minimum alignment low");
            send_bits(16'h3ca5, 16, 0);
            step(0, 0, "final validity deassertion");
        end
        #1;
    end

    // Reset from each reachable phase and capture boundary.
    for (r = 0; r < 7; r = r + 1) begin
        test_id = 10 + r;
        reset_dut;
        case (r)
            0: step(1, 1, "reset target idle");
            1: step(0, 1, "reset target low wait");
            2: begin
                step(0, 1, "initial low");
                step(1, 0, "reset target high wait");
            end
            3, 4, 5, 6: begin
                align_capture;
                case (r)
                    3: send_bits(16'hd369, 1, 0);
                    4: send_bits(16'hd369, 8, 0);
                    5: send_bits(16'hd369, 15, 0);
                    6: send_bits(16'hd369, 16, 0);
                endcase
            end
        endcase

        reset_dut;
        step(1, 1, "post-reset idle high");
        align_capture;
        send_bits(16'ha65b, 16, 0);
        step(0, 0, "post-reset validity deassertion");
        #1;
    end

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

// Inputs
reg clk;
reg RST;
reg FSM_RST;
reg TRG;

// Outputs
wire [4:0] STATE_OUT;

integer tc;
integer pulse;
integer target_month;

ONE_YEAR uut (
    .CLK       (clk),
    .RST       (RST),
    .FSM_RST   (FSM_RST),
    .TRG       (TRG),
    .STATE_OUT (STATE_OUT)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [8*40-1:0] phase;
    begin
        $display("t=%0t case=%0d %0s RST=%b FSM_RST=%b TRG=%b STATE_OUT=%0d",
                 $time, tc, phase, RST, FSM_RST, TRG, STATE_OUT);
    end
endtask

task sample;
    input integer cycles;
    input [8*40-1:0] phase;
    integer k;
    begin
        for (k = 0; k < cycles; k = k + 1) begin
            @(posedge clk);
            #1;
            observe(phase);
        end
    end
endtask

task trigger_level;
    input level;
    input integer cycles;
    input [8*40-1:0] phase;
    begin
        @(negedge clk);
        TRG = level;
        sample(cycles, phase);
    end
endtask

task full_reset;
    begin
        @(negedge clk);
        #2;
        RST = 1;
        FSM_RST = 1;
        TRG = 0;
        #1;
        observe("full reset asynchronous");
        sample(2, "full reset held");
        @(negedge clk);
        RST = 0;
        FSM_RST = 0;
    end
endtask

initial begin
    RST = 1;
    FSM_RST = 1;
    TRG = 0;
    tc = 0;

    // Wait 100 ns for global reset to finish.
    #100;
    observe("initial reset held");

    // 1: Startup and idle retention.
    tc = 1;
    full_reset;
    sample(8, "startup and idle");

    // 2: All triggered transitions, holds, falling edges, and wrap.
    tc = 2;
    full_reset;
    sample(6, "startup");
    for (pulse = 1; pulse <= 11; pulse = pulse + 1) begin
        trigger_level(1, 7, "cycle trigger high");
        trigger_level(0, 4, "cycle trigger low");
    end

    // 3: January trigger, uncaptured pulse, and one-clock pulse.
    tc = 3;
    full_reset;
    TRG = 1;
    sample(8, "startup with trigger high");
    trigger_level(0, 4, "trigger rearmed");

    @(negedge clk);
    #1 TRG = 1;
    #2 TRG = 0;
    sample(6, "pulse between sampling edges");

    trigger_level(1, 1, "one-clock trigger high");
    trigger_level(0, 6, "one-clock trigger response");

    // 4: RST alone preserves an established month.
    tc = 4;
    full_reset;
    sample(6, "startup");
    trigger_level(1, 6, "advance before RST");

    @(negedge clk);
    #2 RST = 1;
    #1;
    observe("RST-only asynchronous");
    sample(3, "RST-only held, trigger high");
    @(negedge clk);
    RST = 0;
    sample(8, "RST release, trigger recaptured");
    trigger_level(0, 4, "falling edge after RST");

    // 5: RST cancels a partially captured trigger.
    tc = 5;
    full_reset;
    sample(6, "startup");
    trigger_level(1, 1, "first trigger capture");
    @(negedge clk);
    #2;
    RST = 1;
    TRG = 0;
    #1;
    observe("RST during trigger pipeline");
    sample(2, "RST held");
    @(negedge clk);
    RST = 0;
    sample(7, "release after trigger cancellation");
    trigger_level(1, 6, "fresh trigger after RST");

    // 6: FSM_RST leaves output and conditioning independently clocked.
    tc = 6;
    full_reset;
    sample(6, "startup");
    trigger_level(1, 6, "advance before FSM_RST");
    trigger_level(0, 4, "trigger rearmed");

    @(negedge clk);
    #2 FSM_RST = 1;
    #1;
    observe("FSM_RST-only asynchronous");
    sample(2, "FSM_RST-only held");
    trigger_level(1, 6, "trigger consumed while held");
    @(negedge clk);
    FSM_RST = 0;
    sample(7, "FSM_RST release, trigger held");
    trigger_level(0, 4, "trigger rearmed");
    trigger_level(1, 6, "fresh trigger after FSM_RST");

    // 7: FSM_RST does not clear a trigger in flight.
    tc = 7;
    full_reset;
    sample(6, "startup");
    @(negedge clk);
    #2 FSM_RST = 1;
    #1;
    observe("FSM_RST before pending trigger");
    trigger_level(1, 1, "capture while FSM_RST held");
    @(negedge clk);
    FSM_RST = 0;
    TRG = 0;
    sample(8, "FSM_RST release with pending trigger");

    // 8..14: Missing reset transitions from May through November.
    // target_month is a fixed stimulus selector, not a DUT-state model.
    for (target_month = 5; target_month <= 11;
         target_month = target_month + 1) begin
        tc = target_month + 3;
        full_reset;
        sample(6, "reset sweep startup");

        // Startup reaches February. Each separated rising edge advances
        // one month; the final low interval drains trigger conditioning.
        for (pulse = 0; pulse < target_month - 2;
             pulse = pulse + 1) begin
            trigger_level(1, 7, "reset sweep advance high");
            trigger_level(0, 4, "reset sweep advance low");
        end

        // Keep RST low so only the month register resets.
        // Observe before the next rising edge to expose output retention.
        @(negedge clk);
        observe("reset sweep stable source month");
        #2 FSM_RST = 1;
        #1;
        observe("reset sweep asynchronous FSM_RST");
        sample(2, "reset sweep January held");

        // The startup pipeline remains asserted across FSM_RST.
        // Sample each clock to expose January-to-February and output lag.
        @(negedge clk);
        FSM_RST = 0;
        sample(6, "reset sweep automatic restart");
    end

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

// Inputs
reg clk;
reg reset;
reg input_signal;

// Outputs
wire output_signal;

integer mode;
integer step;
integer depth;

Moore_State_Machine uut (
    .clk(clk),
    .reset(reset),
    .input_signal(input_signal),
    .output_signal(output_signal)
);

initial clk = 0;
always #5 clk = ~clk;

task apply_reset;
begin
    @(negedge clk);
    reset = 1'b1;
    #1;
    $display("reset_assert t=%0t output_signal=%b",
             $time, output_signal);

    repeat (2) @(posedge clk);
    #1;
    $display("reset_held t=%0t output_signal=%b",
             $time, output_signal);

    @(negedge clk);
    reset = 1'b0;
    #1;
    $display("reset_release t=%0t output_signal=%b",
             $time, output_signal);
end
endtask

task drive_cycle;
    input value;
begin
    @(negedge clk);
    input_signal = ~value;
    #1;
    $display("between_edges t=%0t input_signal=%b output_signal=%b",
             $time, input_signal, output_signal);

    #1;
    input_signal = value;
    #1;
    $display("before_edge t=%0t input_signal=%b output_signal=%b",
             $time, input_signal, output_signal);

    @(posedge clk);
    #1;
    $display("after_edge t=%0t input_signal=%b output_signal=%b",
             $time, input_signal, output_signal);
end
endtask

// Drive an unknown transition from STATE_A. Since STATE_B and STATE_C
// differ in both bits, an X/Z input makes state_reg unknown. Additional
// clock edges exercise both implicit case defaults before reset recovery.
task exercise_unknown_state;
    input unknown_value;
begin
    apply_reset;

    @(negedge clk);
    input_signal = unknown_value;
    #1;
    $display("unknown_state_input t=%0t input_signal=%b output_signal=%b",
             $time, input_signal, output_signal);

    @(posedge clk);
    #1;
    $display("unknown_state_entry t=%0t input_signal=%b output_signal=%b",
             $time, input_signal, output_signal);

    @(posedge clk);
    #1;
    $display("unknown_state_hold_1 t=%0t input_signal=%b output_signal=%b",
             $time, input_signal, output_signal);

    @(posedge clk);
    #1;
    $display("unknown_state_hold_2 t=%0t input_signal=%b output_signal=%b",
             $time, input_signal, output_signal);

    @(negedge clk);
    reset = 1'b1;
    #1;
    $display("unknown_state_reset t=%0t input_signal=%b output_signal=%b",
             $time, input_signal, output_signal);

    @(posedge clk);
    #1;
    $display("unknown_state_reset_held t=%0t input_signal=%b output_signal=%b",
             $time, input_signal, output_signal);

    @(negedge clk);
    reset = 1'b0;
    input_signal = 1'b0;
    #1;
    $display("unknown_state_recovery t=%0t input_signal=%b output_signal=%b",
             $time, input_signal, output_signal);
end
endtask

initial begin
    // Initialize inputs and allow 100 ns for global reset.
    reset = 1'b1;
    input_signal = 1'b0;
    #100;
    $display("initial_reset t=%0t output_signal=%b",
             $time, output_signal);

    // Both STATE_A branches, repeated cycles, and between-edge input changes.
    for (mode = 0; mode < 2; mode = mode + 1) begin
        apply_reset;
        for (step = 0; step < 8; step = step + 1) begin
            drive_cycle(mode);
            $display("cycle_case mode=%0d step=%0d output_signal=%b",
                     mode, step, output_signal);
        end
    end

    // Reset from STATE_A, STATE_B, STATE_C, and STATE_D reached using
    // only top-level stimulus.
    for (depth = 0; depth < 4; depth = depth + 1) begin
        apply_reset;
        for (step = 0; step < depth; step = step + 1) begin
            drive_cycle(1'b1);
        end

        $display("before_reset depth=%0d output_signal=%b",
                 depth, output_signal);

        apply_reset;
        drive_cycle(1'b1);
    end

    // Existing unknown-input transition and recovery coverage.
    for (mode = 0; mode < 2; mode = mode + 1) begin
        apply_reset;

        @(negedge clk);
        if (mode == 0)
            input_signal = 1'bx;
        else
            input_signal = 1'bz;

        #1;
        $display("unknown_input mode=%0d output_signal=%b",
                 mode, output_signal);

        @(posedge clk);
        #1;
        $display("unknown_transition mode=%0d output_signal=%b",
                 mode, output_signal);

        drive_cycle(1'b0);
        drive_cycle(1'b1);

        apply_reset;
        drive_cycle(1'b1);
    end

    // Explicitly repeat unknown-state operation to target the implicit
    // default branches in both DUT case statements.
    exercise_unknown_state(1'bx);
    exercise_unknown_state(1'bz);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam RESET_HIGH_CYCLES = 65535;
localparam START_CYCLES = 21 + 3 + 6;

// Inputs
reg clk;
reg rst_n;
reg [15:0] ad_data;
reg ad_busy;
reg first_data;

// Outputs
wire [2:0] ad_os;
wire ad_cs, ad_rd, ad_reset, ad_convstab, ad_data_valid;
wire [15:0] ad_ch1, ad_ch2, ad_ch3, ad_ch4;
wire [15:0] ad_ch5, ad_ch6, ad_ch7, ad_ch8;

integer test_id, mode;
reg [15:0] samples [0:7];

ad7606_if uut (
    .clk(clk),
    .rst_n(rst_n),
    .ad_data(ad_data),
    .ad_busy(ad_busy),
    .first_data(first_data),
    .ad_os(ad_os),
    .ad_cs(ad_cs),
    .ad_rd(ad_rd),
    .ad_reset(ad_reset),
    .ad_convstab(ad_convstab),
    .ad_data_valid(ad_data_valid),
    .ad_ch1(ad_ch1),
    .ad_ch2(ad_ch2),
    .ad_ch3(ad_ch3),
    .ad_ch4(ad_ch4),
    .ad_ch5(ad_ch5),
    .ad_ch6(ad_ch6),
    .ad_ch7(ad_ch7),
    .ad_ch8(ad_ch8)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [8*32-1:0] label;
    begin
        $display("t=%0t case=%0d %0s rst_n=%b busy=%b first=%b data=%h | os=%b cs=%b rd=%b reset=%b convstab=%b valid=%b ch1=%h ch2=%h ch3=%h ch4=%h ch5=%h ch6=%h ch7=%h ch8=%h",
                 $time, test_id, label, rst_n, ad_busy, first_data,
                 ad_data, ad_os, ad_cs, ad_rd, ad_reset, ad_convstab,
                 ad_data_valid, ad_ch1, ad_ch2, ad_ch3, ad_ch4,
                 ad_ch5, ad_ch6, ad_ch7, ad_ch8);
    end
endtask

task clocks;
    input integer count;
    input [8*32-1:0] label;
    integer k;
    begin
        for (k = 0; k < count; k = k + 1) begin
            @(posedge clk);
            #1;
            observe(label);
        end
    end
endtask

// Return immediately after generated reset falls.
// hold_cycles = 2 preserves the original external-reset hold.
// hold_cycles = 0 creates a pulse entirely before the next rising edge.
task reset_device;
    input integer hold_cycles;
    begin
        @(negedge clk);
        #2;
        rst_n = 0;
        ad_busy = 1;
        ad_data = 16'hDEAD;
        first_data = 0;
        #1;
        observe("external reset asserted");

        if (hold_cycles == 0) begin
            // Release at falling edge + 4 ns, before the next rising edge.
            #1;
            rst_n = 1;
        end
        else begin
            clocks(hold_cycles, "external reset held");
            @(negedge clk);
            rst_n = 1;
        end

        // First edge raises ad_reset; second edge resets the sequencer.
        clocks(2, "generated reset begins");
        repeat (RESET_HIGH_CYCLES - 3) @(posedge clk);
        #1;
        observe("near reset end");
        clocks(2, "reset boundary");
    end
endtask

// Enter with channel 1 selected, before its first processing clock.
task read_scan;
    input integer reverse_order;
    input integer busy_during_read;
    integer channel, phase;
    reg [15:0] sample;
    begin
        for (channel = 0; channel < 8; channel = channel + 1) begin
            // Exactly one falling-edge wait per read interval.
            @(negedge clk);
            if (reverse_order)
                sample = samples[7-channel];
            else
                sample = samples[channel];

            for (phase = 0; phase < 4; phase = phase + 1) begin
                // Earlier intervals carry different stimulus data.
                ad_data = (phase == 3) ? sample : ~sample;
                ad_busy = busy_during_read;
                first_data = ~first_data;
                @(posedge clk);
                #1;
                observe("channel read");

                // The next channel supplies its own falling-edge wait.
                if (phase < 3)
                    @(negedge clk);
            end
        end
        clocks(1, "leave data-valid");
    end
endtask

initial begin
    rst_n = 0;
    ad_data = 0;
    ad_busy = 1;
    first_data = 0;
    test_id = 0;

    samples[0] = 16'h0000;
    samples[1] = 16'hFFFF;
    samples[2] = 16'hAAAA;
    samples[3] = 16'h5555;
    samples[4] = 16'h8000;
    samples[5] = 16'h7FFF;
    samples[6] = 16'h0001;
    samples[7] = 16'h1234;

    #100;

    // Case 1: startup, extended busy, and all channel reads.
    test_id = 1;
    reset_device(2);
    clocks(START_CYCLES, "conversion sequence");
    clocks(5, "busy held high");
    @(negedge clk);
    ad_busy = 0;
    clocks(1, "busy released");
    read_scan(0, 1);

    // Case 2: autonomous repetition with busy already low.
    test_id = 2;
    @(negedge clk);
    ad_busy = 0;
    first_data = 1;
    clocks(START_CYCLES + 1, "repeat with busy low");
    read_scan(1, 0);
    clocks(2, "completed data retained");

    // Modes 0-2 preserve original cases 3-5.
    // Mode 3 targets AD_CONV->IDLE.
    // Modes 4-11 target READ_CH1 through READ_CH8 -> IDLE.
    for (mode = 0; mode < 12; mode = mode + 1) begin
        @(negedge clk);
        test_id = 3 + mode;
        reset_device(2);

        case (mode)
            0: clocks(21 + 1, "interrupt conversion");

            1: clocks(START_CYCLES + 5, "interrupt busy wait");

            2: begin
                clocks(START_CYCLES, "prepare partial read");
                @(negedge clk);
                ad_busy = 0;
                ad_data = 16'hBEEF;
                clocks(1 + 6, "interrupt partial read");
            end

            3: begin
                // Enter AD_CONV before its first processing clock.
                clocks(21, "target conversion reset");
            end

            default: begin
                clocks(START_CYCLES, "prepare channel reset");
                @(negedge clk);
                ad_busy = 0;
                ad_data = samples[mode-4];
                first_data = ~first_data;

                // One busy-release clock enters READ_CH1.
                // Each preceding channel consumes exactly four clocks.
                clocks(1 + 4 * (mode - 4),
                       "target channel reset");
            end
        endcase

        if (mode < 3)
            reset_device(2);
        else
            // One normal processing edge precedes the reset edge,
            // keeping the source state inside the intended interval.
            reset_device(0);

        @(negedge clk);
        ad_busy = 0;
        clocks(START_CYCLES + 1, "recovery conversion");
        read_scan(0, 0);
    end

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam CNTR_WD = 20;
localparam DEPTH = 16;

// Inputs
reg clk;
reg uctl_sysRst_n;
reg [CNTR_WD-1:0] dmaTx2ctrl_len;
reg dmaTx2ctrl_sRdWr, dmaTx2ctrl_stransEn;
reg [31:0] dmaTx2ctrl_sRdAddr;
reg [4:0] words_inFifo;
reg ahbc2ctrl_ack, ahbc2ctrl_addrDn, ahbc2ctrl_dataDn;
reg [31:0] ahbc2ctrl_sWrAddr;

// Outputs
wire ctrl2dmaTx_dataDn, ctrl2ahbc_trEn, ctrl2ahbc_sRdWr;
wire [4:0] ctrl2ahbc_beats;
wire [2:0] ctrl2ahbc_hSize;
wire [31:0] ctrl2ahbc_sRdAddr;

integer i, j, tc;

uctl_ctrlAhbTx #(
    .CNTR_WD(CNTR_WD), .ADDR_SIZE(32),
    .DATA_SIZE(32), .ADD_WIDTH(4)
) uut (
    .uctl_sysClk(clk),
    .uctl_sysRst_n(uctl_sysRst_n),
    .dmaTx2ctrl_len(dmaTx2ctrl_len),
    .dmaTx2ctrl_sRdWr(dmaTx2ctrl_sRdWr),
    .dmaTx2ctrl_stransEn(dmaTx2ctrl_stransEn),
    .dmaTx2ctrl_sRdAddr(dmaTx2ctrl_sRdAddr),
    .words_inFifo(words_inFifo),
    .ahbc2ctrl_ack(ahbc2ctrl_ack),
    .ahbc2ctrl_addrDn(ahbc2ctrl_addrDn),
    .ahbc2ctrl_dataDn(ahbc2ctrl_dataDn),
    .ahbc2ctrl_sWrAddr(ahbc2ctrl_sWrAddr),
    .ctrl2dmaTx_dataDn(ctrl2dmaTx_dataDn),
    .ctrl2ahbc_trEn(ctrl2ahbc_trEn),
    .ctrl2ahbc_beats(ctrl2ahbc_beats),
    .ctrl2ahbc_hSize(ctrl2ahbc_hSize),
    .ctrl2ahbc_sRdAddr(ctrl2ahbc_sRdAddr),
    .ctrl2ahbc_sRdWr(ctrl2ahbc_sRdWr)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [8*36-1:0] label;
    begin
        $display("t=%0t case=%0d %0s done=%b trEn=%b beats=%0d hSize=%b addr=%h rdWr=%b",
                 $time, tc, label, ctrl2dmaTx_dataDn, ctrl2ahbc_trEn,
                 ctrl2ahbc_beats, ctrl2ahbc_hSize,
                 ctrl2ahbc_sRdAddr, ctrl2ahbc_sRdWr);
    end
endtask

task clocks;
    input integer count;
    input [8*36-1:0] label;
    begin
        repeat(count) @(posedge clk);
        #1;
        observe(label);
    end
endtask

task reset_dut;
    begin
        #2;
        uctl_sysRst_n = 0;
        dmaTx2ctrl_len = 0;
        dmaTx2ctrl_sRdWr = 0;
        dmaTx2ctrl_stransEn = 0;
        dmaTx2ctrl_sRdAddr = 0;
        words_inFifo = 0;
        ahbc2ctrl_ack = 0;
        ahbc2ctrl_addrDn = 0;
        ahbc2ctrl_dataDn = 0;
        ahbc2ctrl_sWrAddr = 0;
        #1;
        observe("asynchronous reset");
        clocks(2, "reset held");
        @(negedge clk);
        uctl_sysRst_n = 1;
        clocks(1, "reset released");
    end
endtask

task launch;
    input [CNTR_WD-1:0] length;
    input direction;
    input [4:0] occupied;
    begin
        @(negedge clk);
        dmaTx2ctrl_len = length;
        dmaTx2ctrl_sRdWr = direction;
        dmaTx2ctrl_sRdAddr = 32'h12345678;
        dmaTx2ctrl_stransEn = 1;
        words_inFifo = occupied;
        clocks(1, "new request");
        @(negedge clk);
        dmaTx2ctrl_stransEn = 0;
    end
endtask

task finish_burst;
    input split_address;
    input final_burst;
    input early_data;
    begin
        @(negedge clk);
        ahbc2ctrl_ack = 1;
        ahbc2ctrl_addrDn = !split_address;
        ahbc2ctrl_sWrAddr = ahbc2ctrl_sWrAddr + 32'h100;
        ahbc2ctrl_dataDn = final_burst && early_data;
        clocks(1, "acknowledgement");
        @(negedge clk);
        ahbc2ctrl_ack = 0;
        ahbc2ctrl_addrDn = 0;
        if (split_address) begin
            clocks(2, "address completion pending");
            @(negedge clk);
            ahbc2ctrl_addrDn = 1;
            clocks(1, "address completion");
            @(negedge clk);
            ahbc2ctrl_addrDn = 0;
        end
        if (final_burst) begin
            if (early_data)
                clocks(2, "after immediate completion");
            else begin
                clocks(3, "final data pending");
                @(negedge clk);
                ahbc2ctrl_dataDn = 1;
                #1;
                observe("combinational final completion");
                clocks(1, "after delayed completion");
            end
            @(negedge clk);
            ahbc2ctrl_dataDn = 0;
            clocks(1, "idle after completion");
        end
        else
            clocks(1, "next burst planning");
    end
endtask

task run_transfer;
    input [CNTR_WD-1:0] length;
    input integer bursts;
    input split_address;
    input early_data;
    integer b;
    begin
        reset_dut;
        launch(length, tc % 2, 0);
        @(negedge clk);
        dmaTx2ctrl_stransEn = 1;
        dmaTx2ctrl_len = {CNTR_WD{1'b1}};
        dmaTx2ctrl_sRdAddr = 32'hFEDCBA98;
        dmaTx2ctrl_sRdWr = !dmaTx2ctrl_sRdWr;
        clocks(1, "busy DMA inputs; pulse cleared");
        clocks(2, "acknowledgement pending");
        @(negedge clk);
        dmaTx2ctrl_stransEn = 0;
        for (b = 0; b < bursts; b = b + 1) begin
            @(negedge clk);
            finish_burst(split_address, b == bursts-1, early_data);
        end
    end
endtask

task release_fifo;
    input integer required_words;
    begin
        clocks(2, "FIFO full stall");
        @(negedge clk);
        words_inFifo = DEPTH - required_words + 1;
        clocks(2, "one word below admission");
        @(negedge clk);
        words_inFifo = DEPTH - required_words;
        clocks(1, "exact FIFO admission");
    end
endtask

task idle_admission;
    input [CNTR_WD-1:0] length;
    input integer required_words;
    begin
        reset_dut;
        @(negedge clk);
        words_inFifo = DEPTH;
        dmaTx2ctrl_stransEn = 1;
        dmaTx2ctrl_len = 1;
        dmaTx2ctrl_sRdAddr = 32'h11111111;
        dmaTx2ctrl_sRdWr = 0;
        clocks(1, "idle blocked first length");
        @(negedge clk);
        dmaTx2ctrl_len = length;
        dmaTx2ctrl_sRdAddr = 32'hABCDEF00;
        dmaTx2ctrl_sRdWr = 1;
        clocks(1, "idle blocked replacement length");
        release_fifo(required_words);
        @(negedge clk);
        dmaTx2ctrl_stransEn = 0;
        finish_burst(0, 1, 0);
    end
endtask

initial begin
    uctl_sysRst_n = 0;
    dmaTx2ctrl_len = 0;
    dmaTx2ctrl_sRdWr = 0;
    dmaTx2ctrl_stransEn = 0;
    dmaTx2ctrl_sRdAddr = 0;
    words_inFifo = 0;
    ahbc2ctrl_ack = 0;
    ahbc2ctrl_addrDn = 0;
    ahbc2ctrl_dataDn = 0;
    ahbc2ctrl_sWrAddr = 0;
    tc = 0;

    // Wait 100 ns for global reset to finish.
    #100;

    // Sizing boundaries and both handshake/completion paths.
    for (i = 0; i <= 7; i = i + 1) begin
        #1;
        tc = tc + 1;
        run_transfer(i, (i > 4) ? 2 : 1, i % 2, (i+1) % 2);
    end
    for (i = 60; i <= 67; i = i + 1) begin
        #1;
        tc = tc + 1;
        run_transfer(i, ((i == 60) || (i == 64)) ? 1 : 2,
                     i % 2, (i+1) % 2);
    end
    tc = tc + 1;
    run_transfer(131, 3, 1, 0);

    // Initial FIFO thresholds, including zero-length admission.
    tc = tc + 1; idle_admission(0, 1);
    tc = tc + 1; idle_admission(4, 1);
    tc = tc + 1; idle_admission(60, 15);
    tc = tc + 1; idle_admission(64, 16);

    // First idle admission uses the previously registered zero count.
    tc = tc + 1;
    reset_dut;
    launch(64, 1, 15);
    clocks(2, "initial one-free-word admission");
    finish_burst(0, 1, 1);
    launch(3, 0, 15);
    finish_burst(1, 1, 0);

    // Subsequent thresholds: 15-word plus byte tail; 16-word burst.
    for (j = 0; j < 2; j = j + 1) begin
        #1;
        tc = tc + 1;
        reset_dut;
        launch((j == 0) ? 127 : 128, 1, 0);
        @(negedge clk);
        words_inFifo = DEPTH;
        finish_burst(0, 0, 0);
        release_fifo((j == 0) ? 15 : 16);
        if (j == 0) begin
            @(negedge clk);
            words_inFifo = DEPTH;
            finish_burst(1, 0, 0);
            release_fifo(1);
        end
        finish_burst(0, 1, j);
    end

    // Maximum length: observe initial sizing and one acknowledged burst.
    tc = tc + 1;
    reset_dut;
    launch({CNTR_WD{1'b1}}, 0, 0);
    finish_burst(0, 0, 0);
    reset_dut;

    // Abort independently in each operational state, then recover.
    for (i = 0; i < 5; i = i + 1) begin
        #1;
        tc = tc + 1;
        reset_dut;
        if (i != 0)
            launch((i == 3) ? 8 : 4, 1, 0);
        if (i >= 2) begin
            @(negedge clk);
            ahbc2ctrl_ack = 1;
            clocks(1, "reset setup: address wait");
            @(negedge clk);
            ahbc2ctrl_ack = 0;
        end
        if (i >= 3) begin
            @(negedge clk);
            words_inFifo = DEPTH;
            ahbc2ctrl_addrDn = 1;
            ahbc2ctrl_sWrAddr = 32'h87654320;
            clocks(1, "reset setup: burst planning");
            @(negedge clk);
            ahbc2ctrl_addrDn = 0;
            clocks(2, "reset setup: stalled or data wait");
        end
        reset_dut;
        launch(1, 0, 0);
        finish_burst(0, 1, 0);
    end

    // Idle ignores unsolicited AHB indications and retains its address.
    tc = tc + 1;
    @(negedge clk);
    ahbc2ctrl_ack = 1;
    ahbc2ctrl_addrDn = 1;
    ahbc2ctrl_dataDn = 1;
    ahbc2ctrl_sWrAddr = 32'hFFFFFFFF;
    clocks(2, "unsolicited idle indications");

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

// Inputs
reg clk;
reg [31:0] inst;

// Outputs
wire [4:0] alu_ctrl;
wire reg_file_wr_en;
wire [1:0] reg_file_wr_back_sel;
wire alu_op2_sel;
wire d_mem_rd_en;
wire d_mem_wr_en;
wire [1:0] d_mem_size;
wire jal;
wire jalr;

integer opcode, variant, qualifier;

ctrl uut (
    .inst(inst),
    .alu_ctrl(alu_ctrl),
    .reg_file_wr_en(reg_file_wr_en),
    .reg_file_wr_back_sel(reg_file_wr_back_sel),
    .alu_op2_sel(alu_op2_sel),
    .d_mem_rd_en(d_mem_rd_en),
    .d_mem_wr_en(d_mem_wr_en),
    .d_mem_size(d_mem_size),
    .jal(jal),
    .jalr(jalr)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    begin
        $display("t=%0t inst=%h alu_ctrl=%b reg_file_wr_en=%b reg_file_wr_back_sel=%b alu_op2_sel=%b d_mem_rd_en=%b d_mem_wr_en=%b d_mem_size=%b jal=%b jalr=%b",
                 $time, inst, alu_ctrl, reg_file_wr_en,
                 reg_file_wr_back_sel, alu_op2_sel,
                 d_mem_rd_en, d_mem_wr_en, d_mem_size, jal, jalr);
    end
endtask

initial begin
    inst = 32'b0;

    // Startup; no DUT reset port.
    #100;
    observe;

    // All opcodes, functions, alternate-function values and backgrounds.
    for (opcode = 0; opcode < 32; opcode = opcode + 1) begin
        for (variant = 0; variant < 32; variant = variant + 1) begin
            inst = {32{variant[4]}};
            inst[30] = variant[3];
            inst[14:12] = variant[2:0];
            inst[6:2] = opcode[4:0];
            inst[1:0] = 2'b11;
            #1;
            observe;
        end
    end

    // Qualified-to-unqualified transitions for every major opcode.
    for (opcode = 0; opcode < 32; opcode = opcode + 1) begin
        for (qualifier = 0; qualifier < 3; qualifier = qualifier + 1) begin
            inst = 32'b0;
            inst[6:2] = opcode[4:0];
            inst[1:0] = 2'b11;
            #1;
            observe;

            inst[1:0] = qualifier[1:0];
            #1;
            observe;
        end
    end

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

// Inputs
reg clk;
reg rst;
reg PAR_EN;
reg RX_IN;
reg par_err;
reg strt_glitch;
reg stp_err;
reg [3:0] bit_cnt;
reg [2:0] edge_cnt;

// Outputs
wire data_samp_en;
wire par_chk_en;
wire stp_chk_en;
wire strt_chk_en;
wire enable;
wire deser_en;
wire data_valid;

integer case_id;
integer p, s, b, e, k;

FSM_RX uut (
    .clk(clk),
    .rst(rst),
    .PAR_EN(PAR_EN),
    .RX_IN(RX_IN),
    .par_err(par_err),
    .strt_glitch(strt_glitch),
    .stp_err(stp_err),
    .bit_cnt(bit_cnt),
    .edge_cnt(edge_cnt),
    .data_samp_en(data_samp_en),
    .par_chk_en(par_chk_en),
    .stp_chk_en(stp_chk_en),
    .strt_chk_en(strt_chk_en),
    .enable(enable),
    .deser_en(deser_en),
    .data_valid(data_valid)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [8*24-1:0] label;
    begin
        $display(
            "t=%0t case=%0d %0s rst=%b PAR_EN=%b RX_IN=%b bit=%0d edge=%0d glitch=%b par_err=%b stp_err=%b | data_samp_en=%b par_chk_en=%b stp_chk_en=%b strt_chk_en=%b enable=%b deser_en=%b data_valid=%b",
            $time, case_id, label, rst, PAR_EN, RX_IN,
            bit_cnt, edge_cnt, strt_glitch, par_err, stp_err,
            data_samp_en, par_chk_en, stp_chk_en, strt_chk_en,
            enable, deser_en, data_valid
        );
    end
endtask

// Sample combinational decisions before the edge and settled outputs after it.
task step;
    input [3:0] bits;
    input [2:0] edges;
    input rx, glitch, parity_error, stop_error;
    begin
        @(negedge clk);
        bit_cnt = bits;
        edge_cnt = edges;
        RX_IN = rx;
        strt_glitch = glitch;
        par_err = parity_error;
        stp_err = stop_error;
        #1;
        observe("before clock");
        @(posedge clk);
        #1;
        observe("after clock");
    end
endtask

// Preserve the current inputs at assertion, then exercise both reset RX levels.
task reset_to_idle;
    input parity_mode;
    begin
        @(negedge clk);
        #2;
        rst = 0;
        #1;
        observe("async reset");
        RX_IN = 0;
        #1;
        observe("reset RX low");
        RX_IN = 1;
        #1;
        observe("reset RX high");
        @(negedge clk);
        PAR_EN = parity_mode;
        bit_cnt = 0;
        edge_cnt = 0;
        strt_glitch = 0;
        par_err = 0;
        stp_err = 0;
        rst = 1;
        #1;
        observe("reset released");
    end
endtask

task enter_data;
    input parity_mode;
    begin
        reset_to_idle(parity_mode);
        step(0, 0, 1, 0, 0, 0);
        step(0, 0, 0, 0, 0, 0);
        step(1, 7, 1, 1, 0, 0);
        step(0, 0, 1, 1, 0, 0);
        step(1, 0, 1, 0, 0, 0);
    end
endtask

initial begin
    rst = 1;
    PAR_EN = 0;
    RX_IN = 1;
    par_err = 0;
    strt_glitch = 0;
    stp_err = 0;
    bit_cnt = 0;
    edge_cnt = 0;
    case_id = 0;

    // Wait 100 ns for global reset to finish.
    #100;

    // Cases 1-4: complete frames, both parity modes and stop outcomes.
    for (p = 0; p < 2; p = p + 1) begin
        for (s = 0; s < 2; s = s + 1) begin
            #1;
            case_id = 1 + 2*p + s;
            enter_data(p);

            step(0, 0, 1, 0, 0, 0);
            step(0, 7, 1, 0, 0, 0);
            for (b = 1; b <= 8; b = b + 1) begin
                for (e = 0; e < 8; e = e + 1) begin
                    #1;
                    step(b, e, 1, 0, 0, 0);
                end
            end
            step(15, 0, 1, 0, 0, 0);
            step(15, 7, 1, 0, 0, 0);
            step(9, 7*s, 1, 0, 0, 0);

            if (p == 1) begin
                step(9, 0, 1, 0, 1, 0);
                step(10, 7, 1, 0, 1, 0);
                step(11, 0, 1, 0, 1, 0);
                step(10, 0, 1, 0, 0, 0);
            end

            step(11-p, 0, 1, 0, 0, 1);
            step(10+p, 7, 1, 0, 0, 1);
            step(10+p, 0, 1, 0, 0, s);
            step(0, 0, 1, 0, 0, 0);

            // Start another frame immediately, without reset.
            step(0, 0, 0, 0, 0, 0);
            step(1, 0, 1, 0, 0, 0);
        end
    end

    // Case 5: start glitch rejection and subsequent recovery.
    case_id = 5;
    reset_to_idle(0);
    step(0, 0, 0, 0, 0, 0);
    step(1, 7, 1, 1, 0, 0);
    step(0, 0, 1, 1, 0, 0);
    step(1, 0, 1, 1, 0, 0);
    step(0, 0, 1, 0, 0, 0);
    step(0, 0, 0, 0, 0, 0);
    step(1, 0, 1, 0, 0, 0);

    // Cases 6-7: secondary start transition ignores the glitch input.
    for (k = 0; k < 2; k = k + 1) begin
        #1;
        case_id = 6 + k;
        reset_to_idle(0);
        step(0, 0, 0, 0, 0, 0);
        step(10, 0, 1, 1, 0, 0);
        step(11, 7*k, 1, 1, 0, 0);
        step(2, 0, 1, 0, 0, 0);
    end

    // Case 8: parity rejection and subsequent recovery.
    case_id = 8;
    enter_data(1);
    step(9, 0, 1, 0, 0, 0);
    step(9, 0, 1, 0, 1, 0);
    step(10, 7, 1, 0, 1, 0);
    step(10, 0, 1, 0, 1, 0);
    step(0, 0, 1, 0, 0, 0);
    step(0, 0, 0, 0, 0, 0);
    step(1, 0, 1, 0, 0, 0);

    // Cases 9-13: reset from idle, start, data, parity, and stop.
    for (k = 0; k < 5; k = k + 1) begin
        #1;
        case_id = 9 + k;
        reset_to_idle(1);
        if (k >= 1)
            step(0, 0, 0, 0, 0, 0);
        if (k >= 2)
            step(1, 0, 1, 0, 0, 0);
        if (k >= 3)
            step(9, 0, 1, 0, 0, 0);
        if (k >= 4)
            step(10, 0, 1, 0, 0, 0);
        reset_to_idle(1);
        step(0, 0, 1, 0, 0, 0);
        step(0, 0, 0, 0, 0, 0);
        step(1, 0, 1, 0, 0, 0);
    end

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam PATTERNS = 18;
localparam OBSERVE_CYCLES = 20;

// Inputs
reg clk;
reg reset;
reg start;
reg signed [7:0] in;

// Outputs
wire ready;
wire signed [17:0] out;

integer test_id;
integer p;
integer r;
integer positions;
integer tail_cycles;

// Instantiate the Unit Under Test (UUT)
DUT uut (
    .clock(clk),
    .reset(reset),
    .start(start),
    .in(in),
    .ready(ready),
    .out(out)
);

// clk toggle generate
initial clk = 0;
always #5 clk = ~clk;

// Packed stimulus only: nine row operands followed by three coefficients.
function [95:0] stimulus_set;
    input integer pattern;
    reg [23:0] rows;
    begin
        case (pattern)
             0: rows = {8'hfd, 8'd1, 8'd5};
             1: rows = {8'hfd, 8'd5, 8'd1};
             2: rows = {8'd1, 8'hfd, 8'd5};
             3: rows = {8'd1, 8'd5, 8'hfd};
             4: rows = {8'd5, 8'hfd, 8'd1};
             5: rows = {8'd5, 8'd1, 8'hfd};
             6: rows = {8'hfd, 8'hfd, 8'd5};
             7: rows = {8'd5, 8'd5, 8'hfd};
             8: rows = {8'hfd, 8'd5, 8'hfd};
             9: rows = {8'd5, 8'hfd, 8'd5};
            10: rows = {8'd5, 8'hfd, 8'hfd};
            11: rows = {8'hfd, 8'd5, 8'd5};
            default: rows = 24'd0;
        endcase

        stimulus_set = {
            rows[23:16], 16'd0,
            rows[15:8],  16'd0,
            rows[7:0],   16'd0,
            8'd1, 8'd2, 8'hfd
        };

        case (pattern)
            12: stimulus_set = {
                72'd0, 8'd1, 8'd2, 8'hfd
            };
            13: stimulus_set = {
                {9{8'd1}}, 8'd1, 8'd2, 8'd3
            };
            14: stimulus_set = {
                {3{8'h80}}, {3{8'h7f}},
                8'h7f, 8'h80, 8'd0,
                {3{8'h80}}
            };
            15: stimulus_set = {
                {3{8'h7f}}, {3{8'h80}},
                8'h7f, 8'h80, 8'd1,
                {3{8'h7f}}
            };
            16: stimulus_set = {
                8'h7f, 8'h80, 8'd1,
                8'h80, 8'h7f, 8'hff,
                8'hff, 8'd1, 8'h7f,
                8'h80, 8'h7f, 8'hff
            };
            17: stimulus_set = {
                {9{8'd7}}, 24'd0
            };
        endcase
    end
endfunction

task observe;
    begin
        $display("case=%0d t=%0t reset=%b start=%b in=%0d ready=%b out=%0d out_hex=%h",
                 test_id, $time, reset, start, in, ready, out, out);
    end
endtask

task apply_cycles;
    input integer count;
    input advance;
    input [7:0] value;
    integer k;
    begin
        @(negedge clk);
        start = advance;
        in = value;
        for (k = 0; k < count; k = k + 1) begin
            @(posedge clk);
            #1;
            observe;
        end
    end
endtask

task reset_dut;
    begin
        @(negedge clk);
        #2;
        reset = 1;
        start = 0;
        in = 0;
        #1;
        observe;
        repeat (2) @(posedge clk);
        #1;
        observe;
        @(negedge clk);
        #2;
        reset = 0;
        @(posedge clk);
        #1;
        observe;
    end
endtask

task send_operands;
    input integer first_pattern;
    input integer second_pattern;
    input integer count;
    input stall_boundaries;
    reg [95:0] first_set;
    reg [95:0] second_set;
    reg [7:0] value;
    integer j;
    begin
        first_set = stimulus_set(first_pattern);
        second_set = stimulus_set(second_pattern);
        for (j = 0; j < count; j = j + 1) begin
            #1;
            if (j < 12)
                value = first_set[95 - 8*j -: 8];
            else
                value = second_set[95 - 8*(j-12) -: 8];

            if (stall_boundaries &&
                ((j == 0) || (j == 11) || (j == 12) || (j == 23))) begin
                apply_cycles(2, 0, ~value);
                apply_cycles(1, 0, value);
            end
            apply_cycles(1, 1, value);
        end
    end
endtask

initial begin
    // Initialize Inputs
    reset = 0;
    start = 0;
    in = 0;
    test_id = 0;

    // Wait 100 ns for global reset to finish
    #100;

    // Arithmetic, selection, acquisition stalls, and both output streams.
    for (p = 0; p < PATTERNS; p = p + 1) begin
        #1;
        test_id = p;
        reset_dut;
        send_operands(p, (p + 1) % PATTERNS, 24, 1);
        apply_cycles(OBSERVE_CYCLES, 0, 0);
    end

    // Consecutive transactions without reset; active inputs during output.
    test_id = 18;
    reset_dut;
    send_operands(14, 16, 24, 0);
    apply_cycles(14, 1, 8'h55);
    apply_cycles(6, 0, 8'haa);

    test_id = 19;
    send_operands(17, 15, 24, 0);
    apply_cycles(OBSERVE_CYCLES, 0, 0);

    // Interrupt either acquisition set, output 1, calculation, or output 2.
    for (r = 0; r < 5; r = r + 1) begin
        #1;
        test_id = 20 + r;
        case (r)
            0: begin positions = 6;  tail_cycles = 0;  end
            1: begin positions = 18; tail_cycles = 0;  end
            2: begin positions = 24; tail_cycles = 3;  end
            3: begin positions = 24; tail_cycles = 9;  end
            4: begin positions = 24; tail_cycles = 11; end
        endcase
        reset_dut;
        send_operands(14, 16, positions, 0);
        if (tail_cycles > 0)
            apply_cycles(tail_cycles, 0, 0);
        reset_dut;
        send_operands(16, 14, 24, 0);
        apply_cycles(OBSERVE_CYCLES, 0, 0);
    end

    $display("===========End===========");
    $finish;
end

endmodule

