    data_a = 16'h5678;
    addr_b = 16'h9ABC;
    data_b = 16'hDEF0;
    start_a = 0;
    rw_a = 1;
    start_b = 1;
    rw_b = 0;
    select = 3'b111;

    // Wait 100 ns for global reset to finish
    #100;
    observe(-1);

    // All selections, payload boundaries, and control combinations.
    for (s = 0; s < 8; s = s + 1) begin
        select = s;
        #1;
        observe(-1);

        for (p = 0; p < 16; p = p + 1) begin
            {start_a, rw_a, start_b, rw_b} = p;
            case (p % 4)
                0: begin
                    addr_a = 16'h0000; data_a = 16'hFFFF;
                    addr_b = 16'hFFFF; data_b = 16'h0000;
                end
                1: begin
                    addr_a = 16'hFFFF; data_a = 16'h0000;
                    addr_b = 16'h0000; data_b = 16'hFFFF;
                end
                2: begin
                    addr_a = 16'h1357; data_a = 16'hA5C3;
                    addr_b = 16'h2468; data_b = 16'h5A3C;
