                3: begin
                    addr_a = ~16'h1357; data_a = ~16'hA5C3;
                    addr_b = ~16'h2468; data_b = ~16'h5A3C;
                end
            endcase
            #1;
            observe(p);
        end
    end

    // Return from an unused encoding to a valid route.
    select = 3'b000;
    #1;
    observe(-1);

    $display("===========End===========");
    $finish;
end

