module testbench;

// Inputs
reg clk;
reg rst_n, re, we, fetch, IMhit, DMhit, d_dirty, memRd;
reg [7:0] d_tag;
reg [15:0] iaddr, daddr, writeData;
reg [63:0] IO, DO, MO;

// Outputs
wire IDI, Memre, IMwe, DMwe, Memwe, DDI, ready;
wire [15:0] instruction, readData;
wire [13:0] Memaddr;
wire [63:0] i_data, d_data;

integer n, offset, state_case;

cache_control uut (
    .clk(clk), .rst_n(rst_n),
    .re(re), .we(we), .fetch(fetch), .writeData(writeData),
    .IMhit(IMhit), .DMhit(DMhit), .d_dirty(d_dirty),
    .memRd(memRd), .d_tag(d_tag),
    .iaddr(iaddr), .daddr(daddr),
    .IO(IO), .DO(DO), .MO(MO),
    .IDI(IDI), .Memre(Memre), .IMwe(IMwe), .DMwe(DMwe),
    .Memwe(Memwe), .DDI(DDI), .ready(ready),
    .instruction(instruction), .readData(readData),
    .Memaddr(Memaddr), .i_data(i_data), .d_data(d_data)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [8*64-1:0] label;
    begin
        #1;
        $display("%0t %0s re=%b we=%b fetch=%b iaddr=%h daddr=%h IDI=%b Memre=%b IMwe=%b DMwe=%b Memwe=%b DDI=%b ready=%b instruction=%h readData=%h Memaddr=%h i_data=%h d_data=%h",
                 $time, label, re, we, fetch, iaddr, daddr,
                 IDI, Memre, IMwe, DMwe, Memwe, DDI, ready,
                 instruction, readData, Memaddr, i_data, d_data);
    end
endtask

task step;
    input [8*64-1:0] label;
    begin
        @(posedge clk);
        observe(label);
    end
endtask

task reset_case;
    begin
        @(negedge clk);
        rst_n = 0;
        re = 0;
        we = 0;
        fetch = 0;
        IMhit = 1;
        DMhit = 1;
        d_dirty = 0;
        memRd = 0;
        d_tag = 8'h96;
        iaddr = 16'h2468;
        daddr = 16'hA594;
        writeData = 16'hCAFE;
        IO = 64'hFEDC_BA98_7654_3210;
        DO = 64'h1357_2468_9ABC_DEF0;
        MO = 64'h0123_4567_89AB_CDEF;
        observe("reset asserted");
        repeat (2) @(posedge clk);
        @(negedge clk);
        rst_n = 1;
        observe("reset released");
    end
endtask

// Each data miss also leaves an instruction miss pending.
task data_miss;
    input do_write, dirty, simultaneous_read;
    input [15:0] address;
    input [7:0] victim_tag;
    begin
        reset_case;
        @(negedge clk);
        re = simultaneous_read | ~do_write;
        we = do_write;
        fetch = 1;
        DMhit = 0;
        IMhit = 0;
        d_dirty = dirty;
        daddr = address;
        d_tag = victim_tag;
        iaddr = 16'hFFFF;
        writeData = address[0] ? 16'hFFFF : 16'h0000;
        observe("data miss takes priority");
        step("entered memory wait");
        repeat (2) @(posedge clk);
        observe("delayed memory completion");

        if (dirty) begin
            @(negedge clk);
            memRd = 1;
            observe("write-back completion");
            step("post-write-back line-read request");
            @(negedge clk);
            memRd = 0;
            step("entered refill wait");
            repeat (2) @(posedge clk);
            observe("delayed refill");
        end

        @(negedge clk);
        memRd = 1;
        observe("data refill response");
        @(posedge clk);
        #1;
        DMhit = 1;
        memRd = 0;
        observe("data filled; pending instruction miss");
        step("instruction read wait");
        repeat (2) @(posedge clk);
        observe("instruction request held");
        @(negedge clk);
        MO = 64'hFACE_B00C_55AA_AA55;
        memRd = 1;
        observe("instruction refill response");
        @(posedge clk);
        #1;
        IMhit = 1;
        memRd = 0;
        observe("requests complete after both fills");
        @(negedge clk);
        re = 0;
        we = 0;
        fetch = 0;
        step("idle after miss sequence");
    end
endtask

initial begin
    rst_n = 0;
    re = 0;
    we = 0;
    fetch = 0;
    IMhit = 0;
    DMhit = 0;
    d_dirty = 0;
    memRd = 0;
    d_tag = 0;
    iaddr = 0;
    daddr = 0;
    writeData = 0;
    IO = 64'hFEDC_BA98_7654_3210;
    DO = 64'h1357_2468_9ABC_DEF0;
    MO = 64'h0123_4567_89AB_CDEF;

    // Wait 100 ns for global reset to finish.
    #100;
    observe("initial reset");

    // Local request combinations and all word positions.
    for (n = 0; n < 8; n = n + 1) begin
        reset_case;
        for (offset = 0; offset < 4; offset = offset + 1) begin
            @(negedge clk);
            re = n[0];
            we = n[1];
            fetch = n[2];
            iaddr = 16'h0000 + offset;
            daddr = 16'hFFFC + offset;
            writeData = offset[0] ? 16'hFFFF : 16'h0000;
            step("local request / word offset");
        end
    end

    // Clean data read and write refills, including re+we.
    data_miss(0, 0, 0, 16'h0000, 8'h00);
    for (offset = 0; offset < 4; offset = offset + 1) begin
        #1;
        data_miss(1, 0, offset[0], 16'hFFFC + offset, 8'hFF);
    end

    // Dirty victim address boundaries and mixed tag/index.
    data_miss(0, 1, 0, 16'h0000, 8'h00);
    data_miss(1, 1, 1, 16'hFFFF, 8'hFF);
    data_miss(0, 1, 0, 16'hA594, 8'h3C);

    // Instruction-only miss and instruction miss with data write hit.
    for (n = 0; n < 2; n = n + 1) begin
        reset_case;
        @(negedge clk);
        fetch = 1;
        IMhit = 0;
        we = n[0];
        iaddr = n[0] ? 16'hFFFF : 16'h0000;
        observe("instruction miss launch");
        step("instruction wait entered");
        repeat (2) @(posedge clk);
        observe("instruction response delayed");
        @(negedge clk);
        memRd = 1;
        observe("instruction response");
        @(posedge clk);
        #1;
        IMhit = 1;
        memRd = 0;
        observe("instruction complete / local write resumes");
    end

    // Withdraw a data miss; exercise both response branches.
    for (n = 0; n < 2; n = n + 1) begin
        reset_case;
        @(negedge clk);
        re = 1;
        DMhit = 0;
        observe("withdrawal case launch");
        step("withdrawal case waiting");
        @(negedge clk);
        re = 0;
        memRd = n[0];
        observe("request removed during read wait");
        @(posedge clk);
        #1;
        memRd = 0;
        observe("idle after request removal");
    end

    // Interrupt idle, refill wait, dirty wait, and post-write-back.
    for (state_case = 0; state_case < 4;
         state_case = state_case + 1) begin
        reset_case;
        @(negedge clk);
        we = 1;
        DMhit = (state_case == 0);
        d_dirty = (state_case >= 2);
        observe("reset interruption setup");
        step("reset interruption target");
        if (state_case == 3) begin
            @(negedge clk);
            memRd = 1;
            step("post-write-back before reset");
        end

        #1;
        rst_n = 0;
        observe("asynchronous reset with request active");
        @(negedge clk);
        we = 0;
        memRd = 0;
        DMhit = 1;
        observe("reset with requests cleared");
        @(posedge clk);
        observe("reset held across clock");
        @(negedge clk);
        rst_n = 1;
        step("idle after interrupted-operation reset");
    end

    $display("===========End===========");
    $finish;
end

endmodule

