module testbench;

// Inputs
reg clk;
reg [4:0] FS;
reg [31:0] S, T;

// Outputs
wire N, Z, V, C;
wire [31:0] Y_hi, Y_lo;

integer op, i;
reg [31:0] boundary [0:17];

// Instantiate the Unit Under Test (UUT)
MIPS_32 uut (
    .FS(FS), .S(S), .T(T),
    .N(N), .Z(Z), .V(V), .C(C),
    .Y_hi(Y_hi), .Y_lo(Y_lo)
);

// clk toggle generate
initial clk = 0; //clk is initialized as 0
always #5 clk = ~clk;

task sample;
    input [4:0] fn;
    input [31:0] s_value, t_value;
    begin
        FS = fn;
        S = s_value;
        T = t_value;
        #1;
        $display("FS=%02h S=%08h T=%08h N=%b Z=%b V=%b C=%b Y_hi=%08h Y_lo=%08h",
                 FS, S, T, N, Z, V, C, Y_hi, Y_lo);
    end
endtask

task logic_vectors;
    input [4:0] fn;
    begin
        sample(fn, 32'h00000000, 32'h00000000);
        sample(fn, 32'hffffffff, 32'hffffffff);
        sample(fn, 32'haaaaaaaa, 32'h55555555);
        sample(fn, 32'h55555555, 32'haaaaaaaa);
        sample(fn, 32'haaaaaaaa, 32'haaaaaaaa);
        sample(fn, 32'h00000000, 32'hffffffff);
        sample(fn, 32'hffffffff, 32'h00000000);
        sample(fn, 32'h00000001, 32'h00000001);
        sample(fn, 32'h80000000, 32'h80000000);
        sample(fn, 32'h00008001, 32'h00008001);
        sample(fn, 32'h00008001, 32'hffff8001);
        sample(fn, 32'h00000000, 32'hffff0000);
        sample(fn, 32'h12345678, 32'h00007fff);
        sample(fn, 32'h12345678, 32'hffff7fff);
    end
endtask

initial begin
    // Initialize Inputs
    FS = 5'h00;
    S = 32'h00000000;
    T = 32'h00000000;
    boundary[0]  = 32'h00000000;
    boundary[1]  = 32'h00000001;
    boundary[2]  = 32'h00000002;
    boundary[3]  = 32'h00000003;
    boundary[4]  = 32'h00000004;
    boundary[5]  = 32'h00000005;
    boundary[6]  = 32'h40000000;
    boundary[7]  = 32'h7ffffffb;
    boundary[8]  = 32'h7ffffffc;
    boundary[9]  = 32'h7ffffffd;
    boundary[10] = 32'h7fffffff;
    boundary[11] = 32'h80000000;
    boundary[12] = 32'h80000001;
    boundary[13] = 32'h80000003;
    boundary[14] = 32'h80000004;
    boundary[15] = 32'hfffffffb;
    boundary[16] = 32'hfffffffc;
    boundary[17] = 32'hffffffff;

    // Wait 100 ns for global reset to finish (DUT has no reset).
    #100;

    // Test Case 1: pass-through, arithmetic, and comparisons.
    for (op = 0; op <= 7; op = op + 1) begin
        #1;
        sample(op, 32'h00000000, 32'h00000000);
        sample(op, 32'h00000000, 32'h00000001);
        sample(op, 32'h00000001, 32'h00000000);
        sample(op, 32'h00000001, 32'h00000002);
        sample(op, 32'h00000002, 32'h00000001);
        sample(op, 32'h00000001, 32'h00000001);
        sample(op, 32'h7fffffff, 32'h00000001);
        sample(op, 32'h80000000, 32'hffffffff);
        sample(op, 32'h80000000, 32'h80000000);
        sample(op, 32'hffffffff, 32'hffffffff);
        sample(op, 32'hffffffff, 32'h00000001);
        sample(op, 32'h7fffffff, 32'hffffffff);
        sample(op, 32'h80000000, 32'h00000001);
        sample(op, 32'h80000000, 32'h00000000);
        sample(op, 32'h00000000, 32'h80000000);
        sample(op, 32'h80000001, 32'h00000000);
        sample(op, 32'hffffffff, 32'h80000000);
        sample(op, 32'h00000001, 32'hffffffff);
        sample(op, 32'h12345678, 32'h87654321);
    end

    // Test Case 2: Boolean and immediate operations.
    for (op = 8; op <= 11; op = op + 1) begin
        #1;
        logic_vectors(op);
    end
    for (op = 22; op <= 25; op = op + 1) begin
        #1;
        logic_vectors(op);
    end

    // Test Case 3: shifts and increment/decrement boundaries.
    for (op = 12; op <= 18; op = op + 1) begin
        #1;
        for (i = 0; i < 18; i = i + 1) begin
            #1;
            sample(op, boundary[i], boundary[i]);
        end
        sample(op, 32'h12345678, 32'h87654321);
        sample(op, 32'h12345678, 32'h55555555);
        sample(op, 32'haaaaaaaa, 32'h55555555);
    end

    // Test Case 4: constants, unsupported selectors, and recovery.
    for (op = 19; op <= 21; op = op + 1) begin
        #1;
        sample(op, 32'h00000000, 32'hffffffff);
        sample(op, 32'hffffffff, 32'h00000000);
    end
    for (op = 26; op <= 31; op = op + 1) begin
        #1;
        sample(op, 32'h00000000, 32'hffffffff);
        sample(op, 32'hffffffff, 32'h00000000);
        sample(5'h00, 32'h00000000, 32'h12345678);
    end

    $display("===========End===========");
    $finish;
end

endmodule

