                 m_axis_1_tdata, m_axis_1_tkeep, m_axis_1_tuser,
                 m_axis_1_tvalid, m_axis_1_tlast,
                 m_axis_2_tdata, m_axis_2_tkeep, m_axis_2_tuser,
                 m_axis_2_tvalid, m_axis_2_tlast,
                 m_axis_3_tdata, m_axis_3_tkeep, m_axis_3_tuser,
                 m_axis_3_tvalid, m_axis_3_tlast);
    end
endtask

task reset_dut;
    begin
        @(negedge axis_aclk);
        axis_resetn = 0;
        s_axis_tvalid = 0;
        s_axis_tlast = 0;
        s_axis_tdata = 0;
        s_axis_tkeep = 0;
        s_axis_tuser = 0;

        m_axis_0_tready = 1;
        m_axis_1_tready = 1;
        m_axis_2_tready = 1;
        m_axis_3_tready = 1;

        repeat (2) @(posedge axis_aclk);

        @(negedge axis_aclk);
        axis_resetn = 1;
        repeat (1) @(posedge axis_aclk);
    end
endtask

task set_route_ready;
    input integer route_id;
    input ready_value;
    begin
        m_axis_0_tready = 1;
        m_axis_1_tready = 1;
        m_axis_2_tready = 1;
        m_axis_3_tready = 1;

        case (route_id)
            1: m_axis_0_tready = ready_value;
            2: m_axis_1_tready = ready_value;
            3: m_axis_2_tready = ready_value;
            4: m_axis_3_tready = ready_value;
            default: begin
                m_axis_0_tready = ready_value;
                m_axis_1_tready = ready_value;
                m_axis_2_tready = ready_value;
                m_axis_3_tready = ready_value;
            end
        endcase
    end
endtask

task drive_beat;
    input integer marker;
    input integer route_id;
    input [15:0] protocol_id;
    input last_value;
    input valid_value;
    begin
        @(negedge axis_aclk);

        s_axis_tdata = 256'b0;

        /*
         * vlan_info_id = {vlan_info[3:0], vlan_info[15:8]}.
         * Therefore:
         *   route_id[11:8] -> s_axis_tdata[115:112]
         *   route_id[7:0]  -> s_axis_tdata[127:120]
         */
        s_axis_tdata[127:96] = {
            route_id[7:0],
            4'b0000,
            route_id[11:8],
            protocol_id
        };

        s_axis_tdata[31:0] = marker;
        s_axis_tkeep = 32'hffff_ffff;
        s_axis_tuser = marker;
        s_axis_tvalid = valid_value;
        s_axis_tlast = last_value;

        @(posedge axis_aclk);
    end
endtask

integer route_index;

initial begin
    axis_resetn = 0;
    s_axis_tdata = 0;
    s_axis_tkeep = 0;
    s_axis_tuser = 0;
    s_axis_tvalid = 0;
    s_axis_tlast = 0;

    m_axis_0_tready = 1;
    m_axis_1_tready = 1;
    m_axis_2_tready = 1;
    m_axis_3_tready = 1;

    S_AXI_ACLK = 0;
    S_AXI_ARESETN = 0;

    // TP1: synchronous reset and idle state
    reset_dut;
    observe(1);

    // TP2: valid packet forwarding for all four route identifiers
    for (route_index = 1; route_index <= 4; route_index = route_index + 1) begin
        reset_dut;

        drive_beat(100 + route_index, route_index, 16'h0081, 1'b0, 1'b1);
        observe(20 + route_index * 10);

        drive_beat(200 + route_index, route_index, 16'h0081, 1'b0, 1'b1);
        observe(21 + route_index * 10);

        drive_beat(300 + route_index, route_index, 16'h0081, 1'b1, 1'b1);
        observe(22 + route_index * 10);

        drive_beat(400 + route_index, route_index, 16'h0081, 1'b0, 1'b0);
        observe(23 + route_index * 10);
    end

    // TP3: invalid protocol
    reset_dut;

    drive_beat(501, 12'h001, 16'h0000, 1'b0, 1'b1);
    observe(51);

    drive_beat(502, 12'h001, 16'h0000, 1'b0, 1'b1);
    observe(52);

    drive_beat(503, 12'h001, 16'h0000, 1'b0, 1'b0);
    observe(53);

    // TP4: invalid route identifier
    reset_dut;

    drive_beat(601, 12'h005, 16'h0081, 1'b0, 1'b1);
    observe(61);

    drive_beat(602, 12'h005, 16'h0081, 1'b0, 1'b1);
    observe(62);

    drive_beat(603, 12'h005, 16'h0081, 1'b0, 1'b0);
    observe(63);

    // TP5: end indication overrides invalid protocol/route decision
    reset_dut;

    drive_beat(701, 12'h001, 16'h0000, 1'b0, 1'b1);
    observe(71);

    drive_beat(702, 12'h001, 16'h0000, 1'b1, 1'b1);
    observe(72);

    drive_beat(703, 12'h001, 16'h0000, 1'b0, 1'b1);
    observe(73);

    // TP6: selected output backpressure discards the skipped beat
    reset_dut;
    m_axis_2_tready = 0;

    drive_beat(801, 12'h003, 16'h0081, 1'b0, 1'b1);
    observe(81);

    drive_beat(802, 12'h003, 16'h0081, 1'b0, 1'b1);
    observe(82);

    m_axis_2_tready = 1;

    drive_beat(803, 12'h003, 16'h0081, 1'b1, 1'b1);
    observe(83);

    drive_beat(804, 12'h003, 16'h0081, 1'b0, 1'b0);
    observe(84);

    // TP7: invalid input valid and initial last in WAIT_PKT
    reset_dut;

    drive_beat(901, 12'h004, 16'h0081, 1'b0, 1'b0);
    observe(91);

    drive_beat(902, 12'h004, 16'h0081, 1'b1, 1'b1);
    observe(92);

    drive_beat(903, 12'h004, 16'h0081, 1'b0, 1'b0);
    observe(93);

    // TP8: one valid first beat with tlast asserted during WAIT_PKT
    reset_dut;

    drive_beat(1001, 12'h001, 16'h0081, 1'b1, 1'b1);
    observe(101);

    drive_beat(1002, 12'h001, 16'h0081, 1'b0, 1'b0);
    observe(102);

    drive_beat(1003, 12'h001, 16'h0081, 1'b0, 1'b0);
    observe(103);

    /*
     * TP9: selected output not ready in both write states.
     *
     * The first beat is captured in WAIT_PKT.
     * The second beat is processed in WRITE_PKT_BEG.
     * The third beat is processed in WRITE_PKT_END.
     * The selected output remains unready, exercising the false
     * branches in both alternating routing states for every route.
     */
    for (route_index = 1; route_index <= 4; route_index = route_index + 1) begin
        reset_dut;
        set_route_ready(route_index, 1'b0);

        drive_beat(1100 + route_index, route_index, 16'h0081, 1'b0, 1'b1);
        observe(110 + route_index * 10);

        drive_beat(1200 + route_index, route_index, 16'h0081, 1'b0, 1'b1);
        observe(111 + route_index * 10);

        drive_beat(1300 + route_index, route_index, 16'h0081, 1'b1, 1'b1);
        observe(112 + route_index * 10);

        /*
         * Deasserting tlast after the END-state last beat causes
         * WRITE_PKT_END -> WRITE_PKT_BEG, followed by the saved-end
         * completion path in WRITE_PKT_BEG.
         */
        drive_beat(1400 + route_index, route_index, 16'h0081, 1'b0, 1'b0);
        observe(113 + route_index * 10);
    end

    /*
     * TP10: explicitly exercise END-state end handling with a
     * ready-selected output.  The last indication is asserted while
     * the controller is in WRITE_PKT_END, forcing the transition
     * WRITE_PKT_END -> WRITE_PKT_BEG.
     */
    reset_dut;
    set_route_ready(4, 1'b1);

    drive_beat(1501, 12'h004, 16'h0081, 1'b0, 1'b1);
    observe(151);

    drive_beat(1502, 12'h004, 16'h0081, 1'b0, 1'b1);
    observe(152);

    drive_beat(1503, 12'h004, 16'h0081, 1'b1, 1'b1);
    observe(153);

    drive_beat(1504, 12'h004, 16'h0081, 1'b0, 1'b0);
    observe(154);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam BIT_CLOCKS = 16;

// Inputs
reg clk;
reg Reset, Enable, RxD, RD;

// Outputs
wire FErr, OErr, DRdy;
wire [7:0] DataIn;

integer i;
reg [7:0] payload;

// Instantiate the Unit Under Test (UUT)
RxUnit uut (
    .Clk(clk),
    .Reset(Reset),
    .Enable(Enable),
    .RxD(RxD),
    .RD(RD),
    .FErr(FErr),
    .OErr(OErr),
    .DRdy(DRdy),
    .DataIn(DataIn)
);

// clk toggle generate
initial clk = 0; //clk is initialized as 0
always #5 clk = ~clk;

task clocks;
    input integer count;
    begin
        repeat (count) @(posedge clk);
        #1;
    end
endtask

task observe;
    input [8*64-1:0] label;
    begin
        $display("%0t %0s FErr=%b OErr=%b DRdy=%b DataIn=%02h",
                 $time, label, FErr, OErr, DRdy, DataIn);
    end
endtask

task reset_dut;
    begin
        @(negedge clk);
        Reset = 0;
        Enable = 0;
        RD = 1;
        RxD = 0;
        #1;
        observe("reset asserted before rising edge");
        clocks(2);
        observe("reset sampled, Enable=0 RD=1");
        @(negedge clk);
        Reset = 1;
        Enable = 1;
        RD = 0;
        RxD = 1;
        clocks(2);
    end
endtask

task hold_line;
    input level;
    input integer count;
    begin
        @(negedge clk);
        RxD = level;
        clocks(count);
    end
endtask

task acknowledge;
    begin
        @(negedge clk);
        RD = 1;
        clocks(1);
        observe("read acknowledgement");
        @(negedge clk);
        RD = 0;
        clocks(2);
        observe("after acknowledgement");
    end
endtask

// shape changes data only outside its midpoint window.
task send_frame;
    input [7:0] data;
    input stop_level;
    input shape;
    input pause_data;
    input boundary_rd;
    integer bit_index;
    begin
        hold_line(0, BIT_CLOCKS);
        for (bit_index = 0; bit_index < 8; bit_index = bit_index + 1) begin
            @(negedge clk);
            RxD = data[bit_index];
            if (pause_data && bit_index == 3) begin
                clocks(8);
                @(negedge clk);
                Enable = 0;
                RD = 1;
                RxD = ~data[bit_index];
                clocks(5);
                observe("paused data bit, RD asserted");
                @(negedge clk);
                RxD = data[bit_index];
                RD = 0;
                clocks(5);
                observe("paused data bit, RD released");
                @(negedge clk);
                Enable = 1;
                clocks(8);
            end
            else if (shape) begin
                RxD = ~data[bit_index];
                clocks(4);
                @(negedge clk);
                RxD = data[bit_index];
                clocks(8);
                @(negedge clk);
                RxD = ~data[bit_index];
                clocks(4);
            end
            else begin
                clocks(BIT_CLOCKS);
            end
        end
        hold_line(stop_level, BIT_CLOCKS - 1);
        observe("stop bit before nominal final edge");
        @(negedge clk);
        RD = boundary_rd;
        clocks(1);
        observe("nominal final stop-bit edge");
        @(negedge clk);
        RxD = 1;
        RD = 0;
        clocks(2);
        observe("frame settling interval");
    end
endtask

initial begin
    // Initialize Inputs
    Reset = 0;
    Enable = 0;
    RxD = 1;
    RD = 0;

    // Wait 100 ns for global reset to finish
    #100;
    observe("initial reset");

    // Test Case 1: idle, disabled acquisition, false start.
    reset_dut;
    clocks(20);
    observe("enabled idle high");
    @(negedge clk);
    Enable = 0;
    RxD = 0;
    clocks(20);
    observe("disabled low input");
    @(negedge clk);
    RxD = 1;
    Enable = 1;
    clocks(2);
    hold_line(0, 3);
    hold_line(1, 20);
    observe("short start pulse rejected");
    send_frame(8'h96, 1, 0, 0, 0);

    // Test Case 2: payload patterns and midpoint sampling.
    for (i = 0; i < 7; i = i + 1) begin
        reset_dut;
        case (i)
            0: payload = 8'h00;
            1: payload = 8'hFF;
            2: payload = 8'h55;
            3: payload = 8'hAA;
            4: payload = 8'h01;
            5: payload = 8'h80;
            6: payload = 8'h69;
        endcase
        send_frame(payload, 1, (i == 6), 0, 0);
        acknowledge;
        clocks(3);
    end

    // Test Case 3: framing, overrun, retention and recovery.
    reset_dut;
    send_frame(8'h35, 0, 0, 0, 0);
    clocks(20);
    observe("framing status retained while idle");
    send_frame(8'hCA, 0, 0, 0, 0);
    acknowledge;
    clocks(20);
    observe("error status retained after read");
    send_frame(8'h12, 1, 0, 0, 0);
    send_frame(8'hE7, 1, 0, 0, 0);
    acknowledge;
    send_frame(8'h48, 1, 0, 0, 0);

    // Test Case 4: pause active reception and acknowledge old data.
    reset_dut;
    send_frame(8'hA3, 0, 0, 0, 0);
    send_frame(8'h5C, 1, 0, 1, 0);
    acknowledge;

    // Test Case 5: RD at nominal completion, empty and unread cases.
    for (i = 0; i < 2; i = i + 1) begin
        reset_dut;
        if (i == 1)
            send_frame(8'h27, 1, 0, 0, 0);
        send_frame(8'hD8, 1, 0, 0, 1);
        clocks(3);
        observe("ready retention after boundary acknowledgement");
    end

    // Test Case 6: reset pending status and abort a partial frame.
    reset_dut;
    send_frame(8'h31, 1, 0, 0, 0);
    send_frame(8'hC2, 0, 0, 0, 0);
    reset_dut;
    hold_line(0, BIT_CLOCKS);
    hold_line(1, BIT_CLOCKS);
    hold_line(0, 7);
    observe("partial reception before reset");
    reset_dut;
    clocks(12 * BIT_CLOCKS);
    observe("idle after aborted reception");
    send_frame(8'hB6, 1, 0, 0, 0);
    acknowledge;

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam TLB_ENTRIES = 4;
localparam ASID_WIDTH = 9;
localparam [31:0] A = 32'h00401000;
localparam [31:0] B = 32'h00402000;
localparam [31:0] C = 32'h00803000;
localparam [31:0] D = 32'h00c04000;
localparam [31:0] E = 32'h01005000;

// Inputs
reg clk;
reg rst_ni, flush_i, lu_access_i;
reg [62:0] update_i;
reg [ASID_WIDTH-1:0] lu_asid_i, asid_to_be_flushed_i;
reg [31:0] lu_vaddr_i, vaddr_to_be_flushed_i;

// Outputs
wire [31:0] lu_content_o;
wire lu_is_4M_o, lu_hit_o;
wire [127:0] port_content_q_o;
wire [123:0] port_tags_q_o;
wire [TLB_ENTRIES-1:0] port_replace_en_o;

reg [31:0] entry_addr [0:3];
reg [8:0] entry_asid [0:3];
reg [31:0] entry_data [0:3];
reg entry_large [0:3];
reg [8:0] flush_asid [0:2];
reg [31:0] flush_addr [0:6];
integer tc, i, j;

cva6_tlb_sv32 #(
    .TLB_ENTRIES(TLB_ENTRIES),
    .ASID_WIDTH(ASID_WIDTH)
) uut (
    .clk_i(clk),
    .rst_ni(rst_ni),
    .flush_i(flush_i),
    .update_i(update_i),
    .lu_access_i(lu_access_i),
    .lu_asid_i(lu_asid_i),
    .lu_vaddr_i(lu_vaddr_i),
    .lu_content_o(lu_content_o),
    .asid_to_be_flushed_i(asid_to_be_flushed_i),
    .vaddr_to_be_flushed_i(vaddr_to_be_flushed_i),
    .lu_is_4M_o(lu_is_4M_o),
    .lu_hit_o(lu_hit_o),
    .port_content_q_o(port_content_q_o),
    .port_tags_q_o(port_tags_q_o),
    .port_replace_en_o(port_replace_en_o)
);

initial clk = 0; //clk is initialized as 0
always #5 clk = ~clk;

function [62:0] payload;
    input valid_request, large_page;
    input [8:0] asid;
    input [31:0] address, content;
    begin
        payload = {valid_request, large_page, address[31:22],
                   address[21:12], asid, content};
    end
endfunction

task observe;
    input [8*32-1:0] label;
    begin
        $display("tc=%0d t=%0t %0s rst_n=%b flush=%b update=%h access=%b lookup_asid=%h lookup_va=%h flush_asid=%h flush_va=%h lu_hit_o=%b lu_is_4M_o=%b lu_content_o=%h port_content_q_o=%h port_tags_q_o=%h port_replace_en_o=%b",
                 tc, $time, label, rst_ni, flush_i, update_i,
                 lu_access_i, lu_asid_i, lu_vaddr_i,
                 asid_to_be_flushed_i, vaddr_to_be_flushed_i,
                 lu_hit_o, lu_is_4M_o, lu_content_o,
                 port_content_q_o, port_tags_q_o, port_replace_en_o);
    end
endtask

task reset_dut;
    begin
        @(negedge clk);
        flush_i = 0;
        update_i = 0;
        lu_access_i = 0;
        lu_asid_i = 0;
        lu_vaddr_i = 0;
        asid_to_be_flushed_i = 0;
        vaddr_to_be_flushed_i = 0;
        #2 rst_ni = 0;
        #1 observe("asynchronous_reset");
        repeat (2) @(posedge clk);
        #1 observe("reset_held");
        @(negedge clk);
        rst_ni = 1;
        #1 observe("reset_released");
    end
endtask

task lookup;
    input [8:0] asid;
    input [31:0] address;
    input access_enable;
    begin
        @(negedge clk);
        lu_asid_i = asid;
        lu_vaddr_i = address;
        lu_access_i = access_enable;
        #1 observe("lookup_combinational");
        @(posedge clk);
        #1 observe("lookup_after_edge");
        @(negedge clk);
        lu_access_i = 0;
    end
endtask

task install;
    input valid_request, large_page;
    input [8:0] asid;
    input [31:0] address, content;
    begin
        @(negedge clk);
        lu_access_i = 0;
        update_i = payload(valid_request, large_page, asid,
                           address, content);
        #1 observe("update_before_edge");
        @(posedge clk);
        #1 observe("update_after_edge");
        @(negedge clk);
        update_i = 0;
    end
endtask

task seed_entries;
    integer k;
    begin
        reset_dut;
        for (k = 0; k < 4; k = k + 1) begin
            #1;
            install(1, entry_large[k], entry_asid[k],
                    entry_addr[k], entry_data[k]);
            lookup(entry_asid[k], entry_addr[k], 1);
        end
    end
endtask

task probe_entries;
    input access_enable;
    integer k;
    begin
        for (k = 0; k < 4; k = k + 1) begin
            #1;
            lookup(entry_asid[k], entry_addr[k], access_enable);
        end
    end
endtask

task flush_entries;
    input [8:0] asid;
    input [31:0] address;
    input access_enable;
    begin
        @(negedge clk);
        flush_i = 1;
        asid_to_be_flushed_i = asid;
        vaddr_to_be_flushed_i = address;
        update_i = payload(1, 0, 9'h001, E, 32'h55550001);
        lu_asid_i = 9'h001;
        lu_vaddr_i = A;
        lu_access_i = access_enable;
        #1 observe("flush_before_edge");
        @(posedge clk);
        #1 observe("flush_after_edge");
        @(negedge clk);
        flush_i = 0;
        update_i = 0;
        lu_access_i = 0;
        #1 observe("flush_released");
    end
endtask

task simultaneous_update_access;
    input [8:0] lookup_asid;
    input [31:0] lookup_address;
    begin
        @(negedge clk);
        lu_asid_i = lookup_asid;
        lu_vaddr_i = lookup_address;
        lu_access_i = 1;
        update_i = payload(1, 0, 9'h001, E, 32'h55550001);
        #1 observe("update_access_before_edge");
        @(posedge clk);
        #1 observe("update_access_after_edge");
        @(negedge clk);
        update_i = 0;
        lu_access_i = 0;
    end
endtask

initial begin
    // Initialize Inputs
    rst_ni = 0;
    flush_i = 0;
    update_i = 0;
    lu_access_i = 0;
    lu_asid_i = 0;
    lu_vaddr_i = 0;
    asid_to_be_flushed_i = 0;
    vaddr_to_be_flushed_i = 0;
    tc = 0;

    entry_addr[0] = A; entry_asid[0] = 9'h001;
    entry_addr[1] = A; entry_asid[1] = 9'h101;
    entry_addr[2] = C; entry_asid[2] = 9'h001;
    entry_addr[3] = D; entry_asid[3] = 9'h101;
    entry_data[0] = 32'h11110001; entry_large[0] = 0;
    entry_data[1] = 32'h22220001; entry_large[1] = 0;
    entry_data[2] = 32'h33330001; entry_large[2] = 1;
    entry_data[3] = 32'h44440021; entry_large[3] = 0;

    flush_asid[0] = 9'h000;
    flush_asid[1] = 9'h001;
    flush_asid[2] = 9'h101;
    flush_addr[0] = 0;
    flush_addr[1] = A + 32'hfff;
    flush_addr[2] = B + 32'hfff;
    flush_addr[3] = C + 32'hfff;
    flush_addr[4] = 32'h00bfffff;
    flush_addr[5] = D + 32'hfff;
    flush_addr[6] = 32'hffffffff;

    // Wait 100 ns for global reset to finish
    #100;
    observe("initial_reset");

    // Test Case 1: empty, disabled updates, 4 KiB boundaries, ASIDs.
    tc = 1;
    reset_dut;
    lookup(9'h000, 32'h00000000, 1);
    install(0, 1, 9'h1ff, A, 32'hffffffff);
    lookup(9'h1ff, A, 1);
    install(1, 0, 9'h000, 32'h00000000, 32'h00000000);
    lookup(9'h000, 32'h00000000, 0);
    lookup(9'h000, 32'h00000fff, 0);
    lookup(9'h001, 32'h00000000, 0);
    lookup(9'h000, 32'h00001000, 0);
    lookup(9'h000, 32'h00400000, 0);
    install(1, 0, 9'h1ff, 32'hfffff000, 32'hffffffdf);
    lookup(9'h1ff, 32'hffffffff, 0);
    lookup(9'h0ff, 32'hffffffff, 0);
    lookup(9'h1ff, 32'hffffefff, 0);
    lookup(9'h1ff, 32'hffbfffff, 0);
    lookup(9'h000, 32'h00000000, 0);
    install(0, 1, 9'h000, A, 32'hffffffff);
    lookup(9'h1ff, 32'hfffff000, 0);

    // Test Case 2: 4 MiB endpoint regions and ASID matching.
    tc = 2;
    reset_dut;
    install(1, 1, 9'h101, 32'h00000000, 32'h80000001);
    lookup(9'h101, 32'h00000000, 0);
    lookup(9'h101, 32'h003fffff, 0);
    lookup(9'h101, 32'h00400000, 0);
    lookup(9'h001, 32'h00000000, 0);
    install(1, 1, 9'h1ff, 32'hfffff000, 32'hffffffdf);
    lookup(9'h1ff, 32'hffc00000, 0);
    lookup(9'h1ff, 32'hffffffff, 0);
    lookup(9'h1ff, 32'hffbfffff, 0);

    // Test Cases 3-4: global mappings and flush protection.
    for (i = 0; i < 2; i = i + 1) begin
        #1;
        tc = 3 + i;
        reset_dut;
        install(1, i, 9'h101, A, 32'hffffffff);
        lookup(9'h000, A + 32'hfff, 0);
        lookup(9'h1ff, A, 1);
        lookup(9'h001, B + 32'hfff, 0);
        lookup(9'h001, C, 0);
        flush_entries(9'h101, A + 32'hfff, 0);
        lookup(9'h001, A, 0);
        flush_entries(9'h101, 32'h00000000, 0);
        lookup(9'h001, A, 0);
        flush_entries(9'h000, B + 32'hfff, 0);
        lookup(9'h001, A, 0);
        lookup(9'h001, B, 0);
        flush_entries(9'h000, A + 32'hfff, 0);
        lookup(9'h001, A, 0);
    end

    // Test Case 5: replacement paths, access qualification, concurrent update.
    tc = 5;
    seed_entries;
    probe_entries(0);
    lookup(9'h001, E, 1);
    probe_entries(1);
    for (i = 3; i >= 0; i = i - 1) begin
        #1;
        lookup(entry_asid[i], entry_addr[i], 1);
        lookup(entry_asid[i], entry_addr[i], 1);
    end
    simultaneous_update_access(9'h001, A);
    probe_entries(0);
    lookup(9'h001, E, 0);

    // Test Case 6: access and replacement of the same installed entry.
    tc = 6;
    reset_dut;
    install(1, 0, 9'h001, A, 32'h11110001);
    simultaneous_update_access(9'h001, A);
    lookup(9'h001, A, 0);
    lookup(9'h001, E, 0);

    // Test Cases 100-120: independent flush-selector matrix.
    for (i = 0; i < 3; i = i + 1) begin
        #1;
        for (j = 0; j < 7; j = j + 1) begin
            #1;
            tc = 100 + i * 7 + j;
            seed_entries;
            flush_entries(flush_asid[i], flush_addr[j], 0);
            probe_entries(0);
            lookup(9'h1ff, D, 0);
            lookup(9'h001, E, 0);
        end
    end

    // Test Case 121: absent ASID, then concurrent flush/access and refill.
    tc = 121;
    seed_entries;
    flush_entries(9'h1ff, 32'h00000000, 0);
    probe_entries(0);
    flush_entries(9'h1ff, A, 0);
    probe_entries(0);
    flush_entries(9'h000, 32'h00000000, 1);
    probe_entries(0);
    lookup(9'h001, E, 0);
    install(1, 0, 9'h001, E, 32'h55550001);
    lookup(9'h001, E, 1);

    // Test Cases 130-131: overlapping page sizes in both installation orders.
    for (i = 0; i < 2; i = i + 1) begin
        #1;
        tc = 130 + i;
        reset_dut;
        install(1, i, 9'h001, A, 32'h11110001);
        lookup(9'h001, A, 1);
        install(1, 1-i, 9'h001, A, 32'h22220001);
        lookup(9'h001, A + 32'hfff, 0);
        lookup(9'h001, A, 1);
        lookup(9'h001, B, 1);
        flush_entries(9'h000, A + 32'hfff, 0);
        lookup(9'h001, A, 0);
        lookup(9'h001, B, 0);
    end

    // Test Case 140: asynchronous reset with active requests.
    tc = 140;
    seed_entries;
    @(negedge clk);
    flush_i = 1;
    asid_to_be_flushed_i = 0;
    vaddr_to_be_flushed_i = 0;
    update_i = payload(1, 0, 9'h001, E, 32'h55550001);
    lu_asid_i = 9'h001;
    lu_vaddr_i = A;
    lu_access_i = 1;
    #2 rst_ni = 0;
    #1 observe("reset_active_requests");
    repeat (2) @(posedge clk);
    #1 observe("reset_requests_held");
    @(negedge clk);
    flush_i = 0;
    update_i = 0;
    lu_access_i = 0;
    rst_ni = 1;
    #1 observe("reset_requests_released");
    probe_entries(0);
    lookup(9'h001, E, 0);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

reg clk;
reg rd_rst_n;
reg rd_en;
reg init_end;
reg [23:0] rd_addr;
reg [15:0] rd_data;
reg [9:0] rd_burst_len;

wire rd_end;
wire rd_ack;
wire [3:0] rd_sdram_cmd;
wire [12:0] rd_sdram_addr;
wire [1:0] rd_sdram_bank;
wire [15:0] rd_sdram_data;

integer phase;
integer phase_cycles;
integer short_len;

sdram_read uut (
    .rd_clk        (clk),
    .rd_rst_n      (rd_rst_n),
    .rd_en         (rd_en),
    .init_end      (init_end),
    .rd_addr       (rd_addr),
    .rd_data       (rd_data),
    .rd_burst_len  (rd_burst_len),
    .rd_end        (rd_end),
    .rd_ack        (rd_ack),
    .rd_sdram_cmd  (rd_sdram_cmd),
    .rd_sdram_addr (rd_sdram_addr),
    .rd_sdram_bank (rd_sdram_bank),
    .rd_sdram_data (rd_sdram_data)
);

initial clk = 0;
always #5 clk = ~clk;

task show_outputs;
    begin
        $display("time=%0t rd_end=%b rd_ack=%b cmd=%b addr=%h bank=%b data=%h",
                 $time, rd_end, rd_ack, rd_sdram_cmd, rd_sdram_addr,
                 rd_sdram_bank, rd_sdram_data);
    end
endtask

task cycle;
    begin
        @(posedge clk);
        #1;
        show_outputs;
    end
endtask

task run_cycles;
    input integer count;
    integer i;
    begin
        for (i = 0; i < count; i = i + 1) begin
            cycle;
        end
    end
endtask

task run_data_cycles;
    input integer count;
    input [15:0] first_data;
    integer i;
    begin
        for (i = 0; i < count; i = i + 1) begin
            rd_data = first_data + i;
            cycle;
        end
    end
endtask

task reset_dut;
    begin
        rd_en       = 1'b0;
        init_end    = 1'b0;
        rd_rst_n    = 1'b0;
        #2;
        show_outputs;
        rd_rst_n    = 1'b1;
        cycle;
    end
endtask

// Launch from idle with a one-clock request pulse.
// All following waits are fixed and independent of DUT outputs.
task launch_read;
    input [23:0] address;
    input [9:0] length;
    begin
        @(negedge clk);
        rd_addr      = address;
        rd_burst_len = length;
        rd_en        = 1'b1;
        init_end     = 1'b1;
        cycle;
        @(negedge clk);
        rd_en = 1'b0;
    end
endtask

// Complete a read using a conservative fixed-cycle budget.
// For default timings, completion occurs length+14 edges after launch.
task complete_read;
    input [23:0] address;
    input [9:0] length;
    input [15:0] first_data;
    integer cycle_budget;
    begin
        launch_read(address, length);
        cycle_budget = length + 20;
        run_data_cycles(cycle_budget, first_data);
    end
endtask

initial begin
    rd_rst_n     = 1'b0;
    rd_en        = 1'b0;
    init_end     = 1'b0;
    rd_addr      = 24'hA5C123;
    rd_data      = 16'h0000;
    rd_burst_len = 10'd8;

    #2;
    show_outputs;

    // Original: idle qualification and normal eight-beat transaction.
    rd_rst_n = 1'b1;
    rd_en    = 1'b1;
    init_end = 1'b0;
    run_cycles(2);

    init_end = 1'b1;
    run_data_cycles(30, 16'h1000);

    // Original: reset during an active transaction.
    reset_dut;
    rd_addr      = 24'h2D612A;
    rd_burst_len = 10'd8;
    rd_en        = 1'b1;
    init_end     = 1'b1;
    run_data_cycles(8, 16'h2000);

    rd_rst_n = 1'b0;
    #1;
    show_outputs;
    rd_rst_n = 1'b1;
    rd_en    = 1'b0;
    init_end = 1'b0;
    run_cycles(3);

    // Original: short three-beat burst.
    reset_dut;
    rd_addr      = 24'h7B03E1;
    rd_burst_len = 10'd3;
    rd_en        = 1'b1;
    init_end     = 1'b1;
    run_data_cycles(25, 16'h3000);

    // Original: boundary four-beat burst.
    reset_dut;
    rd_addr      = 24'hC4AA55;
    rd_burst_len = 10'd4;
    rd_en        = 1'b1;
    init_end     = 1'b1;
    run_data_cycles(26, 16'h4000);

    // Supplement idle qualification with all non-launch combinations.
    @(negedge clk);
    reset_dut;
    run_cycles(2);             // rd_en=0, init_end=0

    @(negedge clk);
    init_end = 1'b1;
    run_data_cycles(3, 16'h5500); // rd_en=0, init_end=1

    @(negedge clk);
    rd_en    = 1'b1;
    init_end = 1'b0;
    run_cycles(3);             // rd_en=1, init_end=0

    @(negedge clk);
    rd_en = 1'b0;
    complete_read(24'h000000, 10'd8, 16'hAA00);

    // Directed asynchronous resets at fixed phase entry offsets.
    // These offsets use the default TRCD=2, TCL=3, TRP=4 and length=8.
    // Every iteration includes explicit clock/delay time advancement.
    for (phase = 0; phase < 8; phase = phase + 1) begin
        @(negedge clk);
        reset_dut;

        case (phase)
            0: phase_cycles = 1;  // ACT
            1: phase_cycles = 2;  // TRCD
            2: phase_cycles = 4;  // RD_CMD
            3: phase_cycles = 5;  // CL
            4: phase_cycles = 8;  // DATA
            5: phase_cycles = 17; // PRE
            6: phase_cycles = 18; // TRP
            7: phase_cycles = 22; // END
            default: phase_cycles = 1;
        endcase

        @(negedge clk);
        // Sweep all four banks while keeping row/column nontrivial.
        rd_addr      = {phase[1:0], 13'h1555, 9'h12A};
        rd_burst_len = 10'd8;
        rd_data      = 16'h8000 + phase;
        rd_en        = 1'b1;
        init_end     = 1'b1;

        run_data_cycles(phase_cycles, 16'h6000);

        // Assert between edges, sample immediately, then hold through
        // a rising edge so reset behavior is also observed clocked.
        @(negedge clk);
        #1;
        rd_en    = 1'b0;
        init_end = 1'b0;
        rd_rst_n = 1'b0;
        #1;
        show_outputs;
        cycle;

        @(negedge clk);
        rd_rst_n = 1'b1;
        cycle;

        // Confirm recovery stimulus after every interrupted phase.
        complete_read({phase[1:0], 13'h1FFF, 9'h1FF},
                      10'd8, 16'h7000);
    end

    // Supplement short-burst boundaries, including zero data beats.
    for (short_len = 0; short_len < 3; short_len = short_len + 1) begin
        @(negedge clk);
        reset_dut;
        complete_read({short_len[1:0], 13'h0000, 9'h000},
                      short_len, 16'h9000);
    end

    // Maximum representable length: stable throughout the transaction.
    // Exercises the width-limited acknowledgement upper-bound addition.
    @(negedge clk);
    reset_dut;
    complete_read(24'hFFFFFF, 10'd1023, 16'hA000);

    // Finish with an ordinary burst after boundary characterization.
    complete_read(24'h9635A7, 10'd8, 16'hFF00);
    run_cycles(3);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam INICIO = 0, N1 = 1, N2 = 2, N3_LA = 3,
           N3_SI = 4, ADJ = 5, N4_DO = 6, N4_SI = 7,
           N4_RE = 8, COMP = 9, ADV = 10, ERRO = 11;
localparam [3:0] NULL1 = 4'h0, DO = 4'h1, RE = 4'h2,
                 NULL2 = 4'h8, LA_M = 4'he, SI_M = 4'hf;

// Inputs
reg clk;
reg reset;
reg ok;
reg [3:0] nota;

// Outputs
wire fim;
wire [1:0] tipo;
wire [3:0] estado_atual;

integer target, note_code, order;

Identificador uut (
    .clk(clk),
    .reset(reset),
    .ok(ok),
    .nota(nota),
    .fim(fim),
    .tipo(tipo),
    .estado_atual(estado_atual)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [8*48-1:0] label;
    begin
        $display("%0t %0s target=%0d note_code=%0d order=%0d reset=%b ok=%b nota=%h fim=%b tipo=%b estado_atual=%h",
                 $time, label, target, note_code, order,
                 reset, ok, nota, fim, tipo, estado_atual);
    end
endtask

task reset_dut;
    begin
        @(negedge clk);
        ok = 0;
        nota = NULL1;
        #1 reset = 1;
        #1 observe("reset asserted before clock");
        @(posedge clk);
        #1 observe("reset committed");

        @(negedge clk);
        nota = SI_M;
        #1 ok = 1;
        #1 observe("ok rising while reset high");
        @(posedge clk);
        #1 observe("clock while reset and ok high");
        @(negedge clk);
        ok = 0;
        reset = 0;
        #1 observe("reset released");
    end
endtask

task send_note;
    input [3:0] value;
    begin
        @(negedge clk);
        ok = 0;
        nota = value;
        #1 ok = 1;
        #1 observe("note evaluated before commit");
        #1 ok = 0;
        @(posedge clk);
        #1 observe("note committed");
    end
endtask

// Fixed input prefixes select test starting points through ports only.
task prepare;
    input integer destination;
    begin
        reset_dut;
        case (destination)
            INICIO: begin end
            ERRO: send_note(NULL1);
            default: begin
                send_note(DO);
                if (destination != N1) begin
                    send_note(RE);
                    case (destination)
                        N3_LA: send_note(LA_M);
                        N3_SI: send_note(SI_M);
                        ADJ: begin
                            send_note(LA_M);
                            send_note(NULL1);
                        end
                        N4_DO: begin
                            send_note(LA_M);
                            send_note(DO);
                        end
                        N4_SI: begin
                            send_note(LA_M);
                            send_note(SI_M);
                        end
                        N4_RE: begin
                            send_note(SI_M);
                            send_note(RE);
                        end
                        COMP: begin
                            send_note(LA_M);
                            send_note(DO);
                            send_note(NULL1);
                        end
                        ADV: begin
                            send_note(LA_M);
                            send_note(SI_M);
                            send_note(NULL1);
                        end
                    endcase
                end
            end
        endcase
    end
endtask

initial begin
    // Initialize inputs.
    reset = 0;
    ok = 0;
    nota = NULL1;
    target = 0;
    note_code = 0;
    order = 0;
    #1 reset = 1;

    // Wait 100 ns for global reset to finish.
    #100;
    observe("startup reset");
    @(negedge clk);
    reset = 0;

    // Test 1: Every note from every reachable state, independently.
    for (target = INICIO; target <= ERRO; target = target + 1) begin
        #1;
        for (note_code = 0; note_code < 16; note_code = note_code + 1) begin
            #1;
            prepare(target);
            observe("transition starting point");
            send_note(note_code[3:0]);
            repeat (2) @(posedge clk);
            #1 observe("idle clocks after transition");
        end
    end

    // Test 2: Short reset from every state, after a pending evaluation.
    for (target = INICIO; target <= ERRO; target = target + 1) begin
        #1;
        prepare(target);
        @(negedge clk);
        nota = SI_M;
        #1 ok = 1;
        #1 begin
            ok = 0;
            reset = 1;
        end
        #1 observe("short reset asserted before clock");
        reset = 0;
        #1 observe("short reset released before clock");
        @(posedge clk);
        #1 observe("clock after short reset");
        send_note(DO);
    end

    // Test 3: Note changes, held-high ok, falling edges, and idle clocks.
    target = N2;
    prepare(target);
    @(negedge clk);
    nota = LA_M;
    repeat (2) @(posedge clk);
    #1 observe("nota changed without ok edge");

    @(negedge clk);
    #1 ok = 1;
    #1 observe("ok rising before clock");
    @(posedge clk);
    #1 observe("first clock with ok high");

    @(negedge clk);
    nota = NULL2;
    repeat (3) @(posedge clk);
    #1 observe("nota changed while ok stays high");

    @(negedge clk);
    #1 ok = 0;
    repeat (2) @(posedge clk);
    #1 observe("falling ok followed by idle clocks");

    send_note(NULL2);

    // Test 4: Two evaluations before one commit, in both orders.
    for (order = 0; order < 2; order = order + 1) begin
        #1;
        target = N2;
        prepare(target);
        @(negedge clk);
        if (order == 0)
            nota = NULL1;
        else
            nota = LA_M;
        #1 ok = 1;
        #1 begin
            observe("first evaluation before shared clock");
            ok = 0;
            if (order == 0)
                nota = LA_M;
            else
                nota = NULL1;
        end
        #1 ok = 1;
        #1 observe("second evaluation before shared clock");
        @(posedge clk);
        #1 observe("commit after two evaluations");
        @(negedge clk);
        ok = 0;
        repeat (2) @(posedge clk);
        #1 observe("idle after double evaluation");
    end

    $display("===========End===========");
    $finish;
end

endmodule

