module testbench;

reg clk;
reg aresetn;
reg arready;
reg [3:0] rid;
reg [63:0] rdata;
reg [1:0] rresp;
reg rlast;
reg rvalid;
reg break_point;
reg cpu_rready;
reg infom_flag;
reg [31:0] start_addr;

wire [3:0] arid;
wire [31:0] araddr;
wire [7:0] arlen;
wire [2:0] arsize;
wire [1:0] arburst;
wire [1:0] arlock;
wire [3:0] arcache;
wire [2:0] arprot;
wire arvalid;
wire rready;
wire rvalid_r;
wire rid_r;
wire [63:0] rdata_r;
wire rlast_r;
wire flag;
wire mem_flag;
wire [7:0] mem_rdata;

debug_sram uut (
    .clk(clk),
    .aresetn(aresetn),
    .arid(arid),
    .araddr(araddr),
    .arlen(arlen),
    .arsize(arsize),
    .arburst(arburst),
    .arlock(arlock),
    .arcache(arcache),
    .arprot(arprot),
    .arvalid(arvalid),
    .arready(arready),
    .rid(rid),
    .rdata(rdata),
    .rresp(rresp),
    .rlast(rlast),
    .rvalid(rvalid),
    .rready(rready),
    .break_point(break_point),
    .cpu_rready(cpu_rready),
    .rvalid_r(rvalid_r),
    .rid_r(rid_r),
    .rdata_r(rdata_r),
    .rlast_r(rlast_r),
    .flag(flag),
    .infom_flag(infom_flag),
    .start_addr(start_addr),
    .mem_flag(mem_flag),
    .mem_rdata(mem_rdata)
);

initial clk = 1'b0;
always #5 clk = ~clk;

task reset_dut;
begin
    aresetn     = 1'b0;
    arready     = 1'b0;
    rid         = 4'd0;
    rdata       = 64'd0;
    rresp       = 2'd0;
    rlast       = 1'b0;
    rvalid      = 1'b0;
    break_point = 1'b0;
    cpu_rready  = 1'b0;
    infom_flag  = 1'b0;
    start_addr  = 32'd0;
    #2;
    aresetn     = 1'b1;
    repeat (1) @(posedge clk);
end
endtask

task show_outputs;
input [8*24-1:0] label;
begin
    $display("%0s arid=%h araddr=%h arlen=%h arsize=%h arburst=%h arlock=%h arcache=%h arprot=%h arvalid=%b rready=%b rvalid_r=%b rid_r=%b rdata_r=%h rlast_r=%b flag=%b mem_flag=%b mem_rdata=%h",
             label, arid, araddr, arlen, arsize, arburst, arlock, arcache,
             arprot, arvalid, rready, rvalid_r, rid_r, rdata_r, rlast_r,
             flag, mem_flag, mem_rdata);
end
endtask

task debug_transaction;
input [31:0] addr;
input [63:0] dat;
begin
    reset_dut;

    start_addr = addr;
    infom_flag = 1'b1;
    repeat (1) @(posedge clk);
    infom_flag = 1'b0;
    repeat (2) @(posedge clk);
    show_outputs("debug request waiting:");

    arready = 1'b1;
    repeat (1) @(posedge clk);
    arready = 1'b0;
    show_outputs("debug address accepted:");

    rid    = 4'hA;
    rdata  = 64'h0123456789ABCDEF;
    rresp  = 2'b11;
    rlast  = 1'b1;
    rvalid = 1'b1;
    repeat (1) @(posedge clk);
    rvalid = 1'b0;
    show_outputs("non-debug response while waiting:");

    rid    = 4'd2;
    rdata  = dat;
    rresp  = 2'b01;
    rlast  = 1'b0;
    rvalid = 1'b1;
    repeat (1) @(posedge clk);
    rvalid = 1'b0;
    show_outputs("debug response captured:");

    repeat (1) @(posedge clk);
    show_outputs("debug indication after one cycle:");
end
endtask

/*
 * Supplementary directed stimulus:
 * 1. arready high while no address is valid.
 * 2. infom_flag held high long enough to exercise delay=0.
 * 3. rvalid low while rready is high.
 * 4. ID-2 response presented after rready has already cleared.
 */
task directed_condition_stimulus;
begin
    reset_dut;

    start_addr = 32'h00002000;

    arready = 1'b1;
    repeat (1) @(posedge clk);
    show_outputs("idle ready condition:");

    arready     = 1'b0;
    infom_flag  = 1'b1;
    repeat (1) @(posedge clk);
    show_outputs("request first high:");

    repeat (1) @(posedge clk);
    show_outputs("request held high:");

    arready = 1'b1;
    repeat (1) @(posedge clk);
    show_outputs("request handshake:");

    infom_flag = 1'b0;
    arready    = 1'b0;

