`timescale 1ns / 1ps
module testbench;

localparam integer COUNT_RANGE = 4194304; // 2**22
localparam [21:0] MAX_DIV = 22'h3fffff;

// Inputs
reg clk;
reg rst;
reg [21:0] note_div_left;
reg [21:0] note_div_right;
reg [2:0] volume;

// Outputs
wire [15:0] audio_left;
wire [15:0] audio_right;

integer v;
integer i;
integer swap_channels;

note_gen uut (
    .clk(clk),
    .rst(rst),
    .note_div_left(note_div_left),
    .note_div_right(note_div_right),
    .volume(volume),
    .audio_left(audio_left),
    .audio_right(audio_right)
);

initial clk = 0;

always #5 clk = ~clk;

task observe;
    input [255:0] label;
    begin
        $display("%0t %0s rst=%b div_left=%0d div_right=%0d volume=%0d audio_left=%04h audio_right=%04h",
                 $time, label, rst, note_div_left, note_div_right,
                 volume, audio_left, audio_right);
    end
endtask

task initialize_case;
    input [21:0] left_div;
    input [21:0] right_div;
    input [2:0] level;
    begin
        @(negedge clk);
        #1;
        rst = 1'b1;
        note_div_left = left_div;
        note_div_right = right_div;
        volume = level;
        #1;
        observe("asynchronous reset");
        repeat (2) @(posedge clk);
        #1;
        observe("reset held");
        @(negedge clk);
        rst = 1'b0;
        #1;
        observe("reset released");
    end
endtask

task advance_and_observe;
    input integer cycles;
    input [255:0] label;
    begin
        repeat (cycles) @(posedge clk);
        #1;
        observe(label);
    end
endtask

initial begin
    rst = 1'b1;
    note_div_left = 22'd0;
    note_div_right = 22'd0;
    volume = 3'd0;

    // Wait 100 ns for global reset to finish.
    #100;
    observe("initial reset");

    // All volumes, both phases, zero/one dividers, and exchanged channels.
    for (swap_channels = 0; swap_channels < 2;
         swap_channels = swap_channels + 1) begin
        @(posedge clk);
        for (v = 0; v < 8; v = v + 1) begin
            @(posedge clk);
            initialize_case(swap_channels, 1 - swap_channels, v);
            for (i = 0; i < 4; i = i + 1) begin
                @(posedge clk);
                #1;
                observe("volume and divider timing");
            end
        end
    end

    // Set opposite phases, then change volume without a phase transition.
    initialize_case(22'd0, MAX_DIV, 3'd1);
    advance_and_observe(1, "opposite phases");
    @(negedge clk);
    note_div_left = MAX_DIV;
    #1;
    observe("hold opposite phases");
    for (v = 0; v < 8; v = v + 1) begin
        @(negedge clk);
        volume = v;
        #1;
        observe("combinational volume change");
    end

    // Reset active phases, then verify both channels restart together.
    initialize_case(22'd0, 22'd0, 3'd5);
    advance_and_observe(1, "both channels active");
    initialize_case(22'd1, 22'd1, 3'd5);
    for (i = 0; i < 4; i = i + 1) begin
        @(posedge clk);
        #1;
        observe("restart after active reset");
    end

    // After three edges, both counts are three.
    initialize_case(22'd4, 22'd6, 3'd2);
    advance_and_observe(3, "before live divider change");
    @(negedge clk);
    note_div_left = 22'd5;
    note_div_right = 22'd3;
    #1;
    observe("increase left, equality right");
    for (i = 0; i < 9; i = i + 1) begin
        @(posedge clk);
        #1;
        observe("live divider response");
    end

    // Lower terminals below the current count; wait through natural wrap.
    initialize_case(22'd7, 22'd7, 3'd3);
    advance_and_observe(3, "before lowering dividers");
    @(negedge clk);
    note_div_left = 22'd1;
    note_div_right = 22'd2;
    #1;
    observe("dividers below current count");
    advance_and_observe(COUNT_RANGE - 4, "edge before counter wrap");
    advance_and_observe(1, "counter wrap");
    for (i = 0; i < 6; i = i + 1) begin
        @(posedge clk);
        #1;
        observe("post-wrap divider timing");
    end

    // Maximum divider and adjacent boundary, reached through top ports.
    initialize_case(MAX_DIV, MAX_DIV - 22'd1, 3'd4);
    advance_and_observe(COUNT_RANGE - 2, "before upper terminals");
    for (i = 0; i < 3; i = i + 1) begin
        @(posedge clk);
        #1;
        observe("upper terminal transitions");
    end

    $display("===========End===========");
    $finish;
end

endmodule

