`timescale 1ns / 1ps
module testbench;

localparam MAX_BYTES = 64;
localparam [63:0] HEX_DIGITS = "09abcdef";
localparam [8*MAX_BYTES-1:0] DOLLAR_RECORD =
    "^1234@09abcdef:  $1234  <=  09abcdef#";
localparam [8*MAX_BYTES-1:0] STAR_RECORD =
    "^1@09abcdef:  *09abcdef  <=  09abcdef#";

// Packed string literals are right-aligned; use their complete lengths.
localparam DOLLAR_LENGTH = 37;
localparam STAR_LENGTH = 38;

reg clk;
reg reset;
reg [7:0] char;

wire [1:0] format_type;

integer test_id;
integer sample_id;
integer i, j, k, n;
integer mutation_id;
integer colon_spaces, operand_spaces, result_spaces;
reg [7:0] mutation_char;
reg [8*MAX_BYTES-1:0] text;
integer text_length;

cpu_checker uut (
    .char(char),
    .clk(clk),
    .reset(reset),
    .format_type(format_type)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
begin
    $display("test=%0d sample=%0d time=%0t reset=%b char=%02h format_type=%b",
             test_id, sample_id, $time, reset, char, format_type);
    sample_id = sample_id + 1;
end
endtask

task put;
    input [7:0] value;
begin
    @(negedge clk);
    char = value;
    @(posedge clk);
    #1;
    observe;
end
endtask

task reset_dut;
begin
    @(negedge clk);
    reset = 1;
    char = "^";
    #1;
    observe;
    @(posedge clk);
    #1;
    observe;
    @(posedge clk);
    #1;
    observe;
    @(negedge clk);
    reset = 0;
    char = 0;
end
endtask

task begin_case;
begin
    test_id = test_id + 1;
    sample_id = 0;
    reset_dut;
end
endtask

task repeated_char;
    input [7:0] value;
    input integer count;
    integer p;
begin
    for (p = 0; p < count; p = p + 1) begin
        #1;
        put(value);
    end
end
endtask

task hex_field;
    input integer count;
    integer p;
begin
    for (p = 0; p < count; p = p + 1) begin
        #1;
        put(HEX_DIGITS[8*(7-(p%8)) +: 8]);
    end
end
endtask

// Extended generator permits independent optional-space lengths.
task record_stream_spaced;
    input [7:0] marker;
    input integer leading_digits;
    input integer address_digits;
    input integer operand_digits;
    input integer result_digits;
    input integer spaces_after_colon;
    input integer spaces_after_operand;
    input integer spaces_after_equals;
begin
    put("^");
    repeated_char("9", leading_digits);
    put("@");
    hex_field(address_digits);
    put(":");
    repeated_char(" ", spaces_after_colon);
    put(marker);
    if (marker == "$")
        repeated_char("0", operand_digits);
    else
        hex_field(operand_digits);
    repeated_char(" ", spaces_after_operand);
    put("<");
    put("=");
    repeated_char(" ", spaces_after_equals);
    hex_field(result_digits);
    put("#");
end
endtask

// Preserve the original generator interface and test calls.
task record_stream;
    input [7:0] marker;
    input integer leading_digits;
    input integer address_digits;
    input integer operand_digits;
    input integer result_digits;
    input integer spaces;
begin
    record_stream_spaced(marker, leading_digits, address_digits,
                         operand_digits, result_digits,
                         spaces, spaces, spaces);
end
endtask

// Positions are counted from the first character, starting at zero.
task send_text;
    input [8*MAX_BYTES-1:0] bytes;
    input integer length;
    input integer count;
    input integer replace_position;
    input [7:0] replacement;
    integer p;
begin
    for (p = 0; p < count; p = p + 1) begin
        #1;
        if (p == replace_position)
            put(replacement);
        else
            put(bytes[8*(length-1-p) +: 8]);
    end
end
endtask

initial begin
    reset = 1;
    char = 0;
    test_id = 0;
    sample_id = 0;

    // Wait 100 ns for global reset to finish.
    #100;
    observe;

    // Valid forms, all legal decimal lengths, and optional spacing.
    for (i = 0; i < 4; i = i + 1) begin
        #1;
        begin_case;
        record_stream("$", i+1, 8, i+1, 8, i%3);
        put(".");
        put(".");

        begin_case;
        record_stream("*", i+1, 8, 8, 8, i%3);
        put(".");
    end

    // Exercise the three optional whitespace locations independently.
    for (colon_spaces = 0; colon_spaces <= 2;
         colon_spaces = colon_spaces + 1) begin
        #1;
        for (operand_spaces = 0; operand_spaces <= 2;
             operand_spaces = operand_spaces + 1) begin
            #1;
            for (result_spaces = 0; result_spaces <= 2;
                 result_spaces = result_spaces + 1) begin
                #1;
                begin_case;
                record_stream_spaced("$", 1, 8, 1, 8,
                                     colon_spaces, operand_spaces,
                                     result_spaces);
                put(".");

                begin_case;
                record_stream_spaced("*", 1, 8, 8, 8,
                                     colon_spaces, operand_spaces,
                                     result_spaces);
                put(".");
            end
        end
    end

    // Empty and overflowing decimal fields; include legal boundaries.
    for (i = 0; i <= 5; i = i + 1) begin
        #1;
        begin_case;
        record_stream("$", i, 8, 1, 8, 0);
        put(".");

        begin_case;
        record_stream("$", 1, 8, i, 8, 0);
        put(".");
    end

    // Hexadecimal lengths, including four-bit counter rollover.
    for (i = 0; i < 8; i = i + 1) begin
        #1;
        case (i)
            0: n = 0;
            1: n = 1;
            2: n = 7;
            3: n = 8;
            4: n = 9;
            5: n = 15;
            6: n = 16;
            7: n = 24;
        endcase
        for (j = 0; j < 3; j = j + 1) begin
            #1;
            for (k = 0; k < 2; k = k + 1) begin
                #1;
                begin_case;
                case (j)
                    0: record_stream("*", 1, n, 8, 8, 2*k);
                    1: record_stream("*", 1, 8, n, 8, 2*k);
                    2: record_stream("*", 1, 8, 8, n, 2*k);
                endcase
                put(".");
            end
        end
    end

    // Preserve uppercase-A mutations and extend the same traversal:
    // "/" is below "0"; "g" is above "f"; "a"/"f" are legal hex.
    // Correct lengths ensure each unmodified prefix starts with "^".
    for (k = 0; k < 2; k = k + 1) begin
        #1;
        if (k == 0) begin
            text = DOLLAR_RECORD;
            text_length = DOLLAR_LENGTH;
        end else begin
            text = STAR_RECORD;
            text_length = STAR_LENGTH;
        end

        for (mutation_id = 0; mutation_id < 5;
             mutation_id = mutation_id + 1) begin
            #1;
            case (mutation_id)
                0: mutation_char = "A";
                1: mutation_char = "/";
                2: mutation_char = "g";
                3: mutation_char = "a";
                4: mutation_char = "f";
            endcase

            for (i = 0; i < text_length; i = i + 1) begin
                #1;
                begin_case;
                send_text(text, text_length, text_length,
                          i, mutation_char);
                put(".");
                // Recovery deliberately runs without clearing counters.
                record_stream("*", 1, 8, 8, 8, 0);
                put(".");
            end
        end
    end

    // Tabs are not optional spaces. Correct zero-based positions:
    // after colon, after dollar operand, and after equals.
    for (i = 0; i < 3; i = i + 1) begin
        #1;
        case (i)
            0: n = 15;
            1: n = 22;
            2: n = 26;
        endcase
        begin_case;
        send_text(DOLLAR_RECORD, DOLLAR_LENGTH,
                  DOLLAR_LENGTH, n, 8'h09);
        put(".");
    end

    // Consecutive dollar records expose retained decimal counts.
    for (i = 1; i <= 4; i = i + 1) begin
        #1;
        for (j = 1; j <= 4; j = j + 1) begin
            #1;
            begin_case;
            record_stream("$", 1, 8, i, 8, 0);
            record_stream("$", j, 8, 1, 8, 0);
            put(".");
        end
    end

    // Consecutive marker transitions and ordinary idle characters.
    begin_case;
    send_text("xyz#@ ", 6, 6, -1, 0);
    record_stream("*", 1, 8, 8, 8, 0);
    record_stream("*", 4, 8, 8, 8, 1);
    record_stream("$", 1, 8, 4, 8, 2);
    record_stream("*", 2, 8, 8, 8, 0);
    put(".");
    record_stream("$", 1, 8, 2, 8, 0);
    put(".");
    record_stream("$", 3, 8, 1, 8, 0);
    put(".");

    // Reset every reachable prefix, including completed records.
    for (k = 0; k < 2; k = k + 1) begin
        #1;
        if (k == 0) begin
            text = DOLLAR_RECORD;
            text_length = DOLLAR_LENGTH;
        end else begin
            text = STAR_RECORD;
            text_length = STAR_LENGTH;
        end
        for (i = 0; i <= text_length; i = i + 1) begin
            #1;
            begin_case;
            send_text(text, text_length, i, -1, 0);
            reset_dut;
            record_stream("$", 4, 8, 4, 8, 0);
            put(".");
        end
    end

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps

module testbench;

parameter integer TB_CLOCK_FREQUENCY = 1000000;
parameter integer TB_UART_BAUDRATE = 100000;
parameter integer TB_UART_STOPBIT = 1;

localparam integer BIT_CYCLES = 10;
localparam integer TX_BITS = 1 + 8 + ((TB_UART_STOPBIT > 1) ? 2 : 1);

reg clk;
reg reset;
reg in_valid;
reg [7:0] in_data;
reg out_ready;
reg cts;
reg rxd;

wire in_ready;
wire out_valid;
wire [7:0] out_data;
wire txd;
wire rts;

uart_to_bytes #(
    .CLOCK_FREQUENCY(TB_CLOCK_FREQUENCY),
    .UART_BAUDRATE(TB_UART_BAUDRATE),
    .UART_STOPBIT(TB_UART_STOPBIT)
) uut (
    .reset(reset),
    .clk(clk),
    .in_ready(in_ready),
    .in_valid(in_valid),
    .in_data(in_data),
    .out_ready(out_ready),
    .out_valid(out_valid),
    .out_data(out_data),
    .txd(txd),
    .cts(cts),
    .rxd(rxd),
    .rts(rts)
);

initial clk = 1'b0;
always #5 clk = ~clk;

task observe;
    input integer point;
    begin
        $display("OBS %0d: reset=%b in_ready=%b in_valid=%b in_data=%02h out_ready=%b out_valid=%b out_data=%02h cts=%b rxd=%b txd=%b rts=%b",
                 point, reset, in_ready, in_valid, in_data, out_ready,
                 out_valid, out_data, cts, rxd, txd, rts);
    end
endtask

task reset_dut;
    begin
        reset = 1'b1;
        repeat (2) @(posedge clk);
        #1;
        observe(1);
        reset = 1'b0;
        repeat (3) @(posedge clk);
        #1;
        observe(2);
    end
endtask

task send_uart_byte;
    input [7:0] value;
    integer bit_index;
    begin
        rxd = 1'b0;
        repeat (BIT_CYCLES) @(posedge clk);

        for (bit_index = 0; bit_index < 8; bit_index = bit_index + 1) begin
            rxd = value[bit_index];
            repeat (BIT_CYCLES) @(posedge clk);
        end

        rxd = 1'b1;
        repeat (BIT_CYCLES) @(posedge clk);
    end
endtask

initial begin
    reset = 1'b0;
    in_valid = 1'b0;
    in_data = 8'h00;
    out_ready = 1'b0;
    cts = 1'b0;
    rxd = 1'b1;

    reset_dut;

    // CTS low and synchronized CTS high.
    cts = 1'b0;
    repeat (3) @(posedge clk);
    #1;
    observe(10);

    cts = 1'b1;
    repeat (3) @(posedge clk);
    #1;
    observe(11);

    // Transmit one byte and observe each serial bit period.
    in_data = 8'hA5;
    in_valid = 1'b1;
    @(posedge clk);
    #1;
    observe(20);
    in_valid = 1'b0;

    repeat (TX_BITS) begin
        repeat (BIT_CYCLES) @(posedge clk);
        #1;
        observe(21);
    end

    repeat (3) @(posedge clk);
    #1;
    observe(22);

    // Valid receive frame with backpressure and later consumption.
    reset_dut;
    out_ready = 1'b0;
    send_uart_byte(8'h3C);
    repeat (4) @(posedge clk);
    #1;
    observe(30);

    out_ready = 1'b1;
    repeat (2) @(posedge clk);
    #1;
    observe(31);

    // Invalid start bit: return high before the midpoint sample.
    reset_dut;
    out_ready = 1'b1;
    rxd = 1'b0;
    repeat (BIT_CYCLES / 4) @(posedge clk);
    rxd = 1'b1;
    repeat (8) @(posedge clk);
    #1;
    observe(40);

    // Invalid stop bit.
    reset_dut;
    out_ready = 1'b1;
    rxd = 1'b0;
    repeat (BIT_CYCLES) @(posedge clk);

    // Data byte 8'h96, transmitted least-significant bit first.
    rxd = 1'b0;
    repeat (BIT_CYCLES) @(posedge clk);
    rxd = 1'b1;
    repeat (BIT_CYCLES) @(posedge clk);
    rxd = 1'b1;
    repeat (BIT_CYCLES) @(posedge clk);
    rxd = 1'b0;
    repeat (BIT_CYCLES) @(posedge clk);
    rxd = 1'b1;
    repeat (BIT_CYCLES) @(posedge clk);
    rxd = 1'b0;
    repeat (BIT_CYCLES) @(posedge clk);
    rxd = 1'b0;
    repeat (BIT_CYCLES) @(posedge clk);
    rxd = 1'b1;
    repeat (BIT_CYCLES) @(posedge clk);

    rxd = 1'b0;
    repeat (BIT_CYCLES) @(posedge clk);
    rxd = 1'b1;
    repeat (5) @(posedge clk);
    #1;
    observe(50);

    // Two valid frames while the receive output is blocked.
    reset_dut;
    out_ready = 1'b0;
    send_uart_byte(8'h12);
    send_uart_byte(8'hE7);
    repeat (4) @(posedge clk);
    #1;
    observe(60);

    out_ready = 1'b1;
    repeat (2) @(posedge clk);
    #1;
    observe(61);

    $display("===========End===========");

    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

reg clk;
reg i_rst_n;
reg i_i_valid_inst;
reg [31:0] i_i_inst;
reg i_d_valid_data;
reg [63:0] i_d_data;

wire o_i_valid_addr;
wire [63:0] o_i_addr;
wire [63:0] o_d_w_data;
wire [63:0] o_d_w_addr;
wire [63:0] o_d_r_addr;
wire o_d_MemRead;
wire o_d_MemWrite;
wire o_finish;

cpu uut (
    .i_clk(clk),
    .i_rst_n(i_rst_n),
    .i_i_valid_inst(i_i_valid_inst),
    .i_i_inst(i_i_inst),
    .i_d_valid_data(i_d_valid_data),
    .i_d_data(i_d_data),
    .o_i_valid_addr(o_i_valid_addr),
    .o_i_addr(o_i_addr),
    .o_d_w_data(o_d_w_data),
    .o_d_w_addr(o_d_w_addr),
    .o_d_r_addr(o_d_r_addr),
    .o_d_MemRead(o_d_MemRead),
    .o_d_MemWrite(o_d_MemWrite),
    .o_finish(o_finish)
);

initial clk = 0;
always #5 clk = ~clk;

function [31:0] make_i;
    input [6:0] opcode;
    input [4:0] rd;
    input [2:0] func3;
    input [4:0] rs1;
    input [11:0] imm12;
    begin
        make_i = {imm12, rs1, func3, rd, opcode};
    end
endfunction

function [31:0] make_r;
    input [6:0] func7;
    input [4:0] rs2;
    input [4:0] rs1;
    input [2:0] func3;
    input [4:0] rd;
    input [6:0] opcode;
    begin
        make_r = {func7, rs2, rs1, func3, rd, opcode};
    end
endfunction

function [31:0] make_s;
    input [11:0] imm12;
    input [4:0] rs2;
    input [4:0] rs1;
    input [2:0] func3;
    input [6:0] opcode;
    begin
        make_s = {imm12[11:5], rs2, rs1, func3, imm12[4:0], opcode};
    end
endfunction

function [31:0] make_b;
    input [12:0] disp;
    input [4:0] rs2;
    input [4:0] rs1;
    input [2:0] func3;
    input [6:0] opcode;
    begin
        make_b = {
            disp[12], disp[10:5], rs2, rs1, func3,
            disp[4:1], disp[11], opcode
        };
    end
endfunction

task reset_dut;
    begin
        i_rst_n = 0;
        i_i_valid_inst = 0;
        i_i_inst = 32'b0;
        i_d_valid_data = 0;
        i_d_data = 64'b0;
        #2;
        $display("RESET: iv=%b ia=%h wd=%h wa=%h ra=%h mr=%b mw=%b finish=%b",
                 o_i_valid_addr, o_i_addr, o_d_w_data, o_d_w_addr,
                 o_d_r_addr, o_d_MemRead, o_d_MemWrite, o_finish);
        i_rst_n = 1;
        repeat (1) @(posedge clk);
        #1;
        $display("RESET_RELEASE: iv=%b ia=%h wd=%h wa=%h ra=%h mr=%b mw=%b finish=%b",
                 o_i_valid_addr, o_i_addr, o_d_w_data, o_d_w_addr,
                 o_d_r_addr, o_d_MemRead, o_d_MemWrite, o_finish);
    end
endtask

task reset_from_state;
    input integer target_state;
    begin
        reset_dut;

        // reset_dut releases reset with the controller in state 1.
        // Advance to the requested state using fixed clock cycles.
        if (target_state > 1) begin
            repeat (target_state - 1) @(posedge clk);
        end

        #1;
        i_rst_n = 0;
        #2;
        $display("PHASE_RESET_%0d: iv=%b ia=%h wd=%h wa=%h ra=%h mr=%b mw=%b finish=%b",
                 target_state, o_i_valid_addr, o_i_addr, o_d_w_data,
                 o_d_w_addr, o_d_r_addr, o_d_MemRead,
                 o_d_MemWrite, o_finish);

        i_rst_n = 1;
        repeat (1) @(posedge clk);
        #1;
        $display("PHASE_RESET_RELEASE_%0d: iv=%b ia=%h wd=%h wa=%h ra=%h mr=%b mw=%b finish=%b",
                 target_state, o_i_valid_addr, o_i_addr, o_d_w_data,
                 o_d_w_addr, o_d_r_addr, o_d_MemRead,
                 o_d_MemWrite, o_finish);
    end
endtask

task run_instruction;
    input [31:0] instruction;
    input [63:0] read_data;
    begin
        i_i_inst = instruction;
        i_i_valid_inst = 0;
        i_d_data = read_data;
        i_d_valid_data = 0;
        repeat (8) @(posedge clk);
        #1;
        $display("OBS: inst=%h iv=%b ia=%h wd=%h wa=%h ra=%h mr=%b mw=%b finish=%b",
                 i_i_inst, o_i_valid_addr, o_i_addr, o_d_w_data,
                 o_d_w_addr, o_d_r_addr, o_d_MemRead,
                 o_d_MemWrite, o_finish);
    end
endtask

task run_branch;
    input [31:0] instruction;
    begin
        i_i_inst = instruction;
        i_i_valid_inst = 0;
        repeat (9) @(posedge clk);
        #1;
        $display("BRANCH: inst=%h iv=%b ia=%h wd=%h wa=%h ra=%h mr=%b mw=%b finish=%b",
                 i_i_inst, o_i_valid_addr, o_i_addr, o_d_w_data,
                 o_d_w_addr, o_d_r_addr, o_d_MemRead,
                 o_d_MemWrite, o_finish);
    end
endtask

initial begin
    i_rst_n = 0;
    i_i_valid_inst = 0;
    i_i_inst = 0;
    i_d_valid_data = 0;
    i_d_data = 0;

    // Immediate arithmetic and store behavior.
    reset_dut;
    run_instruction(make_i(7'b0010011, 5'd1, 3'b000, 5'd0, 12'd9), 0);
    run_instruction(make_i(7'b0010011, 5'd2, 3'b000, 5'd1, 12'd5), 0);
    run_instruction(make_s(12'd16, 5'd2, 5'd1, 3'b010, 7'b0100011), 0);
    run_instruction(make_i(7'b0010011, 5'd2, 3'b100, 5'd1, 12'h0f0), 0);
    run_instruction(make_s(12'd24, 5'd2, 5'd1, 3'b010, 7'b0100011), 0);
    run_instruction(make_i(7'b0010011, 5'd2, 3'b110, 5'd1, 12'h0f0), 0);
    run_instruction(make_s(12'd32, 5'd2, 5'd1, 3'b010, 7'b0100011), 0);
    run_instruction(make_i(7'b0010011, 5'd2, 3'b111, 5'd1, 12'h0f0), 0);
    run_instruction(make_s(12'd40, 5'd2, 5'd1, 3'b010, 7'b0100011), 0);
    run_instruction(make_i(7'b0010011, 5'd2, 3'b001, 5'd1, 12'd2), 0);
    run_instruction(make_s(12'd48, 5'd2, 5'd1, 3'b010, 7'b0100011), 0);
    run_instruction(make_i(7'b0010011, 5'd2, 3'b101, 5'd1, 12'd2), 0);
    run_instruction(make_s(12'd56, 5'd2, 5'd1, 3'b010, 7'b0100011), 0);
    run_instruction(make_i(7'b0010011, 5'd2, 3'b010, 5'd1, 12'd1), 0);
    run_instruction(make_s(12'd64, 5'd2, 5'd1, 3'b010, 7'b0100011), 0);

    // Register arithmetic, unsupported function, and destination register zero.
    reset_dut;
    run_instruction(make_i(7'b0010011, 5'd1, 3'b000, 5'd0, 12'd12), 0);
    run_instruction(make_i(7'b0010011, 5'd2, 3'b000, 5'd0, 12'd3), 0);
    run_instruction(make_r(7'b0000000, 5'd2, 5'd1, 3'b000, 5'd3, 7'b0110011), 0);
    run_instruction(make_s(12'd8, 5'd3, 5'd1, 3'b010, 7'b0100011), 0);
    run_instruction(make_r(7'b0100000, 5'd2, 5'd1, 3'b000, 5'd3, 7'b0110011), 0);
    run_instruction(make_s(12'd16, 5'd3, 5'd1, 3'b010, 7'b0100011), 0);
    run_instruction(make_r(7'b0000000, 5'd2, 5'd1, 3'b100, 5'd3, 7'b0110011), 0);
    run_instruction(make_s(12'd24, 5'd3, 5'd1, 3'b010, 7'b0100011), 0);
    run_instruction(make_r(7'b0000000, 5'd2, 5'd1, 3'b110, 5'd3, 7'b0110011), 0);
    run_instruction(make_s(12'd32, 5'd3, 5'd1, 3'b010, 7'b0100011), 0);
    run_instruction(make_r(7'b0000000, 5'd2, 5'd1, 3'b111, 5'd0, 7'b0110011), 0);
    run_instruction(make_s(12'd40, 5'd0, 5'd1, 3'b010, 7'b0100011), 0);
    run_instruction(make_r(7'b0000000, 5'd2, 5'd1, 3'b001, 5'd3, 7'b0110011), 0);
    run_instruction(make_s(12'd48, 5'd3, 5'd1, 3'b010, 7'b0100011), 0);

    // Load behavior and ignored data-valid input.
    reset_dut;
    run_instruction(make_i(7'b0010011, 5'd1, 3'b000, 5'd0, 12'd20), 0);
    run_instruction(make_i(7'b0000011, 5'd4, 3'b010, 5'd1, 12'd12),
                    64'h1234_5678_9abc_def0);
    run_instruction(make_s(12'd8, 5'd4, 5'd1, 3'b010, 7'b0100011),
                    64'h1234_5678_9abc_def0);

    // Unsupported opcode, finish retention, and finish clearing.
    reset_dut;
    run_instruction(32'h00000000, 0);
    run_instruction(32'h0000007f, 0);
    run_instruction(32'h0000007f, 0);
    run_instruction(make_i(7'b0010011, 5'd1, 3'b000, 5'd0, 12'd1), 0);

    // Branch equality and inequality paths, taken and not taken.
    reset_dut;
    run_instruction(make_i(7'b0010011, 5'd1, 3'b000, 5'd0, 12'd7), 0);
    run_instruction(make_i(7'b0010011, 5'd2, 3'b000, 5'd0, 12'd7), 0);
    run_branch(make_b(13'd8, 5'd2, 5'd1, 3'b000, 7'b1100011));
    run_branch(make_b(13'd8, 5'd2, 5'd1, 3'b001, 7'b1100011));

    reset_dut;
    run_instruction(make_i(7'b0010011, 5'd1, 3'b000, 5'd0, 12'd7), 0);
    run_instruction(make_i(7'b0010011, 5'd2, 3'b000, 5'd0, 12'd9), 0);
    run_branch(make_b(13'd8, 5'd2, 5'd1, 3'b000, 7'b1100011));
    run_branch(make_b(13'h1ff8, 5'd2, 5'd1, 3'b001, 7'b1100011));

    // Exercise asynchronous reset from each reachable nonzero controller state.
    reset_from_state(1);
    reset_from_state(2);
    reset_from_state(3);
    reset_from_state(4);
    reset_from_state(5);
    reset_from_state(6);
    reset_from_state(7);

    // Reset after activity.
    i_rst_n = 0;
    #2;
    $display("FINAL_RESET: iv=%b ia=%h wd=%h wa=%h ra=%h mr=%b mw=%b finish=%b",
             o_i_valid_addr, o_i_addr, o_d_w_data, o_d_w_addr,
             o_d_r_addr, o_d_MemRead, o_d_MemWrite, o_finish);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam SETTLE = 6;
localparam START_WAIT = 15 + SETTLE;

// Inputs
reg clk;
reg rst_n;
reg [1:0] rate_in;
reg drp_done, rxpma_done;
reg txrate_done, rxrate_done, txsync_done, phystatus;

// Outputs
wire pclk_sel     [0:4];
wire drp_start    [0:4];
wire drp_x16      [0:4];
wire [2:0] rate_out [0:4];
wire txsync_start [0:4];
wire rate_done    [0:4];
wire rate_idle    [0:4];
wire [4:0] rate_fsm [0:4];

integer test_id, k, checkpoint;
reg [1:0] base_request;
reg [8:0] early_order, late_order;

// Instantiate only the top-level DUT.
`define MAKE_DUT(INST, N, SPEED, LIMIT) \
pcieCore_gtp_pipe_rate #( \
    .PCIE_SIM_SPEEDUP(SPEED), .TXDATA_WAIT_MAX(LIMIT) \
) INST ( \
    .RATE_CLK(clk), .RATE_RST_N(rst_n), .RATE_RATE_IN(rate_in), \
    .RATE_DRP_DONE(drp_done), .RATE_RXPMARESETDONE(rxpma_done), \
    .RATE_TXRATEDONE(txrate_done), .RATE_RXRATEDONE(rxrate_done), \
    .RATE_TXSYNC_DONE(txsync_done), .RATE_PHYSTATUS(phystatus), \
    .RATE_PCLK_SEL(pclk_sel[N]), .RATE_DRP_START(drp_start[N]), \
    .RATE_DRP_X16(drp_x16[N]), .RATE_RATE_OUT(rate_out[N]), \
    .RATE_TXSYNC_START(txsync_start[N]), .RATE_DONE(rate_done[N]), \
    .RATE_IDLE(rate_idle[N]), .RATE_FSM(rate_fsm[N]) \
)

`MAKE_DUT(u_normal15, 0, "FALSE", 4'd15);
`MAKE_DUT(u_normal0,  1, "FALSE", 4'd0);
`MAKE_DUT(u_normal1,  2, "FALSE", 4'd1);
`MAKE_DUT(u_speedup,  3, "TRUE",  4'd0);
`MAKE_DUT(u_lowercase,4, "true",  4'd1);
`undef MAKE_DUT

// clk toggle generate
initial clk = 0;
always #5 clk = ~clk;

`define REPORT(N) \
$display("t=%0t case=%0d phase=%0d cfg=%0d rst_n=%b req=%b PCLK_SEL=%b DRP_START=%b DRP_X16=%b RATE_OUT=%b TXSYNC_START=%b DONE=%b IDLE=%b FSM=%b", \
    $time, test_id, tag, N, rst_n, rate_in, \
    pclk_sel[N], drp_start[N], drp_x16[N], rate_out[N], \
    txsync_start[N], rate_done[N], rate_idle[N], rate_fsm[N])

task observe;
    input integer tag;
    begin
        `REPORT(0);
        `REPORT(1);
        `REPORT(2);
        `REPORT(3);
        `REPORT(4);
    end
endtask
`undef REPORT

task step;
    input integer cycles;
    input integer tag;
    integer n;
    begin
        for (n = 0; n < cycles; n = n + 1) begin
            @(posedge clk);
            #1;
            observe(tag);
        end
    end
endtask

task reset_clean;
    begin
        rst_n = 0;
        rate_in = 0;
        drp_done = 1;
        rxpma_done = 1;
        txsync_done = 1;
        {txrate_done, rxrate_done, phystatus} = 3'b000;
        #1;
        observe(0);                 // Reset asserted before its sampling edge.
        step(2, 1);
        rst_n = 1;
        step(SETTLE, 2);
    end
endtask

task pulse_events;
    input [2:0] events;
    input integer tag;
    begin
        {txrate_done, rxrate_done, phystatus} = events;
        step(4, tag);
        {txrate_done, rxrate_done, phystatus} = 3'b000;
        step(4, tag);
    end
endtask

// event_mode: 0 = late separated, 1 = early separated, 2 = simultaneous.
task change_rate;
    input [1:0] request;
    input [8:0] event_order;
    input integer event_mode;
    integer e;
    begin
        drp_done = 1;
        rxpma_done = 1;
        txsync_done = 1;
        {txrate_done, rxrate_done, phystatus} = 3'b000;
        step(SETTLE, 10);
        pulse_events(3'b111, 11);    // Idle events, before requesting a change.

        rate_in = request;
        step(START_WAIT, 12);

        drp_done = 0;
        step(SETTLE, 13);
        drp_done = 1;
        step(SETTLE, 14);
        if (event_mode == 1)
            pulse_events(event_order[8:6], 30);

        rxpma_done = 0;
        step(SETTLE, 15);
        if (event_mode == 1)
            pulse_events(event_order[5:3], 31);

        drp_done = 0;
        step(SETTLE, 16);
        if (event_mode == 1)
            pulse_events(event_order[2:0], 32);

        drp_done = 1;
        step(SETTLE, 17);

        case (event_mode)
            0: begin
                for (e = 0; e < 3; e = e + 1) begin
                    #1;
                    pulse_events(event_order >> (6 - 3*e), 40 + e);
                end
            end
            2: pulse_events(3'b111, 43);
        endcase

        step(SETTLE, 18);
        txsync_done = 0;
        step(SETTLE, 19);
        txsync_done = 1;
        step(SETTLE, 20);
        step(START_WAIT, 21);        // Retain request and observe idle behavior.
    end
endtask

initial begin
    // Initialize Inputs
    test_id = 0;
    rst_n = 0;
    rate_in = 0;
    drp_done = 1;
    rxpma_done = 1;
    txrate_done = 0;
    rxrate_done = 0;
    txsync_done = 1;
    phystatus = 0;
    base_request = 0;
    early_order = 0;
    late_order = 0;

    // Wait 100 ns for global reset to finish
    #100;
    reset_clean();

    // Paired transactions: all rate encodings and all six event orders.
    for (k = 0; k < 3; k = k + 1) begin
        #1;
        test_id = 100 + 2*k;
        reset_clean();
        case (k)
            0: begin
                base_request = 2'd0;
                early_order = {3'b100, 3'b010, 3'b001};
                late_order  = {3'b010, 3'b001, 3'b100};
            end
            1: begin
                base_request = 2'd2;
                early_order = {3'b100, 3'b001, 3'b010};
                late_order  = {3'b001, 3'b100, 3'b010};
            end
            2: begin
                base_request = 2'd3;
                early_order = {3'b010, 3'b100, 3'b001};
                late_order  = {3'b001, 3'b010, 3'b100};
            end
        endcase
        change_rate(2'd1, early_order, 1);
        test_id = 101 + 2*k;
        change_rate(base_request, late_order, 0);
    end

    // Deliberately retain the preceding request 3 before changing to 2.
    test_id = 110;
    change_rate(2'd2, 9'b0, 2);

    // Reset after progressively later, fixed-time stimulus checkpoints.
    test_id = 200;
    reset_clean();
    for (checkpoint = 0; checkpoint < 10;
         checkpoint = checkpoint + 1) begin
        #1;
        test_id = 200 + checkpoint;
        rate_in = 2'd1;
        step(3, 50);
        if (checkpoint > 0)
            step(START_WAIT - 3, 51);
        if (checkpoint > 1) begin
            drp_done = 0;
            step(SETTLE, 52);
        end
        if (checkpoint > 2) begin
            drp_done = 1;
            step(SETTLE, 53);
        end
        if (checkpoint > 3) begin
            rxpma_done = 0;
            step(SETTLE, 54);
        end
        if (checkpoint > 4) begin
            drp_done = 0;
            step(SETTLE, 55);
        end
        if (checkpoint > 5) begin
            drp_done = 1;
            step(SETTLE, 56);
            pulse_events(3'b110, 57);
        end
        if (checkpoint > 6)
            pulse_events(3'b001, 58);
        if (checkpoint > 7) begin
            txsync_done = 0;
            step(SETTLE, 59);
        end
        if (checkpoint > 8) begin
            txsync_done = 1;
            step(3, 60);            // Two sampling stages plus state response.
        end
        reset_clean();
    end

    // Nonzero request and asserted status inputs during reset.
    test_id = 300;
    rst_n = 0;
    rate_in = 2'd1;
    {txrate_done, rxrate_done, phystatus} = 3'b111;
    step(2, 70);
    rst_n = 1;
    {txrate_done, rxrate_done, phystatus} = 3'b000;
    step(START_WAIT, 71);
    reset_clean();

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

reg clk;
reg rst_ni;

wire max_tick_o;

mod_m_counter #(
    .MOD(65),
    .MOD_BIT($clog2(65))
) uut (
    .clk_i      (clk),
    .rst_ni     (rst_ni),
    .max_tick_o (max_tick_o)
);

initial clk = 0;
always #5 clk = ~clk;

initial begin
    // Test Case 1: asynchronous reset assertion
    rst_ni = 0;
    #1;
    $display("TC1 async reset asserted: max_tick_o=%b", max_tick_o);

    // Test Case 2: first count after reset release
    rst_ni = 1;
    repeat (1) @(posedge clk);
