    // Test Case 3: terminal-count indication at count MOD-1
    repeat (63) @(posedge clk);
    #1;
    $display("TC3 terminal count: max_tick_o=%b", max_tick_o);

    // Test Case 4: wraparound after terminal count
    repeat (1) @(posedge clk);
    #1;
    $display("TC4 after wraparound: max_tick_o=%b", max_tick_o);

    // Test Case 5: asynchronous reset during active counting
    #2;
