`timescale 1ns / 1ps
module testbench;

reg clk;
reg reset;
reg flagz;
reg flagn;
reg [3:0] opcode;

wire pc_inicio;
wire pc_inc;
wire pc_wr;
wire ir_wr;
wire ir_re;
wire mar_wr;
wire clk_md;
wire clk_mi;
wire mbr_wr_m;
wire mbr_wr_b;
wire mbr_re_b;
wire ac_wr;
wire ac_re;
wire [3:0] ula_sel;
wire ula_re;
wire wren;

integer case_no;

processador_fsm uut (
    .flagz(flagz),
    .flagn(flagn),
    .opcode(opcode),
    .clock(clk),
    .reset(reset),
    .pc_inicio(pc_inicio),
    .pc_inc(pc_inc),
    .pc_wr(pc_wr),
    .ir_wr(ir_wr),
    .ir_re(ir_re),
    .mar_wr(mar_wr),
    .clk_md(clk_md),
    .clk_mi(clk_mi),
    .mbr_wr_m(mbr_wr_m),
    .mbr_wr_b(mbr_wr_b),
    .mbr_re_b(mbr_re_b),
    .ac_wr(ac_wr),
    .ac_re(ac_re),
    .ula_sel(ula_sel),
    .ula_re(ula_re),
    .wren(wren)
);

initial clk = 1'b0;

always #5 clk = ~clk;

task run_case;
    input [3:0] test_opcode;
    input test_flagz;
    input test_flagn;
    input integer sample_cycles;
    integer k;
    begin
        case_no = case_no + 1;
        opcode = test_opcode;
        flagz = test_flagz;
        flagn = test_flagn;
        reset = 1'b1;
        repeat (2) @(posedge clk);
        reset = 1'b0;

        for (k = 0; k < sample_cycles; k = k + 1) begin
            @(posedge clk);
            #1 $display("TC%0d C%0d pc_inicio=%b pc_inc=%b pc_wr=%b ir_wr=%b ir_re=%b mar_wr=%b clk_md=%b clk_mi=%b mbr_wr_m=%b mbr_wr_b=%b mbr_re_b=%b ac_wr=%b ac_re=%b ula_sel=%b ula_re=%b wren=%b",
                case_no, k + 1,
                pc_inicio, pc_inc, pc_wr, ir_wr, ir_re, mar_wr,
                clk_md, clk_mi, mbr_wr_m, mbr_wr_b, mbr_re_b,
                ac_wr, ac_re, ula_sel, ula_re, wren);
        end
    end
endtask

/*
 * Starting from the reset state, advance a fixed number of rising edges
 * to the state whose distance from inicio is "state_steps", assert
 * synchronous reset for one rising edge, and sample the resulting outputs.
 *
 * State distances from inicio are:
 *   inicio       = 0
 *   ler_ir       = 1
 *   dec_opcode_1 = 2
 *   dec_opcode_2 = 3
 *   execution states begin at distance 4
 */
task reset_at_state;
    input integer state_steps;
    begin
        repeat (state_steps) @(posedge clk);
        reset = 1'b1;
        @(posedge clk);
        #1 $display("RESET_RECOVERY S%0d pc_inicio=%b pc_inc=%b pc_wr=%b ir_wr=%b ir_re=%b mar_wr=%b clk_md=%b clk_mi=%b mbr_wr_m=%b mbr_wr_b=%b mbr_re_b=%b ac_wr=%b ac_re=%b ula_sel=%b ula_re=%b wren=%b",
            state_steps,
            pc_inicio, pc_inc, pc_wr, ir_wr, ir_re, mar_wr,
            clk_md, clk_mi, mbr_wr_m, mbr_wr_b, mbr_re_b,
            ac_wr, ac_re, ula_sel, ula_re, wren);
        reset = 1'b0;
    end
endtask

/*
 * Cover reset recovery from every reachable state. After each reset pulse,
 * the DUT is in inicio, so each subsequent state is reached from inicio
 * using a fixed clock count.
 */
task reset_recovery_sweep;
    input [3:0] sweep_opcode;
    input sweep_flagz;
    input sweep_flagn;
    integer k;
    begin
        opcode = sweep_opcode;
        flagz = sweep_flagz;
        flagn = sweep_flagn;

        reset = 1'b1;
        repeat (2) @(posedge clk);
        reset = 1'b0;

        /*
         * Common fetch and decode states:
         * inicio, ler_ir, dec_opcode_1, dec_opcode_2.
         */
        reset_at_state(0);
        reset_at_state(1);
        reset_at_state(2);
        reset_at_state(3);

        /*
         * Cover the complete load route and its increment state.
         */
        if (sweep_opcode == 4'b0000) begin
            for (k = 4; k <= 9; k = k + 1)
                reset_at_state(k);
        end

        /*
         * Cover the complete store route and its increment state.
         */
        if (sweep_opcode == 4'b0001) begin
            for (k = 4; k <= 9; k = k + 1)
                reset_at_state(k);
        end

        /*
         * Cover the complete binary ALU route and its increment state.
         */
        if ((sweep_opcode == 4'b0010) ||
            (sweep_opcode == 4'b0011) ||
            (sweep_opcode == 4'b0100) ||
            (sweep_opcode == 4'b0101) ||
            (sweep_opcode == 4'b0110) ||
            (sweep_opcode == 4'b0111)) begin
            for (k = 4; k <= 10; k = k + 1)
                reset_at_state(k);
        end

        /*
         * Cover the unary NOT route, which begins at ula_op_4.
         */
        if (sweep_opcode == 4'b1000) begin
            for (k = 4; k <= 6; k = k + 1)
                reset_at_state(k);
        end

        /*
         * Cover the jump state.
         */
        if ((sweep_opcode == 4'b1001) ||
            (sweep_opcode == 4'b1010) ||
            (sweep_opcode == 4'b1011)) begin
            reset_at_state(4);
        end

        /*
         * Cover the direct increment state.
         */
        if ((sweep_opcode == 4'b1100) ||
            (sweep_opcode == 4'b1111)) begin
            reset_at_state(4);
        end
    end
endtask

initial begin
    clk = 1'b0;
    reset = 1'b1;
    flagz = 1'b0;
    flagn = 1'b0;
    opcode = 4'h0;
    case_no = 0;

    repeat (2) @(posedge clk);
    #1 $display("RESET pc_inicio=%b pc_inc=%b pc_wr=%b ir_wr=%b ir_re=%b mar_wr=%b clk_md=%b clk_mi=%b mbr_wr_m=%b mbr_wr_b=%b mbr_re_b=%b ac_wr=%b ac_re=%b ula_sel=%b ula_re=%b wren=%b",
        pc_inicio, pc_inc, pc_wr, ir_wr, ir_re, mar_wr,
        clk_md, clk_mi, mbr_wr_m, mbr_wr_b, mbr_re_b,
        ac_wr, ac_re, ula_sel, ula_re, wren);
    reset = 1'b0;

    run_case(4'b0000, 1'b0, 1'b0, 10);
    run_case(4'b0001, 1'b0, 1'b0, 10);

    run_case(4'b0010, 1'b0, 1'b0, 11);
    run_case(4'b0011, 1'b0, 1'b0, 11);
    run_case(4'b0100, 1'b0, 1'b0, 11);
    run_case(4'b0101, 1'b0, 1'b0, 11);
    run_case(4'b0110, 1'b0, 1'b0, 11);
    run_case(4'b0111, 1'b0, 1'b0, 11);

    run_case(4'b1000, 1'b0, 1'b0, 8);
    run_case(4'b1001, 1'b0, 1'b0, 6);

    run_case(4'b1011, 1'b1, 1'b0, 6);
    run_case(4'b1011, 1'b0, 1'b0, 6);

    run_case(4'b1010, 1'b0, 1'b1, 6);
    run_case(4'b1010, 1'b0, 1'b0, 6);

    run_case(4'b1100, 1'b0, 1'b0, 6);
    run_case(4'b1111, 1'b0, 1'b0, 6);

    reset_recovery_sweep(4'b0000, 1'b0, 1'b0);
    reset_recovery_sweep(4'b0001, 1'b0, 1'b0);
    reset_recovery_sweep(4'b0010, 1'b0, 1'b0);
    reset_recovery_sweep(4'b1000, 1'b0, 1'b0);
    reset_recovery_sweep(4'b1001, 1'b0, 1'b0);
    reset_recovery_sweep(4'b1100, 1'b0, 1'b0);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam integer N = 1024;

// Inputs
reg clk;
reg sys_rst_n;
reg [7:0] ad_data;

// Outputs
wire ad_clk;
wire sign;
wire [15:0] volt;

integer profile;
integer code;
integer cycle;
integer low_sample;
integer high_sample;

adc #(.CNT_DATA_MAX(N)) uut (
    .sys_clk   (clk),
    .sys_rst_n (sys_rst_n),
    .ad_data   (ad_data),
    .ad_clk    (ad_clk),
    .sign      (sign),
    .volt      (volt)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [8*32-1:0] label;
    begin
        $display("t=%0t profile=%0d case=%0s rst_n=%b ad_data=%0d ad_clk=%b sign=%b volt=%0d",
                 $time, profile, label, sys_rst_n, ad_data,
                 ad_clk, sign, volt);
    end
endtask

task reset_dut;
    begin
        @(negedge clk);
        #2;
        sys_rst_n = 0;
        #1;
        observe("asynchronous reset");
        repeat (3) @(posedge clk);
        #1;
        observe("reset held");
        @(negedge clk);
        ad_data = 0;
        sys_rst_n = 1;
    end
endtask

// Each four-cycle block contains one sampling edge.
task apply_sample;
    input [7:0] value;
    begin
        @(negedge clk);
        ad_data = value;
        #1;
        observe("input changed");
        repeat (4) @(posedge clk);
        #1;
        observe("sampled conversion");
    end
endtask

task calibrate;
    input integer first_value;
    input integer second_value;
    begin
        reset_dut;
        ad_data = first_value;
        repeat (4 * (N / 2)) @(posedge clk);
        #1;
        observe("calibration midpoint");

        @(negedge clk);
        ad_data = second_value;
        repeat (4 * (N - N / 2)) @(posedge clk);
        #1;
        observe("window accumulated");

        @(negedge clk);
        ad_data = 255;
        #1;
        observe("terminal input applied");
        repeat (4) @(posedge clk);
        #1;
        observe("terminal edge completed");
    end
endtask

initial begin
    // Initialize inputs; allow 100 ns for global reset.
    sys_rst_n = 0;
    ad_data = 0;
    profile = -1;
    #100;
    observe("initial reset");

    // Clock phases and interruption of an incomplete calibration.
    reset_dut;
    ad_data = 200;
    for (cycle = 0; cycle < 8; cycle = cycle + 1) begin
        @(posedge clk);
        #1;
        observe("clock phase");
    end
    repeat (4 * 7) @(posedge clk);
    #1;
    observe("partial calibration");
    reset_dut;

    // Independent calibration and exhaustive input sweep per profile.
    for (profile = 0; profile < 9; profile = profile + 1) begin
        case (profile)
            0: begin low_sample = 0;   high_sample = 0;   end
            1: begin low_sample = 1;   high_sample = 1;   end
            2: begin low_sample = 2;   high_sample = 2;   end
            3: begin low_sample = 3;   high_sample = 3;   end
            4: begin low_sample = 64;  high_sample = 65;  end
            5: begin low_sample = 128; high_sample = 128; end
            6: begin low_sample = 252; high_sample = 252; end
            7: begin low_sample = 254; high_sample = 254; end
            8: begin low_sample = 255; high_sample = 255; end
        endcase

        calibrate(low_sample, high_sample);

        // Establish a converted endpoint before the sweep starts at zero.
        apply_sample(255);
        for (code = 0; code < 256; code = code + 1) begin
            apply_sample(code);
            #1;
        end

        // Later samples must not initiate another baseline calibration.
        apply_sample(0);
        repeat (4 * (N + 2)) @(posedge clk);
        #1;
        observe("extended changed input");
        apply_sample(255);
        apply_sample(low_sample);
    end

    reset_dut;
    #1;
    observe("final reset released");

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps

module testbench;

localparam integer TB_CLKS_PER_BIT = 4;

// Generous bounded window for eight UART frames plus controller overhead.
localparam integer TB_PAYLOAD_CYCLES =
    8 * (10 * TB_CLKS_PER_BIT + 8);

reg        clk;
reg        i_rst;
reg        i_rxd;
reg [63:0] i_fft_data;
reg        i_tx_valid;

wire       o_txd;
wire       o_tx_ready;

UART_CONTROLLER #(
    .length(32),
    .CLKS_PER_BIT(TB_CLKS_PER_BIT),
    .SIG_RUN(82),
    .SIG_STOP(83),
    .DATA_LENGTH(2)
) uut (
    .i_clk      (clk),
    .i_rst      (i_rst),
    .i_rxd      (i_rxd),
    .o_txd      (o_txd),
    .i_fft_data (i_fft_data),
    .i_tx_valid (i_tx_valid),
    .o_tx_ready (o_tx_ready)
);

initial clk = 1'b0;
always #5 clk = ~clk;

// Sample only externally visible DUT outputs after NBA updates.
task sample_outputs;
    input integer cycles;
    integer sample_index;
begin
    for (sample_index = 0; sample_index < cycles;
         sample_index = sample_index + 1) begin
        @(posedge clk);
        #1;
        $display("SAMPLE time=%0t o_txd=%b o_tx_ready=%b",
                 $time, o_txd, o_tx_ready);
    end
end
endtask

task reset_dut;
begin
    @(negedge clk);
    i_rst      = 1'b1;
    i_rxd      = 1'b1;
    i_tx_valid = 1'b0;
    i_fft_data = 64'b0;

    repeat (2) @(posedge clk);
    #1;
    // During an interrupted transfer, the UART engine is not reset.
    $display("RESET: o_txd=%b o_tx_ready=%b",
             o_txd, o_tx_ready);

    @(negedge clk);
    i_rst = 1'b0;
    repeat (2) @(posedge clk);
    #1;
    $display("RESET RELEASE: o_txd=%b o_tx_ready=%b",
             o_txd, o_tx_ready);
end
endtask

task uart_command;
    input [7:0] command;
    integer bit_index;
begin
    @(negedge clk);
    i_rxd = 1'b0;
    repeat (TB_CLKS_PER_BIT) @(posedge clk);

    for (bit_index = 0; bit_index < 8;
         bit_index = bit_index + 1) begin
        @(negedge clk);
        i_rxd = command[bit_index];
        repeat (TB_CLKS_PER_BIT) @(posedge clk);
    end

    @(negedge clk);
    i_rxd = 1'b1;
    repeat (TB_CLKS_PER_BIT) @(posedge clk);

    // Include synchronization, receiver cleanup, and controller latency.
    repeat (8) @(posedge clk);
    #1;
    $display("COMMAND command=%02h: o_txd=%b o_tx_ready=%b",
             command, o_txd, o_tx_ready);
end
endtask

task provide_payload;
    input [63:0] payload;
begin
    @(negedge clk);
    i_fft_data = payload;
    i_tx_valid = 1'b1;

    @(posedge clk);
    #1;
    $display("PAYLOAD HANDSHAKE: o_txd=%b o_tx_ready=%b",
             o_txd, o_tx_ready);

    @(negedge clk);
    i_tx_valid = 1'b0;
    // Subsequent transmission uses the previously captured payload.
    i_fft_data = 64'b0;
end
endtask

task observe_payload;
    input [63:0] payload;
begin
    provide_payload(payload);
    sample_outputs(TB_PAYLOAD_CYCLES);
    $display("PAYLOAD COMPLETE: o_txd=%b o_tx_ready=%b",
             o_txd, o_tx_ready);
end
endtask

task false_start;
begin
    // One input-clock low pulse reaches the synchronizer but is high
    // again before the receiver validates the start-bit midpoint.
    @(negedge clk);
    i_rxd = 1'b0;
    @(posedge clk);
    @(negedge clk);
    i_rxd = 1'b1;

    sample_outputs(3 * TB_CLKS_PER_BIT + 8);
    $display("FALSE START COMPLETE: o_txd=%b o_tx_ready=%b",
             o_txd, o_tx_ready);
end
endtask

initial begin
    i_rst      = 1'b0;
    i_rxd      = 1'b1;
    i_tx_valid = 1'b0;
    i_fft_data = 64'b0;

    reset_dut();

    // Test Case 1: STOP and unrecognized commands.
    uart_command(8'd83);
    $display("STOP COMMAND: o_txd=%b o_tx_ready=%b",
             o_txd, o_tx_ready);

    uart_command(8'd0);
    $display("UNKNOWN COMMAND: o_txd=%b o_tx_ready=%b",
             o_txd, o_tx_ready);

    uart_command(8'hFF);
    uart_command(8'h55);
    uart_command(8'hAA);

    // A parallel valid pulse without a RUN command.
    provide_payload(64'hDEADBEEF01234567);
    sample_outputs(12);

    // Test Case 2: RUN, delayed FFT handshake, complete payload.
    reset_dut();
    uart_command(8'd82);
    sample_outputs(12);
    $display("RUN REQUEST: o_txd=%b o_tx_ready=%b",
             o_txd, o_tx_ready);
    observe_payload(64'h0123456789ABCDEF);

    // Test Case 3: Two payloads followed by the threshold command.
    reset_dut();

    uart_command(8'd82);
    $display("PAYLOAD 1 REQUEST: o_txd=%b o_tx_ready=%b",
             o_txd, o_tx_ready);
    observe_payload(64'h1122334455667788);

    uart_command(8'd82);
    $display("PAYLOAD 2 REQUEST: o_txd=%b o_tx_ready=%b",
             o_txd, o_tx_ready);
    observe_payload(64'hA1B2C3D4E5F60718);

    uart_command(8'd82);
    sample_outputs(12);
    $display("THRESHOLD COMMAND: o_txd=%b o_tx_ready=%b",
             o_txd, o_tx_ready);

    // Test Case 4: A later RUN starts a new interval.
    uart_command(8'd82);
    $display("NEW INTERVAL REQUEST: o_txd=%b o_tx_ready=%b",
             o_txd, o_tx_ready);
    observe_payload(64'hFEDCBA9876543210);

    // Test Case 5: Rejected RX start pulse and normal-command recovery.
    reset_dut();
    false_start();
    uart_command(8'd82);
    observe_payload(64'h0000000000000000);

    // Test Case 6: Reset with an outstanding FFT request.
    reset_dut();
    uart_command(8'd82);
    sample_outputs(16);
    $display("BEFORE FFT-WAIT RESET: o_txd=%b o_tx_ready=%b",
             o_txd, o_tx_ready);

    reset_dut();
    sample_outputs(12);
    uart_command(8'd82);
    observe_payload(64'hFFFFFFFFFFFFFFFF);

    // Test Case 7: Reset during active transmission.
    reset_dut();
    uart_command(8'd82);
    provide_payload(64'h55AA00FFFF00AA55);

    // The first byte has started, but cannot yet have completed.
    sample_outputs(6);
    $display("BEFORE TRANSMIT RESET: o_txd=%b o_tx_ready=%b",
             o_txd, o_tx_ready);

    reset_dut();

    // Top-level reset does not reset uart_tx. Give the already-launched
    // byte enough time to finish, then observe the settled outputs.
    sample_outputs(12 * TB_CLKS_PER_BIT + 8);
    $display("AFTER TRANSMITTER DRAIN: o_txd=%b o_tx_ready=%b",
             o_txd, o_tx_ready);

    uart_command(8'd82);
    observe_payload(64'hAA55AA5555AA55AA);

    // Test Case 8: Commands received while waiting for FFT data.
    reset_dut();
    uart_command(8'd82);
    uart_command(8'd83);
    uart_command(8'hA5);
    uart_command(8'd82);
    sample_outputs(12);
    $display("BUSY FFT REQUEST: o_txd=%b o_tx_ready=%b",
             o_txd, o_tx_ready);
    observe_payload(64'h8040201008040201);

    // Test Case 9: Commands during active payload transmission.
    // This is the second completed payload in the current interval.
    uart_command(8'd82);
    provide_payload(64'h7FBFDFEFF7FBFDFE);
    sample_outputs(6);

    uart_command(8'd83);
    uart_command(8'd82);
    uart_command(8'h00);

    // A full bounded window from here includes the remaining payload
    // and idle time, exposing any additional externally visible activity.
    sample_outputs(TB_PAYLOAD_CYCLES);
    $display("BUSY-COMMAND TRANSFER COMPLETE: o_txd=%b o_tx_ready=%b",
             o_txd, o_tx_ready);

    // Repeat threshold and new-interval behavior after busy commands.
    uart_command(8'd82);
    sample_outputs(12);
    $display("SECOND THRESHOLD COMMAND: o_txd=%b o_tx_ready=%b",
             o_txd, o_tx_ready);

    uart_command(8'd82);
    observe_payload(64'h00FF55AA12345678);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

// Unused clock retained for the standard testbench structure.
reg clk;

// Inputs
reg [31:0] transformation_array_input0;
reg [31:0] transformation_array_input1;

// Outputs
wire [31:0] transformation_array_output0;
wire [31:0] transformation_array_output1;

// Instantiate the top-level DUT
shared_transformation_array uut (
    .transformation_array_input0  (transformation_array_input0),
    .transformation_array_input1  (transformation_array_input1),
    .transformation_array_output0 (transformation_array_output0),
    .transformation_array_output1 (transformation_array_output1)
);

initial clk = 1'b0;

always #5 clk = ~clk;

initial begin
    transformation_array_input0 = 32'h00000000;
    transformation_array_input1 = 32'h00000000;
    #1;
    $display("TC1 all zero: input0=%h input1=%h output0=%h output1=%h",
             transformation_array_input0, transformation_array_input1,
             transformation_array_output0, transformation_array_output1);

    transformation_array_input0 = 32'hFFFFFFFF;
    transformation_array_input1 = 32'hFFFFFFFF;
    #1;
    $display("TC2 all ones: input0=%h input1=%h output0=%h output1=%h",
             transformation_array_input0, transformation_array_input1,
             transformation_array_output0, transformation_array_output1);

    transformation_array_input0 = 32'h01234567;
    transformation_array_input1 = 32'h89ABCDEF;
    #1;
    $display("TC3 all nibble values: input0=%h input1=%h output0=%h output1=%h",
             transformation_array_input0, transformation_array_input1,
             transformation_array_output0, transformation_array_output1);

    transformation_array_input0 = 32'h13579BDF;
    transformation_array_input1 = 32'h00000000;
    #1;
    $display("TC4 word0 independence: input0=%h input1=%h output0=%h output1=%h",
             transformation_array_input0, transformation_array_input1,
             transformation_array_output0, transformation_array_output1);

    transformation_array_input0 = 32'h00000000;
    transformation_array_input1 = 32'h2468ACE0;
    #1;
    $display("TC5 word1 independence: input0=%h input1=%h output0=%h output1=%h",
             transformation_array_input0, transformation_array_input1,
             transformation_array_output0, transformation_array_output1);

    transformation_array_input0 = 32'h80000001;
    transformation_array_input1 = 32'h7FFFFFFE;
    #1;
    $display("TC6 boundary transitions: input0=%h input1=%h output0=%h output1=%h",
             transformation_array_input0, transformation_array_input1,
             transformation_array_output0, transformation_array_output1);

    $display("===========End===========");

    $finish;
end

