`timescale 1ns / 1ps
module testbench;

reg clk;
reg reset;
reg start;
reg CO;
reg Z;

wire WE;
wire Busy;
wire [1:0] InsSel;
wire [2:0] InMuxAdd;
wire [3:0] OutMuxAdd;
wire [3:0] RegAdd;
wire [7:0] CUconst;

integer i;
integer target;
integer advance_cycles;
integer j;

CU uut (
    .clk      (clk),
    .reset    (reset),
    .start    (start),
    .CO       (CO),
    .Z        (Z),
    .WE       (WE),
    .Busy     (Busy),
    .InsSel   (InsSel),
    .InMuxAdd (InMuxAdd),
    .OutMuxAdd(OutMuxAdd),
    .RegAdd   (RegAdd),
    .CUconst  (CUconst)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input integer tag;
    begin
        $display("OBS %0d: WE=%b Busy=%b InsSel=%b InMuxAdd=%b OutMuxAdd=%b RegAdd=%b CUconst=%b",
                 tag, WE, Busy, InsSel, InMuxAdd, OutMuxAdd,
                 RegAdd, CUconst);
    end
endtask

task clock_observe;
    input integer tag;
    begin
        @(posedge clk);
        #1;
        observe(tag);
    end
endtask

task reset_dut;
    begin
        // Assert and release away from rising edges.
        @(negedge clk);
        start = 0;
        CO    = 0;
        Z     = 0;
        reset = 1;
        #2;
        observe(1);
        reset = 0;
        #1;
        observe(2);
    end
endtask

initial begin
    reset = 0;
    start = 0;
    CO    = 0;
    Z     = 0;

    // Test Case 1: reset and idle behavior
    reset_dut;
    repeat (2) clock_observe(10);

    // Test Case 2: initialization and direct carry-high finalization
    reset_dut;
    CO = 1;
    start = 1;
    clock_observe(20);
    start = 0;

    for (i = 1; i <= 14; i = i + 1)
        clock_observe(20 + i);

    clock_observe(35);
    clock_observe(36);
    clock_observe(37);
    clock_observe(38);

    // Start is ignored after completion.
    start = 1;
    clock_observe(39);
    start = 0;

    // Test Case 3: carry-low loop iterations followed by carry-high exit
    reset_dut;
    CO = 0;
    Z  = 1;
    start = 1;
    clock_observe(50);
    start = 0;

    for (i = 1; i <= 14; i = i + 1)
        clock_observe(50 + i);

    for (i = 1; i <= 5; i = i + 1)
        clock_observe(70 + i);

    for (i = 1; i <= 5; i = i + 1)
        clock_observe(80 + i);

    CO = 1;
    clock_observe(90);
    clock_observe(91);
    clock_observe(92);
    clock_observe(93);
    clock_observe(94);

    // Complete steps 20, 21 and 22 after the carry-high exit.
    clock_observe(95);
    clock_observe(96);
    clock_observe(97);

    // Extended terminal hold with start requests and status changes.
    for (i = 0; i < 6; i = i + 1) begin
        @(negedge clk);
        start = (i % 2);
        CO = ((i / 2) % 2);
        Z = (i % 2);
        clock_observe(100 + i);
    end

    // Test Case 4: reset from every active sequencer step.
    //
    // After launch, step 1 is pending.
    // CO=0 reaches steps 1..19 with target-1 additional clocks.
    // CO=1 skips 16..19, reaching 20..22 with target-5 clocks.
    // These are fixed traversal lengths, not internal-state polling.
    for (target = 1; target <= 22; target = target + 1) begin
        reset_dut;
        CO = (target >= 20);
        Z = (target % 2);
        start = 1;
        clock_observe(1000 + target * 100);

        if (target <= 19)
            advance_cycles = target - 1;
        else
            advance_cycles = target - 5;

        for (j = 0; j < advance_cycles; j = j + 1) begin
            @(negedge clk);
            // Start must be ignored throughout the active sequence.
            start = (j % 2);
            Z = ((j + target) % 2);
            clock_observe(1001 + target * 100 + j);
        end

        // Abort the pending target step asynchronously.
        // The first sample precedes any subsequent rising edge.
        @(negedge clk);
        #1;
        start = (target % 2);
        CO = ~CO;
        Z = ~Z;
        reset = 1;
        #1;
        observe(5000 + target);

        // Also exercise reset dominance with reset held over a clock.
        clock_observe(5100 + target);

        @(negedge clk);
        start = 0;
        reset = 0;
        #1;
        observe(5200 + target);

        // Confirm idle output retention through external sampling.
        clock_observe(5300 + target);
    end

    // Test Case 5: normal complete operation after the abort sweep,
    // with start continuously asserted during active and terminal steps.
    reset_dut;
    start = 1;
    CO = 1;
    clock_observe(6000);

    for (i = 1; i <= 18; i = i + 1) begin
        @(negedge clk);
        Z = (i % 2);
        clock_observe(6000 + i);
    end

    repeat (3) clock_observe(6100);
    start = 0;
    clock_observe(6101);

    $display("===========End===========");
    $finish;
end

endmodule

