    .alu2_rob_dest(alu2_rob_dest)
);

initial clk = 0;
always #5 clk = ~clk;

function [31:0] enc_i;
    input [5:0] funct3;
    input [4:0] rs1;
    input [4:0] rd;
    input [11:0] imm;
    begin
        enc_i = {imm, rs1, funct3[2:0], rd, 7'b0010011};
    end
endfunction

function [31:0] enc_i_raw;
    input [6:0] funct7;
    input [2:0] funct3;
    input [4:0] rs1;
    input [4:0] rd;
    input [4:0] shamt;
    begin
        enc_i_raw = {funct7, shamt, rs1, funct3, rd, 7'b0010011};
    end
endfunction

function [31:0] enc_jalr;
    input [4:0] rs1;
    input [4:0] rd;
    input [11:0] imm;
    begin
        enc_jalr = {imm, rs1, 3'b000, rd, 7'b1100111};
    end
endfunction

function [31:0] enc_r;
    input [6:0] funct7;
    input [5:0] funct3;
    input [4:0] rs1;
    input [4:0] rs2;
    input [4:0] rd;
    begin
        enc_r = {funct7, rs2, rs1, funct3[2:0], rd, 7'b0110011};
    end
endfunction

function [31:0] enc_b;
    input [2:0] funct3;
    input [4:0] rs1;
    input [4:0] rs2;
    input [12:0] imm;
    begin
        // B-type immediate bit 0 is implicit, not part of the encoding.
        enc_b = {imm[12], imm[10:5], rs2, rs1, funct3,
                 imm[4:1], imm[11], 7'b1100011};
    end
endfunction

function [31:0] enc_l;
    input [2:0] funct3;
    input [4:0] rs1;
    input [4:0] rd;
    input [11:0] imm;
    begin
        enc_l = {imm, rs1, funct3, rd, 7'b0000011};
    end
endfunction

function [31:0] enc_s;
    input [2:0] funct3;
    input [4:0] rs1;
    input [4:0] rs2;
    input [11:0] imm;
    begin
        enc_s = {imm[11:5], rs2, rs1, funct3, imm[4:0],
                 7'b0100011};
    end
endfunction

function [31:0] enc_simple;
    input [6:0] opcode;
    begin
        enc_simple = {25'b0, opcode};
    end
endfunction

task observe;
    input [511:0] tag;
    begin
        $display("%0s | rename_need=%b simple=%b branch_store=%b rename_id=%h",
                 tag, rename_need, rename_need_ins_is_simple,
                 rename_need_ins_is_branch_or_store, rename_need_id);
        $display("rename_flags=%b%b operand_regs=%h,%h rd_rename=%h rd=%h",
                 operand_1_flag, operand_2_flag, operand_1_reg,
                 operand_2_reg, new_ins_rd_rename, new_ins_rd);
        $display("ls=%b rnm=%h op=%h offset=%h rs1=%h store_rs2=%h",
                 ls_mission, ls_ins_rnm, ls_op_type, ls_addr_offset,
                 ls_ins_rs1, store_ins_rs2);
        $display("alu1=%b op=%h rs1=%h rs2=%h dest=%h",
                 alu1_mission, alu1_op_type, alu1_rs1, alu1_rs2,
                 alu1_rob_dest);
        $display("alu2=%b op=%h rs1=%h rs2=%h dest=%h",
                 alu2_mission, alu2_op_type, alu2_rs1, alu2_rs2,
                 alu2_rob_dest);
    end
endtask

task tick;
    input [511:0] tag;
    begin
        @(posedge clk);
        #1 observe(tag);
    end
endtask

task reset_dut;
    begin
        rst = 1;
        rdy = 1;
        rs_flush = 0;
        new_ins_flag = 0;
        rename_finish = 0;
        rs_update_flag = 0;
        tick("reset");
        rst = 0;
        tick("post_reset");
    end
endtask

task allocate;
    input [31:0] ins;
    input [3:0] rn;
    input [4:0] rd;
    input [511:0] tag;
    begin
        new_ins = ins;
        rename = rn;
        rename_reg = rd;
        new_ins_flag = 1;
        @(posedge clk);
        #1;
        last_id = rename_need_id;
        observe(tag);
        new_ins_flag = 0;
    end
endtask

// One rename-completion edge, optionally accompanied by a broadcast.
// No extra issue edge here, so callers can compose overlapping activity.
task complete_sources;
    input [3:0] id;
    input busy1;
    input busy2;
    input [3:0] producer1;
    input [3:0] producer2;
    input [31:0] value1;
    input [31:0] value2;
    input broadcast_valid;
    input [3:0] commit_id;
    input [31:0] broadcast_value;
    input [511:0] tag;
    begin
        rename_finish = 1;
        rename_finish_id = id;
        operand_1_busy = busy1;
        operand_2_busy = busy2;
        operand_1_rename = producer1;
        operand_2_rename = producer2;
        operand_1_data_from_reg = value1;
        operand_2_data_from_reg = value2;
        rs_update_flag = broadcast_valid;
        rs_commit_rename = commit_id;
        rs_value = broadcast_value;
        tick(tag);
        rename_finish = 0;
        rs_update_flag = 0;
    end
endtask

task finish_ready_one;
    input [31:0] value1;
    input [31:0] value2;
    input [511:0] tag;
    begin
        complete_sources(last_id, 0, 0, 0, 0, value1, value2,
                         0, 0, 0, tag);
        tick("issue_after_register_values");
    end
endtask

task finish_ready_two;
    input [3:0] id;
    input [31:0] value1;
    input [31:0] value2;
    input [511:0] tag;
    begin
        complete_sources(id, 0, 0, 0, 0, value1, value2,
                         0, 0, 0, tag);
        tick("issue_after_two_register_values");
    end
endtask

task finish_busy;
    input [3:0] id;
    input [3:0] producer1;
    input [3:0] producer2;
    input [511:0] tag;
    begin
        complete_sources(id, 1, 1, producer1, producer2, 0, 0,
                         0, 0, 0, tag);
    end
endtask

task finish_busy_with_broadcast;
    input [3:0] id;
    input [3:0] producer1;
    input [3:0] producer2;
    input [3:0] commit_id;
    input [31:0] value;
    input [511:0] tag;
    begin
        complete_sources(id, 1, 1, producer1, producer2, 0, 0,
                         1, commit_id, value, tag);
        tick("issue_after_same_cycle_broadcast");
    end
endtask

task broadcast;
    input [3:0] producer;
    input [31:0] value;
    input [511:0] tag;
    begin
        rs_update_flag = 1;
        rs_commit_rename = producer;
        rs_value = value;
        tick(tag);
        rs_update_flag = 0;
    end
endtask

initial begin
    rst = 0;
    rdy = 1;
    new_ins_flag = 0;
    new_ins = 0;
    rename = 0;
    rename_reg = 0;
    rename_finish = 0;
    rename_finish_id = 0;
    operand_1_busy = 0;
    operand_2_busy = 0;
    operand_1_rename = 0;
    operand_2_rename = 0;
    operand_1_data_from_reg = 0;
    operand_2_data_from_reg = 0;
    rs_update_flag = 0;
    rs_commit_rename = 0;
    rs_value = 0;
    rs_flush = 0;

    reset_dut;
    allocate(enc_simple(7'b0110111), 4'h1, 5'd5, "LUI_simple");
    allocate(enc_simple(7'b0010111), 4'h2, 5'd6, "AUIPC_simple");
    allocate(enc_simple(7'b1101111), 4'h3, 5'd7, "JAL_simple");

    reset_dut;
    allocate(enc_jalr(5'd3, 5'd8, 12'h801), 4'h4, 5'd8, "JALR");
    finish_ready_one(32'h11111111, 32'h22222222, "JALR_rename");

    reset_dut;
    for (k = 0; k < 6; k = k + 1) begin
        @(negedge clk);
        allocate(enc_b(k == 0 ? 3'b000 :
                       k == 1 ? 3'b001 :
                       k == 2 ? 3'b100 :
                       k == 3 ? 3'b101 :
                       k == 4 ? 3'b110 : 3'b111,
                       5'd2, 5'd3, 13'h1000),
                 k + 1, 5'd9 + k, "branch_class");
        finish_ready_two(last_id, 32'h10000000 + k,
                         32'h20000000 + k, "branch_rename");
    end

    reset_dut;
    for (k = 0; k < 5; k = k + 1) begin
        @(negedge clk);
        allocate(enc_l(k == 0 ? 3'b000 :
                       k == 1 ? 3'b001 :
                       k == 2 ? 3'b010 :
                       k == 3 ? 3'b100 : 3'b101,
                       5'd4, 5'd10 + k, 12'h801),
                 k + 1, 5'd10 + k, "load_class");
        finish_ready_one(32'h30000000 + k, 32'h0, "load_rename");
    end

    reset_dut;
    for (k = 0; k < 3; k = k + 1) begin
        @(negedge clk);
        allocate(enc_s(k[2:0], 5'd5, 5'd6, 12'h801),
                 k + 1, 5'd11 + k, "store_class");
        finish_ready_two(last_id, 32'h40000000 + k,
                         32'h50000000 + k, "store_rename");
    end

    reset_dut;
    for (k = 0; k < 6; k = k + 1) begin
        @(negedge clk);
        allocate(enc_i(k == 0 ? 6'd0 :
                       k == 1 ? 6'd2 :
                       k == 2 ? 6'd3 :
                       k == 3 ? 6'd4 :
                       k == 4 ? 6'd6 : 6'd7,
                       5'd7, 5'd12 + k, 12'h801),
                 k + 1, 5'd12 + k, "immediate_alu");
        finish_ready_one(32'h60000000 + k, 32'h0,
                         "immediate_rename");
    end

    reset_dut;
    for (k = 0; k < 3; k = k + 1) begin
        @(negedge clk);
        allocate(enc_i(k == 0 ? 6'd1 : 6'd5,
                       5'd8, 5'd2 + k,
                       k == 2 ? 12'h400 : 12'h01f),
                 k + 1, 5'd2 + k, "shift_immediate");
        finish_ready_one(32'h70000000 + k, 32'h0, "shift_rename");
    end

    reset_dut;
    allocate(enc_r(7'b0000000, 6'd0, 5'd1, 5'd2, 5'd3),
             4'h1, 5'd3, "ADD");
    finish_ready_two(last_id, 32'h01010101, 32'h02020202,
                     "ADD_rename");
    allocate(enc_r(7'b0100000, 6'd0, 5'd1, 5'd2, 5'd3),
             4'h2, 5'd3, "SUB");
    finish_ready_two(last_id, 32'h03030303, 32'h04040404,
                     "SUB_rename");

    // Extend the original register sweep with SRA.
    for (k = 1; k < 9; k = k + 1) begin
        @(negedge clk);
        allocate(enc_r(k == 8 ? 7'b0100000 : 7'b0000000,
                       k == 8 ? 6'd5 : k[5:0],
                       5'd1, 5'd2, 5'd4 + k),
                 k + 3, 5'd4 + k, "register_alu");
        finish_ready_two(last_id, 32'h10000000 + k,
                         32'h20000000 + k, "register_alu_rename");
    end

    reset_dut;
    allocate(enc_i(6'd0, 5'd9, 5'd1, 12'h123),
             4'h7, 5'd1, "wakeup_two_operands");
    finish_busy(last_id, 4'ha, 4'hb, "busy_rename");
    broadcast(4'ha, 32'habcdef01, "wakeup_operand_1");
    broadcast(4'hb, 32'h12345678, "wakeup_operand_2");
    tick("issue_after_broadcasts");

    reset_dut;
    allocate(enc_i(6'd0, 5'd1, 5'd2, 12'h010),
             4'h8, 5'd2, "mission_hold");
    finish_ready_one(32'h11112222, 32'h0, "mission_ready");
    rdy = 0;
    tick("mission_held_with_rdy_low");
    rdy = 1;
    tick("mission_after_rdy_restore");

    reset_dut;
    allocate(enc_b(3'b000, 5'd1, 5'd2, 13'h0000),
             4'h9, 5'd0, "flush_pending_entry");
    rs_flush = 1;
    tick("flush_enabled");
    rs_flush = 0;

    reset_dut;
    allocate(enc_l(3'b010, 5'd1, 5'd2, 12'h7ff),
             4'ha, 5'd2, "positive_offset_boundary");
    finish_ready_one(32'h80000000, 32'h0, "positive_offset_rename");

    reset_dut;
    allocate(enc_s(3'b010, 5'd1, 5'd2, 12'h800),
             4'hb, 5'd0, "negative_offset_boundary");
    finish_ready_two(last_id, 32'h90000000, 32'ha0000000,
                     "negative_offset_rename");

    reset_dut;
    allocate(enc_b(3'b001, 5'd2, 5'd3, 13'h0002),
             4'h1, 5'd1, "BNE_directed");
    finish_ready_two(last_id, 32'h11110001, 32'h22220001,
                     "BNE_directed_rename");

    reset_dut;
    allocate(enc_b(3'b101, 5'd2, 5'd3, 13'h0004),
             4'h2, 5'd2, "BGE_directed");
    finish_ready_two(last_id, 32'h11110002, 32'h22220002,
                     "BGE_directed_rename");

    reset_dut;
    allocate(enc_b(3'b111, 5'd2, 5'd3, 13'h0006),
             4'h3, 5'd3, "BGEU_directed");
    finish_ready_two(last_id, 32'h11110003, 32'h22220003,
                     "BGEU_directed_rename");

    reset_dut;
    allocate(enc_r(7'b0000000, 6'd0, 5'd4, 5'd5, 5'd6),
             4'h4, 5'd6, "operand2_busy_path");
    finish_busy(last_id, 4'hc, 4'hd, "operand2_busy_rename");
    broadcast(4'hc, 32'hcafebabe, "operand2_busy_wakeup_1");
    broadcast(4'hd, 32'hdeadbeef, "operand2_busy_wakeup_2");
    tick("operand2_busy_issue");

    reset_dut;
    allocate(enc_r(7'b0000000, 6'd0, 5'd7, 5'd8, 5'd9),
             4'h5, 5'd9, "same_cycle_operand1");
    finish_busy_with_broadcast(last_id, 4'he, 4'hf, 4'he,
                              32'h13572468,
                              "same_cycle_operand1_broadcast");
    broadcast(4'hf, 32'h24681357, "same_cycle_operand1_operand2");
    tick("same_cycle_operand1_issue");

    reset_dut;
    allocate(enc_r(7'b0000000, 6'd0, 5'd10, 5'd11, 5'd12),
             4'h6, 5'd12, "same_cycle_operand2");
    finish_busy_with_broadcast(last_id, 4'he, 4'hf, 4'hf,
                              32'h89abcdef,
                              "same_cycle_operand2_broadcast");
    broadcast(4'he, 32'h76543210, "same_cycle_operand2_operand1");
    tick("same_cycle_operand2_issue");

    /*
     * Corrected dual-ALU test, extended to overflow both arbitration
     * classes. All five entries wait for the same broadcast.
     */
    reset_dut;
    allocate(enc_r(7'b0000000, 6'd0, 5'd1, 5'd2, 5'd13),
             4'h7, 5'd13, "dual_alu_first");
    saved_id = last_id;
    finish_busy(saved_id, 4'hf, 4'hf, "dual_alu_first_waiting");

    allocate(enc_r(7'b0100000, 6'd0, 5'd3, 5'd4, 5'd14),
             4'h8, 5'd14, "dual_alu_second");
    finish_busy(last_id, 4'hf, 4'hf, "dual_alu_second_waiting");

    allocate(enc_r(7'b0100000, 6'd5, 5'd31, 5'd0, 5'd15),
             4'h9, 5'd15, "third_alu_waiter");
    finish_busy(last_id, 4'hf, 4'hf, "third_alu_rename");

    allocate(enc_l(3'b010, 5'd31, 5'd16, 12'h800),
             4'ha, 5'd16, "first_ls_waiter");
    finish_busy(last_id, 4'hf, 4'hf, "first_ls_rename");

    allocate(enc_s(3'b010, 5'd0, 5'd31, 12'h7ff),
             4'hb, 5'd0, "second_ls_waiter");
    finish_busy(last_id, 4'hf, 4'hf, "second_ls_rename");

    broadcast(4'he, 32'h01020304, "nonmatching_fanout_broadcast");
    broadcast(4'hf, 32'hfedcba98, "common_fanout_wakeup");
    tick("dual_alu_plus_ls_issue");

    rdy = 0;
    tick("three_missions_held_1");
    tick("three_missions_held_2");
    rdy = 1;
    tick("remaining_alu_and_ls_issue");
    tick("dual_alu_ports_after_issue");

    /*
     * Matching broadcast with every combination of register/busy
     * sources. Tags match even when the corresponding busy input is 0.
     */
    reset_dut;
    for (k = 0; k < 4; k = k + 1) begin
        @(negedge clk);
        allocate(enc_r(7'b0000000, 6'd4, 5'd0, 5'd31, 5'd1),
                 k, 5'd1, "mixed_source_broadcast");
        complete_sources(last_id, k[0], k[1], 4'hc, 4'hc,
                         32'h01234567, 32'h89abcdef,
                         1, 4'hc, 32'ha5a55a5a,
                         "mixed_source_rename_and_broadcast");
        tick("mixed_source_issue");
        tick("mixed_source_idle");
    end

    // Operand 2 is already ready because allocation supplied immediate.
    reset_dut;
    allocate(enc_i(6'd0, 5'd31, 5'd0, 12'hfff),
             4'h0, 5'd0, "ready_immediate_guard");
    finish_busy_with_broadcast(last_id, 4'hd, 4'hd, 4'hd,
                              32'h80000001, "immediate_matching_broadcast");
    tick("immediate_guard_idle");

    /*
     * Defensive replay: first source stays ready while the second
     * source keeps the entry occupied. No DUT internal access is used.
     * Targets (!operand_1_rdy, busy, tag_match) = (0,1,1).
     */
    reset_dut;
    allocate(enc_r(7'b0000000, 6'd0, 5'd1, 5'd2, 5'd3),
             4'h3, 5'd3, "ready_operand1_guard");
    complete_sources(last_id, 0, 1, 4'hc, 4'hd,
                     32'h12345678, 0, 0, 0, 0,
                     "operand1_ready_operand2_pending");
    complete_sources(last_id, 1, 1, 4'hc, 4'hd,
                     0, 0, 1, 4'hc, 32'hffffffff,
                     "replay_ready_operand1_matching_broadcast");
    broadcast(4'hd, 32'h87654321, "release_pending_operand2");
    tick("ready_operand1_guard_issue");

    /*
     * The general broadcast scan services one entry while the
     * same-cycle rename bypass services a different entry.
     */
    reset_dut;
    allocate(enc_r(7'b0000000, 6'd6, 5'd1, 5'd2, 5'd3),
             4'h1, 5'd3, "general_scan_waiter");
    finish_busy(last_id, 4'hc, 4'hc, "general_scan_rename");

    allocate(enc_r(7'b0000000, 6'd7, 5'd4, 5'd5, 5'd6),
             4'h2, 5'd6, "same_edge_rename_waiter");
    complete_sources(last_id, 1, 1, 4'hc, 4'hc,
                     0, 0, 1, 4'hc, 32'h55aa55aa,
                     "general_scan_and_rename_bypass");
    tick("two_entries_issue_after_shared_broadcast");
    tick("shared_broadcast_idle");

    /*
     * A pre-rename broadcast is not the sole producer result:
     * resend after rename completion so the entry can drain.
     */
    reset_dut;
    allocate(enc_r(7'b0000000, 6'd2, 5'd1, 5'd2, 5'd3),
             4'h4, 5'd3, "broadcast_before_lookup");
    broadcast(4'hb, 32'h11111111, "broadcast_before_rename");
    finish_busy(last_id, 4'hb, 4'hb, "lookup_after_early_broadcast");
    tick("still_waiting_after_lookup");
    broadcast(4'hb, 32'h22222222, "broadcast_after_lookup");
    tick("issue_after_rebroadcast");

    /*
     * Fill exactly RSSIZE=16 entries, exercising every allocation ID,
     * rename array index, and broadcast fanout. Never allocate while full.
     */
    reset_dut;
    for (k = 0; k < 16; k = k + 1) begin
        @(negedge clk);
        allocate(enc_r(7'b0000000, k % 8,
                       k, 31-k, k),
                 k, k, "full_station_allocate");
        finish_busy(last_id, 4'hf, 4'hf, "full_station_waiting");
    end
    broadcast(4'h0, 32'h00000000, "full_station_nonmatch");
    broadcast(4'hf, 32'hffffffff, "full_station_wakeup");
    for (k = 0; k < 9; k = k + 1) begin
        @(posedge clk);
        #1 observe("full_station_drain");
    end

    /*
     * Allocation, completion, and broadcast overlap on distinct entries.
     * A previously ready instruction can issue on this same edge.
     */
    reset_dut;
    allocate(enc_i(6'd0, 5'd1, 5'd2, 12'h001),
             4'h1, 5'd2, "overlap_first");
    saved_id = last_id;
    allocate(enc_r(7'b0000000, 6'd0, 5'd3, 5'd4, 5'd5),
             4'h2, 5'd5, "overlap_second");
    complete_sources(saved_id, 0, 0, 0, 0,
                     32'h01010101, 0, 0, 0, 0,
                     "overlap_first_ready");

    new_ins_flag = 1;
    new_ins = enc_l(3'b010, 5'd6, 5'd7, 12'h000);
    rename = 4'h3;
    rename_reg = 5'd7;
    complete_sources(last_id, 1, 1, 4'ha, 4'ha,
                     0, 0, 1, 4'ha, 32'h02020202,
                     "allocate_rename_broadcast_issue_overlap");
    last_id = rename_need_id;
    new_ins_flag = 0;
    finish_ready_one(32'h03030303, 0, "overlap_load_rename");
    tick("overlap_drain");

    /*
     * Stall all normal actions and flush together, then accept flush
     * with the other requests still asserted. Reset also overrides rdy.
     */
    reset_dut;
    allocate(enc_r(7'b0000000, 6'd0, 5'd1, 5'd2, 5'd3),
             4'h1, 5'd3, "flush_stall_pending");
    saved_id = last_id;
    rdy = 0;
    rs_flush = 1;
    new_ins_flag = 1;
    new_ins = enc_i(6'd0, 5'd4, 5'd5, 12'h7ff);
    rename = 4'h2;
    rename_reg = 5'd5;
    rename_finish = 1;
    rename_finish_id = saved_id;
    operand_1_busy = 1;
    operand_2_busy = 1;
    operand_1_rename = 4'hd;
    operand_2_rename = 4'hd;
    rs_update_flag = 1;
    rs_commit_rename = 4'hd;
    rs_value = 32'hcafed00d;
    tick("all_requests_stalled_with_flush");
    tick("all_requests_still_stalled");
    rdy = 1;
    tick("flush_priority_over_all_requests");
    new_ins_flag = 0;
    rename_finish = 0;
    rs_update_flag = 0;
    rs_flush = 0;
    tick("after_priority_flush");

    allocate(enc_i(6'd0, 5'd1, 5'd2, 12'h001),
             4'h3, 5'd2, "reset_priority_pending");
    rst = 1;
    rdy = 0;
    tick("reset_while_rdy_low");
    rst = 0;
    tick("hold_after_reset");
    rdy = 1;
    tick("enabled_after_reset");

    /*
     * Original malformed-encoding probes, isolated before rename/issue.
     */
    reset_dut;
    allocate(enc_b(3'b010, 5'd1, 5'd2, 13'h0002),
             4'h9, 5'd0, "unsupported_branch_funct3");
    reset_dut;

    allocate(enc_l(3'b011, 5'd1, 5'd2, 12'h001),
             4'ha, 5'd2, "unsupported_load_funct3");
    reset_dut;

    allocate(enc_s(3'b011, 5'd1, 5'd2, 12'h001),
             4'hb, 5'd0, "unsupported_store_funct3");
    reset_dut;

    allocate(enc_i_raw(7'b1000000, 3'b101, 5'd1, 5'd2, 5'd3),
             4'hc, 5'd2, "unsupported_shift_immediate_funct7");
    reset_dut;

    allocate(enc_r(7'b1000000, 6'd0, 5'd1, 5'd2, 5'd3),
             4'hd, 5'd3, "unsupported_add_sub_funct7");
    reset_dut;

    allocate(enc_r(7'b1000000, 6'd5, 5'd1, 5'd2, 5'd3),
             4'he, 5'd3, "unsupported_shift_funct7");
    reset_dut;

    allocate({25'b0, 7'b0000000},
             4'hf, 5'd0, "unsupported_opcode");
    reset_dut;

    /*
     * Four-state defensive probes. All eight binary funct3 values
     * are covered by these two outer ALU cases, so only an X/Z
     * subfield can take their implicit missing-default path.
     * Flush/reset isolation prevents any malformed entry from issuing.
     */
    allocate(enc_i_raw(7'b0000000, 3'bxxx, 5'd1, 5'd2, 5'd3),
             4'h1, 5'd2, "unknown_immediate_funct3");
    reset_dut;

    allocate(enc_r(7'b0000000, 6'b000xxx, 5'd1, 5'd2, 5'd3),
             4'h2, 5'd3, "unknown_register_funct3");
    reset_dut;

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

reg clk;
reg q0;
reg qm1;
reg start;
reg eqz;

wire LdA;
wire clrA;
wire sftA;
wire LdQ;
wire clrQ;
wire sftQ;
wire sftDff;
wire clrff;
wire LdM;
wire clrM;
wire add_sub;
wire EnableALU;
wire decr;
wire LdCount;
wire done;

integer pair_index;

controller_BOOTH uut (
    .LdA(LdA),
    .clrA(clrA),
    .sftA(sftA),
    .LdQ(LdQ),
    .clrQ(clrQ),
    .sftQ(sftQ),
    .sftDff(sftDff),
    .clrff(clrff),
    .LdM(LdM),
    .clrM(clrM),
    .add_sub(add_sub),
    .EnableALU(EnableALU),
    .decr(decr),
    .LdCount(LdCount),
    .done(done),
    .clk(clk),
    .q0(q0),
    .qm1(qm1),
    .start(start),
    .eqz(eqz)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [255:0] label;
    begin
        $display(
            "%0s: start=%b eqz=%b q0=%b qm1=%b LdA=%b clrA=%b sftA=%b LdQ=%b clrQ=%b sftQ=%b sftDff=%b clrff=%b LdM=%b clrM=%b add_sub=%b EnableALU=%b decr=%b LdCount=%b done=%b",
            label, start, eqz, q0, qm1,
            LdA, clrA, sftA, LdQ, clrQ, sftQ, sftDff, clrff,
            LdM, clrM, add_sub, EnableALU, decr, LdCount, done
        );
    end
endtask

// Sample after the rising-edge nonblocking updates have settled.
task step;
    input [255:0] label;
    begin
        @(posedge clk);
        #1 observe(label);
    end
endtask

// With start low, eqz high terminates any active operation.
// Eight edges cover the longest path from any legal state to idle.
// This is a protocol drain, not an internal reset.
task initialize;
    begin
        @(negedge clk);
        q0 = 0;
        qm1 = 0;
        start = 0;
        eqz = 1;
        repeat (8) @(posedge clk);
        #1 observe("drain_to_idle");

        @(negedge clk);
        eqz = 0;
        repeat (2) @(posedge clk);
        #1 observe("startup_idle");
    end
endtask

// Accepted start followed by the mandatory startup sequence.
task launch;
    begin
        @(negedge clk);
        start = 1;
        step("clear");

        // Keep start asserted through clear to exercise ignored start.
        step("load");
        start = 0;
        step("dummy_before_decision");
        step("check");
    end
endtask

initial begin
    q0 = 0;
    qm1 = 0;
    start = 0;
    eqz = 0;

    // Observe natural simulation startup recovery before protocol draining.
    repeat (2) @(posedge clk);
    #1 observe("natural_startup_idle");

    // Test Case 1: pair 01 selects add; start outside idle is ignored.
    initialize;
    launch;

    q0 = 0;
    qm1 = 1;
    eqz = 0;
    start = 1;
    step("add_pair_01");

    start = 0;
    step("shift_after_add");
    step("dummy_after_add");
    step("check_after_add");

    // Complete the operation before beginning another independent test.
    eqz = 1;
    step("done_after_add");
    step("return_idle_after_add");

    // Test Case 2: pair 10 selects subtract.
    initialize;
    launch;

    q0 = 1;
    qm1 = 0;
    eqz = 0;
    step("sub_pair_10");

    step("shift_after_sub");
    step("dummy_after_sub");
    step("check_after_sub");

    eqz = 1;
    step("done_after_sub");
    step("return_idle_after_sub");

    // Test Case 3: pairs 00 and 11 select shift without arithmetic.
    initialize;
    launch;

    q0 = 0;
    qm1 = 0;
    eqz = 0;
    step("shift_pair_00");
    step("dummy_after_shift_00");
    step("check_shift_11");

    q0 = 1;
    qm1 = 1;
    step("shift_pair_11");
    step("dummy_after_shift_11");
    step("check_after_shift_11");

    eqz = 1;
    step("done_after_no_arithmetic");
    step("return_idle_after_shifts");

    // Test Case 4: completion has priority over every Booth pair.
    // Each iteration starts from a drained idle state.
    for (pair_index = 0; pair_index < 4; pair_index = pair_index + 1) begin
        @(negedge clk);
        initialize;
        launch;

        q0 = pair_index[1];
        qm1 = pair_index[0];
        eqz = 1;

        // Also exercise ignored start at the terminal check and in done.
        start = 1;
        step("done_priority");
        step("return_idle");

        // Deassert before the next idle sampling edge.
        start = 0;
        step("idle_eqz_still_high");
        step("idle_done_remains_low");
    end

    // Test Case 5: held start is ignored throughout the active sequence,
    // then accepted again only after the one-cycle done and idle states.
    initialize;

    @(negedge clk);
    start = 1;
    q0 = 0;
    qm1 = 1;
    eqz = 0;

    step("held_start_clear");
    step("held_start_load");
    step("held_start_dummy");
    step("held_start_check");
    step("held_start_add");

    q0 = 1;
    qm1 = 0;
    step("held_start_shift_add");
    step("held_start_dummy_sub");
    step("held_start_check_sub");
    step("held_start_sub");

    q0 = 1;
    qm1 = 1;
    step("held_start_shift_sub");
    step("held_start_dummy_11");
    step("held_start_check_11");
    step("held_start_shift_11");
    step("held_start_dummy_terminal");
    step("held_start_check_terminal");

    eqz = 1;
    step("held_start_done");
    step("held_start_idle");

    // Start is still high: this edge accepts the next transaction.
    step("held_start_restart_clear");

    start = 0;
    step("restart_load");
    step("restart_dummy");
    step("restart_check");
    step("restart_done");
    step("restart_return_idle");

    eqz = 0;
    step("final_idle");
    step("final_idle_hold");

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

// Inputs
reg clk;
reg [1:0] wdsel;
reg [15:0] alu;

// Outputs
wire [15:0] out;

integer sel;

wdselmux_7 uut (
    .wdsel(wdsel),
    .alu(alu),
    .out(out)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [1:0] select_value;
    input [15:0] data_value;
    begin
        wdsel = select_value;
        alu = data_value;
        #1;
        $display("wdsel=%b alu=%h out=%h", wdsel, alu, out);
    end
endtask

initial begin
    wdsel = 2'b00;
    alu = 16'h0000;

    // Allow 100 ns for startup.
    #100;
    $display("startup: wdsel=%b alu=%h out=%h", wdsel, alu, out);

    // All legal modes; ALU changes with selector held fixed.
    for (sel = 0; sel < 4; sel = sel + 1) begin
        observe(sel[1:0], 16'h0000);
        observe(sel[1:0], 16'hFFFF);
        observe(sel[1:0], 16'hAAAA);
        observe(sel[1:0], 16'h5555);
        observe(sel[1:0], 16'h0001);
        observe(sel[1:0], 16'h8000);
    end

    // Selector changes with ALU held fixed, including return to mode 0.
    for (sel = 3; sel >= 0; sel = sel - 1) begin
        observe(sel[1:0], 16'h8000);
    end

    // Supplementary four-state selector observations and recovery.
    observe(2'bxx, 16'h1234);
    observe(2'bxx, 16'hABCD);
    observe(2'bzz, 16'h1234);
    observe(2'bzz, 16'hABCD);
    observe(2'b00, 16'h0000);

    $display("===========End===========");

    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

// Inputs
reg clk;
reg [4:0] ReadRegister1, ReadRegister2, WriteRegister;
reg [63:0] WriteData;
reg RegWrite, reset;

// Outputs
wire [63:0] ReadData1, ReadData2;

integer i;

RegisterFile uut (
    .ReadRegister1(ReadRegister1),
    .ReadRegister2(ReadRegister2),
    .WriteRegister(WriteRegister),
    .ReadData1(ReadData1),
    .ReadData2(ReadData2),
    .WriteData(WriteData),
    .RegWrite(RegWrite),
    .reset(reset),
    .clk(clk)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [255:0] label;
    begin
        $display("%0s t=%0t reset=%b WE=%b WA=%0d WD=%016h RA1=%0d RA2=%0d ReadData1=%016h ReadData2=%016h",
                 label, $time, reset, RegWrite, WriteRegister, WriteData,
                 ReadRegister1, ReadRegister2, ReadData1, ReadData2);
    end
endtask

task initialize;
    begin
        @(negedge clk);
        reset = 1;
        RegWrite = 0;
        ReadRegister1 = 0;
        ReadRegister2 = 31;
        @(posedge clk);
        #1;
        observe("reset edge");
        @(negedge clk);
        reset = 0;
    end
endtask

task scan;
    input [255:0] label;
    integer address;
    begin
        for (address = 0; address < 32; address = address + 1) begin
            @(negedge clk);
            ReadRegister1 = address;
            ReadRegister2 = 31 - address;
            #1;
            observe(label);
        end
    end
endtask

task write_cycle;
    input [4:0] address;
    input [63:0] data;
    input enable;
    begin
        @(negedge clk);
        ReadRegister1 = address;
        ReadRegister2 = address;
        WriteRegister = address;
        WriteData = data;
        RegWrite = enable;
        #1;
        observe("before write edge");
        @(posedge clk);
        #1;
        observe("after write edge");
        @(negedge clk);
        RegWrite = 0;
    end
endtask

task populate;
    integer address;
    begin
        for (address = 0; address < 32; address = address + 1) begin
            #1;
            write_cycle(address, 64'hA5A500005A5A0000 ^ address, 1'b1);
        end
    end
endtask

initial begin
    ReadRegister1 = 0;
    ReadRegister2 = 0;
    WriteRegister = 0;
    WriteData = 0;
    RegWrite = 0;
    reset = 1;

    // Wait 100 ns for global reset to finish.
    #100;

    // Test Case 1: reset all addresses.
    initialize;
    scan("initial reset scan");

    // Test Case 2: writes, overwrites, independent asynchronous reads.
    initialize;
    populate;
    scan("populated scan");

    write_cycle(0,  64'hFFFFFFFFFFFFFFFF, 1'b1);
    write_cycle(31, 64'h0000000000000000, 1'b1);
    write_cycle(15, 64'hAAAAAAAAAAAAAAAA, 1'b1);
    write_cycle(16, 64'h5555555555555555, 1'b1);

    for (i = 0; i < 32; i = i + 1) begin
        @(negedge clk);
        ReadRegister1 = 0;
        ReadRegister2 = 31;
        #1;
        observe("async baseline");
        ReadRegister1 = i;
        #1;
        observe("port1 address change");
        ReadRegister2 = i;
        #1;
        observe("port2 same address");
        ReadRegister1 = 0;
        #1;
        observe("port1 restored");
    end
    scan("overwrite retention scan");

    // Test Case 3: disabled writes at every address.
    initialize;
    populate;
    for (i = 0; i < 32; i = i + 1) begin
        #1;
        write_cycle(i, 64'hFFFFFFFFFFFFFFFF, 1'b0);
    end
    scan("disabled write retention");

    // Test Case 4: synchronous reset with simultaneous write request.
    initialize;
    populate;
    @(negedge clk);
    ReadRegister1 = 0;
    ReadRegister2 = 31;
    WriteRegister = 31;
    WriteData = 64'hFFFFFFFFFFFFFFFF;
    RegWrite = 1;
    #1;
    observe("before reset assertion");
    reset = 1;
    #1;
    observe("reset before rising edge");
    @(posedge clk);
    #1;
    observe("reset overrides write");
    @(negedge clk);
    RegWrite = 0;
    reset = 0;
    scan("reset cleared all entries");

    write_cycle(0, 64'h0123456789ABCDEF, 1'b1);
    scan("write resumes after reset");

    $display("===========End===========");
    $finish;
end

