`timescale 1ns / 1ps
module testbench;

localparam integer TOTAL_EDGES = 33;

// Inputs
reg clk;
reg reset;
reg div;
reg div_signed;
reg [31:0] x;
reg [31:0] y;

// Outputs
wire [31:0] s;
wire [31:0] r;
wire complete;

integer i;

my_div uut (
    .clk(clk),
    .reset(reset),
    .div(div),
    .div_signed(div_signed),
    .x(x),
    .y(y),
    .s(s),
    .r(r),
    .complete(complete)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [8*80-1:0] label;
    begin
        $display("%0t %0s reset=%b div=%b signed=%b x=%h y=%h s=%h r=%h complete=%b",
                 $time, label, reset, div, div_signed, x, y, s, r, complete);
    end
endtask

task clean;
    begin
        @(negedge clk);
        reset = 1;
        div = 0;
        repeat (2) @(posedge clk);
        #1;
        observe("synchronous reset; working outputs are unspecified");
        @(negedge clk);
        reset = 0;
    end
endtask

task launch;
    input mode;
    input [31:0] dividend;
    input [31:0] divisor;
    begin
        @(negedge clk);
        div_signed = mode;
        x = dividend;
        y = divisor;
        div = 1;
    end
endtask

task execute;
    input [8*80-1:0] label;
    input mode;
    input [31:0] dividend;
    input [31:0] divisor;
    begin
        launch(mode, dividend, divisor);
        repeat (TOTAL_EDGES-1) @(posedge clk);
        #1;
        observe("one edge before completion");
        @(posedge clk);
        #1;
        observe(label);
        @(negedge clk);
        div = 0;
        @(posedge clk);
        #1;
        observe("completion cleared / request removed");
    end
endtask

task run_case;
    input [8*80-1:0] label;
    input mode;
    input [31:0] dividend;
    input [31:0] divisor;
    begin
        clean;
        execute(label, mode, dividend, divisor);
    end
endtask

task interrupt_case;
    input integer active_edges;
    input use_reset;
    begin
        clean;
        launch(1'b0, 32'hfedcba98, 32'h00000123);
        repeat (active_edges) @(posedge clk);
        #1;
        observe("before interruption");

        @(negedge clk);
        reset = use_reset;
        div = use_reset;
        repeat (2) @(posedge clk);
        #1;
        observe("interrupted: reset asserted or request canceled");

        @(negedge clk);
        reset = 0;
        div = 0;
        @(posedge clk);
        #1;
        observe("idle after interruption");
        execute("fresh operation after interruption", 1'b1,
                -32'd37, 32'd5);
    end
endtask

initial begin
    // Initialize inputs and allow 100 ns for initial reset.
    reset = 1;
    div = 0;
    div_signed = 0;
    x = 0;
    y = 1;
    #100;
    observe("initial reset");
    @(negedge clk);
    reset = 0;
    repeat (3) @(posedge clk);
    #1;
    observe("idle without request");

    // Unsigned arithmetic and bit boundaries.
    run_case("unsigned zero",             0, 32'd0,        32'd7);
    run_case("unsigned smaller dividend", 0, 32'd3,        32'd7);
    run_case("unsigned equal operands",   0, 32'hffffffff, 32'hffffffff);
    run_case("unsigned exact division",   0, 32'd100,      32'd10);
    run_case("unsigned nonexact division",0, 32'd100,      32'd7);
    run_case("unsigned maximum / one",    0, 32'hffffffff, 32'd1);
    run_case("unsigned high bit / one",   0, 32'h80000000, 32'd1);
    run_case("unsigned maximum / high bit",0,32'hffffffff,32'h80000000);
    run_case("unsigned below high divisor",0,32'h7fffffff,32'h80000000);
    run_case("unsigned power of two",     0, 32'h80000000, 32'd2);
    run_case("unsigned mixed quotient",   0, 32'haaaaaaaa, 32'd1);
    run_case("unsigned mixed operands",   0, 32'hdeadbeef, 32'h00012345);

    // All signed sign combinations, with and without a remainder.
    for (i = 0; i < 4; i = i + 1) begin
        run_case("signed nonexact sign combination", 1,
                 i[1] ? -32'd13 : 32'd13,
                 i[0] ? -32'd5 : 32'd5);
        run_case("signed exact sign combination", 1,
                 i[1] ? -32'd15 : 32'd15,
                 i[0] ? -32'd5 : 32'd5);
        #1;
    end

    // Signed zero, extrema, and wraparound.
    run_case("signed zero / negative",    1, 32'd0,        -32'd7);
    run_case("signed small negative",     1, -32'd3,       32'd7);
    run_case("signed maximum / one",      1, 32'h7fffffff, 32'd1);
    run_case("signed minimum / one",      1, 32'h80000000, 32'd1);
    run_case("signed minimum / minus one",1, 32'h80000000, 32'hffffffff);
    run_case("signed minimum / three",    1, 32'h80000000, 32'd3);
    run_case("signed minimum / minimum",  1, 32'h80000000, 32'h80000000);
    run_case("signed maximum / minimum",  1, 32'h7fffffff, 32'h80000000);
    run_case("signed minus one / minimum",1, 32'hffffffff, 32'h80000000);

    // Cancel or reset after initialization, mid-operation, and at the final boundary.
    for (i = 0; i < 2; i = i + 1) begin
        interrupt_case(1,  i[0]);
        interrupt_case(17, i[0]);
        interrupt_case(32, i[0]);
        #1;
    end

    // Keep request asserted through cleanup and automatic restart.
    clean;
    launch(1'b0, 32'd12345, 32'd37);
    repeat (TOTAL_EDGES) @(posedge clk);
    #1;
    observe("held request: first completion");
    @(posedge clk);
    #1;
    observe("held request: cleanup edge");
    @(posedge clk);
    #1;
    observe("held request: second initialization");
    repeat (31) @(posedge clk);
    #1;
    observe("held request: one edge before second completion");
    @(posedge clk);
    #1;
    observe("held request: second completion");
    @(negedge clk);
    div = 0;
    repeat (2) @(posedge clk);
    #1;
    observe("idle after repeated operation");

    $display("===========End=========== s=%h r=%h complete=%b",
             s, r, complete);
    $finish;
end

endmodule

