module testbench;

localparam DATA_WIDTH = 32;
localparam [31:0] TX_ADDR = 32'h10010024;

// Inputs
reg clk;
reg [DATA_WIDTH-1:0] Address;
reg [DATA_WIDTH-1:0] WriteData_in;
reg MemWrite;
reg [DATA_WIDTH-1:0] ID_ReadData;
reg [DATA_WIDTH-1:0] Rx_ReadData;
reg [DATA_WIDTH-1:0] Rx_ready_ReadData;

// Outputs
wire [DATA_WIDTH-1:0] ReadData;
wire [DATA_WIDTH-1:0] ID_Address;
wire [DATA_WIDTH-1:0] WriteData_out;
wire ID_MemWrite;
wire Tx_MemWrite;
wire Tx_data_Memwrite;
wire Clean_rx_Memwrite;

integer reg_index;
integer offset;

MemControl #(.DATA_WIDTH(DATA_WIDTH)) uut (
    .Address(Address),
    .WriteData_in(WriteData_in),
    .MemWrite(MemWrite),
    .ID_ReadData(ID_ReadData),
    .Rx_ReadData(Rx_ReadData),
    .Rx_ready_ReadData(Rx_ready_ReadData),
    .ReadData(ReadData),
    .ID_Address(ID_Address),
    .WriteData_out(WriteData_out),
    .ID_MemWrite(ID_MemWrite),
    .Tx_MemWrite(Tx_MemWrite),
    .Tx_data_Memwrite(Tx_data_Memwrite),
    .Clean_rx_Memwrite(Clean_rx_Memwrite)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    begin
        $display("t=%0t Address=%h MemWrite=%b WriteData_in=%h ID_ReadData=%h Rx_ReadData=%h Rx_ready_ReadData=%h | ReadData=%h ID_Address=%h WriteData_out=%h ID_MemWrite=%b Tx_MemWrite=%b Tx_data_Memwrite=%b Clean_rx_Memwrite=%b",
                 $time, Address, MemWrite, WriteData_in,
                 ID_ReadData, Rx_ReadData, Rx_ready_ReadData,
                 ReadData, ID_Address, WriteData_out,
                 ID_MemWrite, Tx_MemWrite,
                 Tx_data_Memwrite, Clean_rx_Memwrite);
    end
endtask

task exercise_address;
    input [DATA_WIDTH-1:0] test_address;
    integer phase;
    begin
        Address = test_address;
        for (phase = 0; phase < 4; phase = phase + 1) begin
            case (phase)
                0: begin
                    MemWrite = 0;
                    WriteData_in = 32'h00000000;
                    ID_ReadData = 32'hFFFFFFFF;
                    Rx_ReadData = 32'hAAAAAAAA;
                    Rx_ready_ReadData = 32'h55555555;
                end
                1: begin
                    MemWrite = 1;
                    WriteData_in = 32'hFFFFFFFF;
                    ID_ReadData = 32'hAAAAAAAA;
                    Rx_ReadData = 32'h55555555;
                    Rx_ready_ReadData = 32'h00000000;
                end
                2: begin
                    MemWrite = 1;
                    WriteData_in = 32'hAAAAAAAA;
                    ID_ReadData = 32'h55555555;
                    Rx_ReadData = 32'h00000000;
                    Rx_ready_ReadData = 32'hFFFFFFFF;
                end
                3: begin
                    MemWrite = 0;
                    WriteData_in = 32'h55555555;
                    ID_ReadData = 32'h00000000;
                    Rx_ReadData = 32'hFFFFFFFF;
                    Rx_ready_ReadData = 32'hAAAAAAAA;
                end
            endcase
            #1;
            observe;
        end
    end
endtask

initial begin
    Address = 0;
    WriteData_in = 0;
    MemWrite = 0;
    ID_ReadData = 0;
    Rx_ReadData = 0;
    Rx_ready_ReadData = 0;

    // Wait 100 ns for global reset to finish.
    #100;
    observe;

    // Ordinary memory boundaries and nearby aligned addresses.
    exercise_address(32'h00000000);
    exercise_address(32'h80000000);
    exercise_address(32'hFFFFFFFF);
    exercise_address(32'h10010020);
    exercise_address(32'h10010038);

    // Each peripheral and its immediate byte-address neighbors.
    for (reg_index = 0; reg_index < 5; reg_index = reg_index + 1) begin
        #1;
        for (offset = -1; offset <= 1; offset = offset + 1) begin
            #1;
            exercise_address(TX_ADDR + 4 * reg_index + offset);
        end
    end

    // Return to ordinary memory after peripheral accesses.
    exercise_address(32'h00000000);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

// Inputs
reg clk;
reg [7:0] soma, sub, mul;
reg [3:0] selop;

// Outputs
wire [7:0] resul;

integer op;

MUX4x4 uut (
    .soma(soma),
    .sub(sub),
    .mul(mul),
    .selop(selop),
    .resul(resul)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
begin
    $display("t=%0t selop=%b soma=%h sub=%h mul=%h resul=%h",
             $time, selop, soma, sub, mul, resul);
end
endtask

task vary_candidates;
    input [7:0] value;
begin
    soma = value;
    #1;
    observe;
    sub = value;
    #1;
    observe;
    mul = value;
    #1;
    observe;
end
endtask

initial begin
    soma  = 8'h12;
    sub   = 8'h34;
    mul   = 8'h56;
    selop = 4'h0;

    // Allow 100 ns for initialization; no reset port exists.
    #100;

    // All supported and unsupported operation codes.
    for (op = 0; op < 16; op = op + 1) begin
        selop = op;
        #1;
        observe;
    end

    // Independent candidate changes with each supported selector held fixed.
    for (op = 10; op <= 12; op = op + 1) begin
        soma  = 8'h12;
        sub   = 8'h34;
        mul   = 8'h56;
        selop = op;
        #1;
        observe;

        vary_candidates(8'h00);
        vary_candidates(8'hFF);
        vary_candidates(8'hAA);
        vary_candidates(8'h55);
    end

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam DEPTH = 16, WIDTH = 8, PTR_WIDTH = 4;

// Inputs
reg clk;
reg rd_clk;
reg rst_i;
reg wr_en_i;
reg rd_en_i;
reg [WIDTH-1:0] wdata_i;

// Outputs
wire full_o;
wire wr_error_o;
wire [WIDTH-1:0] rdata_o;
wire empty_o;
wire rd_error_o;

integer i, round, mode;
reg [WIDTH-1:0] pattern;

Async_FIFO #(
    .DEPTH(DEPTH), .WIDTH(WIDTH), .PTR_WIDTH(PTR_WIDTH)
) uut (
    .wr_clk_i(clk),
    .rd_clk_i(rd_clk),
    .rst_i(rst_i),
    .wr_en_i(wr_en_i),
    .wdata_i(wdata_i),
    .full_o(full_o),
    .wr_error_o(wr_error_o),
    .rd_en_i(rd_en_i),
    .rdata_o(rdata_o),
    .empty_o(empty_o),
    .rd_error_o(rd_error_o)
);

// Clock rising edges never coincide.
initial clk = 0;
always #5 clk = ~clk;
initial rd_clk = 0;
always #6 rd_clk = ~rd_clk;

task observe;
    input [8*64-1:0] label;
    begin
        $display("%0t %0s full_o=%b wr_error_o=%b rdata_o=%h empty_o=%b rd_error_o=%b",
                 $time, label, full_o, wr_error_o, rdata_o,
                 empty_o, rd_error_o);
    end
endtask

task reset_fifo;
    begin
        @(negedge clk);
        rst_i = 1;
        wr_en_i = 1;
        rd_en_i = 1;
        wdata_i = 8'hA5;
        #0.1;
        observe("reset asserted before write-clock edge");
        repeat (3) @(posedge clk);
        #0.1;
        observe("reset applied with both requests enabled");
        repeat (2) @(posedge rd_clk);
        #0.1;
        observe("read-clock edges while reset held");
        @(negedge clk);
        wr_en_i = 0;
        rd_en_i = 0;
        rst_i = 0;
        repeat (2) @(posedge clk);
        #0.1;
        observe("reset released, idle");
    end
endtask

task idle_settle;
    input [8*64-1:0] label;
    begin
        repeat (2) @(posedge clk);
        repeat (2) @(posedge rd_clk);
        #0.1;
        observe(label);
    end
endtask

task write_word;
    input [WIDTH-1:0] data;
    input [8*64-1:0] label;
    begin
        @(negedge clk);
        wdata_i = data;
        wr_en_i = 1;
        @(posedge clk);
        #0.1;
        observe(label);
        wr_en_i = 0;
    end
endtask

task read_word;
    input [8*64-1:0] label;
    begin
        @(negedge rd_clk);
        rd_en_i = 1;
        @(posedge rd_clk);
        #0.1;
        observe(label);
        rd_en_i = 0;
    end
endtask

initial begin
    rst_i = 1;
    wr_en_i = 0;
    rd_en_i = 0;
    wdata_i = 0;

    // Wait 100 ns for global reset to finish.
    #100;

    // Case 1: reset, empty reads, and error clearing.
    reset_fifo;
    for (i = 0; i < 2; i = i + 1) begin
        read_word("case 1: read request while empty");
    end
    idle_settle("case 1: idle after empty reads");

    // Case 2: single-word transitions and data patterns.
    reset_fifo;
    for (i = 0; i < 4; i = i + 1) begin
        case (i)
            0: pattern = 8'h00;
            1: pattern = 8'hFF;
            2: pattern = 8'hAA;
            3: pattern = 8'h55;
        endcase
        write_word(pattern, "case 2: single-word write");
        idle_settle("case 2: write visible in read domain");
        read_word("case 2: single-word read");
        idle_settle("case 2: idle retains read data");
        read_word("case 2: extra read after single word");
        idle_settle("case 2: read error cleared, data retained");
    end

    // Case 3: capacity, rejection, freed-slot reuse, and repeated wraps.
    reset_fifo;
    for (round = 0; round < 2; round = round + 1) begin
        for (i = 0; i < DEPTH; i = i + 1) begin
            write_word(round * 64 + i, "case 3: fill");
        end
        idle_settle("case 3: full status settled");
        for (i = 0; i < 2; i = i + 1) begin
            write_word(8'hEE, "case 3: write request while full");
        end
        idle_settle("case 3: idle clears write error");
        read_word("case 3: remove one word from full FIFO");
        idle_settle("case 3: read visible in write domain");
        write_word(8'hC0 + round, "case 3: refill freed location");
        idle_settle("case 3: refilled status settled");
        for (i = 0; i < DEPTH; i = i + 1) begin
            read_word("case 3: drain");
        end
        read_word("case 3: read request after drain");
        idle_settle("case 3: empty status and errors settled");
    end

    // Case 4: reset discards partially consumed contents.
    reset_fifo;
    for (i = 0; i < 3; i = i + 1) begin
        write_word(8'h90 + i, "case 4: populate before reset");
    end
    idle_settle("case 4: queued data visible");
    read_word("case 4: consume one word before reset");
    reset_fifo;
    read_word("case 4: read request after reset");
    idle_settle("case 4: idle after reset read");
    write_word(8'h5A, "case 4: new write after reset");
    idle_settle("case 4: new write visible");
    read_word("case 4: read new data after reset");

    // Case 5: concurrent traffic starting empty, half full, and full.
    for (mode = 0; mode < 3; mode = mode + 1) begin
        reset_fifo;
        for (i = 0; i < mode * (DEPTH / 2); i = i + 1) begin
            write_word(8'h20 + i, "case 5: preload");
        end
        idle_settle("case 5: starting occupancy settled");
        for (i = 0; i < 2 * DEPTH; i = i + 1) begin
            @(negedge clk);
            #0.1;
            wr_en_i = 1;
            rd_en_i = 1;
            wdata_i = 8'h80 + i;
            @(posedge clk);
            #0.1;
            observe("case 5: concurrent traffic, write-clock sample");
            @(negedge clk);
            #0.1;
            observe("case 5: concurrent traffic, interval sample");
        end
        wr_en_i = 0;
        rd_en_i = 0;
        idle_settle("case 5: concurrent requests stopped");
        for (i = 0; i < DEPTH + 1; i = i + 1) begin
            read_word("case 5: bounded drain and empty-read requests");
        end
        idle_settle("case 5: final idle");
    end

    $display("===========End===========");
    $finish;
end

endmodule

