`timescale 1ns / 1ps
module testbench;

localparam integer MEM_WORDS    = 1048576;
localparam integer FRAME_CYCLES = 6 * 40000;
localparam integer GROUP_CYCLES = 5 * FRAME_CYCLES;
localparam [19:0] FB_BASE       = 20'hF0000;

// Directed reset timing for the supplied RTL.
// After startup, s_cnt repeats 1,2,3,4,5 rather than six values.
// Six startup clocks leave formats 01/11 in their first DUMMY cycle.
// The second duration ends safely inside the first overlay pass.
localparam integer DUMMY_RESET_CYCLES   = 6;
localparam integer OVERLAY_RESET_CYCLES = 5 * 32768 + 64;

// Inputs
reg clk;
reg reset;
reg [23:0] IM_Q;
reg [12:0] CR_Q;

// Outputs
wire [19:0] IM_A;
wire [23:0] IM_D;
wire IM_WEN;
wire [8:0] CR_A;

reg [23:0] memory [0:MEM_WORDS-1];
reg [23:0] initial_time;
reg [23:0] directed_flags;

integer i;
integer test_id;
integer case_id;
integer directed_cycles;

DPA uut (
    .clk(clk),
    .reset(reset),
    .IM_A(IM_A),
    .IM_Q(IM_Q),
    .IM_D(IM_D),
    .IM_WEN(IM_WEN),
    .CR_A(CR_A),
    .CR_Q(CR_Q)
);

initial clk = 0;
always #5 clk = ~clk;

function [23:0] source_word;
    input [19:0] address;
    reg [7:0] blue;
    begin
        blue = address[7:0] + 8'd1;
        case (address[6:4])
            0: source_word = 24'h000000;
            1: source_word = 24'hFFFFFF;
            2: source_word = 24'hFF0000;
            3: source_word = 24'h00FF00;
            4: source_word = 24'h0000FF;
            default:
                source_word = {
                    address[7:0],
                    address[15:8] ^ address[7:0],
                    blue
                };
        endcase
    end
endfunction

function [12:0] character_row;
    input [8:0] address;
    begin
        case (address % 24)
            0: character_row = 13'h0000;
            1: character_row = 13'h1FFF;
            2: character_row = 13'h1000;
            3: character_row = 13'h0001;
            4: character_row = 13'h0AAA;
            5: character_row = 13'h1555;
            default:
                character_row = {
                    address[0], address[7:0], address[3:0]
                };
        endcase
    end
endfunction

task observe;
    input [95:0] label;
    begin
        $display("case=%0d %0s t=%0t reset=%b IM_A=%05h IM_D=%06h IM_WEN=%b CR_A=%03h",
                 case_id, label, $time, reset,
                 IM_A, IM_D, IM_WEN, CR_A);
    end
endtask

task start_case;
    input integer number;
    input [23:0] time_word;
    input [2:0] photo_count;
    input [23:0] first_flags;
    begin
        case_id = number;
        #2;
        reset = 1;
        IM_Q = 0;
        CR_Q = 0;
        #1;
        observe("reset");

        memory[0]  = 0;
        memory[1]  = time_word;
        memory[2]  = {4'hA, FB_BASE};
        memory[3]  = {21'h155555, photo_count};
        memory[4]  = 24'hA01000;
        memory[5]  = first_flags;
        memory[6]  = 24'hB08000;
        memory[7]  = 24'h000300;
        memory[8]  = 24'hC20000;
        memory[9]  = 24'h000200;
        memory[10] = 24'hD70000;
        memory[11] = 24'h000080;

        repeat (2) @(posedge clk);
        @(negedge clk);
        reset = 0;
        IM_Q = memory[0];
        CR_Q = character_row(9'd0);
    end
endtask

// Service memory on falling edges; sample registered outputs after rising edges.
task run_cycles;
    input integer cycles;
    integer n;
    reg last_wen;
    begin
        last_wen = 1;
        for (n = 0; n < cycles; n = n + 1) begin
            @(posedge clk);
            #1;
            if (!IM_WEN || !last_wen ||
                (n < 32) || ((n % 1024) == 0))
                observe("sample");
            last_wen = IM_WEN;

            @(negedge clk);
            if (IM_WEN)
                IM_Q = memory[IM_A];
            else
                memory[IM_A] = IM_D;
            CR_Q = character_row(CR_A);
        end
        observe("case_end");
    end
endtask

initial begin
    reset = 1;
    IM_Q = 0;
    CR_Q = 0;
    case_id = -1;
    initial_time = 0;
    directed_flags = 0;
    directed_cycles = 0;

    // Wait 100 ns for global reset to finish.
    #100;
    observe("power_reset");

    // Initialize the complete external memory while reset remains asserted.
    for (i = 0; i < MEM_WORDS; i = i + 1) begin
        memory[i] = source_word(i);
        #1;
    end

    // Case 0: unsupported descriptor flags.
    start_case(0, 24'h000000, 3'd1, 24'h000000);
    memory[7] = 0;
    memory[9] = 0;
    memory[11] = 0;
    run_cycles(12);

    // Case 1: recover by reset, then interrupt an active image transfer.
    start_case(1, 24'h010203, 3'd1, 24'h000080);
    run_cycles(64);

    // Case 2: all formats, priority flags, phase changes and four-photo wrap.
    start_case(2, {8'd12, 8'd34, 8'd56}, 3'd4, 24'h000380);
    run_cycles((2 * 4 + 1) * GROUP_CYCLES + FRAME_CYCLES);

    // Cases 3-9: independent time boundaries and decimal glyph ranges.
    for (test_id = 3; test_id <= 9; test_id = test_id + 1) begin
        #1;
        case (test_id)
            3: initial_time = {8'd0,  8'd9,  8'd9};
            4: initial_time = {8'd9,  8'd59, 8'd59};
            5: initial_time = {8'd23, 8'd59, 8'd59};
            6: initial_time = {8'd19, 8'd19, 8'd59};
            7: initial_time = {8'd20, 8'd29, 8'd29};
            8: initial_time = {8'd21, 8'd39, 8'd39};
            9: initial_time = {8'd22, 8'd49, 8'd49};
        endcase
        start_case(test_id, initial_time, 3'd1, 24'h000100);
        if (test_id < 7)
            run_cycles(2 * GROUP_CYCLES + FRAME_CYCLES);
        else
            run_cycles(FRAME_CYCLES);
    end

    // Case 10: reset saved overlay information and restart format 11.
    start_case(10, 24'h000000, 3'd1, 24'h000200);
    run_cycles(64);

    // Additional coverage-directed cases reuse the existing stimulus tasks.
    //
    // Each run_cycles call returns on a falling edge. The next iteration's
    // #1 plus start_case's #2 asserts reset before the next rising edge.
    // Thus a one-clock DUMMY state is interrupted without output polling.
    //
    // Case 12 resets case 11's format-01 DUMMY.
    // Case 13 resets case 12's format-11 DUMMY.
    // Case 14 resets case 13's format-10 overlay.
    // Case 15 resets case 14's format-11 overlay.
    //
    // Cases 15 and 16 deliberately use out-of-spec time headers to exercise
    // implemented decimal fallback paths. Case 17 restores valid inputs.
    for (test_id = 11; test_id <= 17; test_id = test_id + 1) begin
        #1;

        initial_time = {8'd12, 8'd34, 8'd56};
        directed_flags = 24'h000100;
        directed_cycles = 64;

        case (test_id)
            11: begin
                directed_flags = 24'h000080;
                directed_cycles = DUMMY_RESET_CYCLES;
            end

            12: begin
                directed_flags = 24'h000200;
                directed_cycles = DUMMY_RESET_CYCLES;
            end

            13: begin
                directed_flags = 24'h000100;
                directed_cycles = OVERLAY_RESET_CYCLES;
            end

            14: begin
                directed_flags = 24'h000200;
                directed_cycles = OVERLAY_RESET_CYCLES;
            end

            15: begin
                // Binary values, not BCD: first uncovered fallback values.
                initial_time = {8'd30, 8'd60, 8'd60};
                directed_flags = 24'h000080;
                directed_cycles = FRAME_CYCLES;
            end

            16: begin
                // Exercise the full eight-bit malformed-header range.
                initial_time = {8'd255, 8'd255, 8'd255};
                directed_flags = 24'h000100;
                directed_cycles = 64;
            end

            17: begin
                // Valid recovery following malformed initialization data.
                initial_time = {8'd1, 8'd2, 8'd3};
                directed_flags = 24'h000100;
                directed_cycles = 64;
            end
        endcase

        start_case(test_id, initial_time, 3'd1, directed_flags);
        run_cycles(directed_cycles);
    end

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

// Inputs
reg clk;
reg line1;
reg line2;
reg reset;

// Outputs
wire outp;
wire overflw;

integer state_id;
integer pattern;
integer test_kind;

b01 uut (
    .clock   (clk),
    .line1   (line1),
    .line2   (line2),
    .reset   (reset),
    .outp    (outp),
    .overflw (overflw)
);

initial clk = 0;
always #5 clk = ~clk;

// kind: 0 = initialization, 1 = transitions, 2 = reset.
// stage: 0 = reset, 1 = approach, 2 = exercise, 3 = follow-up.
task cycle;
    input rst;
    input [1:0] lines;
    input integer stage;
    begin
        @(negedge clk);
        reset = rst;
        {line1, line2} = lines;
        #1;
        $display("t=%0t kind=%0d state=%0d pattern=%0d stage=%0d pre-edge reset=%b lines=%b%b outp=%b overflw=%b",
                 $time, test_kind, state_id, pattern, stage,
                 reset, line1, line2, outp, overflw);
        @(posedge clk);
        #1;
        $display("t=%0t kind=%0d state=%0d pattern=%0d stage=%0d post-edge reset=%b lines=%b%b outp=%b overflw=%b",
                 $time, test_kind, state_id, pattern, stage,
                 reset, line1, line2, outp, overflw);
    end
endtask

// Fixed stimulus recipes; IDs: a=0 b=1 c=2 e=3 f=4 g=5 wf0=6 wf1=7.
task approach;
    input integer target;
    reg [7:0] route;
    integer length;
    integer j;
    begin
        route = 8'b0;
        length = 0;
        case (target)
            0: begin route = 8'b0;                         length = 0; end
            1: begin route = {2'b00};                      length = 1; end
            2: begin route = {2'b00, 2'b00};               length = 2; end
            3: begin route = {2'b00, 2'b00, 2'b00, 2'b11}; length = 4; end
            4: begin route = {2'b11};                      length = 1; end
            5: begin route = {2'b11, 2'b01};               length = 2; end
            6: begin route = {2'b00, 2'b00, 2'b00};        length = 3; end
            7: begin route = {2'b00, 2'b00, 2'b11};        length = 3; end
        endcase
        for (j = 0; j < length; j = j + 1) begin
            #1;
            cycle(1'b0, route[2*(length-j)-1 -: 2], 1);
        end
    end
endtask

initial begin
    line1 = 0;
    line2 = 0;
    reset = 1;
    state_id = 0;
    pattern = 0;
    test_kind = 0;

    // Wait 100 ns for global reset to finish.
    #100;
    $display("t=%0t initialization reset=%b lines=%b%b outp=%b overflw=%b",
             $time, reset, line1, line2, outp, overflw);

    // All state/input combinations, independently initialized.
    test_kind = 1;
    for (state_id = 0; state_id < 8; state_id = state_id + 1) begin
        #1;
        for (pattern = 0; pattern < 4; pattern = pattern + 1) begin
            #1;
            cycle(1'b1, 2'b00, 0);
            approach(state_id);
            cycle(1'b0, pattern[1:0], 2);
            cycle(1'b0, 2'b00, 3);
            cycle(1'b0, 2'b00, 3);
        end
    end

    // Reset from every state; hold reset while changing inputs.
    test_kind = 2;
    pattern = 0;
    for (state_id = 0; state_id < 8; state_id = state_id + 1) begin
        #1;
        cycle(1'b1, 2'b00, 0);
        approach(state_id);
        cycle(1'b1, 2'b11, 2);
        cycle(1'b1, 2'b01, 2);
        cycle(1'b0, 2'b11, 3);
        cycle(1'b0, 2'b00, 3);
    end

    // Assert reset immediately after a cycle that activates overflow.
    state_id = 3;
    cycle(1'b1, 2'b00, 0);
    approach(state_id);
    cycle(1'b0, 2'b11, 2);
    cycle(1'b1, 2'b11, 2);
    cycle(1'b0, 2'b00, 3);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam ADDR_WIDTH = 12;
localparam DATA_WIDTH = 32;

// Inputs
reg clk;
reg axis_rst_n;
reg awvalid, wvalid, arvalid, rready;
reg [ADDR_WIDTH-1:0] awaddr, araddr;
reg [DATA_WIDTH-1:0] wdata;
reg ss_tvalid, ss_tlast, sm_tready;
reg [DATA_WIDTH-1:0] ss_tdata;
reg signed [DATA_WIDTH-1:0] tap_Do;
reg [DATA_WIDTH-1:0] data_Do;

// Outputs
wire awready, wready, arready, rvalid;
wire [DATA_WIDTH-1:0] rdata;
wire ss_tready, sm_tvalid, sm_tlast;
wire [DATA_WIDTH-1:0] sm_tdata;
wire [3:0] tap_WE, data_WE;
wire tap_EN, data_EN;
wire [DATA_WIDTH-1:0] tap_Di, data_Di;
wire [ADDR_WIDTH-1:0] tap_A, data_A;

integer test_id, i;

fir #(
    .pADDR_WIDTH(ADDR_WIDTH),
    .pDATA_WIDTH(DATA_WIDTH),
    .Tape_Num(11)
) uut (
    .awready(awready), .wready(wready),
    .awvalid(awvalid), .awaddr(awaddr),
    .wvalid(wvalid), .wdata(wdata),
    .arready(arready), .rready(rready),
    .arvalid(arvalid), .araddr(araddr),
    .rvalid(rvalid), .rdata(rdata),
    .ss_tvalid(ss_tvalid), .ss_tdata(ss_tdata),
    .ss_tlast(ss_tlast), .ss_tready(ss_tready),
    .sm_tready(sm_tready), .sm_tvalid(sm_tvalid),
    .sm_tdata(sm_tdata), .sm_tlast(sm_tlast),
    .tap_WE(tap_WE), .tap_EN(tap_EN),
    .tap_Di(tap_Di), .tap_A(tap_A), .tap_Do(tap_Do),
    .data_WE(data_WE), .data_EN(data_EN),
    .data_Di(data_Di), .data_A(data_A), .data_Do(data_Do),
    .axis_clk(clk), .axis_rst_n(axis_rst_n)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
begin
    $display("case=%0d t=%0t awready=%b wready=%b arready=%b rvalid=%b rdata=%h ss_tready=%b sm_tvalid=%b sm_tdata=%h sm_tlast=%b tap_WE=%h tap_EN=%b tap_Di=%h tap_A=%h data_WE=%h data_EN=%b data_Di=%h data_A=%h",
             test_id, $time, awready, wready, arready, rvalid,
             rdata, ss_tready, sm_tvalid, sm_tdata, sm_tlast,
             tap_WE, tap_EN, tap_Di, tap_A,
             data_WE, data_EN, data_Di, data_A);
end
endtask

// Sample every clock so single-cycle output opportunities remain visible.
task tick;
    input integer cycles;
    integer n;
begin
    for (n = 0; n < cycles; n = n + 1) begin
        @(posedge clk);
        #1;
        observe;
    end
end
endtask

task clear_inputs;
begin
    awvalid = 0; awaddr = 0;
    wvalid = 0; wdata = 0;
    arvalid = 0; araddr = 0; rready = 0;
    ss_tvalid = 0; ss_tdata = 0; ss_tlast = 0;
    sm_tready = 0;
    tap_Do = 0; data_Do = 0;
end
endtask

task reset_dut;
begin
    @(negedge clk);
    #2;
    axis_rst_n = 0;
    #1;
    observe;
    clear_inputs;
    tick(2);
    @(negedge clk);
    axis_rst_n = 1;
    #1;
    observe;
end
endtask

task write_reg;
    input [ADDR_WIDTH-1:0] address;
    input [DATA_WIDTH-1:0] value;
    input integer hold_cycles;
begin
    @(negedge clk);
    awaddr = address;
    awvalid = 1;
    #1;
    observe;
    tick(1);
    @(negedge clk);
    awvalid = 0;
    wdata = value;
    tick(hold_cycles);
    @(negedge clk);
    wvalid = 1;
    #1;
    observe;
    tick(1);
    @(negedge clk);
    wvalid = 0;
end
endtask

// Shared read stimulus:
// ready_pulses=0 preserves the original read_reg timing.
// Each additional pulse exercises ready withdrawal before completion.
task read_reg_pattern;
    input [ADDR_WIDTH-1:0] address;
    input integer hold_cycles;
    input integer ready_pulses;
    integer pulse_index;
begin
    @(negedge clk);
    araddr = address;
    arvalid = 1;
    rready = 0;
    #1;
    observe;
    tick(1);

    @(negedge clk);
    arvalid = 0;
    tick(hold_cycles);

    for (pulse_index = 0;
         pulse_index < ready_pulses;
         pulse_index = pulse_index + 1) begin
        @(negedge clk);
        rready = 1;
        #1;
        observe;

        // One ready clock registers rvalid without completing a
        // transaction whose preceding rvalid was low.
        tick(1);

        @(negedge clk);
        rready = 0;

        // Observe the stable half-cycle with ready low and the
        // previously registered valid still high.
        #1;
        observe;

        // This rising edge clears registered rvalid while the read
        // transaction stays pending.
        tick(1);
    end

    // Complete using the original fixed two-clock ready sequence.
    @(negedge clk);
    rready = 1;
    tick(2);
    @(negedge clk);
    rready = 0;
    tick(1);
end
endtask

// Preserve the original task interface and all existing call sites.
task read_reg;
    input [ADDR_WIDTH-1:0] address;
    input integer hold_cycles;
begin
    read_reg_pattern(address, hold_cycles, 0);
end
endtask

function [ADDR_WIDTH-1:0] test_address;
    input integer index;
begin
    case (index)
        0: test_address = 12'h001;
        1: test_address = 12'h020;
        2: test_address = 12'h048;
        3: test_address = 12'h07f;
        4: test_address = 12'h080;
        5: test_address = 12'h0a0;
        default: test_address = 12'hfff;
    endcase
end
endfunction

function [DATA_WIDTH-1:0] operand;
    input integer index;
begin
    case (index % 6)
        0: operand = 32'h00000000;
        1: operand = 32'h00000001;
        2: operand = 32'hffffffff;
        3: operand = 32'h7fffffff;
        4: operand = 32'h80000000;
        default: operand = 32'h00000002;
    endcase
end
endfunction

task run_frame;
    input integer samples;
    input integer mode;
    input integer stall_final;
    integer s;
begin
    sm_tready = 1;
    write_reg(12'h000, 32'hfffffff9, 0);
    tick(1);
    for (s = 0; s < samples; s = s + 1) begin
        @(negedge clk);
        ss_tvalid = 1;
        sm_tready = 1;
        case (mode)
            0: begin
                ss_tvalid = 0;
                ss_tdata = 0;
                tap_Do = 0;
                data_Do = 0;
            end
            1: begin
                ss_tvalid = (s % 3 != 1);
                ss_tdata = operand(s);
                tap_Do = operand(s + 1);
                data_Do = operand(s + 2);
                sm_tready = (s % 2 == 0);
            end
            2: begin
                ss_tdata = 32'h7fffffff;
                tap_Do = 32'h00000001;
                data_Do = 32'h7fffffff;
            end
            default: begin
                ss_tdata = operand(s);
                tap_Do = 32'h00000002;
                data_Do = 32'h7fffffff;
            end
        endcase
        ss_tlast = (s == samples - 1);
        if (s == samples - 1)
            sm_tready = !stall_final;
        #1;
        observe;
        tick(1);
        @(negedge clk);
        ss_tdata = ~ss_tdata;
        ss_tlast = 1;
        tick(11);
    end
    tick(2);
end
endtask

initial begin
    test_id = 0;
    axis_rst_n = 0;
    clear_inputs;

    // Wait 100 ns for global reset to finish.
    #100;
    observe;

    // 1: Idle handshakes and write data without an address.
    test_id = 1;
    reset_dut;
    @(negedge clk);
    rready = 1;
    wvalid = 1;
    wdata = 32'h12345678;
    tick(2);
    @(negedge clk);
    rready = 0;
    wvalid = 0;
    tick(2);
    read_reg(12'h000, 2);

    // 10..17: Every command encoding and status-read behavior.
    for (i = 0; i < 8; i = i + 1) begin
        #1;
        test_id = 10 + i;
        reset_dut;
        ss_tdata = 7;
        tap_Do = 2;
        data_Do = 3;
        write_reg(12'h000, 32'hffffff00 | i, 2);
        read_reg(12'h000, 2);
        read_reg(12'h000, 0);
    end

    // 20..26: Address boundaries, truncation, and delayed data.
    for (i = 0; i < 7; i = i + 1) begin
        #1;
        test_id = 20 + i;
        reset_dut;
        tap_Do = operand(i);
        write_reg(test_address(i), operand(i + 1), 2);
        read_reg(test_address(i), 2);
    end

    // 30: Simultaneous address capture and requests while busy.
    test_id = 30;
    reset_dut;
    @(negedge clk);
    awaddr = 12'h048; awvalid = 1;
    araddr = 12'h024; arvalid = 1;
    tap_Do = 32'h89abcdef;
    #1;
    observe;
    tick(1);
    @(negedge clk);
    awaddr = 12'h080;
    araddr = 12'h000;
    tick(1);
    @(negedge clk);
    awvalid = 0; arvalid = 0;
    wvalid = 1; wdata = 32'h13579bdf;
    #1;
    observe;
    tick(1);
    @(negedge clk);
    wvalid = 0;
    tap_Do = 32'h76543210;
    tick(2);
    @(negedge clk);
    rready = 1;
    tick(2);
    @(negedge clk);
    rready = 0;
    tick(1);

    // 40..43: Streaming, signed arithmetic, saturation, and wrap.
    for (i = 0; i < 4; i = i + 1) begin
        #1;
        test_id = 40 + i;
        reset_dut;
        case (i)
            0: run_frame(1, 0, 0);
            1: run_frame(13, 1, 0);
            2: run_frame(12, 2, 0);
            3: run_frame(12, 3, 0);
        endcase
        read_reg(12'h000, 1);
        read_reg(12'h000, 0);
    end

    // 44: Restart after completion without resetting.
    test_id = 44;
    run_frame(2, 1, 0);
    read_reg(12'h000, 0);
    run_frame(1, 2, 0);
    read_reg(12'h000, 0);

    // 45: Miss final opportunity, raise ready late, then recover.
    test_id = 45;
    reset_dut;
    run_frame(2, 1, 1);
    tick(3);
    @(negedge clk);
    sm_tready = 1;
    tick(4);
    read_reg(12'h000, 0);
    reset_dut;
    run_frame(1, 2, 0);
    read_reg(12'h000, 0);

    // 50: Coefficient read/write concurrent with calculation.
    test_id = 50;
    reset_dut;
    ss_tvalid = 1; ss_tdata = 5; ss_tlast = 1;
    tap_Do = 3; data_Do = 7; sm_tready = 1;
    write_reg(12'h000, 1, 0);
    tick(1);
    @(negedge clk);
    awaddr = 12'h020; awvalid = 1;
    araddr = 12'h024; arvalid = 1;
    tick(1);
    @(negedge clk);
    awvalid = 0; arvalid = 0;
    wvalid = 1; wdata = 32'hdeadbeef; rready = 1;
    #1;
    observe;
    tick(1);
    @(negedge clk);
    wvalid = 0;
    tick(12);
    read_reg(12'h000, 0);

    // 51: Command update coincident with acquisition.
    test_id = 51;
    reset_dut;
    ss_tvalid = 1; ss_tdata = 5; ss_tlast = 1;
    tap_Do = 3; data_Do = 7; sm_tready = 1;
    write_reg(12'h000, 1, 0);
    awaddr = 0; awvalid = 1;
    tick(1);
    @(negedge clk);
    awvalid = 0; wvalid = 1; wdata = 7;
    tick(1);
    @(negedge clk);
    wvalid = 0;
    read_reg(12'h000, 0);
    tick(12);
    read_reg(12'h000, 0);

    // 52: Command update coincident with final handshake.
    test_id = 52;
    reset_dut;
    ss_tvalid = 1; ss_tdata = 5; ss_tlast = 1;
    tap_Do = 3; data_Do = 7; sm_tready = 1;
    write_reg(12'h000, 1, 0);
    tick(1);
    tick(10);
    @(negedge clk);
    awaddr = 0; awvalid = 1;
    tick(1);
    @(negedge clk);
    awvalid = 0;
    tick(1);
    @(negedge clk);
    wvalid = 1; wdata = 2;
    #1;
    observe;
    tick(1);
    @(negedge clk);
    wvalid = 0;
    read_reg(12'h000, 0);

    // 60..61: Asynchronous reset with processing and channels active.
    for (i = 0; i < 2; i = i + 1) begin
        #1;
        test_id = 60 + i;
        reset_dut;
        ss_tvalid = 1; ss_tdata = 9;
        tap_Do = 2; data_Do = 4; sm_tready = 1;
        write_reg(12'h000, 1, 0);
        awaddr = i ? 12'h024 : 12'h000;
        araddr = i ? 12'h028 : 12'h000;
        awvalid = 1; arvalid = 1;
        tick(1);
        tick(4 * i);
        reset_dut;
        read_reg(12'h000, 0);
        run_frame(1, 2, 0);
    end

    // 70..71: Directed coverage of read-ready withdrawal.
    //
    // Case 70: Status read with one ready pulse targets lines 101
    //          and 156 while the processing engine remains idle.
    // Case 71: Coefficient read with two ready pulses targets
    //          line 154 and repeats the pending-read sequence.
    //
    // Non-start command values keep processing idle. All stimulus
    // and sampling use top-level ports and fixed clock counts.
    for (i = 0; i < 2; i = i + 1) begin
        #1;
        test_id = 70 + i;
        reset_dut;

        tap_Do = operand(i + 3);
        data_Do = operand(i + 4);

        write_reg(12'h000, 32'hffffff06 | i, 1);

        read_reg_pattern(
            i ? 12'h024 : 12'h000,
            i + 1,
            i + 1
        );

        // Observe a subsequent ordinary status read and its clear.
        read_reg(12'h000, 0);
        read_reg(12'h000, 1);
    end

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

reg clk;
reg i_rst;
reg i_en;

wire o_sel_wing;
wire [3:0] o_a0;
wire [3:0] o_a1;

integer k;

ADDRgen uut (
    .i_clk      (clk),
    .i_rst      (i_rst),
    .i_en       (i_en),
    .o_sel_wing (o_sel_wing),
    .o_a0       (o_a0),
    .o_a1       (o_a1)
);

initial clk = 0;
always #5 clk = ~clk;

task reset_dut;
begin
    i_rst = 1'b1;
    i_en  = 1'b0;
    repeat (2) @(posedge clk);
    #1 $display("RESET      sel=%b a0=%h a1=%h",
                o_sel_wing, o_a0, o_a1);
    i_rst = 1'b0;
end
endtask

initial begin
    i_rst = 1'b0;
    i_en  = 1'b0;

    // Test Case 1: reset and idle behavior
    reset_dut();
    repeat (2) @(posedge clk);
    #1 $display("IDLE       sel=%b a0=%h a1=%h",
                o_sel_wing, o_a0, o_a1);

    // Test Case 2: one request, generation cycle, and recovery cycle
    i_en = 1'b1;
    @(posedge clk);
    #1 $display("ACCEPT     sel=%b a0=%h a1=%h",
                o_sel_wing, o_a0, o_a1);

    i_en = 1'b0;
    @(posedge clk);
    #1 $display("GENERATE   sel=%b a0=%h a1=%h",
                o_sel_wing, o_a0, o_a1);

    @(posedge clk);
    #1 $display("RECOVERY   sel=%b a0=%h a1=%h",
                o_sel_wing, o_a0, o_a1);

    // Test Case 3: reset while the controller is in s_1.
    // The first clock accepts the request and enters s_1.
    // Reset is then sampled from s_1, covering the s_1 -> s_0 transition.
    i_en = 1'b1;
    @(posedge clk);
    #1;
    i_en  = 1'b0;
    i_rst = 1'b1;
    @(posedge clk);
    #1 $display("RESET_S1   sel=%b a0=%h a1=%h",
                o_sel_wing, o_a0, o_a1);

    i_rst = 1'b0;
    @(posedge clk);
    #1 $display("IDLE_S1RST sel=%b a0=%h a1=%h",
                o_sel_wing, o_a0, o_a1);

    // Test Case 4: held enable, complete 80-pair sequence plus repeat
    reset_dut();
    i_en = 1'b1;
    @(posedge clk);
    #1 $display("HELD_START sel=%b a0=%h a1=%h",
                o_sel_wing, o_a0, o_a1);

    for (k = 0; k < 81; k = k + 1) begin
        @(posedge clk);
        #1 $display("PAIR_%0d    sel=%b a0=%h a1=%h",
                    k, o_sel_wing, o_a0, o_a1);

        @(posedge clk);
        #1 $display("REC_%0d     sel=%b a0=%h a1=%h",
                    k, o_sel_wing, o_a0, o_a1);

        if (k < 80)
            @(posedge clk);
    end

    i_en = 1'b0;

    // Test Case 5: reset after activity
    reset_dut();
    repeat (1) @(posedge clk);
    #1 $display("POST_RESET sel=%b a0=%h a1=%h",
                o_sel_wing, o_a0, o_a1);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

// Inputs
reg clk;
reg [31:0] Inst;

// Outputs
wire [4:0] ALUSel_out;

integer op, funct, variant, fill;

ALU_decoder uut (
    .Inst(Inst),
    .ALUSel_out(ALUSel_out)
);

initial clk = 0;
always #5 clk = ~clk;

initial begin
    Inst = 32'b0;

    // Wait 100 ns for global initialization.
    #100;
    $display("Initial: Inst=%08h ALUSel_out=%0d",
             Inst, ALUSel_out);

    // Test Case 1: Arithmetic fields and ignored instruction bits.
    // Preserve all original binary combinations, then supplement:
    //   funct 8/9   -> XXX/ZZZ for missing function-case paths.
    //   variant 2/3 -> X/Z for missing bit-30-case paths.
    //
    // For unmatched nested cases, the golden RTL retains its previous
    // output. Observe this behavior without computing expected values.
    for (op = 0; op < 2; op = op + 1) begin
        for (funct = 0; funct < 10; funct = funct + 1) begin
            for (variant = 0; variant < 4; variant = variant + 1) begin
                for (fill = 0; fill < 2; fill = fill + 1) begin
                    Inst = {32{fill[0]}};
                    Inst[6:0] = op[0] ? 7'h33 : 7'h13;

                    case (funct)
                        8:       Inst[14:12] = 3'bxxx;
                        9:       Inst[14:12] = 3'bzzz;
                        default: Inst[14:12] = funct[2:0];
                    endcase

                    case (variant)
                        0: Inst[30] = 1'b0;
                        1: Inst[30] = 1'b1;
                        2: Inst[30] = 1'bx;
                        3: Inst[30] = 1'bz;
                    endcase

                    #1;
                    $display(
                        "Arithmetic: Inst=%08h opcode=%07b funct=%03b bit30=%b ALUSel_out=%0d",
                        Inst, Inst[6:0], Inst[14:12],
                        Inst[30], ALUSel_out
                    );
                end
            end
        end
    end

    // Test Case 2: All opcodes with remaining bits at both extremes.
    // Also restores fully binary inputs following the X/Z tests.
    for (op = 0; op < 128; op = op + 1) begin
        for (fill = 0; fill < 2; fill = fill + 1) begin
            Inst = {32{fill[0]}};
            Inst[6:0] = op[6:0];
            #1;
            $display("Opcode sweep: Inst=%08h ALUSel_out=%0d",
                     Inst, ALUSel_out);
        end
    end

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

// Inputs
reg clk;
reg rst_i;
reg rx_i;

// Outputs
wire done_default, locked_default;
wire done_override, locked_override;
wire [7:0] data_default, data_override;
wire [28:0] period_default, period_override;

integer test_id;
integer scenario, bit_clocks, cut, j;

uart_rx uut_default (
    .clk_i(clk),
    .rst_i(rst_i),
    .rx_i(rx_i),
    .rx_done_tick_o(done_default),
    .dout_bo(data_default),
    .locked_o(locked_default),
    .bitperiod_o(period_default)
);

uart_rx #(.RTX_EXTERNAL_OVERRIDE("YES")) uut_override (
    .clk_i(clk),
    .rst_i(rst_i),
    .rx_i(rx_i),
    .rx_done_tick_o(done_override),
    .dout_bo(data_override),
    .locked_o(locked_override),
    .bitperiod_o(period_override)
);

// Clock toggle generate
initial clk = 0;
always #5 clk = ~clk;

task observe;
begin
    $display("t=%0t case=%0d rst=%b rx=%b default(done=%b dout=%02h locked=%b period=%0d) override(done=%b dout=%02h locked=%b period=%0d)",
             $time, test_id, rst_i, rx_i,
             done_default, data_default, locked_default, period_default,
             done_override, data_override, locked_override, period_override);
end
endtask

task sample_cycles;
    input integer count;
    integer k;
begin
    for (k = 0; k < count; k = k + 1) begin
        @(posedge clk);
        #1;
        observe;
    end
end
endtask

task hold_line;
    input level;
    input integer count;
begin
    @(negedge clk);
    rx_i = level;
    sample_cycles(count);
end
endtask

task reset_dut;
    input reset_rx;
begin
    @(negedge clk);
    rst_i = 1'b1;
    rx_i = reset_rx;
    #1;
    observe;
    sample_cycles(2);
    @(negedge clk);
    rst_i = 1'b0;
    rx_i = 1'b1;
    sample_cycles(3);
end
endtask

task train;
    input integer period;
    input integer extra_low;
    integer b;
    reg [7:0] pattern;
begin
    pattern = 8'h55;
    hold_line(1'b1, 3);
    hold_line(1'b0, period);
    for (b = 0; b < 7; b = b + 1) begin
        #1;
        hold_line(pattern[b], period);
    end
    hold_line(1'b0, period + extra_low);
    hold_line(1'b1, 2 * period + 4);
end
endtask

task send_byte;
    input [7:0] value;
    input integer period;
    integer b;
begin
    hold_line(1'b0, period);
    for (b = 0; b < 8; b = b + 1) begin
        #1;
        hold_line(value[b], period);
    end
    hold_line(1'b1, period);
end
endtask

initial begin
    // Initialize inputs; wait 100 ns for global reset to finish.
    rst_i = 1'b1;
    rx_i = 1'b1;
    test_id = 0;
    #100;
    sample_cycles(1);
    reset_dut(1'b1);

    // Reset each incomplete training prefix, including stop-high wait.
    for (cut = 0; cut < 10; cut = cut + 1) begin
        #1;
        test_id = 10 + cut;
        reset_dut(1'b1);
        hold_line(1'b1, 8);
        for (j = 0; j < cut; j = j + 1) begin
            #1;
            hold_line(j % 2, 8);
        end
        reset_dut(1'b0);
    end

    // Smallest training intervals and their subsequent low/high response.
    for (bit_clocks = 1; bit_clocks <= 2; bit_clocks = bit_clocks + 1) begin
        #1;
        test_id = 30 + bit_clocks;
        reset_dut(1'b1);
        train(bit_clocks, 0);
        hold_line(1'b0, 24);
        hold_line(1'b1, 12);
    end

    // Even/odd training intervals, data patterns, and stop-wait recovery.
    for (scenario = 0; scenario < 2; scenario = scenario + 1) begin
        #1;
        test_id = 40 + scenario;
        bit_clocks = 32 + scenario;
        reset_dut(1'b1);
        train(bit_clocks, 0);
        send_byte(8'h00, bit_clocks);
        send_byte(8'hFF, bit_clocks);
        send_byte(8'h55, bit_clocks);
        send_byte(8'hAA, bit_clocks);
        send_byte(8'h81, bit_clocks);
        send_byte(8'h96, bit_clocks);
        hold_line(1'b1, 3 * bit_clocks);

        // Zero data followed by an extended low stop interval.
        hold_line(1'b0, 12 * bit_clocks);
        hold_line(1'b1, bit_clocks);
        send_byte(8'h3C, bit_clocks);
        hold_line(1'b1, 2 * bit_clocks);
    end

    // Extended training low interval; reset and acquire a different rate.
    test_id = 50;
    reset_dut(1'b1);
    train(32, 5);
    send_byte(8'hA6, 32);
    hold_line(1'b1, 64);
    reset_dut(1'b0);
    train(48, 0);
    send_byte(8'h69, 48);
    hold_line(1'b1, 96);

    // Reset locked idle, start delay, partial data, and low stop wait.
    for (cut = 0; cut < 4; cut = cut + 1) begin
        #1;
        test_id = 60 + cut;
        reset_dut(1'b1);
        train(32, 0);
        case (cut)
            0: hold_line(1'b1, 32);
            1: hold_line(1'b0, 2);
            2: begin
                hold_line(1'b0, 32);
                hold_line(1'b1, 3 * 32);
            end
            3: hold_line(1'b0, 12 * 32);
        endcase
        reset_dut(1'b0);
        train(32, 0);
        send_byte(8'hC3, 32);
        hold_line(1'b1, 64);
    end

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

// Inputs
reg clk;
reg Controle;
reg [15:0] ConstanteIn;

// Outputs
wire [31:0] ConstanteOut;

integer i;

Extensor uut (
    .Controle(Controle),
    .ConstanteIn(ConstanteIn),
    .ConstanteOut(ConstanteOut)
);

initial clk = 0;

always #5 clk = ~clk;

task observe;
    begin
        #1;
        $display("Controle=%b ConstanteIn=%h ConstanteOut=%h",
                 Controle, ConstanteIn, ConstanteOut);
    end
endtask

task exercise_value;
    input [15:0] value;
    begin
        // Change data at fixed mode, then exercise both mode transitions.
        ConstanteIn = value;
        Controle = 1'b0;
        observe;
        Controle = 1'b1;
        observe;
        Controle = 1'b0;
        observe;
    end
endtask

task exercise_unknown_control;
    input valid_mode;
    input unknown_mode;
    input [15:0] value;
    begin
        // Establish a defined output through a normal top-level transaction.
        Controle = valid_mode;
        ConstanteIn = value;
        observe;

        // X or Z matches neither binary case item.
        Controle = unknown_mode;
        observe;

        // Trigger input sensitivity again while control remains unknown.
        ConstanteIn = ~value;
        observe;

        // Resume normal operation with the new data.
        Controle = valid_mode;
        observe;
    end
endtask

initial begin
    Controle = 1'b0;
    ConstanteIn = 16'h0000;

    // Template startup interval; DUT has no reset.
    #100;

    // Test Case 1: Zero, unit values, and signed boundaries.
    exercise_value(16'h0000);
    exercise_value(16'h0001);
    exercise_value(16'h07ff);
    exercise_value(16'h0800);
    exercise_value(16'h0fff);
    exercise_value(16'h7fff);
    exercise_value(16'h8000);
    exercise_value(16'hffff);

    // Test Case 2: Alternating fields and all unused upper-nibble values.
    Controle = 1'b1;
    ConstanteIn = 16'h0000;
    observe;
    for (i = 0; i < 16; i = i + 1) begin
        #1;
        ConstanteIn = {i[3:0], 12'h555};
        observe;
        ConstanteIn = {i[3:0], 12'haaa};
        observe;
    end

    // Test Case 3: Alternating patterns in both modes.
    exercise_value(16'h5555);
    exercise_value(16'haaaa);

    // Test Case 4: Directed implicit no-match branch coverage.
    // Unknown controls are outside the normal binary-control assumption.
    // Print observations only; do not prescribe unknown-control behavior.
    for (i = 0; i < 2; i = i + 1) begin
        #1;
        exercise_unknown_control(i[0], 1'bx, 16'h8000);
        exercise_unknown_control(i[0], 1'bz, 16'h0800);
    end

    $display("===========End===========");
    $finish;
end

endmodule

