);

initial clk = 1'b0;
always #5 clk = ~clk;

task show_outputs;
    input integer test_id;
    begin
        $display("TEST=%0d TIME=%0t CLK=%b CS=%b DONE=%b READ_DATA=%h BYTE_VALID=%b STATE=%h IO0=%b IO1=%b IO2=%b IO3=%b",
                 test_id, $time, qspi_clk, qspi_cs, done_sig,
                 read_data, read_byte_valid, qspi_state,
                 io0, io1, io2, io3);
    end
endtask

task release_read_bus;
    begin
        io0_drive_en = 1'b0;
        io1_drive_en = 1'b0;
        io2_drive_en = 1'b0;
        io3_drive_en = 1'b0;
    end
endtask

task reset_dut;
    begin
        #1;
        cmd_type = 5'b0;
        release_read_bus;
        rst_n = 1'b0;

        #1 show_outputs(0);

        repeat (2) @(posedge clk);
        #1 show_outputs(0);
        rst_n = 1'b1;

        repeat (2) @(posedge clk);
        @(negedge clk);
        #1 show_outputs(0);
    end
endtask

task begin_transaction;
    input [3:0] op;
    begin
        @(posedge clk);
        #1;
        cmd_type = {1'b1, op};

        @(negedge clk);
        #1;
        cmd_type[4] = 1'b0;
    end
endtask

task observe_negedges;
    input integer count;
    input integer test_id;
    integer k;
    begin
        for (k = 0; k < count; k = k + 1) begin
            @(negedge clk);
            #1 show_outputs(test_id);
        end
    end
endtask

task finish_transaction;
    begin
        cmd_type[4] = 1'b0;
        repeat (2) @(posedge clk);
        #1;
    end
endtask

task single_read;
    input [3:0] op;
    input integer byte_count;
    input integer test_id;
    integer byte_index;
    integer bit_index;
    reg [7:0] read_pattern;
    begin
        begin_transaction(op);

        if (op == 4'b0111)
            observe_negedges(33, test_id);
        else
            observe_negedges(9, test_id);

        io1_drive_en = 1'b1;

        for (byte_index = 0;
             byte_index < byte_count;
             byte_index = byte_index + 1) begin
            read_pattern = 8'hA5 ^ byte_index;

            for (bit_index = 0;
                 bit_index < 8;
                 bit_index = bit_index + 1) begin
                io1_drive = read_pattern[7-bit_index];
                @(posedge clk);
                #1 show_outputs(test_id);
            end
        end

        repeat (4) begin
            @(posedge clk);
            #1 show_outputs(test_id);
        end

        release_read_bus;
        finish_transaction;
        show_outputs(test_id);
    end
endtask

task quad_read;
    input integer test_id;
    integer byte_index;
    integer nibble_index;
    reg [7:0] read_pattern;
    begin
        begin_transaction(4'b1001);

        observe_negedges(43, test_id);

        io0_drive_en = 1'b1;
        io1_drive_en = 1'b1;
        io2_drive_en = 1'b1;
        io3_drive_en = 1'b1;

        for (byte_index = 0;
             byte_index < 256;
             byte_index = byte_index + 1) begin
            read_pattern = 8'h3C ^ byte_index;

            for (nibble_index = 0;
                 nibble_index < 2;
                 nibble_index = nibble_index + 1) begin
                if (nibble_index == 0) begin
                    io3_drive = read_pattern[7];
                    io2_drive = read_pattern[6];
                    io1_drive = read_pattern[5];
                    io0_drive = read_pattern[4];
                end
                else begin
                    io3_drive = read_pattern[3];
                    io2_drive = read_pattern[2];
                    io1_drive = read_pattern[1];
                    io0_drive = read_pattern[0];
                end

                @(posedge clk);
                #1 show_outputs(test_id);
            end
        end

        release_read_bus;

        repeat (4) begin
            @(posedge clk);
            #1 show_outputs(test_id);
        end

        finish_transaction;
        show_outputs(test_id);
    end
endtask

task reset_during_phase;
    input [3:0] op;
    input integer phase_clocks;
    input integer test_id;
    begin
        begin_transaction(op);
        observe_negedges(phase_clocks, test_id);

        if (op == 4'b1001 && phase_clocks == 43) begin
            io0_drive_en = 1'b1;
            io1_drive_en = 1'b1;
            io2_drive_en = 1'b1;
            io3_drive_en = 1'b1;
            {io3_drive, io2_drive, io1_drive, io0_drive} = 4'hA;
        end

        @(posedge clk);
        #1 show_outputs(test_id);

        reset_dut;
        show_outputs(test_id);
    end
endtask

initial begin
    rst_n = 1'b0;
    cmd_type = 5'b0;
    cmd_code = 8'h9A;
    qspi_addr = 24'h123456;
    status_reg = 16'hA55A;
    test_vec = 8'h3C;

    io0_drive_en = 1'b0;
    io1_drive_en = 1'b0;
    io2_drive_en = 1'b0;
    io3_drive_en = 1'b0;

    io0_drive = 1'b0;
    io1_drive = 1'b0;
    io2_drive = 1'b0;
    io3_drive = 1'b0;

    reset_dut;

    // Test 1: command-only operations 0001 and 0100.
    begin_transaction(4'b0001);
    observe_negedges(12, 1);
    finish_transaction;
    reset_dut;

    begin_transaction(4'b0100);
    observe_negedges(12, 2);
    finish_transaction;
    reset_dut;

    // Test 2: address-only operation 0010.
    begin_transaction(4'b0010);
    observe_negedges(40, 3);
    finish_transaction;
    reset_dut;

    // Test 3: addressed single-byte write 0101.
    begin_transaction(4'b0101);
    observe_negedges(50, 4);
    finish_transaction;
    reset_dut;

    // Test 4: status-register write 0110.
    begin_transaction(4'b0110);
    observe_negedges(35, 5);
    finish_transaction;
    reset_dut;

    // Test 5: one-byte single-lane read 0011.
    single_read(4'b0011, 1, 6);
    reset_dut;

    // Test 6: two-byte single-lane read 1010.
    single_read(4'b1010, 2, 7);
    reset_dut;

    // Test 7: twenty-one-byte single-lane read 0000.
    single_read(4'b0000, 21, 8);
    reset_dut;

    // Test 8: 256-byte single-lane read 0111.
    single_read(4'b0111, 256, 9);
    reset_dut;

    // Test 9: 256-byte quad-lane write 1000.
    begin_transaction(4'b1000);
    observe_negedges(555, 10);
    finish_transaction;
    reset_dut;

    // Test 10: 256-byte quad-lane read 1001.
    quad_read(11);
    reset_dut;

    // Test 11: unsupported operation remains active.
    begin_transaction(4'b1111);
    observe_negedges(20, 12);
    cmd_type[4] = 1'b0;
    repeat (2) @(posedge clk);
    #1 show_outputs(12);
    reset_dut;

    // Test 12: reset after two dummy clocks.
    reset_during_phase(4'b1001, 34, 13);

    // Test 13: reset after the first quad-read nibble.
    reset_during_phase(4'b1001, 43, 14);

    // Test 14: reset after two single-write data bits.
    reset_during_phase(4'b0101, 34, 15);

    // Test 15: reset after the first quad-write byte.
    reset_during_phase(4'b1000, 34, 16);

    // Test 16: change the live selector during the address phase.
    begin_transaction(4'b0010);
    observe_negedges(8, 17);

    cmd_type = {1'b0, 4'b1111};
    observe_negedges(28, 17);

    cmd_type = {1'b0, 4'b0010};
    observe_negedges(4, 17);
    finish_transaction;
    reset_dut;

    // Test 17: automatic restart with request held high.
    cmd_code = 8'h65;
    begin_transaction(4'b0001);
    cmd_type[4] = 1'b1;

    observe_negedges(19, 18);
    cmd_type[4] = 1'b0;
    observe_negedges(3, 18);
    finish_transaction;
    reset_dut;

    // Test 18: reset while in the single-lane read state.
    // Eight command clocks enter C_READ_WAIT; the ninth fixed
    // observation clock executes the read-state branch.
    reset_during_phase(4'b0011, 9, 19);

    // Test 19: reset during the address phase.
    // Eight command clocks plus 23 address clocks leave the DUT
    // in C_SEND_ADDR before the reset is asserted.
    reset_during_phase(4'b0010, 31, 20);

    // Test 20: reset while writing the captured status register.
    // Eight command clocks enter C_WRITE_STATE_REG; the next
    // fixed clock keeps the controller in that state.
    reset_during_phase(4'b0110, 9, 21);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

reg        clk;
reg        rst_n;
reg        gmii_rx_dv;
reg [7:0]  gmii_rxd;

wire       arp_rx_done;
wire       arp_rx_type;
wire [47:0] src_mac;
wire [31:0] src_ip;

arp_rx uut (
    .clk        (clk),
    .rst_n      (rst_n),
    .gmii_rx_dv (gmii_rx_dv),
    .gmii_rxd   (gmii_rxd),
    .arp_rx_done(arp_rx_done),
    .arp_rx_type(arp_rx_type),
    .src_mac    (src_mac),
    .src_ip     (src_ip)
);

initial clk = 1'b0;
always #5 clk = ~clk;

task reset_dut;
begin
    rst_n      = 1'b0;
    gmii_rx_dv = 1'b0;
    gmii_rxd   = 8'h00;
    #2;
    rst_n      = 1'b1;
    repeat (2) @(posedge clk);
end
endtask

task send_byte;
    input [7:0] value;
begin
    gmii_rx_dv = 1'b1;
    gmii_rxd   = value;
    @(posedge clk);
end
endtask

task send_48;
    input [47:0] value;
    reg [47:0] shift_value;
    integer i;
begin
    shift_value = value;
    for (i = 0; i < 6; i = i + 1) begin
        send_byte(shift_value[47:40]);
        shift_value = shift_value << 8;
    end
end
endtask

task send_32;
    input [31:0] value;
    reg [31:0] shift_value;
    integer i;
begin
    shift_value = value;
    for (i = 0; i < 4; i = i + 1) begin
        send_byte(shift_value[31:24]);
        shift_value = shift_value << 8;
    end
end
endtask

task send_frame;
    input [47:0] destination_mac;
    input [47:0] sender_mac;
    input [31:0] sender_ip;
    input [31:0] target_ip;
    input [15:0] operation;
    input integer insert_gap;
    integer i;
begin
    for (i = 0; i < 7; i = i + 1)
        send_byte(8'h55);
    send_byte(8'hd5);

    if (insert_gap != 0) begin
        gmii_rx_dv = 1'b0;
        gmii_rxd   = 8'h00;
        repeat (2) @(posedge clk);
    end

    send_48(destination_mac);
    send_48(48'h12_34_56_78_9a_bc);
    send_byte(8'h08);
    send_byte(8'h06);

    for (i = 0; i < 6; i = i + 1)
        send_byte(8'h00);

    send_byte(operation[15:8]);
    send_byte(operation[7:0]);
    send_48(sender_mac);
    send_32(sender_ip);
    send_48(48'h00_00_00_00_00_00);
    send_32(target_ip);

    send_byte(8'h00);
end
endtask

// gap_kind = 1: gap during preamble
// gap_kind = 2: gap during ARP payload
task send_frame_with_gap;
    input [47:0] destination_mac;
    input [47:0] sender_mac;
    input [31:0] sender_ip;
    input [31:0] target_ip;
    input [15:0] operation;
    input integer gap_kind;
    integer i;
begin
    send_byte(8'h55);

    if (gap_kind == 1) begin
        gmii_rx_dv = 1'b0;
        gmii_rxd   = 8'h00;
        repeat (2) @(posedge clk);
    end

    for (i = 1; i < 7; i = i + 1)
        send_byte(8'h55);
    send_byte(8'hd5);

    send_48(destination_mac);
    send_48(48'h12_34_56_78_9a_bc);
    send_byte(8'h08);
    send_byte(8'h06);

    for (i = 0; i < 6; i = i + 1)
        send_byte(8'h00);

    if (gap_kind == 2) begin
        gmii_rx_dv = 1'b0;
        gmii_rxd   = 8'h00;
        repeat (2) @(posedge clk);
    end

    send_byte(operation[15:8]);
    send_byte(operation[7:0]);
    send_48(sender_mac);
    send_32(sender_ip);
    send_48(48'h00_00_00_00_00_00);
    send_32(target_ip);

    send_byte(8'h00);
end
endtask

task send_bad_preamble;
begin
    send_byte(8'h55);
    send_byte(8'h00);
    gmii_rx_dv = 1'b0;
    gmii_rxd   = 8'h00;
    repeat (3) @(posedge clk);
end
endtask

task send_bad_delimiter;
    integer i;
begin
    for (i = 0; i < 7; i = i + 1)
        send_byte(8'h55);
    send_byte(8'h00);
    gmii_rx_dv = 1'b0;
    gmii_rxd   = 8'h00;
    repeat (3) @(posedge clk);
end
endtask

task send_bad_eth_type_high;
    integer i;
begin
    for (i = 0; i < 7; i = i + 1)
        send_byte(8'h55);
    send_byte(8'hd5);

    send_48(48'h00_11_22_33_44_55);
    send_48(48'h21_22_23_24_25_26);

    send_byte(8'h09);
    send_byte(8'h06);

    for (i = 0; i < 3; i = i + 1)
        send_byte(8'h00);

    gmii_rx_dv = 1'b0;
    gmii_rxd   = 8'h00;
    repeat (3) @(posedge clk);
end
endtask

// Abort parsing with asynchronous reset while entering one of the
// three active parser states:
// state_kind = 1: st_preamble
// state_kind = 2: st_eth_head
// state_kind = 3: st_arp_data
task reset_while_parsing;
    input integer state_kind;
    integer i;
begin
    if (state_kind == 1) begin
        send_byte(8'h55);
    end
    else if (state_kind == 2) begin
        for (i = 0; i < 7; i = i + 1)
            send_byte(8'h55);
        send_byte(8'hd5);
        send_byte(8'h00);
    end
    else begin
        for (i = 0; i < 7; i = i + 1)
            send_byte(8'h55);
        send_byte(8'hd5);
        send_48(48'h00_11_22_33_44_55);
        send_48(48'h12_34_56_78_9a_bc);
        send_byte(8'h08);
        send_byte(8'h06);
        send_byte(8'h00);
    end

    rst_n      = 1'b0;
    gmii_rx_dv = 1'b0;
    gmii_rxd   = 8'h00;
    #2;
    rst_n      = 1'b1;
    repeat (2) @(posedge clk);
end
endtask

task finish_frame;
begin
    gmii_rx_dv = 1'b0;
    gmii_rxd   = 8'h00;
    repeat (3) @(posedge clk);
end
endtask

task observe_outputs;
    input integer test_number;
begin
    #1;
    $display("TC%0d: arp_rx_done=%b arp_rx_type=%b src_mac=%h src_ip=%h",
             test_number, arp_rx_done, arp_rx_type, src_mac, src_ip);
end
endtask

initial begin
    rst_n      = 1'b0;
    gmii_rx_dv = 1'b0;
    gmii_rxd   = 8'h00;

    // Reset behavior
    #2;
    observe_outputs(0);
    rst_n = 1'b1;
    repeat (2) @(posedge clk);

    // Exercise idle with gmii_rx_dv low and a non-preamble byte.
    reset_dut;
    gmii_rx_dv = 1'b0;
    gmii_rxd   = 8'h55;
    @(posedge clk);
    gmii_rx_dv = 1'b1;
    gmii_rxd   = 8'h00;
    @(posedge clk);
    observe_outputs(10);
    finish_frame;

    // Reset from st_preamble.
    reset_dut;
    reset_while_parsing(1);
    observe_outputs(15);

    // Reset from st_eth_head.
    reset_dut;
    reset_while_parsing(2);
    observe_outputs(16);

    // Reset from st_arp_data.
    reset_dut;
    reset_while_parsing(3);
    observe_outputs(17);

    // Accepted request to local destination
    reset_dut;
    send_frame(
        48'h00_11_22_33_44_55,
        48'ha1_a2_a3_a4_a5_a6,
        32'h0a_01_02_03,
        32'hc0_a8_01_0a,
        16'd1,
        0
    );
    observe_outputs(1);
    finish_frame;

    // Accepted reply to broadcast destination, with GMII gap
    reset_dut;
    send_frame(
        48'hff_ff_ff_ff_ff_ff,
        48'hb1_b2_b3_b4_b5_b6,
        32'h0a_04_05_06,
        32'hc0_a8_01_0a,
        16'd2,
        1
    );
    observe_outputs(2);
    finish_frame;

    // Valid request with a gap during preamble processing
    reset_dut;
    send_frame_with_gap(
        48'h00_11_22_33_44_55,
        48'h11_22_33_44_55_66,
        32'h0b_01_02_03,
        32'hc0_a8_01_0a,
        16'd1,
        1
    );
    observe_outputs(11);
    finish_frame;

    // Valid reply with a gap during ARP payload processing
    reset_dut;
    send_frame_with_gap(
        48'hff_ff_ff_ff_ff_ff,
        48'h22_33_44_55_66_77,
        32'h0b_04_05_06,
        32'hc0_a8_01_0a,
        16'd2,
        2
    );
    observe_outputs(12);
    finish_frame;

    // Invalid preamble byte
    reset_dut;
    send_bad_preamble;
    observe_outputs(3);
    finish_frame;

    // Invalid start-frame delimiter after a complete preamble
    reset_dut;
    send_bad_delimiter;
    observe_outputs(13);
    finish_frame;

    // Invalid destination MAC
    reset_dut;
    send_frame(
        48'h10_20_30_40_50_60,
        48'hc1_c2_c3_c4_c5_c6,
        32'h0a_07_08_09,
        32'hc0_a8_01_0a,
        16'd1,
        0
    );
    observe_outputs(4);
    finish_frame;

    // Invalid Ethernet type, correct high byte and incorrect low byte
    reset_dut;
    send_byte(8'h55);
    send_byte(8'h55);
    send_byte(8'h55);
    send_byte(8'h55);
    send_byte(8'h55);
    send_byte(8'h55);
    send_byte(8'h55);
    send_byte(8'hd5);
    send_48(48'h00_11_22_33_44_55);
    send_48(48'h21_22_23_24_25_26);
    send_byte(8'h08);
    send_byte(8'h00);
    finish_frame;
    observe_outputs(5);

    // Invalid Ethernet type, incorrect high byte and correct low byte
    reset_dut;
    send_bad_eth_type_high;
    observe_outputs(14);
    finish_frame;

    // Unsupported ARP operation
    reset_dut;
    send_frame(
        48'h00_11_22_33_44_55,
        48'hd1_d2_d3_d4_d5_d6,
        32'h0a_0a_0b_0c,
        32'hc0_a8_01_0a,
        16'd3,
        0
    );
    // Keep DV asserted after rejection to exercise the st_rx_end
    // condition where gmii_rx_dv is high and skip_en is low.
    send_byte(8'h00);
    observe_outputs(6);
    finish_frame;

    // Mismatched target IP
    reset_dut;
    send_frame(
        48'h00_11_22_33_44_55,
        48'he1_e2_e3_e4_e5_e6,
        32'h0a_0d_0e_0f,
        32'hc0_a8_01_0b,
        16'd1,
        0
    );
    observe_outputs(7);
    finish_frame;

    // Retention after a rejected frame
    reset_dut;
    send_frame(
        48'h00_11_22_33_44_55,
        48'hf1_f2_f3_f4_f5_f6,
        32'h0a_10_11_12,
        32'hc0_a8_01_0a,
        16'd1,
        0
    );
    observe_outputs(8);
    finish_frame;

    send_frame(
        48'h00_11_22_33_44_55,
        48'h01_02_03_04_05_06,
        32'h0a_13_14_15,
        32'hc0_a8_01_0b,
        16'd1,
        0
    );
    observe_outputs(9);
    finish_frame;

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

// Inputs
reg clk;
reg rst_n, flag, spisomi, wr_en, rd_en, stage_rst;
reg [7:0] tx_data;

// Outputs
wire spi_done, sclk, spisimo, spiste;
wire [7:0] rx_data;

integer test_id, p, r, scenario, clear_mode;
reg [7:0] pattern;

// Instantiate the Unit Under Test (UUT)
spi uut (
    .div_clk(clk),
    .rst_n(rst_n),
    .flag(flag),
    .spisomi(spisomi),
    .wr_en(wr_en),
    .rd_en(rd_en),
    .stage_rst(stage_rst),
    .tx_data(tx_data),
    .spi_done(spi_done),
    .sclk(sclk),
    .spisimo(spisimo),
    .spiste(spiste),
    .rx_data(rx_data)
);

// clk toggle generate
initial clk = 0; //clk is initialized as 0
always #5 clk = ~clk;

task observe;
begin
    $display("test=%0d t=%0t rst_n=%b stage_rst=%b wr=%b rd=%b flag=%b tx=%h si=%b | done=%b sclk=%b simo=%b ste=%b rx=%h",
             test_id, $time, rst_n, stage_rst, wr_en, rd_en,
             flag, tx_data, spisomi,
             spi_done, sclk, spisimo, spiste, rx_data);
end
endtask

task tick;
begin
    @(posedge clk);
    #1;
    observe;
end
endtask

task clean;
begin
    @(negedge clk);
    rst_n = 0;
    stage_rst = 0;
    wr_en = 0;
    rd_en = 0;
    flag = 0;
    tx_data = 0;
    spisomi = 0;
    #1;
    observe;
    tick;
    @(negedge clk);
    rst_n = 1;
    tick;
end
endtask

// Fixed stimulus schedule; no synchronization to DUT outputs.
task transfer;
    input integer edges;
    input [7:0] data;
    input integer live_tx;
    integer i;
begin
    for (i = 0; i < edges; i = i + 1) begin
        @(negedge clk);
        tx_data = live_tx ? {8{(i[1] ^ i[0])}} : data;
        spisomi = i[0] ? data[7 - ((i % 16) / 2)]
                       : ~data[7 - ((i % 16) / 2)];
        tick;
    end
end
endtask

initial begin
    // Initialize Inputs
    test_id = 0;
    rst_n = 0;
    flag = 0;
    spisomi = 0;
    wr_en = 0;
    rd_en = 0;
    stage_rst = 0;
    tx_data = 0;

    // Wait 100 ns for global reset to finish
    #100;
    observe;
    @(negedge clk);
    rst_n = 1;
    tick;

    // Test 1: idle and held flag.
    test_id = 1;
    clean;
    @(negedge clk);
    flag = 1;
    tick;
    tick;
    @(negedge clk);
    flag = 0;
    tick;

    // Tests 10-13: write patterns and uninterrupted repetition.
    for (p = 0; p < 4; p = p + 1) begin
        @(negedge clk);
        test_id = 10 + p;
        case (p)
            0: pattern = 8'h00;
            1: pattern = 8'hFF;
            2: pattern = 8'hA5;
            3: pattern = 8'h5A;
        endcase
        clean;
        wr_en = 1;
        transfer(16, pattern, 0);
        transfer(16, ~pattern, 0);
        @(negedge clk);
        wr_en = 0;
        tick;
    end

    // Test 14: live transmit data and write priority over read/flag.
    test_id = 14;
    clean;
    wr_en = 1;
    rd_en = 1;
    flag = 1;
    transfer(32, 8'hA5, 1);
    @(negedge clk);
    wr_en = 0;
    rd_en = 0;
    tick;

    // Tests 20-23: read patterns, low-phase input rejection, repetition.
    for (p = 0; p < 4; p = p + 1) begin
        @(negedge clk);
        test_id = 20 + p;
        case (p)
            0: pattern = 8'h00;
            1: pattern = 8'hFF;
            2: pattern = 8'hA5;
            3: pattern = 8'h5A;
        endcase
        clean;
        rd_en = 1;
        flag = 1;
        transfer(16, pattern, 0);
        transfer(16, ~pattern, 0);
        @(negedge clk);
        rd_en = 0;
        flag = 0;
        tick;
    end

    // Test 30: retention and direct operation changes.
    test_id = 30;
    clean;
    wr_en = 1;
    transfer(16, 8'hFF, 0);
    wr_en = 0;
    rd_en = 1;
    transfer(16, 8'hA6, 0);
    wr_en = 1;
    rd_en = 0;
    transfer(16, 8'h5A, 0);
    wr_en = 0;
    rd_en = 1;
    transfer(3, 8'h00, 0);
    wr_en = 1;
    rd_en = 0;
    transfer(3, 8'hFF, 0);
    wr_en = 0;
    rd_en = 1;
    transfer(10, 8'hFF, 0);

    // Tests 40-41: partial/completed transfers cleared by idle or flag.
    for (clear_mode = 0; clear_mode < 2;
         clear_mode = clear_mode + 1) begin
        @(negedge clk);
        test_id = 40 + clear_mode;
        clean;
        wr_en = 1;
        transfer(5, 8'hFF, 0);
        @(negedge clk);
        wr_en = 0;
        flag = clear_mode;
        tick;
        tick;

        wr_en = 1;
        transfer(16, 8'hA5, 0);
        wr_en = 0;
        rd_en = 1;
        transfer(6, 8'hFF, 0);
        @(negedge clk);
        rd_en = 0;
        tick;
        tick;

        rd_en = 1;
        transfer(16, 8'h96, 0);
        @(negedge clk);
        rd_en = 0;
        tick;
        tick;

        rd_en = 1;
        transfer(16, 8'h69, 0);
    end

    // Tests 50-55: both reset types at partial and completion boundaries.
    for (r = 0; r < 2; r = r + 1) begin
        @(negedge clk);
        for (scenario = 0; scenario < 3; scenario = scenario + 1) begin
            @(negedge clk);
            test_id = 50 + 3*r + scenario;
            clean;
            if (scenario == 0) begin
                wr_en = 1;
                transfer(15, 8'hFF, 0);
            end else begin
                rd_en = 1;
                transfer((scenario == 1) ? 6 : 16, 8'hFF, 0);
            end

            @(negedge clk);
            wr_en = 1;
            rd_en = 1;
            flag = 1;
            stage_rst = 1;
            if (r == 0)
                rst_n = 0;
            #1;
            observe;
            tick;
            tick;

            @(negedge clk);
            rst_n = 1;
            stage_rst = 0;
            transfer(16, 8'h81, 0);
            @(negedge clk);
            wr_en = 0;
            rd_en = 0;
            flag = 0;
            tick;
        end
    end

    $display("===========End===========");
    $finish;
end

endmodule

