module testbench;

reg clk;
reg reset;
reg dummy;
reg start_out;
reg rnw;
reg [12:0] div_rate;
reg [3:0] dummy_clks;
reg [1:0] mode;
reg [7:0] din;
reg [3:0] dq_i;

wire [7:0] dout;
wire done;
wire done_for_wr;
wire [3:0] dq_t_delayed;
wire c;
wire s;
wire [3:0] dq_o;
wire [3:0] dq_t;

spi_tr8 uut (
    .clk(clk),
    .reset(reset),
    .dummy(dummy),
    .start_out(start_out),
    .rnw(rnw),
    .div_rate(div_rate),
    .dummy_clks(dummy_clks),
    .mode(mode),
    .din(din),
    .dout(dout),
    .done(done),
    .done_for_wr(done_for_wr),
    .dq_t_delayed(dq_t_delayed),
    .c(c),
    .s(s),
    .dq_o(dq_o),
    .dq_t(dq_t),
    .dq_i(dq_i)
);

initial clk = 1'b0;
always #5 clk = ~clk;

task reset_dut;
begin
    start_out = 1'b0;
    dummy     = 1'b0;
    rnw       = 1'b0;
    reset     = 1'b1;
    repeat (3) @(posedge clk);
    #1;
    reset = 1'b0;
    repeat (3) @(posedge clk);
    #1;
end
endtask

task observe;
begin
    $display("c=%b s=%b dq_o=%b dq_t=%b dq_t_delayed=%b dout=%h done=%b done_for_wr=%b",
             c, s, dq_o, dq_t, dq_t_delayed, dout, done, done_for_wr);
end
endtask

task write_transfer;
    input integer rate_value;
    input [1:0] write_mode;
    input [7:0] write_data;
    input integer hold_cycles;
begin
    reset_dut();
    div_rate = rate_value;
    mode = write_mode;
    din = write_data;
    dummy = 1'b0;
    rnw = 1'b0;
    start_out = 1'b1;
    repeat (hold_cycles) @(posedge clk);
    #1;
    observe();
    start_out = 1'b0;
    repeat (20) @(posedge clk);
    #1;
    observe();
end
endtask

task directed_read;
    input integer rate_value;
    input [1:0] read_mode;
    input [3:0] lane_value;
    input integer hold_cycles;
begin
    reset_dut();
    div_rate = rate_value;
    mode = read_mode;
    dq_i = lane_value;
    dummy = 1'b0;
    rnw = 1'b1;
    start_out = 1'b1;
    repeat (hold_cycles) @(posedge clk);
    #1;
    observe();
    start_out = 1'b0;
    repeat (32) @(posedge clk);
    #1;
    observe();
end
endtask

task pulsed_read;
    input integer rate_value;
    input [1:0] read_mode;
    input [3:0] lane_value;
    input integer settle_cycles;
begin
    reset_dut();
    div_rate = rate_value;
    mode = read_mode;
    dq_i = lane_value;
    dummy = 1'b0;
    rnw = 1'b1;
    start_out = 1'b1;
    repeat (2) @(posedge clk);
    start_out = 1'b0;
    repeat (settle_cycles) @(posedge clk);
    #1;
    observe();
end
endtask

task dummy_transfer;
    input integer rate_value;
    input [3:0] configured_dummy_clks;
    input integer hold_cycles;
begin
    reset_dut();
    div_rate = rate_value;
    mode = 2'b00;
    dummy_clks = configured_dummy_clks;
    dummy = 1'b1;
    rnw = 1'b0;
    start_out = 1'b1;
    repeat (hold_cycles) @(posedge clk);
    #1;
    observe();
    start_out = 1'b0;
    repeat (24) @(posedge clk);
    #1;
    observe();
end
endtask

integer i;

initial begin
    reset = 1'b0;
    dummy = 1'b0;
    start_out = 1'b0;
    rnw = 1'b0;
    div_rate = 13'd8;
    dummy_clks = 4'd2;
    mode = 2'b00;
    din = 8'hA5;
    dq_i = 4'b1010;

    reset_dut();
    observe();

    // Write path in all lane modes, including reserved mode 11.
    for (i = 0; i < 4; i = i + 1) begin
        write_transfer(8, i[1:0], 8'hA5 ^ i, 48);
    end

    // Dummy path with zero and nonzero configured counts.
    dummy_transfer(8, 4'd0, 48);
    dummy_transfer(8, 4'd3, 48);

    // Read sampling in supported modes.
    for (i = 0; i < 3; i = i + 1) begin
        directed_read(8, i[1:0], 4'b1010 ^ i, 64);
    end

    // Divider boundary and delayed-output paths.
    directed_read(2, 2'b10, 4'b1101, 64);
    directed_read(4, 2'b10, 4'b1101, 64);
    directed_read(12, 2'b10, 4'b1101, 64);

    // Idle-state combinations with no transfer request.
    reset_dut();
    div_rate = 13'd8;
    mode = 2'b00;
    dummy = 1'b1;
    rnw = 1'b0;
    start_out = 1'b0;
    repeat (4) @(posedge clk);
    #1;
    observe();

    // Explicit idle-to-send_data transition.
    dummy = 1'b0;
    rnw = 1'b0;
    start_out = 1'b1;
    repeat (8) @(posedge clk);
    #1;
    observe();
    start_out = 1'b0;
    repeat (24) @(posedge clk);
    #1;
    observe();

    // Dummy to read transition.
    reset_dut();
    div_rate = 13'd8;
    dummy_clks = 4'd3;
    mode = 2'b01;
    din = 8'h3C;
    dummy = 1'b1;
    rnw = 1'b1;
    start_out = 1'b1;
    repeat (16) @(posedge clk);
    #1;
    observe();
    start_out = 1'b0;
    repeat (32) @(posedge clk);
    #1;
    observe();

    // Dummy to write transition.
    reset_dut();
    div_rate = 13'd8;
    dummy_clks = 4'd3;
    mode = 2'b00;
    din = 8'h69;
    dummy = 1'b1;
    rnw = 1'b0;
    start_out = 1'b1;
    repeat (8) @(posedge clk);
    dummy = 1'b0;
    rnw = 1'b0;
    repeat (8) @(posedge clk);
    #1;
    observe();
    start_out = 1'b0;
    repeat (32) @(posedge clk);
    #1;
    observe();

    // Write to read while start_out remains asserted.
    reset_dut();
    div_rate = 13'd8;
    mode = 2'b10;
    din = 8'h96;
    dq_i = 4'b0110;
    dummy = 1'b0;
    rnw = 1'b0;
    start_out = 1'b1;
    repeat (8) @(posedge clk);
    rnw = 1'b1;
    repeat (16) @(posedge clk);
    #1;
    observe();
    start_out = 1'b0;
    repeat (32) @(posedge clk);
    #1;
    observe();

    // Read to write through the internal start detector.
    reset_dut();
    div_rate = 13'd8;
    mode = 2'b00;
    din = 8'h5A;
    dq_i = 4'b1001;
    dummy = 1'b0;
    rnw = 1'b1;
    start_out = 1'b1;
    repeat (8) @(posedge clk);
    rnw = 1'b0;
    repeat (12) @(posedge clk);
    #1;
    observe();
    start_out = 1'b0;
    repeat (32) @(posedge clk);
    #1;
    observe();

    // Read to dummy and then dummy to write.
    reset_dut();
    div_rate = 13'd8;
    mode = 2'b01;
    din = 8'hC3;
    dq_i = 4'b0101;
    dummy_clks = 4'd3;
    dummy = 1'b0;
    rnw = 1'b1;
    start_out = 1'b1;
    repeat (8) @(posedge clk);
    dummy = 1'b1;
    repeat (12) @(posedge clk);
    #1;
    observe();
    dummy = 1'b0;
    rnw = 1'b0;
    repeat (12) @(posedge clk);
    #1;
    observe();
    start_out = 1'b0;
    repeat (32) @(posedge clk);
    #1;
    observe();

    // Short-pulse read result capture.
    directed_read(8, 2'b00, 4'b0011, 80);
    directed_read(8, 2'b01, 4'b1100, 80);

    // Short-divider alternate-mode start path.
    directed_read(2, 2'b01, 4'b1010, 48);
    directed_read(2, 2'b10, 4'b0110, 48);

    // div_rate == 4 uses poss_c as trigger_edge.
    directed_read(4, 2'b00, 4'b0110, 80);

    // Existing unsupported read-mode stimulus.
    directed_read(8, 2'b11, 4'b1001, 64);

    /*
     * Target send_dummy -> idle_wait:
     * start_out is removed before dummy completion, so the controller
     * remains in send_dummy until done_dly becomes active.
     */
    reset_dut();
    div_rate = 13'd8;
    dummy_clks = 4'd3;
    mode = 2'b00;
    din = 8'h69;
    dummy = 1'b1;
    rnw = 1'b0;
    start_out = 1'b1;
    repeat (4) @(posedge clk);
    start_out = 1'b0;
    repeat (20) @(posedge clk);
    #1;
    observe();
    repeat (16) @(posedge clk);
    #1;
    observe();

    /*
     * Repeat the delayed dummy-exit case at div_rate 4.  This also
     * exercises the alternate b value and the shortened timing path.
     */
    reset_dut();
    div_rate = 13'd4;
    dummy_clks = 4'd6;
    mode = 2'b01;
    dummy = 1'b1;
    rnw = 1'b0;
    start_out = 1'b1;
    repeat (3) @(posedge clk);
    start_out = 1'b0;
    repeat (32) @(posedge clk);
    #1;
    observe();
    repeat (16) @(posedge clk);
    #1;
    observe();

    /*
     * Direct unsupported-mode read.  In mode 11 the receive-counter
     * initialization case has no assignment, leaving count_read away
     * from its terminal value while read_data and pos_c are active.
     */
    reset_dut();
    div_rate = 13'd8;
    mode = 2'b11;
    dq_i = 4'b1001;
    dummy = 1'b0;
    rnw = 1'b1;
    start_out = 1'b1;
    repeat (3) @(posedge clk);
    start_out = 1'b0;
    repeat (80) @(posedge clk);
    #1;
    observe();

    /*
     * Initialize the receive counter in mode 00, then change the
     * external mode to 11 before receive completion.  This targets the
     * unsupported completion-reordering case while done_for_dout is
     * still generated by the initialized receive transfer.
     */
    reset_dut();
    div_rate = 13'd8;
    mode = 2'b00;
    dq_i = 4'b1001;
    dummy = 1'b0;
    rnw = 1'b1;
    start_out = 1'b1;
    repeat (3) @(posedge clk);
    start_out = 1'b0;
    repeat (6) @(posedge clk);
    mode = 2'b11;
    repeat (64) @(posedge clk);
    #1;
    observe();

    /*
     * Keep a supported read active while toggling the request around
     * the trigger-detector timing window.  The fixed short pulse enters
     * trig_posedge and the subsequent inactive interval allows the
     * tracker to resolve through its normal transition sequence.
     */
    reset_dut();
    div_rate = 13'd8;
    mode = 2'b00;
    dq_i = 4'b0011;
    dummy = 1'b0;
    rnw = 1'b1;
    start_out = 1'b1;
    repeat (1) @(posedge clk);
    start_out = 1'b0;
    repeat (3) @(posedge clk);
    start_out = 1'b1;
    repeat (2) @(posedge clk);
    start_out = 1'b0;
    repeat (64) @(posedge clk);
    #1;
    observe();

    // Additional short-pulse completion coverage for both alternate modes.
    pulsed_read(2, 2'b01, 4'b1010, 56);
    pulsed_read(2, 2'b10, 4'b0110, 56);
    pulsed_read(8, 2'b00, 4'b0011, 80);

    $display("===========End===========");
    $finish;
end

endmodule

