module testbench;

localparam N = 16;
localparam Q = 4;
localparam [N-1:0] ZERO = {N{1'b0}};
localparam [N-1:0] ONE  = {{(N-1){1'b0}}, 1'b1};
localparam [N-1:0] FULL = {N{1'b1}};
localparam [N-1:0] ALT  = {N/2{2'b10}};

// Inputs
reg clk;
reg [N-1:0] a, b;
reg cin;

// Outputs
wire [N-1:0] sum;
wire cout;
wire [N:0] result;

integer first_bit, last_bit;
reg [N-1:0] run_mask;

top_module #(.N(N), .Q(Q)) uut (
    .a(a), .b(b), .cin(cin),
    .sum(sum), .cout(cout), .result(result)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [8*24-1:0] label;
    begin
        $display("%0s t=%0t a=%h b=%h cin=%b sum=%h cout=%b result=%h",
                 label, $time, a, b, cin, sum, cout, result);
    end
endtask

task apply_vector;
    input [8*24-1:0] label;
    input [N-1:0] av, bv;
    begin
        a = ZERO;
        b = ZERO;
        cin = 0;
        #10;

        a = av;
        b = bv;
        #10;
        observe(label);

        cin = 1;
        #10;
        observe(label);
    end
endtask

initial begin
    a = ZERO;
    b = ZERO;
    cin = 0;
    run_mask = ZERO;

    // Wait 100 ns for global initialization.
    #100;
    observe("initial_zero");

    // Baseline, limits, and alternating patterns.
    apply_vector("zero", ZERO, ZERO);
    apply_vector("maximum_a", FULL, ZERO);
    apply_vector("maximum_b", ZERO, FULL);
    apply_vector("both_maximum", FULL, FULL);
    apply_vector("alternating_ab", ALT, ~ALT);
    apply_vector("alternating_ba", ~ALT, ALT);
    apply_vector("alternating_generate", ALT, ALT);
    apply_vector("alternate_generate", ~ALT, ~ALT);

    // Isolated bits and all carry-run lengths, including boundaries.
    for (first_bit = 0; first_bit < N; first_bit = first_bit + 1) begin
        #1;
        apply_vector("isolated_a", ONE << first_bit, ZERO);
        apply_vector("isolated_b", ZERO, ONE << first_bit);

        for (last_bit = first_bit; last_bit < N;
             last_bit = last_bit + 1) begin
            #1;
            run_mask = (FULL >> (N - 1 - (last_bit - first_bit)))
                       << first_bit;
            apply_vector("carry_run_ab", run_mask, ONE << first_bit);
            apply_vector("carry_run_ba", ONE << first_bit, run_mask);
        end
    end

    // Return to zero after active stimulus.
    a = ZERO;
    b = ZERO;
    cin = 0;
    #10;
    observe("final_zero");

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

reg clk;
reg rst_n;
reg enb;
reg [115:0] litTree;
reg [7:0] litCode;
reg [3:0] len_in;

wire fin_lit;
wire [4:0] litSymb;
wire [4:0] litCount;

integer i;
integer j;
integer target_length;

CL_code_lit uut (
    .clk     (clk),
    .rst_n   (rst_n),
    .enb     (enb),
    .litTree (litTree),
    .litCode (litCode),
    .len_in  (len_in),
    .fin_lit (fin_lit),
    .litSymb (litSymb),
    .litCount(litCount)
);

initial clk = 1'b0;
always #5 clk = ~clk;

task reset_dut;
begin
    @(negedge clk);
    rst_n = 1'b0;
    enb = 1'b0;
    repeat (2) @(posedge clk);
    #1;
    litCode = 8'd0;
    len_in = 4'd1;
    #1;
    $display("RESET: fin_lit=%b litSymb=%0d litCount=%0d",
             fin_lit, litSymb, litCount);

    @(negedge clk);
    rst_n = 1'b1;
    repeat (1) @(posedge clk);
    #1;
    $display("IDLE AFTER RESET: fin_lit=%b litSymb=%0d litCount=%0d",
             fin_lit, litSymb, litCount);
end
endtask

task observe_lookup;
    input [7:0] code_value;
    input [3:0] length_value;
begin
    litCode = code_value;
    len_in = length_value;
    #1;
    $display("LOOKUP litCode=%0d len_in=%0d: fin_lit=%b litSymb=%0d litCount=%0d",
             litCode, len_in, fin_lit, litSymb, litCount);
end
endtask

task start_build;
begin
    @(negedge clk);
    enb = 1'b1;
    @(posedge clk);
    #1;
    $display("START: fin_lit=%b litSymb=%0d litCount=%0d",
             fin_lit, litSymb, litCount);
    @(negedge clk);
    enb = 1'b0;
end
endtask

task start_and_complete;
begin
    start_build;
    repeat (232) @(posedge clk);
    #1;
    $display("AFTER 232 SCAN CYCLES: fin_lit=%b litSymb=%0d litCount=%0d",
             fin_lit, litSymb, litCount);
    repeat (3) @(posedge clk);
    #1;
    $display("COMPLETED HOLD: fin_lit=%b litSymb=%0d litCount=%0d",
             fin_lit, litSymb, litCount);
end
endtask

task interrupt_scan;
    input integer scan_length;
    integer count_index;
begin
    reset_dut;
    start_build;

    // Each length requires 29 scan cycles. Stop midway through
    // the requested scan so the next reset edge is unambiguous.
    repeat (29 * (scan_length - 1) + 14) @(posedge clk);
    #1;
    litCode = 8'd0;
    len_in = scan_length;
    #1;
    $display("BEFORE RESET DURING LENGTH %0d: fin_lit=%b litSymb=%0d litCount=%0d",
             scan_length, fin_lit, litSymb, litCount);

    // Reset is sampled on the next rising edge while this scan
    // is still active, targeting LenN -> IDLE.
    reset_dut;

    for (count_index = 0; count_index < 16;
         count_index = count_index + 1) begin
        observe_lookup(8'd0, count_index[3:0]);
        #1;
    end
end
endtask

initial begin
    rst_n = 1'b0;
    enb = 1'b0;
    litCode = 8'd0;
    len_in = 4'd0;
    litTree = 116'd0;

    repeat (2) @(posedge clk);
    #1;
    $display("INITIAL RESET: fin_lit=%b litSymb=%0d litCount=%0d",
             fin_lit, litSymb, litCount);
    @(negedge clk);
    rst_n = 1'b1;

    // Test Case 1: lengths 1, 2, 3, 6, and 8.
    litTree = 116'd0;
    for (i = 0; i < 29; i = i + 1) begin
        litTree[i*4 +: 4] = 4'd8;
        #1;
    end
    litTree[0*4 +: 4] = 4'd1;
    litTree[1*4 +: 4] = 4'd2;
    litTree[2*4 +: 4] = 4'd3;
    litTree[3*4 +: 4] = 4'd6;
    litTree[4*4 +: 4] = 4'd6;

    reset_dut;
    start_and_complete;

    observe_lookup(8'd0, 4'd1);
    observe_lookup(8'd1, 4'd2);
    observe_lookup(8'd2, 4'd3);
    observe_lookup(8'd56, 4'd6);
    observe_lookup(8'd57, 4'd8);
    observe_lookup(8'd255, 4'd0);

    for (j = 0; j < 16; j = j + 1) begin
        observe_lookup(8'd0, j[3:0]);
        #1;
    end

    @(negedge clk);
    enb = 1'b1;
    repeat (3) @(posedge clk);
    #1;
    $display("TERMINAL ENABLE HIGH: fin_lit=%b litSymb=%0d litCount=%0d",
             fin_lit, litSymb, litCount);
    @(negedge clk);
    enb = 1'b0;
    #1;
    $display("TERMINAL HOLD: fin_lit=%b litSymb=%0d litCount=%0d",
             fin_lit, litSymb, litCount);

    // Test Case 2: lengths 4, 5, 7, and 8.
    litTree = 116'd0;
    for (i = 0; i < 29; i = i + 1) begin
        litTree[i*4 +: 4] = 4'd8;
        #1;
    end
    litTree[0*4 +: 4] = 4'd4;
    litTree[1*4 +: 4] = 4'd5;
    litTree[2*4 +: 4] = 4'd7;

    reset_dut;
    start_and_complete;

    observe_lookup(8'd0, 4'd4);
    observe_lookup(8'd2, 4'd5);
    observe_lookup(8'd24, 4'd7);
    observe_lookup(8'd50, 4'd8);
    observe_lookup(8'd200, 4'd0);

    for (j = 0; j < 16; j = j + 1) begin
        observe_lookup(8'd50, j[3:0]);
        #1;
    end

    // Test Case 3: synchronous reset from each active scan state.
    // Reuse the second tree and use only fixed clock-cycle waits.
    for (target_length = 1; target_length <= 8;
         target_length = target_length + 1) begin
        interrupt_scan(target_length);
        #1;
    end

    // Test Case 4: complete construction after interrupted builds.
    // The final interrupt_scan returned the DUT to idle.
    start_and_complete;

    observe_lookup(8'd0, 4'd4);
    observe_lookup(8'd2, 4'd5);
    observe_lookup(8'd24, 4'd7);
    observe_lookup(8'd50, 4'd8);

    for (j = 0; j < 16; j = j + 1) begin
        observe_lookup(8'd50, j[3:0]);
        #1;
    end

    $display("===========End===========");
    $finish;
end

