module testbench;

// Inputs
reg clk;
reg rst, gamestart, shot_reimu, shot_enm, shot_boss;
reg [6:0] enmhp1, enmhp2, enmhp3, enmhp4;
reg [9:0] bosshp;

// Outputs
wire [3:0] score0, score1, score2, score3;

integer i, j;
reg [4:0] clear_control;
reg [1:0] shot_control;
reg small_health;

score uut (
    .rst(rst),
    .clk22(clk),
    .shot_reimu(shot_reimu),
    .shot_enm(shot_enm),
    .shot_boss(shot_boss),
    .gamestart(gamestart),
    .enmhp1(enmhp1),
    .enmhp2(enmhp2),
    .enmhp3(enmhp3),
    .enmhp4(enmhp4),
    .bosshp(bosshp),
    .score0(score0),
    .score1(score1),
    .score2(score2),
    .score3(score3)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [8*64-1:0] label;
    begin
        $display("%0t %0s ctrl=%b dead=%b score0=%0d score1=%0d score2=%0d score3=%0d",
                 $time, label,
                 {rst, gamestart, shot_reimu, shot_enm, shot_boss},
                 {bosshp == 0, enmhp4 == 0, enmhp3 == 0,
                  enmhp2 == 0, enmhp1 == 0},
                 score0, score1, score2, score3);
    end
endtask

// Control order: reset, new game, player hit, enemy shot, boss shot.
// Dead-mask order: boss, enemy 4, enemy 3, enemy 2, enemy 1.
task cycle;
    input [8*64-1:0] label;
    input [4:0] control;
    input [4:0] dead;
    begin
        @(negedge clk);
        {rst, gamestart, shot_reimu, shot_enm, shot_boss} = control;
        enmhp1 = dead[0] ? 7'd0 : (small_health ? 7'd1 : 7'd127);
        enmhp2 = dead[1] ? 7'd0 : (small_health ? 7'd1 : 7'd127);
        enmhp3 = dead[2] ? 7'd0 : (small_health ? 7'd1 : 7'd127);
        enmhp4 = dead[3] ? 7'd0 : (small_health ? 7'd1 : 7'd127);
        bosshp = dead[4] ? 10'd0 : (small_health ? 10'd1 : 10'd1023);
        @(posedge clk);
        #1;
        observe(label);
    end
endtask

task clean;
    begin
        cycle("initialize: reset", 5'b10000, 5'b00000);
        cycle("initialize: release", 5'b00000, 5'b00000);
    end
endtask

initial begin
    rst = 1;
    gamestart = 0;
    shot_reimu = 0;
    shot_enm = 0;
    shot_boss = 0;
    enmhp1 = 127;
    enmhp2 = 127;
    enmhp3 = 127;
    enmhp4 = 127;
    bosshp = 1023;
    small_health = 0;
    clear_control = 0;
    shot_control = 0;

    // Wait 100 ns for global reset to finish.
    #100;
    observe("startup reset");

    // Reset/new-game priority, synchronous timing, and history clearing.
    for (j = 0; j < 3; j = j + 1) begin
        clean;
        for (i = 0; i < 12; i = i + 1) begin
            cycle("clear setup: shot and defeated health", 5'b00011, 5'b11111);
            cycle("clear setup: normalize", 5'b00000, 5'b11111);
            #1;
        end
        case (j)
            0: clear_control = 5'b10011;
            1: clear_control = 5'b01011;
            2: clear_control = 5'b11011;
        endcase
        @(negedge clk);
        {rst, gamestart, shot_reimu, shot_enm, shot_boss} = clear_control;
        #1;
        observe("clear asserted before rising edge");
        @(posedge clk);
        #1;
        observe("clear sampled on rising edge");
        cycle("clear held", clear_control, 5'b11111);
        cycle("clear released with health still zero", 5'b00000, 5'b11111);
        cycle("zero-health history retained", 5'b00000, 5'b11111);
        #1;
    end

    // Each shot source and their OR combination; sustained input boundaries.
    for (j = 1; j <= 3; j = j + 1) begin
        clean;
        shot_control = j;
        cycle("isolated shot", {3'b000, shot_control}, 5'b00000);
        cycle("isolated shot: idle", 5'b00000, 5'b00000);
        cycle("isolated shot: hold", 5'b00000, 5'b00000);
        clean;
        for (i = 0; i < 32; i = i + 1) begin
            cycle("sustained shots", {3'b000, shot_control}, 5'b00000);
            #1;
        end
        for (i = 0; i < 4; i = i + 1) begin
            cycle("sustained shots: carry settling", 5'b00000, 5'b00000);
            #1;
        end
        #1;
    end

    // Individual defeats, zero retention, and rearming at nonzero boundaries.
    for (j = 0; j < 5; j = j + 1) begin
        small_health = 0;
        clean;
        cycle("individual defeat", 5'b00000, 5'b00001 << j);
        cycle("individual defeat held", 5'b00000, 5'b00001 << j);
        small_health = 1;
        cycle("rearm at minimum nonzero health", 5'b00000, 5'b00000);
        cycle("individual defeat repeated", 5'b00000, 5'b00001 << j);
        small_health = 0;
        cycle("rearm at maximum nonzero health", 5'b00000, 5'b00000);
        cycle("individual defeat repeated again", 5'b00000, 5'b00001 << j);
        #1;
    end
    clean;
    cycle("all defeats and both shots together", 5'b00011, 5'b11111);
    cycle("all defeated health held", 5'b00000, 5'b11111);
    cycle("all health rearmed", 5'b00000, 5'b00000);
    cycle("all defeats repeated", 5'b00000, 5'b11111);

    // Player hit preserves history and consumes coincident new defeats.
    clean;
    cycle("hit setup: all defeats", 5'b00011, 5'b11111);
    cycle("hit overrides both shots", 5'b00111, 5'b11111);
    cycle("hit held", 5'b00111, 5'b11111);
    cycle("hit release preserves defeated history", 5'b00000, 5'b11111);
    cycle("post-hit rearm", 5'b00000, 5'b00000);
    cycle("post-hit defeats score again", 5'b00000, 5'b11111);

    clean;
    for (i = 0; i < 10; i = i + 1) begin
        cycle("hit setup: pending units carry", 5'b00010, 5'b00000);
        #1;
    end
    cycle("hit overrides carry, shots, and new defeats", 5'b00111, 5'b11111);
    cycle("hit release: new defeats already recorded", 5'b00000, 5'b11111);
    cycle("hit release: idle retention", 5'b00000, 5'b11111);

    // Isolated shots exercise decimal carries; final tens carry meets defeats.
    clean;
    for (i = 0; i < 100; i = i + 1) begin
        cycle("decimal sequence: shot", 5'b00010, 5'b00000);
        cycle("decimal sequence: units normalization", 5'b00000, 5'b00000);
        #1;
    end
    cycle("tens carry and all normal defeats", 5'b00000, 5'b01111);
    cycle("tens carry: settle", 5'b00000, 5'b01111);

    // Hundreds boundary, with and without a coincident boss defeat.
    for (j = 0; j < 2; j = j + 1) begin
        clean;
        for (i = 0; i < 10; i = i + 1) begin
            cycle("hundreds sequence: enemy defeat", 5'b00000, 5'b00001);
            cycle("hundreds normalization / boss merge",
                  5'b00000, (j << 4));
            #1;
        end
        cycle("hundreds sequence: settle", 5'b00000, 5'b00000);
        #1;
    end

    // Boss awards cross the thousands boundary and expose the later clamp.
    clean;
    for (i = 0; i < 11; i = i + 1) begin
        cycle("thousands sequence: boss defeat", 5'b00000, 5'b10000);
        cycle("thousands sequence: rearm and clamp", 5'b00000, 5'b00000);
        #1;
    end

    // Consecutive enemy awards defer hundreds normalization.
    // Starting at nine thousands also exposes upper-digit overflow priority.
    clean;
    for (i = 0; i < 9; i = i + 1) begin
        cycle("upper-priority setup: boss defeat", 5'b00000, 5'b10000);
        cycle("upper-priority setup: boss rearm", 5'b00000, 5'b00000);
        #1;
    end
    for (i = 0; i < 18; i = i + 1) begin
        cycle("alternating new enemy defeats",
              5'b00000, (i % 2) ? 5'b00010 : 5'b00001);
        #1;
    end
    for (i = 0; i < 4; i = i + 1) begin
        cycle("upper-priority sequence: settle", 5'b00000, 5'b00000);
        #1;
    end

    $display("===========End===========");
    $finish;
end

endmodule

