module testbench;

// Inputs
reg clk;
reg reset;
reg boton_u, boton_d, cambiar_fecha;
reg [7:0] dias, mes, year;
reg [1:0] pos_x;

// Outputs
wire [7:0] dias_out, mes_out, year_out;

integer field, decade, limit, buttons, variant;
reg [7:0] first_value, last_value;

contador_fecha uut (
    .clk(clk),
    .reset(reset),
    .boton_u(boton_u),
    .boton_d(boton_d),
    .cambiar_fecha(cambiar_fecha),
    .dias(dias),
    .mes(mes),
    .year(year),
    .pos_x(pos_x),
    .dias_out(dias_out),
    .mes_out(mes_out),
    .year_out(year_out)
);

initial clk = 0; //clk is initialized as 0
always #5 clk = ~clk;

task observe;
    input [8*48-1:0] label;
    begin
        $display(
            "%0t %0s reset=%b edit=%b pos=%0d u=%b d=%b inputs=%h/%h/%h dias_out=%h mes_out=%h year_out=%h",
            $time, label, reset, cambiar_fecha, pos_x,
            boton_u, boton_d, dias, mes, year,
            dias_out, mes_out, year_out
        );
    end
endtask

task sample_cycles;
    input integer count;
    input [8*48-1:0] label;
    integer cycle;
    begin
        for (cycle = 0; cycle < count; cycle = cycle + 1) begin
            @(posedge clk);
            #1;
            observe(label);
        end
    end
endtask

task reset_clean;
    begin
        @(negedge clk);
        cambiar_fecha = 1;
        boton_u = 0;
        boton_d = 0;
        #2 reset = 1;
        #1;
        observe("asynchronous reset");
        sample_cycles(2, "reset held");
        @(negedge clk);
        reset = 0;
        sample_cycles(2, "reset released / no button event");
    end
endtask

task load_date;
    input [7:0] day_value, month_value, year_value;
    begin
        reset_clean;
        @(negedge clk);
        dias = day_value;
        mes = month_value;
        year = year_value;
        cambiar_fecha = 0;
        sample_cycles(1, "external date loaded");
        @(negedge clk);
        cambiar_fecha = 1;
    end
endtask

task seed_field;
    input integer selected_field;
    input [7:0] value;
    begin
        case (selected_field)
            0: load_date(value, 8'h02, 8'h23);
            1: load_date(8'h28, value, 8'h24);
            2: load_date(8'h28, 8'h02, value);
        endcase
        pos_x = selected_field;
    end
endtask

task edit_trial;
    input integer selected_field;
    input [7:0] value;
    input [1:0] button_mask;
    begin
        seed_field(selected_field, value);
        boton_u = button_mask[0];
        boton_d = button_mask[1];
        sample_cycles(3, "buttons held");
        @(negedge clk);
        boton_u = 0;
        boton_d = 0;
        // Twelve edges include the longest legal down-wrap sequence
        // and an additional edge after its decade correction.
        if (button_mask[1])
            sample_cycles(12, "release / pending-event follow-through");
        else
            sample_cycles(2, "up release / subsequent idle");
    end
endtask

initial begin
    reset = 0;
    boton_u = 0;
    boton_d = 0;
    cambiar_fecha = 0;
    dias = 8'h01;
    mes = 8'h01;
    year = 8'h00;
    pos_x = 0;

    // Wait 100 ns for global reset to finish.
    #100;

    // Reset, consecutive loads, and unvalidated external values.
    load_date(8'h31, 8'h02, 8'h00);
    sample_cycles(2, "editing idle / February day retained");
    @(negedge clk);
    cambiar_fecha = 0;
    dias = 8'h00;
    mes = 8'h13;
    year = 8'hFA;
    sample_cycles(1, "unvalidated external load");
    @(negedge clk);
    dias = 8'hA5;
    mes = 8'h00;
    year = 8'hFF;
    sample_cycles(1, "next-edge external replacement");
    @(negedge clk);
    cambiar_fecha = 1;
    dias = 8'h12;
    mes = 8'h12;
    year = 8'h12;
    sample_cycles(2, "external changes ignored while editing");

    // Arithmetic, all decade boundaries, wraps, and simultaneous release.
    for (field = 0; field < 3; field = field + 1) begin
        #1;
        case (field)
            0: begin
                first_value = 8'h01;
                last_value = 8'h31;
                limit = 3;
            end
            1: begin
                first_value = 8'h01;
                last_value = 8'h12;
                limit = 1;
            end
            2: begin
                first_value = 8'h00;
                last_value = 8'h99;
                limit = 9;
            end
        endcase

        edit_trial(field, 8'h02, 2'b01);
        edit_trial(field, 8'h02, 2'b10);
        edit_trial(field, last_value, 2'b01);
        edit_trial(field, first_value, 2'b10);

        for (decade = 1; decade <= limit; decade = decade + 1) begin
            #1;
            edit_trial(field, (decade - 1) * 16 + 9, 2'b01);
            edit_trial(field, decade * 16, 2'b10);
        end

        edit_trial(field, 8'h09, 2'b11);
        edit_trial(field, last_value, 2'b11);

        // Down release while up remains held: correction versus ordinary.
        for (variant = 0; variant < 2; variant = variant + 1) begin
            #1;
            seed_field(field, 8'h10 + variant * 2);
            boton_u = 1;
            boton_d = 1;
            sample_cycles(2, "both buttons held");
            @(negedge clk);
            boton_d = 0;
            sample_cycles(1, "down released / up still held");
            @(negedge clk);
            boton_u = 0;
            sample_cycles(12, "later up release / pending down");
        end
    end

    // Repeat mode/selector/reset tests for up, down, and both buttons.
    for (buttons = 1; buttons <= 3; buttons = buttons + 1) begin
        #1;

        load_date(8'h15, 8'h06, 8'h20);
        pos_x = 0;
        boton_u = buttons & 1;
        boton_d = (buttons >> 1) & 1;
        sample_cycles(2, "press with day selected");
        @(negedge clk);
        pos_x = 3;
        boton_u = 0;
        boton_d = 0;
        sample_cycles(3, "release with unsupported selector");
        @(negedge clk);
        pos_x = 2;
        sample_cycles(12, "pending event processed on year");

        load_date(8'h15, 8'h06, 8'h20);
        pos_x = 0;
        boton_u = buttons & 1;
        boton_d = (buttons >> 1) & 1;
        sample_cycles(1, "arm before entering loading mode");
        @(negedge clk);
        cambiar_fecha = 0;
        boton_u = 0;
        boton_d = 0;
        dias = 8'h21;
        mes = 8'h10;
        year = 8'h40;
        sample_cycles(2, "release during loading / pending retained");
        @(negedge clk);
        cambiar_fecha = 1;
        pos_x = 1;
        sample_cycles(12, "pending event resumes on month");

        load_date(8'h15, 8'h06, 8'h20);
        @(negedge clk);
        cambiar_fecha = 0;
        boton_u = buttons & 1;
        boton_d = (buttons >> 1) & 1;
        sample_cycles(2, "button high entirely in loading mode");
        @(negedge clk);
        boton_u = 0;
        boton_d = 0;
        sample_cycles(1, "button low in loading mode");
        @(negedge clk);
        cambiar_fecha = 1;
        pos_x = 0;
        sample_cycles(2, "editing after loading-only button activity");

        load_date(8'h15, 8'h06, 8'h20);
        pos_x = 3;
        boton_u = buttons & 1;
        boton_d = (buttons >> 1) & 1;
        sample_cycles(1, "arm with unsupported selector");
        @(negedge clk);
        boton_u = 0;
        boton_d = 0;
        sample_cycles(1, "pending release before reset");
        reset_clean;
        @(negedge clk);
        pos_x = 0;
        sample_cycles(3, "supported selector after pending-event reset");
    end

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

reg clk;
reg rst;
reg mode;
reg update;
reg timeout2sec;
reg [3:0] rain;

wire reqlfsr;
wire req2sec;
wire allowgt;
wire [3:0] raout1;
wire [3:0] raout2;
wire [3:0] raout3;
wire [3:0] raout4;
wire [3:0] raout5;
wire segen;

gamecontroller uut (
    .clk(clk),
    .rst(rst),
    .mode(mode),
    .update(update),
    .timeout2sec(timeout2sec),
    .rain(rain),
    .reqlfsr(reqlfsr),
    .req2sec(req2sec),
    .allowgt(allowgt),
    .raout1(raout1),
    .raout2(raout2),
    .raout3(raout3),
    .raout4(raout4),
    .raout5(raout5),
    .segen(segen)
);

initial clk = 0;
always #5 clk = ~clk;

task tick_observe;
    input integer tag;
    begin
        @(posedge clk);
        #1;
        $display("T%0d reqlfsr=%b req2sec=%b allowgt=%b raout1=%h raout2=%h raout3=%h raout4=%h raout5=%h segen=%b",
                 tag, reqlfsr, req2sec, allowgt, raout1, raout2, raout3, raout4, raout5, segen);
    end
endtask

task normal_stage;
    input integer tag;
    input [3:0] first_rain;
    input [3:0] final_rain;
    begin
        timeout2sec = 0;
        tick_observe(tag);
        tick_observe(tag + 1);

        rain = first_rain;
        timeout2sec = 0;
        tick_observe(tag + 2);

        rain = final_rain;
        timeout2sec = 1;
        tick_observe(tag + 3);

        timeout2sec = 0;
    end
endtask

task immediate_stage;
    input integer tag;
    input [3:0] stage_rain;
    begin
        timeout2sec = 1;
        tick_observe(tag);
        tick_observe(tag + 1);

        rain = stage_rain;
        tick_observe(tag + 2);

        timeout2sec = 0;
    end
endtask

// Reset the DUT while it is in a selected request, load, or wait state.
// phase 0: requestN
// phase 1: loadN
// phase 2: waitcN
// phase 3: stop after completing stage N
task reset_in_round_state;
    input integer tag;
    input integer stage;
    input integer phase;
    integer i;
    begin
        // Establish a known initialized starting point.
        rst = 0;
        tick_observe(tag);
        rst = 1;
        mode = 0;
        timeout2sec = 0;
        tick_observe(tag + 1);

        // Enter start and accept a new round.
        mode = 1;
        tick_observe(tag + 2);
        mode = 0;
        update = 1;
        tick_observe(tag + 3);
        update = 0;

        // Advance preceding stages with immediate timeout.
        timeout2sec = 1;
        for (i = 1; i < stage; i = i + 1) begin
            tick_observe(tag + 4 + (i - 1) * 3);
            tick_observe(tag + 5 + (i - 1) * 3);
            tick_observe(tag + 6 + (i - 1) * 3);
        end

        // The DUT is now in requestN.
        if (phase == 0) begin
            rst = 0;
            tick_observe(tag + 30);
        end
        else if (phase == 1) begin
            tick_observe(tag + 30);
            rst = 0;
            tick_observe(tag + 31);
        end
        else if (phase == 2) begin
            tick_observe(tag + 30);
            tick_observe(tag + 31);
            rst = 0;
            tick_observe(tag + 32);
        end
        else begin
            // Complete the selected stage so that stage five reaches stop.
            tick_observe(tag + 30);
            tick_observe(tag + 31);
            tick_observe(tag + 32);
            rst = 0;
            tick_observe(tag + 33);
        end

        // Release reset and execute init once to clear outputs.
        rst = 1;
        timeout2sec = 0;
        mode = 0;
        tick_observe(tag + 34);
    end
endtask

// Reset while the controller is waiting in start.
task reset_from_start;
    input integer tag;
    begin
        rst = 0;
        tick_observe(tag);
        rst = 1;
        mode = 0;
        timeout2sec = 0;
        tick_observe(tag + 1);

        mode = 1;
        tick_observe(tag + 2);
        mode = 0;

        rst = 0;
        tick_observe(tag + 3);

        rst = 1;
        tick_observe(tag + 4);
    end
endtask

initial begin
    rst = 0;
    mode = 0;
    update = 0;
    timeout2sec = 0;
    rain = 0;

    // Initial reset and initialization with mode low.
    tick_observe(1);
    rst = 1;
    tick_observe(2);

    // Enter start and exercise the update-wait branch.
    mode = 1;
    tick_observe(3);
    mode = 0;
    tick_observe(4);

    // Begin a round, then reset while request1 is active.
    update = 1;
    tick_observe(5);
    update = 0;
    tick_observe(6);

    rst = 0;
    tick_observe(7);
    rst = 1;
    tick_observe(8);

    // Re-enter start and run a normal five-stage round.
    mode = 1;
    tick_observe(9);
    mode = 0;
    update = 1;
    tick_observe(10);
    update = 0;

    normal_stage(11, 4'h1, 4'h2);
    normal_stage(15, 4'h3, 4'h4);
    normal_stage(19, 4'h5, 4'h6);
    normal_stage(23, 4'h7, 4'h8);
    normal_stage(27, 4'h9, 4'ha);

    // Execute stop, then accept another update after completion.
    tick_observe(31);
    update = 1;
    tick_observe(32);
    update = 0;

    // Reset before the immediate-timeout round.
    rst = 0;
    tick_observe(33);
    rst = 1;
    mode = 0;
    tick_observe(34);
    mode = 1;
    tick_observe(35);
    mode = 0;

    // Run all five stages with timeout already asserted.
    update = 1;
    tick_observe(36);
    update = 0;

    immediate_stage(37, 4'hb);
    immediate_stage(40, 4'hc);
    immediate_stage(43, 4'hd);
    immediate_stage(46, 4'he);
    immediate_stage(49, 4'hf);

    // Complete the round and accept the next update.
    tick_observe(52);
    update = 1;
    tick_observe(53);
    update = 0;

    // Additional directed reset coverage for the start state.
    reset_from_start(60);

    // Reset from every request state.
    reset_in_round_state(70, 1, 0);
    reset_in_round_state(80, 2, 0);
    reset_in_round_state(90, 3, 0);
    reset_in_round_state(100, 4, 0);
    reset_in_round_state(110, 5, 0);

    // Reset from every load state.
    reset_in_round_state(120, 1, 1);
    reset_in_round_state(130, 2, 1);
    reset_in_round_state(140, 3, 1);
    reset_in_round_state(150, 4, 1);
    reset_in_round_state(160, 5, 1);

    // Reset from every wait state.
    reset_in_round_state(170, 1, 2);
    reset_in_round_state(180, 2, 2);
    reset_in_round_state(190, 3, 2);
    reset_in_round_state(200, 4, 2);
    reset_in_round_state(210, 5, 2);

    // Complete stage five to enter stop, then reset from stop.
    reset_in_round_state(220, 5, 3);

    $display("===========End===========");
    $finish;
end

endmodule

