module testbench;

localparam integer POINT = 20000;
localparam integer CYCLES = POINT + 2;

// Inputs
reg clk;
reg rst;
reg en_Interrupt;
reg [31:0] data_in;

// Outputs
wire Interrupt;
wire [2:0] mode;
wire [31:0] addr;
wire [15:0] L01, L11, L21, L31, L41, L51, L61, L71;
wire [15:0] L81, L91, La1, Lb1, Lc1, Ld1, Le1, Lf1;

integer frame;

LED_Ctrl #(.cycles(CYCLES)) uut (
    .clk_cpu(clk), .rst(rst), .en_Interrupt(en_Interrupt),
    .data_in(data_in), .Interrupt(Interrupt), .mode(mode),
    .addr(addr),
    .L01(L01), .L11(L11), .L21(L21), .L31(L31),
    .L41(L41), .L51(L51), .L61(L61), .L71(L71),
    .L81(L81), .L91(L91), .La1(La1), .Lb1(Lb1),
    .Lc1(Lc1), .Ld1(Ld1), .Le1(Le1), .Lf1(Lf1)
);

initial clk = 0; //clk is initialized as 0
always #5 clk = ~clk;

task observe;
    input [8*40-1:0] label;
    begin
        $display(
            "%0t %0s frame=%0d rst=%b en=%b data_in=%h Interrupt=%b mode=%b addr=%h L01=%h L11=%h L21=%h L31=%h L41=%h L51=%h L61=%h L71=%h L81=%h L91=%h La1=%h Lb1=%h Lc1=%h Ld1=%h Le1=%h Lf1=%h",
            $time, label, frame, rst, en_Interrupt, data_in,
            Interrupt, mode, addr,
            L01, L11, L21, L31, L41, L51, L61, L71,
            L81, L91, La1, Lb1, Lc1, Ld1, Le1, Lf1
        );
    end
endtask

task advance;
    input integer clocks;
    begin
        repeat (clocks) @(posedge clk);
        #1;
    end
endtask

task reset_dut;
    begin
        @(negedge clk);
        #2 rst = 1;
        #1 observe("asynchronous reset");
        advance(2);
        observe("reset held");
        @(negedge clk);
        rst = 0;
        #1 observe("reset released");
    end
endtask

// Entry and exit are after a falling edge, before the next capture.
task acquire;
    input integer entries;
    input integer pattern;
    integer i;
    begin
        for (i = 0; i < entries; i = i + 1) begin
            case (pattern)
                0: data_in = i;
                1: data_in = 32'hfffffff0 | i;
                2: data_in = 32'ha5a5a5a0 | (15 - i);
                default: data_in = 32'h12345678;
            endcase
            #1 observe("acquisition before capture");
            @(posedge clk);
            #1 observe("acquisition after capture");
            @(negedge clk);
            #1;
        end
    end
endtask

initial begin
    // Initialize inputs; allow 100 ns for global reset.
    rst = 1;
    en_Interrupt = 0;
    data_in = 0;
    frame = -1;
    #100;
    observe("initial reset");

    // Interrupt an acquisition, then restart from reset.
    reset_dut;
    acquire(8, 3);
    reset_dut;

    // Consecutive periods deliberately preserve the published bank.
    for (frame = 0; frame < 3; frame = frame + 1) begin
        en_Interrupt = (frame != 2);
        acquire(16, frame);

        // Unaddressed data changes must not replace acquired entries.
        data_in = 32'hdeadbeef;
        #1 observe("outside acquisition");
        advance(POINT - 17);
        observe("immediately before refresh");

        advance(1);
        observe("refresh interval");

        if (frame == 0) begin
            en_Interrupt = 0;
            #1 observe("refresh interrupt disabled");
            en_Interrupt = 1;
            #1 observe("refresh interrupt reenabled");
        end

        // Sample after the edge that publishes the collected bank.
        advance(1);
        observe("after publication edge");

        @(negedge clk);
        en_Interrupt = 1;
        data_in = 32'h01234567;
        #1 observe("enable outside refresh");

        advance(CYCLES - POINT - 1);
        observe("terminal count");
        advance(1);
        observe("counter wrapped");

        @(negedge clk);
        #1;
    end

    // Reset between edges while the enabled interrupt is active.
    data_in = 32'hcafebabe;
    en_Interrupt = 1;
    advance(POINT);
    observe("active interrupt before reset");
    reset_dut;
    acquire(1, 0);

    $display("===========End===========");
    $finish;
end

endmodule

