module testbench;

reg         clk;
reg         i_fpga_rst_125p;
reg         i_rd_en;
reg         i_wr_en;
reg         i_mod_sel;
reg [15:0]  i_addr;
reg [31:0]  i_data;
reg         i_ad80305_do;

wire [7:0]  o_rw_result;
wire [31:0] o_rw_data;
wire        o_ad80305_di;
wire        o_ad80305_clk;
wire        o_ad80305_cs;

integer slot;

localparam integer BIT_CYCLES = 125;

cz_spi_interface uut (
    .i_fpga_clk_125p (clk),
    .i_fpga_rst_125p (i_fpga_rst_125p),
    .i_rd_en         (i_rd_en),
    .i_wr_en         (i_wr_en),
    .i_mod_sel       (i_mod_sel),
    .i_addr          (i_addr),
    .i_data          (i_data),
    .i_ad80305_do    (i_ad80305_do),
    .o_rw_result     (o_rw_result),
    .o_rw_data       (o_rw_data),
    .o_ad80305_di    (o_ad80305_di),
    .o_ad80305_clk   (o_ad80305_clk),
    .o_ad80305_cs    (o_ad80305_cs)
);

/* Preserve the original input-clock period. */
initial clk = 1'b0;
always #5 clk = ~clk;

/* Display actual outputs only; no scoreboard or pass/fail judgments. */
task show_outputs;
    input [255:0] label;
begin
    $display("%0s: time=%0t result=%h data=%h di=%b clk=%b cs=%b",
             label, $time, o_rw_result, o_rw_data,
             o_ad80305_di, o_ad80305_clk, o_ad80305_cs);
end
endtask

task reset_dut;
begin
    i_rd_en         = 1'b0;
    i_wr_en         = 1'b0;
    i_mod_sel       = 1'b0;
    i_addr          = 16'd0;
    i_data          = 32'd0;
    i_ad80305_do    = 1'b0;
    i_fpga_rst_125p = 1'b0;

    /* Observe asynchronous reset before the next rising clock edge. */
    #1;
    show_outputs("RESET_ASSERTED");

    /* The two-stage request samplers have no reset. */
    repeat (4) @(posedge clk);
    @(negedge clk);
    i_fpga_rst_125p = 1'b1;

    repeat (4) @(posedge clk);
    #1;
    show_outputs("RESET_RELEASED");
end
endtask

/* Drive request transitions away from the DUT sampling edge. */
task start_write;
begin
    @(negedge clk);
    i_wr_en = 1'b1;
    repeat (3) @(posedge clk);
    @(negedge clk);
    i_wr_en = 1'b0;
end
endtask

task start_read;
begin
    @(negedge clk);
    i_rd_en = 1'b1;
    repeat (3) @(posedge clk);
    @(negedge clk);
    i_rd_en = 1'b0;
end
endtask

/*
 * Reset a naturally reached phase using only top-level stimulus.
 *
 * Number rising input-clock edges after request assertion as P1, P2, ...
 * The three-cycle request task returns at the falling edge after P3.
 * With the supplied RTL and default parameters:
 *   P4: controller enters start
 *   P6: controller enters the first command phase
 *
 * bit_slot = -1 targets start at P4 + 1 ns.
 * bit_slot >= 0 targets P70 + 125*bit_slot + 1 ns.
 * For clocked phases, this is inside the serial-clock high interval.
 *
 * Write slots:
 *   0..17  command/address
 *   18..49 write data
 *   50     stop
 *
 * Module-select-zero read slots:
 *   18..21 dummy periods
 *   22..53 read data
 *
 * These are fixed protocol delays, not a replicated state machine.
 */
task interrupt_transaction;
    input integer read_transfer;
    input integer bit_slot;
    integer delay_cycles;
begin
    @(negedge clk);
    i_mod_sel    = 1'b0;
    i_addr       = 16'hA55A;
    i_data       = 32'hFFFF_FFFF;
    i_ad80305_do = 1'b1;

    if (read_transfer != 0)
        start_read;
    else
        start_write;

    if (bit_slot < 0)
        delay_cycles = 1;
    else
        delay_cycles = 67 + BIT_CYCLES * bit_slot;

    repeat (delay_cycles) @(posedge clk);
    #1;

    $display("BEFORE_RESET: read=%0d slot=%0d time=%0t "
             , read_transfer, bit_slot, $time);
    show_outputs("INTERRUPTED_TRANSFER");

    /* Assertion occurs off the input-clock edge. */
    reset_dut;
end
endtask

initial begin
    i_fpga_rst_125p = 1'b1;
    i_rd_en        = 1'b0;
    i_wr_en        = 1'b0;
    i_mod_sel      = 1'b0;
    i_addr         = 16'd0;
    i_data         = 32'd0;
    i_ad80305_do   = 1'b0;

    /* Create an explicit reset assertion edge at initialization. */
    #2;
    reset_dut;

    // Original Test Case 1: write transaction.
    reset_dut;
    i_mod_sel = 1'b1;
    i_addr    = 16'hA55A;
    i_data    = 32'h5AA5_3CC3;
    start_write;
    repeat (7000) @(posedge clk);
    #1;
    show_outputs("WRITE");

    // Original Test Case 2: read with no dummy phases.
    reset_dut;
    i_mod_sel    = 1'b1;
    i_addr       = 16'h0000;
    i_ad80305_do = 1'b1;
    start_read;
    repeat (7000) @(posedge clk);
    #1;
    show_outputs("READ_MOD1");

    repeat (4) @(posedge clk);
    #1;
    show_outputs("READ_MOD1_IDLE");

    // Additional write without reset: observe retained read data.
    @(negedge clk);
    i_mod_sel = 1'b0;
    i_addr    = 16'h5AA5;
    i_data    = 32'hA55A_C33C;
    start_write;
    repeat (7000) @(posedge clk);
    #1;
    show_outputs("WRITE_AFTER_READ");

    // Additional read without reset: replace the retained read word.
    @(negedge clk);
    i_mod_sel    = 1'b0;
    i_addr       = 16'hFFFF;
    i_ad80305_do = 1'b0;
    start_read;
    repeat (7500) @(posedge clk);
    #1;
    show_outputs("READ_ZERO_WITHOUT_RESET");

    // Original Test Case 3: read with four dummy phases.
    reset_dut;
    i_mod_sel    = 1'b0;
    i_addr       = 16'hFFFF;
    i_ad80305_do = 1'b0;
    start_read;
    repeat (7500) @(posedge clk);
    #1;
    show_outputs("READ_MOD0");

    repeat (4) @(posedge clk);
    #1;
    show_outputs("READ_MOD0_IDLE");

    /*
     * Start, all command/address and write-data phases, and stop.
     * Each iteration starts a fresh transaction and then resets it.
     */
    for (slot = -1; slot <= 50; slot = slot + 1) begin
        @(negedge clk);
        interrupt_transaction(0, slot);
    end

    /*
     * All four dummy phases and all 32 read-data phases.
     * Shared command/address reset transitions were exercised above.
     */
    for (slot = 18; slot <= 53; slot = slot + 1) begin
        @(negedge clk);
        interrupt_transaction(1, slot);
    end

    // Complete transactions after the interruption sweeps.
    @(negedge clk);
    i_mod_sel = 1'b1;
    i_addr    = 16'h0200;
    i_data    = 32'h8000_0001;
    start_write;
    repeat (7000) @(posedge clk);
    #1;
    show_outputs("RECOVERY_WRITE");

    @(negedge clk);
    i_mod_sel    = 1'b1;
    i_addr       = 16'hFDFF;
    i_ad80305_do = 1'b1;
    start_read;
    repeat (7000) @(posedge clk);
    #1;
    show_outputs("RECOVERY_READ");

    repeat (4) @(posedge clk);
    #1;
    show_outputs("FINAL_IDLE");

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

