// clk toggle generate
initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [8*64-1:0] label;
    begin
        $display("%0s time=%0t rst=%b count=%b",
                 label, $time, rst, count);
    end
endtask

task advance;
    input integer cycles;
    input [8*64-1:0] label;
    integer i;
    begin
        for (i = 0; i < cycles; i = i + 1) begin
            @(posedge clk);
            #1;
            observe(label);
        end
    end
endtask

task reset_case;
    begin
        @(negedge clk);
        rst = 1;
        advance(1, "Case initialization");
        @(negedge clk);
        rst = 0;
        #1;
        observe("Reset released between rising edges");
    end
endtask

initial begin
    // Initialize inputs; allow 100 ns for global reset.
    rst = 1;
    #100;
    observe("Initial reset");
    advance(2, "Reset held");

    // Test Case 1: all increments and repeated wraparound.
    reset_case;
    advance(16, "Counting and wrap");

    // Test Case 2: synchronous reset timing from a nonzero count.
    reset_case;
    advance(3, "Before reset timing tests");

    @(negedge clk);
    rst = 1;
    #1;
    observe("Short reset pulse asserted between rising edges");
    #1;
    rst = 0;
    #1;
    observe("Short reset pulse removed before rising edge");
    advance(1, "Rising edge after short reset pulse");

    @(negedge clk);
    rst = 1;
    #1;
    observe("Reset asserted before sampling edge");
    advance(2, "Reset sampled and held");

    @(negedge clk);
    rst = 0;
    #1;
    observe("Reset deasserted before rising edge");
    advance(2, "Counting resumes after reset");

    // Test Case 3: reset at terminal count, then resume.
    reset_case;
    advance(7, "Counting toward terminal value");
    @(negedge clk);
    rst = 1;
    #1;
    observe("Reset asserted at terminal count");
    advance(1, "Terminal count with reset sampled");

    @(negedge clk);
    rst = 0;
    advance(2, "Counting after terminal-count reset");

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

// Inputs
reg clk;
reg in;
reg [8:0] shift_out;
reg reset;
reg clear;

// Outputs
wire shift;
wire load;
wire [8:0] value;
wire done;

integer test_id;
integer c;
integer r;
integer reset_point;
integer delay_cycles;
reg [8:0] feedback;

Control_RX uut (
    .in(in),
    .shift_out(shift_out),
    .clk(clk),
    .reset(reset),
    .clear(clear),
    .shift(shift),
    .load(load),
    .value(value),
    .done(done)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
begin
    $display("test=%0d t=%0t reset=%b in=%b clear=%b shift_out=%03h shift=%b load=%b value=%03h done=%b",
             test_id, $time, reset, in, clear, shift_out,
             shift, load, value, done);
end
endtask

task clocks;
    input integer count;
    integer k;
begin
    for (k = 0; k < count; k = k + 1) begin
        @(posedge clk);
        #1;
        observe;
    end
end
endtask

task reset_dut;
    input line_level;
begin
    @(negedge clk);
    #2;
    in = line_level;
    clear = 0;
    shift_out = 0;
    reset = 0;
    #1;
    observe;
    clocks(2);
    @(negedge clk);
    reset = 1;
    #1;
    observe;
    clocks(2);
end
endtask

// Returns immediately after the full start interval.
task start_frame;
    input release_start;
begin
    @(negedge clk);
    in = 0;
    clocks(1);
    @(negedge clk);
    in = release_start;
    clocks(16);
end
endtask

// bits[7:0] are data in transmission order; bits[8] is parity.
task receive_intervals;
    input [8:0] bits;
    input [8:0] supplied_feedback;
    integer bit_index;
begin
    for (bit_index = 0; bit_index < 9; bit_index = bit_index + 1) begin
        @(negedge clk);
        in = bits[bit_index];
        shift_out = supplied_feedback;
        #1;
        observe;
        clocks(16);
    end
end
endtask

initial begin
    in = 1;
    shift_out = 0;
    reset = 1;
    clear = 0;
    test_id = 0;
    feedback = 0;
    delay_cycles = 0;

    // Wait 100 ns for global reset to finish.
    #100;

    // Serial levels crossed with feedback boundaries in every interval.
    for (c = 0; c < 8; c = c + 1) begin
        test_id = 10 + c;
        reset_dut(1);
        case (c / 2)
            0: feedback = 9'h000;
            1: feedback = 9'h0ff;
            2: feedback = 9'h100;
            3: feedback = 9'h1ff;
        endcase
        @(negedge clk);
        clear = c[0];
        shift_out = feedback;
        clocks(2);
        start_frame(c[0]);
        receive_intervals({9{c[0]}}, feedback);
        @(negedge clk);
        in = 1;
        clear = 0;
        clocks(3);
    end

    // FINISH restart priority, acknowledgement, and restart from CLEAR.
    for (r = 0; r < 2; r = r + 1) begin
        test_id = 20 + r;
        reset_dut(1);
        start_frame(0);
        receive_intervals(9'h155, 9'h055);
        clocks(3);

        @(negedge clk);
        clear = r[0];
        start_frame(0);
        receive_intervals(9'h0aa, 9'h0aa);

        @(negedge clk);
        in = 1;
        clear = 1;
        clocks(1);
        @(negedge clk);
        clear = 0;
        clocks(3);
        start_frame(0);
        receive_intervals(9'h155, 9'h001);
        @(negedge clk);
        clear = 0;
        clocks(2);
    end

    // Preserve the original six reset-interruption cases.
    // Add seven cases for READ_1->INIT through READ_7->INIT.
    for (reset_point = 0; reset_point < 13;
         reset_point = reset_point + 1) begin
        if (reset_point < 6)
            test_id = 30 + reset_point;
        else
            test_id = 50 + (reset_point - 6);

        reset_dut(1);
        @(negedge clk);
        in = 0;
        clocks(1);
        @(negedge clk);
        in = 1;
        clear = 1;
        shift_out = 9'h155;

        // Timing is measured from entry into START:
        // 16 clocks for START, then 16 clocks per receive interval.
        case (reset_point)
            0: delay_cycles = 5;
            1: delay_cycles = 16 + 7;
            2: delay_cycles = 16 + 8;
            3: delay_cycles = 16 + 8*16 + 7;
            4: delay_cycles = 10*16;
            5: delay_cycles = 10*16 + 1;

            // reset_point 6..12 selects READ_1..READ_7 at phase 7.
            default:
                delay_cycles = 16 + (reset_point - 5)*16 + 7;
        endcase

        clocks(delay_cycles);

        // Assert reset between edges while still in the target state.
        // Observe asynchronous reset behavior and subsequent recovery.
        reset_dut(1);
        start_frame(0);
        receive_intervals(9'h155, 9'h000);
        clocks(2);
    end

    // Reset held and released while the receive line is low.
    test_id = 40;
    reset_dut(0);
    clocks(20);
    reset_dut(1);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam integer BYTE_CYCLES = 12433;

// Inputs
reg clk;
reg rst;
reg start;
reg [31:0] r_data;
reg rstflagz;

// Outputs
wire req_o;
wire zwe;
wire [31:0] r_addr;
wire txen;
wire [7:0] txpcdata;

reg [31:0] words [0:7];
integer case_id;

// Instantiate the Unit Under Test (UUT)
ztopc uut (
    .clk(clk),
    .rst(rst),
    .start(start),
    .r_data(r_data),
    .rstflagz(rstflagz),
    .req_o(req_o),
    .zwe(zwe),
    .r_addr(r_addr),
    .txen(txen),
    .txpcdata(txpcdata)
);

// clk toggle generate
initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [8*28-1:0] phase;
    input integer index;
    begin
        $display("t=%0t case=%0d phase=%0s index=%0d req_o=%b zwe=%b r_addr=%08h txen=%b txpcdata=%02h",
                 $time, case_id, phase, index,
                 req_o, zwe, r_addr, txen, txpcdata);
    end
endtask

task sample_cycles;
    input integer count;
    input [8*28-1:0] phase;
    input integer index;
    begin
        repeat (count) @(posedge clk);
        #1;
        observe(phase, index);
    end
endtask

task reset_dut;
    begin
        @(negedge clk);
        rst = 0;
        start = 1;
        rstflagz = 1;
        r_data = 32'hDEADBEEF;
        #1;
        observe("reset_before_clock", 0);
        sample_cycles(1, "reset_sampled", 0);
        sample_cycles(1, "reset_held", 0);
        @(negedge clk);
        rst = 1;
        start = 0;
        rstflagz = 0;
        r_data = 0;
        sample_cycles(2, "reset_released_idle", 0);
    end
endtask

task begin_read;
    input hold_start;
    begin
        @(negedge clk);
        start = 1;
        rstflagz = 0;
        r_data = 32'hDEADBEEF;
        sample_cycles(1, "start_sampled", 0);
        @(negedge clk);
        start = hold_start;
        sample_cycles(1, "first_request_no_capture", 0);
    end
endtask

task supply_words;
    input integer count;
    input [31:0] data_mask;
    integer w;
    begin
        for (w = 0; w < count; w = w + 1) begin
            @(negedge clk);
            r_data = words[w] ^ data_mask;
            sample_cycles(1, "capture_request", w);
        end
    end
endtask

task acquire;
    input hold_start;
    input terminal_rearm;
    input [31:0] data_mask;
    begin
        begin_read(hold_start);
        supply_words(8, data_mask);
        @(negedge clk);
        rstflagz = terminal_rearm;
        r_data = 32'h13579BDF;
        sample_cycles(1, "terminal_control", 0);
        @(negedge clk);
        rstflagz = 0;
    end
endtask

task observe_transmission;
    integer b;
    begin
        for (b = 0; b < 32; b = b + 1) begin
            @(posedge clk);
            #1;
            observe("byte_start", b);
            sample_cycles(1, "byte_second_clock", b);
            sample_cycles(BYTE_CYCLES - 3, "byte_penultimate_clock", b);
            sample_cycles(1, "byte_final_clock", b);
        end
        sample_cycles(1, "first_inactive_clock", 0);
        sample_cycles(BYTE_CYCLES, "inactive_retention", 0);
    end
endtask

initial begin
    // Initialize Inputs
    rst = 0;
    start = 0;
    r_data = 0;
    rstflagz = 0;
    case_id = 1;

    words[0] = 32'h01234567;
    words[1] = 32'h89ABCDEF;
    words[2] = 32'h00000000;
    words[3] = 32'hFFFFFFFF;
    words[4] = 32'h00FF55AA;
    words[5] = 32'h80017FFE;
    words[6] = 32'h10203040;
    words[7] = 32'hFEDCBA98;

    // Wait 100 ns for global reset to finish
    #100;
    observe("initial_reset", 0);

    // Case 1: Full burst, held start, terminal rearm pulse.
    reset_dut;
    acquire(1'b1, 1'b1, 32'h00000000);
    observe_transmission;

    // Case 2: Guarded start/rearm together, then a fresh burst.
    case_id = 2;
    @(negedge clk);
    start = 1;
    rstflagz = 1;
    sample_cycles(1, "simultaneous_start_rearm", 0);
    @(negedge clk);
    start = 0;
    rstflagz = 0;
    sample_cycles(3, "idle_after_rearm", 0);
    acquire(1'b0, 1'b0, 32'hFFFFFFFF);
    observe_transmission;

    // Case 3: Abort acquisition, restart, then abort transmission.
    case_id = 3;
    reset_dut;
    begin_read(1'b0);
    supply_words(4, 32'h00000000);
    reset_dut;
    acquire(1'b0, 1'b0, 32'h5A5A5A5A);
    sample_cycles(5 * BYTE_CYCLES + 2, "sixth_byte_second_clock", 5);
    reset_dut;
    sample_cycles(BYTE_CYCLES + 1, "idle_after_tx_reset", 0);

    // Case 4: Complete recovery after transmission reset.
    case_id = 4;
    acquire(1'b0, 1'b0, 32'h00000000);
    observe_transmission;

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam integer BLOCK_SIZE = 2048;
localparam integer SHORT_CYCLES = 192;
// Conservative allowance per token, plus post-boundary observation.
localparam integer FULL_CYCLES = 16 * (BLOCK_SIZE + 1) + 32;

// Inputs
reg clk;
reg reset;
reg [7:0] chardata;

// Outputs
wire valid;
wire encode;
wire finish;
wire [3:0] offset;
wire [2:0] match_len;
wire [7:0] char_nxt;

integer test_id;
integer symbol_id;
integer cycle_id;
integer observation_cycles;

LZ77_Encoder uut (
    .clk(clk),
    .reset(reset),
    .chardata(chardata),
    .valid(valid),
    .encode(encode),
    .finish(finish),
    .offset(offset),
    .match_len(match_len),
    .char_nxt(char_nxt)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input integer test_number;
    input integer phase;
    input integer sample_number;
    begin
        $display("t=%0t test=%0d phase=%0d sample=%0d valid=%b encode=%b finish=%b offset=%h match_len=%h char_nxt=%h",
                 $time, test_number, phase, sample_number,
                 valid, encode, finish, offset, match_len, char_nxt);
    end
endtask

task reset_dut;
    input integer test_number;
    begin
        @(negedge clk);
        #2;
        reset = 1;
        chardata = 0;
        #1;
        observe(test_number, 0, 0);
        repeat (2) @(posedge clk);
        #1;
        observe(test_number, 0, 1);
        @(negedge clk);
        reset = 0;
    end
endtask

function [7:0] input_symbol;
    input integer test_number;
    input integer position;
    integer distance;
    reg [3:0] nibble;
    begin
        nibble = 4'hf;

        // Tests 0..6: one-symbol matches; 7..13: two-symbol matches.
        if (test_number < 14) begin
            distance = test_number % 7;
            if (position < 7)
                nibble = position;
            else if (position == 7)
                nibble = 6 - distance;
            else if (position == 8) begin
                if (test_number < 7)
                    nibble = 4'hf;
                else if (distance == 0)
                    nibble = 6;
                else
                    nibble = 7 - distance;
            end
            else if (position == 9)
                nibble = 4'he;
        end
        else begin
            case (test_number)
                // Older candidate fails extension; newer candidate succeeds.
                14: begin
                    case (position)
                        0, 3, 6: nibble = 1;
                        1:       nibble = 2;
                        2:       nibble = 3;
                        4, 7:    nibble = 4;
                        5:       nibble = 5;
                        default: nibble = 4'hf;
                    endcase
                end
                15, 18: nibble = position % 16;
                16:     nibble = 0;
                17: begin
                    case (position)
                        0:       nibble = 1;
                        1:       nibble = 2;
                        default: nibble = 0;
                    endcase
                end
                default: nibble = 0;
            endcase
        end

        input_symbol = {4'h0, nibble};
        if (test_number == 18)
            input_symbol[7:4] = 15 - (position % 16);
    end
endfunction

initial begin
    reset = 1;
    chardata = 0;

    // Wait 100 ns for global reset to finish.
    #100;
    observe(-1, 0, 0);

    // Interrupt a partial capture; the next case starts with a fresh reset.
    @(negedge clk);
    reset = 0;
    for (symbol_id = 0; symbol_id < 11; symbol_id = symbol_id + 1) begin
        @(negedge clk);
        chardata = symbol_id;
        @(posedge clk);
        #1;
        observe(-1, 1, symbol_id);
    end

    // Phase 0: reset; phase 1: capture; phase 2: encoding.
    for (test_id = 0; test_id < 19; test_id = test_id + 1) begin
        reset_dut(test_id);

        // reset_dut returns on a falling edge; drive the first symbol now.
        for (symbol_id = 0; symbol_id < BLOCK_SIZE;
             symbol_id = symbol_id + 1) begin
            chardata = input_symbol(test_id, symbol_id);
            @(posedge clk);
            #1;
            if ((symbol_id == 0) || (symbol_id == BLOCK_SIZE - 2) ||
                (symbol_id == BLOCK_SIZE - 1))
                observe(test_id, 1, symbol_id);
            @(negedge clk);
        end

        chardata = 8'ha5;
        if (test_id < 15)
            observation_cycles = SHORT_CYCLES;
        else
            observation_cycles = FULL_CYCLES;

        for (cycle_id = 0; cycle_id < observation_cycles;
             cycle_id = cycle_id + 1) begin
            @(posedge clk);
            #1;
            observe(test_id, 2, cycle_id);
        end
    end

    reset_dut(19);

    $display("===========End===========");
    $finish;
end

endmodule

