module testbench;

// Inputs
reg clk;
reg [3:0] almost_full;
reg [3:0] empty;
reg [1:0] dest;
reg [3:0] valid;
reg [3:0] state;

// Outputs
wire [3:0] pop;
wire [3:0] push;

// Instantiate the Unit Under Test (UUT)
arbitro_1 uut (
    .clk(clk),
    .almost_full0(almost_full[0]),
    .almost_full1(almost_full[1]),
    .almost_full2(almost_full[2]),
    .almost_full3(almost_full[3]),
    .empty0(empty[0]),
    .empty1(empty[1]),
    .empty2(empty[2]),
    .empty3(empty[3]),
    .dest(dest),
    .valid_0(valid[0]),
    .valid_1(valid[1]),
    .valid_2(valid[2]),
    .valid_3(valid[3]),
    .state(state),
    .pop0(pop[0]),
    .pop1(pop[1]),
    .pop2(pop[2]),
    .pop3(pop[3]),
    .push0(push[0]),
    .push1(push[1]),
    .push2(push[2]),
    .push3(push[3])
);

// clk toggle generate
initial clk = 0; //clk is initialized as 0
always #5 clk = ~clk;

integer testcase;
integer m, d, v, s, mode;

task observe;
begin
    $display("t=%0t case=%0d state=%b empty=%b af=%b dest=%d valid=%b pop0=%b pop1=%b pop2=%b pop3=%b push0=%b push1=%b push2=%b push3=%b",
             $time, testcase, state, empty, almost_full, dest, valid,
             pop[0], pop[1], pop[2], pop[3],
             push[0], push[1], push[2], push[3]);
end
endtask

// Drive away from the active edge and sample settled combinational outputs.
task apply;
    input [3:0] next_state;
    input [3:0] next_empty;
    input [3:0] next_af;
    input [3:0] next_valid;
    input [1:0] next_dest;
begin
    @(negedge clk);
    state = next_state;
    empty = next_empty;
    almost_full = next_af;
    valid = next_valid;
    dest = next_dest;
    #1;
    observe;
end
endtask

// Sample again after each counter update has settled.
task cycles;
    input integer count;
    integer k;
begin
    for (k = 0; k < count; k = k + 1) begin
        @(posedge clk);
        #1;
        observe;
    end
end
endtask

task initialize_case;
begin
    apply(4'b0001, 4'b1111, 4'b0000, 4'b0000, 2'b00);
    cycles(1);
end
endtask

initial begin
    // Initialize Inputs
    testcase = 0;
    almost_full = 0;
    empty = 4'b1111;
    dest = 0;
    valid = 0;
    state = 4'b0001;

    // Wait 100 ns for global reset to finish
    #100;
    observe;

    // Test Case 1: all destination/valid combinations, reset and operating.
    testcase = 1;
    for (mode = 0; mode < 2; mode = mode + 1) begin
        #1;
        initialize_case;
        for (d = 0; d < 4; d = d + 1) begin
            #1;
            for (v = 0; v < 16; v = v + 1) begin
                #1;
                apply(mode, 4'b1111, 4'b0000, v, d);
                cycles(1);
            end
        end
    end

    // Test Case 2: every availability mask, idle retention, and warm reset.
    testcase = 2;
    for (m = 0; m < 16; m = m + 1) begin
        #1;
        initialize_case;
        apply(0, m, 0, 4'b1111, 0);
        cycles(12);
        apply(0, 4'b1111, 0, 4'b1111, 1);
        cycles(2);
        apply(0, m, 0, 4'b1111, 2);
        cycles(2);
        apply(1, m, 0, 4'b1111, 3);
        cycles(1);
        apply(0, m, 0, 4'b1111, 0);
        cycles(2);
    end

    // Test Case 3: sustained weighted service and repeated quota clearing.
    testcase = 3;
    initialize_case;
    apply(0, 0, 0, 4'b1111, 3);
    cycles(22);

    // Test Case 4: retain a partially used queue-1 quota across inactivity.
    testcase = 4;
    initialize_case;
    apply(0, 4'b1101, 0, 0, 0);
    cycles(2);
    apply(0, 4'b1111, 0, 0, 0);
    cycles(2);
    apply(0, 4'b1101, 0, 0, 0);
    cycles(3);

    // Test Case 5: queue 0 re-enables an exhausted queue 3.
    testcase = 5;
    initialize_case;
    apply(0, 4'b0111, 0, 0, 0);
    cycles(3);
    apply(0, 4'b1110, 0, 0, 0);
    cycles(1);
    apply(0, 4'b0111, 0, 0, 0);
    cycles(3);

    // Test Case 6: global blocking, quota preservation, and blocked reset.
    testcase = 6;
    for (m = 1; m < 16; m = m + 1) begin
        #1;
        for (d = 0; d < 4; d = d + 1) begin
            #1;
            initialize_case;
            apply(0, 0, 0, 4'b1111, d);
            cycles(2);
            apply(0, 0, m, 4'b1111, d);
            cycles(3);
            apply(0, 0, 0, 4'b1111, d);
            cycles(10);
            apply(1, 0, m, 4'b1111, d);
            cycles(1);
            apply(0, 0, m, 4'b1111, d);
            cycles(1);
            apply(0, 0, 0, 4'b1111, d);
            cycles(5);
        end
    end

    // Test Case 7: complete external-state decoding.
    testcase = 7;
    for (s = 0; s < 16; s = s + 1) begin
        #1;
        initialize_case;
        apply(s, 0, 0, 4'b1111, 2);
        cycles(2);
    end

    $display("===========End===========");
    $finish;
end

endmodule

