initial clk = 1'b0;
always #5 clk = ~clk;

task set_data;
    input integer kind;
    integer n;
    begin
        for (n = 1; n <= 32; n = n + 1) begin
            if (kind == 0) begin
                ifm[n] = 4'd0;
                weight[n] = 4'd0;
            end
            else if (kind == 1) begin
                ifm[n] = 4'd15;
                weight[n] = 4'd15;
            end
            else if (kind == 2) begin
                ifm[n] = (n % 4) + 1;
                if (n == 31)
                    weight[n] = 4'd1;
                else if (n == 32)
                    weight[n] = 4'd15;
                else
                    weight[n] = (n * 3) % 16;
            end
            else if (kind == 3) begin
                ifm[n] = n % 16;
                weight[n] = 15 - (n % 16);
            end
            else begin
                ifm[n] = 15 - (n % 16);
                weight[n] = (n % 8) + 1;
            end
            #1;
        end
    end
endtask

task pulse_weight;
    begin
        weight_valid = 1'b1;
        @(posedge clk);
        #1 weight_valid = 1'b0;
    end
endtask

task pulse_feature;
    begin
        in_valid = 1'b1;
        @(posedge clk);
        #1 in_valid = 1'b0;
    end
endtask

task reset_dut;
    begin
        rst_n = 1'b0;
        #2;
        $display("RESET: out_valid=%b Out_OFM=%h", out_valid, Out_OFM);
        rst_n = 1'b1;
        repeat (2) @(posedge clk);
    end
endtask

initial begin
    rst_n = 1'b0;
    in_valid = 1'b0;
    weight_valid = 1'b0;

    #100;
    $display("STARTUP_RESET: out_valid=%b Out_OFM=%h", out_valid, Out_OFM);
    rst_n = 1'b1;
    repeat (2) @(posedge clk);

    // Test Case 1: zero transaction and complete execution window
    set_data(0);
    pulse_weight;
    pulse_feature;
    repeat (3) @(posedge clk);
    #1 $display("TC1_PIPELINE: out_valid=%b Out_OFM=%h", out_valid, Out_OFM);
    repeat (48) @(posedge clk);
    #1 $display("TC1_LATE_WINDOW: out_valid=%b Out_OFM=%h", out_valid, Out_OFM);
    repeat (2) @(posedge clk);
    #1 $display("TC1_IDLE: out_valid=%b Out_OFM=%h", out_valid, Out_OFM);

    reset_dut;

    // Test Case 2: maximum unsigned values
    set_data(1);
    pulse_weight;
    pulse_feature;
    repeat (3) @(posedge clk);
    #1 $display("TC2_PIPELINE: out_valid=%b Out_OFM=%h", out_valid, Out_OFM);
    repeat (49) @(posedge clk);
    #1 $display("TC2_LATE_WINDOW: out_valid=%b Out_OFM=%h", out_valid, Out_OFM);
    repeat (2) @(posedge clk);
    #1 $display("TC2_IDLE: out_valid=%b Out_OFM=%h", out_valid, Out_OFM);

    reset_dut;

    // Test Case 3: nonuniform mapping pattern
    set_data(2);
    pulse_weight;
    pulse_feature;
    repeat (3) @(posedge clk);
    #1 $display("TC3_PIPELINE: out_valid=%b Out_OFM=%h", out_valid, Out_OFM);
    repeat (10) @(posedge clk);
    #1 $display("TC3_ACTIVE: out_valid=%b Out_OFM=%h", out_valid, Out_OFM);

    reset_dut;

    // Test Case 4: weight and feature replacement during EXE
    set_data(3);
    pulse_weight;
    set_data(2);
    pulse_feature;
    repeat (5) @(posedge clk);
    #1 $display("TC4_BEFORE_RELOAD: out_valid=%b Out_OFM=%h", out_valid, Out_OFM);

    set_data(4);
    pulse_weight;
    set_data(3);
    pulse_feature;
    repeat (4) @(posedge clk);
    #1 $display("TC4_AFTER_RELOAD: out_valid=%b Out_OFM=%h", out_valid, Out_OFM);

    repeat (40) @(posedge clk);
    #1 $display("TC4_LATE_WINDOW: out_valid=%b Out_OFM=%h", out_valid, Out_OFM);

    rst_n = 1'b0;
    #2;
    $display("TC4_ASYNC_RESET: out_valid=%b Out_OFM=%h", out_valid, Out_OFM);
    rst_n = 1'b1;
    repeat (2) @(posedge clk);
    #1 $display("TC4_RESET_RELEASED: out_valid=%b Out_OFM=%h", out_valid, Out_OFM);

    $finish;
end

