module testbench;

// Inputs
reg clk;
reg reset;
reg done;
reg start;

// Outputs
wire read0;
wire s;
wire en;
wire en1;

integer test_id;
integer phase;
integer cycle_id;

controller_fsm_stream_I uut (
    .clk   (clk),
    .reset (reset),
    .done  (done),
    .start (start),
    .read0 (read0),
    .s     (s),
    .en    (en),
    .en1   (en1)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [127:0] point;
    begin
        $display("test=%0d phase=%0d cycle=%0d point=%0s t=%0t reset=%b start=%b done=%b read0=%b s=%b en=%b en1=%b",
                 test_id, phase, cycle_id, point, $time,
                 reset, start, done, read0, s, en, en1);
    end
endtask

task tick;
    input rst;
    input req;
    input complete;
    begin
        @(negedge clk);
        reset = rst;
        start = req;
        done = complete;
        if (rst) begin
            #1;
            observe("before_reset_edge");
        end
        @(posedge clk);
        #1;
        cycle_id = cycle_id + 1;
        observe("after_edge");
    end
endtask

task initialize_case;
    begin
        cycle_id = 0;
        tick(1, 0, 0);
        tick(0, 0, 0);
    end
endtask

initial begin
    reset = 1;
    start = 0;
    done = 0;
    test_id = 0;
    phase = 0;
    cycle_id = 0;

    // Wait 100 ns for global reset to finish.
    #100;
    observe("initial_reset");

    // Test 1: Idle and reset priority.
    test_id = 1;
    initialize_case;
    tick(0, 0, 1);
    tick(0, 0, 0);
    tick(1, 1, 1);
    tick(1, 1, 1);
    tick(0, 0, 0);

    // Test 2: Normal operation, ignored busy starts, completion, restart.
    test_id = 2;
    initialize_case;
    tick(0, 1, 0);
    tick(0, 1, 0);
    tick(0, 1, 0);
    tick(0, 0, 0);
    tick(0, 1, 0);
    repeat (3) tick(0, 0, 0);
    tick(0, 0, 1);
    tick(0, 0, 0);
    tick(0, 1, 0);
    repeat (3) tick(0, 0, 0);
    tick(0, 0, 1);
    repeat (2) tick(0, 0, 0);

    // Test 3: One-cycle done in each setup/active position.
    test_id = 3;
    for (phase = 0; phase < 4; phase = phase + 1) begin
        initialize_case;
        tick(0, 1, 0);
        repeat (phase) tick(0, 0, 0);
        tick(0, 0, 1);
        repeat (4) tick(0, 0, 0);
        tick(0, 0, 1);
        tick(0, 0, 0);
    end

    // Test 4: Done already high before start and held through completion.
    test_id = 4;
    phase = 0;
    initialize_case;
    tick(0, 0, 1);
    tick(0, 1, 1);
    repeat (5) tick(0, 0, 1);
    tick(0, 0, 0);

    // Test 5: Persistent start, including simultaneous start and done.
    test_id = 5;
    initialize_case;
    repeat (6) tick(0, 1, 0);
    repeat (9) tick(0, 1, 1);
    repeat (4) tick(0, 1, 0);
    tick(0, 0, 1);
    repeat (2) tick(0, 0, 0);

    // Test 6: Reset in idle, S1, S2, active entry, and sustained active.
    test_id = 6;
    for (phase = 0; phase < 5; phase = phase + 1) begin
        initialize_case;
        if (phase > 0) begin
            tick(0, 1, 0);
            repeat (phase - 1) tick(0, 0, 0);
        end
        tick(1, 1, 1);
        tick(1, 1, 1);
        tick(0, 0, 0);
        tick(0, 1, 0);
        repeat (4) tick(0, 0, 0);
        tick(0, 0, 1);
        tick(0, 0, 0);
    end

    $display("===========End===========");
    $finish;
end

endmodule

