module testbench;

// Inputs
reg clk;
reg rst;
reg in_valid;
reg [18:0] instruction;

// Outputs
wire out_valid;
wire signed [15:0] out;
wire [2:0] a;
wire signed [5:0] b, c;
wire signed [3:0] d;
wire signed [9:0] e;
wire count;

integer op, sel;

DALU uut (
    .clk(clk), .rst(rst), .in_valid(in_valid),
    .instruction(instruction),
    .out_valid(out_valid), .out(out),
    .a(a), .b(b), .c(c), .d(d), .e(e), .count(count)
);

initial clk = 0;
always #5 clk = ~clk;

function [18:0] pack_bcd;
    input [2:0] opcode;
    input signed [5:0] bv, cv;
    input signed [3:0] dv;
    begin
        pack_bcd = {opcode, bv, cv, dv};
    end
endfunction

function [18:0] pack_be;
    input [2:0] opcode;
    input signed [5:0] bv;
    input signed [9:0] ev;
    begin
        pack_be = {opcode, bv, ev};
    end
endfunction

task observe;
    input [255:0] label;
    begin
        $display("%0t %0s rst=%b in_valid=%b instruction=%h out_valid=%b out=%0d out_hex=%h a=%0d b=%0d c=%0d d=%0d e=%0d count=%b",
                 $time, label, rst, in_valid, instruction,
                 out_valid, out, out, a, b, c, d, e, count);
    end
endtask

task step;
    input valid;
    input [18:0] word;
    input [255:0] label;
    begin
        @(negedge clk);
        in_valid = valid;
        instruction = word;
        @(posedge clk);
        #1;
        observe(label);
    end
endtask

task reset_dut;
    begin
        @(negedge clk);
        rst = 1;
        in_valid = 1;
        instruction = 19'h7ffff;
        #1;
        observe("reset before rising edge");
        @(posedge clk);
        #1;
        observe("reset sampled");
        @(negedge clk);
        rst = 0;
        in_valid = 0;
        instruction = 0;
    end
endtask

task isolated;
    input [18:0] word;
    begin
        reset_dut;
        step(1, word, "isolated capture");
        step(0, 19'h7ffff, "isolated result");
        step(0, 19'h15555, "idle hold");
    end
endtask

task unsupported;
    input [18:0] word;
    begin
        reset_dut;
        step(1, pack_be(3, 7, 12), "seed capture");
        step(0, 0, "seed result");
        step(1, word, "unsupported capture");
        step(0, 19'h7ffff, "unsupported result");
        step(0, 0, "unsupported idle");
    end
endtask

initial begin
    rst = 1;
    in_valid = 0;
    instruction = 0;

    // Wait 100 ns for global reset to finish.
    #100;
    observe("startup reset");
    reset_dut;
    step(0, 19'h7ffff, "idle after reset");

    // Operation 0: each supported secondary selector.
    for (sel = 0; sel < 5; sel = sel + 1) begin
        @(negedge clk);
        isolated(pack_bcd(0, 0, 0, sel));
        isolated(pack_bcd(0, 31, 31, sel));
        isolated(pack_bcd(0, -32, -32, sel));
        isolated(pack_bcd(0, -32, 31, sel));
        isolated(pack_bcd(0, 31, -32, sel));
        isolated(pack_bcd(0, 21, -22, sel));
        isolated(pack_bcd(0, -1, 0, sel));
    end

    // Product and squared sum: boundaries, signs, zero, cancellation.
    for (op = 1; op <= 2; op = op + 1) begin
        @(negedge clk);
        isolated(pack_bcd(op, 0, 0, 0));
        isolated(pack_bcd(op, 31, 31, 7));
        isolated(pack_bcd(op, -32, -32, -8));
        isolated(pack_bcd(op, -32, -32, 7));
        isolated(pack_bcd(op, -32, 31, 7));
        isolated(pack_bcd(op, 31, -32, -8));
        isolated(pack_bcd(op, 31, 31, -8));
        isolated(pack_bcd(op, 0, -32, 7));
        isolated(pack_bcd(op, -32, 0, -8));
        isolated(pack_bcd(op, -32, 31, 0));
        isolated(pack_bcd(op, -8, 1, 7));
        isolated(pack_bcd(op, -1, -1, -1));
    end

    // Operations using the overlapping signed 10-bit field.
    for (op = 3; op <= 4; op = op + 1) begin
        @(negedge clk);
        isolated(pack_be(op, 0, 0));
        isolated(pack_be(op, 31, 511));
        isolated(pack_be(op, -32, -512));
        isolated(pack_be(op, -32, 511));
        isolated(pack_be(op, 31, -512));
        isolated(pack_be(op, -1, 1));
        isolated(pack_be(op, 1, -1));
        isolated(pack_be(op, -32, -32));
        isolated(pack_be(op, 31, -31));
    end

    // All unsupported secondary and primary encodings.
    for (sel = 5; sel < 16; sel = sel + 1) begin
        @(negedge clk);
        unsupported(pack_bcd(0, -32, 31, sel));
    end
    for (op = 5; op < 8; op = op + 1) begin
        @(negedge clk);
        unsupported(pack_bcd(op, 31, -32, -8));
    end

    // Continuous traffic, bubbles, and draining.
    reset_dut;
    for (op = 0; op < 8; op = op + 1) begin
        step(1, pack_bcd(op, -7, 5, 3), "continuous traffic");
        #1;
    end
    step(1, pack_be(3, 31, 511), "supported after unsupported");
    step(0, 19'h7ffff, "bubble result");
    step(1, pack_bcd(1, -3, 4, -2), "capture after bubble");
    step(1, pack_bcd(2, 2, -3, 4), "continuous resume");
    step(0, 0, "drain result");
    step(0, 19'h7ffff, "drained idle");

    // Reset discards pending work and clears an existing result.
    reset_dut;
    step(1, pack_be(3, 7, 12), "pre-reset seed");
    step(1, pack_bcd(1, 31, 31, 7), "pre-reset pending");
    reset_dut;
    step(0, 19'h7ffff, "post-reset empty pipeline");
    step(1, pack_be(4, -32, 511), "reset recovery capture");
    step(0, 0, "reset recovery result");
    step(0, 19'h7ffff, "reset recovery idle");

    $display("===========End===========");
    $finish;
end

endmodule

