wire [3:1] match1_sel, match2_sel, match3_sel;
wire [3:1] intr_en_reg_sel25, clear_interrupt25;

integer a, q, pattern, r;
integer test_id;

ttc_interface_lite25 uut (
    .n_p_reset25(n_p_reset25),
    .pclk25(clk),
    .psel25(psel25),
    .penable25(penable25),
    .pwrite25(pwrite25),
    .paddr25(paddr25),

    .clk_ctrl_reg_125(source[0][6:0]),
    .clk_ctrl_reg_225(source[1][6:0]),
    .clk_ctrl_reg_325(source[2][6:0]),
    .cntr_ctrl_reg_125(source[3][6:0]),
    .cntr_ctrl_reg_225(source[4][6:0]),
    .cntr_ctrl_reg_325(source[5][6:0]),
    .counter_val_reg_125(source[6]),
    .counter_val_reg_225(source[7]),
    .counter_val_reg_325(source[8]),
    .interval_reg_125(source[9]),
    .interval_reg_225(source[10]),
    .interval_reg_325(source[11]),
    .match_1_reg_125(source[12]),
    .match_1_reg_225(source[13]),
    .match_1_reg_325(source[14]),
    .match_2_reg_125(source[15]),
    .match_2_reg_225(source[16]),
    .match_2_reg_325(source[17]),
    .match_3_reg_125(source[18]),
    .match_3_reg_225(source[19]),
    .match_3_reg_325(source[20]),
    .interrupt_reg_125(source[21][5:0]),
    .interrupt_reg_225(source[22][5:0]),
    .interrupt_reg_325(source[23][5:0]),
    .interrupt_en_reg_125(source[24][5:0]),
    .interrupt_en_reg_225(source[25][5:0]),
    .interrupt_en_reg_325(source[26][5:0]),

    .prdata25(prdata25),
    .clk_ctrl_reg_sel_125(clk_sel[1]),
    .clk_ctrl_reg_sel_225(clk_sel[2]),
    .clk_ctrl_reg_sel_325(clk_sel[3]),
    .cntr_ctrl_reg_sel_125(cntr_sel[1]),
    .cntr_ctrl_reg_sel_225(cntr_sel[2]),
    .cntr_ctrl_reg_sel_325(cntr_sel[3]),
