    .match_2_reg_sel_125(match2_sel[1]),
    .match_2_reg_sel_225(match2_sel[2]),
    .match_2_reg_sel_325(match2_sel[3]),
    .match_3_reg_sel_125(match3_sel[1]),
    .match_3_reg_sel_225(match3_sel[2]),
    .match_3_reg_sel_325(match3_sel[3]),
    .intr_en_reg_sel25(intr_en_reg_sel25),
    .clear_interrupt25(clear_interrupt25)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [8*20-1:0] phase;
    begin
        $display(
            "t=%0t test=%0d phase=%0s reset_n=%b addr=%02h sel/en/wr=%b%b%b prdata25=%08h clk_sel[3:1]=%b cntr_sel[3:1]=%b interval_sel[3:1]=%b match1_sel[3:1]=%b match2_sel[3:1]=%b match3_sel[3:1]=%b intr_en_reg_sel25[3:1]=%b clear_interrupt25[3:1]=%b",
            $time, test_id, phase, n_p_reset25, paddr25,
            psel25, penable25, pwrite25, prdata25,
            clk_sel, cntr_sel, interval_sel,
            match1_sel, match2_sel, match3_sel,
            intr_en_reg_sel25, clear_interrupt25
        );
    end
endtask

task reset_idle;
    begin
        @(negedge clk);
        psel25 = 0;
        penable25 = 0;
        pwrite25 = 0;
        paddr25 = 0;
        n_p_reset25 = 0;
        #1;
        observe("reset_assert");
        @(posedge clk);
        #1;
        observe("reset_held");
        @(negedge clk);
        n_p_reset25 = 1;
        #1;
    end
endtask

task access_bus;
    input [7:0] address;
    input [2:0] qualifiers;
    begin
        @(negedge clk);
        paddr25 = address;
        {psel25, penable25, pwrite25} = qualifiers;
        #1;
        observe("before_edge");
        @(posedge clk);
        #1;
        observe("after_edge");
    end
endtask

task load_sources;
    input integer mode;
    integer i;
    begin
        for (i = 0; i < 27; i = i + 1) begin
            #1;
            case (mode)
                0: source[i] = 16'h81e0 + i;
                1: source[i] = 16'h0000;
                2: source[i] = 16'hffff;
                3: source[i] = 16'haaaa;
                4: source[i] = 16'h5555;
            endcase
        end
    end
endtask

initial begin
    // Initialize inputs and allow 100 ns for startup reset.
    test_id = 0;
    n_p_reset25 = 0;
    psel25 = 0;
    penable25 = 0;
    pwrite25 = 0;
    paddr25 = 0;
    load_sources(0);
    #100;
    observe("startup_reset");
    @(negedge clk);
    n_p_reset25 = 1;

    // Test 1: complete address and qualifier space.
    for (q = 0; q < 8; q = q + 1) begin
        #1;
        test_id = 10 + q;
        reset_idle();
        access_bus(8'h18, 3'b110);
        for (a = 0; a < 256; a = a + 1) begin
            #1;
            access_bus(a, q);
        end
        access_bus(8'h00, 3'b000);
    end

    // Test 2: data boundaries and alternating patterns on every read port.
    for (pattern = 1; pattern <= 4; pattern = pattern + 1) begin
        #1;
        test_id = 20 + pattern;
        reset_idle();
        load_sources(pattern);
        for (a = 0; a < 27; a = a + 1) begin
            #1;
            access_bus(a * 4, 3'b100);
            access_bus(a * 4, 3'b110);
        end
        access_bus(8'h00, 3'b000);
    end

    // Test 3: asynchronous reset during read, write, and IRQ reads.
    for (r = 0; r < 5; r = r + 1) begin
        #1;
        test_id = 30 + r;
        reset_idle();
        load_sources(0);
        access_bus(8'h18, 3'b110);

        @(negedge clk);
        case (r)
            0: begin
                paddr25 = 8'h18;
                {psel25, penable25, pwrite25} = 3'b110;
            end
            1: begin
                paddr25 = 8'h00;
                {psel25, penable25, pwrite25} = 3'b111;
            end
            default: begin
                paddr25 = 8'h54 + (r - 2) * 4;
                {psel25, penable25, pwrite25} = 3'b110;
            end
        endcase
        #1;
        observe("before_reset");
        #1;
        n_p_reset25 = 0;
        #1;
        observe("async_reset");
        @(posedge clk);
        #1;
        observe("reset_active");
        @(negedge clk);
        n_p_reset25 = 1;
        #1;
        observe("reset_release");
        @(posedge clk);
        #1;
        observe("recovery");
        access_bus(8'h00, 3'b000);
    end

    $display("===========End===========");
    $finish;
end

endmodule

