            #1;
            normal(op, 32'h80000001, amount);
            normal(op, 32'h7ffffffe, amount);
            normal(op, 32'h80000001, 32'hffffffe0 | amount);
            normal(op, 32'h7ffffffe, 32'hffffffe0 | amount);
