        apply(op, 32'h00000003, 32'h00000001, 1'b1,
              33'h000000000, 33'h000000000);
        apply(op, 32'h00000003, 32'h00000001, 1'b1,
              33'h000000000, 33'h000000001);
        apply(op, 32'h00000003, 32'h00000001, 1'b1,
              33'h000000001, 33'h000000000);
        apply(op, 32'h00000003, 32'h00000001, 1'b1,
              33'h000000001, 33'h000000001);
        apply(op, 32'h00000003, 32'h00000001, 1'b1,
              33'h100000000, 33'h000000000);
        apply(op, 32'h00000003, 32'h00000001, 1'b1,
              33'h000000000, 33'h100000000);
        apply(op, 32'h00000003, 32'h00000001, 1'b1,
              33'h1ffffffff, 33'h000000001);
        apply(op, 32'hffffffff, 32'h80000000, 1'b1,
              33'h000000000, 33'h000000000);
        apply(op, 32'hffffffff, 32'h80000000, 1'b1,
              33'h1ffffffff, 33'h1ffffffff);
        apply(op, 32'h80000000, 32'h00000001, 1'b1,
              33'h000000000, 33'h000000000);
        apply(op, 32'h80000000, 32'h00000001, 1'b1,
              33'h1ffffffff, 33'h1ffffffff);
        apply(op, 32'h00000001, 32'h80000000, 1'b1,
              33'h000000000, 33'h000000000);
        apply(op, 32'h00000001, 32'h80000000, 1'b1,
              33'h1ffffffff, 33'h1ffffffff);
        apply(op, 32'haaaaaaaa, 32'h55555555, 1'b1,
              33'h155555555, 33'h0aaaaaaaa);
        apply(op, 32'haaaaaaaa, 32'h55555555, 1'b0,
              33'h155555555, 33'h0aaaaaaaa);
    end

    $display("===========End=========== result_o=%h adder_result_o=%h adder_result_ext_o=%h comparison_result_o=%b is_equal_result_o=%b",
             result_o, adder_result_o, adder_result_ext_o,
