module testbench;

localparam [4:0] NOP = 5'd0, SUB = 5'd3;

// Inputs
reg clk;
reg reset;
reg [4:0] opcode;

// Outputs
wire [1:0] muxPC, muxData, ioOp;
wire [4:0] controALU;
wire muxOperand, writeEnableRegs, writeEnable, readEnable;

integer i;

ControlUnit uut (
    .clock(clk),
    .reset(reset),
    .opcode(opcode),
    .muxPC(muxPC),
    .muxData(muxData),
    .muxOperand(muxOperand),
    .controALU(controALU),
    .writeEnableRegs(writeEnableRegs),
    .writeEnable(writeEnable),
    .readEnable(readEnable),
    .ioOp(ioOp)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [8*40-1:0] label;
    begin
        $display("%0s t=%0t clk=%b reset=%b opcode=%b muxPC=%b muxData=%b muxOperand=%b controALU=%b writeEnableRegs=%b writeEnable=%b readEnable=%b ioOp=%b",
                 label, $time, clk, reset, opcode,
                 muxPC, muxData, muxOperand, controALU,
                 writeEnableRegs, writeEnable, readEnable, ioOp);
    end
endtask

task apply;
    input new_reset;
    input [4:0] new_opcode;
    input [8*40-1:0] label;
    begin
        reset = new_reset;
        opcode = new_opcode;
        #1;
        observe(label);
    end
endtask

initial begin
    // Case 1: Startup SUB without prior control initialization.
    reset = 1'b1;
    opcode = SUB;

    // Wait 100 ns for global reset to finish.
    #100;
    observe("startup SUB");

    apply(1'b0, NOP, "initialize common controls");
    apply(1'b1, SUB, "SUB after initialization");

    // Case 2: Every opcode, initialized independently through reset low.
    for (i = 0; i < 32; i = i + 1) begin
        #1;
        apply(1'b0, i[4:0], "opcode sweep reset low");
        apply(1'b1, i[4:0], "opcode sweep reset high");
    end

    // Case 3: Reset transitions with SUB held.
    apply(1'b0, SUB, "reset transition initialize");
    apply(1'b1, SUB, "reset high SUB");
    apply(1'b0, SUB, "reset low from SUB");
    apply(1'b1, SUB, "return high from low");
    apply(1'bx, SUB, "reset X from SUB");
    apply(1'b1, SUB, "return high from X");
    apply(1'bz, SUB, "reset Z from SUB");
    apply(1'b1, SUB, "return high from Z");

    // Case 4: Unknown opcode defaults and recovery.
    apply(1'b0, NOP, "unknown opcode initialize");
    apply(1'b1, 5'bxxxxx, "opcode all X");
    apply(1'b1, SUB, "SUB after all X");
    apply(1'b1, 5'bzzzzz, "opcode all Z");
    apply(1'b1, SUB, "SUB after all Z");
    apply(1'b1, 5'b000x1, "opcode partial X");
    apply(1'b1, SUB, "SUB after partial X");
    apply(1'b1, 5'b000z1, "opcode partial Z");
    apply(1'b1, SUB, "SUB after partial Z");

    // Case 5: Fixed inputs across both clock edges.
    apply(1'b0, NOP, "clock test initialize");
    apply(1'b1, SUB, "clock test SUB");
    @(posedge clk);
    #1;
    observe("SUB after rising clock");
    @(negedge clk);
    #1;
    observe("SUB after falling clock");

    $display("===========End===========");
    $finish;
end

endmodule

