`timescale 1ns / 1ps
module testbench;

localparam [2:0] START_CMD = 3'd0,
                 WR_CMD    = 3'd1,
                 RD_CMD    = 3'd2,
                 STOP_CMD  = 3'd3,
                 NOP_CMD   = 3'd7;

// Inputs
reg clk;
reg wr_i2c;
reg [2:0] cmd;
reg [7:0] din;
reg [15:0] dvsr;
reg rst;
reg sda_in;

// Outputs
wire [7:0] dout;
wire ack, ready, done_tick, sda_out, scl;

integer test_id, i, j, quarter_cycles;
reg [7:0] payload;

I2c uut (
    .wr_i2c(wr_i2c), .cmd(cmd), .din(din), .dvsr(dvsr),
    .clk(clk), .rst(rst), .sda_in(sda_in),
    .dout(dout), .ack(ack), .ready(ready),
    .done_tick(done_tick), .sda_out(sda_out), .scl(scl)
);

initial clk = 0;

always #5 clk = ~clk;

task observe;
    input [191:0] label;
    begin
        $display("t=%0t case=%0d %0s rst=%b wr_i2c=%b cmd=%0d dvsr=%0d din=%h sda_in=%b dout=%h ack=%b ready=%b done_tick=%b sda_out=%b scl=%b",
                 $time, test_id, label, rst, wr_i2c, cmd, dvsr,
                 din, sda_in, dout, ack, ready, done_tick, sda_out, scl);
    end
endtask

task advance;
    input integer cycles;
    input [191:0] label;
    begin
        repeat (cycles) @(posedge clk);
        #1;
        observe(label);
    end
endtask

task reset_dut;
    begin
        @(negedge clk);
        #2 rst = 0;
        #1;
        observe("reset_assert");
        advance(2, "reset_held");
        @(negedge clk);
        wr_i2c = 0;
        cmd = NOP_CMD;
        din = 0;
        sda_in = 1;
        rst = 1;
        advance(1, "reset_release");
    end
endtask

task launch;
    input [2:0] operation;
    begin
        @(negedge clk);
        cmd = operation;
        wr_i2c = (operation == START_CMD);
        advance(1, "command_launch");
    end
endtask

// Called at phase entry; observe its last cycle and the next boundary.
task phase_span;
    input integer cycles;
    input [191:0] label;
    begin
        if (cycles > 1)
            advance(cycles - 1, label);
        advance(1, label);
    end
endtask

task bus_condition;
    input [2:0] operation;
    integer half_cycles, phase_index;
    begin
        half_cycles = ((2 * dvsr) % 65536) + 1;
        launch(operation);
        for (phase_index = 0; phase_index < 2;
             phase_index = phase_index + 1) begin
            phase_span(half_cycles, "start_stop_boundary");
        end
        @(negedge clk);
        wr_i2c = 0;
        cmd = NOP_CMD;
        advance(2, "bus_settled");
    end
endtask

task transfer;
    input [2:0] operation;
    input [7:0] tx_byte;
    input [8:0] serial_samples;
    input response;
    integer q, bit_index, phase_index;
    begin
        q = dvsr + 1;
        din = tx_byte;
        launch(operation);
        for (bit_index = 0; bit_index < 9;
             bit_index = bit_index + 1) begin
            @(negedge clk);
            sda_in = serial_samples[8 - bit_index];
            din = ~tx_byte;
            #1;
            observe("serial_input");
            for (phase_index = 0; phase_index < 4;
                 phase_index = phase_index + 1) begin
                phase_span(q, "data_boundary");
            end
        end
        @(negedge clk);
        sda_in = response;
        #1;
        observe("ack_input");
        for (phase_index = 0; phase_index < 4;
             phase_index = phase_index + 1) begin
            phase_span(q, "ack_boundary");
        end
        @(negedge clk);
        cmd = NOP_CMD;
        wr_i2c = 0;
        advance(2, "post_transfer_hold");
    end
endtask

initial begin
    wr_i2c = 0;
    cmd = NOP_CMD;
    din = 0;
    dvsr = 1;
    rst = 0;
    sda_in = 1;
    test_id = 0;

    // Wait 100 ns for global reset to finish.
    #100;
    observe("initial_reset");
    reset_dut();

    // IDLE command qualification; enabled START is exercised separately.
    for (i = 0; i < 16; i = i + 1) begin
        @(negedge clk);
        cmd = i % 8;
        wr_i2c = (i == 8) ? 0 : (i / 8);
        sda_in = i % 2;
        advance(2, "idle_command");
    end

    // HOLD ignores START and undefined commands regardless of wr_i2c.
    test_id = 1;
    reset_dut();
    bus_condition(START_CMD);
    for (i = 0; i < 5; i = i + 1) begin
        @(negedge clk);
        cmd = (i == 0) ? START_CMD : (i + 3);
        wr_i2c = 1;
        advance(2, "hold_command");
    end
    bus_condition(STOP_CMD);

    // Independent payload cases, with chained transfers inside each case.
    for (i = 0; i < 4; i = i + 1) begin
        test_id = 10 + i;
        reset_dut();
        case (i)
            0: begin dvsr = 0; payload = 8'h00; end
            1: begin dvsr = 1; payload = 8'hff; end
            2: begin dvsr = 2; payload = 8'ha6; end
            3: begin dvsr = 5; payload = 8'h59; end
        endcase
        bus_condition(START_CMD);
        transfer(WR_CMD, payload, {payload, 1'b0}, i % 2);
        transfer(RD_CMD, 8'h00, {payload, 1'b0}, 1'b0);
        transfer(RD_CMD, 8'hff, {payload, 1'b1}, 1'b1);
        bus_condition(STOP_CMD);
    end

    // Upper divisor boundaries and a complete maximum-divisor transfer.
    for (i = 0; i < 3; i = i + 1) begin
        test_id = 20 + i;
        reset_dut();
        case (i)
            0: dvsr = 16'h7fff;
            1: dvsr = 16'h8000;
            2: dvsr = 16'hffff;
        endcase
        bus_condition(START_CMD);
        if (i == 2)
            transfer(RD_CMD, 8'h00, {8'ha6, 1'b1}, 1'b0);
        bus_condition(STOP_CMD);
    end

    // Abort START_1/2, HOLD, DATA_1..4, ACK_1..4, STOP_1/2.
    for (i = 0; i < 13; i = i + 1) begin
        test_id = 30 + i;
        reset_dut();
        dvsr = 1;
        quarter_cycles = dvsr + 1;

        if (i < 3) begin
            launch(START_CMD);
            advance(i * (2 * dvsr + 1), "before_reset");
        end
        else begin
            bus_condition(START_CMD);
            if (i < 11) begin
                j = i - 3;
                din = 8'ha6;
                sda_in = 1;
                launch((j % 2 == 0) ? WR_CMD : RD_CMD);
                if (j < 4)
                    advance((4 * 4 + j) * quarter_cycles,
                            "before_data_reset");
                else
                    advance((9 * 4 + j - 4) * quarter_cycles,
                            "before_ack_reset");
            end
            else begin
                launch(STOP_CMD);
                advance((i - 11) * (2 * dvsr + 1),
                        "before_stop_reset");
            end
        end
        reset_dut();
    end

    // Recovery transaction after the interruption cases.
    test_id = 50;
    bus_condition(START_CMD);
    transfer(RD_CMD, 8'h00, {8'h59, 1'b0}, 1'b1);
    bus_condition(STOP_CMD);

    $display("===========End===========");
    $finish;
end

endmodule

