             $time, test_name, o_dev_ZDQQ, o_dev_ZT, o_dev_DMs,
             o_vram_we, o_vram_ce, o_vram_data, o_vram_addr,
             t_A, t_busy, t_done, o_vram_yoffset);
end
endtask

// Sample after sequential and event-driven updates have settled.
task clocks;
input integer count;
integer n;
begin
    for (n = 0; n < count; n = n + 1) begin
        @(posedge clk);
        #1;
        observe;
    end
end
endtask

task reset_device;
begin
    @(negedge clk);
    i_dev_KZ = 0;
    i_dev_SR = 0;
    i_dev_ZZ0 = 1;
    #1;
    observe;
    clocks(2);
    @(negedge clk);
    i_dev_ZZ0 = 0;
    #1;
    observe;
end
endtask

task pulse;
input [8:0] control;
begin
    @(negedge clk);
    i_dev_KZ = control;
    #1;
    observe;
    #2;
    i_dev_KZ = 0;
    #1;
    observe;
end
endtask

task capture;
input [15:0] source;
begin
    @(negedge clk);
    i_dev_SR = source;
    #1;
    i_dev_KZ = 9'h001;
    #1;
    observe;
    #1;
    i_dev_KZ = 0;
    #1;
    observe;
end
endtask

task send_character;
input [15:0] source;
input integer duration;
begin
    capture(source);
    pulse(9'h040);
    clocks(duration);
end
endtask

initial begin
    // Initialize inputs.
    i_dev_ZZ0 = 0;
    i_dev_KZ = 0;
    i_dev_SR = 0;
    test_name = "initial reset";

    #1;
    i_dev_ZZ0 = 1;
    // Wait 100 ns for global reset to finish.
    #100;
    observe;

    test_name = "reset priority";
    i_dev_SR = 16'hFFFF;
    pulse(9'h001);
    pulse(9'h040);
    pulse(9'h080);
    reset_device;

    test_name = "capture edges and unused controls";
    capture(16'h1241);
    @(negedge clk);
    i_dev_SR = 16'hAB82;
    #1;
    i_dev_KZ = 9'h001;
    #1;
    observe;
    #1;
    i_dev_SR = 16'hCD55;
    #1;
    observe;
    clocks(2);
    @(negedge clk);
    i_dev_KZ = 0;
    #1;
    observe;
    clocks(2);
    pulse(9'h13E);
    clocks(2);
    capture(16'hFE41);
    clocks(2);

    test_name = "start repeat completion restart clear";
    reset_device;
    pulse(9'h080);
    capture(16'h0041);
    pulse(9'h040);
    clocks(1);
    pulse(9'h040);
    clocks(CHAR_CYCLES);
    clocks(3);
    pulse(9'h040);
    clocks(CHAR_CYCLES);
    pulse(9'h080);
    clocks(2);
    pulse(9'h040);
    clocks(CHAR_CYCLES);

    // Start and clear entirely between adjacent processing edges.
    test_name = "clear busy before processing";
    reset_device;
    capture(16'h0042);
    @(negedge clk);
    i_dev_KZ = 9'h040;
    #1;
    observe;
    i_dev_KZ = 0;
    #1;
    i_dev_KZ = 9'h080;
    #1;
    observe;
    i_dev_KZ = 0;
    #1;
    observe;
    clocks(CHAR_CYCLES);
    pulse(9'h040);
    clocks(CHAR_CYCLES);

    test_name = "ordinary character classes";
    for (i = 0; i < 5; i = i + 1) begin
        #1;
        reset_device;
        case (i)
            0: character = 8'h20;
            1: character = 8'h41;
            2: character = 8'h80;
            3: character = 8'hFF;
            4: character = 8'h0D;
        endcase
        send_character({8'hA5, character}, CHAR_CYCLES);
    end

    // Exercise suppressed codes at a partial and a full line.
    test_name = "suppressed codes and full-line priority";
    for (i = 0; i < 2; i = i + 1) begin
        #1;
        reset_device;
        position = 1;
        if (i == 1) position = LINE_MAX;
        for (j = 0; j < position; j = j + 1) begin
            #1;
            send_character(16'h0041 + j, CHAR_CYCLES);
        end
        for (k = 0; k < 5; k = k + 1) begin
            #1;
            case (k)
                0: character = 8'd0;
                1: character = 8'd7;
                2: character = 8'd19;
                3: character = 8'd23;
                4: character = 8'd26;
            endcase
            send_character({8'h00, character}, CHAR_CYCLES);
        end
        send_character(16'h0058, ROW_CYCLES);
        send_character(16'h0059, CHAR_CYCLES);
    end

    test_name = "backspace zero one full and overflow";
    for (i = 0; i < 2; i = i + 1) begin
        #1;
        reset_device;
        backspace = 8'd8;
        if (i == 1) backspace = 8'd25;
        send_character({8'h00, backspace}, CHAR_CYCLES);
        send_character(16'h0041, CHAR_CYCLES);
        send_character({8'h00, backspace}, CHAR_CYCLES);
        for (j = 0; j < LINE_MAX; j = j + 1) begin
            #1;
            send_character(16'h0042 + j, CHAR_CYCLES);
        end
        send_character({8'h00, backspace}, CHAR_CYCLES);
        send_character(16'h0058, CHAR_CYCLES);
        send_character(16'h0059, ROW_CYCLES);
        send_character(16'h005A, CHAR_CYCLES);
    end

    test_name = "line feed at boundary positions";
    for (i = 0; i < 4; i = i + 1) begin
        #1;
        reset_device;
        case (i)
            0: position = 0;
            1: position = 1;
            2: position = LINE_MAX - 1;
            3: position = LINE_MAX;
        endcase
        for (j = 0; j < position; j = j + 1) begin
            #1;
            send_character(16'h0061 + j, CHAR_CYCLES);
        end
        send_character(16'h000A, ROW_CYCLES);
        send_character(16'h0051, CHAR_CYCLES);
    end

    test_name = "circular vertical offset rollover";
    reset_device;
    for (i = 0; i < 32; i = i + 1) begin
        #1;
        send_character(16'h000A, ROW_CYCLES);
    end
    send_character(16'h0052, CHAR_CYCLES);

    test_name = "reset during ordinary write";
    reset_device;
    capture(16'h0053);
    pulse(9'h040);
    clocks(5);
    reset_device;
    clocks(CHAR_CYCLES);
    send_character(16'h0054, CHAR_CYCLES);

    test_name = "reset during row cleaning";
    reset_device;
    for (i = 0; i < LINE_MAX; i = i + 1) begin
        #1;
        send_character(16'h0041 + i, CHAR_CYCLES);
    end
    capture(16'h0055);
    pulse(9'h040);
    clocks(5);
    reset_device;
    clocks(ROW_CYCLES);
    send_character(16'h0056, CHAR_CYCLES);

    // Supplement the existing reset cases with fixed timing sweeps.
    // i=0: ordinary output; i=1: line feed; i=2: overflow cleaning.
    //
    // Ordinary output:
    //   clocks 1,2: START_T1, START_T2
    //   clocks 3..7: PUTCHAR_START through PUTCHAR_DONE
    //   clock 8: DONE
    //
    // Line feed / overflow cleaning:
    //   clock 3: LINEFEED_START / LINECLEAN_START
    //   clocks 4..8: PUTCHAR_START through PUTCHAR_DONE
    //   clock 9: LINEFEED_DONE / LINECLEAN_DONE
    //
    // These are fixed stimulus delays, with no DUT state reads.
    // reset_device asserts reset on the next falling clock edge.
    for (i = 0; i < 3; i = i + 1) begin
        #1;
        for (j = 1; j <= 9; j = j + 1) begin
            #1;
            case (i)
                0: test_name = "reset sweep ordinary output";
                1: test_name = "reset sweep line feed";
                2: test_name = "reset sweep overflow cleaning";
            endcase

            reset_device;

            // Reach the full-line boundary through normal transactions.
            if (i == 2) begin
                for (k = 0; k < LINE_MAX; k = k + 1) begin
                    #1;
                    send_character(16'h0061 + k, CHAR_CYCLES);
                end
            end

            // Line feed from zero exercises both feed and clean flags.
            // Ordinary output at a full line initiates overflow cleaning.
            if (i == 1)
                capture(16'hA50A);
            else
                capture(16'hA557);

            pulse(9'h040);
            clocks(j);
            reset_device;

            // Observe the reset device remaining idle, then exercise
            // fresh capture, processing, completion, and idle recovery.
            clocks(CHAR_CYCLES);
            send_character(16'h5A56, CHAR_CYCLES);
            clocks(2);
        end
    end

    $display("===========End===========");
    $finish;
end

endmodule

