module testbench;

// Inputs
reg clk;
reg rst;
reg ps2_clk;
reg ps2_data;

// Outputs
wire [23:0] key;

integer test_id;
integer i;

KeyBoard_detection uut (
    .clk(clk),
    .rst(rst),
    .ps2_clk(ps2_clk),
    .ps2_data(ps2_data),
    .key(key)
);

initial clk = 0;
always #5 clk = ~clk;

task reset_dut;
begin
    @(negedge clk);
    #2 rst = 1'b1;
    #1;
    $display("test=%0d reset_assert t=%0t key=%06h",
             test_id, $time, key);
    ps2_clk = 1'b1;
    ps2_data = 1'b1;
    repeat (4) @(posedge clk);
    #1;
    $display("test=%0d reset_held t=%0t key=%06h",
             test_id, $time, key);
    @(negedge clk);
    rst = 1'b0;
    repeat (4) @(posedge clk);
    #1;
    $display("test=%0d reset_release t=%0t key=%06h",
             test_id, $time, key);
end
endtask

task serial_bit;
    input bit_value;
    input integer edge_id;
begin
    @(negedge clk);
    ps2_data = bit_value;
    ps2_clk = 1'b1;
    repeat (4) @(posedge clk);
    #1;
    $display("test=%0d edge=%0d high data=%b t=%0t key=%06h",
             test_id, edge_id, ps2_data, $time, key);
    @(negedge clk);
    ps2_clk = 1'b0;
    repeat (4) @(posedge clk);
    #1;
    $display("test=%0d edge=%0d low data=%b t=%0t key=%06h",
             test_id, edge_id, ps2_data, $time, key);
end
endtask

task send_frame;
    input [7:0] data_byte;
    input start_bit;
    input parity_bit;
    input stop_bit;
    integer b;
begin
    serial_bit(start_bit, 0);
    for (b = 0; b < 8; b = b + 1) begin
        #1;
        serial_bit(data_byte[b], b + 1);
    end
    serial_bit(parity_bit, 9);
    serial_bit(stop_bit, 10);
end
endtask

initial begin
    rst = 1'b1;
    ps2_clk = 1'b1;
    ps2_data = 1'b1;
    test_id = 1;

    // Initial reset and idle.
    #100;
    $display("test=%0d initial_reset t=%0t key=%06h",
             test_id, $time, key);
    @(negedge clk);
    rst = 1'b0;
    for (i = 0; i < 4; i = i + 1) begin
        @(negedge clk);
        ps2_data = ~ps2_data;
        repeat (4) @(posedge clk);
        #1;
        $display("test=%0d idle_high data=%b t=%0t key=%06h",
                 test_id, ps2_data, $time, key);
    end

    // Consecutive frames and history rollover.
    test_id = 2;
    reset_dut;
    send_frame(8'h00, 1'b0, 1'b1, 1'b1);
    send_frame(8'hFF, 1'b0, 1'b1, 1'b1);
    send_frame(8'h96, 1'b0, 1'b1, 1'b1);
    send_frame(8'h69, 1'b0, 1'b1, 1'b1);

    // Invalid framing followed by normal reception.
    test_id = 3;
    reset_dut;
    send_frame(8'h3C, 1'b1, 1'b0, 1'b0);
    send_frame(8'h01, 1'b0, 1'b0, 1'b1);

    // Reset during data collection with a populated history.
    test_id = 4;
    reset_dut;
    send_frame(8'hA5, 1'b0, 1'b1, 1'b1);
    serial_bit(1'b0, 0);
    for (i = 0; i < 4; i = i + 1) begin
        #1;
        serial_bit(1'b1, i + 1);
    end
    for (i = 0; i < 4; i = i + 1) begin
        @(negedge clk);
        ps2_data = ~ps2_data;
        repeat (4) @(posedge clk);
        #1;
        $display("test=%0d paused_low data=%b t=%0t key=%06h",
                 test_id, ps2_data, $time, key);
    end
    reset_dut;
    send_frame(8'h52, 1'b0, 1'b0, 1'b1);

    // Reset after publication, before the stop edge.
    test_id = 5;
    reset_dut;
    serial_bit(1'b0, 0);
    for (i = 0; i < 8; i = i + 1) begin
        #1;
        serial_bit(1'b1, i + 1);
    end
    serial_bit(1'b1, 9);
    reset_dut;
    send_frame(8'h80, 1'b0, 1'b0, 1'b1);

    $display("===========End===========");
    $finish;
end

endmodule

