module testbench;

// State encodings
localparam IDLE            = 4'd0;
localparam START           = 4'd1;
localparam ACKNOWLEDGE     = 4'd7;

// Inputs
reg CLK;
reg NRST;
reg [3:0] state;
reg [4:0] command_queue;
reg [7:0] data_queue;

// Outputs
wire [6:0] slave_addr;
wire       read_write;
wire [7:0] control_frame;
wire [7:0] reg_addr;
wire [7:0] data_write;
wire [1:0] control_select;
wire       co_flag;

// Unit Under Test
i2c_oled_setup uut (
    .CLK            (CLK),
    .NRST           (NRST),
    .state          (state),
    .command_queue  (command_queue),
    .data_queue     (data_queue),
    .slave_addr     (slave_addr),
    .read_write     (read_write),
    .control_frame  (control_frame),
    .reg_addr       (reg_addr),
    .data_write     (data_write),
    .control_select (control_select),
    .co_flag        (co_flag)
);

// Clock generation
initial CLK = 1'b0;
always #5 CLK = ~CLK;

task show_outputs;
begin
    $display("OBS t=%0t state=%h cmd=%0d data_queue=%h slave_addr=%h read_write=%b control_frame=%h reg_addr=%h data_write=%h control_select=%b co_flag=%b",
             $time, state, command_queue, data_queue,
             slave_addr, read_write, control_frame,
             reg_addr, data_write, control_select, co_flag);
end
endtask

task reset_dut;
begin
    NRST = 1'b0;
    state = IDLE;
    command_queue = 5'd0;
    data_queue = 8'h00;

    #1;
    show_outputs;

    repeat (1) @(posedge CLK);
    #1;
    show_outputs;

    NRST = 1'b1;
end
endtask

integer st;
integer q;

initial begin
    NRST = 1'b1;
    state = ACKNOWLEDGE;
    command_queue = 5'd0;
    data_queue = 8'h3C;

    // Test Case 0: ACK operation before any reset.
    // Internal control_select and frame_timing remain uninitialized,
    // exercising the implicit default paths of the case statements.
    for (q = 0; q <= 19; q = q + 1) begin
        state = ACKNOWLEDGE;
        command_queue = q;
        repeat (1) @(posedge CLK);
        #1;
        show_outputs;
    end

    // Test Case 1: synchronous reset
    reset_dut;

    // Test Case 2: START state
    state = START;
    repeat (1) @(posedge CLK);
    #1;
    show_outputs;

    // Test Case 3: all state encodings
    reset_dut;
    command_queue = 5'd0;
    data_queue = 8'hA5;

    for (st = 0; st <= 15; st = st + 1) begin
        state = st;
        repeat (1) @(posedge CLK);
        #1;
        show_outputs;
    end

    // Test Case 4: ACK queue 0 with a paused phase
    reset_dut;
    state = ACKNOWLEDGE;
    command_queue = 5'd0;
    data_queue = 8'hA5;

    repeat (1) @(posedge CLK);
    #1;
    show_outputs;

    state = IDLE;
    repeat (1) @(posedge CLK);
    #1;
    show_outputs;

    state = ACKNOWLEDGE;
    repeat (1) @(posedge CLK);
    #1;
    show_outputs;

    // Test Case 5: all explicit and default command queue branches
    for (q = 1; q <= 31; q = q + 1) begin
        state = ACKNOWLEDGE;
        command_queue = q;

        if (q == 1)
            data_queue = 8'h5A;

        repeat (1) @(posedge CLK);
        #1;
        show_outputs;

        repeat (1) @(posedge CLK);
        #1;
        show_outputs;
    end

    $display("===========End===========");

    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

reg         sys_clk;
reg         sys_rst_n;
reg [31:0]  data1_in;
reg [31:0]  data2_in;
reg [31:0]  plus_result_in;
reg [31:0]  multi_result_in;
reg [31:0]  div_result_in;
reg [1:0]   opcode;
reg         trig;
reg         plus_vld_in;
reg         multi_vld_in;
reg         div_vld_in;

wire [31:0] data1_out;
wire [31:0] data2_out;
wire [31:0] result_out;
wire        sel_plus;
wire        sel_multi;
wire        sel_div;
wire        op_plus;
wire        work;
wire        result_vld;

Ctrl uut (
    .sys_clk        (sys_clk),
    .sys_rst_n      (sys_rst_n),
    .data1_in       (data1_in),
    .data2_in       (data2_in),
    .plus_result_in (plus_result_in),
    .multi_result_in(multi_result_in),
    .div_result_in  (div_result_in),
    .data1_out      (data1_out),
    .data2_out      (data2_out),
    .result_out     (result_out),
    .opcode        (opcode),
    .trig          (trig),
    .plus_vld_in   (plus_vld_in),
    .multi_vld_in  (multi_vld_in),
    .div_vld_in    (div_vld_in),
    .sel_plus      (sel_plus),
    .sel_multi     (sel_multi),
    .sel_div       (sel_div),
    .op_plus       (op_plus),
    .work          (work),
    .result_vld    (result_vld)
);

initial sys_clk = 1'b0;
always #5 sys_clk = ~sys_clk;

task show_outputs;
begin
    $display("time=%0t data1_out=%h data2_out=%h result_out=%h sel_plus=%b sel_multi=%b sel_div=%b op_plus=%b work=%b result_vld=%b",
             $time, data1_out, data2_out, result_out,
             sel_plus, sel_multi, sel_div, op_plus, work, result_vld);
end
endtask

task reset_dut;
begin
    sys_rst_n   = 1'b0;
    trig        = 1'b0;
    plus_vld_in = 1'b0;
    multi_vld_in= 1'b0;
    div_vld_in  = 1'b0;
    #2;
    show_outputs;
    sys_rst_n = 1'b1;
    repeat (1) @(posedge sys_clk);
    #1;
    show_outputs;
end
endtask

task drive_request;
input [1:0]  request_opcode;
input [31:0] request_data1;
input [31:0] request_data2;
begin
    opcode   = request_opcode;
    data1_in = request_data1;
    data2_in = request_data2;
    trig     = 1'b1;
    repeat (1) @(posedge sys_clk);
    #1;
    show_outputs;

    trig = 1'b0;
    repeat (1) @(posedge sys_clk);
    #1;
    show_outputs;
end
endtask

integer i;

initial begin
    sys_rst_n       = 1'b0;
    data1_in        = 32'b0;
    data2_in        = 32'b0;
    plus_result_in  = 32'b0;
    multi_result_in = 32'b0;
    div_result_in   = 32'b0;
    opcode          = 2'b00;
    trig            = 1'b0;
    plus_vld_in     = 1'b0;
    multi_vld_in    = 1'b0;
    div_vld_in      = 1'b0;

    // Reset behavior.
    reset_dut;

    // Plus requests for opcode 00 and opcode 01.
    for (i = 0; i < 2; i = i + 1) begin
        reset_dut;
        plus_result_in = 32'h11110000 + i;
        drive_request(i, 32'h00000010 + i, 32'h00000020 + i);

        plus_vld_in = 1'b1;
        repeat (1) @(posedge sys_clk);
        #1;
        show_outputs;

        plus_vld_in = 1'b0;
        repeat (1) @(posedge sys_clk);
        #1;
        show_outputs;
    end

    // Plus state: unrelated response, ignored trigger, and valid priority.
    reset_dut;
    plus_result_in  = 32'hAAAA0001;
    multi_result_in = 32'hBBBB0002;
    div_result_in   = 32'hCCCC0003;
    drive_request(2'b00, 32'h12345678, 32'h87654321);

    multi_vld_in = 1'b1;
    repeat (1) @(posedge sys_clk);
    #1;
    show_outputs;

    multi_vld_in = 1'b0;
    trig         = 1'b1;
    opcode       = 2'b11;
    data1_in     = 32'hDEADBEEF;
    data2_in     = 32'hCAFEBABE;
    repeat (1) @(posedge sys_clk);
    #1;
    show_outputs;

    trig         = 1'b0;
    plus_vld_in  = 1'b1;
    multi_vld_in = 1'b1;
    div_vld_in   = 1'b1;
    repeat (1) @(posedge sys_clk);
    #1;
    show_outputs;

    plus_vld_in  = 1'b0;
    multi_vld_in = 1'b0;
    div_vld_in   = 1'b0;
    repeat (1) @(posedge sys_clk);
    #1;
    show_outputs;

    // Multiply state: unrelated plus response followed by expected response.
    reset_dut;
    plus_result_in  = 32'h01010101;
    multi_result_in = 32'h02020202;
    div_result_in   = 32'h03030303;
    drive_request(2'b10, 32'h0000AAAA, 32'h00005555);

    plus_vld_in = 1'b1;
    repeat (1) @(posedge sys_clk);
    #1;
    show_outputs;

    plus_vld_in = 1'b0;
    repeat (1) @(posedge sys_clk);
    #1;
    show_outputs;

    multi_vld_in = 1'b1;
    repeat (1) @(posedge sys_clk);
    #1;
    show_outputs;

    multi_vld_in = 1'b0;
    repeat (1) @(posedge sys_clk);
    #1;
    show_outputs;

    // Divide state: unrelated responses followed by expected response.
    reset_dut;
    plus_result_in  = 32'h11111111;
    multi_result_in = 32'h22222222;
    div_result_in   = 32'h33333333;
    drive_request(2'b11, 32'hFFFFFFFF, 32'h00000001);

    plus_vld_in  = 1'b1;
    multi_vld_in = 1'b1;
    repeat (1) @(posedge sys_clk);
    #1;
    show_outputs;

    plus_vld_in  = 1'b0;
    multi_vld_in = 1'b0;
    repeat (1) @(posedge sys_clk);
    #1;
    show_outputs;

    div_vld_in = 1'b1;
    repeat (1) @(posedge sys_clk);
    #1;
    show_outputs;

    div_vld_in = 1'b0;
    repeat (1) @(posedge sys_clk);
    #1;
    show_outputs;

    // Idle valid inputs: line 153 condition (state != IDLE)=0,
    // any-valid=1. Keep trig low so the preceding request branch
    // does not mask evaluation of this condition.
    // Preserve the nonzero result from the previous divide completion.
    for (i = 1; i < 8; i = i + 1) begin
        @(negedge sys_clk);
        trig = 1'b0;
        {plus_vld_in, multi_vld_in, div_vld_in} = i;
        plus_result_in  = 32'hA1000000 + i;
        multi_result_in = 32'hB2000000 + i;
        div_result_in   = 32'hC3000000 + i;
        repeat (1) @(posedge sys_clk);
        #1;
        show_outputs;
    end

    plus_vld_in  = 1'b0;
    multi_vld_in = 1'b0;
    div_vld_in   = 1'b0;
    repeat (1) @(posedge sys_clk);
    #1;
    show_outputs;

    // Explicit multiply-over-divide priority while waiting for plus.
    reset_dut;
    plus_result_in  = 32'h01234567;
    multi_result_in = 32'h89ABCDEF;
    div_result_in   = 32'h76543210;
    drive_request(2'b01, 32'hAAAAAAAA, 32'h55555555);

    multi_vld_in = 1'b1;
    div_vld_in   = 1'b1;
    repeat (1) @(posedge sys_clk);
    #1;
    show_outputs;

    multi_vld_in = 1'b0;
    div_vld_in   = 1'b0;
    repeat (1) @(posedge sys_clk);
    #1;
    show_outputs;

    plus_vld_in = 1'b1;
    repeat (1) @(posedge sys_clk);
    #1;
    show_outputs;

    plus_vld_in = 1'b0;
    repeat (1) @(posedge sys_clk);
    #1;
    show_outputs;

    // Extend the original active multiply reset test to all opcodes.
    // This adds PLUS->0 and DIV->0 without touching DUT internals.
    for (i = 0; i < 4; i = i + 1) begin
        reset_dut;
        drive_request(i, 32'h13572468, 32'h24681357);

        // drive_request returns one time unit after a rising edge,
        // so reset assertion here is asynchronous to the clock.
        sys_rst_n = 1'b0;
        #1;
        show_outputs;

        sys_rst_n = 1'b1;
        repeat (1) @(posedge sys_clk);
        #1;
        show_outputs;
    end

    // Four-state opcode requests reach both opcode case defaults.
    // Ordinary case matching treats X/Z-containing values as unmatched.
    // Each request begins in idle and is followed by a sampled clear cycle.
    for (i = 0; i < 4; i = i + 1) begin
        reset_dut;
        @(negedge sys_clk);
        case (i)
            0: drive_request(2'bx0, 32'hFFFFFFFF, 32'h00000000);
            1: drive_request(2'bz1, 32'h00000000, 32'hFFFFFFFF);
            2: drive_request(2'bxx, 32'hAAAAAAAA, 32'h55555555);
            3: drive_request(2'bzz, 32'h55555555, 32'hAAAAAAAA);
        endcase
    end

    // Restore known inputs and observe reset recovery after X/Z stimulus.
    opcode = 2'b00;
    reset_dut;

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

reg        lclk;
reg        lreset_n;
reg        lframe_n;
wire [3:0] lad_in;
reg        lad_host_en;
reg  [3:0] lad_host_data;

wire [3:0] lpc_data_out;
wire       lpc_en;
reg        addr_hit;
wire [15:0] lpc_addr;
reg  [7:0] din;
wire [7:0] lpc_data_in;
wire       io_rden_sm;
wire       io_wren_sm;

wire       int_serirq;
reg        irq_host_en;
reg        irq_host_data;
reg  [7:0] serirq;

assign lad_in = lad_host_en ? lad_host_data : 4'bz;
assign int_serirq = irq_host_en ? irq_host_data : 1'bz;

LPC_Peri uut (
    .lclk         (lclk),
    .lreset_n     (lreset_n),
    .lframe_n     (lframe_n),
    .lad_in       (lad_in),
    .lpc_data_out (lpc_data_out),
    .lpc_en       (lpc_en),
    .addr_hit     (addr_hit),
    .lpc_addr     (lpc_addr),
    .din          (din),
    .lpc_data_in  (lpc_data_in),
    .io_rden_sm   (io_rden_sm),
    .io_wren_sm   (io_wren_sm),
    .int_serirq   (int_serirq),
    .serirq       (serirq)
);

initial lclk = 1'b0;
always #5 lclk = ~lclk;

task show_outputs;
    begin
        $display("t=%0t LAD=%b INT_SERIRQ=%b lpc_data_out=%h lpc_en=%b lpc_addr=%h lpc_data_in=%h io_rden_sm=%b io_wren_sm=%b",
                 $time, lad_in, int_serirq, lpc_data_out, lpc_en,
                 lpc_addr, lpc_data_in, io_rden_sm, io_wren_sm);
    end
endtask

task reset_dut;
    begin
        lframe_n      = 1'b1;
        lad_host_en   = 1'b0;
        lad_host_data = 4'h0;
        addr_hit      = 1'b0;
        din           = 8'h00;
        irq_host_en   = 1'b0;
        irq_host_data = 1'b1;
        serirq        = 8'h00;
        lreset_n      = 1'b0;
        repeat (2) @(posedge lclk);
        lreset_n      = 1'b1;
        repeat (2) @(posedge lclk);
    end
endtask

task read_case;
    input [15:0] address;
    input [7:0]  read_value;
    input integer mode;
    input integer abort_phase;
    integer i;
    begin
        reset_dut;
        addr_hit = (mode != 1);
        din = read_value;

        @(negedge lclk);
        lframe_n = 1'b0;
        lad_host_en = 1'b1;
        lad_host_data = 4'h0;
        @(posedge lclk);

        @(negedge lclk);
        lframe_n = 1'b1;
        lad_host_data = 4'h0;
        @(posedge lclk);

        for (i = 0; i < 4; i = i + 1) begin
            @(negedge lclk);
            lframe_n = (abort_phase == (i + 1)) ? 1'b0 : 1'b1;
            case (i)
                0: lad_host_data = address[15:12];
                1: lad_host_data = address[11:8];
                2: lad_host_data = address[7:4];
                default: lad_host_data = address[3:0];
            endcase
            @(posedge lclk);
        end

        @(negedge lclk);
        lframe_n = (abort_phase == 5) ? 1'b0 : 1'b1;
        lad_host_data = (mode == 2) ? 4'he : 4'hf;
        @(posedge lclk);

        lad_host_en = 1'b0;

        for (i = 0; i < 4; i = i + 1) begin
            @(negedge lclk);
            lframe_n = (abort_phase == (6 + i)) ? 1'b0 : 1'b1;
            @(posedge lclk);
            #1 show_outputs;
        end

        lframe_n = 1'b1;
        repeat (2) @(posedge lclk);
        #1 show_outputs;
    end
endtask

task read_valid;
    input [15:0] address;
    input [7:0]  read_value;
    begin
        read_case(address, read_value, 0, 0);
    end
endtask

task read_miss;
    begin
        read_case(16'ha5c3, 8'h3c, 1, 0);
    end
endtask

task read_bad_turnaround;
    begin
        read_case(16'h1234, 8'ha5, 2, 0);
    end
endtask

task read_frame_abort;
    begin
        read_case(16'habcd, 8'h5a, 0, 2);
    end
endtask

task read_abort_all_phases;
    integer i;
    begin
        for (i = 1; i <= 8; i = i + 1)
            read_case(16'h2468, 8'h96, 0, i);
    end
endtask

task write_case;
    input [15:0] address;
    input [7:0]  write_value;
    input integer mode;
    input integer abort_phase;
    integer i;
    begin
        reset_dut;
        addr_hit = (mode != 1);

        @(negedge lclk);
        lframe_n = 1'b0;
        lad_host_en = 1'b1;
        lad_host_data = 4'h0;
        @(posedge lclk);

        @(negedge lclk);
        lframe_n = 1'b1;
        lad_host_data = 4'h2;
        @(posedge lclk);

        for (i = 0; i < 4; i = i + 1) begin
            @(negedge lclk);
            lframe_n = (abort_phase == (i + 1)) ? 1'b0 : 1'b1;
            case (i)
                0: lad_host_data = address[15:12];
                1: lad_host_data = address[11:8];
                2: lad_host_data = address[7:4];
                default: lad_host_data = address[3:0];
            endcase
            @(posedge lclk);
        end

        @(negedge lclk);
        lframe_n = (abort_phase == 5) ? 1'b0 : 1'b1;
        lad_host_data = write_value[3:0];
        @(posedge lclk);

        @(negedge lclk);
        lframe_n = (abort_phase == 6) ? 1'b0 : 1'b1;
        lad_host_data = write_value[7:4];
        @(posedge lclk);

        @(negedge lclk);
        lframe_n = (abort_phase == 7) ? 1'b0 : 1'b1;
        lad_host_data = (mode == 2) ? 4'he : 4'hf;
        @(posedge lclk);

        lad_host_en = 1'b0;

        for (i = 0; i < 2; i = i + 1) begin
            @(negedge lclk);
            lframe_n = (abort_phase == (8 + i)) ? 1'b0 : 1'b1;
            @(posedge lclk);
            #1 show_outputs;
        end

        lframe_n = 1'b1;
        repeat (2) @(posedge lclk);
        #1 show_outputs;
    end
endtask

task write_valid;
    input [15:0] address;
    input [7:0]  write_value;
    begin
        write_case(address, write_value, 0, 0);
    end
endtask

task write_miss;
    begin
        write_case(16'h6789, 8'h21, 1, 0);
    end
endtask

task write_bad_turnaround;
    begin
        write_case(16'h1234, 8'hdc, 2, 0);
    end
endtask

task write_frame_abort;
    begin
        write_case(16'hde12, 8'ha5, 0, 5);
    end
endtask

task write_abort_all_phases;
    integer i;
    begin
        for (i = 1; i <= 9; i = i + 1)
            write_case(16'h5a69, 8'h3c, 0, i);
    end
endtask

task start_recovery;
    begin
        reset_dut;

        @(negedge lclk);
        lframe_n = 1'b0;
        lad_host_en = 1'b1;
        lad_host_data = 4'h0;
        @(posedge lclk);

        @(negedge lclk);
        lframe_n = 1'b0;
        lad_host_data = 4'h0;
        @(posedge lclk);

        @(negedge lclk);
        lframe_n = 1'b1;
        lad_host_data = 4'h1;
        @(posedge lclk);
        lad_host_en = 1'b0;

        repeat (2) @(posedge lclk);
        #1 show_outputs;
    end
endtask

task serirq_slots;
    input [7:0] request_vector;
    integer i;
    begin
        reset_dut;
        serirq = request_vector;

        irq_host_en = 1'b1;
        irq_host_data = 1'b0;
        repeat (4) @(posedge lclk);

        irq_host_data = 1'b1;
        @(posedge lclk);

        irq_host_en = 1'b0;
        #1 show_outputs;

        for (i = 0; i < 70; i = i + 1) begin
            @(posedge lclk);
            #1 show_outputs;
        end
    end
endtask

initial begin
    lreset_n      = 1'b0;
    lframe_n      = 1'b1;
    lad_host_en   = 1'b0;
    lad_host_data = 4'h0;
    addr_hit      = 1'b0;
    din           = 8'h00;
    irq_host_en   = 1'b0;
    irq_host_data = 1'b1;
    serirq        = 8'h00;

    repeat (2) @(posedge lclk);
    #1 show_outputs;

    start_recovery;

    read_valid(16'ha5c3, 8'h96);
    read_miss;
    read_bad_turnaround;
    read_frame_abort;
    read_abort_all_phases;

    write_valid(16'h5a69, 8'h3c);
    write_miss;
    write_bad_turnaround;
    write_frame_abort;
    write_abort_all_phases;

    serirq_slots(8'hff);
    serirq_slots(8'h00);
    serirq_slots(8'h55);
    serirq_slots(8'haa);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

reg clk;
reg RST_n;
reg start;
reg done_vec;
reg done_rot1;
reg done_rot2;
reg done_rot3;
reg done_inverse;
reg done_mul;

wire done;
wire valid_vec;
wire valid_regfile;
wire [1:0] opr_regfile;
wire valid_rot1;
wire valid_rot2;
wire valid_rot3;
wire valid_transpose;
wire start_transpose;
wire valid_inverse;
wire start_inverse;
wire valid_mul;

integer i;

FSM uut (
    .CLK             (clk),
    .RST_n           (RST_n),
    .start           (start),
    .done            (done),
    .done_vec        (done_vec),
    .valid_vec       (valid_vec),
    .valid_regfile   (valid_regfile),
    .opr_regfile     (opr_regfile),
    .done_rot1       (done_rot1),
    .done_rot2       (done_rot2),
    .done_rot3       (done_rot3),
    .valid_rot1      (valid_rot1),
    .valid_rot2      (valid_rot2),
    .valid_rot3      (valid_rot3),
    .valid_transpose (valid_transpose),
    .start_transpose (start_transpose),
    .done_inverse    (done_inverse),
    .valid_inverse   (valid_inverse),
    .start_inverse   (start_inverse),
    .done_mul        (done_mul),
    .valid_mul       (valid_mul)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input integer point;
    begin
        $display("TP%0d: done=%b valid_vec=%b valid_regfile=%b opr_regfile=%b valid_rot1=%b valid_rot2=%b valid_rot3=%b valid_transpose=%b start_transpose=%b valid_inverse=%b start_inverse=%b valid_mul=%b",
                 point, done, valid_vec, valid_regfile, opr_regfile,
                 valid_rot1, valid_rot2, valid_rot3, valid_transpose,
                 start_transpose, valid_inverse, start_inverse, valid_mul);
    end
endtask

task cycle;
    input integer point;
    input in_start;
    input in_done_vec;
    input in_done_rot1;
    input in_done_rot2;
    input in_done_rot3;
    input in_done_inverse;
    input in_done_mul;
    begin
        start        = in_start;
        done_vec     = in_done_vec;
        done_rot1    = in_done_rot1;
        done_rot2    = in_done_rot2;
        done_rot3    = in_done_rot3;
        done_inverse = in_done_inverse;
        done_mul     = in_done_mul;
        @(posedge clk);
        #1 observe(point);
        start        = 1'b0;
        done_vec     = 1'b0;
        done_rot1    = 1'b0;
        done_rot2    = 1'b0;
        done_rot3    = 1'b0;
        done_inverse = 1'b0;
        done_mul     = 1'b0;
    end
endtask

task reset_dut;
    input integer point;
    begin
        start        = 1'b0;
        done_vec     = 1'b0;
        done_rot1    = 1'b0;
        done_rot2    = 1'b0;
        done_rot3    = 1'b0;
        done_inverse = 1'b0;
        done_mul     = 1'b0;
        RST_n        = 1'b0;
        #2 observe(point);
        RST_n        = 1'b1;
        repeat (2) @(posedge clk);
        #1 observe(point + 1);
    end
endtask

task enter_rot_last;
    input integer point;
    begin
        cycle(point,     1, 0, 0, 0, 0, 0, 0);
        cycle(point + 1, 0, 1, 0, 0, 0, 0, 0);
        cycle(point + 2, 0, 0, 0, 0, 1, 0, 0);
        cycle(point + 3, 0, 1, 0, 0, 0, 0, 0);
        cycle(point + 4, 0, 0, 1, 1, 0, 0, 0);
        cycle(point + 5, 0, 0, 0, 0, 0, 0, 0);
    end
endtask

initial begin
    RST_n        = 1'b1;
    start        = 1'b0;
    done_vec     = 1'b0;
    done_rot1    = 1'b0;
    done_rot2    = 1'b0;
    done_rot3    = 1'b0;
    done_inverse = 1'b0;
    done_mul     = 1'b0;

    reset_dut(1);

    // Idle and transaction launch, followed by reset during VEC_START.
    cycle(3, 0, 0, 0, 0, 0, 0, 0);
    cycle(4, 1, 0, 0, 0, 0, 0, 0);
    cycle(5, 0, 0, 0, 0, 0, 0, 0);
    reset_dut(6);

    // Vector completion and VEC_ROT_BUSY count-zero no-event branch.
    cycle(8, 1, 0, 0, 0, 0, 0, 0);
    cycle(9, 0, 1, 0, 0, 0, 0, 0);
    cycle(10, 0, 0, 0, 0, 0, 0, 0);

    // Count zero: paired rotation completion and transpose request.
    cycle(11, 0, 0, 1, 1, 0, 0, 0);

    // Count one: vector completion with rotations suppressed.
    cycle(12, 0, 1, 0, 0, 0, 0, 0);

    // Count two: third-rotation completion.
    cycle(13, 0, 0, 0, 0, 1, 0, 0);

    // Count three: transition to ROT_LAST_UPDATE.
    cycle(14, 0, 0, 0, 0, 0, 0, 0);

    // ROT_LAST_UPDATE waiting branch and completion branch.
    cycle(15, 0, 0, 0, 0, 0, 0, 0);
    cycle(16, 0, 0, 1, 1, 0, 0, 0);

    // VEC_INVERSE: no completion, then completions at counts zero through two.
    cycle(17, 0, 0, 0, 0, 0, 0, 0);
    cycle(18, 0, 0, 0, 0, 0, 1, 0);
    cycle(19, 0, 0, 0, 0, 0, 0, 0);
    cycle(20, 0, 0, 0, 0, 0, 1, 0);
    cycle(21, 0, 0, 0, 0, 0, 0, 0);
    cycle(22, 0, 0, 0, 0, 0, 1, 0);

    // Count-three transition into MUL_READY.
    cycle(23, 0, 0, 0, 0, 0, 0, 0);

    // MUL_READY progression from count zero through count eight.
    for (i = 0; i < 8; i = i + 1)
        cycle(24 + i, 0, 0, 0, 0, 0, 0, 0);
    cycle(32, 0, 0, 0, 0, 0, 0, 0);

    // MUL_BUSY no-completion branch and completion events.
    cycle(33, 0, 0, 0, 0, 0, 0, 0);
    for (i = 0; i < 8; i = i + 1)
        cycle(34 + i, 0, 0, 0, 0, 0, 0, 1);

    // Terminal MUL_BUSY observation and return to IDLE.
    done_mul = 1'b1;
    #1 observe(42);
    @(posedge clk);
    #1 observe(43);
    done_mul = 1'b0;

    // Supplementary transaction for rotation-completion combinations.
    cycle(44, 1, 0, 0, 0, 0, 0, 0);
    cycle(45, 0, 1, 0, 0, 0, 0, 0);

    // Individual completions do not service VEC_ROT_BUSY by themselves.
    cycle(46, 0, 0, 1, 0, 0, 0, 0);
    cycle(47, 0, 0, 0, 1, 0, 0, 0);

    // At counts zero and one, service via another input while only one
    // rotation reports done; neither event requests transpose.
    cycle(48, 0, 1, 1, 0, 0, 0, 0);
    cycle(49, 0, 0, 0, 1, 1, 0, 0);
    cycle(50, 0, 0, 0, 0, 1, 0, 0);
    cycle(51, 0, 0, 0, 0, 0, 0, 0);

    // ROT_LAST_UPDATE: individual waits before paired completion.
    cycle(52, 0, 0, 1, 0, 0, 0, 0);
    cycle(53, 0, 0, 0, 1, 0, 0, 0);
    cycle(54, 0, 0, 1, 1, 0, 0, 0);

    // Reset from VEC_INVERSE.
    reset_dut(55);

    // Reset from ROT_LAST_UPDATE.
    enter_rot_last(57);
    reset_dut(63);

    // Reset from MUL_READY after its start levels have been observed.
    enter_rot_last(65);
    cycle(71, 0, 0, 1, 1, 0, 0, 0);
    cycle(72, 0, 0, 0, 0, 0, 1, 0);
    cycle(73, 0, 0, 0, 0, 0, 1, 0);
    cycle(74, 0, 0, 0, 0, 0, 1, 0);
    cycle(75, 0, 0, 0, 0, 0, 0, 0);
    cycle(76, 0, 0, 0, 0, 0, 0, 0);
    reset_dut(77);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam FLIT_WIDTH = 16;
localparam TABLE_DEPTH = 8;

// Inputs
reg clk;
reg rst;
reg Arb_valid;
reg [1:0] SEL_VC;
reg VC_selected;
reg [FLIT_WIDTH-1:0] read_O;
reg VC_ANSWER;
reg SW_ANSWER;
reg ROUTE_DONE;
reg [2:0] DIRECTION;

// Outputs
wire ready;
wire [3:0] Route_info;
wire Start_route;
wire [4:0] Vc_request;
wire valid_vc_req;
wire [2:0] Sw_request;
wire Valid_sw_req;
wire clear;

integer i;
integer phase;

CONTROLLER #(
    .flit_width(FLIT_WIDTH),
    .MAX_Packet_NUM(TABLE_DEPTH)
) uut (
    .clk(clk),
    .rst(rst),
    .Arb_valid(Arb_valid),
    .SEL_VC(SEL_VC),
    .VC_selected(VC_selected),
    .read_O(read_O),
    .VC_ANSWER(VC_ANSWER),
    .SW_ANSWER(SW_ANSWER),
    .ROUTE_DONE(ROUTE_DONE),
    .DIRECTION(DIRECTION),
    .ready(ready),
    .Route_info(Route_info),
    .Start_route(Start_route),
    .Vc_request(Vc_request),
    .valid_vc_req(valid_vc_req),
    .Sw_request(Sw_request),
    .Valid_sw_req(Valid_sw_req),
    .clear(clear)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [255:0] label;
    begin
        $display(
            "t=%0t %0s phase=%0d rst=%b flit=%h sel=%b dir=%b ready=%b Route_info=%h Start_route=%b Vc_request=%b valid_vc_req=%b Sw_request=%b Valid_sw_req=%b clear=%b",
            $time, label, phase, rst, read_O, SEL_VC, DIRECTION,
            ready, Route_info, Start_route, Vc_request,
            valid_vc_req, Sw_request, Valid_sw_req, clear
        );
    end
endtask

task step;
    input [255:0] label;
    begin
        @(posedge clk);
        #1;
        observe(label);
    end
endtask

task reset_dut;
    begin
        @(negedge clk);
        #2;
        rst = 0;
        #1;
        observe("asynchronous reset");
        Arb_valid = 0;
        SEL_VC = 0;
        VC_selected = 0;
        read_O = 0;
        VC_ANSWER = 0;
        SW_ANSWER = 0;
        ROUTE_DONE = 0;
        DIRECTION = 0;
        repeat (2) @(posedge clk);
        #1;
        observe("reset held");
        @(negedge clk);
        rst = 1;
        #1;
        observe("reset released");
    end
endtask

// Read route entries through idle output ports only.
task scan_routes;
    integer entry;
    begin
        for (entry = 0; entry < TABLE_DEPTH; entry = entry + 1) begin
            @(negedge clk);
            read_O = 0;
            read_O[6:4] = entry;
            SEL_VC = entry % 4;
            #1;
            observe("idle route scan");
        end
    end
endtask

// fast=1 supplies acknowledgements before their corresponding phases.
// in_store=1 continues a transfer accepted on the preceding DONE exit.
task transfer;
    input [2:0] sequence_id;
    input [1:0] flit_type;
    input [3:0] route_field;
    input [2:0] direction;
    input [1:0] vc;
    input fast;
    input in_store;
    input keep_next;
    begin
        @(negedge clk);
        read_O = 0;
        read_O[10:7] = route_field;
        read_O[6:4] = sequence_id;
        read_O[3:2] = flit_type;
        SEL_VC = vc;
        DIRECTION = direction;
        Arb_valid = !in_store;
        VC_selected = fast;
        ROUTE_DONE = fast;
        VC_ANSWER = fast;
        SW_ANSWER = fast;
        #1;
        observe("flit presented");

        if (!in_store)
            step("FLIT_STORE");

        if (!fast) begin
            repeat (2) @(posedge clk);
            #1;
            observe("channel selection stalled");
            @(negedge clk);
            VC_selected = 1;
            #1;
            observe("channel selection asserted");
        end
        step("TYPE_SELECTION");

        @(negedge clk);
        Arb_valid = 0;
        VC_selected = 0;
        step("decoded type");

        if (flit_type == 2'b00) begin
            if (!fast) begin
                repeat (2) @(posedge clk);
                #1;
                observe("routing stalled");
                @(negedge clk);
                ROUTE_DONE = 1;
                #1;
                observe("route completion before edge");
            end
            step("ASK_VC after routing");
        end

        if (!fast) begin
            repeat (2) @(posedge clk);
            #1;
            observe("VC request stalled");
            @(negedge clk);
            ROUTE_DONE = 0;
            VC_ANSWER = 1;
            #1;
            observe("VC answer before edge");
        end
        step("ASK_SW");

        if (!fast) begin
            @(negedge clk);
            VC_ANSWER = 0;
            repeat (2) @(posedge clk);
            #1;
            observe("switch request stalled");
            @(negedge clk);
            SW_ANSWER = 1;
            #1;
            observe("switch answer before edge");
        end
        step("DONE");

        @(negedge clk);
        Arb_valid = keep_next;
        VC_selected = 0;
        ROUTE_DONE = 0;
        VC_ANSWER = 0;
        SW_ANSWER = 0;
        #1;
        observe("DONE before exit");
        step("DONE exit");
    end
endtask

initial begin
    rst = 0;
    Arb_valid = 0;
    SEL_VC = 0;
    VC_selected = 0;
    read_O = 0;
    VC_ANSWER = 0;
    SW_ANSWER = 0;
    ROUTE_DONE = 0;
    DIRECTION = 0;
    phase = -1;

    // Wait 100 ns for global reset to finish.
    #100;
    reset_dut;
    scan_routes;
    repeat (3) @(posedge clk);
    #1;
    observe("idle held");

    // Populate all entries; alternate immediate and delayed handshakes.
    for (i = 0; i < TABLE_DEPTH; i = i + 1) begin
        #1;
        transfer(i, 2'b00, i, i, i % 4, i % 2, 0, 0);
    end

    // Both nonterminating types reuse and preserve stored routes.
    for (i = 0; i < TABLE_DEPTH; i = i + 1) begin
        #1;
        transfer(i, 2'b01, 15-i, 0, i % 4, 1, 0, 0);
        transfer(i, 2'b11, i, 7, (i+1) % 4, 0, 0, 0);
    end
    scan_routes;

    // Replace existing routes and cover remaining routing-field values.
    for (i = 0; i < TABLE_DEPTH; i = i + 1) begin
        #1;
        transfer(i, 2'b00, 15-i, 7-i, (i+2) % 4, i % 2, 0, 0);
    end
    scan_routes;

    // Clear each entry and observe every entry after each termination.
    for (i = 0; i < TABLE_DEPTH; i = i + 1) begin
        #1;
        transfer(i, 2'b10, i, 0, i % 4, i % 2, 0, 0);
        scan_routes;
    end

    // Consecutive transfers through DONE -> FLIT_STORE.
    reset_dut;
    transfer(7, 2'b00, 15, 5, 3, 0, 0, 1);
    transfer(7, 2'b01,  0, 0, 1, 1, 1, 1);
    transfer(7, 2'b10, 15, 0, 2, 0, 1, 0);
    transfer(7, 2'b11,  0, 0, 0, 1, 0, 0);

    // Reset in IDLE, FLIT_STORE, TYPE_SELECTION, ROUTING,
    // ASK_VC, ASK_SW, and DONE, with retained route data present.
    for (phase = 0; phase < 7; phase = phase + 1) begin
        #1;
        reset_dut;
        transfer(3, 2'b00, 9, 6, 2, 1, 0, 0);

        @(negedge clk);
        read_O = 0;
        read_O[10:7] = 4'hf;
        read_O[6:4] = 7;
        DIRECTION = 5;
        SEL_VC = 3;
        #1;
        observe("reset target IDLE");

        if (phase >= 1) begin
            @(negedge clk);
            Arb_valid = 1;
            step("reset target FLIT_STORE");
        end
        if (phase >= 2) begin
            @(negedge clk);
            Arb_valid = 0;
            VC_selected = 1;
            step("reset target TYPE_SELECTION");
        end
        if (phase >= 3)
            step("reset target ROUTING");
        if (phase >= 4) begin
            @(negedge clk);
            ROUTE_DONE = 1;
            step("reset target ASK_VC");
        end
        if (phase >= 5) begin
            @(negedge clk);
            VC_ANSWER = 1;
            step("reset target ASK_SW");
        end
        if (phase >= 6) begin
            @(negedge clk);
            SW_ANSWER = 1;
            step("reset target DONE");
        end

        reset_dut;
        scan_routes;
    end

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

// Inputs
reg clk;
reg rst;
reg down_velocity, next_picture_delay;
reg [1:0] level;
reg [4:0] key_alphabet;
reg [7:0] random;
reg [9:0] h_cnt, v_cnt;

// Outputs
wire [4:0] life;
wire [9:0] point;
wire [15:0] pixel_addr;

integer test_id, variant;
integer i, j;
integer x_edge [0:3];
integer y_edge [0:3];
integer mask_code [0:5];

mem_addr_generator uut (
    .rst(rst),
    .clk(clk),
    .down_velocity(down_velocity),
    .next_picture_delay(next_picture_delay),
    .level(level),
    .key_alphabet(key_alphabet),
    .random(random),
    .h_cnt(h_cnt),
    .v_cnt(v_cnt),
    .life(life),
    .point(point),
    .pixel_addr(pixel_addr)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [8*32-1:0] label;
    begin
        #1;
        $display("test=%0d variant=%0d t=%0t %0s rst=%b clk=%b down=%b picture=%b level=%0d key=%0d random=%0d h=%0d v=%0d life=%0d point=%0d pixel_addr=%0d",
                 test_id, variant, $time, label, rst, clk,
                 down_velocity, next_picture_delay, level,
                 key_alphabet, random, h_cnt, v_cnt,
                 life, point, pixel_addr);
    end
endtask

task pixel;
    input [8*32-1:0] label;
    input integer x, y;
    begin
        h_cnt = x;
        v_cnt = y;
        observe(label);
    end
endtask

task window;
    input integer x, y;
    begin
        pixel("top_left",     x,      y);
        pixel("top_right",    x + 49, y);
        pixel("bottom_left",  x,      y + 49);
        pixel("bottom_right", x + 49, y + 49);
        pixel("interior",     x + 17, y + 23);
        pixel("left_outside", x - 1,  y + 25);
        pixel("right_outside",x + 50, y + 25);
        // At y=0, truncation drives the maximum coordinate, 1023.
        pixel("above_or_max", x + 25, y - 1);
        pixel("below",        x + 25, y + 50);
    end
endtask

task reset_dut;
    begin
        @(negedge clk);
        rst = 1;
        down_velocity = 0;
        next_picture_delay = 1;
        level = 0;
        key_alphabet = 31;
        random = 0;
        h_cnt = 0;
        v_cnt = 0;
        observe("reset_assert");
        @(negedge clk);
        rst = 0;
        observe("reset_release");
    end
endtask

task picture;
    input [4:0] code;
    input [2:0] col;
    begin
        @(negedge clk);
        random = {code, col};
        next_picture_delay = 0;
        observe("random_capture");

        @(negedge clk);
        random = ~random;
        next_picture_delay = 1;
        observe("picture_rise");

        @(posedge clk);
        observe("clock_after_picture");
    end
endtask

task fill_uniform;
    input [4:0] code;
    input [2:0] col;
    integer n;
    begin
        for (n = 0; n < 6; n = n + 1) begin
            picture(code, col);
            #1;
        end
    end
endtask

task move;
    begin
        @(negedge clk);
        down_velocity = 1;
        observe("movement_rise");
        @(negedge clk);
        down_velocity = 0;
        observe("movement_fall");
    end
endtask

initial begin
    rst = 1;
    down_velocity = 0;
    next_picture_delay = 1;
    level = 0;
    key_alphabet = 31;
    random = 0;
    h_cnt = 0;
    v_cnt = 0;
    test_id = 1;
    variant = 0;

    x_edge[0] = 119;
    x_edge[1] = 120;
    x_edge[2] = 519;
    x_edge[3] = 520;
    y_edge[0] = 249;
    y_edge[1] = 250;
    y_edge[2] = 349;
    y_edge[3] = 350;

    // 1: Reset and initialized rendering.
    #100;
    observe("power_on_reset");
    @(negedge clk);
    rst = 0;
    observe("power_on_release");
    window(370, 0);
    window(270, 50);
    window(420, 100);
    window(370, 150);
    window(120, 200);
    window(120, 250);
    pixel("minimum_coordinates", 0, 0);
    pixel("maximum_coordinates", 1023, 1023);

    // 2: Every source code; all columns; capture isolation.
    test_id = 2;
    for (i = 0; i < 32; i = i + 1) begin
        variant = i;
        reset_dut;
        h_cnt = 120 + 50 * (i % 8);
        v_cnt = 0;
        picture(i, i % 8);
        window(120 + 50 * (i % 8), 0);
        #1;
    end

    // 3: Distinguishable pipeline entries and movement wraparound.
    test_id = 3;
    variant = 0;
    reset_dut;
    for (i = 0; i < 6; i = i + 1) begin
        picture(i + 1, i);
        #1;
    end
    for (i = 0; i < 6; i = i + 1) begin
        window(120 + 50 * (5 - i), 50 * i);
        #1;
    end

    pixel("fixed_movement_probe", 370, 49);
    for (i = 0; i < 9; i = i + 1) begin
        variant = i + 1;
        move;
        #1;
    end
    for (i = 0; i < 6; i = i + 1) begin
        window(120 + 50 * (5 - i), 50 * i + 45);
        #1;
    end
    variant = 10;
    move;
    for (i = 0; i < 6; i = i + 1) begin
        window(120 + 50 * (5 - i), 50 * i);
        #1;
    end

    // 4: Empty-entry rendering and side-region boundaries.
    test_id = 4;
    variant = 0;
    reset_dut;
    fill_uniform(0, 0);
    for (i = 0; i < 6; i = i + 1) begin
        window(120, 50 * i);
        #1;
    end
    for (i = 0; i < 4; i = i + 1) begin
        for (j = 0; j < 4; j = j + 1) begin
            pixel("side_boundary", x_edge[i], y_edge[j]);
            #1;
        end
        #1;
    end
    pixel("left_port_limit", 0, 300);
    pixel("right_port_limit", 1023, 300);

    // 5: Scoring branches at every level.
    test_id = 5;
    for (i = 0; i < 4; i = i + 1) begin
        variant = i;
        reset_dut;
        level = i;
        key_alphabet = 0;
        picture(1, 0);
        key_alphabet = 31;
        picture(1, 0);
        key_alphabet = 4;
        picture(1, 0);
        key_alphabet = 13;
        picture(1, 0);
        key_alphabet = 0;
        picture(1, 0);
        key_alphabet = 18;
        picture(1, 0);
        key_alphabet = 1;
        picture(1, 0);
        #1;
    end

    // 6: Score rollover using repeated empty positions.
    test_id = 6;
    variant = 0;
    reset_dut;
    level = 3;
    fill_uniform(0, 0);
    key_alphabet = 0;
    for (i = 0; i < (1024 / 7 + 2); i = i + 1) begin
        variant = i;
        picture(0, 0);
        #1;
    end

    // 7: Stable, fourth-only, fifth-only, and both-entry changes.
    test_id = 7;
    for (i = 0; i < 4; i = i + 1) begin
        variant = i;
        reset_dut;
        for (j = 0; j < 6; j = j + 1) begin
            mask_code[j] = 1;
            #1;
        end
        case (i)
            1: mask_code[3] = 2;
            2: begin
                mask_code[2] = 2;
                mask_code[3] = 2;
            end
            3: begin
                mask_code[2] = 2;
                mask_code[3] = 3;
            end
        endcase
        for (j = 0; j < 6; j = j + 1) begin
            picture(mask_code[j], 0);
            #1;
        end

        move;
        pixel("bottom_unmasked", 120, 255);
        @(negedge clk);
        key_alphabet = 1;
        observe("match_before_clock");
        @(posedge clk);
        observe("match_after_clock");

        @(negedge clk);
        key_alphabet = 31;
        observe("key_removed");
        repeat (2) @(posedge clk);
        observe("mask_persistence");

        picture(1, 0);
        repeat (2) @(posedge clk);
        observe("tracked_entry_response");
        #1;
    end

    // 8: Life exhaustion, saturation, frozen score, and GAME OVER.
    test_id = 8;
    variant = 0;
    reset_dut;
    for (i = 0; i < 20; i = i + 1) begin
        variant = i;
        picture(1, 0);
        #1;
    end
    level = 3;
    key_alphabet = 1;
    picture(1, 0);
    fill_uniform(0, 0);
    key_alphabet = 0;
    picture(0, 0);

    pixel("game_over_before_move", 220, 190);
    move;
    for (i = 0; i < 2; i = i + 1) begin
        for (j = 0; j < 4; j = j + 1) begin
            window(220 + 50 * j, 190 + 50 * i);
            #1;
        end
        #1;
    end
    pixel("old_letter_location", 370, 0);
    pixel("old_side_region", 119, 250);
    pixel("minimum_coordinates", 0, 0);
    pixel("maximum_coordinates", 1023, 1023);

    // 9: Async recovery with an uninserted pending item.
    test_id = 9;
    variant = 0;
    @(negedge clk);
    random = {5'd26, 3'd7};
    next_picture_delay = 0;
    observe("pending_before_reset");
    key_alphabet = 31;
    level = 0;
    h_cnt = 370;
    v_cnt = 0;
    #2;
    rst = 1;
    observe("async_recovery");
    @(negedge clk);
    rst = 0;
    observe("recovery_release");
    window(370, 0);
    window(270, 50);
    window(420, 100);
    window(370, 150);
    window(120, 200);
    window(120, 250);

    @(negedge clk);
    next_picture_delay = 1;
    observe("insert_after_pending_reset");
    window(120, 0);
    window(470, 0);

    $display("===========End=========== life=%0d point=%0d pixel_addr=%0d",
             life, point, pixel_addr);
    $finish;
end

endmodule

