module testbench;

reg clk;
reg [511:0] data_in;
reg [15:0] DetectedLanes;
reg wr;
reg [63:0] wr_valid, STP_IN, SDP_IN, END_IN;
reg [2:0] gen;

wire [79:0] length;
wire [511:0] data_out;
wire wr_out;
wire [63:0] wr_valid_out, STP_out, SDP_out, END_out;

