    .pclk(clk),
    .data_in(data_in),
    .DetectedLanes(DetectedLanes),
    .wr(wr),
    .wr_valid(wr_valid),
    .STP_IN(STP_IN),
    .SDP_IN(SDP_IN),
    .END_IN(END_IN),
    .gen(gen),
    .length(length),
    .data_out(data_out),
    .wr_out(wr_out),
    .wr_valid_out(wr_valid_out),
    .STP_out(STP_out),
    .SDP_out(SDP_out),
    .END_out(END_out)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [8*48-1:0] label;
    input [8*8-1:0] phase;
    begin
        $display("t=%0t case=%0s phase=%0s gen=%0d STP_IN=%h END_IN=%h length=%h data_out=%h wr_out=%b wr_valid_out=%h STP_out=%h SDP_out=%h END_out=%h",
                 $time, label, phase, gen, STP_IN, END_IN,
                 length, data_out, wr_out, wr_valid_out,
                 STP_out, SDP_out, END_out);
    end
endtask

task beat;
    input [8*48-1:0] label;
    input [2:0] generation;
    input [63:0] starts;
    input [63:0] ends;
    begin
        @(negedge clk);
        gen = generation;
        STP_IN = starts;
        END_IN = ends;
        #1;
        observe(label, "pre");
        @(posedge clk);
        #1;
        observe(label, "post");
    end
endtask

task initialize_group;
    begin
        @(negedge clk);
        data_in = 0;
        DetectedLanes = 0;
        wr = 0;
        wr_valid = 0;
        STP_IN = 0;
        SDP_IN = 0;
        END_IN = 0;
        gen = 3;
        @(posedge clk);
        #1;
        observe("empty initialization", "post");
    end
endtask

initial begin
    data_in = 0;
    DetectedLanes = 0;
    wr = 0;
    wr_valid = 0;
    STP_IN = 0;
    SDP_IN = 0;
    END_IN = 0;
    gen = 0;

    // Wait 100 ns for global initialization.
    #100;
    initialize_group;

    // Generation selection and changing registered data.
    for (i = 0; i < 8; i = i + 1) begin
        #1;
        data_in = {16{32'h01234567 ^ (32'h11111111 * i)}};
        wr = i % 2;
        wr_valid = 64'hAAAAAAAAAAAAAAAA;
        SDP_IN = 64'h5555555555555555;
        DetectedLanes = 16'hFFFF;
        beat("generation sweep", i,
             64'h1, 64'h8000000000000000);
    end

    // Independently vary inputs that do not qualify extraction.
    initialize_group;
    beat("qualifiers zero", 3, 64'h1, 64'h80);
    wr = 1;
    beat("wr only", 3, 64'h1, 64'h80);
    wr = 0;
    wr_valid = 64'hFFFFFFFFFFFFFFFF;
    beat("wr_valid only", 3, 64'h1, 64'h80);
    wr_valid = 0;
    SDP_IN = 64'hFFFFFFFFFFFFFFFF;
    beat("SDP only", 3, 64'h1, 64'h80);
    SDP_IN = 0;
    DetectedLanes = 16'hFFFF;
    beat("DetectedLanes only", 3, 64'h1, 64'h80);
    data_in = {512{1'b1}};
    wr = 1;
    wr_valid = 64'hFFFFFFFFFFFFFFFF;
    SDP_IN = 64'hFFFFFFFFFFFFFFFF;
    beat("all payload and sidebands one", 3, 64'h1, 64'h80);
    data_in = {64{8'hA5}};
    wr_valid = 64'h5555555555555555;
    SDP_IN = 64'hAAAAAAAAAAAAAAAA;
    beat("alternating pass through", 3, 64'h1, 64'h80);
    initialize_group;

    // Every end position and every start position.
    for (i = 0; i < 64; i = i + 1) begin
        #1;
        beat("end position sweep", 3, 64'h1, 64'h1 << i);
    end
    initialize_group;
    for (i = 0; i < 64; i = i + 1) begin
        #1;
        beat("start position sweep", 4,
             64'h1 << i, 64'h8000000000000000);
    end

    // Result packing, aligned packets, and unequal lengths.
    initialize_group;
    beat("sixteen aligned packets", 5,
         64'h1111111111111111, 64'h8888888888888888);
    beat("three unequal adjacent packets", 5,
         (64'h1 << 0) | (64'h1 << 4) | (64'h1 << 12),
         (64'h1 << 3) | (64'h1 << 11) | (64'h1 << 23));
    beat("aligned packets separated by gaps", 5,
         (64'h1 << 0) | (64'h1 << 16) | (64'h1 << 48),
         (64'h1 << 3) | (64'h1 << 23) | (64'h1 << 63));
    beat("empty after populated results", 5, 0, 0);

    // Unmatched markers, repeated starts, and retained phase.
    initialize_group;
    beat("unmatched ends without start", 3, 0,
         (64'h1 << 0) | (64'h1 << 31) | (64'h1 << 63));
    beat("unmatched ends around packet", 3, 64'h1 << 8,
         (64'h1 << 0) | (64'h1 << 15) | (64'h1 << 63));
    beat("start without end", 3, 64'h1, 0);
    beat("end in following beat", 3, 0, 64'h8000000000000000);
    beat("aligned repeated start", 3,
         (64'h1 << 0) | (64'h1 << 8), 64'h1 << 15);
    beat("unaligned repeated start", 3,
         (64'h1 << 0) | (64'h1 << 3), 64'h1 << 3);
    beat("unaligned regions with gap", 3,
         (64'h1 << 0) | (64'h1 << 8),
         (64'h1 << 2) | (64'h1 << 8));
    beat("coincident markers after active region", 3,
         (64'h1 << 0) | (64'h1 << 7), 64'h1 << 7);
    beat("coincident markers at both boundaries", 3,
         64'h8000000000000001, 64'h8000000000000001);

    // Initial four-position region followed by dense end events.
    initialize_group;
    for (i = 16; i <= 33; i = i + 1) begin
        #1;
        beat("end event count 16 through 33", 3,
             64'h1 | (64'h1 << 35),
             (64'hFFFFFFFFFFFFFFFF >> (64-i)) << 3);
    end
    beat("48 end events with wrapped fields", 3,
         64'h1 | (64'h1 << 35),
         64'h0000FFFFFFFFFFFF << 3);
    beat("61 end events through last position", 3,
         64'h1 | (64'h1 << 35), 64'hFFFFFFFFFFFFFFF8);
    beat("64 unmatched end events", 3, 0, 64'hFFFFFFFFFFFFFFFF);
    beat("64 simultaneous start and end events", 3,
         64'hFFFFFFFFFFFFFFFF, 64'hFFFFFFFFFFFFFFFF);

    // Consecutive enabled, disabled, and empty beats.
    initialize_group;
    beat("enabled populated beat", 3, 64'h1, 64'h8000000000000000);
    beat("disabled with same markers", 2, 64'h1, 64'h8000000000000000);
    beat("reenabled with same markers", 4, 64'h1, 64'h8000000000000000);
    beat("empty final beat", 4, 0, 0);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam signed [35:0] ONE = 36'sd512;

// Inputs
reg clk;
reg [13:0] number_of_pulses;
reg [4:0] SW;
reg PID_timer;
reg reset;
reg signed [35:0] KP, KI, KD;

// Outputs
wire reset_nop_0;
wire [13:0] signal_dc;

integer test_id;
integer i, j;
integer boundary_gain;

PID uut (
    .i_Clk(clk),
    .number_of_pulses(number_of_pulses),
    .SW(SW),
    .PID_timer(PID_timer),
    .reset_nop_0(reset_nop_0),
    .reset(reset),
    .signal_dc(signal_dc),
    .KP(KP),
    .KI(KI),
    .KD(KD)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input integer phase;
    begin
        $display("t=%0t case=%0d phase=%0d reset_nop_0=%b signal_dc=%0d",
                 $time, test_id, phase, reset_nop_0, signal_dc);
    end
endtask

task sample_after;
    input integer cycles;
    input integer phase;
    begin
        repeat (cycles) @(posedge clk);
        #1;
        observe(phase);
    end
endtask

task clean;
    begin
        @(negedge clk);
        reset = 1;
        PID_timer = 0;
        number_of_pulses = 0;
        SW = 0;
        KP = 0;
        KI = 0;
        KD = 0;
        sample_after(2, -2);
        @(negedge clk);
        reset = 0;
        sample_after(1, -1);
    end
endtask

task launch;
    input [4:0] target;
    input [13:0] pulses;
    begin
        @(negedge clk);
        SW = target;
        number_of_pulses = pulses;
        PID_timer = 1;
        sample_after(1, 0);
        @(negedge clk);
        PID_timer = 0;
    end
endtask

task finish_update;
    integer cycle;
    begin
        for (cycle = 1; cycle <= 8; cycle = cycle + 1) begin
            @(posedge clk);
            #1;
            observe(cycle);
        end
    end
endtask

task update;
    input [4:0] target;
    input [13:0] pulses;
    begin
        launch(target, pulses);
        finish_update;
    end
endtask

initial begin
    test_id = 0;
    number_of_pulses = 0;
    SW = 0;
    PID_timer = 0;
    reset = 1;
    KP = 0;
    KI = 0;
    KD = 0;

    // Wait 100 ns for global reset to finish.
    #100;
    observe(-3);

    // 1: Reset priority, synchronous assertion, and idle retention.
    test_id = 1;
    clean;
    @(negedge clk);
    KP = ONE;
    update(5'd7, 14'd0);
    sample_after(3, 9);
    @(negedge clk);
    reset = 1;
    PID_timer = 1;
    #1;
    observe(10);
    sample_after(2, 11);
    @(negedge clk);
    reset = 0;
    sample_after(1, 0);
    @(negedge clk);
    PID_timer = 0;
    finish_update;

    // 2: Zero gains with nonzero error and repeated history updates.
    test_id = 2;
    clean;
    update(5'd31, 14'd0);
    update(5'd0, 14'd16383);

    // 10..15: Feedback around zero error, plus feedback endpoints.
    for (i = 0; i < 6; i = i + 1) begin
        @(negedge clk);
        test_id = 10 + i;
        clean;
        @(negedge clk);
        KP = ONE;
        case (i)
            0: update(5'd5, 14'd0);
            1: update(5'd5, 14'd1);
            2: update(5'd5, 14'd255);
            3: update(5'd5, 14'd256);
            4: update(5'd5, 14'd257);
            5: update(5'd5, 14'd16383);
        endcase
    end

    // 20..25: Isolated P/I/D, both gain signs, and history changes.
    for (i = 0; i < 6; i = i + 1) begin
        @(negedge clk);
        test_id = 20 + i;
        clean;
        @(negedge clk);
        case (i)
            0: KP = ONE;
            1: KP = -ONE;
            2: KI = ONE;
            3: KI = -ONE;
            4: KD = ONE;
            5: KD = -ONE;
        endcase
        update(5'd8, 14'd0);
        update(5'd8, 14'd0);
        update(5'd12, 14'd0);
        update(5'd4, 14'd0);
        update(5'd0, 14'd16383);
        update(5'd0, 14'd0);
    end

    // 30..34: Upper limit and command-field wrap boundaries.
    for (i = 0; i < 5; i = i + 1) begin
        @(negedge clk);
        test_id = 30 + i;
        clean;
        @(negedge clk);
        case (i)
            0: boundary_gain = 9999;
            1: boundary_gain = 10000;
            2: boundary_gain = 10001;
            3: boundary_gain = 16383;
            4: boundary_gain = 16384;
        endcase
        KP = ONE * boundary_gain;
        update(5'd1, 14'd0);
    end

    // 40: Combined fractional gains, error changes, and history reset.
    test_id = 40;
    clean;
    @(negedge clk);
    KP = 36'sd768;
    KI = 36'sd128;
    KD = -36'sd256;
    update(5'd31, 14'd1);
    update(5'd31, 14'd1);
    update(5'd0, 14'd16383);
    update(5'd9, 14'd257);
    clean;
    @(negedge clk);
    KP = 36'sd768;
    KI = 36'sd128;
    KD = -36'sd256;
    update(5'd31, 14'd1);

    // 41..42: Signed gain extremes and fixed-width truncation.
    for (i = 0; i < 2; i = i + 1) begin
        @(negedge clk);
        test_id = 41 + i;
        clean;
        @(negedge clk);
        case (i)
            0: begin
                KP = 36'h7ffffffff;
                KI = 36'h800000000;
                KD = 36'h7ffffffff;
            end
            1: begin
                KP = 36'h800000000;
                KI = 36'h7ffffffff;
                KD = 36'h800000000;
            end
        endcase
        update(5'd31, 14'd0);
        update(5'd0, 14'd16383);
        update(5'd31, 14'd0);
    end

    // 50: Captured target/feedback and ignored busy request.
    test_id = 50;
    clean;
    @(negedge clk);
    KP = ONE;
    update(5'd3, 14'd0);
    launch(5'd9, 14'd0);
    SW = 0;
    number_of_pulses = 16383;
    PID_timer = 1;
    sample_after(1, 1);
    @(negedge clk);
    PID_timer = 0;
    for (j = 2; j <= 8; j = j + 1) begin
        @(posedge clk);
        #1;
        observe(j);
    end
    sample_after(9, 9);

    // 51: Continuous request defers publication across two updates.
    test_id = 51;
    clean;
    @(negedge clk);
    KP = ONE;
    update(5'd3, 14'd0);
    @(negedge clk);
    SW = 9;
    PID_timer = 1;
    for (j = 0; j <= 15; j = j + 1) begin
        @(posedge clk);
        #1;
        observe(j);
    end
    @(negedge clk);
    PID_timer = 0;
    sample_after(1, 16);
    sample_after(2, 17);

    // 52: Gains are supplied live during the calculation.
    test_id = 52;
    clean;
    @(negedge clk);
    KP = ONE;
    KI = ONE;
    KD = ONE;
    update(5'd4, 14'd0);
    launch(5'd9, 14'd0);
    sample_after(3, 3);
    @(negedge clk);
    KP = 2 * ONE;
    KI = ONE / 2;
    sample_after(1, 4);
    @(negedge clk);
    KP = 0;
    KI = 0;
    KD = -ONE;
    sample_after(1, 5);
    @(negedge clk);
    KD = 0;
    for (j = 6; j <= 8; j = j + 1) begin
        @(posedge clk);
        #1;
        observe(j);
    end

    // 61..67: Reset pulse in each processing state.
    for (i = 1; i <= 7; i = i + 1) begin
        @(negedge clk);
        test_id = 60 + i;
        clean;
        @(negedge clk);
        KP = ONE;
        KI = ONE;
        update(5'd3, 14'd0);
        launch(5'd9, 14'd0);
        for (j = 1; j <= 8; j = j + 1) begin
            reset = (j == i);
            @(posedge clk);
            #1;
            observe(j);
            @(negedge clk);
        end
        reset = 0;
        update(5'd9, 14'd0);
    end

    // 70: Reset held during processing and into the waiting state.
    test_id = 70;
    clean;
    @(negedge clk);
    KP = ONE;
    KI = ONE;
    update(5'd3, 14'd0);
    launch(5'd9, 14'd0);
    reset = 1;
    finish_update;
    sample_after(2, 9);
    @(negedge clk);
    reset = 0;
    sample_after(1, 10);
    update(5'd9, 14'd0);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam MSTATUS   = 12'h300;
localparam MISA      = 12'h301;
localparam MIE       = 12'h304;
localparam MTVEC     = 12'h305;
localparam MSCRATCH  = 12'h340;
localparam MEPC      = 12'h341;
localparam MCAUSE    = 12'h342;
localparam MTVAL     = 12'h343;
localparam MIP       = 12'h344;
localparam MVENDORID = 12'hF11;
localparam MARCHID   = 12'hF12;
localparam MIMPID    = 12'hF13;
localparam MHARTID   = 12'hF14;

localparam RW = 2'b01;
localparam RS = 2'b10;
localparam RC = 2'b11;

// 2'b1x is intentionally not one of the legal CSR operation encodings.
// Its reduction OR is 1, so it enters the CSR operation decode while
// selecting the inner default arm of each writable CSR case statement.
localparam INVALID_CSR_OP = 2'b1x;

reg clk;
reg reset;
reg [11:0] index;
reg [31:0] data;
reg [1:0] opcode;
reg mret;
reg exception;
reg [3:0] exceptionType;
reg [31:0] exceptionPC;
reg NMI;
reg timerInterrupt;
reg [15:0] externalInterrupts;
reg stalled;

wire interrupt_reg;
wire [31:0] csrData;
wire [31:0] nextPC;

integer ext_line;

Zicsr uut (
    .clk(clk),
    .reset(reset),
    .index(index),
    .data(data),
    .opcode(opcode),
    .mret(mret),
    .exception(exception),
    .exceptionType(exceptionType),
    .exceptionPC(exceptionPC),
    .NMI(NMI),
    .timerInterrupt(timerInterrupt),
    .externalInterrupts(externalInterrupts),
    .stalled(stalled),
    .interrupt_reg(interrupt_reg),
    .csrData(csrData),
    .nextPC(nextPC)
);

initial clk = 1'b0;
always #5 clk = ~clk;

task observe;
    input [127:0] label;
    begin
        #1;
        $display("%s: interrupt_reg=%b csrData=%h nextPC=%h",
                 label, interrupt_reg, csrData, nextPC);
    end
endtask

task csr_access;
    input [127:0] label;
    input [11:0] a;
    input [31:0] d;
    input [1:0] op;
    begin
        index = a;
        data = d;
        opcode = op;
        repeat (1) @(posedge clk);
        observe(label);
    end
endtask

task reset_dut;
    begin
        reset = 1'b0;
        index = 12'b0;
        data = 32'b0;
        opcode = 2'b00;
        mret = 1'b0;
        exception = 1'b0;
        exceptionType = 4'b0;
        exceptionPC = 32'b0;
        NMI = 1'b0;
        timerInterrupt = 1'b0;
        externalInterrupts = 16'b0;
        stalled = 1'b0;
        #2;
        reset = 1'b1;
        repeat (2) @(posedge clk);
    end
endtask

initial begin
    reset = 1'b0;
    index = 12'b0;
    data = 32'b0;
    opcode = 2'b00;
    mret = 1'b0;
    exception = 1'b0;
    exceptionType = 4'b0;
    exceptionPC = 32'b0;
    NMI = 1'b0;
    timerInterrupt = 1'b0;
    externalInterrupts = 16'b0;
    stalled = 1'b0;

    #2;
    reset = 1'b1;
    repeat (2) @(posedge clk);

    // Test Case 1: reset values and all CSR reads
    csr_access("reset MTVEC",   MTVEC,    32'b0, RC);
    csr_access("reset MSTATUS", MSTATUS,  32'b0, RC);
    csr_access("reset MIE",     MIE,      32'b0, RC);
    csr_access("reset MSCRATCH",MSCRATCH, 32'b0, RC);
    csr_access("reset MEPC",    MEPC,     32'b0, RC);
    csr_access("reset MCAUSE",  MCAUSE,   32'b0, RC);
    csr_access("reset MTVAL",   MTVAL,    32'b0, RC);
    csr_access("reset MIP",     MIP,      32'b0, RC);
    csr_access("read MISA",     MISA,     32'b0, RC);
    csr_access("read MVENDORID",MVENDORID,32'b0, RC);
    csr_access("read MARCHID",  MARCHID,  32'b0, RC);
    csr_access("read MIMPID",   MIMPID,   32'b0, RC);
    csr_access("read MHARTID",  MHARTID,  32'b0, RC);
    csr_access("read invalid",  12'h222,  32'b0, RC);

    // Test Case 2: CSR RW, RS, and RC operations
    csr_access("MSCRATCH RW", MSCRATCH, 32'h12345678, RW);
    csr_access("MSCRATCH RS", MSCRATCH, 32'h00000F0F, RS);
    csr_access("MSCRATCH RC", MSCRATCH, 32'h000000F0, RC);

    csr_access("MTVEC RW", MTVEC, 32'h00012001, RW);
    csr_access("MTVEC RS", MTVEC, 32'h00000080, RS);
    csr_access("MTVEC RC", MTVEC, 32'h00000001, RC);

    csr_access("MEPC RW", MEPC, 32'h1234567F, RW);
    csr_access("MEPC RS", MEPC, 32'h00000004, RS);
    csr_access("MEPC RC", MEPC, 32'h00000010, RC);

    csr_access("MCAUSE RW", MCAUSE, 32'h80000007, RW);
    csr_access("MCAUSE RS", MCAUSE, 32'h00000100, RS);
    csr_access("MCAUSE RC", MCAUSE, 32'h00000007, RC);

    csr_access("MTVAL RW", MTVAL, 32'hA5A5A5A5, RW);
    csr_access("MTVAL RS", MTVAL, 32'h0000000F, RS);
    csr_access("MTVAL RC", MTVAL, 32'h00000005, RC);

    csr_access("MIP RW", MIP, 32'h00000008, RW);
    csr_access("MIP RS", MIP, 32'h00000008, RS);
    csr_access("MIP RC", MIP, 32'h00000008, RC);

    csr_access("MSTATUS RW", MSTATUS, 32'h00000088, RW);
    csr_access("MSTATUS RS", MSTATUS, 32'h00000008, RS);
    csr_access("MSTATUS RC", MSTATUS, 32'h00000080, RC);

    csr_access("MIE RW", MIE, 32'h00010888, RW);
    csr_access("MIE RS", MIE, 32'h00000080, RS);
    csr_access("MIE RC", MIE, 32'h00000008, RC);

    // Test Case 3: synchronous exception and aligned trap PC
    reset_dut;
    index = MCAUSE;
    data = 32'b0;
    opcode = 2'b00;
    exception = 1'b1;
    exceptionType = 4'hB;
    exceptionPC = 32'h1234567F;
    repeat (1) @(posedge clk);
    observe("synchronous exception");
    exception = 1'b0;
    repeat (1) @(posedge clk);
    csr_access("exception MCAUSE", MCAUSE, 32'b0, RC);
    csr_access("exception MEPC", MEPC, 32'b0, RC);
    csr_access("exception MTVAL", MTVAL, 32'b0, RC);

    // Test Case 4: external interrupt selection and vectored address
    reset_dut;
    csr_access("enable MSTATUS", MSTATUS, 32'h00000008, RW);
    csr_access("enable external MIE", MIE, 32'h80010800, RW);
    index = MCAUSE;
    opcode = 2'b00;
    externalInterrupts = 16'b1000000000000001;
    repeat (1) @(posedge clk);
    observe("external interrupt registered");
    externalInterrupts = 16'b0;
    repeat (1) @(posedge clk);
    observe("external interrupt taken");
    csr_access("external MCAUSE", MCAUSE, 32'b0, RC);
    csr_access("external MEPC", MEPC, 32'b0, RC);

    // Test Case 5: software interrupt and timer interrupt
    reset_dut;
    csr_access("enable software and timer", MSTATUS, 32'h00000008, RW);
    csr_access("enable software and timer MIE", MIE, 32'h00000088, RW);
    csr_access("set software pending", MIP, 32'h00000008, RW);
    index = MCAUSE;
    opcode = 2'b00;
    repeat (1) @(posedge clk);
    observe("software interrupt registered");
    repeat (1) @(posedge clk);
    observe("software interrupt taken");
    csr_access("software MCAUSE", MCAUSE, 32'b0, RC);

    reset_dut;
    csr_access("enable timer MSTATUS", MSTATUS, 32'h00000008, RW);
    csr_access("enable timer MIE", MIE, 32'h00000080, RW);
    timerInterrupt = 1'b1;
    index = MCAUSE;
    opcode = 2'b00;
    repeat (1) @(posedge clk);
    observe("timer interrupt registered");
    timerInterrupt = 1'b0;
    repeat (1) @(posedge clk);
    observe("timer interrupt taken");
    csr_access("timer MCAUSE", MCAUSE, 32'b0, RC);

    // Test Case 6: interrupt masking
    reset_dut;
    csr_access("masked MIE", MIE, 32'h00010800, RW);
    externalInterrupts = 16'h0001;
    index = MCAUSE;
    opcode = 2'b00;
    repeat (2) @(posedge clk);
    observe("masked external interrupt");
    externalInterrupts = 16'b0;

    // Test Case 7: NMI acceptance, suppression, and MRET
    reset_dut;
    index = MCAUSE;
    opcode = 2'b00;
    exceptionPC = 32'hCAFEBABF;
    NMI = 1'b1;
    repeat (1) @(posedge clk);
    observe("NMI registered");
    NMI = 1'b0;
    repeat (1) @(posedge clk);
    observe("NMI taken");
    csr_access("NMI MCAUSE", MCAUSE, 32'b0, RC);
    csr_access("NMI MEPC", MEPC, 32'b0, RC);

    NMI = 1'b1;
    repeat (1) @(posedge clk);
    observe("second NMI suppressed");
    NMI = 1'b0;
    repeat (1) @(posedge clk);

    mret = 1'b1;
    repeat (1) @(posedge clk);
    observe("MRET");
    mret = 1'b0;
    repeat (1) @(posedge clk);

    NMI = 1'b1;
    repeat (1) @(posedge clk);
    observe("NMI after MRET registered");
    NMI = 1'b0;
    repeat (1) @(posedge clk);
    observe("NMI after MRET taken");

    // Test Case 8: stalled interrupt and stalled exception
    reset_dut;
    csr_access("enable stalled interrupt", MSTATUS, 32'h00000008, RW);
    csr_access("enable stalled external", MIE, 32'h80010800, RW);
    externalInterrupts = 16'h0001;
    index = MEPC;
    opcode = 2'b00;
    exceptionPC = 32'h11111113;
    repeat (1) @(posedge clk);
    observe("stalled interrupt registered");
    externalInterrupts = 16'b0;
    stalled = 1'b1;
    repeat (1) @(posedge clk);
    observe("stalled interrupt deferred");
    stalled = 1'b0;
    repeat (1) @(posedge clk);
    observe("stalled interrupt released");

    reset_dut;
    index = MEPC;
    opcode = 2'b00;
    exception = 1'b1;
    exceptionType = 4'h6;
    exceptionPC = 32'h22222223;
    stalled = 1'b1;
    repeat (1) @(posedge clk);
    observe("stalled exception");
    stalled = 1'b0;
    exception = 1'b0;
    repeat (1) @(posedge clk);
    observe("exception after stall");

    // Test Case 9: MRET takes priority over a registered NMI.
    reset_dut;
    @(negedge clk);
    index = MIP;
    opcode = RW;
    data = 32'hFFFFFFFF;
    exceptionPC = 32'h33333337;
    NMI = 1'b1;
    @(posedge clk);
    observe("NMI before overlapping MRET");
    @(negedge clk);
    NMI = 1'b0;
    mret = 1'b1;
    observe("MRET with registered NMI");
    @(posedge clk);
    observe("MRET clears NMI pending bit");
    @(negedge clk);
    mret = 1'b0;
    opcode = RC;
    data = 32'b0;
    @(posedge clk);
    observe("MIP after NMI MRET");

    // Test Case 10: MRET clears the selected maskable pending bit.
    reset_dut;
    csr_access("MRET software status", MSTATUS, 32'h00000008, RW);
    csr_access("MRET software enable", MIE, 32'h00000008, RW);
    csr_access("MRET software pending", MIP, 32'h00000008, RW);
    @(negedge clk);
    index = MIP;
    opcode = RW;
    data = 32'h00000008;
    exception = 1'b1;
    exceptionType = 4'h9;
    @(posedge clk);
    observe("software request before MRET");
    @(negedge clk);
    mret = 1'b1;
    observe("MRET with interrupt exception and CSR write");
    @(posedge clk);
    observe("MRET clears software pending bit");
    @(negedge clk);
    mret = 1'b0;
    exception = 1'b0;
    opcode = RC;
    data = 32'b0;
    @(posedge clk);
    observe("MIP after software MRET");

    // Test Case 11: stalled registered NMI selects the held interrupt path.
    reset_dut;
    @(negedge clk);
    index = MCAUSE;
    opcode = 2'b00;
    exceptionPC = 32'h44444447;
    stalled = 1'b1;
    NMI = 1'b1;
    @(posedge clk);
    observe("stalled NMI registered");
    @(negedge clk);
    NMI = 1'b0;
    observe("registered NMI while stalled");
    @(posedge clk);
    observe("stalled NMI bookkeeping");
    @(negedge clk);
    stalled = 1'b0;
    opcode = RC;
    data = 32'b0;
    @(posedge clk);
    observe("MCAUSE after stalled NMI");

    // Test Case 12: traverse all external request-to-cause mappings.
    for (ext_line = 0; ext_line < 16; ext_line = ext_line + 1) begin
        reset_dut;
        csr_access("scan MSTATUS", MSTATUS, 32'h00000008, RW);
        csr_access("scan MIE", MIE, 32'hFFFF0800, RW);
        @(negedge clk);
        index = MCAUSE;
        opcode = 2'b00;
        exceptionPC = 32'h55555557;
        externalInterrupts = 16'h0001 << ext_line;
        @(posedge clk);
        observe("external cause selected");
        @(negedge clk);
        externalInterrupts = 16'b0;
        @(posedge clk);
        observe("external cause captured");
    end

    // Test Case 13: exercise the unreachable-by-legal-opcode default
    // operation branches for every writable CSR.
    reset_dut;
    csr_access("MSTATUS invalid opcode", MSTATUS, 32'hFFFFFFFF, INVALID_CSR_OP);
    csr_access("MIE invalid opcode", MIE, 32'hFFFFFFFF, INVALID_CSR_OP);
    csr_access("MTVEC invalid opcode", MTVEC, 32'hFFFFFFFF, INVALID_CSR_OP);
    csr_access("MSCRATCH invalid opcode", MSCRATCH, 32'hFFFFFFFF, INVALID_CSR_OP);
    csr_access("MEPC invalid opcode", MEPC, 32'hFFFFFFFF, INVALID_CSR_OP);
    csr_access("MCAUSE invalid opcode", MCAUSE, 32'hFFFFFFFF, INVALID_CSR_OP);
    csr_access("MTVAL invalid opcode", MTVAL, 32'hFFFFFFFF, INVALID_CSR_OP);
    csr_access("MIP invalid opcode", MIP, 32'hFFFFFFFF, INVALID_CSR_OP);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

// Inputs
reg clk;
reg [31:0] inst;

// Outputs
wire [21:0] decode;
wire csr_write;
wire [1:0] trap;
wire wb_src;

integer i, j;
reg [4:0] source;
reg [31:0] stimulus;

Inst_Controller uut (
    .inst(inst),
    .decode(decode),
    .csr_write(csr_write),
    .trap(trap),
    .wb_src(wb_src)
);

initial clk = 0;
always #5 clk = ~clk;

// Instruction construction only; no expected-output calculation.
function [31:0] instruction;
    input [6:0] opcode;
    input [2:0] funct3;
    input [4:0] rs1;
    input [11:0] upper;
    begin
        instruction = {upper, rs1, funct3, 5'd1, opcode};
    end
endfunction

function [6:0] opcode_at;
    input integer index;
    begin
        case (index)
             0: opcode_at = 7'h33; // Register arithmetic
             1: opcode_at = 7'h13; // Immediate arithmetic
             2: opcode_at = 7'h3b; // Register word arithmetic
             3: opcode_at = 7'h1b; // Immediate word arithmetic
             4: opcode_at = 7'h63; // Branch
             5: opcode_at = 7'h03; // Load
             6: opcode_at = 7'h23; // Store
             7: opcode_at = 7'h67; // JALR
             8: opcode_at = 7'h6f; // JAL
             9: opcode_at = 7'h37; // LUI
            10: opcode_at = 7'h17; // AUIPC
            default: opcode_at = 7'h00;
        endcase
    end
endfunction

function [2:0] csr_function;
    input integer index;
    begin
        case (index)
            0: csr_function = 3'b001;
            1: csr_function = 3'b010;
            2: csr_function = 3'b011;
            3: csr_function = 3'b101;
            4: csr_function = 3'b110;
            default: csr_function = 3'b111;
        endcase
    end
endfunction

function [11:0] system_immediate;
    input integer index;
    begin
        case (index)
            0: system_immediate = 12'h000;
            1: system_immediate = 12'h302;
            2: system_immediate = 12'h102;
            3: system_immediate = 12'h001;
            4: system_immediate = 12'h101;
            5: system_immediate = 12'h103;
            6: system_immediate = 12'h301;
            7: system_immediate = 12'h303;
            default: system_immediate = 12'hfff;
        endcase
    end
endfunction

task observe;
    input [8*28-1:0] label;
    begin
        $display("%0s t=%0t inst=%h decode=%b csr_write=%b trap=%b wb_src=%b",
                 label, $time, inst, decode, csr_write, trap, wb_src);
    end
endtask

task apply;
    input [31:0] value;
    input [8*28-1:0] label;
    begin
        inst = value;
        #2;
        observe(label);
    end
endtask

task clear_controls;
    begin
        apply(32'h00000000, "unsupported-opcode clear");
    end
endtask

initial begin
    // Initialize inputs; allow 100 ns for startup.
    inst = 32'h00000000;
    source = 0;
    stimulus = 0;
    #100;
    observe("startup");

    // Arithmetic: four classes, eight funct3 values, both bit-30 values.
    for (i = 0; i < 64; i = i + 1) begin
        #1;
        clear_controls;
        apply(instruction(opcode_at(i / 16), (i / 2) % 8,
                          5'd1, (i % 2) ? 12'h400 : 12'h000),
              "arithmetic sweep");
    end

    // Branch, load, and store: supported and unsupported functions.
    for (i = 0; i < 24; i = i + 1) begin
        #1;
        clear_controls;
        apply(instruction(opcode_at(4 + i / 8), i % 8,
                          5'd1, 12'h000),
              "branch/load/store sweep");
    end

    // JALR, JAL, LUI, AUIPC: all other instruction bits zero or one.
    for (i = 0; i < 8; i = i + 1) begin
        #1;
        clear_controls;
        stimulus = (i % 2) ? 32'hffffff80 : 32'h00000000;
        stimulus[6:0] = opcode_at(7 + i / 2);
        apply(stimulus, "jump/upper boundaries");
    end

    // CSR source boundaries and transitions, with a preexisting trap.
    for (i = 0; i < 6; i = i + 1) begin
        #1;
        clear_controls;
        apply(instruction(7'h73, 3'b000, 5'd0,
                          system_immediate(i % 3)),
              "CSR trap seed");

        for (j = 0; j < 4; j = j + 1) begin
            #1;
            case (j)
                0: source = 5'd0;
                1: source = 5'd1;
                2: source = 5'd31;
                default: source = 5'd0;
            endcase
            apply(instruction(7'h73, csr_function(i), source, 12'h300),
                  "CSR source transition");
        end

        apply(instruction(7'h73, 3'b100, 5'd0, 12'h300),
              "reserved CSR after zero");
        apply(instruction(7'h73, 3'b000, 5'd0, 12'h001),
              "other system after zero");
    end

    // System immediates and reserved CSR function from two histories.
    for (i = 0; i < 9; i = i + 1) begin
        #1;
        clear_controls;
        apply(instruction(7'h73, 3'b100, 5'd0, 12'h000),
              "reserved CSR from clean");
        apply(instruction(7'h73, 3'b000, 5'd0, system_immediate(i)),
              "system from clean");

        apply(instruction(7'h73, csr_function(i % 6), 5'd31, 12'h300),
              "CSR populated seed");
        apply(instruction(7'h73, 3'b000, 5'd0, system_immediate(i)),
              "system after CSR");
        apply(instruction(7'h73, 3'b100, 5'd31, 12'hfff),
              "reserved CSR populated");
        apply(instruction(7'h73, 3'b000, 5'd0, 12'h001),
              "other system populated");
        clear_controls;
    end

    // Auxiliary retention through every recognized non-CSR class.
    for (i = 0; i < 11; i = i + 1) begin
        #1;
        clear_controls;
        apply(instruction(7'h73, 3'b000, 5'd0,
                          system_immediate(i % 3)),
              "retention trap seed");
        apply(instruction(7'h73, csr_function(i % 6), 5'd31, 12'h300),
              "retention CSR seed");
        apply(instruction(opcode_at(i), 3'b000, 5'd1, 12'h000),
              "non-CSR auxiliary retention");
        apply(instruction(7'h73, 3'b000, 5'd0, 12'h001),
              "system retains ALU fields");
        apply(32'hffffffff, "alternate unsupported clear");
    end

    $display("===========End=========== decode=%b csr_write=%b trap=%b wb_src=%b",
             decode, csr_write, trap, wb_src);
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

parameter BW_FFTP  = 4;
parameter BW_STAGE = 2;

localparam STAGE_CYCLES = 2 * (1 << (BW_FFTP - 1));
localparam RUN_CYCLES   = BW_FFTP * STAGE_CYCLES;
// Enough time to observe completion even after a terminal-time restart.
localparam RECOVERY_CYCLES =
    2 * (1 << (BW_FFTP - 1 + BW_STAGE + 1)) + 8;

// Inputs
reg clk;
reg Reset;
reg Start;

// Outputs
wire [BW_FFTP-2:0] Theta;
wire [BW_STAGE-1:0] Stage;
wire Busy;
wire End;

integer case_id;
integer offset;

FFTTheta_R2 #(
    .bw_fftp(BW_FFTP),
    .bw_stage(BW_STAGE)
) uut (
    .Clock(clk),
    .Reset(Reset),
    .Start(Start),
    .Theta(Theta),
    .Stage(Stage),
    .Busy(Busy),
    .End(End)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
begin
    $display("case=%0d time=%0t Reset=%b Start=%b Theta=%h Stage=%h Busy=%b End=%b",
             case_id, $time, Reset, Start, Theta, Stage, Busy, End);
end
endtask

task sample_cycles;
    input integer count;
    integer cycle;
begin
    for (cycle = 0; cycle < count; cycle = cycle + 1) begin
        @(posedge clk);
        #1;
        observe;
    end
end
endtask

task reset_dut;
begin
    @(negedge clk);
    Start = 0;
    #2;
    Reset = 1;
    #1;
    observe;
    sample_cycles(2);
    @(negedge clk);
    Reset = 0;
end
endtask

task pulse_start;
begin
    @(negedge clk);
    Start = 1;
    sample_cycles(1);
    @(negedge clk);
    Start = 0;
end
endtask

initial begin
    Reset = 0;
    Start = 0;
    case_id = 0;

    // Wait 100 ns for global reset to finish.
    #100;

    // 1: Reset, idle, and reset priority over Start.
    case_id = 1;
    reset_dut;
    sample_cycles(4);
    @(negedge clk);
    #2;
    Reset = 1;
    Start = 1;
    #1;
    observe;
    sample_cycles(2);
    @(negedge clk);
    Start = 0;
    Reset = 0;
    sample_cycles(3);

    // 2-3: Complete schedule, then reuse without reset.
    case_id = 2;
    reset_dut;
    pulse_start;
    sample_cycles(RUN_CYCLES + 8);

    case_id = 3;
    pulse_start;
    sample_cycles(RUN_CYCLES + 8);

    // 4: Start again during an active stage.
    case_id = 4;
    reset_dut;
    pulse_start;
    sample_cycles(STAGE_CYCLES + 3);
    pulse_start;
    sample_cycles(RECOVERY_CYCLES);

    // 5: Hold Start through the nominal terminal boundary.
    case_id = 5;
    reset_dut;
    @(negedge clk);
    Start = 1;
    sample_cycles(RUN_CYCLES + 5);
    @(negedge clk);
    Start = 0;
    sample_cycles(RECOVERY_CYCLES);

    // 6-8: Start at terminal capture, assertion, and cleanup.
    for (offset = 0; offset < 3; offset = offset + 1) begin
        @(negedge clk);
        case_id = 6 + offset;
        reset_dut;
        pulse_start;
        sample_cycles(RUN_CYCLES + offset);
        pulse_start;
        sample_cycles(RECOVERY_CYCLES);
    end

    // 9: Asynchronous reset interrupts active theta generation.
    case_id = 9;
    reset_dut;
    pulse_start;
    sample_cycles(STAGE_CYCLES + 7);
    reset_dut;
    sample_cycles(3);
    pulse_start;
    sample_cycles(RUN_CYCLES + 8);

    // 10: Asynchronous reset during the completion pulse.
    case_id = 10;
    reset_dut;
    pulse_start;
    sample_cycles(RUN_CYCLES + 2);
    reset_dut;
    sample_cycles(3);
    pulse_start;
    sample_cycles(RUN_CYCLES + 8);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam N = 18;
localparam PHASE_CYCLES = (1 << (N - 2));

// Inputs
reg clk;
reg reset;
reg [3:0] fourth, third, second, first;

// Outputs
wire a_m, b_m, c_m, d_m, e_m, f_m, g_m, dp_m;
wire [3:0] an_m;

integer phase, value;

muxer uut (
    .clock(clk),
    .reset(reset),
    .fourth(fourth),
    .third(third),
    .second(second),
    .first(first),
    .a_m(a_m),
    .b_m(b_m),
    .c_m(c_m),
    .d_m(d_m),
    .e_m(e_m),
    .f_m(f_m),
    .g_m(g_m),
    .dp_m(dp_m),
    .an_m(an_m)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [8*32-1:0] label;
    begin
        $display(
            "%0s t=%0t reset=%b first=%h second=%h third=%h fourth=%h a_m=%b b_m=%b c_m=%b d_m=%b e_m=%b f_m=%b g_m=%b dp_m=%b an_m=%b",
            label, $time, reset, first, second, third, fourth,
            a_m, b_m, c_m, d_m, e_m, f_m, g_m, dp_m, an_m
        );
    end
endtask

task reset_scan;
    begin
        @(negedge clk);
        #1 reset = 1;
        #1 observe("reset asserted asynchronously");
        repeat (2) @(posedge clk);
        #1 observe("reset held across clocks");
        @(negedge clk);
        reset = 0;
        #1 observe("reset released");
    end
endtask

task drive_values;
    input integer digit;
    input [3:0] selected;
    input [3:0] others;
    begin
        first = others;
        second = others;
        third = others;
        fourth = others;
        case (digit)
            0: first = selected;
            1: second = selected;
            2: third = selected;
            3: fourth = selected;
        endcase
    end
endtask

initial begin
    reset = 0;
    first = 1;
    second = 2;
    third = 3;
    fourth = 4;

    // Wait 100 ns for global reset to finish.
    #100;

    // Test 1: Phase duration, all transitions, and scan wraparound.
    reset_scan;
    for (phase = 0; phase < 4; phase = phase + 1) begin
        repeat (PHASE_CYCLES - 1) @(posedge clk);
        #1 observe("before phase boundary");
        @(posedge clk);
        #1 observe("after phase boundary");
    end

    // Test 2: Every value and unselected-input isolation in every phase.
    for (phase = 0; phase < 4; phase = phase + 1) begin
        reset_scan;
        repeat (phase * PHASE_CYCLES) @(posedge clk);
        #1;

        @(negedge clk);
        drive_values(phase, 4'd8, 4'd0);
        #1 observe("selected eight; others zero");

        @(negedge clk);
        drive_values(phase, 4'd8, 4'd15);
        #1 observe("only unselected inputs changed");

        for (value = 0; value < 16; value = value + 1) begin
            @(negedge clk);
            drive_values(phase, value, 4'd15);
            #1 observe("selected input decode");
        end

        // Test 3: Asynchronous reset from the exercised phase.
        reset_scan;
    end

    $display("===========End===========");
    $finish;
end

endmodule

