    $display("%s uart_int_o=%b prdata_o=%h st_check=%b p_error_ack=%b st_error_ack=%b rxrst=%b stop_bit=%b two_tx_delay=%h tx_data=%h txrst=%b check=%b parity=%b rx_fifo_rinc=%b tx_fifo_winc=%b baud_div=%h",
             label, uart_int_o, prdata_o, st_check, p_error_ack,
             st_error_ack, rxrst, stop_bit, two_tx_delay, tx_data,
             txrst, check, parity, rx_fifo_rinc, tx_fifo_winc, baud_div);
end
endtask

task bus_write;
input integer index;
input [31:0] data;
begin
    @(negedge clk);
    paddr_i   = index * 4;
    pwdata_i  = data;
    psel_i    = 1'b1;
    penable_i = 1'b1;
    pwrite_i  = 1'b1;
    @(posedge clk);
    #1;
    psel_i    = 1'b0;
    penable_i = 1'b0;
    pwrite_i  = 1'b0;
end
endtask

task bus_read;
input integer index;
input [127:0] label;
begin
    @(negedge clk);
    paddr_i   = index * 4;
    psel_i    = 1'b1;
    penable_i = 1'b0;
    pwrite_i  = 1'b0;
    @(posedge clk);
    #1;
    show_outputs(label);
    psel_i    = 1'b0;
    penable_i = 1'b0;
    pwrite_i  = 1'b0;
end
endtask

task drive_bus_cycle;
input integer index;
input [31:0] data;
input        sel;
input        enable;
input        write;
begin
    @(negedge clk);
    paddr_i   = index * 4;
    pwdata_i  = data;
    psel_i    = sel;
    penable_i = enable;
    pwrite_i  = write;
    @(posedge clk);
    #1;
    show_outputs("qualifier stimulus");
    psel_i    = 1'b0;
    penable_i = 1'b0;
    pwrite_i  = 1'b0;
end
endtask

initial begin
    reset_dut;
    show_outputs("reset defaults");

    bus_write(0, 32'h000000A5);
    repeat (2) @(posedge clk);
    show_outputs("transmit write and delayed strobe");

    bus_write(2, 32'h0000035A);
    bus_write(3, 32'h0000C00F);
    bus_write(4, 32'h0000000A);
    bus_write(5, 32'h0000000F);
    bus_write(6, 32'h0000000D);
    repeat (2) @(posedge clk);
    show_outputs("configuration outputs");

    rx_data     = 8'h5C;
    rx_fifo_cnt = 5'd9;
    tx_fifo_cnt = 5'd13;
    repeat (2) @(posedge clk);
    show_outputs("sampled data and FIFO counts");

    for (i = 0; i <= 9; i = i + 1)
        bus_read(i, "mapped register read");
    bus_read(10, "unmapped register read");

    // Exercise all false combinations of the write qualifier and
    // a qualifying write whose address selects no writable register.
    drive_bus_cycle(0, 32'h11111111, 1'b0, 1'b1, 1'b1);
    drive_bus_cycle(0, 32'h22222222, 1'b1, 1'b0, 1'b1);
    drive_bus_cycle(0, 32'h33333333, 1'b1, 1'b1, 1'b0);
    drive_bus_cycle(10, 32'h44444444, 1'b1, 1'b1, 1'b1);

    // Exercise the address-qualified status-clear condition with
    // each false qualifier combination.
    drive_bus_cycle(7, 32'h00000000, 1'b0, 1'b1, 1'b1);
    drive_bus_cycle(7, 32'h00000000, 1'b1, 1'b0, 1'b1);
    drive_bus_cycle(7, 32'h00000000, 1'b1, 1'b1, 1'b0);

    // Exercise all false combinations of the read qualifier and
    // a qualifying read whose address is unmapped.
    drive_bus_cycle(0, 32'h0, 1'b0, 1'b0, 1'b0);
    drive_bus_cycle(0, 32'h0, 1'b1, 1'b1, 1'b0);
    drive_bus_cycle(0, 32'h0, 1'b1, 1'b0, 1'b1);
    drive_bus_cycle(10, 32'h0, 1'b1, 1'b0, 1'b0);

    // Exercise the status-read condition with address 7 and
    // mismatched phase and direction qualifiers.
    drive_bus_cycle(7, 32'h0, 1'b1, 1'b1, 1'b0);
    drive_bus_cycle(7, 32'h0, 1'b1, 1'b0, 1'b1);

    // Exercise the receive-data-read condition with address 1 and
    // mismatched phase and direction qualifiers.
    drive_bus_cycle(1, 32'h0, 1'b1, 1'b1, 1'b0);
    drive_bus_cycle(1, 32'h0, 1'b1, 1'b0, 1'b1);

    reset_dut;
    rx_data = 8'hA6;
    repeat (1) @(posedge clk);
    bus_read(1, "receive data read and FIFO increment");

    // Status bit 1 is clear after reset while the FIFO is non-empty.
    // This exercises the false branch of uart_status[1] && !rx_fifo_rempty.
    rx_fifo_rempty = 1'b0;
    bus_read(7, "status read with clear status and nonempty RX FIFO");

    rx_fifo_cnt    = 5'd0;
    rx_fifo_rempty = 1'b1;
    repeat (1) @(posedge clk);
    rx_fifo_cnt    = 5'd1;
    repeat (2) @(posedge clk);
    bus_read(7, "status read with empty RX FIFO");

    rx_fifo_rempty = 1'b0;
    bus_read(7, "status read with nonempty RX FIFO");

    reset_dut;
    rx_fifo_cnt = 5'd0;
    repeat (1) @(posedge clk);
    rx_fifo_cnt = 5'd1;
    repeat (3) @(posedge clk);
    show_outputs("receive trigger status");

    bus_write(7, 32'h00000002);
    repeat (2) @(posedge clk);
    show_outputs("receive status clear");

    reset_dut;
    bus_write(4, 32'h00000000);
    repeat (2) @(posedge clk);
    rx_fifo_cnt = 5'd15;
    repeat (1) @(posedge clk);
    rx_fifo_cnt = 5'd0;
    repeat (3) @(posedge clk);
    show_outputs("receive trigger zero boundary");

    reset_dut;
    tx_fifo_wfull = 1'b1;
    bus_write(0, 32'h000000A5);
    repeat (2) @(posedge clk);
    show_outputs("transmit write while FIFO full");
    tx_fifo_wfull = 1'b0;

    tx_fifo_cnt = 5'd1;
    repeat (1) @(posedge clk);
    tx_fifo_cnt = 5'd5;
    repeat (1) @(posedge clk);
    show_outputs("transmit trigger intermediate count");
    tx_fifo_cnt = 5'd0;
    repeat (3) @(posedge clk);
    show_outputs("transmit trigger status");

    bus_write(7, 32'h00000001);
    repeat (2) @(posedge clk);
    show_outputs("transmit status clear");

    reset_dut;
    bus_write(5, 32'h0000000F);
    repeat (2) @(posedge clk);
    tx_fifo_cnt = 5'd0;
    repeat (1) @(posedge clk);
    tx_fifo_cnt = 5'd15;
    repeat (3) @(posedge clk);
    show_outputs("transmit trigger fifteen boundary");

    bus_write(7, 32'h00000001);
    repeat (2) @(posedge clk);
    show_outputs("transmit boundary status clear");

    // Reset while the transmit write controller is in state 1.
    // This exercises the delayed controller's state-1 to idle reset path.
    reset_dut;
    bus_write(0, 32'h0000005A);
    #1;
    rst_ = 1'b0;
    #1;
    show_outputs("reset during delayed transmit sequence");
    @(posedge clk);
    rst_ = 1'b1;
    repeat (3) @(posedge clk);
    show_outputs("delayed transmit sequence after reset");

    reset_dut;
    p_error = 1'b1;
    repeat (8) @(posedge clk);
    show_outputs("parity error held active");
    p_error = 1'b0;
    repeat (3) @(posedge clk);
    show_outputs("parity error status");

    bus_write(7, 32'h00000004);
    repeat (5) @(posedge clk);
    show_outputs("parity error acknowledgement");

    reset_dut;
    st_error = 1'b1;
    repeat (8) @(posedge clk);
    show_outputs("stop error held active");
    st_error = 1'b0;
    repeat (3) @(posedge clk);
    show_outputs("stop error status");

    bus_write(7, 32'h00000008);
    repeat (5) @(posedge clk);
    show_outputs("stop error acknowledgement");

    reset_dut;
    show_outputs("final reset behavior");

    $display("===========End===========");

    $finish;
end

endmodule

