module testbench;

parameter NUM_INT_BDS         = 0;
parameter NUM_INT_BDS_WIDTH   = 5;
parameter NUM_PRI_LVLS        = 1;
parameter MAX_TRAN_SIZE_WIDTH = 23;

// Inputs
reg clk;
reg resetn, doTrans, strDscrptr_DMAArbiter;
reg [NUM_INT_BDS_WIDTH-1:0] intDscrptrNum_DMAArbiter;
reg [31:0] extDscrptrAddr_DMAArbiter, dstAddr_DMAArbiter;
reg extDscrptr_DMAArbiter, dataValid_DMAArbiter;
reg [1:0] dstOp_DMAArbiter;
reg [2:0] dstDataWidth_DMAArbiter, srcDataWidth_DMAArbiter;
reg [MAX_TRAN_SIZE_WIDTH-1:0] numOfBytes_DMAArbiter;
reg [NUM_PRI_LVLS-1:0] priLvl_DMAArbiter;
reg chain_DMAArbiter, extDscrptrNxt_DMAArbiter;
reg intOnProcess_DMAArbiter;
reg [31:0] nxtDscrptrNumAddr_DMAArbiter;
reg [1:0] clrWrTranQueue;
reg wrCache1Sel, rdyToAck, extDataValid, rdCache1Sel;

// Outputs
wire reqInQueue, strDscrptr, dataValid, extDscrptr;
wire chain, extDscrptrNxt, intOnProcess, spaceWrTranQueue;
wire [NUM_PRI_LVLS-1:0] priLvl;
wire [1:0] dstOp;
wire [2:0] dstDataWidth, srcDataWidth;
wire [31:0] dstAddr_wrCache1Sel, dstAddr_rdCache1Sel;
wire [31:0] extDscrptrAddr, nxtDscrptrNumAddr;
wire [MAX_TRAN_SIZE_WIDTH-1:0] numOfBytes;
wire [NUM_INT_BDS_WIDTH-1:0] intDscrptrNum_wrTranQueue0;
wire [NUM_INT_BDS_WIDTH-1:0] intDscrptrNum_wrTranQueue1;

integer i, j, c, op, k, tc;

// Instantiate the Unit Under Test
CoreDMA_Controller_CoreDMA_Controller_0_CoreAXI4DMAController_wrTranQueue #(
    .NUM_INT_BDS(NUM_INT_BDS),
    .NUM_INT_BDS_WIDTH(NUM_INT_BDS_WIDTH),
    .NUM_PRI_LVLS(NUM_PRI_LVLS),
    .MAX_TRAN_SIZE_WIDTH(MAX_TRAN_SIZE_WIDTH)
) uut (
    .clock(clk),
    .resetn(resetn),
    .doTrans(doTrans),
    .strDscrptr_DMAArbiter(strDscrptr_DMAArbiter),
    .intDscrptrNum_DMAArbiter(intDscrptrNum_DMAArbiter),
    .extDscrptrAddr_DMAArbiter(extDscrptrAddr_DMAArbiter),
    .extDscrptr_DMAArbiter(extDscrptr_DMAArbiter),
    .dataValid_DMAArbiter(dataValid_DMAArbiter),
    .dstAddr_DMAArbiter(dstAddr_DMAArbiter),
    .dstOp_DMAArbiter(dstOp_DMAArbiter),
    .dstDataWidth_DMAArbiter(dstDataWidth_DMAArbiter),
    .srcDataWidth_DMAArbiter(srcDataWidth_DMAArbiter),
    .numOfBytes_DMAArbiter(numOfBytes_DMAArbiter),
    .priLvl_DMAArbiter(priLvl_DMAArbiter),
    .chain_DMAArbiter(chain_DMAArbiter),
    .extDscrptrNxt_DMAArbiter(extDscrptrNxt_DMAArbiter),
    .intOnProcess_DMAArbiter(intOnProcess_DMAArbiter),
    .nxtDscrptrNumAddr_DMAArbiter(nxtDscrptrNumAddr_DMAArbiter),
    .clrWrTranQueue(clrWrTranQueue),
    .wrCache1Sel(wrCache1Sel),
    .rdyToAck(rdyToAck),
    .extDataValid(extDataValid),
    .rdCache1Sel(rdCache1Sel),
    .reqInQueue(reqInQueue),
    .strDscrptr(strDscrptr),
    .priLvl(priLvl),
    .dataValid(dataValid),
    .dstOp(dstOp),
    .dstDataWidth(dstDataWidth),
    .srcDataWidth(srcDataWidth),
    .dstAddr_wrCache1Sel(dstAddr_wrCache1Sel),
    .dstAddr_rdCache1Sel(dstAddr_rdCache1Sel),
    .numOfBytes(numOfBytes),
    .intDscrptrNum_wrTranQueue0(intDscrptrNum_wrTranQueue0),
    .intDscrptrNum_wrTranQueue1(intDscrptrNum_wrTranQueue1),
    .extDscrptrAddr(extDscrptrAddr),
    .extDscrptr(extDscrptr),
    .chain(chain),
    .extDscrptrNxt(extDscrptrNxt),
    .intOnProcess(intOnProcess),
    .nxtDscrptrNumAddr(nxtDscrptrNumAddr),
    .spaceWrTranQueue(spaceWrTranQueue)
);

// Clock toggle generation
initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [8*48-1:0] label;
    begin
        $display(
            {"t=%0t case=%0d %0s resetn=%b wr=%b rd=%b ",
             "reqInQueue=%b spaceWrTranQueue=%b strDscrptr=%b ",
             "priLvl=%h dataValid=%b dstOp=%h dstDataWidth=%h ",
             "srcDataWidth=%h dstAddr_wrCache1Sel=%h ",
             "dstAddr_rdCache1Sel=%h numOfBytes=%h ",
             "intDscrptrNum_wrTranQueue0=%h ",
             "intDscrptrNum_wrTranQueue1=%h extDscrptrAddr=%h ",
             "extDscrptr=%b chain=%b extDscrptrNxt=%b ",
             "intOnProcess=%b nxtDscrptrNumAddr=%h"},
            $time, tc, label, resetn, wrCache1Sel, rdCache1Sel,
            reqInQueue, spaceWrTranQueue, strDscrptr,
            priLvl, dataValid, dstOp, dstDataWidth, srcDataWidth,
            dstAddr_wrCache1Sel, dstAddr_rdCache1Sel, numOfBytes,
            intDscrptrNum_wrTranQueue0, intDscrptrNum_wrTranQueue1,
            extDscrptrAddr, extDscrptr, chain, extDscrptrNxt,
            intOnProcess, nxtDscrptrNumAddr
        );
    end
endtask

task views;
    input [8*48-1:0] label;
    integer s;
    begin
        for (s = 0; s < 4; s = s + 1) begin
            wrCache1Sel = s[1];
            rdCache1Sel = s[0];
            #1;
            observe(label);
        end
    end
endtask

task quiet;
    begin
        doTrans = 0;
        clrWrTranQueue = 0;
        rdyToAck = 0;
        extDataValid = 0;
        strDscrptr_DMAArbiter = 0;
    end
endtask

task metadata;
    input integer n;
    begin
        intDscrptrNum_DMAArbiter = n;
        extDscrptrAddr_DMAArbiter = 32'h12345670 + n;
        dstAddr_DMAArbiter = 32'h89abcdef ^ n;
        nxtDscrptrNumAddr_DMAArbiter = 32'h55aa55aa ^ n;
        numOfBytes_DMAArbiter = n;
        priLvl_DMAArbiter = {NUM_PRI_LVLS{n[0]}};
        extDscrptr_DMAArbiter = n[0];
        dataValid_DMAArbiter = n[1];
        dstOp_DMAArbiter = n[1:0];
        dstDataWidth_DMAArbiter = n[2:0];
        srcDataWidth_DMAArbiter = ~n[2:0];
        chain_DMAArbiter = n[2];
        extDscrptrNxt_DMAArbiter = ~n[1];
        intOnProcess_DMAArbiter = ~n[2];
        case (n)
            0: begin
                intDscrptrNum_DMAArbiter = 0;
                extDscrptrAddr_DMAArbiter = 0;
                dstAddr_DMAArbiter = 0;
                nxtDscrptrNumAddr_DMAArbiter = 0;
                numOfBytes_DMAArbiter = 0;
            end
            1: begin
                intDscrptrNum_DMAArbiter = {NUM_INT_BDS_WIDTH{1'b1}};
                extDscrptrAddr_DMAArbiter = 32'hffffffff;
                dstAddr_DMAArbiter = 32'hffffffff;
                nxtDscrptrNumAddr_DMAArbiter = 32'hffffffff;
                numOfBytes_DMAArbiter = {MAX_TRAN_SIZE_WIDTH{1'b1}};
            end
            2: begin
                intDscrptrNum_DMAArbiter = 1;
                extDscrptrAddr_DMAArbiter = 1;
                dstAddr_DMAArbiter = 1;
                nxtDscrptrNumAddr_DMAArbiter = 1;
                numOfBytes_DMAArbiter = 1;
            end
        endcase
    end
endtask

// One active edge, followed by observation and four idle selector views.
task step;
    input enq;
    input [1:0] removals;
    input ack, valid, stream, wsel, rsel;
    input [8*48-1:0] label;
    begin
        @(negedge clk);
        doTrans = enq;
        clrWrTranQueue = removals;
        rdyToAck = ack;
        extDataValid = valid;
        strDscrptr_DMAArbiter = stream;
        wrCache1Sel = wsel;
        rdCache1Sel = rsel;
        @(posedge clk);
        #1;
        observe(label);
        quiet;
        views(label);
    end
endtask

task reset_dut;
    begin
        @(negedge clk);
        quiet;
        #1;
        resetn = 0;
        #1;
        observe("asynchronous reset");
        views("reset selector views");
        @(negedge clk);
        resetn = 1;
    end
endtask

task fill_two;
    begin
        metadata(2);
        step(1, 0, 0, 0, 0, 0, 0, "capture bank 0");
        metadata(5);
        step(1, 0, 0, 0, 0, 1, 1, "capture bank 1");
    end
endtask

task ready_both;
    begin
        step(0, 0, 1, 1, 0, 0, 0, "set bank 0 without capture");
        step(0, 0, 1, 1, 0, 1, 1, "set bank 1 without capture");
    end
endtask

initial begin
    // Initialize inputs; allow 100 ns for global reset.
    tc = 0;
    resetn = 0;
    wrCache1Sel = 0;
    rdCache1Sel = 0;
    quiet;
    metadata(0);
    #100;
    views("initial reset");
    @(negedge clk);
    resetn = 1;

    // Case 1: metadata encodings, alternating capture, removal and reuse.
    tc = 1;
    reset_dut;
    for (i = 0; i < 16; i = i + 1) begin
        #1;
        j = (i / 2 + i % 2) % 8;
        metadata(j);
        step(1, 0, 0, 0, j[0], i[0], i[0], "metadata capture");
        metadata(7 - j);
        step(0, 0, 0, 0, 0, i[0], ~i[0], "changed inputs without capture");
        if (i[0])
            step(0, 3, 0, 0, 0, 0, 1, "remove pair; retain metadata");
    end

    // Case 2: every count-update input, including modular stress.
    for (c = 0; c < 4; c = c + 1) begin
        #1;
        for (op = 0; op < 8; op = op + 1) begin
            #1;
            tc = 100 + 8*c + op;
            reset_dut;
            ready_both;
            for (j = 0; j < c; j = j + 1) begin
                #1;
                metadata(j + 2);
                step(1, 0, 0, 0, 0, j[0], j[0], "occupancy setup");
            end
            metadata(7);
            step(op[2], op[1:0], 0, 0, 0, op[0], 0,
                 "enqueue/removal combination");
            ready_both;
            step(0, 0, 0, 0, 0, 0, 1, "occupancy held with readiness");
        end
    end

    // Case 3: initial readiness, selectors and all readiness-set inputs.
    for (k = 0; k < 64; k = k + 1) begin
        #1;
        tc = 200 + k;
        reset_dut;
        fill_two;
        if (k[5])
            ready_both;
        step(0, 0, 0, 0, 0, k[4], k[3], "readiness baseline");
        step(0, k[4] ? 2'b10 : 2'b01,
             k[2], k[1], k[0], k[4], k[3],
             "readiness event with single removal");
        step(0, 0, 0, 0, 0, k[4], k[3], "readiness hold");
    end

    // Case 4: double clear, retained readiness, and global set priority.
    for (k = 0; k < 12; k = k + 1) begin
        #1;
        tc = 300 + k;
        reset_dut;
        fill_two;
        ready_both;
        case (k / 4)
            0: step(0, 3, 0, 0, 0, k[1], k[0],
                    "double removal without set");
            1: step(0, 3, 1, 1, 0, k[1], k[0],
                    "double removal with external set");
            2: step(0, 3, 0, 0, 1, k[1], k[0],
                    "double removal with streaming set");
        endcase
        metadata(6);
        step(1, 0, 0, 0, 0, 0, 1, "refill reveals retained readiness");
    end

    // Case 5: dirty asynchronous reset and restarted capture order.
    tc = 400;
    reset_dut;
    fill_two;
    ready_both;
    metadata(7);
    step(1, 1, 1, 1, 1, 0, 1, "dirty state with odd capture parity");
    reset_dut;
    metadata(3);
    step(1, 0, 0, 0, 0, 1, 1, "first capture after dirty reset");
    metadata(4);
    step(1, 0, 0, 0, 0, 0, 0, "second capture after dirty reset");

    $display("===========End===========");
    $finish;
end

endmodule

