    begin
        @(negedge clk);
        CNT_RST = 0;
        CNT_en = 0;
        CNT_done = 0;
        CNT_clk_freq = selection;
        #1;
        observe("reset asserted");
        advance(2);
        observe("reset held");
        @(negedge clk);
        CNT_RST = 1;
        CNT_en = 1;
    end
endtask

// Sample the cycles surrounding a scheduled minute update.
task boundary;
    input integer cycles_to_update;
    input [8*64-1:0] label;
    begin
        advance(cycles_to_update - 2);
        observe(label);
        advance(1);
        observe("terminal cycle before minute update");
        advance(1);
        observe("after minute update");
    end
endtask

initial begin
    // Initialize Inputs
    CNT_clk_freq = 0;
    CNT_done = 0;
    CNT_en = 0;
    CNT_RST = 0;

    // Wait 100 ns for global reset to finish
    #100;
    observe("initial reset");
    @(negedge clk);
    CNT_RST = 1;
    advance(3);
    observe("reset released while disabled");

    // All dividers, all minute states, and wash-count wrap.
    for (mode = 0; mode < 4; mode = mode + 1) begin
        #1;
        divider = 10 * (1 << mode);
        minute_limit = 8;
        if (mode == 0)
            minute_limit = 29;
        restart(mode);
        for (minute_no = 1; minute_no <= minute_limit;
             minute_no = minute_no + 1) begin
            #1;
            boundary(60 * divider, "divider sweep: before terminal");
        end
    end

    // Pause with a partially accumulated second.
    restart(0);
    advance(30 * 10 + 3);
    observe("partial second before pause");
    @(negedge clk);
    CNT_en = 0;
    advance(7);
    observe("partial second paused");
    @(negedge clk);
    CNT_en = 1;
    boundary(30 * 10 - 3, "resumed partial second: before terminal");

    // Pause an active event after one wash increment has accumulated.
    restart(0);
    advance(13 * 60 * 10 - 2);
    observe("before repeated fifth-minute event");
    advance(1);
    observe("repeated fifth-minute event active");
    @(negedge clk);
    CNT_en = 0;
    #1;
    observe("event disabled before clock edge");
    advance(3);
    observe("disabled edges clear wash count");
    @(negedge clk);
    CNT_en = 1;
    #1;
    observe("event restored on enable");
    advance(1);
    observe("resumed event consumed");
    advance(1);
    observe("wash count holds after resumed event");

    // Done away from a terminal count; seconds remain partially elapsed.
    restart(0);
    advance(2 * 60 * 10 + 30 * 10 + 3);
    observe("before nonterminal done");
    @(negedge clk);
    CNT_done = 1;
    advance(1);
    observe("nonterminal done applied");
    advance(3);
    observe("nonterminal done held");
    @(negedge clk);
    CNT_done = 0;
    boundary(30 * 10, "after partial clear: before terminal");

    // Done coincident with the second tick advancing seconds to 59.
    restart(0);
    advance(59 * 10 - 1);
    observe("ordinary second terminal before done");
    @(negedge clk);
    CNT_done = 1;
    advance(1);
    observe("done coincident with ordinary second tick");
    @(negedge clk);
    CNT_done = 0;
    boundary(10, "retained seconds after terminal done");

    // Done coincident with a fifth-minute event.
    restart(0);
    advance(5 * 60 * 10 - 1);
    observe("fifth-minute event before done");
    @(negedge clk);
    CNT_done = 1;
    #1;
    observe("done asserted during fifth-minute event");
    advance(1);
    observe("fifth-minute event consumed with done");
    @(negedge clk);
    CNT_done = 0;
    boundary(60 * 10, "first minute after coincident done");

    // Done clears divider/minutes even while disabled.
    restart(0);
    advance(5 * 60 * 10 + 30 * 10 + 3);
    observe("nonzero wash count before disabled done");
    @(negedge clk);
    CNT_en = 0;
    CNT_done = 1;
    advance(2);
    observe("done held while disabled");
    @(negedge clk);
    CNT_done = 0;
    advance(2);
    observe("disabled after done release");
    @(negedge clk);
    CNT_en = 1;
    boundary(30 * 10, "resume after disabled partial clear");

    // Asynchronous reset during an event, between clock edges.
    restart(0);
    advance(13 * 60 * 10 - 1);
    observe("active event and nonzero wash before reset");
    #2;
    CNT_RST = 0;
    #1;
    observe("asynchronous reset before next clock edge");
    advance(2);
    observe("reset held with enable high");
    @(negedge clk);
    CNT_RST = 1;
    boundary(60 * 10, "first minute after asynchronous reset");

    // Increase divider during the terminal cycle at subsecond count 9.
    restart(0);
    advance(60 * 10 - 1);
    observe("event before selecting slower divider");
    @(negedge clk);
    CNT_clk_freq = 3;
    #1;
    observe("slower divider selected");
    boundary(80 - 10 + 1, "slower divider: before terminal");

    // Decrease divider at subsecond count 9, with 59 seconds elapsed.
    restart(3);
    advance(59 * 80 + 9);
    observe("before selecting faster divider");
    @(negedge clk);
    CNT_clk_freq = 0;
    #1;
    observe("faster divider selected");
    advance(1);
    observe("minute update after faster divider selection");
    advance(1);
    observe("after faster-divider event");

    $display("===========End===========");
    $finish;
end

endmodule

