module testbench;

// Inputs
reg clk;
reg [3:0] in3, in2, in1, in0;
reg [1:0] sel;

// Outputs
wire [3:0] out;

integer s, d;

// Instantiate the Unit Under Test (UUT)
mux_4to1 uut (
    .in3(in3),
    .in2(in2),
    .in1(in1),
    .in0(in0),
    .sel(sel),
    .out(out)
);

// clk toggle generate
initial clk = 0; // clk is initialized as 0
always #5 clk = ~clk;

task drive_selected;
    input [3:0] value;
    begin
        case (sel)
            2'b00: in0 = value;
            2'b01: in1 = value;
            2'b10: in2 = value;
            2'b11: in3 = value;
        endcase
    end
endtask

task observe;
    input [8*24-1:0] label;
    begin
        $display("%0s sel=%b in3=%h in2=%h in1=%h in0=%h out=%h",
                 label, sel, in3, in2, in1, in0, out);
    end
endtask

initial begin
    // Initialize Inputs
    in3 = 0;
    in2 = 0;
    in1 = 0;
    in0 = 0;
    sel = 0;

    // Wait 100 ns for global reset to finish
    #100;
    observe("initialization");

    // Test Case 1: Selection changes with fixed, distinct data
    in0 = 4'h1;
    in1 = 4'h2;
    in2 = 4'h4;
    in3 = 4'h8;
    for (s = 0; s < 5; s = s + 1) begin
        sel = s % 4;
        #1;
        observe("selection");
    end

    // Test Case 2: All data values and unselected-input isolation
    for (s = 0; s < 4; s = s + 1) begin
        sel = s;
        in0 = 0;
        in1 = 0;
        in2 = 0;
        in3 = 0;
        #1;
        observe("group initialization");

        for (d = 0; d < 16; d = d + 1) begin
            in0 = ~d[3:0];
            in1 = ~d[3:0];
            in2 = ~d[3:0];
            in3 = ~d[3:0];
            drive_selected(d[3:0]);
            #1;
            observe("selected data");

            // Selected input retains its value; other inputs toggle.
            in0 = d[3:0];
            in1 = d[3:0];
            in2 = d[3:0];
            in3 = d[3:0];
            #1;
            observe("unselected changes");
        end
    end

    // Test Case 3: Exercise the implicit no-match path of the case statement.
    // Unknown or high-impedance select values match none of the legal cases.
    in0 = 4'ha;
    in1 = 4'h5;
    in2 = 4'hc;
    in3 = 4'h3;

    sel = 2'bxx;
    #1;
    observe("unknown select");

    sel = 2'bzz;
    #1;
    observe("high impedance select");

    sel = 2'b0x;
    #1;
    observe("partial unknown select");

    sel = 2'bx1;
    #1;
    observe("partial unknown select");

    sel = 2'b1z;
    #1;
    observe("partial high impedance");

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

reg clk;
reg reset_n;
reg [15:0] bit_rate;
reg [3:0] data_bits;
reg [1:0] stop_bits;
reg rxd;
reg rxd_ack;
reg txd_syn;
reg [7:0] txd_data;

wire txd;
wire rxd_syn;
wire [7:0] rxd_data;
wire txd_ready;

integer case_id;
integer i;

uart_core uut (
    .clk(clk), .reset_n(reset_n),
    .bit_rate(bit_rate), .data_bits(data_bits), .stop_bits(stop_bits),
    .rxd(rxd), .txd(txd), .rxd_syn(rxd_syn),
    .rxd_data(rxd_data), .rxd_ack(rxd_ack),
    .txd_syn(txd_syn), .txd_data(txd_data),
    .txd_ready(txd_ready)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input integer phase;
    begin
        $display("case=%0d phase=%0d txd=%b rxd_syn=%b rxd_data=%h txd_ready=%b",
                 case_id, phase, txd, rxd_syn, rxd_data, txd_ready);
    end
endtask

task reset_dut;
    input [15:0] rate;
    input [3:0] bits;
    input [1:0] stops;
    begin
        reset_n = 0;
        bit_rate = rate;
        data_bits = bits;
        stop_bits = stops;
        rxd = 1;
        rxd_ack = 0;
        txd_syn = 0;
        txd_data = 0;
        repeat (2) @(posedge clk);
        #1;
        observe(0);
        reset_n = 1;
        repeat (6) @(posedge clk);
        #1;
        observe(1);
    end
endtask

task acknowledge_rx;
    begin
        rxd_ack = 1;
        @(posedge clk);
        #1;
        observe(90);
        rxd_ack = 0;
        repeat (4) @(posedge clk);
        #1;
        observe(91);
    end
endtask

task receive_frame;
    input [7:0] value;
    input integer low_stop;
    integer bit_index;
    begin
        rxd = 0;
        repeat (bit_rate + 1) @(posedge clk);
        #1;
        observe(10);
        for (bit_index = 0; bit_index < data_bits; bit_index = bit_index + 1) begin
            rxd = value[bit_index % 8];
            repeat (bit_rate + 1) @(posedge clk);
            #1;
            observe(20 + bit_index);
        end
        rxd = low_stop ? 0 : 1;
        repeat ((stop_bits + 1) * (bit_rate + 1) + 8) @(posedge clk);
        #1;
        observe(40);
        rxd = 1;
        repeat (4) @(posedge clk);
        #1;
        observe(41);
    end
endtask

task transmit_frame;
    input [7:0] value;
    input integer hold_cycles;
    integer bit_index;
    begin
        txd_data = value;
        txd_syn = 1;
        @(posedge clk);
        #1;
        observe(50);
        txd_data = ~value;
        repeat (hold_cycles) @(posedge clk);
        #1;
        observe(51);
        txd_syn = 0;
        @(posedge clk);
        #1;
        observe(52);
        repeat (bit_rate + 1) @(posedge clk);
        #1;
        observe(53);
        for (bit_index = 0; bit_index < data_bits; bit_index = bit_index + 1) begin
            @(posedge clk);
            #1;
            observe(60 + bit_index);
            repeat (bit_rate) @(posedge clk);
            #1;
        end
        @(posedge clk);
        #1;
        observe(80);
        repeat (bit_rate * stop_bits) @(posedge clk);
        #1;
        observe(81);
        @(posedge clk);
        #1;
        observe(82);
    end
endtask

initial begin
    reset_n = 0;
    bit_rate = 15;
    data_bits = 8;
    stop_bits = 1;
    rxd = 1;
    rxd_ack = 0;
    txd_syn = 0;
    txd_data = 0;
    case_id = 0;

    #100;

    // Reset and rejected short start.
    case_id = 1;
    reset_dut(15, 8, 1);
    rxd = 0;
    repeat (3) @(posedge clk);
    #1;
    observe(2);
    rxd = 1;
    repeat (20) @(posedge clk);
    #1;
    observe(3);

    // Full receive frame and held notification.
    case_id = 2;
    reset_dut(15, 8, 1);
    receive_frame(8'ha6, 0);
    acknowledge_rx();

    // Short frames without resetting between them retain receive history.
    case_id = 3;
    reset_dut(15, 7, 2);
    receive_frame(8'h53, 1);
    acknowledge_rx();
    data_bits = 1;
    receive_frame(8'h01, 0);
    acknowledge_rx();

    // Even bit rate and zero stop multiplier.
    case_id = 4;
    reset_dut(16, 8, 0);
    receive_frame(8'h81, 0);
    acknowledge_rx();

    // Transmit request hold, captured data, and normal framing.
    case_id = 5;
    reset_dut(15, 8, 1);
    transmit_frame(8'h96, 4);

    // Transmit data-count and stop-duration boundaries.
    case_id = 6;
    reset_dut(16, 1, 0);
    transmit_frame(8'h01, 1);
    case_id = 7;
    reset_dut(15, 9, 2);
    transmit_frame(8'hc5, 1);

    // Both engines active; reset partway through their frames.
    case_id = 8;
    reset_dut(15, 8, 1);
    txd_data = 8'h39;
    txd_syn = 1;
    rxd = 0;
    repeat (2) @(posedge clk);
    #1;
    observe(50);
    txd_syn = 0;
    repeat (bit_rate + 1) @(posedge clk);
    #1;
    for (i = 0; i < 8; i = i + 1) begin
        rxd = (8'hb2 >> i) & 1'b1;
        repeat (bit_rate + 1) @(posedge clk);
        #1;
        observe(60 + i);
    end
    rxd = 1;
    repeat (2 * (bit_rate + 1) + 8) @(posedge clk);
    #1;
    observe(80);
    reset_n = 0;
    @(posedge clk);
    #1;
    observe(81);

    // Reset RX during data collection and TX while its request is held.
    case_id = 9;
    reset_dut(15, 8, 1);
    rxd = 0;
    txd_data = 8'ha5;
    txd_syn = 1;
    repeat (bit_rate + 1) @(posedge clk);
    #1;
    observe(70);
    reset_n = 0;
    @(posedge clk);
    #1;
    observe(71);

    // Complete RX data sampling, then reset during RX stop and TX start.
    case_id = 10;
    reset_dut(15, 8, 1);
    rxd = 0;
    repeat (bit_rate + 1) @(posedge clk);
    #1;
    observe(10);
    for (i = 0; i < 8; i = i + 1) begin
        rxd = (8'h5a >> i) & 1'b1;
        repeat (bit_rate + 1) @(posedge clk);
        #1;
        observe(20 + i);
    end
    rxd = 1;
    txd_data = 8'hc3;
    txd_syn = 1;
    @(posedge clk);
    #1;
    observe(50);
    txd_syn = 0;
    @(posedge clk);
    #1;
    observe(52);
    reset_n = 0;
    @(posedge clk);
    #1;
    observe(81);

    // Reset TX after it has entered data transmission.
    case_id = 11;
    reset_dut(15, 8, 1);
    txd_data = 8'h69;
    txd_syn = 1;
    @(posedge clk);
    #1;
    observe(50);
    txd_syn = 0;
    @(posedge clk);
    #1;
    observe(52);
    repeat (bit_rate + 3) @(posedge clk);
    #1;
    observe(60);
    reset_n = 0;
    @(posedge clk);
    #1;
    observe(81);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam [80:0] IDENTITY = {
    9'sd1, 9'sd0, 9'sd0,
    9'sd0, 9'sd1, 9'sd0,
    9'sd0, 9'sd0, 9'sd1
};
localparam [80:0] DENSE = {
     9'sd2, -9'sd3,  9'sd5,
    -9'sd7,  9'sd11, 9'sd13,
     9'sd17, 9'sd19, -9'sd23
};
localparam [80:0] MIXED = {
    -9'sd29, 9'sd31,  9'sd37,
     9'sd41, -9'sd43, 9'sd47,
     9'sd53, 9'sd59, -9'sd61
};
localparam [80:0] CANCEL = {
    9'sd1,  9'sd1, 9'sd1,
    9'sd1, -9'sd1, 9'sd0,
   -9'sd1,  9'sd0, 9'sd1
};
localparam [80:0] BOUNDARY = {
    9'sh100, 9'sd255,  9'sd0,
    9'sd255, -9'sd255, 9'sd1,
   -9'sd1,   9'sh100,  9'sd255
};

// Inputs: packed matrices use row-major element order.
reg clk;
reg irst_n;
reg [80:0] a, b;

// Outputs
wire signed [18:0] odata11, odata12, odata13;
wire signed [18:0] odata21, odata22, odata23;
wire signed [18:0] odata31, odata32, odata33;
integer i, edge_number;

MultipleMatrix_3x3_3x3 uut (
    .iclk(clk), .irst_n(irst_n),
    .iData_a11(a[80:72]), .iData_a12(a[71:63]),
    .iData_a13(a[62:54]), .iData_a21(a[53:45]),
    .iData_a22(a[44:36]), .iData_a23(a[35:27]),
    .iData_a31(a[26:18]), .iData_a32(a[17:9]),
    .iData_a33(a[8:0]),
    .iData_b11(b[80:72]), .iData_b12(b[71:63]),
    .iData_b13(b[62:54]), .iData_b21(b[53:45]),
    .iData_b22(b[44:36]), .iData_b23(b[35:27]),
    .iData_b31(b[26:18]), .iData_b32(b[17:9]),
    .iData_b33(b[8:0]),
    .odata11(odata11), .odata12(odata12), .odata13(odata13),
    .odata21(odata21), .odata22(odata22), .odata23(odata23),
    .odata31(odata31), .odata32(odata32), .odata33(odata33)
);

initial clk = 0;

always #5 clk = ~clk;

task observe;
    input [8*32-1:0] label;
    input integer test_id;
    input integer sample_id;
    begin
        $display(
            "t=%0t %0s case=%0d sample=%0d rst_n=%b odata11=%0d odata12=%0d odata13=%0d odata21=%0d odata22=%0d odata23=%0d odata31=%0d odata32=%0d odata33=%0d",
            $time, label, test_id, sample_id, irst_n,
            odata11, odata12, odata13,
            odata21, odata22, odata23,
            odata31, odata32, odata33
        );
    end
endtask

task sample_edge;
    input [8*32-1:0] label;
    input integer test_id;
    input integer sample_id;
    begin
        @(posedge clk);
        #1;
        observe(label, test_id, sample_id);
    end
endtask

task reset_clean;
    input integer test_id;
    begin
        @(negedge clk);
        irst_n = 0;
        a = 0;
        b = 0;
        #1;
        observe("case_reset", test_id, 0);
        @(negedge clk);
        irst_n = 1;
    end
endtask

task select_pair;
    input integer test_id;
    begin
        case (test_id)
             0: begin a = 0;                b = DENSE;           end
             1: begin a = DENSE;            b = 0;               end
             2: begin a = IDENTITY;         b = DENSE;           end
             3: begin a = DENSE;            b = IDENTITY;        end
             4: begin a = DENSE;            b = MIXED;           end
             5: begin
                    a = CANCEL;
                    b = {3{9'sd255, 9'sh100, 9'sd1}};
                end
             6: begin a = {9{9'sd255}};     b = {9{9'sd255}};    end
             7: begin a = {9{9'sh100}};     b = {9{9'sd255}};    end
             8: begin a = {9{9'sd255}};     b = {9{9'sh100}};    end
             9: begin a = {9{9'sh100}};     b = {9{9'sh100}};    end
            10: begin a = {9{9'sh100}};     b = {9{-9'sd255}};   end
            11: begin a = BOUNDARY;         b = BOUNDARY;        end
            default: begin a = 0;          b = 0;               end
        endcase
    end
endtask

initial begin
    // Initialize inputs and allow 100 ns for startup reset.
    irst_n = 0;
    a = 0;
    b = 0;
    #100;
    observe("startup_reset", 0, 0);

    // Independent arithmetic and boundary cases.
    for (i = 0; i < 12; i = i + 1) begin
        reset_clean(i);
        #1;
        select_pair(i);
        for (edge_number = 1; edge_number <= 3;
             edge_number = edge_number + 1) begin
            @(posedge clk);
            #1;
            observe("arithmetic", i, edge_number);
        end
    end

    // Isolate each A element; dense B exercises its three product paths.
    for (i = 0; i < 9; i = i + 1) begin
        reset_clean(20 + i);
        #1;
        a[80 - 9*i -: 9] = 9'sd1;
        b = DENSE;
        repeat (2) @(posedge clk);
        #1;
        observe("single_element_A", i, 2);
    end

    // Continuous traffic, followed by two drain cycles.
    reset_clean(40);
    for (i = 0; i < 12; i = i + 1) begin
        @(negedge clk);
        select_pair(i);
        sample_edge("stream", i, 1);
    end
    @(negedge clk);
    a = 0;
    b = 0;
    sample_edge("stream_drain", 40, 1);
    sample_edge("stream_drain", 40, 2);

    // Establish a result, then capture a different pending matrix pair.
    reset_clean(50);
    select_pair(4);
    sample_edge("before_async_reset", 50, 1);
    sample_edge("before_async_reset", 50, 2);
    @(negedge clk);
    select_pair(9);
    sample_edge("pending_before_reset", 50, 3);

    // Reset pulse has no rising clock edge inside it.
    @(negedge clk);
    #1;
    irst_n = 0;
    #1;
    observe("async_pulse_asserted", 50, 4);
    #1;
    irst_n = 1;
    select_pair(2);
    sample_edge("pulse_recovery", 50, 1);
    sample_edge("pulse_recovery", 50, 2);

    // Hold reset across clocks while changing inputs.
    @(negedge clk);
    #1;
    irst_n = 0;
    select_pair(9);
    #1;
    observe("held_reset_asserted", 51, 0);
    sample_edge("held_reset", 51, 1);
    @(negedge clk);
    select_pair(11);
    sample_edge("held_reset", 51, 2);
    @(negedge clk);
    irst_n = 1;
    sample_edge("held_reset_recovery", 51, 1);
    sample_edge("held_reset_recovery", 51, 2);

    $display("===========End===========");
    $finish;
end

endmodule

