always #5 clk = ~clk;

task reset_dut;
begin
    rst_n = 0;
    #1;
    repeat (1) @(posedge clk);
    #1;
    rst_n = 1;
    repeat (1) @(posedge clk);
    #1;
end
endtask

task apply_and_observe;
    input integer case_id;
    input [39:0] a_value;
    input [37:0] b_value;
    input [27:0] c_value;
    input [17:0] d_value;
    input [8:0]  coeff_value;
begin
    a         = a_value;
    b         = b_value;
    c         = c_value;
    d         = d_value;
    coeffHalf = coeff_value;

    @(posedge clk);
    repeat (2) @(posedge clk);
    #1;

    $display("Test Case %0d: result = %h", case_id, result);
end
endtask

initial begin
    a         = 40'd0;
    b         = 38'd0;
    c         = 28'd0;
    d         = 18'd0;
    coeffHalf = 9'd0;
    rst_n     = 1'b1;

    #1;
    rst_n = 1'b0;
