    $display("Reset asserted asynchronously: result = %h", result);

    repeat (1) @(posedge clk);
    #1;
    $display("Reset active at clock edge: result = %h", result);

    rst_n = 1'b1;
    repeat (1) @(posedge clk);
    #1;

    // Test Case 1: all-zero arithmetic inputs
    reset_dut;
    apply_and_observe(
        1,
        40'd0,
        38'd0,
        28'd0,
        18'd0,
        9'd0
    );

    // Test Case 2: upper-path maximum values
    reset_dut;
    apply_and_observe(
        2,
        {40{1'b1}},
        38'd0,
        {28{1'b1}},
        18'd0,
        9'd0
    );

    // Test Case 3: lower-path maximum values
    reset_dut;
    apply_and_observe(
        3,
        40'd0,
        {38{1'b1}},
        28'd0,
        {18{1'b1}},
        9'd0
    );

    // Test Case 4: mixed upper and lower arithmetic paths
    reset_dut;
    apply_and_observe(
        4,
        40'h0123_4567_89,
        38'h2A_BCDE_F012,
        28'h0A_BCDEF0,
