        5,
        {40{1'b1}},
        {38{1'b1}},
        {28{1'b1}},
        {18{1'b1}},
        9'd0
    );

    // Test Case 6: same arithmetic inputs with a different coeffHalf value
    reset_dut;
    apply_and_observe(
        6,
        40'h0000_1234_56,
        38'h02_3456_789A,
        28'h012_34567,
        18'h2_3456,
