        40'h0000_1234_56,
        38'h02_3456_789A,
        28'h012_34567,
        18'h2_3456,
        9'h1FF
    );

    // Test Case 7: consecutive inputs to exercise pipeline throughput
    reset_dut;

    a         = 40'h0000_0000_01;
    b         = 38'h00_0000_0001;
    c         = 28'h000_00001;
    d         = 18'h0_0001;
