    @(posedge clk);

    a         = 40'h0000_0000_AA;
    b         = 38'h00_0000_00BB;
    c         = 28'h000_000CC;
    d         = 18'h0_00DD;
    coeffHalf = 9'h022;
    @(posedge clk);

