    #1;
    $display("Pipeline Test 1: result = %h", result);

    a         = 40'h000F_FFFF_FF;
    b         = 38'h3F_FFFF_FFFF;
    c         = 28'hFFF_FFFFF;
    d         = 18'h3_FFFF;
    coeffHalf = 9'h1FF;
    @(posedge clk);

    #1;
    $display("Pipeline Test 2: result = %h", result);

