module testbench;

// Inputs
reg clk;
reg nvdla_core_rstn;
reg [5:0] info_pipe_in_pd_d0;
reg info_pipe_in_rdy_d1;
reg info_pipe_in_vld_d0;

// Outputs
wire [5:0] info_pipe_in_pd_d1;
wire info_pipe_in_rdy_d0;
wire info_pipe_in_vld_d1;

integer i;

FP_FORMAT_CVT_pipe_p1 uut (
    .nvdla_core_clk(clk),
    .nvdla_core_rstn(nvdla_core_rstn),
    .info_pipe_in_pd_d0(info_pipe_in_pd_d0),
    .info_pipe_in_rdy_d1(info_pipe_in_rdy_d1),
    .info_pipe_in_vld_d0(info_pipe_in_vld_d0),
    .info_pipe_in_pd_d1(info_pipe_in_pd_d1),
    .info_pipe_in_rdy_d0(info_pipe_in_rdy_d0),
    .info_pipe_in_vld_d1(info_pipe_in_vld_d1)
);

initial clk = 0;
always #5 clk = ~clk;

task observe;
    input [8*48-1:0] label;
    begin
        $display("%0t %0s rstn=%b in_pd=%h in_vld=%b down_rdy=%b | pd_d1=%h rdy_d0=%b vld_d1=%b",
                 $time, label, nvdla_core_rstn,
                 info_pipe_in_pd_d0, info_pipe_in_vld_d0,
                 info_pipe_in_rdy_d1, info_pipe_in_pd_d1,
                 info_pipe_in_rdy_d0, info_pipe_in_vld_d1);
    end
endtask

task step;
    input [8*48-1:0] label;
    input upstream_valid;
    input downstream_ready;
    input [5:0] payload;
    begin
        @(negedge clk);
        info_pipe_in_vld_d0 = upstream_valid;
        info_pipe_in_rdy_d1 = downstream_ready;
        info_pipe_in_pd_d0 = payload;
        #1;
        observe({label, " pre-edge"});
        @(posedge clk);
        #1;
        observe({label, " post-edge"});
    end
endtask

task reset_stage;
    begin
        @(negedge clk);
        info_pipe_in_vld_d0 = 0;
        info_pipe_in_rdy_d1 = 0;
        #2;
        nvdla_core_rstn = 0;
        #1;
        observe("reset asserted between edges");
        repeat (2) @(posedge clk);
        #1;
        observe("reset held");
        @(negedge clk);
        nvdla_core_rstn = 1;
        #1;
        observe("reset released");
    end
endtask

initial begin
    nvdla_core_rstn = 0;
    info_pipe_in_pd_d0 = 0;
    info_pipe_in_rdy_d1 = 0;
    info_pipe_in_vld_d0 = 0;

    // Wait 100 ns for global reset to finish.
    #100;
    observe("initial reset");

    // Test Case 1: Empty, stalled, replaced, and drained.
    reset_stage;
    step("empty idle, downstream blocked", 0, 0, 6'h15);
    step("empty idle, downstream ready",   0, 1, 6'h2a);
    step("capture into empty blocked stage", 1, 0, 6'h00);
    step("occupied stall, upstream invalid", 0, 0, 6'h3f);
    step("occupied stall, pending valid",    1, 0, 6'h2a);
    step("continued stall, pending stable",  1, 0, 6'h2a);
    step("release stall and replace",        1, 1, 6'h2a);
    step("drain without replacement",        0, 1, 6'h15);
    step("empty idle retains payload",       0, 0, 6'h3f);

    // Test Case 2: Consecutive transfers and payload boundaries.
    reset_stage;
    for (i = 0; i < 4; i = i + 1) begin
        @(negedge clk);
        info_pipe_in_vld_d0 = 1;
        info_pipe_in_rdy_d1 = 1;
        info_pipe_in_pd_d0 = i * 21;
        #1;
        observe("stream pre-edge");
        @(posedge clk);
        #1;
        observe("stream post-edge");
    end
    step("stream drain", 0, 1, 6'h00);
    step("idle after drain", 0, 1, 6'h15);

    // Test Case 3: Asynchronous reset of an occupied blocked stage.
    reset_stage;
    step("load before reset", 1, 0, 6'h15);
    step("hold before reset", 0, 0, 6'h2a);
    reset_stage;
    step("idle after occupied reset", 0, 1, 6'h00);
    step("capture after reset", 1, 0, 6'h3f);
    step("drain after recovery", 0, 1, 6'h00);

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

localparam COUNT_KEY = 33;
localparam COUNT_SEQ = 33;
localparam DEC_SEQ   = 1;
localparam COUNT_FIN = 8;
localparam SIZE_MEM  = 32;

// Inputs
reg clk;
reg reset;
reg start;
reg [3:0] k;

// Outputs
wire nloss;
wire [3:0] nl;
wire speaker;

reg [3:0] keys_seen [0:SIZE_MEM-1];
reg [3:0] driven_keys;
integer case_id;
integer phase, key_mode, boundary;
integer fault_mode, action, stage, finish_mode;
integer round_no, item;

b12 #(
    .COUNT_KEY(COUNT_KEY),
    .COUNT_SEQ(COUNT_SEQ),
    .DEC_SEQ(DEC_SEQ),
    .COUNT_FIN(COUNT_FIN)
) uut (
    .clock(clk),
    .reset(reset),
    .start(start),
    .k(k),
    .nloss(nloss),
    .nl(nl),
    .speaker(speaker)
);

initial clk = 0;
always #5 clk = ~clk;

task show;
begin
    $display("case=%0d time=%0t reset=%b start=%b k=%b nloss=%b nl=%b speaker=%b",
             case_id, $time, reset, start, k, nloss, nl, speaker);
end
endtask

task advance;
    input integer cycles;
begin
    repeat (cycles) @(posedge clk);
    #1;
    show;
end
endtask

task trace;
    input integer cycles;
    integer sample_no;
begin
    for (sample_no = 0; sample_no < cycles;
         sample_no = sample_no + 1) begin
        @(posedge clk);
        #1;
        show;
    end
end
endtask

task reset_game;
begin
    @(negedge clk);
    start = 0;
    k = 0;
    #2;
    reset = 1;
    #1;
    show;
    advance(2);
    @(negedge clk);
    reset = 0;
    advance(2);
end
endtask

task restart_game;
begin
    @(negedge clk);
    start = 1;
    k = 4'b1111;
    advance(1);
    advance(2);
    @(negedge clk);
    start = 0;
    k = 0;
end
endtask

task new_game;
    input integer phase_offset;
begin
    reset_game;
    advance(phase_offset);
    restart_game;
end
endtask

// Append: one clock; each displayed item: three setup clocks,
// duration+1 active clocks, and duration+1 gap clocks.
task demonstrate;
    input integer length;
    input integer detailed_audio;
    integer position;
    integer duration;
begin
    duration = COUNT_SEQ - (length - 1) * DEC_SEQ;
    advance(1);
    for (position = 0; position < length;
         position = position + 1) begin
        advance(3);
        keys_seen[position] = nl;
        if (detailed_audio) begin
            trace(duration + 1);
        end else begin
            advance(duration);
            advance(1);
        end
        advance(1);
        advance(duration);
        #1;
    end
    advance(2);
end
endtask

// Two acceptance/LED clocks, then active and gap intervals.
// Leave the button held until subsequent stimulus changes it.
task reply;
    input [3:0] buttons;
    input integer length;
    input integer detailed_audio;
    integer duration;
begin
    duration = COUNT_SEQ - (length - 1) * DEC_SEQ;
    @(negedge clk);
    k = buttons;
    advance(1);
    advance(1);
    if (detailed_audio) begin
        trace(duration + 1);
    end else begin
        advance(duration);
        advance(1);
    end
    advance(1);
    advance(duration);
end
endtask

task play_round;
    input integer length;
    integer position;
begin
    demonstrate(length, 0);
    for (position = 0; position < length;
         position = position + 1) begin
        reply(keys_seen[position], length, 0);
        if (position + 1 < length)
            advance(2);
        #1;
    end
end
endtask

initial begin
    reset = 1;
    start = 0;
    k = 0;
    driven_keys = 0;
    case_id = 1;

    // Initial reset, reset/start priority, and dormant operation.
    #100;
    show;
    @(negedge clk);
    start = 1;
    k = 4'b1111;
    advance(2);
    @(negedge clk);
    reset = 0;
    start = 0;
    k = 0;
    advance(6);

    // Cases 10-37: all colors, individual keys, and priority masks.
    for (phase = 0; phase < 4; phase = phase + 1) begin
        for (key_mode = 0; key_mode < 7;
             key_mode = key_mode + 1) begin
            case_id = 10 + phase * 7 + key_mode;
            new_game(phase);
            k = 4'b1111;
            demonstrate(1, 1);
            case (key_mode)
                0: driven_keys = 4'b0001;
                1: driven_keys = 4'b0010;
                2: driven_keys = 4'b0100;
                3: driven_keys = 4'b1000;
                4: driven_keys = 4'b1111;
                5: driven_keys = 4'b1110;
                6: driven_keys = 4'b1100;
            endcase
            reply(driven_keys, 1, 1);
            k = 0;
            advance(3 + 2 * (COUNT_SEQ + 1));
            trace(4 * (COUNT_FIN + 1));
            #1;
        end
        #1;
    end

    // Cases 40-42: last accepted cycle, timeout edge, and late input.
    for (boundary = 0; boundary < 3; boundary = boundary + 1) begin
        case_id = 40 + boundary;
        new_game(0);
        demonstrate(1, 0);
        advance(COUNT_KEY - 1 + boundary);
        @(negedge clk);
        k = keys_seen[0];
        trace(2);
        @(negedge clk);
        k = 0;
        advance(3 + 2 * (COUNT_SEQ + 1));
        trace(4 * (COUNT_FIN + 1));
        #1;
    end

    // Cases 50-51: wrong key or timeout at position three.
    for (fault_mode = 0; fault_mode < 2;
         fault_mode = fault_mode + 1) begin
        case_id = 50 + fault_mode;
        new_game(fault_mode);
        for (round_no = 1; round_no <= 2;
             round_no = round_no + 1) begin
            play_round(round_no);
            #1;
        end
        demonstrate(3, 0);
        for (item = 0; item < 2; item = item + 1) begin
            reply(keys_seen[item], 3, 0);
            advance(2);
            #1;
        end
        k = 0;
        if (fault_mode == 0)
            reply({keys_seen[2][2:0], keys_seen[2][3]}, 3, 1);
        else
            advance(COUNT_KEY + 1);
        k = 0;
        advance(3 * (3 + 2 * (COUNT_SEQ - 2 * DEC_SEQ + 1)));
        trace(4 * (COUNT_FIN + 1));
        if (fault_mode == 0) begin
            restart_game;
            demonstrate(1, 0);
        end else begin
            reset_game;
        end
        #1;
    end

    // Retain cases 60-67 and extend the same interruption sweep.
    //
    // Added cases 100-135 target setup, feedback-gap, and loss
    // phases using fixed timing only. State names in comments
    // describe the intended interruption points; there are no
    // hierarchical accesses or DUT-state-dependent waits.
    //
    // After new_game releases start, elapsed rising edges are:
    //   0: G2
    //   1: G3
    //   2: G4
    //   3: G5
    //   4: G6
    //   COUNT_SEQ+5:   G7
    //   2*COUNT_SEQ+6: G8
    //   2*COUNT_SEQ+7: G9
    //
    // demonstrate(1,0) returns at the beginning of G10.
    for (action = 0; action < 2; action = action + 1) begin
        for (stage = 0; stage < 22; stage = stage + 1) begin
            if (stage < 4)
                case_id = 60 + action * 4 + stage;
            else
                case_id = 100 + action * 18 + (stage - 4);

            new_game(stage);

            case (stage)
                // Original four interruption cases, unchanged.
                0: begin
                    advance(4);
                    trace(8);
                end

                1: begin
                    demonstrate(1, 0);
                    advance(COUNT_KEY / 2);
                end

                2: begin
                    demonstrate(1, 0);
                    @(negedge clk);
                    k = keys_seen[0];
                    trace(8);
                end

                3: begin
                    demonstrate(1, 0);
                    @(negedge clk);
                    k = {keys_seen[0][2:0], keys_seen[0][3]};
                    trace(8);
                end

                // G2: keep initialization asserted for one clock.
                // This leaves G2 stable until reset_game or
                // restart_game drives at the next falling edge.
                4: begin
                    start = 1;
                    advance(1);
                end

                // One-clock append/read setup phases:
                // stage 5 -> G3, stage 6 -> G4, stage 7 -> G5.
                5, 6, 7: begin
                    advance(stage - 4);
                end

                // Beginning of the demonstration gap: G7.
                8: begin
                    advance(COUNT_SEQ + 5);
                end

                // Player address setup and read wait: G8, G9.
                9, 10: begin
                    advance(2 * COUNT_SEQ + stage - 3);
                end

                // Correct acceptance: G10a.
                // Correct feedback gap: G12.
                11, 12: begin
                    demonstrate(1, 0);
                    @(negedge clk);
                    k = keys_seen[0];
                    advance(1);
                    if (stage == 12)
                        advance(COUNT_SEQ + 2);
                end

                // Wrong acceptance: Ea.
                // Error feedback gap: E1.
                13, 14: begin
                    demonstrate(1, 0);
                    @(negedge clk);
                    k = {keys_seen[0][2:0], keys_seen[0][3]};
                    advance(1);
                    if (stage == 14)
                        advance(COUNT_SEQ + 2);
                end

                // Timeout enters K0 after COUNT_KEY+1 clocks.
                // Subsequent fixed offsets target:
                //   stage 15: K0, offset 0
                //   stage 16: K1, offset 1
                //   stage 17: K2, offset 2
                //   stage 18: K3, offset 3
                //   stage 19: K4, offset COUNT_SEQ+4
                //   stage 20: K5, offset 2*COUNT_SEQ+5
                //   stage 21: K6, offset 2*COUNT_SEQ+COUNT_FIN+6
                15, 16, 17, 18, 19, 20, 21: begin
                    demonstrate(1, 0);
                    advance(COUNT_KEY + 1);

                    if (stage <= 18)
                        advance(stage - 15);
                    else if (stage == 19)
                        advance(COUNT_SEQ + 4);
                    else if (stage == 20)
                        advance(2 * COUNT_SEQ + 5);
                    else
                        advance(2 * COUNT_SEQ + COUNT_FIN + 6);
                end
            endcase

            if (action == 0) begin
                reset_game;
            end else begin
                restart_game;
                demonstrate(1, 0);
            end
            #1;
        end
        #1;
    end

    // Cases 70-71: original complete games and W0 restart/reset.
    // Cases 72-73: additional complete games and W1 restart/reset.
    //
    // play_round(SIZE_MEM) ends on entry to W0.
    // Four complete indication phases return to W0.
    // One additional COUNT_FIN+1 interval enters W1.
    for (finish_mode = 0; finish_mode < 4;
         finish_mode = finish_mode + 1) begin
        case_id = 70 + finish_mode;
        new_game(finish_mode);
        for (round_no = 1; round_no <= SIZE_MEM;
             round_no = round_no + 1) begin
            play_round(round_no);
            #1;
        end

        trace(4 * (COUNT_FIN + 1));

        if (finish_mode >= 2)
            advance(COUNT_FIN + 1);

        if ((finish_mode % 2) == 0) begin
            restart_game;
            demonstrate(1, 1);
        end else begin
            reset_game;
        end
        #1;
    end

    $display("===========End===========");
    $finish;
end

endmodule

`timescale 1ns / 1ps
module testbench;

// Inputs
reg clk;
reg [7:0] data_in;

// Outputs
wire [7:0] result_out;

// Instantiate the Unit Under Test
sbox_replace uut (
    .data_in    (data_in),
    .result_out (result_out)
);

// Independent clock generation; the DUT is combinational and does not use clk
initial clk = 1'b0;
always #5 clk = ~clk;

initial begin
    integer i;

    data_in = 8'h00;
    #1;

    // Test all 256 S-box input entries, including boundary values
    for (i = 0; i < 256; i = i + 1) begin
        data_in = i;
        #1;
        $display("data_in = 8'h%02h, result_out = 8'h%02h",
                 data_in, result_out);
    end

    $display("===========End===========");
    $finish;
end

endmodule
